-- Sources: data/i18n/zhCN. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["item:stalker-claws"] = {n="草原捕食者的爪子",s="在莫高雷各地，人们从草原捕食者身上取得草原捕食者的爪子，用于净化仪式。牛头人萨满祭司将它们缚入图腾，用来净化受污染的水井。",h="在莫高雷各地，人们从草原捕食者身上取得草原捕食者的爪子，用于净化仪式。牛头人萨满祭司将它们缚入图腾，用来净化受污染的水井。",kw={"净化图腾","莫高雷","穆尔·雷角","草原捕食者","草原捕食者的爪子","雷角之井净化图腾","水井"},ang={["class:Shaman"]="身为萨满祭司，你将平原上野生掠食者凶猛而纯净的力量缚入净化图腾。它们的爪子是赋予图腾力量的关键。",["race:Tauren"]="身为牛头人，收集这些爪子能帮助你的部族恢复神圣水源，清除那些肆意闯入的工业开采者留下的毒害。"},sec={{t="平原上的掠食者",b="草原捕食者在莫高雷的草原上四处猎食。它们行踪隐秘，出击精准致命，是危险的掠食者，却也维系着大地母亲安排下不可或缺的平衡。穆尔·雷角需要它们的爪子，帮助这片凋敝的土地恢复生机。他无意伤害这些野兽；它们狩猎时蕴含的自然之力，拥有对抗人为污染所需的灵性力量。"},{t="净化水井",b="地精在卡利姆多中部各地钻探采矿，使化学毒物渗入地下水，污染了滋养牛头人祖传水井的水源。雷角水井已被污秽的淤泥污染。部族的萨满祭司将草原捕食者的爪子和平原狮的爪子缚入雷角之井净化图腾，借这件传导灵性力量的器物，清除大地泉水中违背自然的污泥。"}},faq={{q="草原捕食者的爪子从何而来？",a="草原捕食者游荡在莫高雷长满青草的丘陵间，尤其常见于血蹄村的东边和西边。人们通过猎杀它们来收集爪子。",al={"草原捕食者的爪子在哪找","谁掉落草原捕食者的爪子","草原捕食者的爪子来源"}},{q="穆尔·雷角为什么需要这些爪子？",a="穆尔·雷角需要这些爪子和平原狮的爪子，制作雷角之井净化图腾。这些本土猎食者的纯净与力量，有助于净化中毒的水井。",al={"为什么收集草原捕食者的爪子","穆尔·雷角的目的","草原捕食者的爪子用途"}},{q="雷角水井为什么受到污染？",a="地精在莫高雷的作业造成了违背自然的工业污染。他们的活动破坏了自然平衡，也毒害了当地的地下水。",al={"谁污染了水井","雷角水井为什么受到污染","雷角水井污染"}},{q="收集完爪子之后要做什么？",a="收集完爪子后，穆尔会将它们雕刻成净化图腾。随后，必须将图腾直接带到雷角水井，清除其中残留的污染。",al={"接下来会发生什么","收集爪子后的下一步","净化图腾仪式"}}},fp="13,148,23.364.0,19.338.0,33.136.0,43.173.0,42.141.0,42.152.0"}
P.entries["item:steelgrill-s-tools"] = {n="贝尔丁的工具",s="在钢架补给站，贝尔丁·钢架需要新工具来维持工坊运转。他使用攻城坦克和设备时毫不爱惜，所以卡拉诺斯一直在送来替换用的工具。",h="在钢架补给站，贝尔丁·钢架需要新工具来维持工坊运转。他使用攻城坦克和设备时毫不爱惜，所以卡拉诺斯一直在送来替换用的工具。",kw={"贝尔丁","补给站","卡拉诺斯","棘齿城","攻城坦克","扳手","钢架","工具"},ang={["profession:Engineering"]="作为一名工程师，你知道维修重型攻城坦克会如何磨损弧光扳手和精巧的扳手。",["race:Dwarf"]="作为一名矮人，你懂得维护联盟装甲攻城坦克的自豪。为贝尔丁提供充足的物资，有助于让铁炉堡的装甲先锋随时准备投入战斗。"},sec={{t="手重的工匠",b="贝尔丁·钢架是丹莫罗最出色的攻城坦克技师之一。不过，商人们都知道他下手很重。他不停地修理装甲坦克和机械装置，精巧的工具在他手里很快就会损坏。弧光扳手会折断，尖齿棘轮会磨损，所以他不断从卡拉诺斯订购替换工具，补充到维修台上。"},{t="让战车继续前进",b="在卡拉诺斯东北方的补给站里，贝尔丁为驾驶员迪恩·石轮这样的老练驾驶员维修战车。这些工具让铁炉堡的战争机器保持运转。新扳手和棘轮让那里组装的攻城坦克得以及时维修，为当地防御提供支持。"}},faq={{q="贝尔丁的工具有什么用途？",a="这些工具用来替换钢架补给站里磨损的机修工具。贝尔丁·钢架用它们检修矮人的重型机械，其中就包括驾驶员迪恩·石轮受损的攻城坦克。",al={"这些工具是什么","贝尔丁的工具用途"}},{q="贝尔丁·钢架为什么会用坏这么多工具？",a="贝尔丁干活粗手粗脚，使用工具也毫不爱惜。弧光扳手和尖齿棘轮频频断裂，卡拉诺斯的供应商几乎跟不上他的需求。",al={"工具为什么损坏","贝尔丁为什么需要工具"}},{q="这箱工具是从哪里来的？",a="工具箱在附近的卡拉诺斯组装并装满工具，随后被运往东北方的钢架补给站。",al={"哪里能拿到工具","工具货物来源"}},{q="贝尔丁·钢架是谁？",a="贝尔丁是一位矮人机械大师，经营着卡拉诺斯东北方的钢架补给站。他被认为是这一带最出色的攻城坦克技师。",al={"贝尔丁是谁","贝尔丁·钢架的故事"}}},fx={["8eb066d8"]={q="贝尔丁的工具是什么？",a="贝尔丁的工具是一批刚刚打包好的重型机械设备，包括弧光扳手和尖牙棘轮。它已准备妥当，将直接送交贝尔丁·钢架，他是在卡拉诺斯附近的钢架补给站工作的攻城器械技术大师。",al={"贝尔丁的工具是什么","贝尔丁的工具箱"}},["11454cb4"]={q="贝尔丁·钢架为什么需要这箱工具？",a="贝尔丁是位机械专家，但他维修重型机械时，总把工具用到断裂为止。他刚刚折断了最后一把尖牙棘轮，急需这批新工具，好完成驾驶员迪恩·石轮等人的攻城器械所需的关键维修。",al={"贝尔丁为什么要工具","为什么需要贝尔丁的工具","为什么要工具"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="钢齿土狼的肋骨",s="在千针石林，钢齿土狼的肋骨标志着一头可怕土狼的统治走向终结。雷霆崖的梅洛·石蹄要求将这根骨头带到猎人高地，作为钢齿土狼已被击杀的证明。",h="在千针石林，钢齿土狼的肋骨标志着一头可怕土狼的统治走向终结。雷霆崖的梅洛·石蹄要求将这根骨头带到猎人高地，作为钢齿土狼已被击杀的证明。",kw={"伊索克营地","猎人高地","土狼","梅洛·石蹄","钢齿土狼","钢齿土狼的肋骨","千针石林","雷霆崖"},ang={["class:Hunter"]="身为猎人，追踪钢齿土狼能让你与危险的兽群首领较量，考验自己的技艺，也能帮助除去威胁荒野平衡的祸患。",["race:Tauren"]="身为牛头人，带回钢齿土狼的肋骨，便是清除玷污神圣平衡的残暴生物，履行你对Earthmother的职责。"},sec={{t="祝福之外的狩猎",b="牛头人狩猎往往是为了获取食物、赢得荣耀，或是寻求与自然的和谐。钢齿土狼却不同。这头土狼首领游荡在千针石林伊索克营地以南的峡谷底部，恐吓温顺的野生动物，并纠集较弱的掠食者四处杀戮。猎人高地的狩猎大师梅洛·石蹄决定除掉钢齿土狼。他要求带回这头土狼的肋骨，以此证明暴君已死，峡谷中的祸害已被清除。"}},faq={{q="钢齿土狼的肋骨有什么用？",a="将肋骨带给雷霆崖猎人高地的梅洛·石蹄。它能证明钢齿土狼已被击败。",al={"钢齿土狼的肋骨任务","谁要钢齿土狼的肋骨","钢齿土狼的肋骨用途"}},{q="在哪里能找到钢齿土狼，取得肋骨？",a="钢齿土狼游荡在千针石林西北部、伊索克营地以南的峡谷底部。忠诚的同伴常常护卫在它两侧。",al={"钢齿土狼位置","钢齿土狼在哪里","寻找钢齿土狼"}},{q="梅洛·石蹄为什么要杀死钢齿土狼？",a="梅洛认为钢齿土狼是一个违背自然、不受大地母亲祝福的暴君。这头土狼在温顺的野兽间散播杀戮与恐惧，与那些为了生存而狩猎的掠食者不同。",al={"为什么杀死钢齿土狼","梅洛·石蹄的动机","钢齿土狼背景故事"}},{q="梅洛·石蹄是谁？",a="梅洛·石蹄是一位经验丰富的牛头人猎手，身在雷霆崖的猎人高地。他派遣有志磨炼追踪本领的猎手，追猎卡利姆多各地的危险野兽。",al={"梅洛是谁","梅洛·石蹄位置","猎人高地梅洛"}}},fp="15,181,27.428.0,33.118.0,42.121.0,47.180.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="被偷走的银币",s="十字路口哨塔中存放部落银币的保险箱失踪了。赤鳞迅猛龙将银币带到了棘齿城以南的迅猛龙巢穴。",h="十字路口哨塔中存放部落银币的保险箱失踪了。赤鳞迅猛龙将银币带到了棘齿城以南的迅猛龙巢穴。",kw={"贫瘠之地军饷","十字路口","加兹罗格","迅猛龙巢穴","银币锁箱","被偷走的银币","日鳞迅猛龙"},ang={["faction:Horde"]="十字路口是部落在贫瘠之地的核心据点。追回军饷，才能让当地的步兵有饭吃、有饷领，随时准备坚守防线，抵御半人马和联盟的入侵。"},sec={{t="野兽窃案",b="赤鳞迅猛龙从十字路口的哨塔里搬走了一只装着银币的保险箱。这些银币原本是驻军卫兵的军饷。迅猛龙把锁箱拖到了棘齿城以南的迅猛龙巢穴，那里是它们共同筑巢的地方。加兹罗格和其他监工都无法解释，这些掠食者为什么要偷走它。这起窃案让他们不禁怀疑，迅猛龙究竟是喜欢闪亮的东西，还是有着超乎寻常野兽的狡黠。"}},faq={{q="被偷走的银币是什么？",a="被偷走的银币装在一只沉重的锁箱里，原本是发给十字路口卫兵的军饷。迅猛龙从哨塔里偷走了箱子，把它带回了筑巢的地方。",al={"被偷走的银币是什么","银币是什么"}},{q="迅猛龙为什么要偷走一箱银币？",a="就连加兹罗格也无法解释，迅猛龙为什么要偷走锁箱。它们也许是被闪亮的金属吸引，也许是凭着异乎寻常的狡黠，把箱子带进了巢穴深处。",al={"迅猛龙为什么想要银币","迅猛龙的智力","为什么是银币"}},{q="银币被带到哪里去了？",a="迅猛龙把锁箱带到了迅猛龙巢穴，那是贫瘠之地东部、棘齿城以南一处遍布巢穴的崎岖峡谷。",al={"被偷走的银币位置","银币在哪里"}},{q="谁在寻找被偷走的银币？",a="驻守十字路口的兽人加兹罗格正在寻找这只箱子。这些银币是前哨站疲于应战的守军整整一个月的军饷。",al={"谁想要银币","谁交还被偷走的银币"}}},fp="13,157,15.406.0,26.160.0,41.157.0,27.120.0,37.146.0"}
P.entries["item:stone-of-relu"] = {n="雷鲁之石",s="在湿地的一场伏击中，雷鲁之石遗失，被一只迅猛龙吞下。考古学家弗拉冈特相信，它能揭开古老化石中的秘密。",h="在湿地的一场伏击中，雷鲁之石遗失，被一只迅猛龙吞下。考古学家弗拉冈特相信，它能揭开古老化石中的秘密。",kw={"考古学家弗拉冈特","探险者协会","化石","斑驳的迅猛龙","勘察员维尔加","雷鲁之石","湿地"},ang={["faction:Alliance"]="米奈希尔港的联盟探险队需要依靠雷鲁之石这样的出土文物，来证明在危机四伏的沼泽各处艰难挖掘是值得的。",["race:Dwarf"]="对探险者协会而言，雷鲁之石有助于拼凑出远古生命的起源，以及世人遗忘的世界遗产。"},sec={{t="解读古代遗物的钥匙",b="探险者协会在考察中发现了雷鲁之石。考古学家弗拉冈特相信，它能解读从卡利姆多和东部王国收集来的史前化石。他打算用它研究自己在湿地收集的标本，以及勘察员雷姆塔维尔在黑海岸挖掘出的化石。"},{t="遗失于沼泽",b="考古学家弗拉冈特沿着湿地的道路前去会见勘察员维尔加时，遭到了斑驳的迅猛龙伏击。混乱中，这件遗物掉落，被其中一只野兽吞下。如今，探险者协会正在寻找沼泽中的迅猛龙，以便剖开它们的喉咙，取出这块古老的石头。"}},faq={{q="雷鲁之石是什么？",a="雷鲁之石是考古学家弗拉冈特正在寻找的一件古代神器。他相信，它能揭开史前化石中隐藏的奥秘，并释放其中的力量。",al={"雷鲁之石","这块石头是什么","雷鲁神器"}},{q="这块石头怎么会进了迅猛龙的肚子？",a="考古学家弗拉冈特带着这件遗物，沿湿地的一条道路前去会见勘察员维尔加，途中遭到了斑驳的迅猛龙袭击。混乱中，一只野兽吞下了掉落的石头。",al={"迅猛龙为什么有它","谁弄丢了石头","石头如何遗失"}},{q="弗拉冈特打算用这块石头做什么？",a="弗拉冈特打算将这块石头用于他寻回的化石，以及勘察员雷姆塔维尔在黑海岸发现的化石，以解读并释放其中潜藏的魔法奥秘。",al={"弗拉冈特想要什么","雷鲁之石的用途"}}},fp="13,142,23.275.0,19.285.0,26.146.0,41.160.0,48.179.0"}
P.entries["item:stonetalon-sap"] = {n="石爪苔液",s="暗色湖和石爪峰附近的树液兽身上带有金吉尔寻找的树液。这位暗矛巫医用它调制药剂，给关在笼中的暗夜精灵囚犯使用。",h="暗色湖和石爪峰附近的树液兽身上带有金吉尔寻找的树液。这位暗矛巫医用它调制药剂，给关在笼中的暗夜精灵囚犯使用。",kw={"金吉尔","玛拉卡金","暗色湖","树液兽","石爪峰","石爪苔液"},ang={["race:NightElf"]="一名部落巫医用石爪山的本土物质毒害关在笼中的暗夜精灵囚犯，这是对自然和Elune的亵渎。",["race:Troll"]="巫医金吉尔展示了暗矛如何将敌人钟爱的周遭环境化作巫毒武器。"},sec={{t="苦涩的收获",b="暗色湖和石爪峰附近的树液兽身上带有一种效力强大的林地汁液。玛拉卡金的金吉尔寻找这种树液，用来调制一种他称为森林魔法的药剂。他打算将药剂用在关在笼中的暗夜精灵囚犯身上，让他们珍爱的荒野精华反过来伤害他们。"}},faq={{q="哪些生物身上带有石爪苔液？",a="暗色湖附近以及通往石爪峰的山坡上的树液兽身上带有石爪苔液。",al={"石爪苔液哪里获取","石爪苔液谁掉落","树液兽"}},{q="巫医金吉尔用树液做什么？",a="金吉尔将树液与奔跑者的眼睛、暮光之须和灵龙的鳞片混合，调制毒性药剂，给关在笼中的暗夜精灵囚犯使用。",al={"金吉尔为何需要树液","金吉尔森林魔法配方"}},{q="哪里最容易找到树液兽？",a="树液兽生活在暗色湖周围的树林中，以及通往石爪峰的小径沿途。",al={"树液兽位置","暗色湖树液兽"}},{q="树液本身具有魔力吗？",a="树液蕴含着石爪山高地的生命力，但金吉尔需要巨魔魔精和特定材料，才能让它具有致命的毒性。",al={"石爪苔液有魔力吗","石爪苔液的特性"}}},fx={b24da591={q="什么是石爪苔液？",a="石爪苔液是一种黏稠的天然树脂，采自石爪山脉中游荡的树液兽，尤其是暗色湖和石爪峰附近的树液兽。它质地浓稠，蕴含着原始的自然精华，是调制药剂和巫毒酿剂的理想材料，能借助当地荒野的奇特魔力。",al={"什么是石爪苔液","石爪苔液物品","关于石爪苔液"}},["7615d27b"]={q="石爪苔液来自哪里？",a="这种琥珀色的树液直接采自石爪山脉森林和湖岸间游荡的活体树液兽。它并非由凡人匠人制造或蒸馏而成，而是由这些古怪的原始植物生物自然分泌的。",al={"石爪苔液的来源","哪里能获得树液"}}},fp="14,172,16.241.1,36.94.0,47.141.1,43.96.0,30.123.0"}
P.entries["item:stormpike-banner"] = {n="雷矛军旗",s="联盟新兵进入冰翼洞穴，夺取雷矛军旗。这场试炼位于奥特兰克山谷的丹巴达尔西南方，鹰身人在那里守卫着军旗。",h="联盟新兵进入冰翼洞穴，夺取雷矛军旗。这场试炼位于奥特兰克山谷的丹巴达尔西南方，鹰身人在那里守卫着军旗。",kw={"奥特兰克山谷","丹巴达尔","哈格丁","冰翼洞穴","徽记","实验场","雷矛军旗"},ang={["faction:Alliance"]="身为联盟新兵，带回军旗就能加入雷矛卫队，并获得佩戴其战斗徽记、对抗霜狼氏族的资格。",["race:Dwarf"]="身为矮人，你将这面军旗视为铁炉堡主权的象征，也视为雷矛氏族在山谷各处发掘先祖遗物这一使命的象征。"},sec={{t="入伍试炼",b="哈格丁中尉派遣联盟新兵进入丹巴达尔西南方的冰翼洞穴。在迎战霜狼兽人之前，新兵必须勇闯鹰身人的巢穴，夺取雷矛军旗，并活着将它带回。归来的新兵将获得雷矛卫队新兵的军衔和徽记。"}},faq={{q="雷矛军旗在哪里？",a="雷矛军旗位于奥特兰克山谷的丹巴达尔西南方，就在冰翼洞穴深处。",al={"军旗位置","雷矛军旗在哪","如何找到军旗"}},{q="新兵为什么必须取回军旗？",a="哈格丁中尉要求联盟新兵在奔赴战线之前证明自己的勇气。带回军旗便能获得他们的第一枚雷矛徽记。",al={"实验场试炼","为什么取军旗","哈格丁任务"}},{q="洞穴里有哪些威胁守卫着军旗？",a="当地凶猛的鹰身人守卫着冰翼洞穴，攻击前来寻找军旗的闯入者。",al={"军旗附近的怪物","冰翼洞穴敌人"}},{q="找到军旗后，该把它交给谁？",a="将军旗交还给哈格丁中尉，他是驻守在奥特兰克山脉洞穴入口外的联盟军官。",al={"交还军旗","上交军旗"}}},fx={["27f01085"]={q="什么是雷矛军旗？",a="雷矛军旗是代表雷矛卫队的军旗。雷矛卫队是一支正在奥特兰克山谷征战的矮人远征军。军旗插在丹巴达尔西南方危机四伏、遍布 鹰身人 的冰翼洞穴深处，作为考验的标记。新兵必须深入冰封的洞穴，勇敢面对潜伏其中的凶兽，并取回军旗，以证明自己的勇气和佩戴雷矛徽记的资格。",al={"什么是雷矛军旗","雷矛军旗的背景","关于雷矛军旗"}}},fp="16,139,19.286.0,38.96.0,44.167.0,46.90.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="卡尔·雷矛的订单",s="巡山人卡尔·雷矛从洛克莫丹向弗伦·长须发去委托，请他打造一面精良的矮人盾牌。",h="巡山人卡尔·雷矛从洛克莫丹向弗伦·长须发去委托，请他打造一面精良的矮人盾牌。",kw={"铁匠","丹莫罗","矮人区","弗伦·长须","委托","盾牌","雷矛","暴风城"},ang={["profession:Blacksmithing"]="雷矛的委托表明了护甲大师的地位。各个王国的主顾都在寻求技艺精湛的矮人铁匠。",["race:Dwarf"]="身为矮人，你与守卫卡兹莫丹的巡山人，以及远居人类城市的工匠，都有着氏族和技艺的纽带。"},sec={{t="北方的委托",b="巡山人卡尔·雷矛在洛克莫丹守望，矮人的边境危机四伏。他需要一面坚固的盾牌，不放心将这样的活计交给寻常铁匠。弗伦·长须是一位护甲匠，他十分钦佩这位匠人的手艺。弗伦离开了铁炉堡，如今住在暴风城的矮人区，与人类为邻。雷矛猜想，是一笔巨额报酬吸引他去了南方，于是便托旅人将自己的委托送往另一个王国。"},{t="雷矛家族",b="弗伦·长须在暴风城的矮人区收到了雷矛的信，答应打造这面盾牌。雷矛氏族历史悠久，满怀自豪，以尚武的坚韧和财富闻名于卡兹莫丹。他很欢迎来自北方故乡的消息和生意。于是，弗伦开始着手完成这位巡山人的订单。"}},faq={{q="卡尔·雷矛的订单是什么？",a="巡山人卡尔·雷矛从洛克莫丹发来委托，请弗伦·长须为他锻造一面精良的盾牌。",al={"这封信是什么","雷矛订单物品","卡尔·雷矛的订单"}},{q="这封信是谁写的？",a="这封信是巡山人卡尔·雷矛写的。他是一名守卫洛克莫丹各处隘口的矮人哨兵，十分钦佩弗伦·长须的锻造技艺。",al={"卡尔·雷矛的订单是谁寄的","谁写的","巡山人卡尔·雷矛"}},{q="这封信要送到哪里？",a="这封信要送给弗伦·长须，他的锻炉位于暴风城的矮人区。",al={"卡尔·雷矛的订单送到哪里","这封信交给谁","递送卡尔·雷矛的订单"}},{q="雷矛为什么要雇用远在暴风城的铁匠？",a="雷矛认为弗伦的技艺无人能及，不愿让其他护甲匠代劳。弗伦离开了铁炉堡，前往南方，在人类之中谋生。",al={"为什么找弗伦","为什么不在铁炉堡锻造","为什么送到暴风城"}}},fx={["181a24c8"]={q="弗伦·长须为什么想要卡尔·雷矛的订单？",a="这份书面订单委托制作一面精工打造的矮人盾牌。住在暴风城矮人区的护甲匠弗伦·长须，很看重声名显赫的雷矛氏族带来的生意。他知道，这个家族不仅自豪而且在整个卡兹莫丹备受尊敬，也有足够的财富为出色的手艺支付丰厚报酬。",al={"弗伦为什么要这个","为什么需要卡尔·雷矛的订单","卡尔·雷矛的订单为何需要"}}},fp="19,100,21.422.0,18.312.0,28.87.0,22.131.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="暴风城护甲标记",s="在东谷伐木场，萨拉·迪博雷恩接受为王国效力者交来的暴风城护甲标记。凭此标记，他们可以向受暴风城委托的工匠领取制作的装备。",h="在东谷伐木场，萨拉·迪博雷恩接受为王国效力者交来的暴风城护甲标记。凭此标记，他们可以向受暴风城委托的工匠领取制作的装备。",kw={"护甲标记","布甲和皮甲","东谷伐木场","艾尔文森林","军需申领","萨拉·迪博雷恩","暴风城护甲标记"},ang={["faction:Alliance"]="身为联盟的一员，你可以看到东谷伐木场如何将边境定居点与暴风城的军事指挥机构联系起来。"},sec={{t="军需申领",b="暴风城的指挥官会向为王国效力的人发放护甲标记。维持艾尔文森林各地的秩序，让暴风城的资源捉襟见肘。因此，指挥官有时会在军事哨站用这些官方凭据代替制式装备。标记证明持有者曾为王国效力，并让签约的当地工匠为其提供量身定制的护甲。"},{t="东谷补给",b="萨拉·迪博雷恩和其他工匠受暴风城军队委托，在东谷伐木场工作。营地位于艾尔文的东部边境，他们在那里利用当地材料制作防护用的布衣和皮衣。在那里出示标记，就能领取合身的护甲，用于守卫周围的林地。"}},faq={{q="暴风城护甲标记有什么用途？",a="暴风城护甲标记是发给协助暴风城卫兵者的官方军用凭证。它能证明你的功绩，让你向与军队签约的工匠领取防护护甲。",al={"护甲标记是什么","标记用途","暴风城标记用法"}},{q="谁接受这种标记？",a="萨拉·迪博雷恩在东谷伐木场接受这种标记，营地就在艾尔文森林向东过河的地方。她与暴风城军队签有契约，提供量身定制的布甲和皮甲装备。",al={"谁收标记","标记交到哪里","萨拉·迪博雷恩标记"}},{q="暴风城为什么使用标记，而不直接发放护甲？",a="暴风城使用标记，是因为外围岗哨可能缺乏仓储空间、锻造设施或裁缝设施，无法就地为新兵配发装备。战地指挥官可以派新兵去找萨拉·迪博雷恩这样的当地工匠，他们拥有专门的作坊。",al={"为何用代币代替护甲","为何使用军用标记","艾尔文军用凭证"}},{q="凭标记可以领取什么装备？",a="标记持有者可以选择一件由签约军需供应商按需新制的布甲或皮甲。",al={"能获得什么护甲","标记奖励","布甲或皮甲"}}},fx={e5398b12={q="暴风城护甲标记是什么？",a="这是代表暴风城军队签发的正式军用凭证。当地指挥官无需将笨重的成套护具运过艾尔文森林，而是发放这种标记作为军需配给的凭据，持有人可向获授权的护甲匠领取新制的布甲或皮甲。",al={"暴风城护甲标记是什么","护甲标记","标记是什么"}},["3e7f2980"]={q="暴风城护甲标记来自哪里，由谁制作？",a="卫兵托马斯在艾尔文东侧桥边的岗哨，代表暴风城军队向展现出机敏与英勇的守卫者发放这种标记。它承载着王国军队的权威，授权当地工匠为新兵提供装备，费用由王室承担。",al={"谁制作了护甲标记","标记来自哪里","谁发放护甲标记"}},["618263b5"]={q="萨拉·迪博雷恩为什么想要暴风城护甲标记？",a="萨拉·迪博雷恩受暴风城军队委托，为新兵和志愿者提供布甲与皮甲。交出亲手制作的装备前，她需要这种标记作为正式授权凭证，以确保王国的物资只交给得到认可的守卫者。",al={"萨拉为什么要标记","为什么把标记送到东谷","为什么需要护甲标记"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="斯托曼的回信",s="格里安·斯托曼从哨兵岭向湖畔镇传话，表示无法抽调士兵支援赤脊山。",h="格里安·斯托曼从哨兵岭向湖畔镇传话，表示无法抽调士兵支援赤脊山。",kw={"格里安","湖畔镇","信件","所罗门镇长","前往西部荒野的信使","人民军","赤脊山","所罗门","斯托曼","西部荒野"},ang={["faction:Alliance"]="对联盟而言，这封信表明，偏远的聚居地正彼此求援，而首都却按兵不动。",["race:Human"]="身为人类守卫，你看到西部荒野和赤脊山失去了暴风城皇家卫兵的保护，正为生存而挣扎。"},sec={{t="遭拒的求援",b="黑石兽人和豺狼人不断进逼湖畔镇，所罗门镇长向哨兵岭请求援助。格里安·斯托曼以书信作答，并为湖畔镇的损失深感悲痛。然而，西部荒野也有自己的战事。王室撤走驻军后，人民军随之成立，如今农民和志愿者正独自对抗迪菲亚潜行者。斯托曼的部队已经伤亡惨重，兵力捉襟见肘，无力再向另一片遭到遗弃的边境派出援兵。"},{t="王国的漠视",b="赤脊山和西部荒野面临着同样严峻的困境。暴风城的王廷已经抛弃了这两片土地。瓦里安·乌瑞恩国王下落不明，王国的常备军也因不明原因未能驻守各地边境。偏远城镇只能自行组织志愿守卫，否则便难逃覆灭。所罗门收到封好的回信，明白两座城镇都无力拯救对方。王国日渐分崩离析，首都却依然沉默。"}},faq={{q="斯托曼的回信写了什么？",a="格里安·斯托曼在信中写道，西部荒野正与迪菲亚潜行者进行一场残酷的战争，而且和赤脊山一样，已经失去了暴风城军队的保护。他哀悼阵亡的守卫，却拒绝了所罗门镇长的增援请求。",al={"信中写了什么","斯托曼信件内容","给所罗门的回信原文"}},{q="所罗门最初为什么向西部荒野求援？",a="湖畔镇正遭受豺狼人和黑石兽人的猛烈进攻。所罗门镇长向暴风城的马库斯·乔纳森将军求援，却没有等来援军，于是转而向艾尔文另一边的人民军求助，希望同为边境守卫的他们能伸出援手。",al={"为何向西部荒野求援","所罗门向斯托曼求援","湖畔镇为何向民兵求援"}},{q="人民军为什么抽不出兵力？",a="人民军是一支志愿军，正艰难抵御迪菲亚潜行者，守住哨兵岭及周围的平原。伤亡与日俱增，又没有正规军支援，若派战士前往湖畔镇，西部荒野就会失去防守。",al={"民兵为何不援助","西部荒野能否援助赤脊山","为何拒绝所罗门"}},{q="暴风城军队为什么没有保护这些城镇？",a="两座城镇都无人知晓暴风城军队为何缺席。斯托曼在信中写道，暴风城撤走了部队，让西部荒野毫无防备，而所罗门则不明白，究竟有什么事能让军队离开自己的人民。两地都只能依靠当地的志愿者。",al={"暴风城军队在哪里","暴风城为何不援助","暴风城弃守"}}},fx={["399f6159"]={q="斯托曼的回信是什么？",a="这是哨兵岭人民军指挥官格里安·斯托曼写给赤脊山的所罗门镇长的一份正式书面公函。信中带来了严峻的消息：西部荒野正深陷与迪菲亚潜行者的殊死战斗，无法派出任何士兵或调拨资源援助湖畔镇。",al={"斯托曼的回信是什么","斯托曼给所罗门的信","格里安给湖畔镇的答复"}},["945d8c3a"]={q="斯托曼的回信来自哪里，由谁写成？",a="这封信是格里安·斯托曼在西部荒野的哨兵岭亲笔写下的。读过所罗门镇长请求增援的信后，斯托曼拟好了回信，托你穿越王国，将它送回赤脊山。",al={"谁写了斯托曼的回信","谁写了给所罗门的斯托曼的回信","斯托曼的回信来自哪里"}},c46920a1={q="为什么有人想要斯托曼的回信？",a="所罗门镇长正在湖畔镇等待这封回信，希望获得军事援助，抵御威胁赤脊山的黑石兽人入侵。他需要斯托曼的答复，才能知道人民军是否能驰援湖畔镇，还是这座镇子必须独自面对危机。",al={"谁要斯托曼的回信","为什么送斯托曼的信","为什么把回信交给所罗门"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="怪味粉末",s="在洛克莫丹，怪味粉末让调查破坏事件的工程师们深感不安。总工程师辛德维尔七世担心它可能是炸药，希望请专家鉴定。",h="在洛克莫丹，怪味粉末让调查破坏事件的工程师们深感不安。总工程师辛德维尔七世担心它可能是炸药，希望请专家鉴定。",kw={"水坝危机","阿什兰·暗石","丹莫德","辛德维尔七世","洛克莫丹","怪味粉末","萨多尔大桥"},ang={["profession:Engineering"]="身为工程师，你或许能辨认出不稳定爆破混合物散发的硫磺气味，这与联盟采矿哨站使用的标准配方不同。",["race:Dwarf"]="身为矮人，你深知保护洛克莫丹的石造设施和蓄水池至关重要。敌方炸药的任何迹象，对氏族而言都是迫在眉睫的危机。"},sec={{t="易爆的发现",b="在洛克莫丹的基础设施遭到蓄意破坏的现场，人们发现了怪味粉末。总工程师辛德维尔七世担心，这可能是一种特制炸药，与采矿时通常使用的火药不同。他无法辨明它的成分或来源，也不愿亲自动手摆弄它。哪怕一点火星，都可能酿成灾难。"},{t="北上之路",b="总工程师辛德维尔七世派人带着样本穿过奥加兹大门，前往湿地接受检验。阿什兰·暗石是一位经验丰富的爆破专家，随军团驻扎在萨多尔大桥附近的丹莫德，他将检查这些粉末颗粒，查明破坏者正在筹备什么样的爆炸。"}},faq={{q="怪味粉末是什么？",a="怪味粉末是在调查洛克莫丹当地的破坏事件时发现的可疑化学残留物。它的浓烈气味和成分让矮人工程师怀疑它是炸药。",al={"怪味粉末是什么","这是什么粉末","粉末 洛克莫丹"}},{q="总工程师辛德维尔七世为什么要检验它？",a="总工程师辛德维尔七世怀疑这种粉末是一种特制炸药。他需要一位精通大规模爆破的专家，来弄清洛克莫丹面临的威胁。",al={"为什么检验粉末","辛德维尔七世 粉末","谁需要这种粉末"}},{q="谁能鉴定这种粉末？",a="总工程师辛德维尔七世指引旅人将样本交给阿什兰·暗石，这位爆破专家随军团驻扎在萨多尔大桥附近的丹莫德。",al={"谁能鉴定粉末","粉末送到哪里","粉末专家"}},{q="为什么运送这种粉末很危险？",a="这种粉末可能极不稳定，而运送它还意味着要穿过奥加兹大门，踏上湿地泥泞且危机四伏的道路。",al={"粉末危险吗","为什么危险"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="有奇怪标记的箱子",s="在黑海岸，死去海龟驮载的货物中发现了一个有奇怪标记的箱子。箱上的符文指向娜迦，表明这些海龟并非偶然搁浅。",h="在黑海岸，死去海龟驮载的货物中发现了一个有奇怪标记的箱子。箱上的符文指向娜迦，表明这些海龟并非偶然搁浅。",kw={"奥伯丁","车厢","黑海岸","灰雾","温尼斯·布莱葛","娜迦","海龟","有奇怪标记的箱子"},ang={["class:Priest"]="身为牧师，你协助奥伯丁的月神殿学者收存海岸遗物，他们正努力保护海岸，抵御来自海洋的腐化。",["race:NightElf"]="在黑海岸发现绑在当地海龟身上的娜迦补给箱，向kaldorei发出了警告：他们那些古老而变异的同族正从无尽之海向岸上推进。"},sec={{t="深海的战利品",b="死去的海龟和其他海洋生物被冲上黑海岸的沙滩。有些龟壳上还绑着破损的挽具和车厢。残骸中散落着密封的箱子，上面刻着陌生而蜿蜒的符文。灰雾鱼人常藏身于中空的肋骨和破损的车厢中，啃食尸体，守着剩下的东西。"},{t="娜迦扩张的证据",b="温尼斯·布莱葛是奥伯丁的月神殿研究员，她认出了这些标记。这些文字和车厢属于娜迦，他们利用巨型海龟将补给和战争装备运上陆地。这些箱子表明，娜迦正在北部海岸活动，可能正驱赶坐骑向南前往灰谷。奥伯丁的祭司们将这些遗物送往达纳苏斯研究。"}},faq={{q="在哪里能找到有奇怪标记的箱子？",a="箱子位于黑海岸沿岸一只死去海龟身上绑着的废弃车厢里。灰雾鱼人常在尸体附近进食，守着剩下的东西。",al={"哪里能找到有奇怪标记的箱子","箱子位置","海龟车厢箱子"}},{q="有奇怪标记的箱子是谁制作的？",a="箱子及其铭文都出自娜迦之手。他们将车厢绑在活海龟身上，把给养、武器和装备从深海运到卡利姆多的海岸。",al={"箱子是谁制作的","箱子上的标记","箱子符文","这些标记是什么"}},{q="奥伯丁有谁想要这个箱子？",a="温尼斯·布莱葛是奥伯丁的月神殿研究员，她收集这个箱子，以研究这些奇怪的搁浅事件和娜迦的威胁。",al={"交给谁","箱子交付","谁想要箱子"}},{q="海龟为什么驮着这些箱子？",a="娜迦把巨型海龟当作驮兽，将挽具和车厢绑在它们背上，把补给和战争装备运上陆地。温尼斯怀疑，其中一只海龟是在向南行进时被杀死的，它或许正要前往灰谷。",al={"海龟为什么驮着箱子","海龟车厢","海龟为什么绑着挽具"}},{q="把箱子交给温尼斯后会怎样？",a="温尼斯·布莱葛将箱子和海岸调查结果送往达纳苏斯的月神殿，让暗夜精灵的领袖们研究娜迦势力所及的范围。",al={"箱子送到哪里","箱子送往达纳苏斯"}}},fp="20,168,20.323.0,26.395.1,40.154.0,34.171.0,32.145.0,46.218.0,52.162.0"}
P.entries["item:strigid-owl-feather"] = {n="巨翼枭的羽毛",s="巨翼枭的羽毛采自栖息在泰达希尔枝头的猫头鹰。赛恩·腐蹄为了他的秘密交易而收集这些羽毛。",h="巨翼枭的羽毛采自栖息在泰达希尔枝头的猫头鹰。赛恩·腐蹄为了他的秘密交易而收集这些羽毛。",kw={"多兰纳尔","施法材料","巨翼枭","巨翼枭的羽毛","巨翼恶枭","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="身为德鲁伊，你十分敬重泰达希尔的飞禽猎手。看到有人受骗收集它们的羽毛，用作可疑的施法材料，你可能会感到不安。",["race:NightElf"]="身为暗夜精灵，你知道泰达希尔的猫头鹰是Elune的生灵。赛恩·腐蹄对它们的利用，是对这片神圣林地的亵渎。"},sec={{t="林间羽毛与黑暗交易",b="巨翼枭和巨翼鸣枭在大地之冠中捕猎。它们的羽毛和绒羽散落在林地上。在多兰纳尔外，叛徒萨特赛恩·腐蹄派遣初出茅庐的旅人沿着幽影谷通往这里的道路，收集巨翼枭的羽毛、蜘蛛丝和夜刃豹的牙齿，供他从事见不得光的生意。"}},faq={{q="哪里能找到巨翼枭的羽毛？",a="巨翼枭和巨翼恶枭栖息在多兰纳尔周围以及泰达希尔各处的林地中，你可以在那里收集它们的羽毛。",al={"羽毛位置","巨翼枭的羽毛哪里掉落","猫头鹰羽毛采集"}},{q="谁需要巨翼枭的羽毛？",a="赛恩·腐蹄是盘踞在通往多兰纳尔的小路旁的萨特，他要你收集这些羽毛，以及树林蜘蛛丝和夜刃豹的牙齿。",al={"谁需要猫头鹰羽毛","猫头鹰羽毛交付","赛恩猫头鹰羽毛"}},{q="赛恩·腐蹄用这些羽毛做什么？",a="赛恩说，这些羽毛是他在森林中从事秘密生意所需的施法材料。他还以欺骗毫无戒心的新兵替他干脏活为乐。",al={"赛恩为什么要羽毛","赛恩施法材料用途"}}},fp="19,121,32.327.1,38.133.0,31.125.0,45.147.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="结实的龙喉胫骨",s="怒牙营地的叛离者龙喉氏族兽人提供了可用于制作护甲的坚固胫骨。在幽暗城，维罗拉·奈特雷需要用这些骨头为战士的护腿制作骨架。",h="怒牙营地的叛离者龙喉氏族兽人提供了可用于制作护甲的坚固胫骨。在幽暗城，维罗拉·奈特雷需要用这些骨头为战士的护腿制作骨架。",kw={"怒牙营地","龙喉胫骨","护腿","结实的龙喉胫骨","幽暗城","维罗拉·奈特雷","湿地"},ang={["class:Warrior"]="身为战士，你亲手检验致密的兽人骨头，收集能为定制护甲搭建骨架的材料。这展现了你的力量。",["race:Undead"]="身为亡灵，你能从维罗拉·奈特雷用敌人的骨头为黑暗女王麾下的勇士制作装备的做法中，看出被遗忘者的务实。"},sec={{t="骨头撑起的骨架",b="维罗拉·奈特雷需要能承受残暴护腿重压的骨头。湿地中部怒牙营地的叛离者龙喉氏族兽人骨架粗壮，胫骨可以用来支撑护甲。每根骨头都必须亲手检验。战士会丢弃任何一受力就折断的骨头。"}},faq={{q="这些胫骨为什么比普通胫骨更坚固？",a="龙喉氏族兽人的骨架粗壮，但骨裂会使骨头变得脆弱，无法用于制作护甲。战士会亲手弯折每根胫骨，只留下那些不易折断的。",al={"胫骨为何坚固","龙喉氏族骨头强度","检验胫骨"}},{q="谁需要结实的龙喉胫骨？",a="幽暗城的护甲匠维罗拉·奈特雷需要结实的龙喉胫骨。她用这些骨头制作骨架支柱，为有潜力的部落战士打造残暴护腿。",al={"谁需要胫骨","维罗拉·奈特雷的骨头","交付龙喉胫骨"}},{q="这些骨头在哪里收集？",a="这些骨头来自阿拉希高地以南、湿地的叛离者龙喉氏族兽人。尤其是在萨多尔大桥西南方丘陵中的怒牙营地，可以找到这些兽人。",al={"哪里能找到龙喉胫骨","龙喉胫骨位置","怒牙骨头"}},{q="维罗拉·奈特雷为什么用兽人的骨头制作护甲？",a="被遗忘者铁匠用骨头、肌腱和金属制作坚固耐用的作战装备。龙喉氏族氏族与萨尔的部落为敌，因此被遗忘者铁匠将他们的遗骸用作坚韧的制作材料。",al={"为何使用兽人骨头","被遗忘者骨制护甲","维罗拉骨头制作"}}},fp="25,163,19.292.0,58.180.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="苏利·巴鲁的信",s="在萨多尔大桥下，苏利·巴鲁的信承载着一名士兵写给铁炉堡的萨拉的诀别。他的字里行间，满是生命最后时日里对她的爱。",h="在萨多尔大桥下，苏利·巴鲁的信承载着一名士兵写给铁炉堡的萨拉的诀别。他的字里行间，满是生命最后时日里对她的爱。",kw={"阿拉希高地","铁炉堡","信","萨拉·巴鲁","苏利·巴鲁","萨多尔大桥","浸透了水的信封","湿地"},ang={["faction:Alliance"]="身为联盟的一员，你可以将一名阵亡士兵最后的心声带给他的遗孀，让这些话语不至于被遗忘在桥下。",["race:Dwarf"]="身为矮人，你能从这封信中看到，普通的巡山人和士兵在守卫卡兹莫丹的高桥与山口时付出了怎样的牺牲。"},sec={{t="水下的最后诀别",b="在萨多尔大桥下，从湿地延伸而来的道路通向阿拉希高地。湍急的水流下，一具矮人的骸骨被压在那里。他的手中紧攥着一封被水浸透、脆弱不堪的信封。里面的信这样开头：“我亲爱的萨拉……”羊皮纸在水下受损，墨迹却依然诉说着这位矮人守卫者在生命最后几天或几个小时里的牵挂。他再也没有回到铁炉堡。"},{t="送往铁炉堡",b="在铁炉堡，萨拉·巴鲁一直等待着，自从丈夫出征，她便不知他的下落。苏利最后的心声让她在悲痛中得到了一个答案，也证实了她一直以来的恐惧：他死在远离家乡的北方渡口，长眠于水流之下。他亲笔写下的话语，将他的深情送到了她身边。"}},faq={{q="在哪里可以找到苏利·巴鲁的信？",a="在湿地与阿拉希高地之间的萨多尔大桥水下，一具矮人骸骨的手中紧攥着一个浸透了水的信封，信就在里面。",al={"信的位置","苏利的信在哪里","哪里能找到苏利·巴鲁的信"}},{q="苏利·巴鲁是谁？",a="苏利·巴鲁是一名矮人士兵，在保卫萨多尔大桥附近的北方渡口时阵亡。他的遗骸被压在河流之下。",al={"苏利·巴鲁是谁","苏利·巴鲁的故事","苏利遭遇了什么"}},{q="这封信是写给谁的？",a="这封信是写给萨拉·巴鲁夫人的，她是苏利的妻子，住在铁炉堡。",al={"信交给谁","萨拉·巴鲁是谁","苏利的信在哪里交"}},{q="将信交给萨拉·巴鲁后会发生什么？",a="萨拉·巴鲁读信后，得知丈夫葬身水下，悲痛欲绝。她仍能读到他满怀爱意写给她的最后话语。",al={"萨拉·巴鲁的反应","交付信件","苏利的信任务完成"}}},fx={efe638b9={q="苏利·巴鲁的信是什么？",a="这是一封饱经战火、情意深切的信，由一位名叫苏利·巴鲁的矮人士兵费尽心力写成。人们在萨多尔大桥下冰冷的水中发现了这封保存下来的信，里面是他战死前写给铁炉堡妻子的最后心声。",al={"苏利的信是什么","苏利·巴鲁的信","关于苏利·巴鲁的信"}},b8624ec6={q="苏利·巴鲁的信来自哪里，由谁写成？",a="这封信由苏利·巴鲁写成，他是一名联盟士兵，在湿地与阿拉希高地之间的萨多尔大桥前线服役。信保存在浸透了水的信封中，由他沉在大桥下的遗骸紧紧攥着。",al={"谁写了苏利·巴鲁的信","苏利的信来自哪里","苏利·巴鲁的信作者"}},b54d6872={q="为什么有人想要苏利·巴鲁的信？",a="收信人萨拉·巴鲁住在铁炉堡，尚不知道丈夫已不幸身亡。送达这封信，就能完成一位阵亡士兵的遗愿，也让这位悲伤地等待挚爱消息的遗孀得到苦乐交织的慰藉。",al={"为什么送苏利·巴鲁的信","谁要苏利的信","为什么把信交给萨拉·巴鲁"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sunscorched-shell"] = {n="晒焦的蛋壳",s="风巢下方，双足飞龙的卵留下了被千针石林的沙漠酷热晒硬的蛋壳。达纳苏斯的护甲匠玛希尔用它们制作涂在锁甲链环上的漆。",h="风巢下方，双足飞龙的卵留下了被千针石林的沙漠酷热晒硬的蛋壳。达纳苏斯的护甲匠玛希尔用它们制作涂在锁甲链环上的漆。",kw={"达纳苏斯","弗伦·长须","风巢","锁甲","玛希尔","晒焦的蛋壳","千针石林","双足飞龙"},ang={["class:Warrior"]="作为一名寻求锁甲防护的战士，你可以帮助玛希尔收集坚韧的蛋壳，用来强化护甲。",["profession:Blacksmithing"]="作为一名铁匠，你可以了解技艺精湛的铁匠如何利用天然矿物涂层，为锁甲制作防护漆。"},sec={{t="沙漠中的卵",b="风巢的双足飞龙在卡利姆多南部的石柱台地上产卵。在它们的巢穴下方，丢弃的蛋壳碎片经受着沙漠烈日与灼热狂风的烘烤。这些易碎的残片蕴含着天然的韧性，吸引了技艺精湛的工匠的注意。"},{t="工匠的漆",b="在达纳苏斯，护甲匠玛希尔正在研究他的同行、矮人铁匠弗伦·长须开创的技法。玛希尔将蛋壳加工成用于锁甲的精制漆。涂在金属链环上后，这层漆能增强链环的强度，又不会给穿戴者增加负担。"}},faq={{q="哪里能找到晒焦的蛋壳？",a="你可以在风巢各处的双足飞龙巢穴下方找到它们。风巢位于千针石林西部，是一座从峡谷底部拔地而起的高耸台地。",al={"晒焦的蛋壳位置","哪里找蛋壳","风巢蛋壳"}},{q="这些蛋壳来自什么生物？",a="它们是风巢双足飞龙留下的破碎蛋壳，这些双足飞龙栖息在千针石林的台地顶端。",al={"这些卵是什么生物产的","双足飞龙卵","蛋壳来源"}},{q="玛希尔为什么需要晒焦的蛋壳？",a="玛希尔想要试验弗伦·长须发现的护甲锻造技法。他将坚硬的蛋壳熬制成坚韧的漆，用来加固锁甲链环。",al={"玛希尔蛋壳","蛋壳用途","护甲漆"}},{q="弗伦·长须是谁，他与此事有何关联？",a="弗伦·长须是玛希尔的一位铁匠同行，在暴风城的矮人区工作。他对特殊材料和硬化技法的试验，启发了玛希尔尝试用双足飞龙的蛋壳制漆。",al={"弗伦的关联","弗伦·长须蛋壳"}}},fp="17,131,15.237.0,21.234.0,35.126.0,40.102.0,41.153.0,46.211.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="超级收割机6000型的设计图",s="在狂风峭壁，荆棘谷地精的超级收割机6000型的设计图令地精竞争对手垂涎不已。图纸记载了一种部署在石爪山脉的巨型机械伐木机的技术构造，其设计由侏儒工程师格雷苏监督完成。",h="在狂风峭壁，荆棘谷地精的超级收割机6000型的设计图令地精竞争对手垂涎不已。图纸记载了一种部署在石爪山脉的巨型机械伐木机的技术构造，其设计由侏儒工程师格雷苏监督完成。",kw={"设计图","格雷苏","斯布特瓦夫","石爪山","超级收割机6000","荆棘谷地精","狂风峭壁","菲兹克斯"},ang={["profession:Engineering"]="身为工程师，你看得出，格雷苏精密的侏儒式图纸让普通工匠摸不着头脑，而地精公司的打手们却已让这些机械运转起来。",["race:Gnome"]="身为侏儒，你能从设计图中看出格雷苏的奇思妙想。就连荆棘谷地精也要依靠侏儒工程师来设计复杂的重型机械。"},sec={{t="狂风峭壁的工业间谍",b="荆棘谷地精的操作员随身携带着超级收割机6000型的设计图，穿行于狂风峭壁。图纸展示了如何建造巨型机械伐木机，正是这些机器推动着公司无休止的毁林采伐。荆棘谷地精让侏儒格雷苏负责这一型号的设计，令传统的地精工程师们大为不满。地精工程师菲兹克斯被逐出这项工程后，斯布特瓦夫很快就雇用了他，让他窃取设计图。然而，格雷苏那些密密麻麻、古怪的侏儒式注释，解读起来几乎和强行夺取图纸一样困难。"}},faq={{q="超级收割机 6000是什么？",a="超级收割机 6000是一种巨型机械伐木机，专为荆棘谷地精在石爪山脉的毁林采伐而开发。",al={"超级收割机是什么","超级收割机机械"}},{q="谁设计了超级收割机6000？",a="侏儒工程师格雷苏受雇主持荆棘谷地精在狂风峭壁的机械工程后，在公司的监督下绘制了设计图。他的任命惹恼了当地的地精机械师。",al={"谁绘制了设计图","谁设计了超级收割机"}},{q="菲兹克斯为什么想要这些设计图？",a="荆棘谷地精赶走菲兹克斯后，斯布特瓦夫雇用他去窃取图纸。菲兹克斯想向新老板证明自己的价值和机械天赋。",al={"菲兹克斯为什么想要图纸","谁想要设计图"}},{q="狂风峭壁的设计图在谁手里？",a="荆棘谷地精的操作员随身携带着纸质图纸，在狂风峭壁各处监管机械并砍伐林木。",al={"设计图在哪里掉落","谁掉落设计图"}}},fp="28,235,38.481.0,30.131.0,35.214.0,43.156.0,43.120.0"}
P.entries["item:supplies-for-sven"] = {n="斯温的货物",s="夜色镇将补给送往斯温·约根在暮色森林西北部的营地。卡尔文家族为他的小队提供物资，帮助他们坚守岗位，抵御暗影。",h="夜色镇将补给送往斯温·约根在暮色森林西北部的营地。卡尔文家族为他的小队提供物资，帮助他们坚守岗位，抵御暗影。",kw={"营地","卡尔文","夜色镇","暮色森林","补给","斯温的货物","斯温·约根"},ang={["class:Paladin"]="身为圣骑士，你可以将斯温对暮色森林黑暗势力的抗争视为践行Light的事业。这些补给支援着一位信仰上的弟兄。",["faction:Alliance"]="守夜人为保卫夜色镇而疲于奔命，联盟旅人常常将补给送往斯温营地这样的孤立哨站。"},sec={{t="营地的生命线",b="斯温·约根和他为数不多的追随者在西北部的荒野扎营，远离夜色镇。他们人手太少，守卫任务又太繁重，无法抽出人手进镇。卡尔文家族将食物、绷带和其他必需品送往这处孤立的营地，帮助小队守住阵地。"}},faq={{q="这些补给是谁送来的？",a="这些补给由夜色镇的卡尔文家族送来。他们筹备物资，支援斯温·约根和他在荒野中的营地。",al={"谁送来斯温的货物","谁打包了斯温的补给","卡尔文家族补给"}},{q="斯温为什么不能自己去取补给？",a="斯温的小队人手太少，无法离开营地。他幸存的同伴在暮色森林西北部守卫营地，抵御野兽和亡灵，抽不出人手踏上通往夜色镇的危险道路。",al={"斯温为什么不去取食物","为什么要给斯温送货","为什么需要补给"}},{q="斯温的营地在哪里？",a="斯温的营地位于暮色森林西北边缘的丘陵中，超出了守夜人的直接保护范围。",al={"斯温·约根在哪里","斯温营地位置","暮色森林寻找斯温"}},{q="斯温·约根是谁？",a="斯温·约根是一名拓荒者，也是圣光的虔诚信徒，曾在暮色森林务农。家园遭逢惨剧后，他在边境建立了一处武装营地，反击肆虐这一地区的黑暗势力。",al={"斯温是谁","斯温·约根的往事"}}},fx={["0c0166a3"]={q="什么是斯温的货物？",a="这些货物是为斯温·约根及其在暮色森林坚守的一小队追随者准备的补给。卡雷文家族定期筹备这类援助，让这些忠诚的十字军能继续为圣光效力，对抗黑暗森林中的恐怖之物，不必放弃他们的守望。",al={"斯温的货物是什么","斯温的货物","斯温的货物物品"}}},fp="17,177,23.274.0,24.125.0,38.195.0,29.114.0,19.227.0"}
P.entries["item:surena-s-choker"] = {n="苏伦娜的项圈",s="在暴风城，黑暗缚灵者加科因想找回他送给昔日学徒苏伦娜·凯尔东的血石颈环。她与埃尔兰·杜德摩尔一同逃走，加入了迪菲亚潜行者，如今加科因派出有志入门的修习者，要他们用武力夺回颈环。",h="在暴风城，黑暗缚灵者加科因想找回他送给昔日学徒苏伦娜·凯尔东的血石颈环。她与埃尔兰·杜德摩尔一同逃走，加入了迪菲亚潜行者，如今加科因派出有志入门的修习者，要他们用武力夺回颈环。",kw={"血石颈环","布莱克威尔南瓜田","埃尔兰·杜德摩尔","黑暗缚灵者加科因","已宰的羔羊","苏伦娜·凯尔东","苏伦娜的项圈"},ang={["class:Warlock"]="对于人类或侏儒术士来说，取回苏伦娜·凯尔东的颈环是最初的试炼。它表明，在追求恶魔力量的道路上，容不得感情用事。"},sec={{t="导师付诸东流的心血",b="在暴风城已宰的羔羊的地下，黑暗缚灵者加科因曾传授苏伦娜·凯尔东黑暗法术。他看中了她青春的魅力与魔法天赋，送给她一条珍贵的血石颈环，帮助她研习法术。但苏伦娜放弃了修行，与效力于迪菲亚潜行者的潜行者埃尔兰·杜德摩尔一同逃走了。\n\n加科因不会让叛徒留着如此强大的神器。如今，他派出渴望掌控虚空的入门者，前往布莱克威尔南瓜田找到她，用武力夺回颈环。他们的行动将证明自己的忠诚究竟属于谁。"}},faq={{q="黑暗缚灵者加科因为何想要拿回苏伦娜的项圈？",a="苏伦娜还是学徒时，加科因把血石颈环送给了她。她放弃了学业，与一名迪菲亚潜行者成员一同逃走了。加科因不会让叛徒留着一件珍贵的黑暗魔法神器。",al={"加科因为何想要颈环","加科因 苏伦娜项链","为何要夺回颈环"}},{q="苏伦娜·凯尔东是谁？",a="苏伦娜·凯尔东曾是一名术士学徒，在暴风城师从黑暗缚灵者加科因时展现出与生俱来的天赋。她背弃了导师，与埃尔兰·杜德摩尔一同逃走，藏身于艾尔文森林的迪菲亚匪徒之中。",al={"苏伦娜是谁","苏伦娜·凯尔东的故事","颈环在谁手里"}},{q="在哪里能找到颈环？",a="苏伦娜·凯尔东随身带着颈环，躲在艾尔文森林东部布莱克威尔南瓜田的迪菲亚匪徒之中。",al={"苏伦娜在哪里","颈环位置","苏伦娜·凯尔东在哪里"}},{q="颈环取回后有什么用途？",a="夺回颈环能证明修习者的冷酷无情，以及对黑暗缚灵者加科因的忠诚。他没有说过会如何处置颈环。他为苏伦娜荒废的天赋感到惋惜，也希望自己在新学生身上投入的心血能换来不同的结果。",al={"加科因用颈环做什么","颈环用途","术士为何需要颈环"}}},fx={["195efbf9"]={q="苏伦娜的项圈是什么？",a="这是一条华丽的血石项链，原属于住在暴风城已宰的羔羊的术士大师黑暗缚灵者加科因。在昔日的学徒苏伦娜·凯尔东背叛他之前，加科因曾迷恋她的青春与美貌，将这件珍贵的首饰赠予了她。",al={"苏伦娜的项圈是什么","苏伦娜的项圈是什么东西","血石颈环"}},["7b9593ae"]={q="苏伦娜的项圈从何而来，是谁制作的？",a="项圈的具体制作者无人知晓，但它最初由黑暗缚灵者加科因持有。在年轻的学生苏伦娜·凯尔东跟随他学习期间，加科因将这条血石项链赠予了她，那时距离她与一名迪菲亚潜行者私奔到艾尔文的南瓜田还有很久。",al={"苏伦娜的项圈是谁制作的","苏伦娜的项圈的来历","项圈从何而来"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="猛鹫的胃",s="猛鹫是翱翔于莫高雷各地的猛禽，它们的胃被用于制作对抗致命毒素的传统药物。",h="猛鹫是翱翔于莫高雷各地的猛禽，它们的胃被用于制作对抗致命毒素的传统药物。",kw={"血蹄村","胃","茂尔·祈雨","马兹拉纳其","莫高雷","药方","猛鹫"},ang={["race:Tauren"]="身为牛头人猎人或萨满祭司，收集这些部位就是在尊崇利用莫高雷野生动物养育和医治部族的传统。"},sec={{t="珍稀的民间药材",b="猛鹫在莫高雷的平原与台地间猎食，目光敏锐，也喜食腐肉。牛头人在日常生活中使用它们的羽毛和肉，而草药师与医者则珍视它们的内脏，尤其是胃。猛鹫的胃厚实且肌肉发达，与狮骨和狼心配合使用，有助于治疗毒咬伤和溃烂的感染。"},{t="医治马兹拉纳其咬伤的药方",b="在血蹄村，茂尔·祈雨正照料着马兹拉纳其在他肩上留下的伤口。随着毒素在体内蔓延，这只传说中的平原陆行鸟的毒液让茂尔陷入谵妄。为了制成能够驱除致命毒液的膏药，茂尔需要猛鹫的胃、草原狼的心脏、平原狮的腿骨和平原陆行鸟的鳞片。"}},faq={{q="猛鹫的胃有什么用途？",a="血蹄村的茂尔·祈雨需要猛鹫的胃，作为药方中不可或缺的一味药材。它与另外三种动物身体部位混合后，能制成药物，治疗凶猛的平原陆行鸟马兹拉纳其留下的毒性感染。",al={"猛鹫的胃用途","为何需要猛鹫的胃","猛鹫内脏用途"}},{q="猛鹫的胃从何而来？",a="猛鹫的胃来自滑翔于莫高雷平原上空的猛鹫，包括普通猛鹫、瘦小的猛鹫和利爪猛鹫。",al={"哪里能找到猛鹫的胃","什么掉落猛鹫的胃","猎杀猛鹫"}},{q="茂尔·祈雨为什么需要这个特定部位？",a="马兹拉纳其咬伤了茂尔，这只异常凶猛的平原陆行鸟的毒液让他高烧不退，噩梦连连。牛头人的民间医术使用药效强劲的动物身体部位，包括胃，来对抗茂尔血脉中的毒素。",al={"茂尔的药方","为何要用胃","医治马兹拉纳其咬伤"}},{q="除了医治茂尔，猛鹫的胃还有其他用途吗？",a="没有。除了用于血蹄村茂尔·祈雨的特制民间药方，猛鹫的胃在烹饪、炼金或制造中都没有常规用途。",al={"猛鹫的胃其他用途","猛鹫的胃烹饪","猛鹫的胃炼金"}}},fp="13,123,22.322.0,31.338.0,33.200.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:tablet-of-verga"] = {n="维尔加石板",s="维尔加石板落在骷髅石的火刃氏族手中，奥格瑞玛的术士正寻求其上记载的恶魔符文。",h="维尔加石板落在骷髅石的火刃氏族手中，奥格瑞玛的术士正寻求其上记载的恶魔符文。",kw={"火刃氏族","暗影裂口","杜隆塔尔","甘鲁尔·血眼","骷髅石","维尔加石板","虚空行者"},ang={["class:Warlock"]="作为在奥格瑞玛修习的术士，夺回石板意味着你向部落证明自身价值、学会束缚擅长防御的虚空行者仆从又迈进了一步。",["faction:Horde"]="作为部落的一员，你要在奥格瑞玛城门附近对抗火刃氏族。从教徒手中夺回失窃的遗物，能打击他们对萨尔新建国度的影响。"},sec={{t="失窃的遗物",b="维尔加石板上刻着仪式符文，能召唤虚空中的生物，并使其服从主人的意志。火刃氏族的教徒偷走了石板，将它藏在奥格瑞玛东边骷髅石内的一只箱子里。暗影裂口的术士想要找到它，研究上面的符文，学习召唤虚空行者。夺回石板也能防止教徒获得同样的优势。"}},faq={{q="维尔加石板在哪里？",a="维尔加石板藏在骷髅石内的火刃氏族的藏匿处中，骷髅石位于杜隆塔尔的奥格瑞玛东边，是一片遍布教徒的洞穴。",al={"维尔加石板位置","哪里能找到维尔加石板","维尔加石板在哪"}},{q="谁想找回维尔加石板？",a="甘鲁尔·血眼是奥格瑞玛地下暗影裂口的一位术士大师，他派遣学徒取回石板，以便教导他们召唤更强大的仆从。",al={"谁需要维尔加石板","维尔加石板交给谁","甘鲁尔石板"}},{q="石板蕴含什么力量？",a="石板上刻着召唤并束缚虚空行者所需的古老符文，这种生物来自扭曲虚空。",al={"石板有什么用","维尔加石板背景故事","维尔加石板符文"}},{q="火刃氏族为什么偷走石板？",a="火刃氏族的教徒企图破坏部落，增强自身的恶魔力量。偷走石板既能让奥格瑞玛的施法者失去关键的仪式知识，又能让教徒将这些知识据为己有。",al={"火刃氏族为什么持有石板","火刃氏族维尔加"}}},fp="15,117,14.387.0,37.143.0,40.162.0,35.112.0,35.197.0"}
P.entries["item:tainted-heart"] = {n="被污染的心脏",s="在泰达希尔，德纳兰将一颗仍受腐化侵扰的心脏交给冒险者。虽然表面的污秽苔藓已被清除，残留的能量却依然存在，他希望用肥沃的土壤将其净化。",h="在泰达希尔，德纳兰将一颗仍受腐化侵扰的心脏交给冒险者。虽然表面的污秽苔藓已被清除，残留的能量却依然存在，他希望用肥沃的土壤将其净化。",kw={"净化","腐化","德纳兰","奥拉密斯湖","花盆","被污染的心脏","泰达希尔"},ang={["class:Druid"]="作为一名塞纳里奥德鲁伊，净化被污染的心脏能让你直接了解那股悄然蔓延、威胁着这棵年轻世界之树健康的腐化力量。",["profession:Herbalism"]="作为一名草药师，你能领会德纳兰调配肥沃土壤的技艺，这些土壤能从活体植物组织中汲出违背自然的腐败。"},sec={{t="腐化核心",b="一种令植物和野兽扭曲的疾病，正在扰乱泰达希尔的自然平衡。一株枯萎的植物被剥去污秽苔藓后，德纳兰将其内部的被污染的心脏交给冒险者。黑暗仍盘踞在心脏的组织中。德纳兰希望，经过特殊配制、富含养分的土壤能够消除污染，让遭到腐化的生命恢复原貌。"},{t="德纳兰的疗法",b="被污染的心脏被放入德纳兰的魔法花盆后，显露出奇异的生命力。它钻入肥沃的土壤，吸收其中具有疗愈作用的养分。土壤灼除了腐化，心脏随后破土而出，生机盎然，纯净的能量在其中搏动，迫切地想要保护治愈它的人。"}},faq={{q="被污染的心脏是什么？",a="被污染的心脏是泰达希尔上一株腐化植物的内核。植物学家德纳兰剥去了污秽的苔藓，但心脏在得到净化前仍处于腐化之中。",al={"被污染的心脏是什么","被污染的心脏物品"}},{q="谁来净化被污染的心脏？",a="德纳兰指引冒险者，将被污染的心脏种在他位于奥拉密斯湖的特制花盆中。富含养分的土壤会净化它，清除其中违背自然的腐化。",al={"谁来净化","如何净化被污染的心脏"}},{q="种下后会发生什么？",a="心脏钻入花盆的土壤中。片刻之后，它便破土而出，已被净化，充满跃动的生命力，随时准备与使它恢复的人建立羁绊。",al={"心脏会发生什么","种下心脏的结果"}},{q="心脏最初为何会受到腐化？",a="一种奇异的枯萎病正在世界之树泰达希尔蔓延，腐化着遍布其枝干的本土植物、树精和野生动物。",al={"为何受到腐化","泰达希尔腐化心脏"}}},fp="13,150,16.325.0,16.267.1,26.165.0,31.186.0,33.144.1,46.132.0"}
P.entries["item:tainted-keg"] = {n="被污染的酒桶",s="在塔伦米尔，被污染的酒桶里装着偷来的矮人烈酒，其中掺入了药剂师林度恩调制的致命被遗忘者药剂。这桶酒被当作饮品送给遭囚禁的人类农夫，用来测试皇家药剂师学会正在研制的毒药。",h="在塔伦米尔，被污染的酒桶里装着偷来的矮人烈酒，其中掺入了药剂师林度恩调制的致命被遗忘者药剂。这桶酒被当作饮品送给遭囚禁的人类农夫，用来测试皇家药剂师学会正在研制的毒药。",kw={"药剂师林度恩","被俘的农夫","丹加洛克","苦楚药剂","矮人烈酒","被污染的酒桶","塔伦米尔"},ang={["race:Human"]="用掺毒麦酒杀害被俘的乡间劳工，显露出遍布希尔斯布莱德的幸存生者所面临的残酷手段。",["race:Undead"]="对皇家药剂师学会而言，这桶被污染的烈酒标志着他们在制造能够灭绝人类的生物武器方面取得了进展。"},sec={{t="致命佳酿",b="丹加洛克的矮人火枪手被窃贼偷走了一桶矮人烈酒。药剂师林度恩将他新近精炼的苦楚药剂混入烈酒。被遗忘者选择用一种寻常饮品承载毒药，希望借此避人耳目。熟悉的麦酒成了迅速夺命的催命符。"},{t="囚徒试毒",b="几名人类农夫被关押在塔伦米尔旅店的楼上。高级执行官达萨利亚怀疑，一名暴风城的军事谋士藏在他们之中。当那名谋士已在别处身亡的消息传来，农夫们便失去了利用价值。达萨利亚将他们交给林度恩，后者把掺了毒药的酒桶放在囚室的地毯上，作为一场残忍庆祝的一部分。囚徒们口渴难耐，绝望之下喝了酒。药剂迅速夺去了他们的性命，证明了其致命效力。"}},faq={{q="被污染的酒桶里装着什么？",a="酒桶里装着烈性矮人麦酒，一种从丹加洛克偷来的矮人麦酒，其中混入了苦楚药剂，这是药剂师林度恩在塔伦米尔研制的一种试验性毒药。",al={"被污染的酒桶里的东西","酒桶里有什么毒药","桶里装着什么"}},{q="麦酒最初来自哪里？",a="烈酒是从丹加洛克的矮人巡山人和火枪手那里偷来的，那是一座位于希尔斯布莱德丘陵东南部、戒备森严的堡垒。",al={"谁酿造了麦酒","烈酒是从哪里偷来的","矮人烈酒来源"}},{q="谁喝了酒桶里的酒？",a="被关押在塔伦米尔旅店楼上房间里的人类农夫喝下了桶里的酒，几乎立刻就被毒酒夺去了性命。",al={"谁喝了酒","被污染的酒桶的受害者","被俘的农夫"}},{q="农夫们为何遭到囚禁？",a="高级执行官达萨利亚囚禁了这些农夫，因为她怀疑一名来自暴风城的联盟军事谋士藏在他们之中。在确认那名谋士已死于瘟疫之地后，农夫们被认定再无用处，随即被交给了药剂师们。",al={"为何囚禁农夫","达萨利亚为何抓捕农夫","农夫为何在塔伦米尔"}}},fx={fd5e0197={q="什么是被污染的酒桶？",a="被污染的酒桶里装着被盗来的矮人掘地工烈酒，其中掺入了被遗忘者调制的致命混合物。药剂师林度恩配制了这批致命的污染酒，作为他持续进行的炼金研究中的实用试验。",al={"什么是被污染的酒桶","被污染的酒桶物品","这个酒桶是什么"}},["5c778a45"]={q="药剂师林度恩为什么要使用被污染的酒桶？",a="药剂师林度恩想让人把酒桶送去，以测试他刚刚完成的苦楚精华药剂是否有效。高级执行官达萨利亚已将抓获的人类农夫交由他处置，而向他们提供毒酒，能让皇家药剂师协会方便地亲眼观察毒素的致命效果。",al={"为什么要使用被污染的酒桶","林度恩为什么要被污染的酒桶","被污染的酒桶的用途"}}},fp="11,201,16.276.0,24.458.1,31.151.0,39.136.0,24.115.1,41.243.0"}
P.entries["item:tainted-letter"] = {n="被污染的信件",s="在北郡修道院附近，杜希拉·拉萨雷向人类术士学徒寄出密封的召唤信，召他们避开旁人的目光，接受秘密教导。",h="在北郡修道院附近，杜希拉·拉萨雷向人类术士学徒寄出密封的召唤信，召他们避开旁人的目光，接受秘密教导。",kw={"杜希拉·拉萨雷","艾尔文森林","北郡修道院","被污染的信件","扭曲虚空","术士"},ang={["class:Warlock"]="身为术士，你收到被污染的信件，由此踏入暴风城王国中隐秘的法术之道。要掌控虚空的力量，就必须时刻保持警惕，谨慎行事。",["race:Human"]="身为人类，你生活在一个普遍崇奉圣光的社会中。黑暗魔法的研习者在北郡修道院这样的地方，隐于外围秘密修习。"},sec={{t="秘密召唤",b="从附近狗头人营地归来的学徒，带着杜希拉的召唤信前往北郡修道院。牧师、圣骑士和士兵在修道院的草坪上公开训练，但研习邪能的人必须隐瞒自己的道路。初出茅庐的术士若在修道院周边寻找导师时引人注目，就可能招来镇上卫兵和神职人员的怀疑。"},{t="野心的代价",b="杜希拉·拉萨雷在修道院外围接见学生，那里的哨兵不太会窥探他们的举动。艾尔文的普通民众不信任术士，而这封信开启了一堂关于自律的课。奥术和虚空魔法都有带来腐化的风险。与扭曲虚空中的生灵交流之人，必须以耐心的自制约束野心。"}},faq={{q="谁寄出了被污染的信件？",a="这封信由北郡修道院附近的术士训练师杜希拉·拉萨雷寄出。",al={"谁写了被污染的信件","杜希拉的信","被污染的信件寄件人"}},{q="为什么这封信被认为受到了污染？",a="杜希拉·拉萨雷的徽记和邪能魔法的痕迹，表明这封信出自一位研习恶魔法术的人之手。",al={"为什么受到污染","信件为何受到污染","被污染的封印"}},{q="北郡的卫兵为什么监视杜希拉·拉萨雷？",a="北郡的卫兵和牧师不信任邪能魔法与恶魔召唤术。杜希拉待在修道院外围，以避开他们的严密监视。",al={"杜希拉与卫兵","卫兵为何怀疑杜希拉","藏身北郡的术士"}},{q="读完信后，杜希拉会给出什么忠告？",a="杜希拉警告说，与来自扭曲虚空的存在打交道，会带来诱惑与腐化。她敦促学生们在坚守野心的同时，保持自制与审慎。",al={"杜希拉的忠告","杜希拉说了什么","杜希拉的训练"}}},fx={["63258adc"]={q="被污染的信件是什么？",a="被污染的信件是你返回北郡修道院时留给你的一封密封信函，上面盖着杜希拉·拉萨雷独有的私人印记。这封信写给初涉黑暗法术的学徒，急切地召唤他们前去与她面谈。信上带有微弱的邪能腐化痕迹，与修道院围墙内虔诚而井然有序的圣光事务截然不同。",al={"被污染的信件是什么","被污染的信件的身份","关于被污染的信件"}},["3c923280"]={q="为什么要把被污染的信件交给你？",a="这封信交到你手中，是为了让你完成北郡一带的初步任务后，尽快与你的训练师杜希拉·拉萨雷取得联系。杜希拉在修道院边缘悄然活动，密切留意着崭露头角的术士。信中指引你在被修道院的其他事务分心之前去找她，好让她向你传授有关自制、野心以及扭曲虚空腐化本质的重要警示。",al={"为什么需要被污染的信件","谁需要被污染的信件","为什么交付被污染的信件"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="被污染的备忘录",s="在寒脊山谷，阿拉玛尔·格里姆敦促初出茅庐的侏儒术士抛弃旧路，通过黑暗魔法寻求力量。",h="在寒脊山谷，阿拉玛尔·格里姆敦促初出茅庐的侏儒术士抛弃旧路，通过黑暗魔法寻求力量。",kw={"阿拉玛尔·格里姆","安威玛尔","寒脊山谷","侏儒术士","诺莫瑞根","被污染的备忘录"},ang={["class:Warlock"]="身为术士，你在阿拉玛尔·格里姆的指导下接受训练。他将黑暗召唤之术视为掌控局势、获取力量的途径。",["race:Gnome"]="身为侏儒，你听到格里姆试图唤起你的愤懑：诺莫瑞根已然失落，而你的族人似乎成了矮人土地上仰人鼻息的难民。"},sec={{t="隐秘的召唤",b="在安威玛尔，鲜有人赞许邪能施法者，许多人都不信任他们。阿拉玛尔·格里姆将被污染的备忘录交给研习禁忌法术的年轻侏儒。他摒弃圣光，也不屑于寻常武器。在他看来，诺莫瑞根的陷落证明，旧有的道路和机械技艺辜负了他们的族人。\n\n格里姆认为，依赖矮人的施舍是一条死路。他敦促侏儒掌握不容置疑的力量，召唤绝对服从命令的仆从。他相信，唯有如此，他们才能保障自己的未来。"}},faq={{q="被污染的备忘录是谁写的？",a="被污染的备忘录出自安威玛尔的侏儒术士训练师阿拉玛尔·格里姆之手。",al={"被污染的备忘录作者","谁寄出了被污染的备忘录","阿拉玛尔·格里姆字条"}},{q="为什么这份备忘录被称为“被污染的”？",a="这份备忘录涉及禁忌的术士魔法。它的标题反映了丹莫罗对恶魔和邪能力量的不信任，在那里，作为东道主的矮人对这些力量的使用者敬而远之。",al={"为何被污染","被污染的信件背景故事"}},{q="阿拉玛尔·格里姆如何看待诺莫瑞根？",a="阿拉玛尔·格里姆认为，传统的奥术魔法和草率的机械摆弄，导致侏儒在诺莫瑞根陷落时濒临灭绝。他认为矮人将侏儒视为二等公民，并敦促术士掌握属于自己的绝对力量，而非等待联盟的援助。",al={"阿拉玛尔·格里姆 诺莫瑞根","阿拉玛尔·格里姆的观点"}}},fx={["0c729b68"]={q="被污染的备忘录是什么？",a="被污染的备忘录是一封私密的个人便笺，写给刚在寒脊山谷开始训练、颇有潜力的侏儒术士。这张便笺由地表的盟友悄悄传递，邀请他们将目光投向圣光或武力战斗的常规传统之外，寻找志趣相投、思想开放且研习黑暗法术的同道。",al={"被污染的备忘录是什么","被污染的备忘录","这张便笺是什么"}},e7be2e4a={q="为什么有人要把被污染的备忘录交给你？",a="这份备忘录交给你，是为了招揽你踏入术士之道。术士训练师阿拉玛尔·格里姆借它寻找不愿遵循矮人与侏儒常规教条的新手施法者，催促你到安威玛尔与他见面，学习驾驭召唤而来的顺从盟友，并揭开恶魔力量的真正源泉。",al={"为什么收到备忘录","为什么需要被污染的备忘录","谁需要被污染的备忘录"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="堕落护符",s="在黑海岸，萨巴克希斯用堕落护符驱使黑木熊怪与昔日的盟友为敌。这个萨特将护符放在随身携带的袋子里，护符的魔力使整个部族陷入邪能带来的疯狂。",h="在黑海岸，萨巴克希斯用堕落护符驱使黑木熊怪与昔日的盟友为敌。这个萨特将护符放在随身携带的袋子里，护符的魔力使整个部族陷入邪能带来的疯狂。",kw={"奥伯丁","黑木","黑海岸","熊怪","萨特","堕落护符","桑迪斯·织风","萨巴克希斯"},ang={["class:Druid"]="身为德鲁伊，你认为护符这类器物是对自然秩序的亵渎。它们将神圣的野兽扭曲成狂野的傀儡，供燃烧军团残余的爪牙驱使。",["race:NightElf"]="身为奥伯丁的卡多雷，找回护符有助于让与你的先祖结盟的熊怪摆脱恶魔的腐化，并治愈这片土地。"},sec={{t="疯狂的媒介",b="奥伯丁的暗夜精灵一直在追查黑木熊怪背叛昔日盟友的原因。桑迪斯·织风发现，是萨特导致了这个部族的堕落。恶魔的爪牙利用这样的护符，在荒野中散播腐化巫术，污染食物，将平和的森林之灵扭曲成狂暴的野兽。这些器物引导邪能魔法，控制当地部族的心智与意志。"},{t="挣脱控制",b="为了引出萨巴克希斯，你用受过祝福的月亮井水净化熊怪的食物样本。净化之举激怒了这名监工。萨巴克希斯被杀死后，你从他的恶魔之袋中取出护符。你将它带给奥伯丁的桑迪斯·织风，让卡多雷消除它散发的邪恶力量，并研究如何解除森林中的恶魔诅咒。"}},faq={{q="堕落护符是什么？",a="萨巴克希斯利用堕落护符引导邪恶魔法，腐化黑海岸黑木熊怪的心智和食物。",al={"堕落护符是什么","护符用途","护符有什么作用"}},{q="谁携带着护符？",a="萨巴克希斯将护符放在他的恶魔之袋中随身携带，这个萨特负责监督壁泉河附近的黑木熊怪北部营地。",al={"谁掉落堕落护符","堕落护符在哪里","如何获得护符"}},{q="如何引出护符的持有者？",a="你收集熊怪的水果、谷物和坚果，然后在净化之碗中将它们与月亮井水混合。将这份供品放在河边的篝火旁，净化之举便会激怒萨巴克希斯，令他发动攻击。",al={"如何召唤萨巴克希斯","如何找到萨巴克希斯","黑海岸召唤萨特"}},{q="找回护符后会如何处置？",a="你将护符带给奥伯丁的桑迪斯·织风。他将护符妥善保管，等待处理，并研究如何让熊怪永久摆脱恶魔的腐化。",al={"护符交给谁","交付堕落护符","桑迪斯·织风护符"}}},fp="22,194,20.379.0,17.350.1,35.126.0,25.134.0,46.205.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="塔隆凯的珠宝",s="塔隆凯的珠宝是一颗从泰达希尔上一件附魔德鲁伊法器中被窃走的闪光翡翠。这颗珠宝被熊怪秘法师“梦境吞噬者”费罗卡斯视为珍宝，它是修复翡翠摄梦符所必需的关键核心。",h="塔隆凯的珠宝是一颗从泰达希尔上一件附魔德鲁伊法器中被窃走的闪光翡翠。这颗珠宝被熊怪秘法师“梦境吞噬者”费罗卡斯视为珍宝，它是修复翡翠摄梦符所必需的关键核心。",kw={"多兰纳尔","翡翠摄梦符","梦境吞噬者费罗卡斯","蓟皮秘法师","星风村","塔隆凯·捷根","塔隆凯的珠宝"},ang={["class:Druid"]="这颗翡翠是一种特制的德鲁伊组件，旨在与翡翠梦境产生共鸣，因此被腐蚀的熊怪滥用它是对自然平衡的亵渎。",["race:NightElf"]="取回珠宝有助于恢复泰达希尔的秩序，因为它将神圣的工艺品从入侵的蓟皮熊怪手中夺回。"},sec={{t="被窃的核心",b="塔隆凯·捷根从班奈希尔兽穴的德鲁伊守护者Gaerolas Talvethen那里得到了翡翠摄梦符，这是一种可以从翡翠梦境中汲取能量的强大法器。当他的护身符受损时，中央那颗光芒四射的翡翠被撬了下来，并被带到了泰达希尔东部的荒野中。这颗珠宝落入了“梦境吞噬者”费罗卡斯的手中，这是一位被腐蚀的蓟皮熊怪领袖，他将这颗闪耀的宝石做成了自己的项链。虽然这颗绿色宝石在幽暗的森林中投下了一道诡异的光芒，但其真正的和谐共鸣对这只熊怪来说完全毫无用处，在被取回之前，它仅仅是作为一个战利品存在。"}},faq={{q="什么是塔隆凯的珠宝？",a="它是一颗附魔的闪光翡翠，是翡翠摄梦符的核心部件，翡翠摄梦符是由Gaerolas Talvethen送给多兰纳尔的塔隆凯·捷根的德鲁伊法器。",al={"什么是珠宝","塔隆凯的珠宝背景"}},{q="是谁偷走了塔隆凯的珠宝？",a="它是由“梦境吞噬者”费罗卡斯偷走的，他是居住在星风村北部的被腐蚀的蓟皮熊怪秘法师中的领袖。",al={"谁拥有珠宝","谁偷了它","谁拿走了塔隆凯的珠宝"}},{q="蓟皮熊怪能使用这颗珠宝的力量吗？",a="不能。虽然费罗卡斯把这颗翡翠戴在脖子上作为发光的装饰品，但塔隆凯指出，这块宝石的德鲁伊力量对这只被腐蚀的熊怪来说毫无用处。",al={"费罗卡斯能用它吗","蓟皮翡翠力量"}},{q="珠宝被取回后去了哪里？",a="宝石被送回了位于多兰纳尔上层的塔隆凯·捷根手中，他用它来完全修复和补好受损的翡翠摄梦符。",al={"珠宝的下落","修复摄梦符"}}},fp="17,157,13.586.0,26.159.0,28.119.0,49.113.0,46.135.0"}
P.entries["item:taming-rod"] = {n="驯兽棒",s="在杜隆塔尔，驯兽棒帮助新手猎人学习指挥野兽。训练师将它们交给学徒，让他们在与动物伙伴建立长久羁绊之前先行练习。",h="在杜隆塔尔，驯兽棒帮助新手猎人学习指挥野兽。训练师将它们交给学徒，让他们在与动物伙伴建立长久羁绊之前先行练习。",kw={"硬甲蝎","可怕的杂斑野猪","猎人宠物","剃刀岭","驯兽棒","驯服野兽","索塔尔"},ang={["class:Hunter"]="身为猎人，在能够与野兽建立长久羁绊之前，你会使用驯兽棒进行练习。",["faction:Horde"]="在杜隆塔尔和莫高雷，索塔尔等训练师用驯兽棒考验年轻的新学徒，看他们是否具备驾驭卡利姆多凶悍野兽所需的自律。"},sec={{t="导师的训练用具",b="在剃刀岭，索塔尔等训练师会将驯兽棒交给立志成为猎人的兽人和巨魔。这些附有魔法的工具能帮助尚无法与野生生物建立永久羁绊的新手。驯兽棒能安抚当地的捕食者，例如可怕的杂斑野猪或硬甲蝎，让猎人练习下达命令，并与动物伙伴并肩作战。这种羁绊只能短暂维持，让学徒能够练习，而不必与野兽建立长久的联系。"},{t="迈向精通的一步",b="每根驯兽棒的魔法都会在短时间后消退，而且各自只能作用于特定种类的野兽。新手要接连面对性情不同的野兽，完成一系列试炼，从温顺的觅食者到凶猛的剧毒猎食者。当学徒证明自己能够指挥它们后，就会将驯兽棒交还训练师。随后，训练师会教导学徒不借助魔法器物，驯服、召唤和解散终生相伴的伙伴。"}},faq={{q="驯兽棒有什么用途？",a="猎人用驯兽棒练习在战斗中指挥野兽。训练师会将它交给年轻的猎人，它的魔法能短暂安抚并魅惑野兽。",al={"驯兽棒有什么作用","驯兽棒用途","为什么会有驯兽棒"}},{q="用驯兽棒驯服的宠物可以一直保留吗？",a="不可以。受驯兽棒影响的野兽只用于训练，魔法消退或你交还驯兽棒时，羁绊就会结束。完成试炼后，你会学到如何驯服长久相伴的伙伴。",al={"宠物是否永久保留","野猪能否保留","蝎子能否保留"}},{q="任何驯兽棒都能对任何动物使用吗？",a="不能。每根驯兽棒都只能作用于相应训练阶段的特定目标生物，例如可怕的杂斑野猪或硬甲蝎。",al={"驯兽棒是否对所有生物有效","驯兽棒目标"}},{q="完成训练后可以保留驯兽棒吗？",a="不可以。完成任务后，你要将驯兽棒交还猎人训练师。最后一场试炼结束后，训练师会教你独自驯服、召唤和解散野兽。",al={"保留驯兽棒","驯兽棒能否留下"}}},fp="10,164,28.377.0,21.391.0,30.160.0,38.189.0,39.141.0,56.172.0"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="塔拉加曼的心脏",s="在奥格瑞玛地下，尼尔鲁·火刃想要塔拉加曼的心脏，以此证明恶魔已被清除。这件战利品来自统治怒焰裂谷深处的恶魔卫士。",h="在奥格瑞玛地下，尼尔鲁·火刃想要塔拉加曼的心脏，以此证明恶魔已被清除。这件战利品来自统治怒焰裂谷深处的恶魔卫士。",kw={"恶魔卫士","心脏","饥饿者","尼尔鲁·火刃","奥格瑞玛","怒焰裂谷","灼热之刃","塔拉加曼"},ang={["class:Warlock"]="身为术士，你了解暗影裂口中暗影与欺诈交织而成的微妙关系网。与尼尔鲁·火刃打交道、处理恶魔残骸，对你而言都是熟悉的事。",["faction:Horde"]="身为部落的一员，你协助保护奥格瑞玛，使其免遭内部的腐化。这头怪物被剜出的心脏，彰显着部落的警惕。"},sec={{t="欺诈的战利品",b="饥饿者塔拉加曼的心脏证明这名恶魔卫士已经倒下。尼尔鲁·火刃告诉萨尔和热切的冒险者，塔拉加曼指挥着怒焰裂谷中的灼热之刃邪教徒。把心脏带给尼尔鲁，似乎就能完成大酋长的命令，保护奥格瑞玛免遭恶魔腐化。将邪教的领导者说成一名粗暴的恶魔卫士，也让城下凡人之间的关系网得以继续隐藏。"}},faq={{q="谁想要塔拉加曼的心脏？",a="尼尔鲁·火刃是奥格瑞玛暗影裂口的一名兽人术士，他要你把心脏带给他，以此证明恶魔已被杀死。",al={"谁收取 塔拉加曼 的心脏","塔拉加曼 的心脏交给谁","谁想要心脏"}},{q="在哪里能取得这颗心脏？",a="你可以在奥格瑞玛地下、怒焰裂谷中央的熔岩洞窟中，从饥饿者塔拉加曼的尸体上取走心脏。那名威势逼人的恶魔卫士就栖身于此。",al={"如何获得 塔拉加曼 的心脏","塔拉加曼 的心脏在哪里掉落","塔拉加曼 的心脏位置"}},{q="萨尔见过这颗心脏吗？",a="没有。你会把心脏直接交给尼尔鲁·火刃。他说自己会处理这些恶魔残骸，并替你向大酋长萨尔禀报胜利。",al={"萨尔会收到心脏吗","把心脏交给萨尔","萨尔 塔拉加曼 的心脏"}},{q="塔拉加曼真的是灼热之刃的首领吗？",a="尼尔鲁·火刃指认饥饿者塔拉加曼是灼热之刃的首领。他说，杀死这个恶魔并带回其心脏，就能让萨尔满意。",al={"塔拉加曼 是首领吗","谁领导 灼热之刃","塔拉加曼 真正首领"}}},fx={a71e3ad9={q="什么是饥饿者塔拉加曼的心脏？",a="这是饥饿者塔拉加曼被剖出的心脏。塔拉加曼是一只体型巨大的恶魔卫士，潜伏在奥格瑞玛下方怒焰裂谷的熔岩深处。冒险者将心脏从洞穴中带出，作为证据，证明被尼鲁·火刃称为灼热之刃首领的恶魔已被击败。",al={"什么是塔拉加曼的心脏","饥饿者塔拉加曼的心脏","塔拉加曼的心脏背景"}},d8388abb={q="饥饿者塔拉加曼的心脏从何而来？",a="这颗心脏是从饥饿者塔拉加曼的胸膛中剜出的。他是一只驻守在怒焰裂谷深处的巨型恶魔卫士。灼热之刃教徒在奥格瑞玛下方的地下隧道中召唤并藏匿了塔拉加曼，因此这颗心脏成了侵蚀城市地下深处的恶魔腐化的有机遗物。",al={"塔拉加曼的心脏的来历","这颗心脏从哪里来","谁制作了塔拉加曼的心脏"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="破损的手稿",s="破损的手稿藏在千针石林的裂蹄堡中。这些残页出自阴谋之书，术士们寻找它们，以学习召唤地狱猎犬的方法。",h="破损的手稿藏在千针石林的裂蹄堡中。这些残页出自阴谋之书，术士们寻找它们，以学习召唤地狱猎犬的方法。",kw={"地狱猎犬","约拉·安尼森","克罗姆·粗臂","发霉的书籍","裂蹄堡","破损的手稿","千针石林","阴谋之书"},ang={["class:Warlock"]="身为术士，你寻找这份手稿，是为了获得驾驭地狱猎犬的知识。"},sec={{t="遭到毁坏的魔典",b="阴谋之书曾是一部完整的孤本，保存在如今已覆灭的洛丹伦王国。一名身份不明的亵渎者从装订处撕走了近半数书页。留下的书脊和书页后来被称为发霉的书籍。它们被向南运往卡兹莫丹，却在途中遗失于海中。被撕下的书页则越过无尽之海，抵达卡利姆多，落入裂蹄堡内的加拉克半人马手中。"},{t="寻回残篇",b="手稿存放在裂蹄堡洞穴深处的一个破旧箱子里。它在那里经受着千针石林干燥的风。联盟术士与铁炉堡的克罗姆·粗臂合作，部落的施术者则协助幽暗城的约拉·安尼森。双方都冒险迎战凶悍的半人马，力图将残页与发霉的书籍重新合为一体。两者合起来，便记载着召唤并束缚恶魔地狱猎犬的黑暗仪式。"}},faq={{q="破损的手稿是什么？",a="破损的手稿汇集了一批残页，约占孤本阴谋之书的一半，这部魔典记载着恶魔学知识。",al={"破损的手稿背景故事","手稿是什么","阴谋之书书页"}},{q="这些书页是如何流落到千针石林的？",a="一名身份不明的亵渎者在洛丹伦撕毁阴谋之书后，书页漂洋过海。加拉克半人马得到这些书页，将它们藏在裂蹄堡内的一个箱子里。",al={"为何在裂蹄堡","半人马魔典","千针石林手稿"}},{q="手稿有什么用途？",a="术士们将破损的手稿与被水浸透的发霉的书籍合在一起，复原阴谋之书。复原后的书中记载着召唤地狱猎犬的仪式。",al={"为何需要手稿","地狱猎犬任务书页"}},{q="是谁撕毁了原本的书？",a="无人知晓是谁撕毁了原本的书。铁炉堡的克罗姆·粗臂和幽暗城的约拉·安尼森，都为这部独一无二的学术著作遭到毁坏而痛惜。",al={"谁撕毁了魔典","谁毁坏了阴谋之书"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="塔赞的背包",s="在棘齿城附近，塔赞随身带着一个上锁的背包，与沿岸的海盗做交易。碎手氏族想要得到包里的秘密情报。",h="在棘齿城附近，塔赞随身带着一个上锁的背包，与沿岸的海盗做交易。碎手氏族想要得到包里的秘密情报。",kw={"贫瘠之地","暗影裂口","加摩尔","棘齿城","碎手氏族","塔赞","塔赞的背包","瑟祖克"},ang={["class:Rogue"]="作为一名部落潜行者，你必须取回背包，并从加摩尔身上偷出钥匙，才能在碎手氏族赢得一席之地。",["faction:Horde"]="在奥格瑞玛，碎手氏族寻求暗中的优势，而大酋长萨尔则采取更为审慎的方针。"},sec={{t="贫瘠之地的秘密",b="塔赞与驻扎在棘齿城附近、贫瘠之地沿岸的海盗做交易。瑟祖克是碎手氏族的一位公会首领，身处奥格瑞玛地下的暗影裂口，他注意到了此事。这个公会寻求大酋长萨尔谨慎的外交手段之外的隐秘力量，并将塔赞列为铲除目标，以夺取他背包里的情报。"},{t="复杂的锁",b="背包上的锁让人很难在野外将它打开。塔赞把钥匙交给了同伙加摩尔，后者是奥格瑞玛一家酒馆里常年醉酒的常客。想要取得背包的潜行者必须在不惊动旁人的情况下，从加摩尔的口袋里偷出钥匙，然后才能阅读塔赞的日志。"}},faq={{q="这个背包属于谁？",a="背包属于塔赞，他是一个巨魔，在贫瘠之地的棘齿城附近与海盗做交易。",al={"塔赞是谁","塔赞物主","背包主人"}},{q="碎手氏族为什么想要塔赞的背包？",a="瑟祖克和碎手氏族想要得到塔赞与沿岸海盗交易的情报，以扩展他们的关系网，并在暗影中重拾尚武的自豪。",al={"瑟祖克为何想要这个","碎手氏族背包","为何偷背包"}},{q="打开背包的钥匙在哪里？",a="塔赞把钥匙留给了同伙加摩尔，后者是奥格瑞玛一家酒馆里的醉酒常客。",al={"如何打开背包","塔赞钥匙","钥匙在哪"}},{q="塔赞的背包里有什么？",a="塔赞的日志放在上锁的背包里，详细记载着他的秘密交易以及他与沿岸海盗的联系。",al={"背包内容","包里有什么","塔赞日志"}}},fp="15,130,22.331.0,14.260.1,32.87.0,49.170.0,37.85.1,31.108.1"}
P.entries["item:tear-of-the-moons"] = {n="众月之泪",s="在南贫瘠之地的巴尔莫丹，矮人挖掘者出土了众月之泪。它的奇异力量让费格雷深陷痴迷，而Twinbraid将军则担忧这块水晶会带来什么后果。",h="在南贫瘠之地的巴尔莫丹，矮人挖掘者出土了众月之泪。它的奇异力量让费格雷深陷痴迷，而Twinbraid将军则担忧这块水晶会带来什么后果。",kw={"巴尔莫丹","巴尔丹城堡","贫瘠之地","挖掘","费格雷","众月之泪","穴居人","双辫"},ang={["faction:Horde"]="身为部落的一员，你协助从巴尔丹城堡取回这件遗物，打击了正在侵占牛头人祖地的铁炉堡驻军。",["race:Dwarf"]="身为矮人，费格雷的命运警示着你，巴尔丹远征队正冒险唤醒卡利姆多地下的危险。"},sec={{t="出土的遗物",b="矮人挖掘者在巴尔莫丹最初的挖掘中发现了众月之泪。水晶的奇异光芒令矿工们着迷，尤其是费格雷。他声称水晶赋予了他强大的力量，随后却变得精神失常，与同伴反目。远征队的指挥官Twinbraid将军畏惧这件遗物的影响，断言它受到了诅咒。他拿走水晶，将它锁进巴尔丹城堡中自己的保险箱里。随后，他将费格雷放逐到了贫瘠之地。"},{t="痴迷的代价",b="被放逐的费格雷无法抑制自己对水晶力量的渴望。他请求路过的部落旅人帮忙闯入矮人要塞，从Twinbraid的宝库中取走水晶。费格雷拿到众月之泪并摩挲它时，口中发出了奇怪的咕哝声。水晶从他手中滑落，在地上摔得粉碎。费格雷变成了穴居人，不久便死去了。"}},faq={{q="众月之泪从何而来？",a="矮人勘探员和挖掘者在巴尔莫丹出土了众月之泪，那是南贫瘠之地的一处考古挖掘场。",al={"众月之泪的起源","众月之泪在哪里发现","众月之泪的背景"}},{q="为什么水晶被锁在巴尔丹城堡里？",a="费格雷对水晶日益痴迷，并与矿工同伴反目，塔文布莱德将军因此担心水晶受到了诅咒。他将水晶锁进巴尔丹城堡中的保险箱，以保护远征队。",al={"为什么被锁起来","双辫保险箱中的众月之泪","双辫为什么拿走它"}},{q="费格雷拿回众月之泪后发生了什么？",a="费格雷摩挲着水晶，水晶却从他手中滑落，摔得粉碎。他变成了穴居人，不久便死去了。",al={"费格雷变成穴居人","费格雷发生了什么","穴居人变形费格雷"}},{q="众月之泪能保住或修复吗？",a="费格雷拿回众月之泪时，它摔得粉碎。记载中没有提到后来有人将它修复。",al={"能否保留众月之泪","破碎的众月之泪","修复众月之泪"}}},fp="17,170,17.458.0,22.354.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="蒂罗亚之泪",s="夜色镇附近的蒂罗亚之泪吸引着寻找稀有炼金材料的人。这种花生长在暮色森林的密斯特曼托庄园里。",h="夜色镇附近的蒂罗亚之泪吸引着寻找稀有炼金材料的人。这种花生长在暮色森林的密斯特曼托庄园里。",kw={"贵族的美酒","夜色镇","密斯特曼托","斯塔文","蒂罗亚之泪","蒂罗亚草","维沙克","加尔德斯"},ang={["class:Warlock"]="身为术士，你或许知道蒂罗亚之泪是都城地下从事秘术活动的人所寻找的一种材料。他们用它调制药水，让追查内情的贵族噤声。",["profession:Herbalism"]="身为草药师，你或许能在暮色森林枯败的土地上找到蒂罗亚之泪，那里远离寻常的葱郁田野。"},sec={{t="幽暗中的花园",b="夜色镇外，蒂罗亚之泪生长在斯塔文·密斯特曼托的庄园里。暮色森林的土壤已不再适合正常植物生长，但这种白色小花仍在阴影笼罩的园圃间顽强绽放。它稀少而隐蔽，吸引着那些在合法市场之外寻找稀有材料的人。"},{t="给贵族的药剂",b="在暴风城的街道下方，黑爪加尔德斯正在寻找蒂罗亚之泪，用来调制一剂给维沙克公爵服用的药水。身为贵族的一员，维沙克扬言要调查都城地下的秘密活动。加尔德斯将这种花与来自巨石水坝下方的麝鼠根混合。这剂药水旨在正式调查开始前，分散维沙克的注意力，让他失去行动能力。"}},faq={{q="蒂罗亚之泪生长在哪里？",a="这种花生长在暮色森林夜色镇郊外，密斯特曼托家族庄园那杂草丛生的花园里。",al={"蒂罗亚之泪位置","蒂罗亚之泪在哪里","蒂罗亚地点"}},{q="谁想要蒂罗亚之泪？",a="黑爪加尔德斯在暴风城地下秘密活动，同时也在寻找这种花。他需要用它调制一种特殊的药水。",al={"谁需要蒂罗亚之泪","蒂罗亚之泪任务发布者","谁想要它"}},{q="这种花有什么用途？",a="这种花与麝鼠根混合后可制成药水，用来让维沙克公爵失去行动能力，使他不再呼吁调查都城地下的黑暗勾当。",al={"蒂罗亚之泪用途","蒂罗亚之泪有什么用","贵族药剂花朵"}},{q="维沙克公爵是谁？",a="维沙克公爵是暴风城贵族的一名贵族。得知城内地下的颠覆活动后，他开始敦促议会展开调查。",al={"维沙克","维沙克是谁","维沙克公爵"}}},fx={e7b72a0d={q="蒂罗亚之泪是什么？",a="蒂罗亚之泪是一种纤弱而罕见的白色花朵，生长在暮色森林。它生长在夜色镇郊外无人照料的斯塔文的花园，这株静静绽放的植物蕴含着强大的效力，令远在暴风城地下通道中活动的黑暗法术修习者垂涎。",al={"蒂罗亚之泪是什么","蒂罗亚之泪花朵","蒂罗亚之泪"}},d8c5f010={q="蒂罗亚之泪从何而来？",a="这种花自然生长在杂草丛生的斯塔文的花园，那里位于暮色森林幽暗的林间，就在夜色镇的安全范围之外。它并非出自任何凡人工匠之手，只是在昔日密斯特曼托家宅那片饱经悲剧的庄园中，不受打扰地绽放。",al={"蒂罗亚之泪从何而来","蒂罗亚之泪是谁制作的","蒂罗亚之泪的来历"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="尖端机器人的存储器核心",s="在诺莫瑞根，工匠大师欧沃斯巴克正在寻找尖端机器人的存储器核心，以研究这台自动机械行为失常的原因。",h="在诺莫瑞根，工匠大师欧沃斯巴克正在寻找尖端机器人的存储器核心，以研究这台自动机械行为失常的原因。",kw={"大脑","诺莫瑞根","存储器核心","负电子","欧沃斯巴克","正电子","尖端机器人","侏儒区"},ang={["profession:Engineering"]="身为工程师，你能看出一次短路是如何使尖端机器人的正电子大脑发生极化，并将它的逻辑彻底颠倒的。",["race:Gnome"]="对侏儒而言，尖端机器人是诺莫瑞根陷落的又一个牺牲品。城市的毁灭也葬送了和平时期杰出的工程造物。"},sec={{t="极化的大脑",b="诺莫瑞根陷落之前，尖端机器人用装置和知识协助工匠大师欧沃斯巴克及其他发明家。城市陷落时，一次意外放电击中了尖端机器人，将它的正电子大脑转变为具有敌意的负电子状态。如今，这台自动机械游荡在诺莫瑞根遭到污染的厅堂中，攻击视野中的任何人。欧沃斯巴克希望存储器核心能帮助他弄清故障，让自己的造物恢复理智。"}},faq={{q="尖端机器人的存储器核心是什么？",a="尖端机器人的存储器核心保存着尖端机器人的数据和知识。尖端机器人是工匠大师欧沃斯巴克制造的自动机械，它的核心记录了诺莫瑞根陷落时导致它失常的电流干扰。",al={"尖端机器人的存储器核心","尖端机器人 大脑物品","尖端机器人 的核心是什么"}},{q="谁想要尖端机器人的存储器核心？",a="工匠大师欧沃斯巴克想要尖端机器人的存储器核心。他与其他流亡的侏儒一同在铁炉堡的侏儒区避难。他请求冒险者进入诺莫瑞根，使尖端机器人停止运作并带回核心，以便尝试修复。",al={"谁需要尖端机器人的存储器核心","谁交付 尖端机器人 的核心","尖端机器人 的核心交到哪里"}},{q="尖端机器人为什么会发狂？",a="诺莫瑞根陷落时，一道意外的电火花击中了尖端机器人的正电子大脑。电流激增使其极化，进入负电子状态，将它原本乐于助人的性格和行为协议变得狂暴失控。",al={"尖端机器人 为何具有敌意","尖端机器人 发生了什么","尖端机器人 发狂"}},{q="从哪里获得核心？",a="核心取自尖端机器人，它游荡在诺莫瑞根上层的机械走廊，以及位于丹莫罗的入口处。",al={"哪里获得尖端机器人的存储器核心","尖端机器人 位置","如何获得 尖端机器人 的大脑"}}},fx={a503508b={q="尖端机器人的存储器核心从何而来，是谁制作的？",a="这枚存储器核心来自尖端机器人，那是工匠大师欧沃斯巴克在诺莫瑞根制造的一台复杂机械构造体。欧沃斯巴克设计这台机器，是为了用它储存的无穷数据和小装置协助自己与其他发明家。然而，当诺莫瑞根陷落于穴居人之手时，一股失控的电流冲击了尖端机器人，将它的正电子脑极化为负电子状态，使这台机器陷入了疯狂。",al={"尖端机器人的存储器核心是谁制作的","尖端机器人的来历","谁制造了尖端机器人"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="望远镜片",s="加兹鲁维需要望远镜片，才能完成棘齿城港口上方天文台里的望远镜。南海海盗从一艘船上抢走了它，镜片至今仍在城镇南边的海盗营地里。",h="加兹鲁维需要望远镜片，才能完成棘齿城港口上方天文台里的望远镜。南海海盗从一艘船上抢走了它，镜片至今仍在城镇南边的海盗营地里。",kw={"箱子","加兹鲁维","天文台","棘齿城","南海海盗","被盗的赃物","望远镜片"},ang={["profession:Engineering"]="身为工程师，你能看出这块镜片精湛的光学工艺。远距离观测装置需要它来聚焦，消除球面像差。",["race:Gnome"]="身为侏儒，你或许对地精的火箭技术嗤之以鼻，但加兹鲁维对光学天文学的热忱表明，地精工程学并非只专注于烈性炸药。"},sec={{t="仰望星空",b="棘齿城主要以唯利是图的贸易闻名，但这里的管理者兼首席工程师加兹鲁维，在机械工程上还有更大的抱负。他的天文台耸立在港口上方，里面的望远镜用来观测往来船只和星辰。较大的镜片已从杜隆塔尔经陆路安全运抵。那块较小却至关重要的镜片走的是海路，而南海海盗正在贫瘠之地沿海的商船航线上四处劫掠。"},{t="海盗的掠夺",b="南海海盗袭击运输船时，抢走了所有值钱的东西，包括那些精密的光学器件。海盗可能不懂镜片的精湛工艺，也可能不知道如何将它脱手，于是把它丢在棘齿城南边海滩营地的杂物堆里。加兹鲁维需要有人把这块完好无损的镜片带回来，他的观测台才能看清远方。"}},faq={{q="加兹鲁维为什么需要这块镜片？",a="加兹鲁维需要望远镜片，才能完成棘齿城天文台里的望远镜。较大的镜片已从杜隆塔尔经陆路运抵，但较小的镜片却在海上丢失了。",al={"加兹鲁维镜片","镜片用途","为什么需要望远镜片"}},{q="谁偷走了望远镜片？",a="南海海盗偷走了望远镜片。这群由人类和地精组成的海盗伺机劫掠商旅海岸附近的商船，并把镜片藏在棘齿城南边海岸营地里一个带有标记的箱子中。",al={"谁拿走了镜片","镜片在谁手里","望远镜片位置"}},{q="镜片最初来自哪里？",a="望远镜片是经海路运往棘齿城的，而与它配套的另一块镜片则从杜隆塔尔经陆路运来。运抵这座港口的货物，往往来自无尽之海彼岸，或是藏宝海湾等南方地精领地。",al={"镜片制造地","镜片来源","加兹鲁维在哪里订购镜片"}},{q="镜片被偷走后依然完好无损吗？",a="镜片竟然奇迹般地毫发无损。一个标着“易碎——请勿摔落”的箱子保护了这块精密镜片，使它免遭海盗粗暴搬运的损害。",al={"镜片是否损坏","易碎请勿摔落的箱子"}}},fp="15,186,15.371.0,14.346.0,32.171.0,30.203.0,40.213.0,43.136.0"}
P.entries["item:teronis-journal"] = {n="泰洛尼斯的日记",s="泰洛尼斯的日记记载了一名斥候在灰谷寻找宝石的经历，他希望与宝石有关的那根法杖能减缓熊怪的攻势。",h="泰洛尼斯的日记记载了一名斥候在灰谷寻找宝石的经历，他希望与宝石有关的那根法杖能减缓熊怪的攻势。",kw={"灰谷","阿斯特兰纳","发光的宝石","莱恩·狼行者","莱恩的净化","哨兵","泰洛尼斯","泰洛尼斯的日记"},ang={["faction:Alliance"]="将泰洛尼斯的野外笔记带回阿斯特兰纳，有助于驻军协调援助，并找回这位阵亡斥候的遗体。",["race:NightElf"]="对暗夜精灵而言，泰洛尼斯的日记让人想起斥候们为保护灰谷古老林地免遭腐化侵蚀而面临的危险。"},sec={{t="斥候最后的记录",b="泰洛尼斯是莱恩·狼行者的多年好友，他协助哨兵，在灰谷寻找一颗宝石。他相信这颗宝石是某根法杖的一部分，而那根法杖能够减缓熊怪对他族人的攻势。在岸边附近，凶猛的生物终结了他的旅程。这本日记从他的遗物中被找回，保存得出奇完好。日记记载了一颗光芒四射的宝石曾是那根法杖的一部分，这些发现为阿斯特兰纳的守军提供了线索，让他们能够继续他未竟的搜寻。"}},faq={{q="这本日记属于谁？",a="日记的主人是暗夜精灵泰洛尼斯，他是莱恩·狼行者的多年好友。他在灰谷寻找一颗与某根法杖有关的宝石，相信那根法杖能够减缓熊怪的攻势，却未能带着调查结果归来，便死在了荒野中。",al={"日记是谁写的","泰洛尼斯是谁","泰洛尼斯的故事"}},{q="在哪里能找到这本日记？",a="泰洛尼斯遇害后的遗体在灰谷荒野中被发现，这本日记就在他的遗物之中，地点靠近当地鱼人栖居的岸边。",al={"哪里能找到日记","泰洛尼斯的日记位置","如何获得日记"}},{q="把日记带到阿斯特兰纳有什么目的？",a="将日记交还给莱恩·狼行者，能让阿斯特兰纳得知泰洛尼斯的死讯，也能让哨兵拿到他的笔记，继续寻找那根他寄望能减缓熊怪攻势的法杖。",al={"为何把日记带给莱恩","日记交给谁","日记交付"}},{q="根据任务，泰洛尼斯在寻找什么物品？",a="泰洛尼斯寻找的是一颗发光的宝石，它是已故法师达图尔制作的一根法杖的部件。他的调查表明，这件宝物可能被附近的鱼人拾走了。",al={"泰洛尼斯在寻找什么","他在寻找什么宝石","泰洛尼斯的宝石"}}},fx={["5fb93f8f"]={q="什么是泰洛尼斯的日记？",a="泰洛尼斯的日记是暗夜精灵斥候泰洛尼斯留下的私人笔记。在灰谷，他的遗体旁发现了这本日记和他的其他遗物。日记记载了他的任务，以及他受命寻找一块奇异宝石时最初进行的侦察工作，之后他不幸殒命。",al={"泰洛尼斯的日记是什么","泰洛尼斯的日记物品","关于泰洛尼斯的日记"}}},fp="16,115,22.463.0,31.224.0,27.158.0,57.192.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="萨瑞尔祖恩的头颅",s="萨瑞尔祖恩的头颅被送到湖畔镇，证明那名在赤脊山各条通路上制造恐慌的指挥官已经毙命。他统领着占据石堡的黑石前锋。",h="萨瑞尔祖恩的头颅被送到湖畔镇，证明那名在赤脊山各条通路上制造恐慌的指挥官已经毙命。他统领着占据石堡的黑石前锋。",kw={"黑石前锋","湖畔镇","治安官马瑞斯","石堡","石堡要塞","萨瑞尔祖恩","萨瑞尔祖恩的头颅"},ang={["faction:Alliance"]="每杀死一名黑石酋长，都能减轻湖畔镇的压力。这座饱受围困的小镇没有暴风城的正式援军，只能为生存而战。"},sec={{t="石堡的战利品",b="石堡要塞的黑石兽人袭击农场，伏击路上的旅人，让湖畔镇承受着巨大的压力。萨瑞尔祖恩指挥黑石前锋，带头发动了这些袭击。湖畔镇的驻军不能冒险根据传闻或局部胜利采取行动，因此治安官马瑞斯要求拿出萨瑞尔祖恩已死的证据。他被斩下的头颅表明，黑石前锋从要塞发动的协同伏击遭受了重创。"}},faq={{q="萨瑞尔祖恩是谁？",a="萨瑞尔祖恩是石堡要塞中一名狡诈凶残的黑石兽人指挥官。他统领着黑石前锋，这些兽人与黑石叛节者一起，在湖畔镇和要塞之间不断发动伏击。",al={"萨瑞尔祖恩背景故事","萨瑞尔祖恩是谁","萨瑞尔祖恩首领"}},{q="治安官马瑞斯为什么要他的头颅？",a="暴风城迟迟不向赤脊山提供大规模军事援助，治安官马瑞斯和湖畔镇卫兵只能依靠雇佣兵，逐一铲除主要威胁。马瑞斯需要确凿的证据证明萨瑞尔祖恩已经死亡，才能确定黑石前锋的指挥体系确实已被摧毁。",al={"为何要萨瑞尔祖恩的头颅","马瑞斯头颅证据","马瑞斯悬赏"}},{q="在哪里能找到萨瑞尔祖恩？",a="萨瑞尔祖恩盘踞在赤脊山东部丘陵中的石堡要塞，周围有黑石兽人和豺狼人。",al={"萨瑞尔祖恩位置","萨瑞尔祖恩在哪里","寻找萨瑞尔祖恩"}},{q="取下萨瑞尔祖恩的头颅，就能消除黑石的威胁吗？",a="不能。萨瑞尔祖恩的死亡扰乱了黑石前锋的伏击行动，但黑石氏族仍有大批部队固守在石堡要塞和赤脊山各处。",al={"兽人都走了吗","我们救了赤脊山吗","萨瑞尔祖恩死后"}}},fx={a015b31b={q="什么是萨瑞尔祖恩的头颅？",a="这颗被砍下的头颅证明了萨瑞尔祖恩已被杀死。萨瑞尔祖恩是指挥黑石兽人在石堡要塞周边伏击的首领。它被带回湖畔镇后，向疲惫不堪的镇卫兵表明，赤脊山最危险的黑石氏族前线首领之一再也无法威胁道路了。",al={"萨瑞尔祖恩的头颅物品","萨瑞尔祖恩头颅的背景"}},f673cecf={q="萨瑞尔祖恩的头颅来自哪里？",a="它直接取自萨瑞尔祖恩的尸体。萨瑞尔祖恩是盘踞在石堡要塞废墟中的重要黑石兽人首领。在被你或湖畔镇的守军击败后，它的头颅被取下，作为确凿的战利品和证明其死亡的明证。",al={"谁取下了萨瑞尔祖恩的头颅","萨瑞尔祖恩头颅的来历","萨瑞尔祖恩的头颅来自哪里"}}},fp="17,139,20.381.0,19.185.0,38.234.0,26.121.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="萨纳瑞恩的希望",s="在黑海岸，萨纳瑞恩·绿树正设法研究患病的蓟熊，寻找治愈它们的方法。他的陷阱能让它们暂时平静下来，以便将它们带回营地。",h="在黑海岸，萨纳瑞恩·绿树正设法研究患病的蓟熊，寻找治愈它们的方法。他的陷阱能让它们暂时平静下来，以便将它们带回营地。",kw={"黑海岸","染疫的土地","狂暴的蓟熊","萨纳瑞恩","萨纳瑞恩的希望","蓟熊","陷阱"},ang={["class:Druid"]="身为德鲁伊，你可以将萨纳瑞恩的陷阱看作一种选择：只要受腐化的野兽还有获救的机会，就尽力保全它们的性命。",["race:NightElf"]="身为暗夜精灵，你知道黑海岸的居民十分喜爱蓟熊。蓟熊身染疾病，让萨纳瑞恩的陷阱成为绝境中怜悯之心的象征。"},sec={{t="温和的陷阱",b="萨纳瑞恩·绿树制作了一种能使野兽平静的陷阱，用来研究患病的蓟熊。一种神秘的疾病正在黑海岸蔓延，让动物变得越来越狂躁凶暴。萨纳瑞恩希望治愈它们，不愿看着它们被杀死。将萨纳瑞恩的希望放在地上，它便会散发出抚慰心神的光芒。狂暴的蓟熊经过时，会暂时平静下来，便能跟随旅人回到萨纳瑞恩的营地接受治疗。"},{t="难寻的良方",b="萨纳瑞恩的治疗魔法无法挽救被捕获的蓟熊。陷阱让这头发狂的动物安静下来，没有伤害它，但腐化远比他预想的更为凶险。当他将治疗魔法注入蓟熊体内时，魔法与病变发生了冲突。蓟熊倒地死去。尽管初次尝试以令人心碎的失败告终，萨纳瑞恩仍决心查明森林疾病的真相。"}},faq={{q="萨纳瑞恩的希望有什么作用？",a="萨纳瑞恩的希望能让狂暴的蓟熊暂时平静下来。将它放在林地上，它会释放一片光芒，让旅人能将蓟熊安然带回萨纳瑞恩·绿树身边。",al={"萨纳瑞恩的希望用途","陷阱如何运作","这是什么陷阱"}},{q="萨纳瑞恩为什么要捕获一头活熊？",a="萨纳瑞恩相信，侵袭黑海岸野生动物的疾病可以治愈，无须以杀戮来应对。他需要一头活熊来试验净化的药方。",al={"为什么捕获蓟熊","为什么捕捉狂暴的熊","萨纳瑞恩想要什么"}},{q="陷阱丢失后，还能再领一个吗？",a="可以。萨纳瑞恩说，他的希望永不消逝。如果陷阱被白白触发，或遗失在荒野中，就回去找他再领一个。",al={"萨纳瑞恩的希望丢失","陷阱失效","陷阱消失"}},{q="蓟熊被带回来后会怎样？",a="蓟熊来到萨纳瑞恩身边后，他会施展治疗魔法，试图清除腐化。疾病压垮了这头野兽，它片刻后便死去了。",al={"蓟熊能否存活","萨纳瑞恩能否治愈蓟熊","蓟熊死在萨纳瑞恩身边"}}},fp="17,135,14.402.0,18.413.1,31.184.0,46.168.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="乌尔之书",s="Ur的书如今存放在影牙城堡。Ur死后，大法师阿鲁高取走了它，如今幽暗城的被遗忘者学者也对它产生了兴趣。这位达拉然法师在书中记述了来自其他位面的奇异生物。",h="Ur的书如今存放在影牙城堡。Ur死后，大法师阿鲁高取走了它，如今幽暗城的被遗忘者学者也对它产生了兴趣。这位达拉然法师在书中记述了来自其他位面的奇异生物。",kw={"炼金房","阿鲁高","乌尔之书","达拉然","看守者贝尔杜加","影牙城堡","银松森林","ur"},ang={["class:Mage"]="对法师而言，Ur的著作展现了达拉然学者对其他领域的研究有多深入，也揭示了阿鲁高滥用那些禁忌知识所带来的致命代价。",["race:Undead"]="身为亡灵，取得Ur的研究成果便能帮助炼金房中效忠黑暗女王的学者。一位谨慎的人类巫师留下的研究，或许会成为被遗忘者能够运用的力量。"},sec={{t="达拉然的法师",b="乌尔是一位达拉然法师，以研究其他位面及其中的生物而闻名。在天灾军团到来之前，肯瑞托就已熟知他的研究。乌尔痴迷于这个世界之外的魔法，却选择将发现记录下来，而非鲁莽地突破帷幕。谨慎与克制贯穿了他的研究。当天灾军团进攻达拉然时，无论是魔法还是谨慎，都没能救下他。"},{t="被遗忘者的野心",b="Ur死后，大法师阿鲁高取走了他的著作，并利用其中的知识将狼人召唤到银松森林。如今，这本书就放在影牙城堡的书架上。幽暗城炼金房的看守者贝尔杜加听说了这本书，想要得到Ur的研究成果。被遗忘者没有Ur那样的克制；为了生存与征服，他们会使用危险的魔法。"}},faq={{q="Ur是谁？",a="Ur是达拉然的一位人类法师，在第三次大战之前就以研究其他维度及其中的生物而闻名。他担忧这些生物带来的危险，不愿召唤它们。",al={"乌尔之书是谁写的","ur 达拉然法师"}},{q="乌尔之书在哪里？",a="乌尔之书放在银松森林的影牙城堡内，在巨兽芬鲁斯栖身的房间里的一处书架上。",al={"乌尔之书位置","乌尔之书在哪里"}},{q="看守者贝尔杜加为什么想要这本书？",a="看守者贝尔杜加为幽暗城中对Ur的著作感兴趣的人收集这些著作。被遗忘者认为Ur的良知限制了他的力量，因此打算抛开道德约束，利用他的研究来壮大自身。",al={"看守者贝尔杜加 乌尔之书","幽暗城为什么想要这本书"}},{q="这本书是怎么落到影牙城堡的？",a="乌尔在达拉然陷落时丧生，随后大法师阿鲁高得到了他的研究成果。为了寻找抵御天灾军团的方法，阿鲁高将这些笔记带到银松森林，并利用乌尔的理论将狼人召唤到了艾泽拉斯。",al={"阿鲁高与乌尔之书","阿鲁高如何得到这本书"}}},fx={["62a01830"]={q="什么是乌尔之书？",a="乌尔之书是一部学术典籍，收录了达拉然杰出法师乌尔的奥秘研究。书中详述了他对其他世界和危险奥术现象的深入研究。这些知识力量强大，后来大法师阿鲁高利用乌尔的著作，将可怕的狼人召唤到了银松森林。",al={"乌尔之书是什么","乌尔之书的背景"}},["905bb2c4"]={q="乌尔之书来自哪里？是谁写的？",a="在天灾军团摧毁达拉然后，这本书被留在了这座魔法王国中。此前，法师乌尔曾在达拉然执笔撰写此书，记录他的奥术理论和对其他维度的探索。乌尔在达拉然沦陷期间身亡后，这项研究便被搁置了。",al={"谁写了乌尔之书","乌尔之书的来历","乌尔之书来自哪里"}}},fp="14,174,19.378.0,17.359.1,11.167.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="收货人的交易日程表",s="在布莱克威尔南瓜田附近，收货人的交易日程表记录了非法黄金货物途经艾尔文森林的行程。豺狼人携带着这份手写日程，而治安官杜汉认得上面记载的名字。",h="在布莱克威尔南瓜田附近，收货人的交易日程表记录了非法黄金货物途经艾尔文森林的行程。豺狼人携带着这份手写日程，而治安官杜汉认得上面记载的名字。",kw={"布莱克威尔","收货人","杜汉","艾尔文","黄金","闪金镇","矿井","日程表"},ang={["faction:Alliance"]="身为联盟的一员，当未经许可的采矿队在首都附近攫取资源时，你便能看出暴风城对自身领土的掌控有多么薄弱。",["profession:Mining"]="身为矿工，你能看出艾尔文的矿井并未闲置。富饶的金矿脉正被采空，矿石被运往别处。"},sec={{t="失窃的黄金与秘密货运",b="黄金仍按时从艾尔文的矿井运出，尽管暴风城已有数月未正式开采这些矿井。盗匪的劫掠和怪物的入侵迫使矿工离去。这份日程列明了一个名叫收货人的人接收每批货物的日期和时刻。\n\n线索指向艾尔文森林东部、布莱克威尔南瓜田附近的一处营地。治安官杜汉看到日程表时，认出了收货人的名字。究竟是谁出钱购买这些失窃的黄金，仍无人知晓。"}},faq={{q="收货人的交易日程表是什么？",a="收货人的交易日程表记录了黄金货物何时从艾尔文森林的废弃矿井运出，交给一名叫作收货人的人员。",al={"这张字条是什么","收货人的交易日程表物品","黄金运输日程表"}},{q="日程表从何而来？",a="艾尔文森林河岸和山坡上的豺狼人携带着这份日程表。它们可能从信使手中夺走了它，也可能参与了黄金的运输。",al={"谁掉落日程表","哪里能找到日程表"}},{q="收货人是谁？",a="收货人是一名驻扎在艾尔文森林东部、布莱克威尔南瓜田附近的人员。治安官杜汉认得这个名字，却不知道此人为谁效力。",al={"收货人是谁","收货人的身份"}},{q="为什么这份日程表让治安官杜汉感到不安？",a="治安官杜汉感到不安，是因为暴风城已有数月未派正式矿工在艾尔文的矿井采矿，却仍有大量黄金从中运出。这些货物表明，王国内部有人在有组织地非法采矿。",al={"杜汉为何在意","艾尔文矿井黄金"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="藏尸者的心脏",s="在暮色森林，伊莉莎埋葬于地下的尸体中，有一颗仍在跳动的心脏。藏尸者通过黑暗魔法，将自己的心脏放入亡妻体内，使它成为了自身力量的根基。",h="在暮色森林，伊莉莎埋葬于地下的尸体中，有一颗仍在跳动的心脏。藏尸者通过黑暗魔法，将自己的心脏放入亡妻体内，使它成为了自身力量的根基。",kw={"藏尸者的新娘","夜色镇","暮色森林","伊莉莎","埃伯洛克","藏尸者的心脏","藏尸者"},ang={["class:Warlock"]="身为术士，你能看出，这颗心脏通过血肉塑造与灵魂束缚，维系着死灵魔法赋予的不死状态。",["race:Human"]="身为人类，你听到饱受困扰的暮色森林居民低声谈论着那位善良炼金师的悲惨堕落。"},sec={{t="抗拒死亡的爱",b="夜色镇的传说中，藏尸者曾是一位温和的炼金师。妻子伊莉莎死后，悲痛摧毁了他的理智。他转向邪恶的巫术，挖出自己的心脏，放进她毫无生气的胸膛。魔法使她的尸体化为亡灵，但这次复生却将伊莉莎扭曲成了一头贪婪的怪物，对活人的血肉有着永不满足的渴望。炼金师被自己的所作所为吓坏了，于是再次将她埋葬。"},{t="夜色镇的屏障",b="藏尸者的心脏仍在伊莉莎的坟墓中跳动，维系着他的黑暗力量。埃伯洛克市长相信，夜色镇可以通过消灭藏尸者复生的新娘并夺取心脏，削弱他的巫术。镇上的领袖们希望，若能在心脏仍在跳动时将其取回，就能用它的精华对抗这位死灵法师，并将其化作抵御他所带来恐怖的屏障。"}},faq={{q="为什么伊莉莎体内会有藏尸者的心脏？",a="悲痛驱使藏尸者借助禁忌魔法，将自己仍在跳动的心脏放入伊莉莎的尸体。仪式使她化为亡灵，却也让她对人肉充满了贪婪的渴望。",al={"为什么伊莉莎体内有心脏","伊莉莎体内的藏尸者的心脏","谁把心脏放进伊莉莎体内"}},{q="为什么埃伯洛克市长想把心脏带回夜色镇？",a="埃伯洛克市长希望，心脏中的黑暗魔法能够削弱藏尸者，并化作保护夜色镇的屏障。",al={"为什么艾尔罗想要心脏","埃伯洛克的心脏计划","夜色镇用心脏做什么"}},{q="藏尸者没有心脏，为什么还能活着？",a="藏尸者通过黑暗巫术，将自己的生命力和力量与心脏绑定。心脏仍在他埋葬于地下的妻子遗体中跳动，而他也在没有心脏的情况下存活着。",al={"藏尸者还活着吗","藏尸者没有心脏怎么活着"}},{q="在哪里能找到心脏？",a="心脏就在伊莉莎体内，她被埋在暮色森林一处隐蔽的墓地中。只有直面这位化为亡灵、饥渴难耐的新娘并将其击败，才能取得心脏。",al={"藏尸者的心脏在哪里","伊莉莎的坟墓位置","如何获得藏尸者的心脏"}}},fx={cac9cdef={q="什么是藏尸者的心脏？",a="它就是叛变炼金术师“藏尸者”那颗在魔法维持下仍不断跳动的心脏。藏尸者因妻子伊莉莎之死而悲痛欲狂，挖出自己的心脏并放入她的尸体中，试图让她复生。即便离开了胸腔，这颗心脏仍是他死灵力量的容器和媒介，维持着伊莉莎受诅咒的不死状态，也维系着他自身邪恶的活力。",al={"藏尸者的心脏是什么","藏尸者心脏的背景","藏尸者的心脏"}}},fp="20,173,24.367.0,22.376.1,41.169.0,66.117.0,48.156.0,29.163.0"}
P.entries["item:the-general-s-response"] = {n="将军的回信",s="赤脊山危机当前，马库斯·乔纳森将军回应了湖畔镇的求援。他的回信确认收到了所罗门镇长为抵御黑石兽人和豺狼人而发出的求援，但暴风城暂时不会派出援军。",h="赤脊山危机当前，马库斯·乔纳森将军回应了湖畔镇的求援。他的回信确认收到了所罗门镇长为抵御黑石兽人和豺狼人而发出的求援，但暴风城暂时不会派出援军。",kw={"马库斯·乔纳森将军","湖畔镇","所罗门镇长","前往暴风城的信使","赤脊山","暴风城","将军的回信"},ang={["faction:Alliance"]="暴风城的回应显露出Grand Alliance承受的压力。湖畔镇正在流血，王室却似乎对其困境无动于衷，令人费解。",["race:Human"]="对南方诸王国的人类而言，这封迟来的回信表明，在外省为生存而战的人们与深居暴风要塞的贵族之间，裂痕正日益加深。"},sec={{t="外交僵局",b="所罗门镇长请求暴风城派兵，保卫赤脊山，抵御正在集结的黑石兽人氏族和豺狼人战团。马库斯·乔纳森将军回信说，他已将求援呈报王室，但眼下不会有士兵前来。他命人将信送回湖畔镇。迟迟等不到援军令所罗门镇长忧心忡忡，他怀疑暴风城的领袖出了问题。"}},faq={{q="《将军的回信》中写了什么？",a="马库斯·乔纳森将军哀悼死者，并表示会将湖畔镇的困境禀告国王。他希望能带来援军，还私下透露，国王陛下近来鲜少露面，举止也颇为反常。",al={"信件内容","信里写了什么","将军的信"}},{q="马库斯·乔纳森将军为什么无法向湖畔镇派兵？",a="马库斯·乔纳森将军正在等待国王的答复，才能承诺派出援军。他私下告诉所罗门镇长，国王陛下近来鲜少露面，举止也颇为反常。",al={"为何没有援军","暴风城为何不援助湖畔镇","为何没有援助"}},{q="所罗门镇长对这封信有何反应？",a="这封回信令所罗门镇长深感不安。湖畔镇面临如此险境，暴风城却迟迟没有行动，这让他难以理解。他担心，这种漠视意味着王国内部有更严重的问题。",al={"所罗门镇长的反应","所罗门镇长怎么想","所罗门镇长的回应"}}},fx={["3ebc4cbb"]={q="将军的回信是什么？",a="这是一封加盖封印的正式公函，由暴风城卫兵的指挥官马库斯·乔纳森将军写给赤脊山的所罗门镇长。信使往返于王都和湖畔镇之间，传递这封信函，带来最高指挥部对赤脊山紧急请求王国增援的正式答复。",al={"将军的回信是什么","将军的回信物品","这封信是什么"}},["174955dc"]={q="将军的回信来自哪里，是谁写的？",a="这封信由马库斯·乔纳森将军在暴风城亲笔写成。在英雄谷收到所罗门镇长的紧急请愿后，乔纳森一边等候王廷的消息，一边拟就这封正式回信，托你将它带回湖畔镇，交给镇长。",al={"将军的回信是谁写的","将军的回信来自哪里","将军的回信是谁寄的"}},d0ef00e9={q="为什么有人需要将军的回信？",a="所罗门镇长正焦急地等候这封公函，想知道暴风城是否会派兵，解救遭受黑石兽人和豺狼人威胁的湖畔镇。送达信件，就能让这座饱受围困的城镇的领导者明确知道，王国能够提供哪些援助，又有哪些援助无法提供。",al={"所罗门为什么需要这封信","谁需要将军的回信","为什么要送将军的回信"}}},fp="22,247,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-lich-s-spellbook"] = {n="巫妖的法术书",s="澈水湖岛上的一本法术书引起了比索·埃斯沙德的注意。他希望从书页中了解那位巫妖的本领，以及他生前的身份。",h="澈水湖岛上的一本法术书引起了比索·埃斯沙德的注意。他希望从书页中了解那位巫妖的本领，以及他生前的身份。",kw={"比索·埃斯沙德","澈水湖","冈瑟尔·阿坎努斯","巫妖","死灵法术","法术书","提瑞斯法林地","幽暗城"},ang={["class:Mage"]="身为法师，你能看出这本法术书如何将达拉然的魔法与黑暗的死灵法术结合起来。作者化为亡灵后，法术造诣有了长足的进步。",["race:Undead"]="身为亡灵，你知道有些摆脱巫妖王控制的亡灵并未立即加入被遗忘者。散居在提瑞斯法各地、独自行动的亡灵幸存者仍然彼此猜忌。"},sec={{t="隐居大师的典籍",b="一位拥有自由意志的巫妖与他的骷髅仆从守卫着澈水湖中的一座岛屿。他不信任外界，将其他亡灵误认为天灾军团的奴仆，命令守卫杀死任何靠近的人。比索·埃斯沙德正在为希尔瓦娜斯·风行者女王麾下的被遗忘者寻找技艺精湛的通灵师。他派遣一名使者进入岛上的营地，取走巫妖的法术书。比索希望从书页中了解这位大师的力量，以及他在死亡吞噬洛丹伦之前的身份。"},{t="揭开冈瑟尔·阿坎努斯的身份",b="取回的法术书揭示，这位隐居的巫妖正是冈瑟尔·阿坎努斯，比索·埃斯沙德在第三次大战之前的老友和战友。冈瑟尔生前就是死灵法术奇才，而他的著作表明，化为亡灵后，他的力量变得更加强大。比索知道，冈瑟尔能成为被遗忘者所珍视的黑暗法术大师。但首先，必须有人让这位多疑的巫妖相信，被遗忘者已经摆脱了巫妖王的控制。"}},faq={{q="巫妖的法术书在哪里？",a="法术书放在名为冈瑟尔的书籍的容器中，位于提瑞斯法林地北部澈水湖中央岛屿的营地内。",al={"书在哪里","法术书位置","冈瑟尔的书"}},{q="这本法术书属于谁？",a="这本书属于澈水湖岛上一位拥有自由意志、独自隐居的巫妖。比索·埃斯沙德希望从书页中了解这位巫妖的身份和本领。",al={"这是谁的书","巫妖身份","谁写了法术书"}},{q="比索·埃斯沙德为什么想要这本书？",a="比索·埃斯沙德想查明巫妖的身份，衡量他的死灵法术造诣，希望将他招募到希尔瓦娜斯女士与被遗忘者麾下。",al={"为什么取书","比索任务原因","幽暗城为什么想要这本书"}},{q="巫妖为什么攻击登岛的访客？",a="巫妖认为，附近的其他亡灵仍是受精神控制的天灾军团奴隶。他命令仆从攻击任何靠近他藏身岛屿的人。",al={"冈瑟尔为什么怀有敌意","仆从为什么攻击","澈水湖敌意"}},{q="比索希望了解作者的哪些情况？",a="比索希望查明这位离群索居的巫妖生前是谁，以及他的死灵法术知识能否帮助被遗忘者。",al={"比索会了解到什么","巫妖作者研究","比索法术书研究"}}},fp="20,161,26.483.0,25.432.1,36.140.0,24.154.1,39.145.0,48.149.0,48.117.1"}
P.entries["item:the-state-of-lakeshire"] = {n="湖畔镇的现状",s="在湖畔镇，所罗门镇长的报告请求援助，以免城镇陷落。报告敦促暴风城的马库斯·乔纳森将军派遣王国军队增援，应对赤脊山的危机。",h="在湖畔镇，所罗门镇长的报告请求援助，以免城镇陷落。报告敦促暴风城的马库斯·乔纳森将军派遣王国军队增援，应对赤脊山的危机。",kw={"公文","所罗门镇长","马库斯·乔纳森","赤脊山","援军","报告","湖畔镇的现状","暴风城"},ang={["faction:Alliance"]="对联盟而言，这份报告揭示了边远城镇的处境有多么危险，以及首都的政治拖延如何阻碍军事援助。",["race:Human"]="作为王国的一名人类，传递这份报告让你看到，赤脊山的平民与远在暴风城的王室之间的联系正日渐疏远。"},sec={{t="求援的呼声",b="所罗门镇长在信中描述了威胁湖畔镇的袭击。黑石兽人和豺狼人步步紧逼，镇上的守军无法无限期地守住边界。信使带着他的公文，沿着通往艾尔文森林的道路向西赶去。所罗门请求暴风城军队介入，保护王国的东部疆土。"},{t="官僚作风与僵局",b="马库斯·乔纳森将军在暴风城门口收到了所罗门的报告。他尊重镇长的地位，也明白局势的危险，却无法自行调动军队。调兵需要王室批准，因此湖畔镇的求援必须等到与年轻的国王及摄政王伯瓦尔·弗塔根议事时才能商讨。"}},faq={{q="什么是《湖畔镇的现状》？",a="《湖畔镇的现状》是所罗门镇长提交的正式公文，陈述了湖畔镇面临的军事威胁，并请求暴风城派兵增援。",al={"湖畔镇的现状文件","这是什么报告","所罗门的信"}},{q="这份公文应该交给谁？",a="这份公文应交给马库斯·乔纳森将军。他统领暴风城的城市卫兵和王国部队，驻守在暴风城门口。",al={"谁接收报告","交给谁","马库斯·乔纳森报告"}},{q="湖畔镇为什么需要王国援军？",a="湖畔镇需要王国援军，因为黑石兽人、暗皮豺狼人和当地的鱼人不断围攻镇子，让镇上的卫兵难以招架。",al={"湖畔镇为何陷入危险","什么威胁着赤脊山"}},{q="马库斯·乔纳森将军会立即派出援军吗？",a="不会。马库斯·乔纳森将军承认危机十分严重，但他需要国王的正式批准才能调动军队。这项请求必须先交由王室审议。",al={"暴风城是否援助","乔纳森是否派兵"}}},fx={["629511cc"]={q="湖畔镇的现状来自哪里？是谁写的？",a="湖畔镇的民政首领兼法官所罗门镇长起草了这份重要报告。面对包围城镇的敌对势力不断施压，所罗门亲自写下这份公文，正式说明赤脊山岌岌可危的局势，并请求暴风城最高指挥部立即提供军事援助。",al={"谁写了湖畔镇的现状","谁撰写了湖畔镇的现状","湖畔镇现状报告的作者"}},["09d61feb"]={q="为什么急需湖畔镇的现状报告？",a="湖畔镇一直遭到围困，所罗门镇长知道，没有王室援军，镇子无法独自坚守。马库斯·乔纳森将军需要这份正式报告作为派遣部分暴风城军队的依据，并将湖畔镇的危急处境直接呈报给国王和伯瓦尔·弗塔根公爵。",al={"为什么需要湖畔镇的现状报告","为什么要送交湖畔镇的现状报告","马库斯·乔纳森为什么想要湖畔镇的现状报告"}}},fp="22,188,13.289.0,24.301.0,31.130.0,41.150.0,45.150.0,51.161.0"}
P.entries["item:theramore-medal"] = {n="塞拉摩徽章",s="在北方城堡，塞拉摩徽章是沿商旅海岸守卫这座前哨的海军陆战队员和军官的服役凭证。徽章印有塞拉摩的标志，表明佩戴者隶属联盟驻军。",h="在北方城堡，塞拉摩徽章是沿商旅海岸守卫这座前哨的海军陆战队员和军官的服役凭证。徽章印有塞拉摩的标志，表明佩戴者隶属联盟驻军。",kw={"贫瘠之地","法莫斯队长","商旅海岸","北方城堡","沙罗萨斯·亮阳","塞拉摩徽章"},ang={["faction:Alliance"]="对于效忠联盟的人而言，塞拉摩徽章被当作血腥悬赏的凭证收集，表明卡利姆多边疆的北方城堡已变得多么孤立而好战。",["faction:Horde"]="对于部落冒险者而言，这些徽章证明联盟在贫瘠之地海岸的军事力量正在不断壮大。"},sec={{t="北方城堡的信物",b="驻扎在北方城堡的海军陆战队员、射手、突击队员和军官都携带着压印有塞拉摩标志的徽章。这些士兵效忠于吉安娜·普罗德摩尔的领地。对于驻守在贫瘠之地上方峭壁上的人类部队而言，这些徽章证明他们的服役具有合法性，权力来自塞拉摩。其他人则将这些信物视为从一支过分狂热的外来驻军手中夺取的战利品，这支驻军把每一艘靠近海岸的船都当作致命威胁。"},{t="海盗的复仇",b="北方城堡的炮台威胁着商旅海岸沿线的船只，时常不分私掠船和商船，一并加以炮击。在炮火中损失船只后，棘齿城的私掠船长沙罗萨斯船长开始索求这些徽章。他想要证据，证明北方城堡那些肆意开火的士兵已为击沉他的船只付出血的代价，肇事者已被杀死，偿还了血债。"}},faq={{q="什么是塞拉摩徽章？",a="塞拉摩徽章是驻扎在北方城堡的塞拉摩军人携带的身份标志。它表明持有者是贫瘠之地联盟驻军中的现役海军陆战队员、水手或军官。",al={"塞拉摩徽章","塞拉摩徽章是什么","北方城堡徽章"}},{q="谁携带这些徽章？",a="在商旅海岸沿线，驻扎在北方城堡的海军陆战队员、神射手、甲板水手、突击队员、资深炮手和军官都携带这些徽章。",al={"谁有塞拉摩徽章","谁掉落塞拉摩徽章","塞拉摩徽章的来源"}},{q="沙罗萨斯船长为什么想要这些徽章？",a="北方城堡的火炮曾轰击过往船只，其中包括沙罗萨斯船长麾下舰队的船只。他索要这些徽章，是要以此证明肇事的士兵已被杀死，偿还了血债。",al={"棘齿城为什么要徽章","沙罗萨斯的徽章","为什么收集塞拉摩徽章"}},{q="北方城堡为什么攻击过往船只？",a="北方城堡的驻军位于部落领土边缘，疑神疑鬼。这里的炮手变得鲁莽而好战，几乎任何靠近这片沿海据点的船只都会遭到炮击。",al={"北方城堡为什么炮击船只","北方城堡的侵略行为","北方城堡为什么攻击棘齿城"}}},fp="15,169,20.455.0,16.386.0,26.153.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="厚熊皮",s="在丹莫罗，厚熊皮帮助旅人和士兵抵御山间的严寒。熊在雪原上游荡，它们的毛皮可用来制作保暖的衣物和寝具。",h="在丹莫罗，厚熊皮帮助旅人和士兵抵御山间的严寒。熊在雪原上游荡，它们的毛皮可用来制作保暖的衣物和寝具。",kw={"贝隆·风箱","丹莫罗","灰色洞穴","冰爪熊","贝尔丁","钢架补给站","厚熊皮"},ang={["class:Hunter"]="身为猎人，你学会了穿行于丹莫罗寒冷的灌木丛，追踪危险的山间野兽，并从荒野中收集耐用的材料。",["race:Gnome"]="身为侏儒，你知道钢架补给站里像贝隆·风箱这样的驾驶员，要靠在矮人领地狩猎获取实用物资，才能让他们的机械在长期高山部署中维持适宜生存的条件。"},sec={{t="抵御山间冰霜的温暖",b="熊在丹莫罗的山脊间游荡，穿行于东部王国最严酷的雪原之中。它们厚实的皮毛能抵挡暴风雪，当地居民和旅人也会利用这些毛皮。猎人收集熊皮，为衣物添上衬里，为漏风的哨站保暖，也为冰冷的睡袋加上垫层。"},{t="为攻城坦克旅准备的寝具",b="驾驶员贝隆·风箱在钢架补给站为他的攻城坦克贝尔丁整备物资，准备为攻城坦克旅执行一次长期任务，在野外度过一个月。身处高高的雪堆之间，冰冷的钢铁几乎带不来半点舒适，于是他雇用了当地斥候，前往灰色洞穴以南的雪原收集厚熊皮。这些毛皮将用来为他的舱室制作温暖的寝具。"}},faq={{q="厚熊皮从哪里来？",a="厚熊皮来自丹莫罗的熊，包括小黑熊和冰爪熊。它们在灰色洞穴以南的积雪苔原和松林中捕猎。",al={"哪里获得厚熊皮","谁掉落厚熊皮","熊皮位置"}},{q="驾驶员贝隆·风箱为什么需要这些毛皮？",a="驾驶员贝隆·风箱需要厚熊皮，为他的坦克贝尔丁内部制作温暖的寝具。他正在为随攻城坦克旅执行为期一个月的任务整备坦克，这些寝具将帮助他抵御山间寒冷的夜晚。",al={"贝隆·风箱毛皮","贝隆·风箱为什么需要毛皮","为贝尔丁储备毛皮"}},{q="丹莫罗的哪些生物能提供这种毛皮？",a="小黑熊和冰爪熊都能提供厚熊皮。两者都在丹莫罗高地的积雪间游荡，它们浓密的毛皮可用来制作冬季寝具和保暖用品。",al={"哪些熊掉落毛皮","丹莫罗熊的种类"}}},fx={a2edc513={q="厚熊皮是什么？",a="厚熊皮取自漫游在丹莫罗冰冷峭壁和积雪间的野熊，厚实而保暖。为了在刺骨的严寒与暴风雪中生存，野熊长出了这种致密的皮毛，提供必需的温暖，抵御卡兹莫丹高山间无休止的寒冷。",al={"厚熊皮","这张毛皮是什么","丹莫罗熊皮"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thistlenettle-s-badge"] = {n="希斯耐特的徽章",s="死亡矿井坍塌后，工头希斯耐特只留下了这枚徽章。",h="死亡矿井坍塌后，工头希斯耐特只留下了这枚徽章。",kw={"死亡矿井","探险者协会","月溪镇","我的兄弟","蓟草","希斯耐特的徽章","西部荒野","维尔德"},ang={["faction:Alliance"]="身为联盟的一员，你可以让暴风城矮人区里一名悲痛的矮人了却心事。",["race:Dwarf"]="身为矮人，你知道工头希斯耐特曾带着探险者协会的徽章前往西部荒野。找回它，就能让这位逝去的铁炉堡之子不被遗忘。"},sec={{t="死亡矿井中的探险者协会",b="在迪菲亚潜行者封锁月溪镇及其地下隧道之前，来自铁炉堡探险者协会的矮人勘探者曾在西部荒野的旧金矿中作业。工头希斯耐特和他的矿工们当时正在地下深处，一条隧道突然坍塌，将他们分隔开来。他的兄弟维尔德逃到了暴风城，但工头和几名矿工却被困在了地下。"},{t="悲痛的确证",b="工头希斯耐特死在了尚未封闭的隧道里，随后在主铸造厂外坍塌的矿道间化作了无意识的亡灵。他的探险者协会徽章仍留在身上。找回这枚徽章，将它交给他悲痛的兄弟，便能证实工头的死讯。"}},faq={{q="这枚徽章属于谁？",a="这枚徽章属于工头希斯耐特，他是一名矮人矿工，也是探险者协会的成员。一场突如其来的隧道坍塌将他困在了西部荒野的地下深处。",al={"希斯耐特的徽章原本属于谁","希斯耐特的徽章主人"}},{q="在哪里能找到这枚徽章？",a="工头希斯耐特随身带着这枚徽章，徘徊在死亡矿井怪物横行的上层通道中，就在迪菲亚据点的正门外。",al={"徽章位置","如何获得希斯耐特的徽章","哪里能找到蓟草"}},{q="谁想要希斯耐特的徽章？",a="维尔德·蓟草想要这枚徽章。他是工头的兄弟，住在暴风城的矮人区，等待着亲人的消息。",al={"谁收取希斯耐特的徽章","我的兄弟交给谁","维尔德·蓟草位置"}},{q="蓟草兄弟为何会在死亡矿井？",a="这对兄弟为探险者协会勘测并勘探月溪镇地下矿藏丰富的洞穴。敌对的盗贼和隧道坍塌毁掉了他们的探险。",al={"矮人为何在死亡矿井","蓟草死亡矿井任务"}}},fp="21,84,38.365.0,19.261.1,30.162.0,25.143.0,32.137.0,53.168.0"}
P.entries["item:thresher-eye"] = {n="蛇颈龙的眼球",s="在黑海岸，维兹班恩·曲针需要蛇颈龙的眼球来修理他的传声盒。他用这些眼球修复奥伯丁以北海滩上的传声盒 411。",h="在黑海岸，维兹班恩·曲针需要蛇颈龙的眼球来修理他的传声盒。他用这些眼球修复奥伯丁以北海滩上的传声盒 411。",kw={"奥伯丁","传声盒411","黑海岸","黑海岸蛇颈龙","蛇颈龙的眼球","维兹班恩·曲针"},ang={["profession:Engineering"]="维兹班恩用动物身体部位修复机械中继装置的做法，是侏儒工程学中一个不同寻常的例子。",["race:Gnome"]="维兹班恩·曲针展现了侏儒才智中更为天马行空的一面，在卡利姆多的荒野里，一边喝着crawler wine，一边摆弄野外的机械。"},sec={{t="侏儒装置所需的生态样本",b="黑海岸鱼龙在黑海岸近海的浪涛与浅滩外缘捕猎。它们威胁着当地的渔民和旅人，而它们硕大的眼球引起了维兹班恩·曲针的兴趣。这位侏儒工程师驻扎在附近，喜爱喝蟹肉酒。他需要这些眼球来修理传声盒 411，那是奥伯丁以北海滩上的一台远距离通信机器。"},{t="眼球的用途",b="维兹班恩没有解释，这些黏滑的眼球如何能修好精密的机械。它们或许充当粗糙的透镜、化学试剂，或是生物齿轮。无论原理如何，只要将三颗眼球放入传声盒 411的检修舱，就能恢复它的通信连接，维兹班恩也会伴着充满杂音的通信传送补给。"}},faq={{q="蛇颈龙的眼球从哪里来？",a="蛇颈龙的眼球来自黑海岸近海的黑海岸鱼龙和老年黑海岸鱼龙，尤其是在奥伯丁附近。",al={"蛇颈龙的眼球哪里掉落","如何获得蛇颈龙的眼球","蛇颈龙的眼球来源"}},{q="维兹班恩·曲针为什么需要蛇颈龙的眼球？",a="维兹班恩需要这些眼球来修理传声盒411，那是奥伯丁以北海岸上的一台侏儒机器。将眼球放入舱口，就能恢复机器的各项系统。",al={"为什么需要蛇颈龙的眼球","传声盒 411眼球","蛇颈龙的眼球有什么用"}},{q="眼球怎么能修好机器？",a="维兹班恩·曲针没有解释眼球如何修好机器。这台装置接收眼球后便重新启动，但他究竟是利用视网膜聚焦，还是用其中的有机部分构造部件，仍不清楚。",al={"机器为什么需要眼球","侏儒机器生物部件"}},{q="传声盒 411是什么？",a="传声盒 411是维兹班恩·曲针在黑海岸各处安置的数台通信与监测装置之一。装入所需的材料后，它就能让他远程通信并发放补给。",al={"传声盒 411用途","谁制造了传声盒 411"}}},fp="12,168,38.344.0,23.314.0,33.128.0,48.213.0,30.217.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="图勒的头颅",s="在瑟伯切尔，高级执行官哈德瑞克要求拿出图勒·鸦爪已死的证据。他被斩下的头颅证实，芬里斯岛上的天灾军团部队指挥官已经倒下，也帮助被遗忘者守住银松森林。",h="在瑟伯切尔，高级执行官哈德瑞克要求拿出图勒·鸦爪已死的证据。他被斩下的头颅证实，芬里斯岛上的天灾军团部队指挥官已经倒下，也帮助被遗忘者守住银松森林。",kw={"芬里斯","哈德瑞克","死灵法师","鸦爪","天灾军团","瑟伯切尔","图勒"},ang={["faction:Horde"]="图勒·鸦爪之死稳固了银松森林的东部边界，也保护了部落新近夺取的领土，使其免受Scourge的攻击。",["race:Undead"]="对被遗忘者而言，斩下图勒的头颅既是一场军事胜利，也是对巫妖王掌控洛丹伦的切身复仇。"},sec={{t="芬里斯岛的战利品",b="芬里斯岛是巫妖王在银松森林的主要天灾军团据点。死灵法师图勒·鸦爪在芬里斯城堡指挥腐皮豺狼人和亡灵仆从，威胁着包括瑟伯切尔在内的被遗忘者前哨站。没有图勒被斩下的头颅，高级执行官哈德瑞克就不会接受任何关于他已死的报告。图勒死去时，黑暗魔法涌过林间。他的头颅为哈德瑞克提供了所需的证据，让他得以宣布芬里斯岛的势力已被击溃。"}},faq={{q="谁想要图勒的头颅？",a="高级执行官哈德瑞克在银松森林的瑟伯切尔指挥被遗忘者部队，他要求拿到图勒的头颅，以证明这位天灾军团首领已经死去。",al={"谁需要图勒的头颅","图勒的头颅交给谁","谁收图勒的头颅"}},{q="图勒·鸦爪是谁？",a="图勒·鸦爪是一名强大的死灵法师，统领着芬里斯岛上的天灾军团。他在芬里斯城堡指挥对被遗忘者的进攻，并施展鸦爪之诅等法术。",al={"图勒的故事","图勒是谁","图勒·鸦爪的背景故事"}},{q="为什么被遗忘者一定要他的头颅？",a="被遗忘者不能任由银松森林受到天灾军团的威胁。死灵法师以欺诈和黑暗复生之术而臭名昭著，因此高级执行官哈德瑞克要求拿出图勒已被消灭的实物证据。",al={"为什么要图勒的头颅","为什么要他的头颅"}},{q="图勒·鸦爪被杀死时会发生什么？",a="图勒·鸦爪被杀死时，死亡能量会迸发并席卷这片地区。瑟伯切尔的被遗忘者学者和药剂师在远处也能感受到这股魔法冲击波。",al={"图勒死后会发生什么","图勒释放的能量"}}},fp="12,201,21.432.1,23.152.0,24.198.0,49.193.0,43.163.1"}
P.entries["item:thunder-lizard-blood"] = {n="雷霆蜥蜴的血液",s="在南贫瘠之地，猎人们带回雷霆蜥蜴的血液，证明自己活着完成了狩猎。这些血液来自漫步于平原的巨兽。",h="在南贫瘠之地，猎人们带回雷霆蜥蜴的血液，证明自己活着完成了狩猎。这些血液来自漫步于平原的巨兽。",kw={"贫瘠之地","陶拉祖营地","乔恩·星眼","雷角蜥蜴","雷头蜥蜴","雷霆蜥蜴的血液","雷首蜥蜴"},ang={["class:Hunter"]="身为猎人，你需要站稳脚步、灵活闪避，才能战胜雷霆蜥蜴。取得它的血液，便能证明你有本领制服草原上最庞大的野兽。",["race:Tauren"]="身为来自陶拉祖营地的牛头人猎人，你要面对雷霆蜥蜴，与家乡那些令人敬畏的巨兽一同经历传统的生存考验。"},sec={{t="狩猎的战利品",b="平原上的雷霆蜥蜴有着雷鼻蜥蜴、雷皮蜥蜴和雷首蜥蜴等名称。它们沉重的脚步撼动大地，庞大的身躯足以将疏于防备的猎人踩扁。带回它们的血液，既能展现狩猎的技艺，也能证明猎人有足够的耐力，在它们雷鸣般的脚步下存活。"}},faq={{q="哪些生物能提供这种血液？",a="雷角蜥蜴、雷皮蜥蜴和雷首蜥蜴都能提供这种血液。这些成年的雷霆蜥蜴漫步于南贫瘠之地陶拉祖营地周围的草原。",al={"谁掉落雷霆蜥蜴的血液","哪里获取雷霆蜥蜴的血液","哪些雷霆蜥蜴"}},{q="为什么要收集雷霆蜥蜴的血液？",a="陶拉祖营地的乔恩·星眼要求猎人收集这些血液，作为遍及贫瘠之地的一系列试炼的一部分。能够安然无恙地带回血液，就证明猎人有能力面对卡利姆多体型最庞大、足以将人踩扁的巨兽。",al={"谁需要雷霆蜥蜴的血液","雷霆蜥蜴的血液用途"}},{q="这些雷霆蜥蜴通常在哪里出没？",a="雷霆蜥蜴漫步于陶拉祖营地北面、东面和南面的草原，与南贫瘠之地的其他大型动物一同觅食。",al={"雷霆蜥蜴位置","雷角蜥蜴在哪里"}}},fp="20,118,18.304.0,34.152.0,41.186.0,46.152.0"}
P.entries["item:thunder-lizard-horn"] = {n="雷霆蜥蜴的角",s="在贫瘠之地，酿酒师德罗恩正在寻找雷霆蜥蜴的角，用来酿造老陈闻名遐迩的美酒。",h="在贫瘠之地，酿酒师德罗恩正在寻找雷霆蜥蜴的角，用来酿造老陈闻名遐迩的美酒。",kw={"贫瘠之地","酿酒师德罗恩","老陈","奥瓦坦卡","棘齿城","雷头蜥蜴","风暴烈酒","雷霆蜥蜴的角","雷首蜥蜴"},ang={["class:Hunter"]="身为猎人，你在开阔的草原上追踪雷霆蜥蜴时要格外小心。它们释放的闪电使其比贫瘠之地常见的科多兽或陆行鸟更加致命。",["profession:Cooking"]="身为厨师，你可能会觉得德罗恩的配方很不寻常：它将陆行鸟的内脏、掠食野兽的獠牙和野兽的角混合在一起，酿成令人陶醉的酒。"},sec={{t="强效酿酒原料",b="雷霆蜥蜴游荡在贫瘠之地，带有脊冠的身躯上电光噼啪作响。棘齿城的酿酒师德罗恩十分看重它们的角，将其用作酿造风暴烈酒麦酒的原料。他的导师从云游四方的熊猫人酿酒师老陈那里学会了配方，又将它传给了德罗恩。蜥蜴角赋予了这种酒强劲的烈性。"}},faq={{q="这种角有什么用途？",a="棘齿城的酿酒师德罗恩用这种角作原料，酿造因老陈而闻名的美酒。",al={"雷霆蜥蜴的角用途","什么会用到雷霆蜥蜴的角","为什么需要雷霆蜥蜴的角"}},{q="哪些野兽会掉落雷霆蜥蜴的角？",a="雷首蜥蜴、雷角蜥蜴、雷蹄蜥蜴、雷皮蜥蜴，以及行踪难觅的奥瓦坦卡，都可能掉落雷霆蜥蜴的角。",al={"哪里能获得雷霆蜥蜴的角","谁掉落雷霆蜥蜴的角","雷霆蜥蜴的角来源"}},{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩在棘齿城酿酒。他从前的导师从老陈那里学会了风暴烈酒的配方，又将它传授给了他。",al={"德罗恩是谁","酿酒师德罗恩的故事","德罗恩 棘齿城"}},{q="为了取角而猎杀雷霆蜥蜴危险吗？",a="雷霆蜥蜴受到激怒时，会释放闪电，发出雷鸣般的践踏，因此独自猎杀它们十分危险。",al={"雷霆蜥蜴有多难对付","猎杀雷霆蜥蜴"}}},fp="19,98,24.297.0,26.82.0,41.111.0,24.130.0,54.117.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="雷鹰的唾液腺",s="在贫瘠之地各处，大雷鹰体内的腺体深受酿酒师德罗恩珍视。他需要用它来重现老陈风暴烈酒那火辣的洞穴麦酒。",h="在贫瘠之地各处，大雷鹰体内的腺体深受酿酒师德罗恩珍视。他需要用它来重现老陈风暴烈酒那火辣的洞穴麦酒。",kw={"贫瘠之地","德罗恩","腺体","酒桶","棘齿城","唾液","雷鹰","洞穴麦酒"},ang={["faction:Horde"]="身为部落的一员，你在游历卡利姆多时，可以猎杀遍布贫瘠之地的凶猛雷鹰，证明自己的实力。",["profession:Cooking"]="身为厨师，你或许不愿使用唾液腺，但富有创意的酿酒师却十分珍视奇异动物精华所带来的浓烈风味与效力。"},sec={{t="荒野中的原料",b="大雷鹰在贫瘠之地干旱的草原上四处猎食。这些长着翅膀的蛇类以驾驭风暴而闻名，其中年岁更长、也更危险的个体会生出蕴含天然力量的唾液腺。旅人对这些致命的野兽敬而远之，酿酒师却将这种腺体视为酿制奇异饮品的珍稀基料。"},{t="老陈的秘密酒方",b="老陈风暴烈酒游历卡利姆多之后，酿酒师德罗恩在棘齿城外定居。德罗恩研究这位游历四方的酿酒师所用的发酵方法，需要新鲜的雷鹰的唾液腺、雷皮蜥蜴的闪电腺和科多兽的肝脏来酿制洞穴麦酒。这种火辣的烈酒后劲十足，是为强健冒险者的体魄而酿。"}},faq={{q="在哪里能找到雷鹰的唾液腺？",a="大雷鹰在贫瘠之地开阔的草原上猎食，它们的唾液腺也在那里采集。",al={"雷鹰的唾液腺掉落","唾液腺哪里获取","雷鹰腺体位置"}},{q="唾液腺有什么用途？",a="棘齿城外的酿酒师德罗恩需要这种腺体来酿制洞穴麦酒，这种烈酒的配方是老陈风暴烈酒留下的。",al={"唾液腺用途","雷鹰的唾液腺有什么用","雷鹰唾液用途"}},{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩住在棘齿城港口附近。他向四处游历的旅人老陈风暴烈酒学会了奇异的酿酒技艺，并用烈性麦酒与冒险者交易，换取他们冒险从当地野兽身上取得的原料。",al={"德罗恩 棘齿城","德罗恩是谁","酿酒师德罗恩背景故事"}},{q="洞穴麦酒是什么？",a="老陈风暴烈酒构思洞穴麦酒时，便打算将它酿成一种极为烈性的饮品。酿酒师德罗恩用大雷鹰的唾液腺、闪电腺和科多兽的肝脏来酿制它。",al={"洞穴麦酒背景故事","洞穴麦酒是什么","老陈的洞穴麦酒"}}},fp="24,125,17.286.0,21.332.0,45.104.0,34.112.0,24.197.0,18.166.0"}
P.entries["item:thunderhawk-wings"] = {n="雷鹰的翅膀",s="在贫瘠之地中部和南部，猎人从翱翔于头顶的风蛇身上夺取雷鹰的翅膀。在陶拉祖营地，乔恩·星眼收下这些翅膀，作为猎人力量、智谋与耐力的证明。",h="在贫瘠之地中部和南部，猎人从翱翔于头顶的风蛇身上夺取雷鹰的翅膀。在陶拉祖营地，乔恩·星眼收下这些翅膀，作为猎人力量、智谋与耐力的证明。",kw={"贫瘠之地","陶拉祖营地","乔恩·星眼","瑟格拉·黑棘","雷鹰","风蛇","翅膀"},ang={["class:Hunter"]="身为猎人，夺取翱翔于空中的thunderhawk的翅膀，是成长道路上的一道试炼。面对这些迅捷的空中野兽，你的追踪本领、耐心与射术都将受到考验。",["race:Tauren"]="身为牛头人，你通过收取这些翅膀，向草原之灵致敬，并对Earthmother麾下的凶猛生灵表达敬意。"},sec={{t="狩猎的战利品",b="驻扎在陶拉祖营地的猎人珍视一对完整的雷鹰的翅膀。风蛇被当地猎人称为雷鹰，是凶猛的有翼爬行动物，会从空中迅速发动攻击。在开阔的平原上追踪它们，并在战斗中夺取它们的翅膀，考验着猎人的技艺。对于初学者而言，带回这些翅膀，便证明自己已准备好踏上成为出色猎人的毕生之路。"}},faq={{q="在哪里能找到雷鹰的翅膀？",a="雷鹰的翅膀来自盘旋在贫瘠之地中部和南部山脊与平原上空的雷鹰，尤其是陶拉祖营地周围。",al={"哪里获取翅膀","雷鹰的翅膀位置","如何获取雷鹰的翅膀"}},{q="谁需要这些翅膀？",a="乔恩·星眼是一位驻扎在陶拉祖营地的老练牛头人猎人，他要求初学者带来这些翅膀，以证明自己已掌握草原上的狩猎仪式。",al={"谁收雷鹰的翅膀","交付雷鹰的翅膀","乔恩·星眼翅膀"}},{q="夺取这些翅膀意味着什么？",a="将这些翅膀带给乔恩·星眼，就完成了一项艰难的试炼。这表明猎人拥有面对凶猛空中掠食者所需的力量、勇气与耐心。",al={"为何猎杀雷鹰","翅膀用途","猎杀雷鹰的意义"}}},fp="17,133,18.340.0,34.144.0,22.144.0,37.168.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="雷角之井净化图腾",s="穆尔·雷角在血蹄村准备雷角之井净化图腾。图腾中的先祖魔法将用于净化雷角水井。",h="穆尔·雷角在血蹄村准备雷角之井净化图腾。图腾中的先祖魔法将用于净化雷角水井。",kw={"血蹄","净化","莫高雷","穆尔","仪式","雷角","图腾","水井"},ang={["class:Shaman"]="身为萨满祭司，你知道净化图腾可以安抚躁动的自然之灵，让元素能量变得狂暴的地方恢复平衡。",["race:Tauren"]="身为牛头人，你肩负着神圣的职责，要为Earth Mother和守护莫高雷的氏族先祖净化先祖水井。"},sec={{t="净化雷角水井",b="穆尔·雷角在血蹄村将准备好的图腾托付给旅人。他们带着图腾向北前往雷角氏族的圣泉，邪恶之徒已污染了那里的泉水。牛头人部族挖掘的先祖水井滋养着他们的兽群和猎场。通过仪式中的祈唤，图腾安抚水中躁动的灵魂，并净化这片土地。"}},faq={{q="雷角之井净化图腾有什么用途？",a="这根图腾是为净化血蹄村北面受到污染的雷角水井而准备的。使用它可以驱散毒害水井的邪恶力量，也能让守护水井的先祖之灵感到欣慰。",al={"图腾有什么作用","为何使用雷角图腾","净化图腾的用途"}},{q="是谁制作了这根图腾？",a="穆尔·雷角制作并授予这根图腾。这位长者住在血蹄村，守护着这片土地的生机，并与先祖沟通。",al={"谁制作了这根图腾","谁给予雷角图腾","穆尔·雷角的图腾"}},{q="必须在哪里使用图腾？",a="在雷角水井使用图腾，水井位于莫高雷中部、血蹄村以北。",al={"图腾在哪里使用","图腾位置","雷角水井在哪里"}},{q="仪式完成后会发生什么？",a="净化水井能让雷角氏族的先祖之灵获得安宁。穆尔·雷角在梦中见到他们向净化这片土地的人表达感激与赞许，并赐予先祖的礼物。",al={"净化水井之后","仪式结果","先祖的反应"}}},fp="27,151,30.355.0,55.217.0,22.153.0,29.91.0,43.188.1"}
P.entries["item:thurman-s-remains"] = {n="萨尔曼的遗骸",s="在阿加曼德磨坊，萨尔曼的遗骸见证了这个家族抵抗天灾军团的失败。那位曾经富有的磨坊主死于瘟疫，如今沦为亡灵奴仆，在自己破败的庄园中游荡。",h="在阿加曼德磨坊，萨尔曼的遗骸见证了这个家族抵抗天灾军团的失败。那位曾经富有的磨坊主死于瘟疫，如今沦为亡灵奴仆，在自己破败的庄园中游荡。",kw={"阿加曼德","阿加曼德磨坊","库勒曼·法席恩","家族中的死亡","萨尔曼·阿加曼德","萨尔曼的遗骸","提瑞斯法林地"},ang={["race:Undead"]="身为被遗忘者，你取回这些遗骸，向那些贵族主人清算旧账，正是他们的狂妄让工人落入了Scourge的魔掌。"},sec={{t="破败的遗产",b="第三次大战之前，阿加曼德家族是提瑞斯法林地最富有的地主，拥有大片磨坊，雇用了数十名当地工人。当天灾军团席卷洛丹伦时，萨尔曼·阿加曼德和他的亲族没有逃离，而是加固了庄园。他们坚信自己的财富和坚固的磨坊足以抵挡进攻，便说服忠心的工人拿起武器，与他们并肩作战。防守失败了。阿加曼德家族及其工人惨遭屠杀，沦为巫妖王没有心智的仆从。库勒曼·法席恩曾是这里的工人，死后复生成为被遗忘者，如今要求消灭从前的主人。他要取得萨尔曼的遗骸，以此证明这个愚蠢的家长已为葬送全家付出代价。"}},faq={{q="萨尔曼·阿加曼德生前是谁？",a="萨尔曼·阿加曼德出身于富有的阿加曼德家族，这个家族拥有提瑞斯法林地北部的阿加曼德磨坊。当天灾军团进攻洛丹伦时，他因傲慢而说服工人留下战斗。庄园里的所有人都遭到屠杀，随后又被复生。",al={"萨尔曼·阿加曼德","萨尔曼是谁","萨尔曼生前是谁"}},{q="库勒曼·法席恩为什么想要萨尔曼的遗骸？",a="库勒曼·法席恩曾是一名磨坊工人，他信任阿加曼德家族，并在保卫他们的庄园时丧命。如今他已成为被遗忘者的一员，想要取得萨尔曼的遗骸，向那些害工人沦为亡灵的雇主复仇。",al={"库勒曼为何想要遗骸","库勒曼·法席恩的动机","为何杀死萨尔曼"}},{q="萨尔曼被消灭时还有自由意志吗？",a="没有。萨尔曼·阿加曼德死后一直受到天灾军团的精神控制，与幽暗城的被遗忘者不同。他作为没有思想的爪牙效命，直到在磨坊被消灭。",al={"萨尔曼有自由意志吗","萨尔曼曾属于天灾军团吗","萨尔曼是被遗忘者吗"}},{q="阿加曼德家族还有谁被列为目标？",a="除了萨尔曼，库勒曼·法席恩还想消灭格里高·阿加曼德和妮萨·阿加曼德，并取回他们的遗骸，终结这个曾经统治磨坊的家族血脉。",al={"其他阿加曼德家族成员","阿加曼德家族成员","家族墓穴的目标"}}},fp="17,207,16.697.0,24.260.0,49.216.0,49.188.0,51.171.0"}
P.entries["item:thurman-s-sewing-kit"] = {n="萨尔曼的针线包",s="拉尔森服装店当天的裁缝活需要用到萨尔曼的针线包。年轻的学徒萨尔曼·斯涅德把它留在了运河旁的家中，盼着悠闲地度过一天。",h="拉尔森服装店当天的裁缝活需要用到萨尔曼的针线包。年轻的学徒萨尔曼·斯涅德把它留在了运河旁的家中，盼着悠闲地度过一天。",kw={"拉尔森服装店","法师区","雷玛·施涅德","针线包","暴风城运河","萨尔曼·斯涅德","萨尔曼的针线包"},ang={["profession:Tailoring"]="每个裁缝都知道，初当学徒时的活计有多枯燥。但很少有人会像年轻的萨尔曼·斯涅德那样，干脆把剪刀留在家里。"},sec={{t="不情愿的学徒的工具",b="萨尔曼的针线包里装着他做裁缝活所需的针、剪刀和线。年轻的萨尔曼在拉尔森服装店学习手艺，店铺位于暴风城的法师区深处，靠近法师塔。他的母亲雷玛·施涅德知道，没有针线包，他就没法干活。于是，她请运河沿岸的路人把针线包送到店里。萨尔曼拿到工具时的反应，暴露了他是故意把工具留在家里的。他原本盼着能免去一天缝制衣物的劳作，享享清闲。"}},faq={{q="萨尔曼的针线包里有什么？",a="针线包里装着针、剪刀和线，供萨尔曼·斯涅德在拉尔森服装店做裁缝活时使用。",al={"针线包里有什么","针线包的内容","萨尔曼的剪刀"}},{q="这个针线包属于谁？",a="萨尔曼的针线包属于萨尔曼·斯涅德，他是暴风城法师区里跟随拉尔森学习手艺的年轻学徒。",al={"针线包属于谁","萨尔曼针线包主人","萨尔曼是谁"}},{q="针线包为什么被留在了萨尔曼家里？",a="雷玛以为萨尔曼匆忙出门，忘了带针线包。他其实是故意把它留在家里的，盼着能躲过在拉尔森服装店干活的一天。",al={"萨尔曼为什么忘带针线包","萨尔曼是故意忘带的吗","为什么留下针线包"}},{q="这个针线包需要送到哪里？",a="把针线包送到暴风城法师区的拉尔森服装店，店铺就在法师塔附近。",al={"针线包送到哪里","拉尔森服装店位置","萨尔曼位置"}}},fx={["128c9147"]={q="雷玛·施涅德为什么希望有人送去萨尔曼的针线包？",a="萨尔曼是法师区的拉尔森服装店的一名裁缝学徒。他的母亲雷玛·施涅德请你送去针线包，好让他完成每天的裁缝工作。然而，萨尔曼其实是故意偷偷留下工具，希望借此逃避杂务，偷懒一天。",al={"为什么要送萨尔曼的针线包","萨尔曼为什么需要他的针线包","为什么需要针线包"}}},fp="20,191,30.450.0,36.101.0,35.124.0,46.139.0,41.87.0"}
P.entries["item:timberling-seed"] = {n="林精的种子",s="在泰达希尔各地，人们从变得充满敌意的植物之灵身上采集林精的种子。博物学家和德鲁伊研究这些种子，探寻森林中的植物变得凶暴的原因。",h="在泰达希尔各地，人们从变得充满敌意的植物之灵身上采集林精的种子。博物学家和德鲁伊研究这些种子，探寻森林中的植物变得凶暴的原因。",kw={"腐化","达纳苏斯","德纳兰","奥拉密斯湖","雷利亚·绿树","泰达希尔","林精","林精的种子"},ang={["class:Druid"]="身为德鲁伊，你能从这些受污染的种子中看出早期警兆：非自然的腐化正在泰达希尔的植物元素生物间蔓延，这令塞纳里奥区的守护者深感忧虑。",["profession:Herbalism"]="身为草药师，你可以研究这些种子，了解土壤状况和周围的腐化如何影响野生植物。"},sec={{t="躁动森林的种子",b="林精是泰达希尔的自然元素生物，它们的性情反映着世界之树的平衡状况。近来，它们变得暴躁而充满敌意，困扰着照料枝干的暗夜精灵。奥拉密斯湖畔的德纳兰等草药师怀疑土壤出了问题。他们采集野生林精的种子，希望经过净化和悉心照料的土壤能让温顺的后代萌发生长。"},{t="根深蒂固的腐化",b="野生林精的种子带有来自受腐化亲代的污染。达纳苏斯的雷利亚·绿树等塞纳里奥学者发现，问题远不止生长不良那么简单。腐化已在泰达希尔的植物之灵间蔓延，并侵入了这棵巨树的整个生态系统。"}},faq={{q="什么是林精的种子？",a="林精的种子是林精用来繁衍的种仁，林精是一种遍布泰达希尔、形似植物的自然元素生物。博物学家采集这些种子，以研究林精的生长与生态。",al={"林精的种子","什么是林精的种子"}},{q="这些种子在哪里采集？",a="奥拉密斯湖沿岸和浅水区的野生林精与沼泽兽身上都能采集到这些种子。",al={"哪里获取种子","林精的种子掉落","谁掉落林精的种子"}},{q="德纳兰为什么需要林精的种子？",a="德纳兰怀疑贫瘠的土壤使林精陷入狂怒。他希望经过特殊调配的土壤能让野生种子萌发，长成温顺、未受腐化的林精。",al={"德纳兰的目的","为什么收集种子","德纳兰的计划"}},{q="雷利亚·绿树对这些种子有何发现？",a="雷利亚发现，这些种子带有来自受腐化亲代的污染。他无力消除这种腐化，希望只能寄托在德纳兰的园艺实验上。",al={"雷利亚的种子研究","雷利亚发现了什么","种子是否受到污染"}}},fp="15,176,26.377.0,19.278.1,26.185.0,31.97.0,39.156.0,54.168.1"}
P.entries["item:timberling-sprout"] = {n="林精的新芽",s="在奥拉密斯湖畔，林精的新芽刚扎根便已受到腐化。暗夜精灵看守者会在它们长成好斗的林精之前将其拔除。",h="在奥拉密斯湖畔，林精的新芽刚扎根便已受到腐化。暗夜精灵看守者会在它们长成好斗的林精之前将其拔除。",kw={"奥达希尔","腐化","奥拉密斯湖","幽影谷","泰达希尔","林精","林精的新芽"},ang={["class:Druid"]="作为一名与卡利姆多的植物和元素生物心意相通的德鲁伊，你或许会将林地之灵诞生时便已受到腐化的景象，视为泰达希尔未来的不祥之兆。",["race:NightElf"]="作为一名在幽影谷受训的年轻暗夜精灵，你受命清除这些新芽，守护你新的林地家园。"},sec={{t="染病的幼苗",b="林精是与泰达希尔的自然生命力紧密相连的植物之灵。在奥拉密斯湖畔，暗夜精灵发现，有些幼苗萌发时便已受到污染，充满攻击性，而非健康地生长，与荒野和谐共存。这些新芽似乎已无法净化，也无法自然痊愈，因此照料者会将它们收集起来并销毁。他们希望阻止这些充满敌意的林精在新栽种的世界之树脆弱的枝干上蔓延。"}},faq={{q="哪里能找到林精的新芽？",a="林精的新芽生长在泰达希尔的多兰纳尔以南，靠近奥拉密斯湖水边的地方。",al={"新芽位置","林精的新芽在哪里","寻找新芽"}},{q="暗夜精灵为什么要从地里拔除林精的新芽？",a="这些新芽萌发时便已受到污染。若放任不管，它们就会长成凶暴的林精，威胁泰达希尔的安全与平衡。照料者认为它们已无可救治，因此趁它们尚小时就将其拔除。",al={"为什么杀死新芽","林精的新芽用途","为什么销毁新芽"}},{q="是什么导致这些新芽受到污染？",a="一种神秘的疾病正影响着泰达希尔的野生动物和植物元素生物。植物学家德纳兰尚不清楚病源，但它会从幼小的林精扎根的那一刻起侵染它们。",al={"林精为什么受到腐化","是什么在污染它们","新芽疾病"}},{q="是谁要求收集林精的新芽？",a="照料奥拉密斯湖的植物学家德纳兰请冒险者收集这些新芽，将它们从湖畔清除，以保持这片土地的纯净。",al={"谁需要新芽","新芽任务给予者","林精的新芽交付"}}},fp="17,136,18.399.0,35.99.0,63.206.0,46.180.0,48.139.0"}
P.entries["item:tirisfal-pumpkin"] = {n="提瑞斯法南瓜",s="在索利丹农场，活着的人类仍在饱受枯萎侵蚀的提瑞斯法种植南瓜。被遗忘者夺走这些南瓜，用于皇家药剂师学会的混合药剂。",h="在索利丹农场，活着的人类仍在饱受枯萎侵蚀的提瑞斯法种植南瓜。被遗忘者夺走这些南瓜，用于皇家药剂师学会的混合药剂。",kw={"药剂师乔汉","布瑞尔","亡灵卫兵希米尔","悲伤之地","南瓜","试剂","索利丹农场","提瑞斯法南瓜"},ang={["faction:Alliance"]="身为联盟的一员，你看到索利丹农场的南瓜，便会想到洛丹伦的幸存者正在被遗忘者的袭扰中设法养活自己。",["race:Undead"]="身为亡灵，你袭击索利丹农场，既是为了夺走活人的食物，也是为了给药剂师乔汉提供被遗忘者研究所需的材料。"},sec={{t="荒芜之地的收成",b="布瑞尔以西，尽管腐化正在洛丹伦蔓延，庄稼依然生长。在索利丹农场，活着的人类农夫在附近血色十字军的监视下耕种土地，种出硕大的橙色南瓜。收成养活着这些农夫。对布瑞尔的被遗忘者而言，这些南瓜既是破坏的目标，也是药剂师乔汉所需的原料。"},{t="炼金试剂",b="亡灵卫兵希米尔派新近加入的被遗忘者前往双方争夺的田地，在农夫眼皮底下偷走南瓜。这些蔬菜并非亡者的食物，而是要投入皇家药剂师学会的大锅中。药剂师们测试天然植物对瘟疫和实验性混合药剂的反应，利用洛丹伦仅存的庄稼对付活人。"}},faq={{q="哪里能找到提瑞斯法南瓜？",a="它们生长在提瑞斯法林地的索利丹农场，位于布瑞尔以西、丧钟镇正北方不远处。",al={"南瓜位置","南瓜在哪里","索利丹农场南瓜"}},{q="被遗忘者为什么想要这些南瓜？",a="亡灵卫兵希米尔下令偷走南瓜，让幸存的人类和血色十字军无法获得它们，再将它们送给布瑞尔的药剂师乔汉，作为药剂研究的原料。",al={"为什么偷南瓜","乔汉南瓜","南瓜有什么用"}},{q="玩家能食用提瑞斯法南瓜或用它们烹饪吗？",a="不能。皇家药剂师学会收集它们用于混合药剂，冒险者不会用它们烹饪。",al={"提瑞斯法南瓜能吃吗","南瓜烹饪材料"}},{q="现在是谁在种植这些南瓜？",a="活着的人类农夫仍在索利丹农场耕种，附近哨塔中的血色十字军为他们提供有限的保护。",al={"农场归谁所有","索利丹农夫"}}},fp="16,155,26.337.0,19.344.0,37.95.0,42.188.0,47.108.0,30.128.0"}
P.entries["item:token-of-thievery"] = {n="偷窃技能证明物",s="在赤脊山，盗贼们要在奥瑟尔伐木场接受卢修斯设下的考验。一只上锁的箱子里放着偷窃技能证明物，盗贼们要在训练中取回它，以证明自己的技艺。",h="在赤脊山，盗贼们要在奥瑟尔伐木场接受卢修斯设下的考验。一只上锁的箱子里放着偷窃技能证明物，盗贼们要在训练中取回它，以证明自己的技艺。",kw={"奥瑟尔伐木场","偷窃技能认证书","湖畔镇","开锁","卢修斯","赤脊山","盗贼工具","偷窃技能证明物"},ang={["class:Rogue"]="身为盗贼，你要从受黑石兽人威胁的废墟中取回偷窃技能证明物，以证明自己使用开锁工具的技艺。"},sec={{t="巧手的考验",b="在湖畔镇，卢修斯让有潜力的盗贼接受实地考验。他将偷窃技能证明物藏在奥瑟尔伐木场废墟中一只上锁的箱子里，那里有黑石兽人出没，威胁着周边地区。取回证明物的过程，将考验新手能否在性命攸关的险境中开锁。成功者将获得偷窃技能认证书。"}},faq={{q="偷窃技能证明物是什么？",a="卢修斯将偷窃技能证明物锁在奥瑟尔伐木场的一只箱子里。盗贼新手必须在危险中打开箱锁，证明自己的技艺。",al={"偷窃技能证明物用途","偷窃技能证明物是什么","卢修斯的证明物"}},{q="是谁把证明物放进锁箱的？",a="卢修斯是湖畔镇一位经验丰富的盗贼导师，他将证明物放进箱子里，作为年轻盗贼训练的一部分。",al={"证明物属于谁","卢修斯锁箱主人","谁藏了证明物"}},{q="为什么把箱子放在奥瑟尔伐木场？",a="从湖畔镇沿路而上便是奥瑟尔伐木场，四处游荡的黑石兽人让那里危机四伏。卢修斯派学徒前往那里，在敌人的地盘上迅速而悄无声息地开锁。",al={"为什么是奥瑟尔伐木场","伐木场放置锁箱的原因","伐木场的危险"}},{q="证明物能换来什么？",a="将证明物交还给卢修斯后，盗贼便能获得偷窃技能认证书，证明自己完成了开锁的基础训练。",al={"证明物奖励","卢修斯给什么","偷窃技能认证书"}}},fp="17,148,17.285.0,30.136.0,34.105.0,41.158.0,46.122.0"}
P.entries["item:tome-of-the-cabal-quest-item"] = {n="阴谋之书",s="棘齿城的术士收集好危险的材料后，会从斯坦哈德·法尔杉那里获得阴谋之书。书中记载着将地狱猎犬从扭曲虚空召来并加以束缚的咒语。",h="棘齿城的术士收集好危险的材料后，会从斯坦哈德·法尔杉那里获得阴谋之书。书中记载着将地狱猎犬从扭曲虚空召来并加以束缚的咒语。",kw={"地狱猎犬","棘齿城","斯坦哈德·法尔杉","召唤法阵","誓缚","阴谋之书"},ang={["class:Warlock"]="身为术士，你必须掌握这本典籍，才能获得地狱猎犬作为伙伴，并掌控恶魔魔法。"},sec={{t="通往扭曲虚空的门户",b="地狱猎犬是来自混乱的扭曲虚空的凶恶野兽，以吞噬法力而令人畏惧。对经验丰富的术士而言，降服一只地狱猎犬是一道考验。阴谋之书记载着为这种恶魔打开通道的仪式。斯坦哈德·法尔杉是棘齿城一位经验丰富的召唤师，只有求学者集齐施法所需的稀有而危险的材料，他才会交出这本典籍。"},{t="召唤仪式",b="斯坦哈德·法尔杉在自己的密室中布下主召唤法阵，他的侍僧则使用导能法杖构筑一道更大的防护屏障。术士准确念诵典籍中的咒语，将地狱猎犬拖入我们的世界。术士必须立即与恶魔交战并将其降服，使它服从自己的意志。"}},faq={{q="阴谋之书有什么用途？",a="阴谋之书记载着将地狱猎犬从扭曲虚空召入棘齿城预先布好的法阵中的咒语，术士可以在那里迎战并束缚这只恶魔。",al={"阴谋之书有什么作用","阴谋之书用途","典籍 地狱猎犬"}},{q="谁会提供阴谋之书？",a="斯坦哈德·法尔杉是一位术士导师，住在贫瘠之地棘齿城上方的山丘中，施术者完成艰难的准备工作后，他就会交出这本典籍。",al={"谁提供阴谋之书","哪里获得阴谋之书","斯坦哈德·法尔杉的书"}},{q="完成仪式后还能保留这本典籍吗？",a="不能。击败召来的地狱猎犬并证明自己的驾驭能力后，你要将阴谋之书交还给斯坦哈德·法尔杉，以此证明你已成功。",al={"能否保留这本书","阴谋之书奖励","保留阴谋之书"}},{q="可以在世界上的任何地方召唤地狱猎犬吗？",a="不可以。你必须在棘齿城上方斯坦哈德·法尔杉的圣所中念诵咒语，他和侍僧在那里维持着大小召唤法阵，用来困住降临的野兽。",al={"任意地点召唤地狱猎犬","在哪里阅读典籍","典籍仪式地点"}}},fp="30,185,23.358.0,20.311.0,39.176.0,35.157.0,49.145.0,51.187.0"}
P.entries["item:top-of-gelkak-s-key"] = {n="基尔卡克钥匙的头部",s="一只巨型森林陆行鸟将基尔卡克钥匙的头部带进了黑海岸附近的树林。这是侏儒基尔卡克·旋杆的机械钥匙碎裂后的三块碎片之一，他的船遭遇了海难。",h="一只巨型森林陆行鸟将基尔卡克钥匙的头部带进了黑海岸附近的树林。这是侏儒基尔卡克·旋杆的机械钥匙碎裂后的三块碎片之一，他的船遭遇了海难。",kw={"黑海岸","大副","森林陆行鸟","基尔卡克","旋杆","钥匙","海盗","找回"},ang={["profession:Engineering"]="这把钥匙能为一台自动机械上发条并将其启动，展现了侏儒工匠精巧而扎实的技艺。",["race:Gnome"]="身为侏儒，看到同族凭着古怪的作风和发条装置从海难中幸存下来，你或许会感到熟悉而亲切。"},sec={{t="破碎的机械",b="蛇颈龙在黑海岸近海袭击了基尔卡克·旋杆的船，将它沉入海底。这个侏儒被冲上岸时，身上还带着为机械大副上发条的钥匙。钥匙撞上岸边的岩石，断成了三截。晕头转向的海盗还没回过神来，野兽就来翻找残骸了。一只巨型森林陆行鸟将装饰华丽的钥匙头部带进了树林。"},{t="修复大副",b="基尔卡克·旋杆需要这把钥匙给机械大副上发条，将它启动，好用它对付当地的野生动物。钥匙的中部和底部分别被海岸鱼人和礁石蟹带走了。只要集齐三块碎片，旋杆就能重新拼好钥匙，让他的构造体运转起来。"}},faq={{q="基尔卡克钥匙的头部有什么用？",a="基尔卡克钥匙的头部是三块碎片之一，基尔卡克·旋杆需要它们来修复他的机械发条钥匙。钥匙拼好后，就能重新启动他的机械大副。",al={"基尔卡克的钥匙有什么用","基尔卡克钥匙的头部用途","基尔卡克钥匙用途"}},{q="森林陆行鸟是怎么得到这块钥匙碎片的？",a="基尔卡克在黑海岸近海遭遇海难时，钥匙撞在岩石上断裂了。野兽前来翻找残骸，一只巨型森林陆行鸟将黄铜制成的钥匙头部带进了海岸东北方的树林。",al={"陆行鸟为什么有钥匙","谁拿走了基尔卡克钥匙的头部","森林陆行鸟怎么得到钥匙的"}},{q="钥匙的其他碎片在哪里？",a="沉船附近的灰雾鱼人拿走了钥匙的中部，而在潮线上觅食的螃蟹则带走了底部。",al={"其他钥匙碎片在哪里","基尔卡克钥匙的中部和底部","基尔卡克钥匙碎片"}},{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是个侏儒海盗，蛇颈龙毁掉了他的船，让他流落黑海岸。他受困于此，怒火中烧，正盘算着向海岸上的生物复仇。",al={"基尔卡克是谁","基尔卡克·旋杆的故事"}}},fp="19,175,21.361.0,24.296.1,41.179.0,50.201.0,38.120.0,23.163.0"}
P.entries["item:torch-of-the-dormant-flame"] = {n="眠炎火炬",s="在眠炎圣殿，一位萨满祭司正准备点燃眠炎火炬。这支尚未点燃的火炬，正等待着从杜隆塔尔山巅的火焰之灵那里赢得的余烬。",h="在眠炎圣殿，一位萨满祭司正准备点燃眠炎火炬。这支尚未点燃的火炬，正等待着从杜隆塔尔山巅的火焰之灵那里赢得的余烬。",kw={"火焰的召唤","杜隆塔尔","火焰灵契","萨满祭司","眠炎圣殿","泰尔夫·祖拉姆","眠炎火炬"},ang={["class:Shaman"]="身为萨满祭司，你起初拿到的是一支尚未经受试炼的火炬。征服活生生的火焰化身，将火炬点燃，赢得召唤火焰图腾的资格。"},sec={{t="觉醒的容器",b="一位寻求火焰眷顾的萨满祭司，带着尚未点燃的眠炎火炬，登上杜隆塔尔的高峰。火焰灵契让萨满祭司能够看见山巅的火焰之魂，并向它发起挑战。火焰之灵倒下后，它的余烬被放入眠炎圣殿饱经风霜的火盆中。萨满祭司将火炬顶端触向炽白的烈焰，木质的火炬随之苏醒，化为掌控元素之力的燃烧象征。"}},faq={{q="眠炎火炬有什么用途？",a="接受火焰的召唤试炼的萨满祭司会得到这支尚未点燃的仪式火炬。击败火焰的化身后，将它的余烬放入圣殿的火盆，再将火炬伸入炽白的烈焰中，以元素之力将其点燃。",al={"眠炎火炬是什么","为什么会有尚未点燃的火炬","火炬有什么用"}},{q="这支火炬在哪里点燃？",a="击败火焰之魂后，在杜隆塔尔泰尔夫·祖拉姆附近的山顶，用眠炎圣殿的火盆点燃这支火炬。",al={"眠炎火炬在哪里点燃","眠炎圣殿火炬","如何点燃眠炎火炬"}},{q="谁会提供尚未点燃的火炬？",a="住在十字路口北面的萨满祭司卡纳尔·菲斯，将尚未点燃的火炬交给初学者，并派他们去见眠炎圣殿的守护者泰尔夫·祖拉姆。泰尔夫·祖拉姆认得这支火炬，知道持有者正试图驯服火焰。",al={"谁给眠炎火炬","眠炎火炬来源","火焰的召唤火炬提供者"}}},fp="26,158,19.443.0,54.249.0,30.187.0,29.231.0"}
P.entries["item:torn-fin-eye"] = {n="碎鳍鱼人的眼球",s="在希尔斯布莱德沿海，碎鳍鱼人的眼球引起了皇家药剂师学会的注意。被遗忘者搜集这些眼球，用于研制新瘟疫的炼金工作。",h="在希尔斯布莱德沿海，碎鳍鱼人的眼球引起了皇家药剂师学会的注意。被遗忘者搜集这些眼球，用于研制新瘟疫的炼金工作。",kw={"药剂师林度恩","苦楚药剂","希尔斯布莱德丘陵","鱼人","皇家药剂师学会","碎鳍","碎鳍鱼人的眼球","幽暗城"},ang={["faction:Horde"]="作为部落的一员，你通过收集沿海的试剂，支援部落在希尔斯布莱德丘陵的战事，巩固被遗忘者的据点，抵御联盟从南海镇发起的推进。",["race:Undead"]="作为一名Undead，收集碎鳍鱼人的眼球这类有机催化剂，可以推进皇家药剂师学会的目标：完善一种能同时毁灭Scourge与生者的瘟疫。"},sec={{t="毁灭的试剂",b="皇家药剂师学会利用稀有的生物材料，研究被遗忘者的新的瘟疫。碎鳍鱼人的眼球取自希尔斯布莱德丘陵西部海岸的鱼人。它们的有机特性有助于激活不稳定的炼金化合物。将这些眼球与刺脊纳迦的鳞片、具有恢复功效的巨魔药剂以及取自豺狼人的淤泥混合，便能帮助稳定并激活有毒混合物，将死亡散播到敌人的土地上。"},{t="酿造苦痛",b="在幽暗城的炼金房，炼金大师们发现，加入泥头复合物的腐败胶质需要来自希尔斯布莱德海岸的催化剂。塔伦米尔的药剂师林度恩用采集来的眼球催化他的苦楚药剂。这种药剂是被遗忘者持续在 人类聚居地附近研制毁灭性生物武器的工作之一。"}},faq={{q="碎鳍鱼人的眼球有什么用途？",a="皇家药剂师学会搜集碎鳍鱼人的眼球，用作炼金催化剂。在塔伦米尔，药剂师林度恩将它们与刺脊纳迦的鳞片和强效巨魔之血药剂混合，激活不稳定的泥头花水中的污染物，推进致命瘟疫的研究。",al={"碎鳍鱼人的眼球用途","为什么收集碎鳍鱼人的眼球","碎鳍鱼人的眼球作用"}},{q="哪里能找到碎鳍鱼人的眼球？",a="你可以在希尔斯布莱德丘陵的西部海岸，从碎鳍鱼人身上采集碎鳍鱼人的眼球，那里位于南海镇以西的海边。",al={"哪里获取碎鳍鱼人的眼球","碎鳍鱼人的眼球位置","谁掉落碎鳍鱼人的眼球"}},{q="谁下令收集这些眼球？",a="幽暗城的被遗忘者研究者和塔伦米尔的药剂师林度恩需要这些眼球来完成苦楚药剂。",al={"谁需要碎鳍鱼人的眼球","碎鳍鱼人的眼球任务发布者"}},{q="皇家药剂师学会为什么需要鱼人的身体组织？",a="皇家药剂师学会研究当地生物，寻找能激活或增强有毒污染物的化合物。碎鳍鱼人的眼内液体可以催化不稳定的瘟疫原型。",al={"为什么需要鱼人眼球","药剂师 鱼人"}}},fp="12,144,18.431.0,13.332.1,32.276.0,32.133.0,39.120.0,56.184.0"}
P.entries["item:torn-murloc-fin"] = {n="破损的鱼人鳞片",s="在艾尔文东部的水道沿岸，鱼人成群聚集，已有猎人响应暴风城军队的悬赏。",h="在艾尔文东部的水道沿岸，鱼人成群聚集，已有猎人响应暴风城军队的悬赏。",kw={"鱼人悬赏","艾尔文鱼人","卫兵托马斯","鱼人的鳍","鱼人觅食者","鱼人潜伏者","石碑湖","破损的鱼人鳞片"},ang={["faction:Alliance"]="对联盟而言，清剿艾尔文东部水道沿岸的鱼人，可以保护连接闪金镇、湖畔镇和暴风城的重要通道。",["race:Human"]="身为人类，你知道地方当局越来越依赖雇佣兵，保护家园和河岸免受那些充满敌意的鱼人聚落侵扰。"},sec={{t="悬赏除患",b="艾尔文东部的溪流和湖泊沿岸，鱼人的数量日益增多。因此，暴风城军队发布悬赏，以削减它们的数量。卫兵托马斯驻守着东部河流上的桥梁，收集割下的鱼鳍作为凭证。内部动乱和周边威胁让兵力捉襟见肘，地方当局只能依靠旅人带回鱼人营地已被清剿的证明。"}},faq={{q="谁会购买或收集破损的鱼人鳞片？",a="在艾尔文森林东部的桥头，卫兵托马斯为治安官杜汉和暴风城军队收集破损的鱼人鳞片。",al={"谁要鱼鳍","鱼鳍交付","卫兵托马斯鱼鳍"}},{q="携带这些鱼鳍的鱼人在哪里？",a="这些鱼鳍来自北面石碑湖周围，以及艾尔文东部边界附近南侧溪流分岔处的鱼人觅食者和潜伏者。",al={"哪里刷鱼鳍","鱼人的鳍位置","鱼鳍掉落"}},{q="暴风城为什么要求用鱼鳍作为凭证？",a="鱼鳍易于辨认，也方便携带。暴风城军队凭这些鱼鳍确认鱼人已被杀死，再向赏金猎人支付赏金。",al={"为什么要鱼鳍","击杀鱼人的凭证","悬赏凭证"}},{q="暴风城军队为什么悬赏猎杀鱼人？",a="鱼人村落沿着水道迅速扩张，威胁着旅人、渔民和当地的基础设施。暴风城军队的兵力正忙于应付其他地方的事务。",al={"为什么悬赏鱼人","艾尔文鱼人之患"}}},fx={afa68c63={q="破损的鱼人鳞片是什么？",a="破损的鱼人鳞片是从盘踞在艾尔文森林东部的鱼人皮上割下的战利品。它并非装饰品或炼金材料，而是证明一名四处游荡的两栖掠夺者已被杀死的实物凭证，为发布悬赏的当地官员提供可靠的依据。",al={"破损的鱼人鳞片是什么","破损的鱼人鳞片背景故事","关于鱼人的鳍"}},["5ee7d3aa"]={q="破损的鱼人鳞片从何而来？",a="这些鳍直接取自栖息在艾尔文森林淡水浅滩的鱼人觅食者和潜伏者的尸体。其中，好斗的部族已在石碑湖岸边及东部河流的南侧支流沿岸扎营，威胁着当地的旅人与农田。",al={"破损的鱼人鳞片来历","鱼人的鳍从何而来","破损的鱼人鳞片来源"}}},fp="15,108,17.368.0,38.116.0,50.142.0,41.127.0,50.168.0"}
P.entries["item:totem-of-hawkwind"] = {n="鹰风图腾",s="在纳拉其营地，年轻的牛头人会在启程前往血蹄村之前，领到鹰风图腾。他们将图腾呈给贝恩·血蹄，以此证明自己已完成最初的试炼，准备好继续参加大地之母仪祭。",h="在纳拉其营地，年轻的牛头人会在启程前往血蹄村之前，领到鹰风图腾。他们将图腾呈给贝恩·血蹄，以此证明自己已完成最初的试炼，准备好继续参加大地之母仪祭。",kw={"贝恩·血蹄","血蹄村","纳拉其营地","鹰风酋长","鹰风","大地之母仪祭","图腾"},ang={["race:Tauren"]="身为牛头人，携带这枚图腾，标志着你告别红云台地上的童年，走向莫高雷更广阔的部族领地。"},sec={{t="酋长的认可",b="鹰风酋长在红云台地上为即将成年的年轻人雕刻鹰风图腾。这件信物表明持有者的身份，也证明他们已通过考验。牛头人很少使用正式文书；寓意深远的符号和熟悉的部族工艺承载着领袖的心意。年轻人在纳拉其营地完成最初的试炼后，鹰风便让他们带上图腾，沿着道路前往莫高雷更广阔的土地。图腾上独特的雕刻向贝恩·血蹄表明持有者的身份，也证明他们具备迎接后续试炼的意志与力量，能够继续踏上寻求雷霆崖祝福的道路。"}},faq={{q="鹰风图腾有什么用途？",a="年轻的牛头人将鹰风图腾从纳拉其营地带到血蹄村，作为通过考验的信物。他们将图腾出示给贝恩·血蹄，以此证明鹰风酋长已认定他们准备好继续参加大地之母仪祭。",al={"鹰风图腾有什么用","鹰风图腾用途","为什么会有这枚图腾"}},{q="是谁制作了这枚图腾？",a="鹰风酋长在红云台地雕刻这枚图腾。莫高雷各地的盟友酋长都认得图腾上独特的雕刻。",al={"谁雕刻了图腾","图腾制作者","鹰风图腾起源"}},{q="鹰风图腾要交给谁？",a="这枚图腾要带给凯恩·血蹄之子贝恩·血蹄。他掌管着红云台地以东的血蹄村。",al={"图腾交给谁","图腾接收者","图腾送到哪里"}},{q="为什么用图腾而不用书信？",a="牛头人依靠口述传统、手工技艺和祖传符号传承文化。雕刻的图腾承载着制作者亲手留下的印记与精神，部族领袖认为它比羊皮纸上的墨迹更有分量。",al={"为什么不用书信","牛头人信物传统"}}},fp="17,228,25.528.0,39.225.0,19.116.0,35.114.0,36.196.0"}
P.entries["item:tough-wolf-meat"] = {n="硬狼肉",s="在北郡和寒脊，狼群在山谷中游荡，也为饥饿的当地人提供肉食。硬狼肉肉质粗糙，筋多难嚼。艾尔文森林的居民会吃这种肉，丹莫罗的矮人物资供应商也用它来补充储备。",h="在北郡和寒脊，狼群在山谷中游荡，也为饥饿的当地人提供肉食。硬狼肉肉质粗糙，筋多难嚼。艾尔文森林的居民会吃这种肉，丹莫罗的矮人物资供应商也用它来补充储备。",kw={"丹莫罗","伊根·派特斯金纳","艾尔文森林","北郡修道院","森林狼","硬狼肉","幼狼"},ang={["race:Dwarf"]="身为寒脊山谷的矮人，你可以在启程穿越丹莫罗之前，猎杀蓬毛森林狼，取肉供应当地的物资供应商。",["race:Human"]="身为北郡山谷的人类新兵，你可以为修道院外的伊根·派特斯金纳收集狼肉。这是走出修道院宁静回廊后，最早接到的生存任务之一。"},sec={{t="边地口粮",b="狼群在北郡山谷和丹莫罗附近游荡。它们威胁着附近的定居点，但它们的肉也是来之不易的食物。这种肉粗糙多筋，难以咀嚼，却深受物资匮乏的边地居民珍视。\n\n北郡修道院外的伊根·派特斯金纳痛恨这些凶恶的野兽，却会把它们的肉做成肉排。他用基本物资和装备，换取人们猎杀狼群。"}},faq={{q="硬狼肉从哪里来？",a="艾尔文森林北郡山谷的幼狼和森林狼都能提供硬狼肉。丹莫罗寒脊山谷的蓬毛狼也能提供这种肉。",al={"硬狼肉来源","如何获得硬狼肉","哪里刷硬狼肉"}},{q="艾尔文森林里谁在收集这种肉？",a="北郡修道院外的伊根·派特斯金纳在收集这种肉。他痛恨狼群，却会把狼肉做成肉排，并用多余的装备换取新兵带来的八块狼肉。",al={"谁需要狼肉","伊根·派特斯金纳狼肉","狼肉交付"}},{q="这种肉在人类领地之外也有用吗？",a="有用。严寒的丹莫罗有矮人物资供应商收取寒脊山谷蓬毛狼的肉，以补充物资储备。",al={"丹莫罗狼肉","矮人狼肉","矮人物资供应商狼肉"}},{q="硬狼肉能用于普通烹饪配方吗？",a="不能。伊根·派特斯金纳和寒脊山谷的物资供应商等当地边地居民，会以酬劳换取硬狼肉。它不是常规营地烹饪配方的食材。",al={"硬狼肉能烹饪吗","硬狼肉配方"}}},fx={["877dd280"]={q="硬狼肉是什么？",a="这是一种粗糙的瘦肉，取自游荡在北郡和丹莫罗荒野中的野狼。虽然筋多，肉质也远称不上鲜嫩，但当地的捕兽者和饥肠辘辘的拓荒者知道如何将它烹成充饥的肉排，作为扎实的主食。",al={"硬狼肉是什么","硬狼肉背景故事","硬狼肉"}}},fp="15,231,16.376.0,37.157.0,48.186.0,43.127.0,50.165.0"}
P.entries["item:tourmaline-phial"] = {n="红玉瓶",s="红玉瓶在阿里斯瑞恩之池采集受祝福的月亮井水，供泰达希尔的仪式使用。",h="红玉瓶在阿里斯瑞恩之池采集受祝福的月亮井水，供泰达希尔的仪式使用。",kw={"科瑞萨斯·月怒","大地之冠","多兰纳尔","月亮井","阿里斯瑞恩之池","泰达希尔","红玉瓶"},ang={["class:Druid"]="身为德鲁伊，你带着宝石瓶采集月亮井水，在学习照料泰达希尔脆弱生态的过程中，履行这项仪式职责。",["race:NightElf"]="身为暗夜精灵，你知道，在泰达希尔艰难抵御腐化之际，月亮井水体现了你的族人对Elune恩典和德鲁伊警戒守护的依赖。"},sec={{t="阿里斯瑞恩的容器",b="科瑞萨斯·月怒将红玉瓶交给旅人，用于照料世界之树的仪式。多兰纳尔的德鲁伊使用宝石瓶，在泰达希尔各处采集纯净的月亮井水。这只瓶子用于采集阿里斯瑞恩之池旁的月亮井水，那里位于通往达纳苏斯的道路东南方，敌对的瘤背熊怪正变得愈发猖獗。"}},faq={{q="红玉瓶有什么用途？",a="红玉瓶用于采集阿里斯瑞恩之池月亮井中的圣水。装满后，你要将它交还给多兰纳尔的科瑞萨斯·月怒，用于大地之冠仪式。",al={"红玉瓶的作用","红玉瓶的用途","使用红玉瓶"}},{q="谁提供红玉瓶？",a="多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒会将空瓶交给旅人。",al={"谁提供红玉瓶","红玉瓶获取地点"}},{q="这只瓶子对应的月亮井在哪里？",a="月亮井位于阿里斯瑞恩之池旁，在通往达纳苏斯的主入口东南方。",al={"阿里斯瑞恩之池月亮井","红玉瓶装水地点"}}},fp="16,117,20.342.0,38.188.0,34.83.0,37.93.0"}
P.entries["item:toxic-fogger"] = {n="剧毒粮草",s="在石爪山，剧毒粮草将被送往荆棘谷地精的空中航线。被遗忘者的皇家药剂师学会在这件装置中装满了致命毒药，用来污染公司的航班。",h="在石爪山，剧毒粮草将被送往荆棘谷地精的空中航线。被遗忘者的皇家药剂师学会在这件装置中装满了致命毒药，用来污染公司的航班。",kw={"药剂师扎玛","直升机停机坪","峭壁湖","空港","石爪山","剧毒粮草","荆棘谷地精"},ang={["race:Tauren"]="身为牛头人，你或许会觉得致命毒雾有违传统的荣誉准则。荆棘谷地精对大地的破坏，让雷霆崖的许多人容忍了扎玛的严酷手段。",["race:Undead"]="身为亡灵，你能看到皇家药剂师学会的战地策略正在付诸实践：用空气传播的毒素扰乱敌人的补给，并向盟友证明，阴暗的手段也能取得成效。"},sec={{t="被遗忘者的解决之道",b="药剂师扎玛派人用剧毒粮草对付荆棘谷地精的采矿作业。药剂师林度恩在塔伦米尔调制了其中的毒药，扎玛则从雷霆崖将其送出。她怀疑地精使用信使飞行器，在石爪山与总部之间运送信件和轻型货物。她计划在这些飞行器降落和补充燃料的地方释放毒药。被遗忘者打算打击公司的补给线，避免与其雇佣兵陷入旷日持久的小规模交战。"},{t="峭壁湖的破坏行动",b="剧毒粮草将被放置在峭壁湖附近荆棘谷地精的直升机停机坪上。这处隐蔽的降落点高踞于遭到砍伐的山丘之上，将远方的作业队与外界枢纽相连。启动剧毒粮草后，有毒蒸气会弥漫整个集结场，让返航的飞行员猝不及防。一些部落成员或许不愿使用毒药，但扎玛要求她的代理人放下愧疚。她相信，只要能战胜这些掠夺者，再阴暗的手段也不为过。"}},faq={{q="剧毒粮草有什么用途？",a="剧毒粮草用于毒害荆棘谷地精位于石爪山脉峭壁湖的空港。它释放的蒸气会污染运往公司总部的轻型货物，并使前往那里的信使中毒。",al={"剧毒粮草的作用","剧毒粮草用途","为何使用剧毒粮草"}},{q="谁制造了剧毒粮草？",a="药剂师林度恩在塔伦米尔用无辜者的鲜血调制了这种毒药。药剂师扎玛是皇家药剂师学会驻雷霆崖地下预见之池的使者，由她派人将毒药送出。",al={"谁制造了剧毒粮草","剧毒粮草制造者","药剂师扎玛的毒药"}},{q="剧毒粮草需要放在哪里？",a="将剧毒粮草安放在石爪山脉峭壁湖附近荆棘谷地精的高架直升机停机坪上，就在大水车的南面。",al={"剧毒粮草放置地点","直升机停机坪位置","空港位置"}},{q="部落为何要用毒药对付荆棘谷地精？",a="荆棘谷地精的伐木和采矿活动正在蹂躏石爪山。药剂师扎玛认为常规战斗太过缓慢，部落必须采取无情的手段，在地精造成无法挽回的破坏之前消灭他们。",al={"为何毒害地精","部落是否允许使用毒药","被遗忘者在石爪山的手段"}}},fx={["3a36a6bd"]={q="什么是剧毒粮草？",a="剧毒粮草是一种特殊的散播装置，里面装有被遗忘者调制的致命药剂。它被设计成启动后释放有毒云雾，是一种用于破坏的工具，旨在污染荆棘谷地精的后勤网络，扰乱他们在石爪山的行动。",al={"什么是剧毒粮草","剧毒粮草物品","剧毒粮草装置"}},bbff0049={q="药剂师扎玛为什么要部署剧毒粮草？",a="药剂师扎玛打算直接打击荆棘谷地精的补给线。将剧毒粮草部署在他们的小型飞艇港后，毒剂便能覆盖起飞的飞行器和货物，再被带回地精总部，让他们为肆无忌惮的掠夺付出惨痛代价。",al={"为什么使用剧毒粮草","为什么想要剧毒粮草","为什么需要剧毒粮草"}}},fp="12,179,19.487.0,25.430.1,34.196.0,29.204.0,46.146.0,70.220.0"}
P.entries["item:translated-letter"] = {n="翻译好的信件",s="在夜色镇，希拉·沃宁迪为镇长埃伯洛克翻译亚伯克隆比的信。这封信揭示了隐士与镇子之间往来的内情。",h="在夜色镇，希拉·沃宁迪为镇长埃伯洛克翻译亚伯克隆比的信。这封信揭示了隐士与镇子之间往来的内情。",kw={"亚伯克隆比","夜色镇","写给艾尔罗的信","艾尔罗·埃伯洛克公爵","希拉·沃宁迪","翻译好的信件"},ang={["faction:Alliance"]="作为一名在暮色森林旅行的联盟成员，你会了解到，善意如何被利用，反过来危害夜色镇本就势单力薄的守卫者。"},sec={{t="骇人的真相",b="起初，这些跑腿差事是为了帮助乌鸦岭一位看似无助的隐士。亚伯克隆比写给镇长埃伯洛克的晦涩信件，直到希拉·沃宁迪译出后才揭开谜底。信中的话揭露了隐士就是藏尸者。他用别人送来的物资造出了缝合怪，一个可怕的憎恶，随后放出这庞然大物，让它践踏、屠杀夜色镇的居民。"},{t="善意的代价",b="当翻译好的信件呈到艾尔罗·埃伯洛克公爵面前时，镇长的脸色顿时变得煞白。旅行者出于善意伸出援手，亚伯克隆比却利用这番辛劳造出了杀戮的工具。镇议会匆忙召集守夜人之际，这封信揭示了在暮色森林鬼影重重的道路上，善举如何被扭曲成灾祸。"}},faq={{q="翻译好的信件说了什么？",a="这封信带来了亚伯克隆比写给艾尔罗·埃伯洛克公爵的惊人消息。将译好的信送到夜色镇交给他后，你就能得知信的完整内容。",al={"信件内容","亚伯克隆比写了什么","信里说了什么"}},{q="谁翻译了这封信？",a="夜色镇的学者希拉·沃宁迪译出了亚伯克隆比晦涩难懂的字迹，并告诫你赶快把这惊人的消息带回给艾尔罗。",al={"谁翻译了信","谁解读了信","希拉·沃宁迪的信"}},{q="艾尔罗读信后有什么反应？",a="译出的内容令艾尔罗深感不安。把信交给他，就能得知这对夜色镇意味着什么。",al={"艾尔罗的反应","交付翻译好的信件","翻译后会发生什么"}},{q="任务完成后，可以扔掉翻译好的信件吗？",a="可以。艾尔罗查看羊皮纸并推进镇子的防御工作后，这封信会留在你的背包里作为纪念，不再有其他用途。",al={"翻译好的信件能否安全删除","翻译好的信件能否摧毁","保留翻译好的信件"}}},fx={ad927ea8={q="什么是翻译好的信件？",a="翻译好的信件是一封阴森的信，由隐士亚伯克隆比写下，再由希拉·沃宁迪解译。信中揭露了亚伯克隆比在乌鸦岭实施阴谋所造成的可怕后果，并直接警告夜色镇的居民，迫近的灾难即将降临。",al={"翻译好的信件","什么是翻译好的信件","关于翻译好的信件"}},["7688c5ef"]={q="艾尔罗·埃伯洛克公爵为什么需要翻译好的信件？",a="夜色镇镇长艾尔罗·埃伯洛克公爵必须读懂解译后的内容，才能了解他的城镇正面临的严重威胁。信件揭露了亚伯克隆比所作所为的可怕真相，也让镇民提前得知，一只庞然怪物正直奔他们的城门而来。",al={"为什么要把翻译好的信件交给艾尔罗","艾尔罗为什么想要翻译好的信件","谁需要翻译好的信件"}}},fp="17,150,21.409.1,28.357.1,36.168.1,26.149.0,40.104.1,55.145.1"}
P.entries["item:treshala-s-pendant"] = {n="塔莎拉的坠饰",s="在剃刀沼泽，一枚坠饰承载着塔莎拉与赫尔拉斯·静水之间的深情。赫尔拉斯将它从达纳苏斯的家中带到卡利姆多南部，野猪人在他弥留之际将它夺走。",h="在剃刀沼泽，一枚坠饰承载着塔莎拉与赫尔拉斯·静水之间的深情。赫尔拉斯将它从达纳苏斯的家中带到卡利姆多南部，野猪人在他弥留之际将它夺走。",kw={"达纳苏斯","赫尔拉斯·静水","生命消逝","野猪人","剃刀沼泽","塔莎拉·静水","塔莎拉的坠饰"},ang={["faction:Alliance"]="身为联盟的一员，你可以将这件信物送往达纳苏斯，让一位哀悼探险家丈夫遇难的遗孀，在悲痛中得到最后的慰藉。",["race:NightElf"]="身为暗夜精灵，你可以寻回坠饰，向一位远离泰达希尔枝桠庇护、客死异乡的kaldorei同胞致敬。"},sec={{t="挚爱的信物",b="赫尔拉斯·静水离开泰达希尔，踏上危机四伏的旅途时，一直贴身带着这枚坠饰。这条项链让他想起家乡、深爱的妻子塔莎拉，以及他们彼此的深情。"},{t="遗失于荆棘之中",b="赫尔拉斯与同伴深入剃刀沼泽，遭到了凶残野猪人的袭击。在他生命的最后时刻，一名长着獠牙的守卫从他身上扯下了坠饰。生命渐渐流逝，赫尔拉斯请求一位路过的冒险者从杀害他的凶手手中夺回这件信物，将它连同他的死讯带回达纳苏斯，交给塔莎拉。"}},faq={{q="塔莎拉的坠饰是什么？",a="塔莎拉的坠饰属于塔莎拉·静水。她的丈夫赫尔拉斯生前一直带着它，作为两人结为夫妻的信物，直到他在剃刀沼泽遇难。",al={"这是什么物品","情谊坠饰","坠饰属于谁"}},{q="坠饰为何会落在剃刀沼泽？",a="赫尔拉斯·静水带着坠饰前往剃刀沼泽探险。野猪人伏击了他，使他身受致命伤，随后其中一名野猪人夺走了他的项链。",al={"为何在剃刀沼泽","如何遗失的"}},{q="是谁请求寻回坠饰？",a="赫尔拉斯·静水在剃刀沼泽奄奄一息，恳求路过的冒险者找回坠饰，将它连同自己的死讯交给他在达纳苏斯的妻子。",al={"谁给予任务","谁想找回坠饰"}},{q="寻回的坠饰要交给谁？",a="寻回的坠饰要交给塔莎拉·静水。赫尔拉斯的遗孀住在达纳苏斯，那是坐落于泰达希尔之上的暗夜精灵首都。",al={"坠饰交到哪里","塔莎拉是谁"}}},fx={["1ac8940a"]={q="为什么要寻找塔莎拉的坠饰？",a="濒死的暗夜精灵赫尔拉斯·静水在剃刀沼泽中奄奄一息，他最后的愿望是找回这件被盗的纪念品。这是他的妻子塔莎拉送给他的信物。在他孤独地死于野猪人要塞之前，他希望你能从夺走坠饰的暴徒手中把它取回，并将坠饰和他去世的噩耗一并送到达纳苏斯交给他的妻子。",al={"为什么要寻找塔莎拉的坠饰","赫尔拉斯为什么想要坠饰","塔莎拉的坠饰的用途"}}},fp="18,197,17.180.0,18.295.1,27.133.0,45.160.0,41.167.0,46.128.0"}
P.entries["item:trogg-stone-tooth"] = {n="穴居人的石牙",s="在洛克莫丹的群山中，碎石穴居人会留下粗糙、矿化的牙齿。矮人守军用每颗牙齿证明，南部边境的穴居人正遭到猎杀。",h="在洛克莫丹的群山中，碎石穴居人会留下粗糙、矿化的牙齿。矮人守军用每颗牙齿证明，南部边境的穴居人正遭到猎杀。",kw={"洛克莫丹","拉格弗斯上尉","碎石","穴居人的威胁","穴居人","穴居人的石牙"},ang={["faction:Alliance"]="身为联盟的一员，响应拉格弗斯上尉的号召，能够减轻连接矮人诸国与联盟其他地区的商路所承受的压力。",["race:Dwarf"]="身为矮人，在铁炉堡大批军队随联盟远征之时，你带回的每颗牙齿都有助于保卫卡兹莫丹。"},sec={{t="南门的悬赏",b="拉格弗斯上尉号召志愿者前往洛克莫丹南门附近，猎杀碎石穴居人。由于铁炉堡的预备部队已投入联盟前线，卡兹莫丹各地的矮人驻军兵力捉襟见肘。拉格弗斯上尉无法从南门哨塔抽调士兵，巡视附近的山地。因此，志愿者们猎杀潜伏的穴居人，并带回穴居人的石牙，作为每头穴居人被击杀的粗陋却无可辩驳的凭证。"}},faq={{q="谁在收集这些穴居人的石牙？",a="在洛克莫丹南部的哨塔，拉格弗斯上尉收集这些牙齿，以此证明旅人们正在猎杀碎石穴居人。",al={"谁收穴居人石牙","拉格弗斯上尉牙齿","谁需要石牙"}},{q="这些牙齿为什么是石头做的？",a="穴居人具有大地与地底生物的特性，这与他们源自古老岩石的起源有关。他们的獠牙和牙齿沉重且已矿化，如同未经雕琢的岩石。",al={"为什么是石牙","穴居人牙齿构造","穴居人的牙齿是石头吗"}},{q="矮人驻军为什么不能亲自猎杀穴居人？",a="铁炉堡的预备部队已投身联盟更大范围的战事，导致当地哨站人手不足。拉格弗斯上尉的部队必须守卫南门，不能让防御工事无人驻守。",al={"拉格弗斯上尉为何需要帮助","矮人为何不打穴居人","铁炉堡的预备部队"}},{q="哪些穴居人身上有这些牙齿？",a="这些牙齿来自洛克莫丹山地和挖掘场中的碎石穴居人。其中包括普通的挖掘者、斥候、能折断骨头的战士和地卜师。",al={"哪里获取穴居人石牙","谁掉落石牙"}}},fx={d6a17ab5={q="穴居人的石牙是什么？",a="穴居人的石牙是一颗确实坚硬如石的牙齿，取自盘踞在洛克莫丹峭壁间的碎石穴居人的口中。这些硬化的牙齿反映了穴居人奇异的土石本性，也让当地的矮人守卫有了无可辩驳的实物证据，证明一名四处劫掠的穴居人已被彻底消灭。",al={"穴居人的石牙是什么","穴居人的石牙资料","穴居人的石牙"}}},fp="17,187,27.438.0,34.132.0,32.137.0,58.202.0,31.155.0"}
P.entries["item:troll-charm"] = {n="巨魔符咒",s="在灰谷，死去的暗矛旅人身上的巨魔符咒被夺走了。蓟皮熊怪伏击了这支前往佐拉姆加前哨站的队伍，抢走了这些神圣的护符。",h="在灰谷，死去的暗矛旅人身上的巨魔符咒被夺走了。蓟皮熊怪伏击了这支前往佐拉姆加前哨站的队伍，抢走了这些神圣的护符。",kw={"灰谷","暗矛","米苏瓦","蓟皮要塞","蓟皮村","巨魔符咒","佐拉姆加前哨站"},ang={["faction:Horde"]="身为部落的一员，夺回被盗的符咒，既能削弱好勇斗狠的蓟皮部族，也能为惨死在灰谷险恶道路上的部落旅人报仇。",["race:Troll"]="身为暗矛巨魔，任由神圣的符咒落在野蛮的熊怪手中，是对你死去的族人不可容忍的侮辱。"},sec={{t="暗矛的神圣饰物",b="暗矛巨魔随身携带灵魂符咒，作为尊严的象征。斥候米苏瓦说，巨魔若没有符咒，就如同兽人没有战斗留下的伤疤一样，有失尊严。一队暗矛族人穿行于灰谷的林荫下，前往佐拉姆加前哨站，途中遭到堕落的蓟皮熊怪伏击，全数遇害。他们的灵魂被送往彼岸，熊怪却将符咒当作战利品，藏进了蓟皮要塞深处的箱子里。"}},faq={{q="巨魔符咒有什么用途？",a="暗矛巨魔随身携带巨魔符咒，将其作为神圣的灵魂护符和个人尊严的象征。",al={"巨魔符咒的用途","巨魔符咒的故事","巨魔为何携带符咒"}},{q="这些符咒在哪里？",a="这些符咒锁在蓟皮要塞内的箱子里，那是灰谷北部蓟皮村后方的一片洞穴。",al={"巨魔符咒在哪","如何找到巨魔符咒","巨魔箱子的位置"}},{q="熊怪为什么会有这些符咒？",a="蓟皮熊怪伏击并杀害了前往佐拉姆加前哨站的暗矛旅人，随后洗劫了他们的随身物品，留下了这些符咒。",al={"熊怪为何持有符咒","谁偷走了符咒"}},{q="谁想找回这些符咒？",a="米苏瓦是驻守在佐拉姆海岸的佐拉姆加前哨站的一名暗矛巨魔，他希望找回这些符咒，为遇害的族人挽回荣誉。",al={"谁收取符咒","米苏瓦的任务"}}},fx={["5fe70fe7"]={q="什么是巨魔符咒？",a="巨魔符咒是暗矛巨魔随身携带的神圣部族护符。这些符咒对巨魔而言具有深远的个人和精神意义，被视为身份与地位的重要凭证——以至于没有符咒的巨魔，在同族眼中就像没有战痕的兽人一样。",al={"什么是巨魔符咒","巨魔符咒物品","神圣的巨魔符咒"}},["6d34290e"]={q="巨魔护符来自哪里？是谁制作的？",a="这些护符由途经灰谷、前往佐拉姆加前哨站的暗矛巨魔制作并随身携带。不幸的是，旅人们在路上遭到敌对的蓟皮熊怪伏击并被杀害，神圣的物品也被劫走，锁在蓟皮要塞深处的箱子里。",al={"巨魔护符的来历","巨魔护符是谁制作的","巨魔护符来自哪里"}},["77137dd7"]={q="米苏瓦为什么想要取回巨魔护符？",a="佐拉姆加前哨站的米苏瓦为遇难的旅人哀悼，但她接受他们终将在来世重聚的事实。然而，任由粗野凶恶的熊怪占有这些神圣遗物，被视为对巨魔传统无法容忍的侮辱。找回护符，便能让死者的记忆重获尊严。",al={"为什么要获取巨魔护符","米苏瓦为什么想要护符","为什么要找巨魔护符"}}},fp="11,176,32.441.0,31.92.0,29.120.0,38.141.0,26.130.0"}
P.entries["item:trophy-swoop-quill"] = {n="猛鹫的羽毛",s="在莫高雷各处，猛鹫盘旋于平原上空，它们的羽毛是猎手技艺的证明。牛头人将这些羽毛带给血蹄村的哈肯·风之图腾。",h="在莫高雷各处，猛鹫盘旋于平原上空，它们的羽毛是猎手技艺的证明。牛头人将这些羽毛带给血蹄村的哈肯·风之图腾。",kw={"血蹄村","哈肯·风之图腾","莫高雷","猎捕猛鹫","猛鹫羽毛","锐爪猛鹫","猛鹫的羽毛","瘦小的猛鹫"},ang={["class:Hunter"]="身为猎人，在开阔的平原上追踪空中的猎物，会考验你的追踪本领、耐心与射击技艺。",["race:Tauren"]="身为牛头人，在莫高雷各处猎捕猛鹫并带回它们的羽毛，会考验你的耐心与机智，为你和你的氏族赢得荣誉。"},sec={{t="狩猎的信物",b="猛鹫翱翔于莫高雷草原的高空，踪迹难寻。血蹄村的年轻牛头人猎手和旅者寻求一根作为战利品的羽毛，以证明自己的机智与决心。将羽毛带给哈肯·风之图腾这样的长者，既能为猎手的氏族赢得荣誉，也能展现出在平原上生存所需的敏锐感官。"}},faq={{q="猛鹫的羽毛有什么用途？",a="将猛鹫的羽毛带给血蹄村的哈肯·风之图腾，就能证明你的狩猎功绩。这些羽毛展现了你的决心与敏锐的观察力，也能为你在当地牛头人中赢得声望。",al={"猛鹫羽毛有什么用","谁需要猛鹫羽毛","猛鹫羽毛用途"}},{q="猛鹫的羽毛从何而来？",a="猛鹫的羽毛来自翱翔于莫高雷草海平原上的普通猛鹫、消瘦的猛鹫和长爪猛鹫。",al={"哪里获得猛鹫羽毛","谁掉落猛鹫的羽毛","猛鹫位置"}},{q="为什么猛鹫被认为难以猎捕？",a="哈肯·风之图腾将猛鹫描述为狡猾的鸟类，它们在草地上空高高盘旋，迅速掠过大地。敏锐的目光能帮你发现它们，轻快的脚步则能帮你追上它们。",al={"为什么猎捕猛鹫","猛鹫难杀吗"}}},fp="18,161,17.325.0,38.200.0,39.119.0,44.194.0"}
P.entries["item:twilight-pendant"] = {n="暮光坠饰",s="在黑暗深渊，暮光坠饰是效忠于暮光之锤的教徒的标志。银色黎明正在收集这些坠饰，作为该教派在灰谷海岸活动的证据。",h="在黑暗深渊，暮光坠饰是效忠于暮光之锤的教徒的标志。银色黎明正在收集这些坠饰，作为该教派在灰谷海岸活动的证据。",kw={"银月守卫玛纳杜斯","灰谷","黑暗深渊","上古之神","暮光之锤的末日","暮光坠饰","暮光之锤"},ang={["faction:Alliance"]="身为联盟的一员，你可以将这些战利品交给达纳苏斯的银月守卫玛纳杜斯。它们表明联盟支持银色黎明在卡利姆多北部对抗潜藏邪恶的行动。",["race:NightElf"]="身为暗夜精灵，你知道黑暗深渊曾有一口备受尊崇且力量强大的月亮井。收缴其中象征腐化的信物，对kaldorei而言是一件极为神圣的事。"},sec={{t="上古之神的信物",b="在黑暗深渊被淹没的废墟之下，暮光之锤与纳迦聚集在一起，敬奉混乱的上古之神。暗影法师、水术师、掠夺者和寻知者都佩戴着暮光坠饰，以示对其暗影庇护者的虔诚。这个教派盘踞在昔日暗夜精灵神殿的废墟中，因此，对外来者而言，这些坠饰是了解那里聚集了多少教徒并阻挠其计划的少数途径之一。"},{t="银色黎明的守望",b="达纳苏斯的银月守卫玛纳杜斯正在收集暮光坠饰，以证明日益滋长的黑暗正在被击退。黑暗深渊曾有一口纯净的月亮井，而虚空崇拜者对它的亵渎正威胁着卡利姆多。收集这些坠饰，表明暮光之锤在灰谷的据点正在被逐步铲除，赶在其庇护者释放更大的恐怖之前。"}},faq={{q="暮光坠饰是什么？",a="暮光坠饰是黑暗深渊的暮光之锤成员佩戴的身份护符。它们表明教徒对上古之神及其仪式的虔诚。",al={"暮光坠饰资料","暮光坠饰是什么"}},{q="银月守卫玛纳杜斯为什么想要这些坠饰？",a="银月守卫玛纳杜斯在达纳苏斯收集暮光坠饰，以证明黑暗深渊的暮光之锤正在其计划成形之前遭到打击。",al={"谁需要暮光坠饰","为什么收集暮光坠饰"}},{q="谁佩戴这些坠饰？",a="黑暗深渊中的暮光侍僧、暮光水法师、暮光暗影法师、暮光寻知者、暮光元素师和暮光劫掠者都佩戴这些坠饰。",al={"谁掉落暮光坠饰","暮光坠饰来自哪里"}},{q="暮光之锤在黑暗深渊构成了什么威胁？",a="暮光之锤与纳迦结盟，试图复兴对上古之神的崇拜。其仪式亵渎了一口古老的暗夜精灵月亮井，还可能让恐怖蔓延至整个卡利姆多。",al={"暮光之锤在黑暗深渊做什么","教徒为什么在灰谷"}}},fp="16,189,22.391.0,24.368.0,27.159.0,50.165.0,25.130.0,65.190.0"}
P.entries["item:twilight-whisker"] = {n="夜行虎须",s="在玛拉卡金，巫医金吉尔正收集夜行虎须，用来调制药剂。石爪山脉北部高地的 暮光 奔跑者 身上长着这些胡须。",h="在玛拉卡金，巫医金吉尔正收集夜行虎须，用来调制药剂。石爪山脉北部高地的 暮光 奔跑者 身上长着这些胡须。",kw={"森林魔法","玛拉卡金","石爪山脉","石爪峰","暮光巡游者","夜行虎须","巫医金吉尔"},ang={["race:NightElf"]="身为暗夜精灵，你目睹 暮光 runners 和 fey dragons 这样的神圣林地生灵遭到亵渎，被用来毒害卡利姆多森林中的暗夜精灵俘虏。",["race:Troll"]="身为巨魔，你目睹金吉尔将当地野兽用作暗矛巫毒的材料，以森林的自然精华对付他的敌人。"},sec={{t="巫医的材料",b="暮光 奔跑者 在石爪峰附近的高耸山崖间潜行。猎人看重它们的毛皮，而玛拉卡金的巫医金吉尔索取它们硬挺的胡须，却有着更阴暗的目的。他要向那些因保卫这片林地而被俘的暗夜精灵复仇。为了羞辱并毒害俘虏，金吉尔收集树脂般的树液、无数眼睛、灵龙的鳞片和夜行虎须，调制一种致命药剂，并称之为森林魔法。"}},faq={{q="哪里能找到夜行虎须？",a="石爪山脉北部、石爪峰周围山坡上的 夜行虎 身上长着夜行虎须。",al={"夜行虎须位置","夜行虎须掉落来源","夜行虎须获取地点"}},{q="巫医金吉尔为什么需要它们？",a="巫医金吉尔将夜行虎须与树液、巨角鹿 的眼睛和一片灵龙的鳞片混合，调制致命药剂，用来毒害玛拉卡金的暗夜精灵俘虏。",al={"金吉尔 胡须","金吉尔 索取夜行虎须的原因","金吉尔 森林魔法材料"}},{q="金吉尔收到胡须后会发生什么？",a="收到材料后，金吉尔在自己的洞穴里施放了药剂。药剂迅速杀死了笼中的暗夜精灵囚犯，他们的灵魂化为小精灵，飘然而去。",al={"森林魔法结果","囚犯的下场"}}},fx={["15466f07"]={q="什么是夜行虎须？",a="夜行虎须是从徘徊于石爪山脉高处的暮光奔行者身上采集的坚硬须毛。对大多数人而言，它不过是野兽的残渣；但对巫毒和炼金术的研习者来说，它是一种强效试剂，蕴含着当地掠食者的野性精华。",al={"什么是夜行虎须","夜行虎须介绍","夜行虎须是什么"}},["8f61da64"]={q="夜行虎须来自哪里？",a="夜行虎须取自暮光奔行者，这种掠食性猫科动物原生于石爪山脉。它们并非由凡人之手制作，而是直接从石爪峰附近出没的野兽身上拔取的。",al={"夜行虎须的来历","哪里能获得夜行虎须","谁会掉落夜行虎须"}}},fp="16,168,24.419.0,34.114.0,40.163.0,49.166.1"}
P.entries["item:twitching-antenna"] = {n="颤抖的触角",s="在贫瘠之地南部，异种虫的触角被割下后仍会颤抖。陶拉祖营地的鲁迦·狂暴图腾收集这些触角，要求年轻战士在神经停止抽动前将它们带回，以此证明自己的速度和战斗技巧。",h="在贫瘠之地南部，异种虫的触角被割下后仍会颤抖。陶拉祖营地的鲁迦·狂暴图腾收集这些触角，要求年轻战士在神经停止抽动前将它们带回，以此证明自己的速度和战斗技巧。",kw={"触角","贫瘠之地","陶拉祖营地","巨人旷野","鲁迦·狂暴图腾","异种虫","颤抖的触角"},ang={["class:Hunter"]="身为猎人，你追踪并猎杀异种虫，然后趁触角还在颤抖时将它们收集起来。这场试炼考验你的速度、追踪能力和野外技巧。",["race:Tauren"]="身为牛头人，你知道陶拉祖营地的猎人认为，异种虫的突然到来扰乱了平原的自然平衡。年轻的勇士必须保持警惕。"},sec={{t="狩猎的证明",b="异种幼蝎、异种群居蝎、异种收割者和异种爬行者的触角从头部割下后仍会颤抖。虫子被杀死后，这种抽动很快就会停止。年轻战士必须在南方荒野猎杀异种虫，趁触角还在颤抖时，赶紧穿过灌木荒地返回。及时带回触角既考验速度，也考验技巧，使这场狩猎成为部落战士的成年试炼。"},{t="南方的威胁",b="异种虫的触角也指向了一个令陶拉祖营地猎人忧心的威胁。异种虫并非贫瘠之地的原生生物，它们在巨人旷野新掘出的虫丘让营地感到不安。鲁迦·狂暴图腾想用这些标本研究危险，让部落战士做好准备，应对正在侵入平原的外来威胁。"}},faq={{q="哪些生物会掉落颤抖的触角？",a="贫瘠之地南部巨人旷野附近的异种幼蝎、异种收割者、异种群居蝎和异种爬行者身上都有这些触角。",al={"颤抖的触角哪里掉落","谁掉落颤抖的触角","异种虫触角来源"}},{q="为什么触角必须还在颤抖？",a="颤抖说明触角刚被割下。鲁迦·狂暴图腾利用触角很快就会停止抽动这一点，考验试炼者在荒野中的速度和战斗技巧。",al={"为什么颤抖","为什么要赶紧带回触角","巨人旷野试炼时限"}},{q="谁在寻找这些触角？",a="鲁迦·狂暴图腾是贫瘠之地南部陶拉祖营地的一名牛头人战士，他为试炼巨人旷野收集这些触角。",al={"谁需要颤抖的触角","谁交触角"}},{q="巨人旷野在哪里？",a="巨人旷野位于贫瘠之地的陶拉祖营地以南。巨大的骸骨从那里的地面耸起，周围分布着异种虫的巢穴。",al={"巨人旷野在哪里","巨人旷野位置"}}},fp="17,173,17.366.0,23.314.0,39.121.0,41.176.0,34.130.0,29.144.0"}
P.entries["item:ukor-s-burden"] = {n="乌克尔的货物",s="在试炼谷，乌克尔送来的食物遭到拒收，他需要有人帮忙把食物带回剃刀岭。",h="在试炼谷，乌克尔送来的食物遭到拒收，他需要有人帮忙把食物带回剃刀岭。",kw={"杜隆塔尔","格罗斯克","苦工","口粮","剃刀岭","乌克尔","试炼谷"},ang={["faction:Horde"]="身为部落的一员，你能看到杜隆塔尔的严酷试炼如何塑造新兵。即便是一番好意，也必须服从他们训练的要求。"},sec={{t="好心办错事",b="乌克尔是个兽人苦工，平日很少自作主张，这次却从剃刀岭的旅店带来了补给，想帮助试炼谷的年轻新兵。一路上，他穿过杜隆塔尔的红色尘土，避开危险的野兽。监工和教官拒收了食物，认为艰苦与饥饿才能造就真正的战士。如今，乌克尔在峡谷入口外等候，害怕归途中沿路出没的野兽。他把这袋补给托付给过往的旅人，请他们送还给旅店老板格罗斯克。"}},faq={{q="乌克尔的货物里装着什么？",a="乌克尔的货物里装着剃刀岭旅店的食物和补给。乌克尔原本希望让受训的年轻兽人和巨魔吃饱肚子，但试炼谷不欢迎外来的补给。",al={"包里有什么","乌克尔的货物内容","是什么食物"}},{q="试炼谷为什么拒收食物？",a="试炼谷的监工认为，艰苦与饥饿能磨炼年轻战士的品格。旅店老板格罗斯克说，饥饿能让新兵斗志昂扬，因此他们拒绝外来的施舍。",al={"试炼谷为什么拒收食物","为什么不要食物","为什么不需要食物"}},{q="这袋货物需要送到哪里？",a="把袋子送回剃刀岭旅店，交给旅店老板格罗斯克。他会把补给放回货架，再请送回货物的人喝上一杯。",al={"乌克尔的货物送到哪里","谁要乌克尔的货物","运送乌克尔的货物"}}},fp="13,110,26.495.0,29.175.0,45.183.0,33.157.0"}
P.entries["item:uncloven-satyr-hoof"] = {n="完整的萨特之蹄",s="在灰谷，萨特贪婪地吞噬着古老森林的魔法。它们肿胀的蹄子蕴藏着窃取来的力量，尤拉莱克用这股力量在森金村打造护甲。",h="在灰谷，萨特贪婪地吞噬着古老森林的魔法。它们肿胀的蹄子蕴藏着窃取来的力量，尤拉莱克用这股力量在森金村打造护甲。",kw={"灰谷","杜隆塔尔","护手","蹄子","萨特","森金","尤拉莱克","无分趾"},ang={["class:Warrior"]="作为一名渴望声名的年轻战士，你可以猎杀灰谷的萨特，并委托森金村的部落训练师打造专用护甲，以此证明自己的武艺。",["race:Troll"]="身为巨魔，你也拥有暗矛工匠将黑暗或敌对能量转化为实用装备的本领。尤拉莱克从恶魔敌人身上汲取力量，免得这些力量白白浪费。"},sec={{t="汲取的力量",b="萨特出没于灰谷东北部遭到腐化的林地，吞噬古老森林中纯净的魔法。吞噬得越多，腐化就越会扭曲它们的恶魔身躯。它们的蹄子逐渐肿胀，天然的分趾随之消失，吸收的能量密集地储存在其中。技艺精湛的萨满祭司和制皮师能够提取这股不稳定的力量。"},{t="打造野蛮护甲",b="在杜隆塔尔海岸的森金村，巨魔护甲匠尤拉莱克将恶魔的腐化转化为部落勇士的力量。他收集那些吞噬过森林魔法的萨特的蹄子，抽取其中封存的魔力。随后，他将这股窃取来的力量注入野蛮护手，为即将面对卡利姆多严酷考验的年轻战士打造护甲。"}},faq={{q="这些萨特的蹄子为什么没有分趾？",a="灰谷的萨特吞噬森林中的神圣魔法，在汲取其力量的同时将其腐化。吞噬得最多的萨特会长出肿胀的蹄子，分趾随之消失，窃取来的能量密集地封存在蹄内。",al={"为什么没有分趾","无分趾的蹄子含义","肿胀的蹄子"}},{q="在哪里能找到完整的萨特之蹄？",a="灰谷东北部遭到腐化的废墟和受污染的林地中，萨特身上就有这些蹄子，萨提纳尔和夜道谷附近的萨特也不例外。",al={"哪里刷蹄子","萨特蹄子位置","哪些萨特掉落蹄子"}},{q="杜隆塔尔有谁需要这些蹄子？",a="尤拉莱克是杜隆塔尔南部海岸森金村的一名护甲匠，他需要七只蹄子，以便抽取其中储存的魔法。",al={"谁需要萨特蹄子","萨特蹄子任务给予者","蹄子的用途"}},{q="这些蹄子用来打造什么？",a="尤拉莱克从蹄子中抽取遭到腐化的森林之力，打造一副坚固且灌注魔力的野蛮护手。",al={"用来做什么","蹄子制作奖励","野蛮护手材料"}}},fp="19,148,13.338.0,25.329.0,36.215.0,41.140.0,34.131.0,34.110.0"}
P.entries["item:underbelly-whelp-scale"] = {n="雏龙的腹鳞",s="在止水湖南岸，雏龙的腹鳞在赤脊山的工匠之间流通。黑色雏龙身上长着这种柔韧的鳞片，当钱币短缺时，当地工匠便格外看重它们。",h="在止水湖南岸，雏龙的腹鳞在赤脊山的工匠之间流通。黑色雏龙身上长着这种柔韧的鳞片，当钱币短缺时，当地工匠便格外看重它们。",kw={"阿古斯","黑色雏龙","湖畔镇","赤脊山","斯纳弗莱尔","腹鳞","雏龙的腹鳞","弗纳·奥斯古"},ang={["faction:Alliance"]="身为联盟旅人，你知道湖畔镇孤立无援的守军依靠与艾尔文森林以物易物来维持装备供应。龙鳞这类需要冒险在当地获取的悬赏物资，有助于维持镇上的补给。",["profession:Blacksmithing"]="阿古斯和其他工匠看重这些鳞片的强韧。它们可以加工成衬里、握柄和专用的防护配件，比普通牛皮更加坚固。"},sec={{t="稀有的交易货物",b="黑龙的鳞片十分坚韧，但普通人面对一头成年黑龙，往往性命难保。在止水湖南岸，黑色雏龙在嶙峋的岩壁间筑巢。它们背上的鳞甲可能易碎或粗糙，而腹部下方较柔软的鳞片更易弯曲，也仍能提供防护。这些特性让雏龙的腹鳞在当地的交易中颇有价值。工匠们珍视它，债主也可以接受它来抵付钱币。"},{t="弗纳·奥斯古的债务",b="在湖畔镇，钱币短缺或商路受阻时，工匠们有时会以物易物。当地铁匠弗纳·奥斯古欠了闪金镇铁匠阿古斯一大笔债。这笔债源于一批从闪金镇运来的鞋。阿古斯偏爱稀有货物，因此弗纳·奥斯古依靠旅人收集雏龙的腹鳞。这些鳞片能帮他偿还欠款，让他的铁匠铺保有良好的信誉。"}},faq={{q="雏龙的腹鳞来自哪里？",a="雏龙的腹鳞取自黑色雏龙。它们栖息在赤脊山湖畔镇以南的岩崖和丘陵中，也可以从斯纳弗莱尔这样发育成熟的雏龙身上采集到这些鳞片。",al={"谁掉落雏龙的腹鳞","哪里获取雏龙鳞片","如何寻找雏龙鳞片"}},{q="弗纳·奥斯古为什么想要这些鳞片？",a="弗纳·奥斯古因一批运来的马蹄铁，欠了闪金镇铁匠阿古斯的钱。阿古斯接受龙鳞抵债，多余的鳞片还能供弗纳·奥斯古制作坚韧的护具。",al={"弗纳·奥斯古为什么需要鳞片","弗纳·奥斯古 雏龙的腹鳞"}},{q="为什么腹鳞比普通龙鳞更受青睐？",a="幼龙的腹鳞足够柔韧，可以裁剪、塑形，缝制成实用的护甲或加固装备。它们背上的鳞片往往过于坚硬、厚重或扭曲，难以用普通的制皮和锻造技艺加工。",al={"为什么要腹鳞","腹鳞有何特别之处"}},{q="赤脊山为什么会有黑色雏龙？",a="黑龙一直盘踞在燃烧平原与赤脊山交界处的炽热山峰和峭壁间。它的雏龙在高耸险峻、难以抵达的崖壁上孵化、成长。",al={"赤脊山为什么有龙","赤脊山 黑色雏龙"}}},fx={["4599dc10"]={q="什么是雏龙的腹鳞？",a="这是从游荡在赤脊山南部的黑色雏龙腹部采集的柔韧鳞片。成年龙背部的鳞片坚硬无比，而幼龙的腹鳞既异常坚韧，又足够柔软，能够由技艺娴熟的工匠加工，因此是珍贵的制造材料。",al={"什么是雏龙的腹鳞","雏龙的腹鳞物品","雏龙鳞片背景"}}},fp="22,168,22.404.0,13.408.0,43.205.0,41.205.0,63.226.0,47.189.0"}
P.entries["item:unidentified-ore"] = {n="未经化验的矿石",s="在狂风峭壁，未经化验的矿石引起了荆棘谷地精的注意。匹兹尼克取得了一份样本，交给了菲兹克斯，供其在安德麦研究。",h="在狂风峭壁，未经化验的矿石引起了荆棘谷地精的注意。匹兹尼克取得了一份样本，交给了菲兹克斯，供其在安德麦研究。",kw={"匹兹尼克","石爪山","安德麦","未经化验的矿石","荆棘谷地精","狂风峭壁","菲兹克斯"},ang={["profession:Engineering"]="地精工艺需要具有独特反应特性的原料，因此，荒野峭壁中尚未分类的矿石为富有创意的工匠提供了研究材料。",["profession:Mining"]="矿工在狂风峭壁各处都能找到普通矿脉，但这份样本超出了矿业常识的范畴，连Undermine最出色的鉴定师也对它兴趣盎然。"},sec={{t="狂风峭壁的奇异矿藏",b="荆棘谷地精在狂风峭壁大肆伐木、露天采矿，暴露出了石爪山脉中不寻常的矿层。矿场的新主管格雷苏下令大量开采这种奇异的金绿色矿石。遭到降职的地精工人匹兹尼克仍然忠于被解雇的前主管菲兹克斯，一边谋划脱离这伙人，一边设法取得了一份样本。他把样本交给了一名准备前往峭壁西侧山脊的旅行者。菲兹克斯打算将大部分矿石送往安德麦研究，留下一小部分为自己牟利。"}},faq={{q="未经化验的矿石是什么？",a="未经化验的矿石是荆棘谷地精在狂风峭壁作业时挖出的矿物样本。它的成分引起了菲兹克斯和安德麦采矿工程师的兴趣。",al={"这是什么矿石","未经化验的矿石背景故事","这是什么石头"}},{q="谁发现了矿石？",a="驻扎在狂风峭壁的荆棘谷地精成员匹兹尼克取得了这份样本。最近接连出了岔子，他担心遭到公司主管的惩罚，于是看到了逃离此地、另谋差事的机会。",al={"谁挖出了它","谁提供矿石","匹兹尼克矿石"}},{q="谁想研究这份样本？",a="在狂风峭壁西缘扎营的地精菲兹克斯收到了这份矿物。他打算将大部分送给安德麦的工程师，给自己留下一小部分。",al={"谁想要矿石","谁分析它","菲兹克斯矿石"}},{q="安德麦为什么在意这块石头？",a="地精四处寻找可用于制造炸药、冶金或燃烧的新材料。来自卡利姆多古老山脉的奇异矿物，或许能为贸易集团带来工业和商业上的潜力。",al={"安德麦的兴趣","地精为什么想要它"}}},fx={["4673b3b7"]={q="未经化验的矿石来自哪里？",a="这份样本来自石爪山脉狂风峭壁的荆棘谷地精矿坑。矿坑的新头目格伦佐·扳钳命令大量开采一种奇异的金绿色矿石。匹兹尼克仍忠于被解雇的前任老板齐兹·菲兹克斯，于是偷偷开采了一份样本，准备交给齐兹。",al={"未经化验的矿石的来历","在哪里发现未经化验的矿石","矿石来自哪里"}}},fp="16,155,29.531.0,29.142.0,18.194.0,35.184.0,41.192.0"}
P.entries["item:unrefined-ore-sample"] = {n="未精炼的矿石样本",s="千针石林的一种奇特矿石引起了部落的注意。塔特纳克·钢炉想要一份样本，判断这种未经提炼的矿物能否强化大酋长萨尔麾下军队的武器。",h="千针石林的一种奇特矿石引起了部落的注意。塔特纳克·钢炉想要一份样本，判断这种未经提炼的矿物能否强化大酋长萨尔麾下军队的武器。",kw={"陶拉祖营地","吉比斯尼克","砂齿","狗头人","矿石","塔特纳克·钢炉","千针石林","未精炼的矿石样本"},ang={["faction:Horde"]="身为部落的一员，你知道卡利姆多南部每一处新发现的矿脉，都可能帮助萨尔建立不久的国家在巩固边境的同时，自行供应武器。",["profession:Blacksmithing"]="身为铁匠，你能理解塔特纳克的苦恼。测试新矿石的强度和耐久性，能帮助铁匠为战士打造在战斗中不会碎裂的刀剑。"},sec={{t="害兽挖出的矿石",b="在贫瘠之地以南，砂齿狗头人在千针石林的峡谷峭壁下挖掘岩石。北返的旅行者在被杀死的害兽身上发现了一种奇特的矿物，与卡利姆多常见矿脉中的矿物不同。他们拒绝将自己的收获交给部落。那些在地下深处挖掘和勘测的狗头人，身上带着从挖掘处采出的原矿块。"},{t="为大酋长锻造",b="在陶拉祖营地，武器匠塔特纳克·钢炉奉大酋长萨尔之命，改良部落的武器。旅行者隐瞒矿藏消息的行为让他愤怒；他认为，他们的拒绝是对部落战争事业的侮辱。有了原矿样本，塔特纳克便能测试这种矿物的强度和韧性，再将其熔炼，锻造一把样品刀剑，交由奥格瑞玛认可。"}},faq={{q="这种未精炼的矿石来自哪里？",a="砂齿狗头人从贫瘠之地以南的千针石林峡谷深处带出这种矿石。他们的掘地工、勘测员和首领吉比斯尼克都住在那里。",al={"矿石位置","哪里获取未精炼的矿石样本","谁掉落未精炼的矿石"}},{q="塔特纳克·钢炉为什么想要样本？",a="塔特纳克奉大酋长之命改良部落的武器。他想检验并熔炼这种矿石，看看能否用它锻造出更坚固的武器。",al={"塔特纳克为何需要矿石","陶拉祖矿石用途","矿石有什么用"}},{q="那些旅行者为什么不愿交出矿石？",a="从千针石林过来的部落旅行者在一名狗头人身上发现了这种矿石，将其留作战利品或稀罕物。即使有人请他们支援部落的锻造工作，他们也拒绝出售矿石。",al={"旅行者是谁","旅行者矿石贫瘠之地"}},{q="贫瘠之地有这种矿石吗？",a="没有。陶拉祖营地位于贫瘠之地南部，但矿石必须从更南边的千针石林的狗头人身上取得。",al={"贫瘠之地的矿石","贫瘠之地能否开采这种矿石"}}},fp="20,150,19.333.0,24.399.0,40.159.0,45.162.0,49.189.0,42.124.0"}
P.entries["item:ur-s-treatise-on-shadow-magic"] = {n="乌尔的暗影魔法研究论文",s="暴风城的法师曾严加看管《乌尔的暗影魔法研究论文》，唯恐书中的知识招致灾祸。如今，这部被莫甘斯盗走的典籍藏在伊尔加拉之塔中。",h="暴风城的法师曾严加看管《乌尔的暗影魔法研究论文》，唯恐书中的知识招致灾祸。如今，这部被莫甘斯盗走的典籍藏在伊尔加拉之塔中。",kw={"安多玛斯","达拉然","伊尔加拉","莫甘斯","赤脊山","密室","暗影魔法","典籍","论文","ur"},ang={["class:Mage"]="作为暴风城的法师，在一名同僚屈服于黑暗诱惑之后，你协助管控这篇论文，维护密室的安全。",["faction:Alliance"]="作为联盟的旅者，你知道莫甘斯盘踞在赤脊山，威胁着王国的东部边疆。取回这件强大的神器，关乎暴风城的安全。"},sec={{t="危险的遗产",b="来自达拉然的Ur撰文探讨了暗影魔法，以及它潜移默化的腐化本质。暴风城巫师圣殿的法师担心，这些法术会给毫无防备的人带来灭顶之灾，因此封印了这部典籍，禁止他人阅读。莫甘斯投身黑暗法术后，遭到暴风城法师团体的放逐，便带着典籍向东逃入赤脊山。他在那里以伊尔加拉之塔为据点。"},{t="封印中的秘密",b="高阶巫师安多玛斯担心莫甘斯会掌握Ur著作中的黑暗知识。他派冒险者前往伊尔加拉之塔，取回这部典籍。莫甘斯虽已深陷禁忌魔法，暴风城法师团体施加的封印却依然牢固。直到被取回时，这本书都未曾被打开。"}},faq={{q="Ur是谁？",a="Ur是一位来自达拉然、备受尊敬的巫师和学者。他研究异位面生物、黑暗法术，以及包括暗影法术在内的奥秘魔法。",al={"这本书是谁写的","达拉然的ur","ur是谁"}},{q="这篇论文为何如此危险？",a="暗影魔法会腐化未经训练的施法者，带来灾难与毁灭。高阶巫师安多玛斯告诫人们，不要探究其中的禁忌奥秘。",al={"这本书为何危险","这本书有什么作用","暗影魔法的危险"}},{q="谁盗走了《乌尔的暗影魔法研究论文》？",a="莫甘斯因沉迷黑暗魔法而被暴风城的巫师组织放逐，随后盗走了这部典籍。他向东逃到了赤脊山的伊尔加拉之塔。",al={"谁偷走了书","莫甘斯盗走的书","谁拿走了论文"}},{q="莫甘斯成功读到论文了吗？",a="没有。暴风城的法师封印了这部典籍，防护结界始终牢不可破。在典籍被取回之前，莫甘斯一直未能将它打开。",al={"莫甘斯读过了吗","封印是否牢固","书被打开了吗"}},{q="这与《乌尔之书》是同一部著作吗？",a="两部著作均出自Ur之手，且关系密切。《乌尔之书》是一部内容更广泛的魔法典籍，存放在影牙城堡的废墟中。《暗影魔法研究论文》似乎是其中的节选，或是一部专门探讨暗影法术的著作。",al={"与乌尔之书的区别","乌尔之书 暗影之牙","这是乌尔之书吗"}}},fx={["9052da59"]={q="乌尔的暗影魔法研究论文是什么？",a="这是一本蕴含强大力量、受到严密看管的典籍，详述了暗影魔法的禁忌奥秘。暴风城的巫师圣殿法师用防护结界守护着它，书中记载着强大的秘术知识，一旦解除封印，便可能给鲁莽研读它的人带来毁灭与灾难。",al={"ur的论文是什么","乌尔的暗影魔法研究论文","暗影魔法研究论文是什么"}},["0481e4cc"]={q="乌尔的暗影魔法研究论文来自哪里，是谁写的？",a="这本书出自达拉然才华横溢的肯瑞托法师Ur之手，这位学者毕生致力于研究黑暗法术、异界存在和暗影魔法。他那些危险的著作最终流传到了暴风城，城中的法师将这篇论文封存起来，以免未经训练的人窥见其中的秘密。",al={"谁写了ur的论文","ur的论文来自哪里","乌尔的暗影魔法研究论文来源"}},["9d095b57"]={q="为什么有人想要乌尔的暗影魔法研究论文？",a="受到黑暗力量诱惑的施法者渴求这篇论文中强大的奥术与暗影秘密。叛逃法师莫甘斯将它偷走，以增强自己的秘术力量，而高阶巫师安多玛斯和暴风城的法师急切地想要找回它，确保封印完好，将其中的危险牢牢封存。",al={"为什么有人想要这篇论文","为什么法师想要ur的论文","为什么莫甘斯想要这篇论文"}}},fp="29,167,18.397.0,18.299.1,11.140.0,33.143.0,40.147.0,41.113.1,40.218.0"}
P.entries["item:urgent-message"] = {n="紧急信件",s="紧急信件是卫兵穆赫·月角写下的一封密封急报，警告乱风岗，千针石林各地的半人马暴行正愈演愈烈。旅人将信件带下峡谷，向牛头人驻军发出警报：他们的补给线和斥候小队正面临迫在眉睫的威胁。",h="紧急信件是卫兵穆赫·月角写下的一封密封急报，警告乱风岗，千针石林各地的半人马暴行正愈演愈烈。旅人将信件带下峡谷，向牛头人驻军发出警报：他们的补给线和斥候小队正面临迫在眉睫的威胁。",kw={"卫兵穆赫·月角","半人马","峭壁卫兵图林·长角","乱风岗","升降梯","恐怖图腾","千针石林","紧急信件"},ang={["faction:Horde"]="这封信凸显了部落在卡利姆多南部补给线的脆弱，那里孤立的哨站依靠信使和卫兵，才能在险恶的环境中生存。",["race:Tauren"]="对牛头人而言，这封信痛苦地提醒着他们与半人马之间由来已久的血仇，也唤起了他们对恐怖图腾同胞日益加深的不安。"},sec={{t="高处传来的警告",b="紧急信件由卫兵穆赫·月角写于从贫瘠之地通往千针石林的升降梯附近，是旅人穿越边界的第一道防线。卫兵穆赫·月角监视着下方嶙峋的峡谷，那里好战的半人马部族再度开始无休止地袭击部落旅人。这封信送往乱风岗高处的峭壁卫兵图林·长角手中，警告日益猖獗的袭击者已逼近重要道路，敦促当地驻军准备应对持久冲突，同时提防其他威胁，例如行事难以预料的恐怖图腾氏族。"},{t="峡谷底部的血案",b="当信件送到乱风岗巍峨台地上的峭壁卫兵图林·长角手中时，营地最深的恐惧得到了证实。半人马的进攻已不再只是边境上的小规模冲突；劫掠者伏击了一支穿越谷底的重要补给商队，将整支队伍屠戮殆尽。这封急报迫使牛头人首领立即从戒备防守转向主动报复，组织反击，力求在乱风岗与卡利姆多其他地区的联系彻底中断之前，平定这些四处劫掠的部族。"}},faq={{q="紧急信件里写了什么？",a="信中详述了千针石林各地半人马袭击骤增的情况，警告旅途中的队伍和道路正面临迫在眉睫的危险，并敦促乱风岗备战。",al={"信里写了什么","紧急信件内容","信件讲什么"}},{q="这封信是谁写的，又是写给谁的？",a="信件由驻守在贫瘠之地通往下方的升降梯处的卫兵穆赫·月角起草，直接写给乱风岗的指挥官峭壁卫兵图林·长角。",al={"谁写了紧急信件","紧急信件寄信人","谁收到紧急信件"}},{q="半人马为何袭击补给商队？",a="半人马部族长期以来一直与牛头人争夺卡利姆多中部的干旱土地。他们袭击谷底的商队，掠夺重要物资，并阻止部落安全穿越千针石林。",al={"半人马为何攻击","千针石林半人马动机","半人马为何劫掠"}},{q="斥候对恐怖图腾发出了什么警告？",a="卫兵穆赫·月角告诫所有携带急报的信使远离附近的恐怖图腾氏族，并指出他们的战士对其他牛头人的态度愈发冷漠，举止也越发可疑。",al={"恐怖图腾警告","为何避开恐怖图腾","恐怖图腾举止反常"}}},fx={d8ee5ef2={q="什么是紧急信件？",a="紧急信件是一封由卫兵穆赫·月角在千针石林边境附近写下并封好的信函。信中报告了峡谷底部半人马的敌意骤然加剧，提醒牛头人当局，威胁当地旅人和补给线的危险正在不断扩大。",al={"什么是紧急信件","紧急信件物品","紧急公文"}},["1e5b60e5"]={q="为什么需要把紧急信件送到乱风岗？",a="峭壁卫兵图林·长角负责乱风岗的防御，需要立即掌握敌人的动向。这封信警告他，半人马劫掠者的袭击愈发频繁，好让他及时采取果断行动，避免更多补给车队和巡逻队遭到伏击和屠杀。",al={"为什么要递送紧急信件","谁需要紧急信件","峭壁卫兵图林·长角为什么需要信件"}}},fp="14,129,26.447.0,29.376.1,38.166.0,43.143.0,46.207.0,57.134.0"}
P.entries["item:valdred-s-hands"] = {n="瓦德雷的手掌",s="在银松森林南部，瓦德雷·莫莱被砍下的双手成了拉林夫·安迪恩为亡妻复仇的凭证。拉林夫·安迪恩在幽暗城索要这份骇人的战利品。",h="在银松森林南部，瓦德雷·莫莱被砍下的双手成了拉林夫·安迪恩为亡妻复仇的凭证。拉林夫·安迪恩在幽暗城索要这份骇人的战利品。",kw={"丈夫的复仇","黛丽娅","格雷迈恩之墙","拉林夫·安迪恩","银松森林","瓦德雷","瓦德雷·莫莱","瓦德雷的手掌"},ang={["race:Undead"]="瓦德雷的手掌展现了被遗忘者冷酷而渴望复仇的本性。他们无法感受寻常的悲伤，往往将失去所爱之人的痛苦化作经久不散、难以释怀的怨恨。"},sec={{t="背叛留下的骇人战利品",b="瘟疫吞噬了洛丹伦，也终结了瓦德雷·莫莱与拉林夫·安迪恩的友谊。瓦德雷杀害了拉林夫·安迪恩的妻子黛丽娅。拉林夫·安迪恩死后成为了被遗忘者的一员，声称自己已无法真正感到悲伤。然而，他仍然渴望复仇。当瓦德雷越过格雷迈恩之墙，向南逃往吉尔尼斯时，拉林夫·安迪恩派出一名使者追赶这位昔日的朋友。他要求砍下瓦德雷的双手，作为复仇已成的凭证。"},{t="苦涩的追忆",b="拉林夫·安迪恩收到瓦德雷的手掌后，便交出了黛丽娅的雕花戒指，称这枚戒指已毫无意义。对他而言，黛丽娅已死去太久，遗物再也无法带来慰藉。他留下了那双手，让它们成为背叛与复仇的冰冷印记。"}},faq={{q="瓦德雷·莫莱是谁？",a="瓦德雷·莫莱曾是拉林夫·安迪恩的挚友。他杀害了拉林夫的妻子黛丽娅，背叛了这份友谊，随后试图向南逃往吉尔尼斯。",al={"瓦德雷是谁","瓦德雷·莫莱背景故事","瓦德雷的故事"}},{q="拉林夫·安迪恩为什么偏偏要瓦德雷的手掌？",a="拉林夫想要瓦德雷的手掌，因为正是这双手扼死或击杀了他的妻子。他留下这双手，作为朋友背叛自己以及自己完成复仇的实物战利品。",al={"为什么要双手","为什么要瓦德雷的手掌","拉林夫的双手战利品"}},{q="在哪里能找到瓦德雷·莫莱？",a="瓦德雷位于银松森林南部，靠近格雷迈恩之墙，正试图逃入吉尔尼斯。",al={"瓦德雷在哪里","瓦德雷的位置","瓦德雷·莫莱刷新地点"}},{q="把双手带到幽暗城后会怎样？",a="拉林夫将双手留在幽暗城，作为自己复仇的永久印记。他还丢弃了黛丽娅的雕花戒指，视其为毫无意义的小饰物。",al={"拉林夫如何处置双手","交付瓦德雷的手掌"}}},fp="15,165,29.426.0,20.251.1,22.165.0,59.192.0,29.95.0,59.138.1"}
P.entries["item:velinde-s-journal"] = {n="维林德的日记",s="维琳德·星歌的私人日记记录了她的职责，以及她离开达纳苏斯的谜团。这位暗夜精灵女祭司的日记存放在哨兵营房中。",h="维琳德·星歌的私人日记记录了她的职责，以及她离开达纳苏斯的谜团。这位暗夜精灵女祭司的日记存放在哨兵营房中。",kw={"达纳苏斯","哨兵","塞恩提尔·刃纹","贸易区","维琳德·星歌","维林德的日记","维林德的钥匙","维琳德的储物箱"},ang={["class:Priest"]="对牧师而言，维琳德的秘密职责和失踪，揭示了The Sisterhood of Elune正面临的严峻考验。",["race:NightElf"]="对暗夜精灵而言，维琳德的神秘离去牵动着达纳苏斯的领导层。守卫Kaldorei首都的Sentinels对此深感忧虑。"},sec={{t="女祭司的记录",b="暗夜精灵女祭司维琳德·星歌离开达纳苏斯时，她的物品被锁在贸易区哨兵营房的一个储物箱里。其中就有她的私人日记，记载着她的责任与义务。哨兵敬重维琳德，相信她是去处理私事了。日记的内容表明，她这次原因不明的离去，比他们起初以为的更令人不安。"}},faq={{q="在哪里可以找到维林德的日记？",a="维林德的日记就在达纳苏斯贸易区哨兵营房中她的箱子里。穿过与锁甲店相连的上层桥梁，就能到达那座建筑。",al={"日记位置","维琳德日记在哪","维琳德的储物箱位置"}},{q="维琳德·星歌是谁？",a="维琳德·星歌是一位受人敬重的暗夜精灵女祭司，深受哨兵信任。她突然悄然离开了达纳苏斯，留下了自己的储物箱和随身物品。",al={"维琳德是谁","维琳德的故事"}},{q="哨兵为什么关心她的日记？",a="哨兵相信维琳德是出于正当的个人原因离开达纳苏斯，并期待她归来。她的文字透露出，她的失踪背后另有不祥的隐情，哨兵需要进一步调查。",al={"哨兵为什么要日记","日记里有什么"}},{q="谁请你取回日记？",a="当你带着从梅尔莎的魔法书中获悉的信息前去接洽时，达纳苏斯的哨兵塞恩提尔·刃纹会给予许可，并将维琳德箱子的钥匙交给你。",al={"谁给任务","塞恩提尔·刃纹是谁"}}},fp="17,160,20.402.0,33.179.0,25.172.0,44.215.0,37.172.0"}
P.entries["item:velinde-s-key"] = {n="维林德的钥匙",s="在达纳苏斯，维林德的钥匙守护着一位失踪女祭司的文字。塞恩提尔·刃纹会将它托付给那些能拿出证据、证明自己有意查明维琳德·星歌下落的人。",h="在达纳苏斯，维林德的钥匙守护着一位失踪女祭司的文字。塞恩提尔·刃纹会将它托付给那些能拿出证据、证明自己有意查明维琳德·星歌下落的人。",kw={"达纳苏斯","储物箱","哨兵营房","塞恩提尔·刃纹","维琳德·星歌","维琳德的私人物品","维林德的日记","维林德的钥匙"},ang={["class:Priest"]="身为牧师，你追寻着一位虔诚的Elune姐妹留下的踪迹，她的道路转向了孤独而令人不安的方向。",["race:NightElf"]="身为暗夜精灵，你接触到了一位备受尊敬的女祭司留下的物品，她对Elune和族人的忠诚从未受到质疑。"},sec={{t="信任的凭证",b="塞恩提尔·刃纹在达纳苏斯保管着维林德的钥匙。这把朴素的钥匙锁着女祭司维琳德·星歌的私人物品，它们存放在贸易区上方哨兵营房的一只储物箱中。维琳德毫无征兆地离开了暗夜精灵的领地，她的物品便被收存起来。刃纹只会将钥匙交给那些能拿出确凿证据、证明自己有意查明她下落的人，比如在梅尔莎迪斯之书中发现的线索。"},{t="开启往昔",b="维琳德·星歌的钥匙能打开她的储物箱，里面的日记记载着她的职责与纷扰的思绪。哨兵一直以为她是为私事离开，终有一天会回来。她留下的文字开始揭示，她远行所参与的那次探险背后，藏着一个更加阴暗、更加令人费解的谜团。"}},faq={{q="维林德的钥匙能打开什么？",a="维林德的钥匙能打开维琳德的箱子，那是达纳苏斯哨兵营房内的一只箱子。它位于贸易区，穿过一座桥后便可在楼上找到。",al={"维林德的钥匙使用地点","维琳德储物箱","这能打开哪个箱子"}},{q="谁会把钥匙交给你？",a="塞恩提尔·刃纹是一名驻守达纳苏斯的哨兵，在调查维琳德失踪一事时，他会将钥匙托付给你。",al={"谁保管维林德的钥匙","维林德的钥匙获取地点"}},{q="维琳德·星歌是谁？",a="维琳德·星歌曾是一位备受尊敬的暗夜精灵女祭司，深受哨兵信任。她突然为自己的私事离开，将随身物品留在了达纳苏斯。",al={"维琳德是谁","维琳德的背景故事"}},{q="她上锁的箱子里有什么？",a="维林德的日记就放在储物箱中。日记记载了她的职责，也揭示了是什么促使她离开暗夜精灵的领地。",al={"维琳德的储物箱里有什么","维琳德储物箱中的物品"}}},fp="13,143,15.439.0,18.280.1,29.155.0,22.116.0,24.161.0,38.128.0"}
P.entries["item:venomtail-antidote"] = {n="毒尾蝎解毒剂",s="在杜隆塔尔，急需毒尾蝎解毒剂来挽救一名身中蝎毒的斥候。考格汉正在奥格瑞玛为林纳格配制解毒剂，而林纳格此刻正中毒倒在杜隆塔尔西北边境附近。",h="在杜隆塔尔，急需毒尾蝎解毒剂来挽救一名身中蝎毒的斥候。考格汉正在奥格瑞玛为林纳格配制解毒剂，而林纳格此刻正中毒倒在杜隆塔尔西北边境附近。",kw={"解毒剂","暗影裂口","解药","杜隆塔尔","考格汉","奥格瑞玛","林纳格","蝎子","毒尾蝎"},ang={["faction:Horde"]="身为部落的一员，你要面对杜隆塔尔严酷的沙漠。要救下林纳格，荒野中的斥候与城里的药剂师必须迅速协作。",["race:Troll"]="身为巨魔，你深知自尊有多么强烈。林纳格宁愿冒着独自死在荒野中的危险，也不愿因败给一只蝎子而在森金村遭人当面嘲笑。"},sec={{t="与剧毒争分夺秒",b="杜隆塔尔的毒尾蝎只需深深一蜇，就能在一个小时内夺走一名战士的性命。巨魔斥候林纳格在西北边境附近中了毒，远离援助。他唯一的生机，是奥格瑞玛暗影裂口的药剂师考格汉配制的解毒剂。"},{t="考格汉的解药",b="要找到考格汉，就得深入奥格瑞玛地下。他熟知沙漠中的毒素和药性猛烈的解药，配制了一小瓶药剂，要在毒素致命之前将其清除。这剂药能化解毒素，让林纳格免于屈辱地死在荒野中。考格汉仍要求这名斥候完成更多试炼和狩猎，以弥补自己的疏忽。"}},faq={{q="毒尾蝎解毒剂有什么用途？",a="毒尾蝎解毒剂能化解毒尾蝎的致命毒素。在杜隆塔尔西北边境附近中毒的巨魔林纳格，需要在毒发身亡前得到它。",al={"解毒剂用途","谁需要毒尾蝎解毒剂","毒尾蝎解毒剂有什么作用"}},{q="谁配制毒尾蝎解毒剂？",a="考格汉在奥格瑞玛地下的暗影裂口配制解毒剂。他熟知杜隆塔尔的蝎毒，也知道如何化解蝎子蜇刺造成的中毒。",al={"谁配制解毒剂","哪里获取毒尾蝎解毒剂","考格汉解毒剂"}},{q="为什么获取解毒剂时必须争分夺秒？",a="毒尾蝎的毒素能在蜇伤后的一个小时内夺走林纳格的性命。你必须拿到解毒剂，迅速穿越杜隆塔尔将它送回，才能救他一命。",al={"为什么急需解毒剂","林纳格还能活多久","毒尾蝎毒发时间"}},{q="为什么林纳格不愿去森金村求助？",a="林纳格因败在一只普通蝎子手下而感到羞耻。他担心自己若是虚弱地回去，森金村的族人会嘲笑他的粗心和愚蠢。",al={"为什么不去森金村","林纳格的自尊","为什么躲在杜隆塔尔"}}},fp="18,162,24.249.0,15.326.0,40.168.0,33.136.0,52.140.0,55.158.0"}
P.entries["item:venomtail-poison-sac"] = {n="毒尾蝎的毒囊",s="在杜隆塔尔，蝎毒能让猎人濒临死亡，而蝎子的毒囊中也含有炼金师配制解药所需的成分。",h="在杜隆塔尔，蝎毒能让猎人濒临死亡，而蝎子的毒囊中也含有炼金师配制解药所需的成分。",kw={"解毒剂","杜隆塔尔","考格汉","毒","林纳格","毒囊","蝎子","毒尾"},ang={["class:Hunter"]="身为猎人，你可以将林纳格的不幸当作警示：不了解危险野兽的毒液，也不携带解药就去追猎它们，可能会让你丢掉性命。",["faction:Horde"]="身为杜隆塔尔的一名年轻部落冒险者，你会了解到，毫无准备就贸然闯入这片红色荒原的人，可能会死于当地的毒素。"},sec={{t="致命毒素与解药",b="蝎子游荡在杜隆塔尔的红色岩石之间，其中包括毒尾蝎、堕落蝎和死亡毒蝎。它们尾部的毒囊储存着发作迅速的毒液，若不及时治疗，即使身经百战的战士也可能倒下。这些毒囊也含有炼金师配制解毒剂所需的主要成分。猎人林纳格在奥格瑞玛城外被蝎子蜇伤后，当地的炼金师需要四个新鲜的毒囊来配制解药，中和他血管中的毒液。"}},faq={{q="哪些生物带有这些毒囊？",a="杜隆塔尔的蝎子带有这些毒囊，主要是奥格瑞玛附近的毒尾蝎，此外还有堕落蝎和稀有的死亡毒蝎。",al={"谁掉落毒尾蝎的毒囊","哪里获取毒尾蝎的毒囊","哪些蝎子有毒囊"}},{q="毒囊有什么用途？",a="奥格瑞玛的考格汉用这些毒囊提炼一种特制解毒剂，急需用它来救治林纳格。林纳格在准备不足的情况下外出狩猎，被蜇伤后中了毒。",al={"毒尾蝎的毒囊用途","为何需要毒尾蝎的毒囊"}},{q="谁能用这些毒囊配制解毒剂？",a="奥格瑞玛的考格汉知道如何从四个完整毒囊的原始毒液中提炼出解药，在毒素致命之前救人一命。",al={"谁配制解毒剂","哪里交付毒尾蝎毒囊","考格汉 毒尾蝎"}}},fp="20,119,29.470.0,39.152.0,32.159.0,42.137.0"}
P.entries["item:venture-co-documents"] = {n="风险投资公司文件",s="在莫高雷东部，风险投资公司文件证实了牛头人土地上存在非法露天采矿活动。这些文件从一支被毁商队中的箱子里找回，详细记载了公司的活动。",h="在莫高雷东部，风险投资公司文件证实了牛头人土地上存在非法露天采矿活动。这些文件从一支被毁商队中的箱子里找回，详细记载了公司的活动。",kw={"摩林·云行者","莫高雷采矿","被破坏的货车","风险投资公司文件","荆棘谷地精"},ang={["profession:Mining"]="身为矿工，你能看出与文件装在一起的原矿样本为何如此重要：它们表明，这片山麓蕴藏着丰富、尚未开采的矿脉，正待挖掘。",["race:Tauren"]="身为牛头人，你知道地精的机械玷污了Earth Mother的神圣土地。这些文件能帮助长者确认亵渎的范围，并发起报复性打击。"},sec={{t="掠夺的证据",b="风险投资公司文件是在一辆遭到洗劫的货车里发现的，就放在采出的矿石上。这些账册显示，这个由地精领导的财团已悄然在莫高雷东部山麓设立了钻探和采矿哨站。在卡利姆多各地，荆棘谷地精以无情的滥伐和毫无节制的挖掘而闻名。摩林·云行者和牛头人先遣斥候利用这些缴获的记录，评估他们神圣的祖传平原所面临的威胁，并召集猎人驱逐入侵者。"}},faq={{q="风险投资公司文件里记载了什么？",a="这些文件详细记载了荆棘谷地精在莫高雷东部的采矿和资源开采活动。文件揭露，这家地精企业正在开采并运走当地的矿产资源。",al={"风险投资公司文件内容","风险投资公司文件是什么","文件里写了什么"}},{q="这些文件是在哪里发现的？",a="这些文件是在血蹄村以东的被破坏的货车所在地发现的，装在遭到洗劫的货车残骸中一个密封的荆棘谷地精箱子里。",al={"在哪里找文件","风险投资公司文件位置","被破坏的货车箱子"}},{q="谁需要查看这些文件？",a="把文件交给摩林·云行者，他是一名驻守在血蹄村以东主路旁的牛头人猎人。他守护着莫高雷的安全。",al={"文件交给谁","交付风险投资公司文件","摩林·云行者文件"}},{q="荆棘谷地精为什么在莫高雷采矿？",a="荆棘谷地精为了牟利而采矿，四处寻找富饶的矿脉和未经开发的土地，将贵重矿石开采殆尽。他们丝毫不顾与原住民订立的条约、信仰习俗或自然环境。",al={"地精为什么在莫高雷","荆棘谷地精在莫高雷的目的","荆棘谷地精为什么挖掘"}}},fp="21,172,24.448.0,42.171.0,38.151.0,30.149.0,46.191.0"}
P.entries["item:venture-co-engineering-plans"] = {n="风险投资公司工程计划书",s="在狂风峭壁，风险投资公司工程计划书揭示了伐木机械的构造。联盟特工从地精的伐木场取回这些图纸。",h="在狂风峭壁，风险投资公司工程计划书揭示了伐木机械的构造。联盟特工从地精的伐木场取回这些图纸。",kw={"隐秘行动","峭壁湖","工程计划书","加克希姆·尘链","石爪山","风险投资公司.","狂风峭壁"},ang={["profession:Engineering"]="作为一名工程师，你可以研究荆棘谷地精那些粗暴、消耗大量资源的机器，从中获得有关重型工业机械的见解。",["race:Gnome"]="作为一名侏儒工匠，夺取地精对手的图纸意味着赢得智慧上的胜利，也能从中获取可供改进利用的工业构想。"},sec={{t="工业机密",b="在峭壁湖南面的伐木场里，风险投资公司工程计划书展示了伐木机械的构造、优势与缺陷。荆棘谷地精用这些机械砍光石爪山的森林，浓烟则笼罩着狂风峭壁。"},{t="侏儒谍报",b="侏儒工程师加克希姆·尘链指挥着针对荆棘谷地精伐木设施的秘密行动，并设法取得计划书。炸药能立即破坏伐木场，而图纸能让联盟工匠利用地精设备的弱点，并改进其设计，用于联盟的工程。"}},faq={{q="风险投资公司工程计划书在哪里？",a="风险投资公司工程计划书位于石爪山脉峭壁湖南面的狂风峭壁，就在荆棘谷地精的主要伐木场内。",al={"哪里能找到工程计划书","石爪山计划书位置","计划书在哪里"}},{q="谁想要这些工程计划书？",a="加克希姆·尘链是一名在石爪山脉协调秘密行动的联盟侏儒，他派遣特工去取回计划书。",al={"谁需要计划书","工程计划书交给谁","加克希姆·尘链计划书"}},{q="这些蓝图为何对联盟如此重要？",a="图纸揭示了荆棘谷地精伐木机械的缺陷，帮助特工拆毁这些机械，也为联盟侏儒提供了可供改进并用于自身发明的工业设计。",al={"为什么要偷计划书","计划书有什么用"}},{q="窃取这些计划书与什么行动有关？",a="取回计划书是隐秘行动 - 阿尔法的首要目标。特工还会在场地各处安放雷管，但带回蓝图才标志着行动成功。",al={"隐秘行动 - 阿尔法目标","这是哪个任务需要的"}}},fx={["605bae91"]={q="什么是风险投资公司工程计划书？",a="这些文件包含风险投资公司工程师在石爪山脉绘制的详细技术图纸和蓝图。它们保存在峭壁湖附近的伐木场内，描述了公司用来砍伐狂风峭壁森林的机器和工业装置的建造、线路布置及运作设计。",al={"什么是风险投资公司工程计划书","风险投资公司工程计划书","风险投资公司计划书"}},a84a85f7={q="风险投资公司工程计划书从何而来？",a="这些计划书源自风险投资公司在狂风峭壁的工业活动。公司工程师和操作员为监督伐木与机械建造而制定了这些计划，并将其妥善保存在峭壁湖以南不远处的主伐木场内，之后成为联盟秘密行动人员的目标。",al={"工程计划书从何而来","谁制作了风险投资公司工程计划书","风险投资公司计划书来源"}}},fp="29,157,18.275.0,17.294.1,52.157.0,34.127.0,51.185.0,47.175.0"}
P.entries["item:venture-co-letters"] = {n="风险投资公司函件",s="在狂风矿洞，风险投资公司函件记载着这家财团在石爪山脉的活动。这些函件是在以爆炸制造混乱的掩护下取回的，为暗夜精灵哨兵提供了地精行动的情报。",h="在狂风矿洞，风险投资公司函件记载着这家财团在石爪山脉的活动。这些函件是在以爆炸制造混乱的掩护下取回的，为暗夜精灵哨兵提供了地精行动的情报。",kw={"凯拉·影矛","哨兵","石爪山脉","风险投资公司","风险投资公司函件","狂风峭壁","狂风矿洞"},ang={["faction:Alliance"]="联盟斥候对荆棘谷地精展开秘密行动，保护暗夜精灵在石爪山的领地免遭工业开发的侵害。",["race:NightElf"]="地精的伐木机器亵渎着石爪山的荒野。有关荆棘谷地精阴谋的情报对Sentinels至关重要。"},sec={{t="工业情报",b="荆棘谷地精的机器砍伐树木，露天开采狂风峭壁周围的古老林地。联盟特工暗中实施破坏，引开工人的注意，潜入狂风矿洞。他们取回的函件包含这家公司在当地活动的私人通信和后勤记录。哨兵首领可以从这些记录中了解亵渎者如何安排劳工和补给线。"},{t="送交哨兵",b="函件从狂风矿洞深处被带出，送到哨兵指挥官凯拉·影矛手中。在石爪山各地，地精亵渎者和部落的入侵都让哨兵承受着压力。窃取的通信能帮助他们预判荆棘谷地精的下一步行动，保护这片神圣山脉中尚未遭到破坏的地方。"}},faq={{q="风险投资公司函件是什么？",a="风险投资公司函件是荆棘谷地精存放在石爪山脉狂风矿洞的内部通信和行动记录。",al={"风险投资公司函件","函件是什么","石爪山函件"}},{q="在哪里能找到函件？",a="函件就在狂风矿洞内的风险投资公司文件中，矿洞位于狂风峭壁的东端。",al={"函件在哪里","函件位置","狂风矿洞函件"}},{q="谁想要这些函件？",a="侏儒特工加克希姆·尘链负责指挥窃取函件的行动，函件随后会送交当地暗夜精灵哨兵的首领凯拉·影矛。",al={"函件交给谁","谁想要函件","交付函件"}},{q="哨兵为什么需要这些通信？",a="哨兵为阻止石爪山的伐木和挖掘活动而战。函件揭示了荆棘谷地精的计划和重点，帮助守卫者制定应对方案。",al={"哨兵为何想要函件","哨兵关注之事"}}},fx={["52f3029e"]={q="风险投资公司函件从何而来？是谁写的？",a="这些文件来自风险投资公司位于狂风峭壁最东端的狂风矿洞采矿行动。它们是现场文件中的公司内部函件，由公司的地区操作员和主管撰写，用于协调其在石爪山脉各地大肆开采与伐木的行动。",al={"风险投资公司函件来源","谁写了风险投资公司函件","这些函件从何而来"}}},fp="19,203,23.390.0,25.299.1,33.146.0,28.104.0,24.156.0,46.169.0"}
P.entries["item:verdant-note"] = {n="绿色便笺",s="在纳拉其营地，绿色便笺召唤年轻的牛头人德鲁伊开始训练。这封代加尔特·迷雾行者送来的便笺，指引他们走向大地之母的仪式。",h="在纳拉其营地，绿色便笺召唤年轻的牛头人德鲁伊开始训练。这封代加尔特·迷雾行者送来的便笺，指引他们走向大地之母的仪式。",kw={"纳拉其营地","德鲁伊","大地母亲","加尔特·迷雾行者","莫高雷","红云台地","绿色便笺"},ang={["class:Druid"]="身为德鲁伊，绿色便笺标志着你获准研习牛头人的德鲁伊之道，并开始与Earthmother终生的沟通。",["race:Tauren"]="身为Shu'halo，你的德鲁伊之道源自先祖的召唤，肩负着恢复莫高雷神圣猎场平衡的使命。"},sec={{t="踏上修行之路的召唤",b="拥有自然天赋的年轻牛头人在红云台地开始试炼后不久，就会收到绿色便笺。一名信使将加尔特·迷雾行者的简短召令送到纳拉其营地，初学者必须在那里向导师报到。不安的灵魂与动荡的元素侵扰着莫高雷，长者们需要尽快培养新的德鲁伊。"},{t="大地之母的教诲",b="加尔特·迷雾行者教导初学者与自然沟通。他提醒他们，暗夜精灵同样与荒野有着深厚的联系，却因古老的骄傲而与牛头人保持距离。牛头人的德鲁伊之道以敬奉大地之母为核心。初学者学习聆听大地上躁动不安的先祖之声，以血肉之躯践行她的意志。"}},faq={{q="绿色便笺是什么？",a="绿色便笺召唤初出茅庐的牛头人德鲁伊前往纳拉其营地。它让他们寻找加尔特·迷雾行者，开始心灵的修行。",al={"绿色便笺物品","这张便笺是什么"}},{q="绿色便笺是谁送来的？",a="一名信使代加尔特·迷雾行者送来绿色便笺。加尔特是红云台地纳拉其营地的德鲁伊训练师。",al={"绿色便笺是谁送的","绿色便笺是谁写的"}},{q="加尔特·迷雾行者为何召集德鲁伊初学者？",a="躁动不安的先祖之灵侵扰着莫高雷及附近地区。加尔特需要尽快培养新的德鲁伊，与荒野之灵沟通，治愈这片动荡的大地。",al={"加尔特为何找我","加尔特·迷雾行者的原因"}},{q="加尔特向德鲁伊讲述了哪些关于暗夜精灵的事？",a="加尔特提醒他们，暗夜精灵与自然有着神圣的联系，但他们十分骄傲，不太可能欢迎牛头人加入自己的圈子。他敦促初学者专心学习大地母亲的教诲。",al={"暗夜精灵与牛头人德鲁伊","暗夜精灵的情况"}}},fp="12,152,18.314.0,28.334.0,25.133.0,27.115.0,51.162.0,53.197.0"}
P.entries["item:verdant-sigil"] = {n="绿色符记",s="在幽影谷，管理员伊尔萨莱恩将绿色符记交给年轻的暗夜精灵德鲁伊，召唤他们开始修行。",h="在幽影谷，管理员伊尔萨莱恩将绿色符记交给年轻的暗夜精灵德鲁伊，召唤他们开始修行。",kw={"奥达希尔","德鲁伊","翡翠梦境","伊尔萨莱恩","玛丹特·硬木","幽影谷","泰达希尔","绿色符记"},ang={["class:Druid"]="对于年轻的暗夜精灵德鲁伊而言，收到绿色符记标志着你迎来了第一次成长仪式，从简单的森林养护转向严谨的塞纳里奥教导。",["race:NightElf"]="在奥达希尔的树冠下，符记体现了kaldorei的传统：让你的心灵与自然世界及泰达希尔的守护者相契合。"},sec={{t="修行之路的召唤",b="在幽影谷，感受到荒野召唤的年轻暗夜精灵会从管理员伊尔萨莱恩手中接过绿色符记。一位信使受德鲁伊训练师玛丹特·硬木所托，将符记送来，指引初学者登上奥达希尔的枝桠。这枚信物邀请他们放下日常杂务，开始潜心学习如何与自然之灵沟通，探寻翡翠梦境的奥秘。"},{t="踏入梦境的第一步",b="将绿色符记呈交给玛丹特·硬木，标志着年轻德鲁伊开始了毕生的修行。初学者尚未准备好通过沉睡冥想漫步翡翠梦境，但这枚信物标志着他们师承之路的起点。在玛丹特的指导下，他们学习聆听荒野的低语，练习初步的变形与治疗法术，为泰达希尔效力。"}},faq={{q="绿色符记有什么用途？",a="绿色符记召唤幽影谷的暗夜精灵德鲁伊初学者前往奥达希尔，寻找玛丹特·硬木，开始正式修行。",al={"绿色符记有什么作用","为什么会有绿色符记","绿色符记用途"}},{q="谁会发放绿色符记？",a="管理员伊尔萨莱恩在幽影谷将绿色符记交给初入门的德鲁伊，传达玛丹特·硬木的口信。",al={"谁发放绿色符记","绿色符记在哪里领取"}},{q="收到符记后，该把它带到哪里？",a="你要将绿色符记带给德鲁伊训练师玛丹特·硬木，他位于幽影谷中心的奥达希尔中央厅室。",al={"绿色符记交到哪里","谁收绿色符记","绿色符记交付"}},{q="将符记呈交给玛丹特·硬木之后会发生什么？",a="玛丹特收下绿色符记，欢迎你成为他的学生。他引导你与自然沟通，并随着你的力量增长，为你探索翡翠梦境的奥秘做好准备。",al={"玛丹特如何处理符记","绿色符记之后"}}},fp="13,125,21.397.0,29.362.0,41.129.0,32.117.0,44.127.0,61.183.0"}
P.entries["item:verna-s-westfall-stew-recipe"] = {n="弗娜的杂味炖肉食谱",s="法布隆夫妇准备离开西部荒野的农场时，弗娜将自己的炖肉食谱送给萨尔玛·萨丁。对留下的人来说，那份熟悉的慰藉或许还能延续。",h="法布隆夫妇准备离开西部荒野的农场时，弗娜将自己的炖肉食谱送给萨尔玛·萨丁。对留下的人来说，那份熟悉的慰藉或许还能延续。",kw={"烹饪","法布隆","食谱","萨丁农场","萨尔玛·萨丁","弗娜·法布隆","杂味炖肉"},ang={["faction:Alliance"]="对联盟而言，这份食谱讲述了忠诚的农户因不法之徒横行而被迫离开家园的遭遇，而暴风城仍在艰难地维系当地的统治。",["profession:Cooking"]="对厨师而言，在西部荒野的农场逐渐衰败之际，弗娜的手写食谱保存了当地的烹饪知识。"},sec={{t="临别的礼物",b="弗娜和农夫法布隆在西部荒野安家多年。如今，迪菲亚潜行者和失控的收割傀儡在乡间肆虐。法布隆夫妇正等着修好马车，好逃往暴风城。\n\n等待期间，弗娜写下了自己珍爱的杂味炖肉配方。她将食谱托付给前往邻居兼好友萨尔玛·萨丁那里的旅人。这样，留下的人或许仍能从这道炖肉中得到熟悉的慰藉。"}},faq={{q="弗娜为什么要送出自己的炖肉食谱？",a="弗娜和农夫法布隆正准备逃离西部荒野，因为匪徒和失控的机器已经占据了他们的田地。离开农场之际，弗娜希望好友萨尔玛·萨丁能继续为留下的人烹制这道炖肉。",al={"弗娜为何送出食谱","为何送出杂味炖肉食谱","弗娜食谱的用途"}},{q="这份食谱是送给谁的？",a="弗娜的食谱是送给萨尔玛·萨丁的，她住在岔路口前方不远处的萨丁农场。",al={"谁收到食谱","食谱交给谁","炖肉食谱送到哪里"}},{q="法布隆夫妇打算去哪里？",a="法布隆夫妇正等着修好马车，好逃往暴风城。他们想寻一处安全之地，远离威胁乡间的混乱和匪患。",al={"法布隆夫妇去哪里","弗娜去哪里","法布隆的目的地"}},{q="杂味炖肉在当地有什么特别之处？",a="杂味炖肉是当地的一道家常菜，食材来自本地的农作物和野味。如今粮食短缺，农场荒废，这些丰盛的炖肉配方帮助幸存的农户熬过艰难时日。",al={"杂味炖肉是什么","杂味炖肉为何重要","杂味炖肉的故事"}}},fx={["39bb19d7"]={q="弗娜的杂味炖肉食谱是什么？",a="这是一份由弗娜·法布隆亲笔写下的烹饪指南，详细记载了制作丰盛的杂味炖肉所需的食材与步骤。弗娜即将离开危机四伏的故乡，为了不让这道拿手的地方菜肴失传，她把做法写在羊皮纸上，让邻居能继续为旅人和当地居民提供饭食。",al={"弗娜的炖肉食谱","弗娜的杂味炖肉食谱是什么","弗娜的杂味炖肉食谱物品"}},b68c02b6={q="弗娜的杂味炖肉食谱来自哪里，是谁写的？",a="这份食谱是弗娜·法布隆在西部荒野北部的法布隆家园匆匆写下的。面对迪菲亚强盗和四处觅食的野兽日益频繁的袭击，她在收拾家中的马车、逃离这片乡野之前，亲手写下了食谱。",al={"谁写了弗娜的炖肉食谱","弗娜食谱来源","弗娜的炖肉食谱来自哪里"}}},fp="28,152,15.463.0,41.219.0,28.106.0,39.167.0,47.172.0"}
P.entries["item:verner-s-note"] = {n="弗纳的便笺",s="在赤脊山，弗纳·奥斯古将一份书面请购单送往西边，交给闪金镇的铁匠阿古斯。信中说明了湖畔镇缺铁的困境，并向这位艾尔文的铁匠求购马蹄铁。",h="在赤脊山，弗纳·奥斯古将一份书面请购单送往西边，交给闪金镇的铁匠阿古斯。信中说明了湖畔镇缺铁的困境，并向这位艾尔文的铁匠求购马蹄铁。",kw={"闪金镇","马蹄铁","湖畔镇","赤脊山","铁匠阿古斯","马蹄铁的价格","弗纳·奥斯古","弗纳的便笺"},ang={["faction:Alliance"]="身为联盟的一员，你能看到暴风城乡间聚落承受的压力。湖畔镇必须与腹地的村庄协调，才能维持补给线。",["profession:Blacksmithing"]="身为铁匠，你能看到边境战事如何消耗物资。当武器和护甲耗尽每一块铁锭时，湖畔镇就必须从闪金镇这样较为安全的聚落购入钉蹄物资。"},sec={{t="求援购铁",b="湖畔镇的防务几乎耗尽了弗纳·奥斯古的全部铁料。这位镇上的铁匠用储备的铁料为暴风城卫队打造武器和护甲，而这些卫兵在抵御入侵的豺狼人和应对当地威胁时，早已捉襟见肘。与此同时，湖畔镇的马厩日渐荒废，连坐骑最基本的马蹄铁都无从配备。弗纳请求闪金镇的铁匠阿古斯从艾尔文送来打造好的马蹄铁，好让镇上的马匹钉上蹄铁。"}},faq={{q="弗纳的便笺上写了什么？",a="弗纳的便笺告诉铁匠阿古斯，弗纳为湖畔镇的暴风城卫队打造武器和护甲，几乎用尽了储备的铁料。由于没有剩余的铁料打造马蹄铁，他请求阿古斯从闪金镇送些过来。",al={"弗纳的便笺内容","便笺写了什么","弗纳的便笺信息"}},{q="弗纳·奥斯古是谁？",a="弗纳·奥斯古是赤脊山湖畔镇的铁匠。他为镇上的守卫配备装备，也维护劳作器具，为牲畜钉蹄铁。",al={"弗纳是谁","弗纳·奥斯古 赤脊山"}},{q="这张便笺要交给谁？",a="这张便笺沿着道路向西送去，交给艾尔文森林闪金镇锻炉外的铁匠阿古斯。",al={"弗纳的便笺交给谁","便笺送到哪里","铁匠阿古斯是谁"}},{q="弗纳为什么不能自己打造马蹄铁？",a="弗纳已将储备的铁料用于为暴风城卫队锻造武器和修理装备，这些卫兵正面对豺狼人和当地的其他威胁。因此，他已没有铁料打造马蹄铁。",al={"湖畔镇为什么需要马蹄铁","为什么向闪金镇求购马蹄铁"}}},fx={["486dfee9"]={q="弗纳的便笺是什么？",a="这是一封由湖畔镇当地铁匠弗纳·奥斯古亲笔写的信，收信人是闪金镇的铁匠阿古斯。信中说明，为了装备当地的暴风城卫队以应对日益加剧的地区威胁，湖畔镇的铁匠铺已经耗尽了铁料，因此无力为镇上马厩里的马匹打造马掌。这封信是一份正式的申请，请求阿古斯提供一箱马掌以解燃眉之急。",al={"弗纳的便笺","这张便笺是什么","弗纳便笺的用途"}},b8effef9={q="弗纳的便笺来自哪里？是谁写的？",a="这封便笺由弗纳·奥斯古亲自在赤脊山湖畔镇的铁匠铺写下。周边的豺狼人和兽人不断来犯，镇卫队疲于应对，弗纳也因此承受着不断增加的武器需求。他写下这封信，向艾尔文森林的同行安排一批紧急物资。",al={"谁写了弗纳的便笺","弗纳的便笺来自哪里","弗纳便笺的来源"}},c0af4e8d={q="为什么有人需要弗纳的便笺？",a="便笺向铁匠阿古斯说明弗纳·奥斯古的铁料短缺，并请求借用五十对马掌，直到弗纳收到下一批铁料。送达便笺后，阿古斯便能为湖畔镇的马厩安排援助。",al={"阿古斯为什么需要弗纳的便笺","谁需要弗纳的便笺","为什么要送弗纳的便笺"}}},fp="13,162,15.401.0,33.213.0,21.151.0,23.114.0,45.164.0"}
P.entries["item:verog-s-head"] = {n="维罗戈的头颅",s="雷戈萨·死门要求带回维罗戈的头颅，以证明这位科卡尔首领已经死去。这位酋长统率着死水绿洲一带的部队，击败他是为了削弱威胁贫瘠之地的部族。",h="雷戈萨·死门要求带回维罗戈的头颅，以证明这位科卡尔首领已经死去。这位酋长统率着死水绿洲一带的部队，击败他是为了削弱威胁贫瘠之地的部族。",kw={"贫瘠之地","半人马","科卡尔","雷戈萨·死门","死水绿洲","维罗戈","狂热的维罗戈","维罗戈的头颅"},ang={["faction:Horde"]="击败维罗戈并取下他的头颅，有助于保护十字路口与南贫瘠之地之间的部落路线，使其免遭半人马袭击。",["race:Tauren"]="身为牛头人，你明白击败科卡尔的分量：你的族人与卡利姆多的半人马部族之间的残酷战争，已经持续了数代。"},sec={{t="绿洲的战利品",b="科卡尔半人马威胁着贫瘠之地北部的部落旅人和补给路线。狂热的维罗戈在干旱的灌木荒野中游荡，让他位于死水绿洲的指挥帐篷疏于防守。部落行动人员攻击大帐周围的部队，直到警报响起。维罗戈赶回营地防守，在那里被杀死并斩下头颅。雷戈萨·死门收下维罗戈的头颅，作为又一位危险的科卡尔酋长已经倒下的证据。巴拉克·科多班恩的头颅早已陈列在旁。"}},faq={{q="狂热的维罗戈是谁？",a="狂热的维罗戈是一位科卡尔半人马军阀，以贫瘠之地的死水绿洲为据点。他在干旱的平原上游荡，统率着绿洲帐篷周围的敌对部队。",al={"维罗戈 是谁","维罗戈 的故事","狂热的维罗戈"}},{q="谁想要维罗戈的头颅？",a="雷戈萨·死门是驻扎在十字路口以西营地的一位兽人老兵，他想要维罗戈的头颅。他收集被杀死的科卡尔军阀的战利品，以削弱他们的战团和士气。",al={"谁收维罗戈的头颅","雷戈萨·死门 维罗戈","上交维罗戈的头颅"}},{q="在哪里能找到维罗戈？",a="维罗戈的营地和指挥帐篷位于十字路口东南方的死水绿洲。当半人马守卫被杀、警报响起时，他就会返回驻地防守。",al={"维罗戈 在哪里","维罗戈 的位置","死水绿洲帐篷"}},{q="头颅上交后会怎样？",a="雷戈萨·死门将维罗戈的头颅放在巴拉克·科多班恩的头颅旁边。这些头颅标志着部落针对科卡尔首领展开的征战。",al={"雷戈萨 如何处置头颅","半人马头颅陈列"}}},fp="12,199,21.488.0,26.172.0,23.179.0,21.175.0,47.122.0"}
P.entries["item:vial-of-innocent-blood"] = {n="无辜者之血",s="辛迪加暗影法师在敦霍尔德城堡的废墟中收集无辜者之血。塔伦米尔的皇家药剂师学会想用它作为实验性毒素的催化剂。",h="辛迪加暗影法师在敦霍尔德城堡的废墟中收集无辜者之血。塔伦米尔的皇家药剂师学会想用它作为实验性毒素的催化剂。",kw={"药剂师林度恩","敦霍尔德城堡","希尔斯布莱德丘陵","无辜者之血","辛迪加暗影法师","塔伦米尔"},ang={["faction:Horde"]="作为部落的一员，取得这种材料有助于部落对抗荆棘谷地精在石爪山的森林砍伐活动。",["race:Undead"]="身为亡灵，你知道皇家药剂师学会会使用有违道德的材料，从人类亡命之徒手中收集原料，以推进其炼金术研究。"},sec={{t="可怖的材料",b="辛迪加暗影法师在敦霍尔德城堡的废墟中收集无辜者的鲜血。辛迪加中堕落的人类贵族在残破的城墙内研习黑暗法术。塔伦米尔的药剂师林度恩需要未受污染的鲜血，用来研制一种实验性的镇静药剂。他打算用这种药剂对付石爪山脉的荆棘谷地精，并认为辛迪加的储备是个便利的来源。"}},faq={{q="无辜者之血有什么用途？",a="塔伦米尔的药剂师林度恩用这些鲜血调制毒素，意在抑制荆棘谷地精作业人员的攻击性。这些人正在石爪山脉给部落制造麻烦。",al={"无辜者之血用途","无辜者之血有什么用","无辜者鲜血用途"}},{q="谁携带着这些血瓶？",a="辛迪加暗影法师携带着这些血瓶，出没于希尔斯布莱德丘陵东南部的敦霍尔德城堡废墟周围。",al={"谁掉落无辜者之血","哪里获取无辜者之血","辛迪加暗影法师"}},{q="辛迪加暗影法师为什么持有无辜者的鲜血？",a="辛迪加的人类匪徒和堕落贵族雇用暗影施法者，采集并保存无辜者的鲜血，用于黑暗魔法实验。",al={"辛迪加为什么持有鲜血","辛迪加鲜血仪式"}},{q="药剂师林度恩为什么需要无辜者的鲜血？",a="林度恩说，无辜者的鲜血具有罕见的特性，是调制一种药剂所必需的。这种药剂能消除受害者的暴戾，使其变得温顺。",al={"为什么需要无辜者之血","药剂师林度恩鲜血"}}},fp="22,177,18.379.0,44.168.0,24.125.0,50.139.0,52.135.0"}
P.entries["item:vial-of-phlogiston"] = {n="燃素",s="在剃刀沼泽，燃素吸引着联盟和部落的铁匠。护甲大师用它为前途可期的战士淬炼锁甲，而野猪人则在要塞中守护着它。",h="在剃刀沼泽，燃素吸引着联盟和部落的铁匠。护甲大师用它为前途可期的战士淬炼锁甲，而野猪人则在要塞中守护着它。",kw={"野蛮护甲","弗伦的铠甲","弗伦·长须","燃素","剃刀沼泽","鲁古格","索恩格瑞姆·火眼"},ang={["class:Warrior"]="身为战士，取回燃素是获得标志性淬炼护甲的关键一步。这证明你有能力攻入剃刀沼泽。",["profession:Blacksmithing"]="身为铁匠，你知道燃素是特殊冶金工艺中不可或缺的熔剂，用于淬炼传奇锁甲的甲片。"},sec={{t="熔炉精华",b="燃素蕴含着不稳定的火焰，在秘奥的金属加工技艺中占有一席之地。暴风城的矮人铁匠弗伦·长须需要它，贫瘠之地近乎失明的兽人护甲匠索恩格瑞姆·火眼也同样需要它。两人都用它强化战士的护甲，使其突破寻常的物理极限。没有这种炼金制剂，两人都无法完成弗伦的铠甲或部落的野蛮护甲所需的特殊锻造。"},{t="荆棘深处取燃素",b="一瓶燃素藏在剃刀沼泽深处，位于贫瘠之地最南端盘根错节的灌木丛中。地卜师鲁古格在这座荆棘密布的堡垒中持有它。无论是要将它送往暴风城的弗伦手中，还是送到漫天尘土另一端的索恩格瑞姆的铁砧上，都必须冒险深入敌对野猪人的领地。"}},faq={{q="燃素有什么用途？",a="锻造大师将燃素用作淬炼所需的炼金催化剂。它凝聚的热量能将未经加工的锁甲和铁料淬炼成异常坚固的战士护甲。",al={"燃素用途","燃素有什么作用","为什么需要燃素"}},{q="谁携带着燃素？",a="野猪人地卜师鲁古格携带着这瓶燃素，身处贫瘠之地南部剃刀沼泽荆棘密布的隧道深处。",al={"谁掉落燃素","燃素掉落","哪里获得燃素"}},{q="哪些铁匠需要这种材料？",a="暴风城的弗伦·长须和贫瘠之地的索恩格瑞姆·火眼都需要燃素，为久经沙场的战士锻造独特的硬化护甲套装。",al={"谁需要燃素","燃素任务","哪些任务需要燃素"}}},fx={["3ab06e7f"]={q="燃素是什么？",a="燃素是一种极其稀有的炼金物质，以其高热和淬火特性而闻名，深受高级护甲匠重视。联盟和部落中专门从事锻造的铁匠都在寻求这种物质。它是一种关键催化剂，可用于打造坚韧、经过淬火的锁甲，供久经沙场的战士穿戴。",al={"燃素是什么","燃素的背景","燃素物品"}}},fp="18,178,20.391.0,27.322.0,28.155.0,35.121.0,35.148.0"}
P.entries["item:vial-of-purest-water"] = {n="一瓶最纯净的水",s="在南贫瘠之地，布瑞恩为一名萨满祭司学徒祝福了一瓶纯净的水。瓶中的水能帮助水之先知伊斯伦调制water sapta，让人得以看见元素之灵。",h="在南贫瘠之地，布瑞恩为一名萨满祭司学徒祝福了一瓶纯净的水。瓶中的水能帮助水之先知伊斯伦调制water sapta，让人得以看见元素之灵。",kw={"贫瘠之地","布瑞恩","水之召唤","水之先知伊斯伦","银松森林","一瓶最纯净的水","水之灵契"},ang={["class:Shaman"]="作为萨满祭司，送达这瓶净化过的水，将引领你完成最后几步试炼，与水之灵沟通，并获得你的水之图腾。",["faction:Horde"]="作为部落萨满祭司，你会在围绕这瓶水展开的试炼中穿行于卡利姆多和东部王国，加深与元素的联系。"},sec={{t="净化的供品",b="布瑞恩引导学徒经受耐心与净化的试炼，然后将水封入瓶中。这水蕴含着未受污染的纯净元素之力。带着它穿过贫瘠之地，交给守望在一处僻静海岸的水之先知伊斯伦。她需要用它调制water sapta。没有这样纯净的水，萨满祭司就无法在远离烈日炙烤的平原之处与灵体守护者沟通。"},{t="通往水之图腾的道路",b="水之先知伊斯伦用这受过祝福的水考验学徒的决心，并开启学徒的感知，使其察觉隐藏的元素。她将一部分水调入水之灵契，让学徒能够看见银松森林一处遥远圣坛中的灵体。她留下余下的水滴，用于对抗并净化别处一个失控的元素化身。携带这瓶水标志着一个转折：学徒从卑微的杂务走向直接面对真实的元素。"}},faq={{q="一瓶最纯净的水有什么用途？",a="瓶中装着为一名萨满祭司学徒净化并祝福过的水。水之先知伊斯伦用它调制水之灵契，赋予学徒感知水元素所需的灵视，也将它用于获得水之图腾所必需的后续仪式试炼。",al={"一瓶最纯净的水用途","这瓶水有什么作用","最纯净的水用途"}},{q="瓶中的水由谁准备？",a="萨满祭司在布瑞恩的指引下收集这些水。布瑞恩是一位隐居在贫瘠之地南部深处的兽人萨满祭司；学徒完成试炼后，布瑞恩会祝福净化后的水，将其封入瓶中，以便携带。",al={"谁制作了这瓶水","谁装满这瓶水","布瑞恩的水"}},{q="这瓶水需要送到哪里？",a="将这瓶水带给贫瘠之地东海岸的水之先知伊斯伦，她就在棘齿城以南不远处，面朝无尽之海。",al={"这瓶水交给谁","这瓶水送到哪里","交付最纯净的水"}},{q="送达这瓶水后，仪式会指引学徒前往何处？",a="收到这瓶水并调制好水之灵契后，水之先知伊斯伦会派萨满祭司渡海前往东部王国。圣坛位于银松森林，在幽暗城以南。",al={"接下来去哪里","送水后的下一步","银松森林水之圣坛"}}},fp="20,168,19.366.0,23.393.1,42.260.0,39.216.0,37.119.0,53.182.0"}
P.entries["item:vial-of-spider-venom"] = {n="瓶装蜘蛛毒液",s="暮色森林的蜘蛛身怀毒液，伊瓦夫人需要用它来制作防护结界。她收集这些毒液和亡灵残骸，制作惩罚图腾。",h="暮色森林的蜘蛛身怀毒液，伊瓦夫人需要用它来制作防护结界。她收集这些毒液和亡灵残骸，制作惩罚图腾。",kw={"夜色镇","暮色森林","伊瓦夫人","纳拉克西斯","隐士","蜘蛛毒液","惩罚图腾","瓶装蜘蛛毒液"},ang={["class:Rogue"]="身为潜行者，你或许会调制毒药并将其涂在刀刃上，但这些未经处理的蜘蛛毒液是用来施展神秘防护法术的，而非直接用于刺杀。",["faction:Alliance"]="身为行走在暮色森林阴暗道路上的联盟冒险者，你可以帮助伊瓦夫人制作防护图腾，保护那些面对林中恐怖威胁的旅人。"},sec={{t="暮色森林的剧毒威胁",b="暮色森林的灌木丛中潜藏着毒蜘蛛，从小型结网毒蜘蛛、绿色独行蛛，到黑色寡妇和纳拉克西斯。它们毒牙中的毒液足以麻痹旅人，腐蚀血肉。杀死蜘蛛的人可以将毒液装入完好的小瓶。"},{t="制作惩罚图腾",b="在夜色镇，占卜师伊瓦夫人为即将踏入黑暗世界的旅人看到了不祥的预兆。她需要五瓶蜘蛛毒液，以及食尸鬼的獠牙和骷髅的手指，来制作具有反击之力的结界。她的技艺将毒液的侵蚀之力转向攻击者，让惩罚图腾对任何攻击佩戴者的人施以伤害。"}},faq={{q="这些蜘蛛毒液来自哪里？",a="毒液来自暮色森林中捕食猎物的蜘蛛，包括结网毒蜘蛛、食腐独行蛛、绿色独行蛛、黑色小蜘蛛，以及凶恶的蛛母纳拉克西斯。",al={"蜘蛛毒液来源","谁掉落蜘蛛毒液","暮色森林哪里获取蜘蛛毒液"}},{q="谁需要蜘蛛毒液？",a="夜色镇的先知伊瓦夫人需要五瓶蜘蛛毒液，以及骷髅的手指和食尸鬼的獠牙，来制作魔法结界。",al={"谁需要蜘蛛毒液","暮色森林蜘蛛毒液交付","伊瓦夫人毒液"}},{q="这些毒液用来制作什么？",a="伊瓦夫人将毒液与亡灵残骸结合，为惩罚图腾附魔。这种防御护符会以魔法伤害攻击者。",al={"艾瓦制作什么","惩罚图腾材料","为什么收集蜘蛛毒液"}},{q="伊瓦夫人为什么需要用危险的毒液来制作防护结界？",a="伊瓦夫人利用森林中掠食者与亡灵的致命力量和反击特性，制作出能将伤害返还给施暴者的护符。",al={"结界为什么需要毒液","艾瓦图腾材料背景"}}},fx={cd5271e6={q="瓶装蜘蛛毒液是什么？",a="这是一小瓶从暮色森林肆虐的巨型蜘蛛身上采集的强烈腐蚀性毒液。它虽触之即毙，却深受当地秘术师和乡野女巫珍视；她们会用这种阴暗而剧毒的物质施展诅咒，或为护符附魔，使攻击者的恶意反噬自身。",al={"什么是蜘蛛毒液","瓶装蜘蛛毒液的背景","瓶装蜘蛛毒液是什么"}}},fp="20,155,26.258.0,32.346.0,39.176.0,32.119.0,32.133.0,63.143.0"}
P.entries["item:vicious-night-web-spider-venom"] = {n="邪恶夜行蜘蛛的毒液",s="在提瑞斯法东部，邪恶夜行蜘蛛的毒液携带着一种古老的病原体。皇家药剂师学会看重其中保存的古老病原株，并将其用于被遗忘者的新的瘟疫研究。",h="在提瑞斯法东部，邪恶夜行蜘蛛的毒液携带着一种古老的病原体。皇家药剂师学会看重其中保存的古老病原株，并将其用于被遗忘者的新的瘟疫研究。",kw={"药剂师乔汉","布瑞尔","新的瘟疫","蜘蛛毒液","提瑞斯法林地","毒蛛峡谷","邪恶的夜行蜘蛛"},ang={["class:Rogue"]="作为熟悉天然神经毒素的Rogue，你能看出皇家药剂师学会如何将危险的野生毒液制成生物武器。",["race:Undead"]="身为被遗忘者，收集这种毒液有助于希尔瓦娜斯推进她的指令，研制出足以击垮阿尔萨斯及其Scourge的瘟疫。"},sec={{t="留存的病原体",b="布瑞尔的药剂师乔汉正在研究记载着一场夺去数千人性命的瘟疫的古籍。引发那场疫情的病原体在当地夜行蜘蛛的毒液中存续了数百年。药剂师们在血色修道院以南的毒蛛峡谷猎杀其中凶恶的品种，提取留存的病原体，用于炼金实验。"},{t="助长新的瘟疫",b="被遗忘者寻求一种对付天灾军团和生者的武器。乔汉将这种毒液作为最后一种成分加入他的实验药剂，希望其中留存的病原体能与混合物共同起效。"}},faq={{q="与普通蜘蛛毒液相比，这种毒液有何独特之处？",a="皇家药剂师学会研究的古籍记载，夜行蜘蛛一族的毒腺中保存着一种古老的瘟疫病原体。它们的毒液就是病原体的储库。",al={"为何需要这种毒液","夜行毒液背景","蜘蛛毒液瘟疫"}},{q="在哪里能找到携带这种毒液的蜘蛛？",a="邪恶的夜行蜘蛛主要生活在毒蛛峡谷，那里位于提瑞斯法林地东部、血色修道院以南。",al={"哪里能找到蜘蛛毒液","邪恶的夜行蜘蛛位置","毒蛛峡谷蜘蛛"}},{q="布瑞尔有谁需要这种毒液？",a="布瑞尔的药剂师乔汉需要多份样本，以便继续为被遗忘者研究一种新的传染性病原体。",al={"谁需要蜘蛛毒液","药剂师乔汉毒液","谁使用这种毒液"}},{q="这种毒液在被遗忘者的研究中起什么作用？",a="乔汉需要这种毒液作为实验的最后一种成分。古籍记载，夜行蜘蛛毒液中保存着一种古老的瘟疫，他想弄清其中的病原体能否与他的药剂共同起效。",al={"药剂师毒液研究","新的瘟疫成分","被遗忘者蜘蛛毒液"}}},fp="30,214,21.338.0,22.200.1,63.182.0,51.114.0,30.120.0,52.213.0"}
P.entries["item:vile-familiar-head"] = {n="邪灵劣魔的头颅",s="在火刃集会所附近，邪灵劣魔的头颅代表着年轻部落术士面临的一项严酷考验。在鲁赞的指导下，他们收集这些骇人的战利品，证明自己已准备好束缚第一个恶魔仆从。这项考验要求他们严守纪律，并对即将召唤的生物所具有的致命力量心存敬畏。",h="在火刃集会所附近，邪灵劣魔的头颅代表着年轻部落术士面临的一项严酷考验。在鲁赞的指导下，他们收集这些骇人的战利品，证明自己已准备好束缚第一个恶魔仆从。这项考验要求他们严守纪律，并对即将召唤的生物所具有的致命力量心存敬畏。",kw={"火刃集会所","杜隆塔尔","小鬼","鲁赞","试炼谷","邪灵劣魔","邪灵劣魔的头颅","术士任务"},ang={["class:Warlock"]="对术士而言，收集这些头颅是掌控虚空的早期一步，也让他们获得召唤并束缚小鬼为自己效劳的资格。",["faction:Horde"]="即使在杜隆塔尔的训练场上，术士也在偏僻处修习，时刻留意部落对他们钻研恶魔之道所抱有的挥之不去的猜疑。"},sec={{t="恶魔学的血腥一课",b="在试炼谷烈日炙烤的峡谷中，鲁赞要求想要学习召唤术的新手带回六个邪灵劣魔的头颅。邪灵劣魔是浑身冒火的小鬼，拥有危险的元素狡黠，出没于火刃集会所外。新手必须直面并击败它们，证明自己能够降伏恶魔，而不会反被恶魔压倒。在萨尔的部落中，术士只是勉强得到容忍，因此他们必须谨慎训练。新手若被召唤出的生物杀死，只会让研习黑暗法术的人蒙受更深的耻辱与猜疑。"}},faq={{q="邪灵劣魔的头颅有什么用途？",a="在试炼谷，这些头颅能证明术士新手已做好准备。鲁赞要求学徒带回六个，才会教他们召唤第一个小鬼仆从。",al={"邪灵劣魔的头颅用途","这些头颅有什么用","鲁赞任务物品"}},{q="邪灵劣魔来自哪里？",a="邪灵劣魔聚集在试炼谷东北部一处洞穴的入口及内部。隐秘而邪恶的火刃集会所就藏在这座洞穴中。",al={"邪灵劣魔位置","哪里能找到邪灵劣魔","火刃集会所洞穴"}},{q="鲁赞为什么让年轻术士收集这些头颅？",a="鲁赞要求术士在召唤一种生物之前，先有能力制服它。小鬼诡计多端，还会投掷不稳定的火焰，因此面对面击败它们，能让学徒领教自己打算驾驭的恶魔有多危险。",al={"为什么收集头颅","鲁赞的动机","为什么先杀死仆从"}},{q="部落如何看待收集这类战利品的术士？",a="如今的部落容忍术士，却并未接纳他们。与邪能魔法有关的背叛留下了深深的不信任，因此鲁赞和其他训练师坚持要求学徒严守纪律，谨慎行事。",al={"术士是否被接纳","部落术士的名声","不受信任的术士"}}},fp="18,291,31.555.0,38.148.0,34.156.0,55.214.0,59.192.0"}
P.entries["item:vile-fin-scale"] = {n="邪鳍鱼人的鳞片",s="邪鳍鱼人的鳞片来自游荡在提瑞斯法北部海岸和水道中的鱼人部族。在布瑞尔，皇家药剂师学会正研究这些样本，研制一种旨在打击生者与 天灾军团 的瘟疫。",h="邪鳍鱼人的鳞片来自游荡在提瑞斯法北部海岸和水道中的鱼人部族。在布瑞尔，皇家药剂师学会正研究这些样本，研制一种旨在打击生者与 天灾军团 的瘟疫。",kw={"一种新瘟疫","药剂师乔汉","布瑞尔","鱼人","皇家药剂师学会","提瑞斯法林地","邪鳍鱼人的鳞片"},ang={["faction:Horde"]="身为部落的一员，你清剿充满敌意的沿海鱼人聚落，帮助保障提瑞斯法林地边缘地带的安全，让信使和旅人得以通行。",["race:Undead"]="身为亡灵，你收集的每一片邪鳍鳞片，都在帮助皇家药剂师学会履行职责，研制武器，让被遗忘者能在生者与 Scourge 的威胁下生存。"},sec={{t="药剂试剂",b="皇家药剂师学会正寻求一种能在生者与 天灾军团 之中传播的瘟疫。普通毒素很容易调制，但传染病需要具备能从一个群体传播到另一个群体的特性。在布瑞尔，药剂师乔汉正研究邪鳍鳞片的天然韧性及其表面的黏液层。他希望这些特性能让实验中的传染性病原更加稳定，并帮助它们继续传播。"},{t="海岸上的威胁",b="邪鳍部族栖居在提瑞斯法林地的北部海岸和西部浅滩，威胁着旅人，并不断侵入被遗忘者的领地。收集它们的鳞片既能遏制这些野蛮鱼人的数量，也能为乔汉的实验室提供新鲜的有机材料，用于生物战试验。"}},faq={{q="药剂师乔汉为什么需要这些鳞片？",a="药剂师乔汉研究邪鳍鳞片，是为了协助皇家药剂师学会研制一种新瘟疫。普通毒药无法传播，因此他研究鳞片的天然特性，希望借此让实验中的病原从一个群体传播到另一个群体。",al={"乔汉 用鳞片做什么","为什么需要 邪鳍 鳞片","乔汉 瘟疫 鳞片"}},{q="在哪里能找到邪鳍鱼人？",a="邪鳍鱼人栖居在提瑞斯法林地的沿岸，尤其是北部海岸线，以及澈水湖和大海旁的西部水域。",al={"邪鳍 在哪里","提瑞斯法 鱼人位置","哪里获取鳞片"}},{q="新的瘟疫计划为什么对被遗忘者如此重要？",a="被遗忘者想要一种武器，用来对付他们的死敌：没有心智的 天灾军团，以及视他们为怪物的活人种族。乔汉在布瑞尔的研究，是整个王国为实现这一目标所做的早期尝试。",al={"为什么研制新瘟疫","被遗忘者 瘟疫目标","药剂师乔汉在研究什么"}},{q="具体哪些生物身上有这些鳞片？",a="提瑞斯法的邪鳍部族中，邪鳍智者、邪鳍污水鱼人 和 邪鳍泥浆鱼人 身上有这些鳞片。",al={"谁掉落邪鳍鱼人的鳞片","哪些鱼人掉落鳞片"}}},fp="14,216,19.381.0,20.304.0,45.245.0,36.141.0,60.197.0,44.109.0"}
P.entries["item:voodoo-charm"] = {n="巫毒咒符",s="在泰达希尔的兽穴中，巫毒咒符能破除瘤背控制奥本·怒爪躯体的魔法。",h="在泰达希尔的兽穴中，巫毒咒符能破除瘤背控制奥本·怒爪躯体的魔法。",kw={"利爪德鲁伊","瘤背","奥本·怒爪","泰达希尔","沉睡的德鲁伊","巫毒咒符"},ang={["class:Druid"]="对于在泰达希尔受训的年轻德鲁伊而言，用咒符让一位利爪德鲁伊同胞得到解脱、释放他的灵魂，揭示了一场悲剧：在翡翠梦境中漫游时，留在身后的肉体是何等脆弱。",["race:NightElf"]="对暗夜精灵而言，咒符揭示了瘤背熊怪堕落之深：它们竟将神圣的 kaldorei 兽穴变成了囚禁灵魂的恐怖牢笼。"},sec={{t="斩断黑暗束缚",b="在泰达希尔的瘤背兽穴中，奥本·怒爪的灵魂与肉体分离了。熊怪用邪恶的魔法控制了神圣的 卡多雷 守护者们沉睡的躯体，奥本的身体仍受它们的巫术操纵。他检查了咒符，发现其中的黑暗束缚无法通过传统的祈祷驱散。必须先击倒他失去灵魂的躯体，再对倒下的身体引导咒符的力量，才能清除熊怪的控制。随后，奥本游荡的灵魂便能永远离去，前往翡翠梦境。"}},faq={{q="巫毒咒符有什么用途？",a="巫毒咒符能破除瘤背熊怪对奥本·怒爪的魔法控制。击倒他失去灵魂、受人操纵的躯体后，必须对他的遗体使用咒符，才能解除魔法，释放他的灵魂。",al={"巫毒咒符有什么作用","巫毒咒符用途","如何使用巫毒咒符"}},{q="谁会给你巫毒咒符？",a="在利爪德鲁伊任务中，奥本·怒爪的灵魂会将巫毒咒符交给你。检查过咒符后，他会说明如何用它摆脱瘤背部族的巫术。",al={"哪里获得巫毒咒符","谁给咒符","奥本 咒符"}},{q="为什么暗夜精灵领地中会有名为巫毒咒符的东西？",a="这个名字反映了瘤背熊怪所用的外来或扭曲的秘术魔法。随着腐化与怪异的部族魔法渗入 巨树，它们也沦陷其中。咒符体现的正是那种禁锢并操纵休眠德鲁伊躯体的魔法。",al={"泰达希尔为何有巫毒","是巨魔巫毒吗"}},{q="使用咒符后会发生什么？",a="咒符破除奥本·怒爪躯体上的魔法后，他便摆脱了瘤背部族的控制。他的肉体得以安息，灵魂则离开泰达希尔，前往翡翠梦境。",al={"奥本 后来如何","奥本 是否存活"}}},fp="12,127,24.506.1,40.210.0,31.166.0,51.263.0,37.205.1"}
P.entries["item:wailing-essence"] = {n="哀嚎香精",s="哀嚎香精是一种奇异的浓缩物质，存在于哀嚎洞穴深处游荡的灵质怪体内。它被怀疑助长了贫瘠之地动植物间蔓延的怪异变异，因此引来了投机炼金师的关注，他们急于将它的强大效力装瓶利用。",h="哀嚎香精是一种奇异的浓缩物质，存在于哀嚎洞穴深处游荡的灵质怪体内。它被怀疑助长了贫瘠之地动植物间蔓延的怪异变异，因此引来了投机炼金师的关注，他们急于将它的强大效力装瓶利用。",kw={"灵质","麦伯克·米希瑞克斯","棘齿城","智慧饮料","哀嚎洞穴","哀嚎香精"},ang={["class:Druid"]="这种香精的存在直接指向哀嚎洞穴深处的腐化力量，凸显出净化梦境所受污染的迫切需要。"},sec={{t="不稳定的混合物",b="贫瘠之地中部的地下洞穴已充斥着异常能量，使野兽扭曲变异，并催生了胶状的灵质怪。这些黏糊糊的生物在体内浓缩出一种黏稠物质，被称为哀嚎香精。当地德鲁伊观察着这些水域，心中的恐惧与日俱增，地精商人却只看到了直接获利的商机。在港口城镇棘齿城，一位名叫麦伯克·米希瑞克斯的古怪炼金师相信，这种香精正是他那系列利润丰厚、旨在提升饮用者智力的“智慧饮料”所缺少的活性成分，却丝毫不在意其中可能潜藏的梦魇腐化。"}},faq={{q="哀嚎香精从何而来？",a="它采集自哀嚎洞穴内的灵质软泥怪，包括吞噬软浆怪、进化的软浆怪和梦魇软浆怪。",al={"哀嚎香精掉落","哀嚎香精获取地点","什么掉落哀嚎香精"}},{q="谁想要这种香精？",a="麦伯克·米希瑞克斯是一名在棘齿城做实验的地精，他正在寻找这种香精，以调制能提升智力的“智慧饮料”的新配方。",al={"谁需要哀嚎香精","谁收购哀嚎香精","哀嚎香精交付"}},{q="这种香精被怀疑对贫瘠之地造成了什么影响？",a="麦伯克怀疑，这种香精正是贫瘠之地各处野生动物迅速变异、植物异常疯长并不断蔓延的根源。",al={"哀嚎香精用途","哀嚎香精是否危险","哀嚎香精背景故事"}},{q="饮用哀嚎香精真的安全吗？",a="这种香精提取自受诅咒的洞穴深处那些遭到腐化、沾染梦魇的灵质怪，将它加入市售饮料供人饮用，再怎么说也是鲁莽之举，不过这倒很符合地精商人的一贯作风。",al={"哀嚎香精能否饮用","智慧饮料是否安全"}}},fx={["387b8d38"]={q="哀嚎香精是什么？",a="哀嚎香精是一种奇异而强效的物质，藏于哀嚎洞穴深处。它聚集在洞穴中四处游荡的游荡的鬼魂和黏液怪体内。当地观察者怀疑，它正是导致周围贫瘠之地的植物和野生动物发生奇异变异的非自然催化剂。",al={"哀嚎香精是什么","哀嚎香精信息","关于哀嚎香精"}}},fp="15,184,21.484.0,37.150.0,23.131.0,54.110.0,42.163.0"}
P.entries["item:warsong-axe-shipment"] = {n="一箱战歌之斧",s="一箱战歌之斧正在藏宝海湾等待启航，运往灰谷。这些新铸的斧头将交给战歌氏族，用于他们伐木营地的劳作。",h="一箱战歌之斧正在藏宝海湾等待启航，运往灰谷。这些新铸的斧头将交给战歌氏族，用于他们伐木营地的劳作。",kw={"灰谷","斧头","藏宝海湾","洛克·奥卡尔","碎木岗哨","一箱战歌之斧","战歌物资","码头管理员罗兹基尔"},ang={["faction:Horde"]="对部落而言，这箱货物有助于维持战歌伐木营地的物资供应，让营地在灰谷敌对势力的持续威胁下继续生产。",["race:Orc"]="对Warsong clan而言，锋利的斧头意味着更多木材，可以用于奥格瑞玛和杜隆塔尔不断扩建的基业。"},sec={{t="漫长的跨海航程",b="供战歌伐木营地使用的斧头正在藏宝海湾等待装运。营地的伐木工需要源源不断的耐用工具，而并非每件工具都能在前线锻造。订单越过无尽之海，送到这座中立的地精港口，货箱就存放在码头管理员罗兹基尔附近。这些磨利的斧头将运往碎木岗哨，再从那里转送到营地。要为遥远的边境营地补充物资，就得经历漫长的海上航程。"}},faq={{q="一箱战歌之斧在哪里？",a="货箱放在藏宝海湾的码头上，位于荆棘谷最南端。",al={"斧头货物位置","斧头货物在哪里","藏宝海湾斧头箱"}},{q="运往灰谷的货物为什么会在遥远南方的藏宝海湾？",a="黑水 海盗和热砂港承运穿越无尽之海的商船货物。藏宝海湾连接着遥远的土地，因此部落的工具也要经过这座港口。",al={"为什么是藏宝海湾","为什么在荆棘谷","藏宝海湾的战歌斧头"}},{q="谁需要这些斧头？",a="洛克·奥卡尔是驻守灰谷碎木岗哨的一名先驱，他需要这些斧头来补充战歌伐木营地日渐减少的库存。",al={"谁需要斧头","货物是给谁的","洛克·奥卡尔的斧头"}},{q="谁负责照管藏宝海湾的这批货物？",a="码头管理员罗兹基尔负责管理藏宝海湾的海运货物，这批货物正在那里等待运往卡利姆多。",al={"货物在谁那里","码头管理员罗兹基尔","藏宝海湾码头管理员"}}},fx={["445f7bbf"]={q="一箱战歌之斧是什么？",a="这是一批装箱运送的重型伐木斧，发往战歌氏族在灰谷的伐木作业点。兽人伐木工在砍伐卡利姆多的古老森林时，工具磨损得很快，因此定期运送新锻造的伐木斧，对于保障伐木场和伐木队的工具供应至关重要。",al={"一箱战歌之斧是什么","一箱战歌之斧的身份","灰谷的斧头箱"}}},fp="20,175,29.410.0,42.83.0,62.165.0,21.133.0,39.108.0"}
P.entries["item:warsong-oil"] = {n="战歌之油",s="在战歌伐木营地，战歌之油维持着伐木机械的运转。萨特伏击了一支运输队，将一批油运进了遭到腐化的林中聚居地。",h="在战歌伐木营地，战歌之油维持着伐木机械的运转。萨特伏击了一支运输队，将一批油运进了遭到腐化的林中聚居地。",kw={"灰谷","洛克·奥卡尔","夜道谷","萨提纳尔","碎木岗哨","战歌之油","战歌补给品","萨维亚"},ang={["faction:Horde"]="对部落而言，灰谷的木材支撑着他们在杜隆塔尔和贫瘠之地的据点。崇拜恶魔的萨特夺走机械用油后，那些新建定居点的建设便受到了影响。",["profession:Engineering"]="工程师们知道，地精设计的伐木机关节和圆锯需要持续润滑。没有润滑油，它们在伐木作业开始后几小时内就会烧坏。"},sec={{t="被盗的机械用油",b="战歌之油维持着战歌氏族在灰谷的伐木机械运转。地精制造的伐木机和大型锯木厂需要持续供应这种润滑油。没有它，伐木工作就可能停顿，拖慢木材供应，影响奥格瑞玛的建设，以及部落在杜隆塔尔和贫瘠之地各处定居点的防御加固。"},{t="萨特的仪式",b="萨特伏击了一支运送战歌之油的运输队，使这批油未能抵达碎木岗哨和伐木营地。他们将油桶带进了遭到腐化的聚居地，包括夜道谷、萨提纳尔和萨维亚，并在那里用这种易燃的润滑油举行仪式。"}},faq={{q="战歌之油有什么用途？",a="战歌之油维持着战歌伐木营地的重型伐木机、锯子和伐木机械的运转。",al={"战歌之油的用途","为什么需要油","有什么用途"}},{q="萨特为什么会有这些油？",a="萨特在灰谷的道路上伏击了一支前往碎木岗哨的补给车队。他们夺走了油，用于在破败的聚居地举行仪式。",al={"谁偷走了油","萨特为什么有油","油被运到哪里"}},{q="在哪里能找到战歌之油？",a="灰谷由萨特控制的地点存放着一桶桶战歌之油，尤其是夜道谷、萨提纳尔和萨维亚。",al={"战歌之油的位置","哪里能找到战歌之油","油的位置"}},{q="谁需要找回这些油？",a="碎木岗哨的洛克·奥卡尔需要战歌之油、锯条、绳索和斧头，为陷入困境的战歌伐木作业补充物资。",al={"谁需要油","战歌之油任务给予者"}}},fx={["7f00f21d"]={q="战歌之油是什么？",a="战歌之油是为部落在灰谷的伐木机械提供的重要润滑剂和燃料。它用于确保战歌伐木营地的重型机械和锯片顺畅运转，是维持氏族伐木作业、抵御荒野环境损耗不可或缺的资源。",al={"战歌之油是什么","这种油是什么","战歌之油信息"}}},fp="11,128,21.322.0,20.265.0,29.109.0,31.136.0,31.98.0,28.131.0"}
P.entries["item:warsong-outrider-update"] = {n="战歌侍从的报告",s="在灰谷东部边界，一名战歌侦查骑兵正在准备战歌侍从的报告。这名驻守当地的侦查骑兵记录前线情报，交由部落信使传递。这些报告有助于保障通往艾萨拉的通道安全，并巩固兽人在暗夜精灵抵抗下的立足之地。",h="在灰谷东部边界，一名战歌侦查骑兵正在准备战歌侍从的报告。这名驻守当地的侦查骑兵记录前线情报，交由部落信使传递。这些报告有助于保障通往艾萨拉的通道安全，并巩固兽人在暗夜精灵抵抗下的立足之地。",kw={"灰谷","艾萨拉","贫瘠之地","卡德拉克","碎木岗哨","战歌侦查骑兵","战歌侍从的报告"},ang={["faction:Horde"]="身为部落的一员，你依靠前线报告来保护贫瘠之地与灰谷之间的补给路线。这些路线运送着扩建奥格瑞玛所需的木材。",["race:Orc"]="身为兽人，你依靠警觉的斥候和迅捷的信使维护战歌的荣誉，并守住领地，抵御那些质疑你氏族伐木权的暗夜精灵哨兵。"},sec={{t="边境情报",b="出了碎木岗哨，东行的道路穿过灰谷动荡的边境地带，通往艾萨拉的古老废墟。兽人先锋骑兵在这片边境巡逻，记录战术观察、巡逻队动向和资源评估。\n\n他们将实地记录送交驻守北部哨塔的卡德拉克，那座哨塔守卫着贫瘠之地的边界。这些报告让部落指挥官能够清楚掌握森林树冠下敌军的集结情况，以及领地面临的威胁。"}},faq={{q="这份报告有什么用途？",a="这份报告记录了暗夜精灵的活动，以及灰谷东部通往艾萨拉的道路沿线状况。卡德拉克利用这些情报协调部落的兵力部署，并加强贫瘠之地北部边界的防御。",al={"战歌侍从的报告用途","为何需要侦查骑兵的报告","这是什么报告"}},{q="谁携带并递送这份公文？",a="一名在碎木岗哨与艾萨拉边界之间的大路上巡逻的战歌侦查骑兵携带着这份公文。这名侦查骑兵将公文交给卡德拉克，并领取新的战略命令。",al={"谁撰写侦查骑兵的报告","侦查骑兵的报告来自哪里"}},{q="这份报告需要送到哪里？",a="将报告直接交给北部哨塔的卡德拉克。这座哨塔守卫着贫瘠之地的边界和灰谷的南部入口。",al={"侦查骑兵的报告交到哪里","谁需要侦查骑兵的报告"}},{q="战歌为何如此重视灰谷？",a="战歌氏族砍伐灰谷的古老森林，为奥格瑞玛提供所需的木材和建筑材料。他们的采集活动使他们与守卫森林的暗夜精灵和银翼要塞发生冲突。",al={"兽人为何在灰谷","战歌为何重视灰谷"}}},fp="23,299,21.471.0,35.230.0,39.187.0,34.139.0,45.209.0"}
P.entries["item:warsong-runner-update"] = {n="战歌信使的报告",s="在佐拉姆加前哨站，战歌信使的报告将灰谷西部的情报传递给卡德拉克。",h="在佐拉姆加前哨站，战歌信使的报告将灰谷西部的情报传递给卡德拉克。",kw={"灰谷","卡德拉克","贫瘠之地","战歌报告","战歌氏族","战歌信使的报告","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="这份报告揭示了在敌对的暗夜精灵领地上维持偏远前哨站的艰难。信使维系着灰谷与贫瘠之地之间的通信。",["race:Orc"]="身为兽人，你知道战歌斥候和信使冒着生命危险穿行于密林之中，将战术报告送交卡德拉克，并推动氏族的领土主张。"},sec={{t="西线的耳目",b="佐拉姆加前哨站的战歌信使监视着灰谷西部的海岸及附近的威胁。这份军报记录了前哨站斥候收集的见闻，并汇报当地的动向。军报被送往贫瘠之地边境的卡德拉克哨塔，帮助部落领袖巩固阵地，并筹划向精灵世代居住的森林进军。"}},faq={{q="战歌信使的报告是什么？",a="战歌信使的报告是灰谷西部佐拉姆加前哨站的战歌信使发出的一份书面军报。它将前线的见闻传递给贫瘠之地边境的部落领袖。",al={"信使报告","战歌信使的报告是什么","战歌报告 佐拉姆"}},{q="这份军报来自哪里？",a="这份军报来自佐拉姆加前哨站的战歌信使，前哨站位于灰谷最西端的海岸，靠近佐拉姆海岸。",al={"信使位置","战歌信使在哪里","谁提供信使报告"}},{q="谁接收这份报告？",a="接收报告的是卡德拉克，他是驻守在贫瘠之地北部边境哨塔中的战歌指挥官。",al={"交给谁","卡德拉克报告","递送信使报告"}},{q="卡德拉克为什么需要这份军报？",a="卡德拉克负责协调战歌氏族向灰谷进军的军事行动。来自佐拉姆加等前哨站的军报，让他了解敌军的抵抗、海上进军路线以及当地领土的控制情况。",al={"为什么需要信使报告","战歌报告的用途"}}},fp="21,90,25.339.0,34.137.0,35.120.0,25.103.0,35.198.0"}
P.entries["item:warsong-saw-blades"] = {n="战歌锯条",s="战歌锯条让部落在灰谷的伐木机械持续运转。战歌氏族依靠地精制造的机械伐木，这些锯条为其皆伐作业提供保障。",h="战歌锯条让部落在灰谷的伐木机械持续运转。战歌氏族依靠地精制造的机械伐木，这些锯条为其皆伐作业提供保障。",kw={"灰谷伐木","洛克·奥卡尔","皮克希尔","碎木岗哨","战歌伐木营地","战歌锯条"},ang={["faction:Horde"]="部落向卡利姆多中部的扩张依赖灰谷的木材，因此，维护战歌锯木设备的正常运转是一项战略要务。",["race:NightElf"]="身为暗夜精灵，在你眼中，每一箱地精锻造的锯条，都是对灰谷古老林冠及其神圣林地之灵的又一次侵袭。"},sec={{t="机械化伐木",b="在灰谷，战歌氏族的伐木作业依赖地精工程师提供和维护的重型机械。单靠斧头无法满足部落对卡利姆多木材的需求，因此需要用蒸汽机和圆锯切割原木。灰谷古老的硬木很快就会使普通锯条变钝、断裂。替换用的锯条必须源源不断地运来，战歌伐木营地的锯木厂才能持续运转。"},{t="保障货物运输",b="将机械零件运过争夺中的领土，总会遇到麻烦。敌对的熊怪和萨特经常截下其他伐木物资，而锯条的运输则由碎木岗哨的皮克希尔等地精联络人经手。伐木主管洛克·奥卡尔收集锯条、绳索、油和斧头，让营地在灰谷守护者的破坏下仍能维持运转。"}},faq={{q="战歌锯条有什么用途？",a="这些锯条用于替换灰谷东南部战歌伐木营地内圆锯和重型伐木机械上的部件。",al={"锯条用途","锯条使用","它们有什么用"}},{q="谁向部落提供这些锯条？",a="地精商人和后勤人员负责经手这些锯条。碎木岗哨的地精皮克希尔负责接收运给战歌氏族的锯条。",al={"谁制造锯条","锯条来自哪里","锯条供应商"}},{q="部落为什么需要这么多锯条？",a="灰谷茂密而古老的树木很快就会磨钝锯齿。部落需要大量木材，在杜隆塔尔和贫瘠之地的干旱平原上建造定居点，而持续不断的伐木作业使机械磨损的速度超过了当地铁匠重新锻造的速度。",al={"为什么要这么多锯条","战歌伐木需求","为什么需要锯子"}},{q="谁在收集伐木物资？",a="洛克·奥卡尔是一名兽人，负责监督从碎木岗哨出发的补给运输，他组织收集锯条、油、绳索和斧头，送往伐木营地。",al={"谁需要锯条","谁收取锯条","洛克·奥卡尔任务"}}},fx={["12f75673"]={q="什么是战歌锯条？",a="这些坚固耐用的金属锯条是战歌氏族用于工业伐木机械的重要部件。兽人严重依赖机械化伐木来采伐灰谷古老而茂密的木材，但粗壮的树木会很快磨损锯齿。若没有稳定供应的锋利耐用锯条，战歌氏族的伐木作业就会停摆。",al={"什么是战歌锯条","战歌锯条物品","什么是锯条"}}},fp="18,181,19.368.0,21.326.0,41.126.0,43.140.0,43.258.0,39.162.0"}
P.entries["item:warsong-scout-update"] = {n="战歌斥候的报告",s="在碎木岗哨，一名战歌斥候记录着部落需要掌握的灰谷情报。",h="在碎木岗哨，一名战歌斥候记录着部落需要掌握的灰谷情报。",kw={"灰谷","贫瘠之地","卡德拉克","报告","斥候","碎木","更新","战歌"},ang={["faction:Horde"]="随着部落向森林深处扩张，战歌军情文书维系着部落在灰谷的前线营地与贫瘠之地补给基地之间的联系。",["race:Orc"]="身为兽人，你知道战歌氏族承担着灰谷伐木行动的重任。行动迅速的斥候帮助守住氏族在森林中的前哨。"},sec={{t="古老森林中的耳目",b="部落在灰谷寻求木材和补给通道，战歌斥候则监视着这片森林。他们以设有防御工事的碎木岗哨为据点，追踪暗夜精灵哨兵以及这片区域内的动向。他们的观察报告随日常命令一同送到驻守贫瘠之地与灰谷边境的卡德拉克手中。他据此评估部队的战备状况，并协调这片争夺中的森林里的补给与通行。"}},faq={{q="战歌斥候的报告是什么？",a="战歌斥候的报告汇集了一名驻守灰谷东部碎木岗哨的战歌斥候所观察到的情况，供边境的指挥官参阅。",al={"斥候报告","战歌斥候军情文书","战歌斥候报告"}},{q="谁需要这份报告？",a="卡德拉克需要这份报告。这位部落军官在一座瞭望塔上监视着贫瘠之地北部与灰谷之间的边境，并利用这份报告规划军事行动。",al={"谁需要这个","卡德拉克报告","报告交给谁"}},{q="战歌斥候在哪里？",a="这名斥候驻守在碎木岗哨内，那是部落沿着灰谷东部主干道建立的据点。",al={"斥候在哪","斥候位置","寻找战歌斥候"}},{q="为什么这些军情文书对部落如此重要？",a="暗夜精灵拼死保卫灰谷。斥候报告向部落领袖预警伏击和部队调动，帮助保障补给路线与伐木营地的安全。",al={"为何重要","战歌后勤","灰谷情报"}}},fp="20,70,26.383.0,33.130.0,25.172.0,35.116.0,51.157.0"}
P.entries["item:water-of-the-seers"] = {n="先知之水",s="在血蹄村，年轻的牛头人在接受部族试炼前，会饮下神圣的先知之水。这种饮剂让心灵感知到灵魂世界，并召来Plains Vision为他们引路。",h="在血蹄村，年轻的牛头人在接受部族试炼前，会饮下神圣的先知之水。这种饮剂让心灵感知到灵魂世界，并召来Plains Vision为他们引路。",kw={"血蹄村","平原幻象","幻象仪祭","先知奥萨迪·智慧行者","部族篝火","先知之水"},ang={["class:Shaman"]="身为萨满祭司，先知之水让你早早体会到与灵魂世界沟通的滋味。",["race:Tauren"]="身为牛头人，饮下先知之水是你迈向成年、传承族人神圣传统的一部分。"},sec={{t="灵魂的容器",b="年轻的牛头人在血蹄村的部族篝火前饮下先知之水。部族的秘法师为古老的幻象仪祭调制这种饮剂。它能开启饮用者的灵视，随后Plains Vision便会从余烬中显现，引领他们前往先知奥萨迪·智慧行者所在之处。"}},faq={{q="饮下先知之水后会发生什么？",a="在部族篝火旁饮下先知之水，会开启你的灵魂感知。平原上的幻象会从火焰中显现，引领你穿越莫高雷。",al={"先知之水有什么作用","饮用先知之水","平原幻象之水"}},{q="应该在哪里饮下先知之水？",a="在血蹄村的大型部族篝火前饮下先知之水，篝火就在萨满长者们的北面不远处。",al={"在哪里喝先知之水","先知之水位置","部族篝火位置"}},{q="幻象会引领你去见谁？",a="平原上的幻象会引领你向西北方前进，进入莫高雷的山麓，抵达先知奥萨迪·智慧行者所在的洞穴。他在那里等候，为你解读这段旅程。",al={"狼去哪里","平原幻象目的地","先知是谁"}}},fp="18,189,23.279.0,51.156.0,35.114.0,33.134.0"}
P.entries["item:water-pitcher"] = {n="水罐",s="在红云台地，水罐用来将当地水井中清冽的泉水运回纳拉其营地。鹰风酋长的母亲让年轻的牛头人把水罐带回来，以此教导他们谦逊、奉献和尊敬部族长者。",h="在红云台地，水罐用来将当地水井中清冽的泉水运回纳拉其营地。鹰风酋长的母亲让年轻的牛头人把水罐带回来，以此教导他们谦逊、奉献和尊敬部族长者。",kw={"一项卑微的任务","纳拉其营地","鹰风酋长","鹰风酋长的母亲","莫高雷水井","红云台地","水罐"},ang={["race:Tauren"]="对于在红云台地逐渐成年的年轻牛头人来说，提送水罐是早期的一课：尊敬长者、帮助族人，才是力量的根基。"},sec={{t="谦逊的一课",b="水罐放在纳拉其营地东南方的水井旁。鹰风酋长的母亲让一名新手把它装满水，再送到鹰风酋长那里。这项杂务考验着年轻勇士的品格，让他们明白，身为部族的守护者，任何职责都不卑微。照料族人的日常所需，与狩猎时挥舞武器同样重要。"}},faq={{q="水罐有什么用途？",a="水罐用来将清冽的井水运回纳拉其营地。提着它穿过平原，考验着年轻的冒险者是否愿意为了部族的福祉承担日常劳作。",al={"水罐用途","为什么要提送水罐","水罐谦卑任务"}},{q="在哪里能找到水罐？",a="你可以在红云台地上、纳拉其营地东南方的水井旁找到水罐，就在鹰风酋长的母亲料理日常事务的地方附近。",al={"水罐位置","水罐在哪里","莫高雷寻找水罐"}},{q="是谁让你去取水罐？",a="鹰风酋长的母亲让年轻的旅者去取水罐。她年事已高，腿脚不便，难以走完这段路，于是便让热心的年轻人借此考验自己的活力与谦逊。",al={"谁发布水罐任务","鹰风酋长的母亲水罐"}},{q="水罐装满后要交给谁？",a="你要把装满水的水罐送到纳拉其营地的鹰风酋长那里。他认为，这一举动证明了送水者有为部族效力的诚心与奉献精神。",al={"水罐交给谁","运送水罐","把水罐送到哪里"}}},fp="13,190,20.330.0,35.168.0,36.131.0,40.169.0,49.154.0"}
P.entries["item:webwood-egg"] = {n="树林蜘蛛的卵",s="树林蜘蛛的卵藏在幽影谷黑丝洞的巢穴中。博物学者寻找能够孵化的卵，以便在安全的实验室里研究幼蛛。",h="树林蜘蛛的卵藏在幽影谷黑丝洞的巢穴中。博物学者寻找能够孵化的卵，以便在安全的实验室里研究幼蛛。",kw={"奥达希尔","吉尔沙兰","幽影谷","黑丝洞","蜘蛛卵","泰达希尔","树林蜘蛛的卵"},ang={["class:Druid"]="身为德鲁伊，你可以了解受污染的Webwood蜘蛛如何繁殖，以及它们的行为习性。这能为恢复泰达希尔遭到破坏的自然平衡提供线索。",["race:NightElf"]="身为守护泰达希尔神圣枝干的年轻kaldorei，你收集这些卵，帮助学者调查正在世界之树本土野生生物中蔓延的异常污染。"},sec={{t="受控的标本",b="成年的树林蜘蛛带有剧毒，太过危险，单凭一名研究者无法驯服或制服。因此，基尔沙兰·风行者这样的学者会前往黑丝洞，从隐蔽的卵堆中收集尚未孵化的卵。这些卵可以安全携带，孵出的幼蛛也能被关在容器中。博物学者可以研究它们，而不必面对成年蜘蛛致命的毒牙。"},{t="送往达纳苏斯",b="泰达希尔的本土野生生物受到腐化，变得异常凶暴，令遍布枝干各处的学者深感不安。在奥达希尔收集到的卵和毒液将被送往达纳苏斯。研究者希望在受控的环境中饲养并观察这些蜘蛛，进一步了解正在世界之树枝干间蔓延的黑暗侵蚀。"}},faq={{q="在哪里能找到树林蜘蛛的卵？",a="树林蜘蛛的卵成堆藏在黑丝洞的隧道深处，这座洞穴位于幽影谷西北部。",al={"树林蜘蛛的卵位置","树林蜘蛛的卵在哪里","寻找树林蜘蛛的卵"}},{q="谁需要树林蜘蛛的卵？",a="奥达希尔的研究者基尔沙兰·风行者需要这种卵，以研究那些侵扰幽影谷的凶暴蛛形生物。",al={"谁需要树林蜘蛛的卵","交付卵","基尔沙兰的卵"}},{q="为什么要收集卵，而不是捕捉蜘蛛？",a="成年的树林蜘蛛十分危险，体型也过于庞大，难以捕捉和关押。尚未孵化的卵可以安全运输，并在孵化前放进牢固的围栏中。",al={"为什么要卵","为什么不捕捉活蜘蛛"}},{q="收集到的卵会如何处理？",a="吉尔沙兰会安排将卵和提取的蜘蛛毒液送往达纳苏斯。在那里，学者们可以远离野外的危险，研究这些生物。",al={"卵送往哪里","卵的目的地"}}},fx={["0a629fbc"]={q="树林蜘蛛的卵是什么？",a="树林蜘蛛的卵是栖息在幽影谷的巨型树林蜘蛛产下的、尚未孵化的蜘蛛卵。卵中有尚未破壳的活体蜘蛛样本，让研究者能够研究这些凶猛的蛛形生物，而不必立刻冒着受伤的危险。",al={"树林蜘蛛的卵是什么","树林蜘蛛的卵背景"}},fd568742={q="树林蜘蛛的卵来自哪里？",a="这些卵是盘踞在幽影谷西北部黑丝洞中的巨型树林蜘蛛自然产下的。在洞穴深处阴暗、蛛网密布的角落里，蜘蛛守着成窝的卵，幼蛛在其中发育，等待孵化。",al={"树林蜘蛛的卵起源","树林蜘蛛的卵来自哪里","谁产下了树林蜘蛛的卵"}}},fp="11,151,20.355.0,22.353.0,29.104.0,26.118.0,49.178.0,46.163.0"}
P.entries["item:webwood-ichor"] = {n="树林蜘蛛的脓液",s="在幽影谷，树林蜘蛛的毒液让埃沃隆病入膏肓。迪兰妮亚·月光需要它们的脓液、紫蓝色蘑菇 和 月瓣百合花 来调制解毒剂。",h="在幽影谷，树林蜘蛛的毒液让埃沃隆病入膏肓。迪兰妮亚·月光需要它们的脓液、紫蓝色蘑菇 和 月瓣百合花 来调制解毒剂。",kw={"解毒剂","迪兰妮亚·月光","埃沃隆","幽影谷","黑丝洞","泰达希尔","树林蜘蛛的脓液","树林蜘蛛"},ang={["race:NightElf"]="作为一名守卫奥达希尔的年轻暗夜精灵，收集树林蜘蛛的脓液让你明白，泰达希尔最致命的毒物也可能蕴藏着自身的解药。"},sec={{t="以毒解毒",b="幽影谷的树林蜘蛛携带的毒液让埃沃隆病入膏肓。迪兰妮亚·月光请求收集它们的脓液、紫蓝色蘑菇 和 月瓣百合花，以配制解毒剂。"}},faq={{q="树林蜘蛛的脓液有什么用途？",a="幽影谷的迪兰妮亚·月光需要树林蜘蛛的脓液、紫蓝色蘑菇 和 月瓣百合花，为中毒的暗夜精灵埃沃隆配制解毒剂。",al={"树林蜘蛛的脓液用途","树林蜘蛛的脓液有什么用","为什么收集脓液"}},{q="树林蜘蛛的脓液从哪里来？",a="树林蜘蛛的脓液来自幽影谷西北部的 树林蜘蛛，尤其是黑丝洞周围和洞内的那些。",al={"哪里能找到树林蜘蛛的脓液","如何获得树林蜘蛛的脓液","树林蜘蛛的脓液掉落"}},{q="为什么要用蜘蛛的体液来治疗蜘蛛咬伤？",a="迪兰妮亚要求收集树林蜘蛛的脓液，作为埃沃隆解毒剂的一种原料。她没有解释脓液在混合物中如何起效。",al={"蜘蛛毒解药","为什么用毒液制作解毒剂"}}},fp="13,168,12.180.0,31.166.0,35.122.0,43.128.0"}
P.entries["item:webwood-spider-silk"] = {n="树林蜘蛛丝",s="树林蜘蛛丝采自泰达希尔林中的树林潜伏者。工匠对蜘蛛丝有诸多用途，但这些丝束却引起了世界之树枝桠间一些可疑人物的兴趣。",h="树林蜘蛛丝采自泰达希尔林中的树林潜伏者。工匠对蜘蛛丝有诸多用途，但这些丝束却引起了世界之树枝桠间一些可疑人物的兴趣。",kw={"多兰纳尔","蜘蛛丝","泰达希尔","树林潜伏者","树林蜘蛛丝","赛恩·腐蹄","赛恩的要求"},ang={["profession:Tailoring"]="身为裁缝，你或许会寻找蛛丝，但这些丝束牵涉的是与萨特之间的黑暗交易，而非寻常的织布活计。",["race:NightElf"]="身为刚离开幽影谷的年轻暗夜精灵，要谨慎选择猎杀的生物，尤其是当家园腹地附近一个独来独往的萨特催促你收集它们时。"},sec={{t="可疑的材料",b="多兰纳尔周围的树林潜伏者吐出的丝纤细而坚韧，采集起来却很危险。赛恩·腐蹄是林间道路旁的一名萨特，他让年轻的冒险者收集这些蜘蛛丝，以及夜刃豹的獠牙和巨翼枭的羽毛。他说，自己在森林里的生意需要这些稀有材料，初来乍到的冒险者便照办了，没有追问他腐化的本性或真正的动机。"}},faq={{q="哪里能找到树林蜘蛛丝？",a="树林蜘蛛丝采自泰达希尔野外的树林潜伏者及其近缘蜘蛛，尤其是多兰纳尔周围。",al={"树林蜘蛛丝位置","谁掉落树林蜘蛛丝","哪里获取树林蜘蛛丝"}},{q="谁想要这些蜘蛛丝？",a="赛恩·腐蹄想要这些蜘蛛丝。这名萨特在幽影谷与多兰纳尔之间道路北侧不远处，暗中进行着交易，并要求收集蜘蛛丝、猫头鹰羽毛和猛兽獠牙。",al={"谁需要树林蜘蛛丝","树林蜘蛛丝任务给予者","赛恩·腐蹄蜘蛛丝"}},{q="赛恩·腐蹄为什么想要树林蜘蛛丝？",a="赛恩说，他在森林里的生意需要这些蜘蛛丝作为材料，却对详情守口如瓶。",al={"赛恩·腐蹄的动机","赛恩为什么要蜘蛛丝"}},{q="玩家能用树林蜘蛛丝制作裁缝物品吗？",a="不能。虽然采来的确实是蜘蛛丝，但它是完成任务所需的材料，并非普通的裁缝布料。",al={"树林蜘蛛丝是裁缝材料吗","树林蜘蛛丝制作"}}},fp="19,171,17.347.0,39.117.0,20.171.0,48.99.1,50.114.0"}
P.entries["item:webwood-venom-sac"] = {n="树林蜘蛛的毒囊",s="在幽影谷，树林蜘蛛的毒囊引起了研究泰达希尔生长状况的博物学家的注意。这些毒囊来自体型异常巨大的蜘蛛，其中的毒液或许能揭示这棵新生的世界之树如何改变了当地的野生生物。",h="在幽影谷，树林蜘蛛的毒囊引起了研究泰达希尔生长状况的博物学家的注意。这些毒囊来自体型异常巨大的蜘蛛，其中的毒液或许能揭示这棵新生的世界之树如何改变了当地的野生生物。",kw={"奥达希尔","基尔沙兰·风行者","幽影谷","黑丝洞","泰达希尔","毒液","树林蜘蛛","树林蜘蛛的毒囊"},ang={["class:Druid"]="对于感知自然平衡的德鲁伊而言，这些毒囊的强烈毒性是令人不安的证据，表明泰达希尔的枝干间出了问题。",["race:NightElf"]="身为幽影谷的一名年轻暗夜精灵冒险者，你收集这些样本，帮助学者了解枝干上的故乡为何有如此奇异的生态。"},sec={{t="泰达希尔生长的征兆",b="树林蜘蛛栖息在黑丝洞内及其周边，与其他地方一种体型小得多的蜘蛛有亲缘关系。它们突然增大的体型和凶猛的捕食习性令暗夜精灵研究者深感忧虑。基尔沙兰·风行者等博物学家研究它们毒囊中的毒液，检验其毒性和成分。他们希望了解，泰达希尔未经祝福的迅速生长，正在如何改变栖息于其枝干上的生物。"}},faq={{q="哪里能找到树林蜘蛛的毒囊？",a="树林蜘蛛的毒囊来自幽影谷北部的蜘蛛，尤其是黑丝洞内及其周边的蜘蛛。",al={"哪里掉落","树林蜘蛛的毒囊位置","蜘蛛毒液位置"}},{q="谁需要这些毒囊？",a="基尔沙兰·风行者是幽影谷奥达希尔的一位暗夜精灵研究者，他在返回达纳苏斯之前收集这些毒囊，以研究蜘蛛的生物特性。",al={"谁需要毒囊","基尔沙兰·风行者任务"}},{q="树林蜘蛛为什么如此巨大？",a="研究者认为，泰达希尔的出现与迅速生长改变了当地的野生生物，使普通蜘蛛变成了体型庞大、极具攻击性的捕食者。",al={"蜘蛛为何巨大","树林蜘蛛体型"}},{q="这种毒液会用来制作解毒药吗？",a="基尔沙兰收集这些毒囊，是为了进行比较和研究。这一带的蜘蛛毒液十分危险，需要埃沃隆的解毒药等药剂，才能救活那些在林中被咬伤的人。",al={"是否用于治疗","解毒药材料"}}},fp="17,183,32.382.0,35.108.0,27.151.0,37.149.0,39.180.0"}
P.entries["item:well-stone"] = {n="水井石",s="莫高雷各处的水井旁，都散落着水井石。它们蕴含的大地与水之魔法，可用于调制牛头人成年仪式所需的先知之水。",h="莫高雷各处的水井旁，都散落着水井石。它们蕴含的大地与水之魔法，可用于调制牛头人成年仪式所需的先知之水。",kw={"琥珀颗粒","血蹄村","莫高雷","幻象仪祭","先知之水","水井石","扎尔曼·双月"},ang={["class:Shaman"]="萨满祭司知道，水井石是大地与水之魔法的天然锚点。石中潜藏的灵力汇聚于仪式用的混合药液中，带来蜕变。",["race:Tauren"]="对年轻的牛头人而言，收集水井石是展现自身与大地相通的重要一步。这让他们懂得，大地的有形元素如何带来心灵的启迪。"},sec={{t="大地能量的容器",b="水井石散落在莫高雷水井旁松软的泥土中，吸收着草原与地下水的灵性共鸣。萨满祭司和扎尔曼·双月这样的先知都知道，这些石头是承载生命魔法的容器，并非普通的河中卵石。它们与草原参天大树下磨碎的琥珀颗粒混合后，其矿物特性便能调和药液，让年轻的牛头人在神圣的幻象仪祭仪式中进入幻象。"}},faq={{q="水井石有什么用途？",a="水井石与琥珀颗粒混合，可酿制先知之水。试炼者在部族的篝火前饮下它，寻求证明自身心灵已然成熟的人便会获得指引前路的幻象。",al={"水井石用途","水井石有什么用","为什么收集水井石"}},{q="哪里能找到水井石？",a="水井石散落在莫高雷各处公共水井周围的地面上，那里是滋养草原的水分与土壤交融之处。",al={"哪里能找到水井石","水井石位置","莫高雷水井石"}},{q="谁需要这些石头？",a="扎尔曼·双月是血蹄村一位备受敬重的秘法师，他指引试炼者收集水井石，作为幻象仪祭仪式的一部分。",al={"谁需要水井石","扎尔曼·双月水井石","幻象仪祭石头"}}},fp="10,150,26.433.0,30.196.0,28.141.0,26.123.0"}
P.entries["item:wendigo-mane"] = {n="雪怪的鬃毛",s="雪怪游荡在丹莫罗冰封的峭壁间，靠鬃毛抵御山中的严寒。驾驶员迪恩·石轮正好需要这些鬃毛。",h="雪怪游荡在丹莫罗冰封的峭壁间，靠鬃毛抵御山中的严寒。驾驶员迪恩·石轮正好需要这些鬃毛。",kw={"丹莫罗","毛皮","灰色洞穴","卡拉诺斯","鬃毛","皮毛","石轮","特罗普","雪怪"},ang={["profession:Engineering"]="丹莫罗的矮人机械有着冰冷的金属驾驶舱。雪怪毛皮可以制成实用的保暖衬里。",["race:Dwarf"]="年轻的矮人会猎杀灰色洞穴的雪怪，向卡拉诺斯的老兵证明自己的坚韧。"},sec={{t="铁工坊的暖意",b="雪怪游荡在丹莫罗的雪堆间，粗硬的毛皮为它们抵御刺骨的寒风。在卡拉诺斯外，驾驶员迪恩·石轮派冒险者前往灰色洞穴，收集雪怪厚实的鬃毛。他打算把这些鬃毛织成保暖地毯，铺在他引以为傲的矮人攻城车巨魔犁的内部甲板上。"}},faq={{q="哪些生物会掉落雪怪的鬃毛？",a="雪怪的鬃毛来自丹莫罗雪地中的雪怪。其中包括幼年雪怪、成年的雪怪，以及瓦加什、饥饿的雪怪和冰须这样的首领。",al={"雪怪的鬃毛在哪里掉落","谁掉落雪怪的鬃毛","雪怪的鬃毛来源"}},{q="驾驶员迪恩·石轮为什么需要这些鬃毛？",a="驾驶员迪恩·石轮想用这些鬃毛织成保暖地毯，铺在他的攻城车巨魔碾压者的内部甲板上。当这台机器驶过冰封的地形时，厚实的毛皮能让他的操作位置保持温暖。",al={"石轮为什么需要鬃毛","驾驶员迪恩·石轮的地毯","鬃毛的用途"}},{q="去哪里猎取雪怪的鬃毛最好？",a="驾驶员迪恩·石轮推荐灰色洞穴，那是一片位于卡拉诺斯正西方山中的洞穴群。洞内和周围的山坡上到处都是雪怪。",al={"灰色洞穴位置","哪里可以猎杀雪怪","丹莫罗雪怪洞穴"}},{q="猎杀雪怪危险吗？",a="危险。雪怪是凶猛的掠食者，领地意识强，力大无穷，皮糙肉厚。矮人训练师认为，深入雪怪巢穴与它们交锋，是对巡山人勇气和战斗意志的早期考验。",al={"雪怪难杀吗","与雪怪战斗"}}},fx={["9c5452b4"]={q="雪怪的鬃毛是什么？",a="雪怪的鬃毛是一簇浓密蓬乱的粗毛，取自徘徊在丹莫罗积雪山崖间的凶猛雪怪。这种结实的毛皮能让这些野兽抵御山间刺骨的暴风雪，既坚韧又保暖，是制作粗制工艺品的上好材料。",al={"雪怪的鬃毛是什么","雪怪的鬃毛物品","雪怪毛皮"}},e05af805={q="雪怪的鬃毛从哪里来？",a="这些鬃毛直接取自游荡在丹莫罗的野生雪怪，尤其是卡拉诺斯以西的灰色洞穴等巢穴附近的雪怪。这些天然兽皮由猎人取得，他们甘愿冒险面对山中野兽的利爪和尖牙。",al={"雪怪的鬃毛从哪里来","谁掉落雪怪的鬃毛","雪怪的鬃毛来历"}}},fp="12,133,24.300.0,36.170.0,42.199.0,57.151.0,31.198.0"}
P.entries["item:whitestone-oak-lumber"] = {n="白石橡木",s="在月溪镇地下，迪菲亚加工白石橡木，用来建造舰队。这种木材坚固耐用，也吸引了寻找神圣武器柄材的联盟铁匠。",h="在月溪镇地下，迪菲亚加工白石橡木，用来建造舰队。这种木材坚固耐用，也吸引了寻找神圣武器柄材的联盟铁匠。",kw={"死亡矿井","地精木雕","乔丹·斯迪威尔","圣骑士战锤","正义试炼","白石橡木"},ang={["class:Paladin"]="身为圣骑士，你必须从迪菲亚的地下船坞取得这种木材，用于乔丹·斯迪威尔的正义试炼。他用它为圣光的捍卫者打造神圣的战锤。",["profession:Blacksmithing"]="在斯迪威尔的武器设计图中，白石橡木、精炼矿石和一颗宝石融为一体。它们共同平衡了武器的重量、耐久性与超自然共鸣。"},sec={{t="神圣的武器柄",b="铁炉堡城外的乔丹·斯迪威尔需要白石橡木，打造一件配得上圣光勇士的武器。他将木材与净化过的科尔宝石和精炼金属结合，制成平衡而坚韧的武器柄。这根武器柄必须承受正义试炼期间引导的神圣能量。"},{t="地下船坞的木材",b="在月溪镇下方的死亡矿井深处，地精木匠加工白石橡木，为迪菲亚潜行者建造隐秘的作战舰队。这种木材纹理致密，能够承受重压与猛烈撞击。军械匠在制作仪式用品和作战装备时，若需要比普通白蜡木或松木更坚固的木材，就会选用它。"}},faq={{q="哪里能找到白石橡木？",a="在西部荒野月溪镇下方的死亡矿井深处，地精木匠加工着白石橡木。迪菲亚潜行者在那里建造秘密的巨型战舰。",al={"白石橡木获取地点","白石橡木位置","白石橡木掉落者"}},{q="谁会使用这种木材？",a="乔丹·斯迪威尔是丹莫罗铁炉堡城门附近的一名铁匠，他需要这种木材，为成长中的圣骑士打造一件专用武器。",al={"白石橡木需求者","白石橡木交付"}},{q="这种木材用来制作什么？",a="乔丹·斯迪威尔将这种坚韧的木材制成双手圣锤的锤柄。他为完成正义试炼的人锻造这把锤子。",al={"白石橡木用途","乔丹·斯迪威尔锻造什么"}},{q="地精的木材为何适合制作神圣武器？",a="迪菲亚潜行者使用的木材质地致密，坚固得足以建造战舰。乔丹·斯迪威尔看出，这种木材能够承受神圣力量的冲击。",al={"为何使用地精木材","为何使用死亡矿井木材"}}},fx={["3fba151d"]={q="白石橡木是什么？",a="白石橡木是一种优质的专用木材，深受能工巧匠的青睐。它以坚固和质地优良著称，是锻造圣光武器杰作时制作木柄或握把的必备材料。",al={"白石橡木是什么","白石橡木","白石木材是什么"}},["9364a134"]={q="白石橡木从哪里来，又是谁加工的？",a="这种木材在西部荒野的死亡矿井深处采伐并加工。受雇于迪菲亚潜行者的地精木雕工负责将其加工成形，他们在地下进行非法建造工程的同时，也砍伐和加工这些木材。",al={"白石橡木从哪里来","白石橡木来源","谁加工白石橡木"}},e7d39b03={q="乔丹·斯迪威尔为什么需要白石橡木？",a="武器锻造师乔丹·斯迪威尔需要这种特定的木材，为一位神圣的圣骑士锻造一把非凡的武器。这种坚固的橡木将与精炼矿石、净化过的科尔宝石以及他父亲的铁锤配合使用，为他心目中最出色的作品奠定基础。",al={"为什么需要白石橡木","乔丹为什么需要白石橡木","白石橡木用途"}}},fp="21,150,13.284.1,25.279.1,37.158.1,21.134.0,30.148.0,48.145.0"}
P.entries["item:wildmane-cleansing-totem"] = {n="蛮鬃之井净化图腾",s="莫高雷的蛮鬃水井还剩最后一次净化。冰蹄和雷角的水井净化之后，穆尔·雷角为北方的水井准备了一根图腾。",h="莫高雷的蛮鬃水井还剩最后一次净化。冰蹄和雷角的水井净化之后，穆尔·雷角为北方的水井准备了一根图腾。",kw={"血蹄村","地精毒素","莫高雷","穆尔·雷角","牛头人","蛮鬃之井净化图腾","蛮鬃水井"},ang={["class:Shaman"]="身为萨满祭司，你通过雕刻的图腾引导灵魂净化之力，治愈被肆意工业开发所伤的水之灵。",["race:Tauren"]="身为牛头人，恢复蛮鬃水井是你对Earth Mother应尽的义务，也是保护祖先家园免受外来工业毒素侵害的方式。"},sec={{t="净化神圣的水井",b="蛮鬃水井仍需净化。地精的开发活动毒害了这片土地，污染了莫高雷稀缺的水源，因此牛头人以神圣的仪式对抗这场灾祸。冰蹄和雷角的水井净化之后，穆尔·雷角为雷霆崖以北的水井制作了最后一根图腾。图腾注入了自然之灵的力量，能净化污浊的井水，让滋养生命的清泉再次润泽平原。"}},faq={{q="蛮鬃之井净化图腾有什么用途？",a="这根图腾用于牛头人的净化仪式，清除雷霆崖以北蛮鬃水井中的毒素和污水。",al={"图腾有什么用","蛮鬃图腾用途","为何净化水井"}},{q="谁制作了蛮鬃之井净化图腾？",a="当你收集齐所需的材料，并净化莫高雷其他受污染的水井后，穆尔·雷角就会制作这根图腾。",al={"谁给了我这根图腾","穆尔·雷角的图腾","净化图腾哪里获得"}},{q="莫高雷的水井为何会被下毒？",a="地精的开发活动将毒素和工业废水带入莫高雷的水源，威胁着牛头人部族和平原的自然平衡。",al={"谁给水井下毒","水井为何有毒","地精毒害莫高雷"}},{q="这根图腾需要在哪里使用？",a="在雷霆崖以北的蛮鬃水井使用这根图腾。",al={"蛮鬃水井位置","蛮鬃水井在哪里","图腾带到哪里"}}},fp="24,191,26.406.0,52.143.0,41.118.0,44.150.0,38.64.0"}
P.entries["item:wiley-s-note"] = {n="威利的便笺",s="在湖畔镇，黑衣威利为格里安·斯托曼写下一封机密便笺，以偿还人情。便笺的内容揭示了迪菲亚潜行者结成的同盟，将暴风城的情报机构卷入了调查。",h="在湖畔镇，黑衣威利为格里安·斯托曼写下一封机密便笺，以偿还人情。便笺的内容揭示了迪菲亚潜行者结成的同盟，将暴风城的情报机构卷入了调查。",kw={"迪菲亚潜行者","格里安·斯托曼","马迪亚斯·肖尔","哨兵岭","si:7","石匠","黑衣威利","威利的便笺"},ang={["class:Rogue"]="身为潜行者，你看到黑衣威利和SI:7的首领马迪亚斯·肖尔经手这封密信。",["faction:Alliance"]="身为联盟的一员，你看到西部荒野的当地匪患被认定为一股有组织的势力，威胁着暴风城的稳定。"},sec={{t="危险的账簿",b="黑衣威利是湖畔镇的一名潜行者，他在赤脊山写下了这封密信。他将密信交给格里安·斯托曼，以偿还旧日的人情。在便笺中，威利讲述了自己所知的迪菲亚潜行者的计划。这个兄弟会在当地的豺狼人、狗头人和地精特工中都有盟友。"},{t="与石匠行会的关联",b="威利的便笺揭示了迪菲亚潜行者与石匠行会之间的关联，后者在第二次战争后重建了暴风城。格里安·斯托曼看出了这层关联在政治上的分量，于是将便笺送交军情七处的情报首脑马迪亚斯·肖尔。暴风城的情报机构就此加入了调查。"}},faq={{q="威利的便笺是谁写的？",a="便笺由湖畔镇的潜行者黑衣威利所写。他将便笺交给人民军的格里安·斯托曼，以偿还尚未还清的人情。",al={"威利的便笺作者","威利是谁","黑衣威利的便笺"}},{q="便笺中包含什么情报？",a="便笺警告说，迪菲亚潜行者正在策划一场庞大的阴谋，并在豺狼人、狗头人和地精中拥有盟友。格里安·斯托曼就其中更敏感的内容寻求建议。",al={"威利的便笺内容","便笺说了什么","迪菲亚便笺情报"}},{q="便笺需要送到哪里？",a="格里安·斯托曼在西部荒野的哨兵岭收到便笺。读过之后，他命人将便笺送往暴风城的SI:7总部，交给马迪亚斯·肖尔。",al={"威利的便笺交给谁","交付威利的便笺","便笺送到哪里"}},{q="格里安·斯托曼为什么将便笺送往SI:7？",a="格里安·斯托曼怀疑，便笺指向的阴谋远比匪患更深。他将便笺送交暴风城情报机构的首领马迪亚斯·肖尔，以便展开调查。",al={"为什么给马迪亚斯·肖尔看","为什么把便笺交给肖尔","si7威利的便笺"}}},fp="12,218,18.283.0,25.292.1,23.141.0,39.183.0,41.169.0,49.160.0"}
P.entries["item:william-s-shipment"] = {n="威廉的货物",s="闪金镇的威廉的货物将送往暴风城，交给他的兄弟摩根，里面装着从艾尔文森林的狗头人那里收集的蜡烛。",h="闪金镇的威廉的货物将送往暴风城，交给他的兄弟摩根，里面装着从艾尔文森林的狗头人那里收集的蜡烛。",kw={"蜡烛","闪金镇","狗头人蜡烛","摩根·匹斯特","匹斯特的药剂店","暴风城","贸易区","威廉·匹斯特","威廉的货物"},ang={["faction:Alliance"]="作为联盟的一员，你协助保护艾尔文森林的矿洞，抵御狗头人的侵扰，并为首都的商店供应炼金原料。",["race:Human"]="作为人类，你能看到闪金镇的贸易将乡间村落与首都暴风城联系在一起。"},sec={{t="家族生意",b="威廉·匹斯特维系着闪金镇与首都之间的贸易。他在艾尔文森林收集货物，他的兄弟摩根则在暴风城的贸易区经营匹斯特的药剂店。威廉无法放下手头的事务北上，因此由信使将蜡和蜡烛送进城。"},{t="狗头人的蜡",b="威廉的货物里装满了来自艾尔文森林矿洞的狗头人蜡烛。他收集这些大蜡烛是为了其中的蜡，再将它们打包，送给匹斯特的药剂店的摩根。这些蜡会成为首都炼金生意所用的原料。"}},faq={{q="威廉的货物里装着什么？",a="货物里装着从艾尔文森林矿洞中的狗头人那里收集的蜡烛。威廉从过往的旅人手中收集这些蜡烛，再将它们打包，作为家族炼金店的原料。",al={"货物内容","箱子里有什么","威廉寄什么"}},{q="威廉要把这个包裹寄给谁？",a="威廉将包裹寄给他的兄弟摩根·匹斯特，他在暴风城的贸易区经营匹斯特的药剂店。",al={"谁收货","包裹送给谁","货物目的地"}},{q="药剂店为什么需要这么多蜡烛？",a="威廉说，他和兄弟需要这些大蜡烛中的蜡。他没有说明这些蜡会用来配制什么。",al={"炼金为什么需要蜡烛","匹斯特用蜡烛做什么","蜡烛用途"}},{q="威廉为什么不亲自送包裹？",a="威廉忙着在闪金镇打理事务、收集货物，抽不出时间走陆路前往暴风城。他雇用前往首都的旅人帮忙捎带包裹。",al={"威廉为什么不能去","威廉为什么需要信使"}}},fx={bf7eefd8={q="威廉的货物是什么？",a="威廉的货物是一包包装严实的大蜡烛，由闪金镇的威廉·匹斯特准备。这些蜡烛取自艾尔文森林矿洞中的狗头人，装箱后将送往暴风城的摩根·匹斯特手中。",al={"威廉的货物是什么","威廉的货物包裹","威廉的送货"}},["2b07f2a7"]={q="威廉的货物从哪里来，又是谁准备的？",a="这批货物直接来自威廉·匹斯特，他是一位住在闪金镇狮王之傲旅店的炼金师。威廉亲手将大蜡烛装入箱中，这些蜡烛取自盘踞在附近法戈第和玉石矿洞中的狗头人。",al={"谁准备了威廉的货物","威廉的货物从哪里来","威廉的货物来历"}}},fp="18,118,16.286.0,10.217.0,34.192.0,39.121.0,44.117.0,48.185.0"}
P.entries["item:wine-ticket"] = {n="酒票",s="在暴风城，雷纳多·加林纳用酒票为自家的店铺招揽顾客。向苏泽塔·加林纳出示一张酒票，就能免费领取一瓶黑葡萄酒。",h="在暴风城，雷纳多·加林纳用酒票为自家的店铺招揽顾客。向苏泽塔·加林纳出示一张酒票，就能免费领取一瓶黑葡萄酒。",kw={"加林纳酒店","黑皮诺","雷纳多·加林纳","暴风城运河","苏泽塔·加林纳","贸易区","酒票"},ang={["profession:Cooking"]="用这张酒票换来的Pinot Noir，很适合搭配从东部王国各地收集的丰盛肉食和奶酪。"},sec={{t="推广家族佳酿",b="在暴风城的贸易区附近，雷纳多·加林纳派发印制的酒票，为加林纳酒店招揽生意。这家精品葡萄酒商店就坐落在附近的运河边。每张酒票都能免费品尝黑葡萄酒，吸引好奇的路人和初来乍到的冒险者光顾这家家族店铺，希望他们成为常客。"}},faq={{q="酒票有什么用？",a="把酒票带给苏泽塔·加林纳，她就在暴风城贸易区运河边的加林纳酒店。她会凭票免费给你一瓶黑葡萄酒。",al={"酒票用途","酒票怎么用","酒票交到哪里"}},{q="这些酒票是谁发的？",a="雷纳多·加林纳在贸易区附近派发酒票，为自家的葡萄酒商店招揽顾客。",al={"谁发酒票","哪里领酒票"}},{q="酒票能换到什么酒？",a="出示酒票即可领取一瓶黑葡萄酒，这是加林纳家族在王国出售的最上等的葡萄酒之一。",al={"酒票奖励","能换到什么酒"}}},fx={eb06e870={q="酒票是什么？",a="酒票是在暴风城街头发放的促销凭券兼广告传单。它是加林纳酒店发出的邀请，持票者可以免费品尝加林纳家族最上等的佳酿。",al={"酒票是什么","酒票物品","酒铺广告票"}},["38c548d0"]={q="苏泽塔·加林纳为什么需要酒票？",a="苏泽塔·加林纳收取酒票，是为了确认你从她的兄弟雷纳多·加林纳那里收到了酒庄的街头促销凭券。凭券兑换时，他们会兑现促销承诺，赠送一瓶黑皮诺，欢迎新顾客光临运河边的店铺。",al={"苏泽塔为什么需要酒票","为什么上交酒票","为什么需要酒票"}}},fp="11,157,28.333.0,34.170.0,28.106.0,41.111.0"}
P.entries["item:winterhoof-cleansing-totem"] = {n="冰蹄之井净化图腾",s="在冰蹄水井，荆棘谷地精污染了莫高雷平原下的水源。穆尔·雷角制作了一根图腾来净化水源。",h="在冰蹄水井，荆棘谷地精污染了莫高雷平原下的水源。穆尔·雷角制作了一根图腾来净化水源。",kw={"血蹄村","净化","莫高雷","穆尔·雷角","图腾","荆棘谷地精","水井","冰蹄"},ang={["class:Shaman"]="身为萨满祭司，你运用大地与流水的和谐之力，驱除人为的污染，践行萨满之道。",["race:Tauren"]="对牛头人而言，淡水遭到亵渎，触及了他们与Earth Mother之间联系的根本。图腾的仪式有助于守护他们的家园。"},sec={{t="净化泉水",b="穆尔·雷角在血蹄村制作冰蹄之井净化图腾。荆棘谷地精旗下的地精在作业中污染了莫高雷的地下水。穆尔将守护魔法注入雕刻好的木头，用来清除外来的毒素。图腾被带过敌对地精守卫的防线，送到冰蹄水井，通过一场集中的仪式驱散污染。平原上游荡的兽群和当地部族重新有了洁净的饮用水。"}},faq={{q="冰蹄之井净化图腾有什么用途？",a="你将图腾带到血蹄村东南方的冰蹄水井，举行仪式，清除含水层中的污染。",al={"净化图腾用途","冰蹄图腾用法","图腾有什么作用"}},{q="这根图腾是谁制作的？",a="穆尔·雷角是血蹄村一位受人敬重的牛头人，他雕刻并准备好图腾，以修复冰蹄水井遭受的破坏。",al={"谁制作了冰蹄图腾","净化图腾制作者","穆尔图腾"}},{q="冰蹄水井为何受到污染？",a="荆棘谷地精在泉水周围建立了营地。其伐木和采矿机械排出的污水、废料和化学淤泥污染了这处天然饮水地。",al={"谁污染了冰蹄水井","水井污染原因","水井为何变脏"}},{q="净化仪式完成后会发生什么？",a="浑浊的水重新变得洁净无害，当地的野生动物和迁徙的牛头人群体都能安全地饮用井水。",al={"使用图腾之后","水井净化结果","水井能否修复"}}},fp="26,138,20.441.0,48.139.0,23.131.0,43.167.0,51.137.0"}
P.entries["item:witchwing-talon"] = {n="巫翼鹰身人的爪子",s="在贫瘠之地西北部，巫翼鹰身人的爪子是鹰身人劫掠者已被消灭的凭证。十字路口的部落斥候收集这些爪子作为证据，力求确保重要商队路线的安全。",h="在贫瘠之地西北部，巫翼鹰身人的爪子是鹰身人劫掠者已被消灭的凭证。十字路口的部落斥候收集这些爪子作为证据，力求确保重要商队路线的安全。",kw={"贫瘠之地","商队","十字路口","达索克·快刀","鹰身人","爪子","巫翼"},ang={["class:Rogue"]="达索克·快刀看重悄无声息而又精准的袭击。在他看来，这些锋利的爪子证明，一名技艺娴熟的杀手已经向空中的掠食者下手。",["faction:Horde"]="商队将卡利姆多各处分散的部落前哨连接起来，因此清剿鹰身人巢穴有助于保障边疆的安全。"},sec={{t="来自巢穴的战利品",b="巫翼鹰身人从十字路口西北方的巢穴出动，袭击部落的补给商队。斥候达索克·快刀负责协调针对这群鹰身人各级成员的打击行动。达索克要求拿出每个食腐者已被杀死的实物证据，而这些爪子正是凭证。有了劫掠者已被消灭的证据，斥候们就能先削弱这群鹰身人的兵力，再向其更高层的首领发起攻击。"}},faq={{q="谁需要巫翼鹰身人的爪子，又是为什么？",a="十字路口的兽人斥候达索克·快刀负责收集这些爪子。他正筹划一场针对巫翼族群的战役，需要八只爪子，证明其前线劫掠者已被杀死。",al={"谁需要爪子","巫翼鹰身人的爪子任务给予者","达索克·快刀爪子"}},{q="哪些鹰身人身上有这些爪子？",a="巫翼鹰身人的爪子来自贫瘠之地西北部的鹰身人，包括在悬崖和干燥山脊一带筑巢的普通鹰身人和巫翼游荡者。",al={"什么掉落巫翼鹰身人的爪子","哪些鹰身人有爪子"}},{q="为什么要对付巫翼鹰身人？",a="巫翼鹰身人越来越猖狂，在贫瘠之地各处袭击部落的补给线和贸易商队。达索克打算先削减它们的底层兵力，再对付它们的副官和女族长。",al={"为什么杀 巫翼 鹰身人","鹰身人劫掠者的目的"}}},fp="15,169,24.338.0,35.198.0,33.160.0,45.199.0"}
P.entries["item:wolf-heart-sample"] = {n="狼心样本",s="狼心样本即将送往十字路口，将来自洛丹伦的染病狼组织带到卡利姆多。皇家药剂师学会想要了解北方毒素对贫瘠之地本土野兽的影响。",h="狼心样本即将送往十字路口，将来自洛丹伦的染病狼组织带到卡利姆多。皇家药剂师学会想要了解北方毒素对贫瘠之地本土野兽的影响。",kw={"药剂师赫布瑞姆","药剂师伦弗利尔","贫瘠之地","十字路口","洛丹伦","皇家药剂师学会","毒素","狼心样本"},ang={["faction:Horde"]="身为部落的一员，你协助将研究试剂运过大海，将幽暗城与贫瘠之地的部落哨站联系起来。",["race:Undead"]="身为亡灵，你将皇家药剂师学会的研究带到卡利姆多，让他们在那里用陌生的野生动物试验北方的制剂。"},sec={{t="远渡重洋的毒物",b="狼心样本取自洛丹伦废墟中感染瘟疫的狼。药剂师伦弗利尔收集了这些心脏，随后它们被装好，准备运过无尽之海。被遗忘者的皇家药剂师学会希望深入了解毒液、疫病和生物试剂。一名信使将包裹送往贫瘠之地的十字路口，将幽暗城在饱受创伤的东部王国开展的实验与卡利姆多的边疆哨站联系起来。"},{t="赫布瑞姆的研究",b="药剂师赫布瑞姆在十字路口接收狼心样本。赫布瑞姆研究来自洛丹伦那些遭天灾军团蹂躏的土地的毒素，如何影响卡利姆多的本土野生动物。狼心中残存的毒性或许能揭示某些特性，帮助远离故土的被遗忘者改良毒药和药剂。"}},faq={{q="狼心样本是什么？",a="狼心样本是从洛丹伦染疫的狼身上采集并保存的组织。北方瘟疫留下的毒性，为皇家药剂师学会研究烈性毒药提供了材料。",al={"狼心样本","样本是什么","包裹里有什么"}},{q="是谁将这份样本送往贫瘠之地的？",a="药剂师金格从幽暗城寄出了这份样本，用的是药剂师伦弗利尔从银松森林寄给她的狼心。",al={"谁寄来的狼心","谁给的这个","狼心样本的来源"}},{q="药剂师赫布瑞姆为什么需要它？",a="赫布瑞姆研究来自洛丹伦的毒素如何影响卡利姆多的本土野兽。他计划检验样本的毒性，以改进被遗忘者的炼金制剂和毒药。",al={"赫布瑞姆为什么需要它","赫布瑞姆的研究","狼心的用途"}},{q="这份样本需要送到哪里？",a="将样本交给十字路口的药剂师赫布瑞姆，那里是贫瘠之地腹地的一处重要部落聚居地。",al={"狼心送到哪里","赫布瑞姆在哪里","交付地点"}}},fp="17,188,14.376.0,18.277.0,30.195.0,36.124.0,36.196.0,43.118.0"}
P.entries["item:wolf-heart-samples"] = {n="狼心样本",s="银松森林的狼心中含有一种毒素，活着的狼却能承受它。药剂师伦弗利尔将样本送往皇家药剂师学会，由那里的成员加以研究。",h="银松森林的狼心中含有一种毒素，活着的狼却能承受它。药剂师伦弗利尔将样本送往皇家药剂师学会，由那里的成员加以研究。",kw={"药剂师伦弗利尔","药剂师金格","皇家药剂师学会","银松森林","毒素","幽暗城","狼心样本"},ang={["race:Undead"]="身为Undead，你依靠皇家药剂师学会对致命试剂的探索，保卫被遗忘者，抵御活人和亡灵的敌人。"},sec={{t="毒素的悖论",b="药剂师伦弗利尔在银松森林检验尸体时，在某些狼的心脏中发现了一种致命化合物。毒素浸透了组织，其浓度本应足以杀死这些狼，它们却依然活着。伦弗利尔留出了组织样本，准备送往幽暗城。被遗忘者研究能够耐受毒素的生物，力求掌握生物战的手段，并配制新的试剂。"},{t="送往幽暗城",b="信使将样本送到洛丹伦废墟下方，交给位于炼金房的皇家药剂师学会总部的药剂师金格。金格和她的同僚十分看重新的毒素。他们解剖并检验这些染毒的组织，分离其中的剧毒化合物，并探究这些野兽如何在毒素侵蚀下存活，希望将所得用于炼金术研究。"}},faq={{q="这些狼心为何对被遗忘者如此重要？",a="这些狼心含有成因不明的高浓度毒素，本应足以杀死它们的宿主。皇家药剂师学会既想了解这种毒素，也想弄清这些狼如何在毒素侵蚀下存活。",al={"狼心为何重要","狼心有何特殊之处","药剂师为何需要狼心"}},{q="是谁要求收集这些样本？",a="药剂师伦弗利尔研究了银松森林的狼，随后采集了这些样本。他安排一名信使将样本送到幽暗城的协会总部，交给他的同僚药剂师金格。",al={"谁需要狼心","谁送出了样本","谁接收样本"}},{q="药剂师金格会如何处理这些样本？",a="药剂师金格会解剖并检验这些样本。皇家药剂师学会将新的毒素编目并制成武器，为希尔瓦娜斯女王研制瘟疫和药剂。",al={"金格如何处理狼心","金格的实验","药剂师金格的研究"}},{q="这些狼来自哪里？",a="这些狼来自银松森林，那里的荒野受到黑暗魔法、腐朽和诡异腐化的侵扰，当地的动物也因此发生了变化。",al={"狼来自哪里","银松森林的狼","狼的位置"}}},fp="18,153,15.383.0,24.371.0,54.194.0,27.205.0,40.167.0,31.132.0"}
P.entries["item:wood-pulp"] = {n="木浆",s="在巴尔莫丹，木浆帮助矮人配制爆破药包。驻扎在南贫瘠之地的矮人人员随身携带木浆，将其用作吸收基料，以稳定液体炸药。",h="在巴尔莫丹，木浆帮助矮人配制爆破药包。驻扎在南贫瘠之地的矮人人员随身携带木浆，将其用作吸收基料，以稳定液体炸药。",kw={"巴尔莫丹","巴尔丹","贫瘠之地","加恩·石塔","硝化甘油","加恩的复仇","硝酸钠","木浆"},ang={["profession:Engineering"]="工程师知道，木浆能吸收硝化甘油和硝酸盐氧化剂，将这种易爆液体稳定地容纳在耐用的炸药中。",["race:Tauren"]="身为石塔部族的牛头人，你认为用入侵者的弹药反攻巴尔莫丹，是为祖居遭到摧毁讨回公道。"},sec={{t="易爆的配方",b="在巴尔莫丹，铁炉堡矮人用土方机械和化学炸药挖掘牛头人祖传的猎场。液态硝化甘油本身并不稳定，因此矮人工程师将它与硝酸钠一同浸入多孔木浆，制成用于挖掘和作战的稳定药包。火枪手、士兵和军官都携带成捆的药包，用于坑道爆破和野战弹药。"},{t="反攻堡垒",b="勘探员卡兹戈姆倒下后，加恩·石塔取得了矮人的爆破图纸。这位流离失所的牛头人战士用这些技术反击侵占部族土地的入侵者。加恩从巴尔丹驻军处夺取木浆、硝化甘油和硝酸盐，制成药包，准备摧毁矮人在巴尔莫丹的飞行器。"}},faq={{q="木浆在巴尔莫丹有什么用途？",a="在巴尔莫丹，矮人工程师将木浆用作弹药的吸收基料。他们把不稳定的液态硝化甘油浸入木浆，让工兵能够更安全地携带和操作爆破药包。",al={"矮人为什么有木浆","木浆用途","木浆有什么用"}},{q="贫瘠之地的哪些人携带木浆？",a="驻扎在南贫瘠之地巴尔莫丹的矮人部队携带木浆。其中包括巴尔丹的士兵、火枪手、军官，以及统领他们的领主塞瑞克·黑炉。",al={"哪里获取木浆","谁掉落木浆","木浆位置"}},{q="加恩·石塔为什么需要这些木浆？",a="加恩·石塔用木浆将矮人的破坏手段反过来对付他们。他按照矮人的爆破图纸，将木浆与夺来的硝化甘油和硝酸钠混合，制成药包，准备摧毁矮人在巴尔莫丹的飞行器。",al={"谁需要木浆","加恩·石塔木浆","为什么收集木浆"}},{q="木浆本身会爆炸吗？",a="不会。未经处理的木浆是碎木纤维；只有与硝化甘油这样的易爆化学品，以及硝酸钠这样的氧化剂混合后，才会变得危险。",al={"木浆是否易爆","木浆会爆炸吗"}}},fp="9,147,17.373.0,23.350.1,41.154.0,37.166.0,45.264.0,33.162.0"}
P.entries["item:wooden-key"] = {n="木制钥匙",s="在灰谷北部，木制钥匙掌握在费伍德森林边界附近那些陷入疯狂的古树手中。它能打开一只隐蔽的箱子，里面存放着达图尔的变形魔棒的残件。",h="在灰谷北部，木制钥匙掌握在费伍德森林边界附近那些陷入疯狂的古树手中。它能打开一只隐蔽的箱子，里面存放着达图尔的变形魔棒的残件。",kw={"灰谷","疯狂的古树","达图尔的魔棒","费伍德森林","铁杆","莎尔蒂恩","枯萎的古树","木制钥匙"},ang={["class:Druid"]="持有这把钥匙的扭曲古树，显露出恶魔的枯萎之力已深入灰谷与费伍德森林之间的塞纳里奥林地。",["race:NightElf"]="对任何星辰之子而言，看到卡利姆多那些备受爱戴的古树陷入疯狂，在通往费伍德森林的道路旁紧握着失落的遗物，都是一件令人悲伤的事。"},sec={{t="疯癫之手中的钥匙",b="疯狂的古树和枯萎的古树携带着木制钥匙，徘徊在林中树居北面的林荫小径上。莎尔蒂恩曾熟知当地的树人，如今却说腐化已经扭曲了它们的本性。其中一棵古树带着一把钥匙，能打开存放着达图尔的变形魔棒部件的箱子。"},{t="解锁法杖",b="莎尔蒂恩派冒险者取回钥匙，打开通往费伍德森林的道路西侧一小片林间空地里隐蔽的旧箱子。铁杆就放在里面，它是重铸达图尔的变形魔棒所需的部件之一，这根法杖能用来对抗侵蚀神圣森林的腐化。"}},faq={{q="木制钥匙能打开什么？",a="木制钥匙能打开一只旧箱子，箱子位于向北通往费伍德森林的主路西侧的一小片林间空地上。里面放着铁杆，这是重铸达图尔的变形魔棒所需的部件。",al={"木制钥匙能打开什么","木制钥匙箱子","木制钥匙在哪里使用"}},{q="谁携带着木制钥匙？",a="疯狂的古树和枯萎的古树带着钥匙，穿行在林中树居北面、靠近费伍德森林边界的树林中。",al={"谁掉落木制钥匙","在哪里找到木制钥匙","木制钥匙掉落"}},{q="古树为什么会有这把钥匙？",a="莎尔蒂恩说，费伍德森林附近的一棵被腐化的树人带着这把钥匙。她没有解释钥匙是如何落到树人手中的。",al={"树人为什么有钥匙","古树钥匙背景故事"}},{q="谁派你去取回木制钥匙？",a="莎尔蒂恩是一位照料灰谷纯净月亮井的树妖，她指引冒险者找回钥匙，以推进重铸达图尔的变形魔棒的工作。",al={"木制钥匙任务给予者","谁需要木制钥匙"}}},fx={ebbbe3a2={q="木制钥匙是什么？",a="木制钥匙是一把简单的雕刻钥匙，由在灰谷北部、费伍德森林附近游荡的堕落树人携带。它是用来锁住一只隐秘宝箱的，箱中藏着已故暗夜精灵达图尔的一件遗物。",al={"木制钥匙信息","木制钥匙是什么","关于木制钥匙"}},a6fc69e1={q="莎尔蒂恩为什么想要木制钥匙？",a="莎尔蒂恩需要这把钥匙，这样你就能打开费伍德森林边界附近林间空地中的那只破旧宝箱。里面有一根铁杆，是重新组装达图尔之杖并净化这片土地所必需的关键部件。",al={"为什么需要木制钥匙","为什么要取回木制钥匙","为什么有人想要木制钥匙"}}},fp="10,156,18.256.0,17.259.1,32.160.0,27.122.0,34.137.0,41.143.0"}
P.entries["item:worn-parchment"] = {n="破旧的羊皮纸",s="在黑海岸北部的奥萨拉克斯之塔，破旧的羊皮纸残片提供了有关聚集在此的邪教徒的线索。",h="在黑海岸北部的奥萨拉克斯之塔，破旧的羊皮纸残片提供了有关聚集在此的邪教徒的线索。",kw={"奥萨拉克斯","巴苏尔·影击","暗滩教派","黑海岸","狂热者","破旧的羊皮纸"},ang={["class:Warlock"]="身为术士，你从这些记载中得知，暗滩教派有组织的术士集会正在暗夜精灵的土地上秘密活动，避开联盟与部落的耳目，操纵邪能与暗影。",["race:NightElf"]="身为暗夜精灵，你知道，在奥萨拉克斯这样的古老废墟附近，黑暗施法者与恶魔腐化正玷污着黑海岸神圣的荒野。"},sec={{t="阴谋的碎片",b="沿着黑海岸迷雾笼罩的海岸向北，黑暗施法者及其追随者占据了破败的奥萨拉克斯之塔。暗滩教派 狂热者在塔外巡逻，随身物品中带着破旧的羊皮纸残片。单独一张残片上只有零星的文字和奇怪的符号。将这些残片汇集起来，便揭示了一个此前无人知晓的组织，名为暗滩教派。"},{t="揭开邪教的面纱",b="斥候巴苏尔·影击从附近的高处监视着高塔，并利用收集来的羊皮纸，为净化者德尔格伦和奥伯丁的哨兵评估威胁。这些文字证实，那里的术士隶属于一个邪教组织，并非各自为生的流亡者。邪教有何图谋，仍然无人知晓。"}},faq={{q="谁带着这些破旧的羊皮纸？",a="暗滩教派 狂热者带着这些羊皮纸。他们是邪教的步卒，驻扎在黑海岸北部奥萨拉克斯之塔的外围。",al={"谁掉落破旧的羊皮纸","哪里获取破旧的羊皮纸","破旧的羊皮纸来源"}},{q="羊皮纸上写着什么？",a="每张羊皮纸上都记着晦涩的仪式笔记和命令片段。巴苏尔·影击收集并解读了这些残片，揭示了暗滩教派的名称与存在。",al={"破旧的羊皮纸写了什么","破旧的羊皮纸内容","羊皮纸含义"}},{q="巴苏尔·影击为什么要收集它们？",a="净化者德尔格伦指派巴苏尔监视奥萨拉克斯之塔。巴苏尔需要借助这些文字，查明术士为何聚集在废墟中，评估他们对黑海岸的威胁，并回报情况。",al={"谁需要破旧的羊皮纸","巴苏尔任务","为何收集羊皮纸"}},{q="暗滩教派是什么？",a="暗滩教派是一个隐秘的邪教徒与术士团体，以奥萨拉克斯的废墟为据点。即使是巴苏尔·影击这样经验丰富的斥候，在发现这些文字之前，也从未遇到过这个组织。",al={"暗滩教派邪教","暗滩教派是谁","暗滩教派"}}},fp="14,120,28.378.0,18.307.1,34.175.0,34.183.0,45.201.0,36.221.0"}
P.entries["item:worn-stone-token"] = {n="用旧的石雕",s="遍布奥特兰克山脉的用旧的石雕，其附魔已然消退，尽管达拉然制作它们是为了号令元素生物。从法师到劳工，达拉然的人员仍随身携带着这些石雕。",h="遍布奥特兰克山脉的用旧的石雕，其附魔已然消退，尽管达拉然制作它们是为了号令元素生物。从法师到劳工，达拉然的人员仍随身携带着这些石雕。",kw={"奥特兰克山脉","达拉然","元素生物","看守者贝瓦里尔","大法师沃迪恩·伍德格莱尔","石雕","塔伦米尔","用旧的石雕"},ang={["class:Mage"]="身为法师，你认出这些石雕是实用的法术焦点，肯瑞托用它们在野外维持召唤出的元素生物的稳定，并使其服从号令。",["faction:Horde"]="身为部落的一员，你可以帮助塔伦米尔的被遗忘者，研究驻扎在奥特兰克的敌对肯瑞托势力的奥术防御与施法手段。"},sec={{t="驾驭元素的石雕",b="达拉然的法师借助护符号令元素生物，迫使来自其他位面的生灵服从自己的意志。用旧的石雕就是这类器具耗尽力量后的形态。奇术师和召唤师随身带着它们，驻守在奥特兰克各处废墟和收容所周围的达拉然劳工与卫兵也不例外。这些石雕的存在表明，束缚元素生物的法术已深深融入达拉然的日常事务。"},{t="被遗忘者的好奇心",b="在塔伦米尔，被遗忘者监视着附近的巫师。大法师沃迪恩·伍德格莱尔想要收集用旧的石雕，研究达拉然奴役元素生物的方法。看守者贝瓦里尔指示手下先收集那些磨损且已失去魔力的石雕。这些石雕能让这位法师安全地研究基础附魔技法，再着手研究更强大、更不稳定的导魔器具。"}},faq={{q="这些石雕曾用来做什么？",a="达拉然的巫师用这些石雕束缚并号令从其他位面召唤来的元素生物，让它们充当劳工、卫兵和守卫者。",al={"用旧的石雕用途","石雕是什么","达拉然人员为何携带石雕"}},{q="为什么说这些石雕是用旧的？",a="随着时间流逝和频繁使用，石雕上原本生效的附魔已经消退。看守者贝瓦里尔认为，让大法师沃迪恩·伍德格莱尔从失去魔力的样本入手研究达拉然的束缚仪式更为安全。",al={"为何用旧","石雕有魔力吗","失去魔力的石雕"}},{q="谁会携带这些石雕？",a="奥特兰克山脉南部的达拉然人员都携带着这些石雕，从高阶召唤师和奇术师，到普通劳工、持盾卫兵，以及收容所里的典狱官贝拉摩尔。",al={"谁掉落用旧的石雕","哪里获取石雕","达拉然石雕掉落"}},{q="被遗忘者为什么想要这些石雕？",a="大法师沃迪恩·伍德格莱尔想要研究达拉然控制元素生物的奥术，揭开其召唤与奴役之术的奥秘。",al={"看守者贝瓦里尔为何需要石雕","大法师沃迪恩·伍德格莱尔的石雕"}}},fx={["4cdbd814"]={q="用旧的石雕是什么？",a="用旧的石雕是一件褪色的魔法神器，由达拉然法师制作。这些附魔石块是奥术器具，用来束缚、命令和控制从其他位面召唤来的元素仆从。随着时间流逝或经过频繁使用，其中蕴含的魔力已经减弱，变得毫无生气，但它们仍保留着达拉然元素技艺的结构奥秘。",al={"用旧的石雕是什么","用旧的石雕","石雕"}},["2e06b1f4"]={q="用旧的石雕从哪里来？由谁制作？",a="这些石雕由达拉然的法师和工匠制作。达拉然是一个以精通异次元魔法而闻名的法师政权。你会发现驻扎在奥特兰克山脉各处的达拉然部队携带着它们，其中包括召唤师、神官、盾卫、工人，以及附近收容所的典狱官贝拉摩尔。",al={"用旧的石雕由谁制作","石雕的来源","石雕从哪里来"}}},fp="16,187,27.327.0,18.301.0,32.161.0,37.180.0,25.188.0,32.120.0"}
P.entries["item:woven-wand"] = {n="狼人魔杖",s="狼人魔杖已在幽暗城回到比索·埃斯沙德手中。三位达拉然学徒曾将它制成兄弟情谊的信物，后来，背叛与洛丹伦的陷落使他们分道扬镳。",h="狼人魔杖已在幽暗城回到比索·埃斯沙德手中。三位达拉然学徒曾将它制成兄弟情谊的信物，后来，背叛与洛丹伦的陷落使他们分道扬镳。",kw={"奥拉瑞克","比索·埃斯沙德","达拉然","芬里斯城堡","冈瑟尔·阿坎努斯","魔法区","图勒·鸦爪","狼人魔杖"},ang={["class:Mage"]="身为法师，你能看出达拉然的学徒如何将各自的魔杖合为一体，汇聚他们共同的奥术力量。",["race:Undead"]="身为亡灵，你能从这根魔杖中看到那些被Scourge夺去的凡人生命。它将两位幸存的被遗忘者联系在一起，寄托着他们对那位已逝故友的追忆。"},sec={{t="隐秘的壁龛",b="图勒·鸦爪投身黑暗后，虽然开始憎恨魔杖所代表的一切，却无法将它摧毁，也无法将它交还给昔日的朋友。他将魔杖带到银松森林，藏在芬里斯城堡深处的一处壁龛中。多年后，图勒的巢穴被攻破，他的仆人奥拉瑞克指引部落人员找到了藏匿之处。他们找回了这件完好无损的遗物。图勒从未唤醒其中沉睡的魔法，魔杖随后被送到幽暗城的魔法区，交到了比索·埃斯沙德手中。"},{t="断裂的情谊",b="当达拉然还在培养北方的年轻法师时，学徒比索·埃斯沙德、冈瑟尔·阿坎努斯和图勒·鸦爪将各自的魔杖合为一件护符。狼人魔杖汇聚了三人的魔力，也见证了他们的友谊。天灾军团横扫洛丹伦，打破了这份羁绊。图勒宣誓效忠巫妖王，转而研习通灵术。亡灵瘟疫夺去了比索和冈瑟尔的生命，切断了他们与达拉然的联系。"}},faq={{q="是谁制作了狼人魔杖？",a="比索·埃斯沙德、冈瑟尔·阿坎努斯和图勒·鸦爪在达拉然当学徒时制作了狼人魔杖。他们将三根魔杖合为一体，作为友谊的见证。",al={"狼人魔杖是谁制作的","狼人魔杖的制作者","魔杖制作者"}},{q="魔杖为何被藏在芬里斯城堡？",a="图勒背叛昔日的朋友、为巫妖王效力后，便憎恨这根魔杖及其代表的一切。但他既无法将它摧毁，也无法舍弃它，于是将它藏在芬里斯城堡的一处壁龛中。",al={"图勒为何藏起魔杖","狼人魔杖在哪里找到的","为何是芬里斯城堡"}},{q="比索·埃斯沙德为何认为魔杖已经遗失？",a="瘟疫肆虐大地，学徒们的友谊也随之破裂，比索认为魔杖在那时便已遗失。图勒从未使用过它的魔法；否则，比索便能通过他们之间残存的魔法联系感知到它的力量。",al={"比索如何谈论魔杖","比索对魔杖的反应"}},{q="魔杖是如何被找回的？",a="部落人员攻破图勒·鸦爪的巢穴后，从芬里斯城堡找回了魔杖。他从前的仆人奥拉瑞克指引他们找到了那处隐秘的壁龛。",al={"谁找到了魔杖","如何获得狼人魔杖"}}},fp="10,177,17.492.1,15.432.1,27.162.1,39.197.0,48.215.0,27.151.1"}
P.entries["item:xavian-water-sample"] = {n="克萨维亚水样",s="萨维亚的古老水域蕴藏着奥格瑞玛部落法师所追寻的奥术力量。他们希望借此解开灰谷最古老的圣地中留存的潜在魔力之谜。",h="萨维亚的古老水域蕴藏着奥格瑞玛部落法师所追寻的奥术力量。他们希望借此解开灰谷最古老的圣地中留存的潜在魔力之谜。",kw={"灰谷","迪诺","奥格瑞玛","萨特","碎木","水样","萨维亚"},ang={["class:Mage"]="身为部落法师，取回水样既考验你驾驭天然奥术力量的本领，也考验你穿越敌人盘踞、受恶魔污染之地的能力。",["faction:Horde"]="身为部落的一员，随着部落巩固在灰谷碎木岗哨周边的势力，你可以看到采集萨维亚的古老奥术资源如何帮助奥格瑞玛的学者。"},sec={{t="古城之水",b="萨维亚曾是一座传说中的精灵古城，学识渊博之人至今仍知晓它的古老学问。即使已成废墟，据说这里的水仍蕴藏着强大的魔力。奥格瑞玛的奥术导师迪诺派遣初露头角的法师深入灰谷，从萨维亚最高的瀑布下方的水池中汲取新鲜的水。他们必须穿越险地，因为如今堕落的萨特正严密守卫着废墟，抵御前来干涉的施法者。"}},faq={{q="在哪里采集水样？",a="在萨维亚废墟最高的瀑布下方的水池中装满迪诺的瓶子。这处水池位于灰谷东北部，越过碎木岗哨和萨提纳尔之外的湖泊，继续向北便能找到。",al={"萨维亚的水在哪采集","萨维亚瀑布位置","如何获取克萨维亚水样"}},{q="迪诺为什么需要这些水？",a="迪诺是奥格瑞玛精神谷的奥术导师，她需要这些水来研究强大而奇异的魔法。她教导年轻的部落施法者，并探寻萨维亚未受扰动的水域中蕴藏的古老魔法精华。",al={"谁需要萨维亚的水","为什么采集萨维亚的水","迪诺的目的"}},{q="萨维亚的水域有哪些威胁？",a="萨特盘踞在古老的精灵废墟中，凶狠地抵御好奇的法师，捍卫自己的领地。周围的水道中还栖息着凶猛的野兽，包括河流鳄鱼。",al={"萨维亚有哪些敌人","谁住在萨维亚","萨维亚的危险"}},{q="水样送回奥格瑞玛后会发生什么？",a="水样一送回奥格瑞玛，迪诺便立即着手研究其中的奥术特性。她利用收集到的魔力推进研究，并协助训练和教导部落法师。",al={"交还萨维亚的水","水的用途"}}},fx={ff7d6737={q="克萨维亚水样是什么？",a="这是一只装满水的瓶子，水取自克萨维亚废墟最高瀑布的底部。据说这座古老暗夜精灵聚居地的水蕴含着强大的魔力，引起了部落学者的浓厚兴趣。",al={"克萨维亚水样是什么","克萨维亚水样","克萨维亚水瓶"}},["27a4db96"]={q="克萨维亚水样从哪里来？由谁制作？",a="这些水取自克萨维亚中心的天然瀑布。克萨维亚是一座古老的精灵城市，深藏于灰谷东部。没有凡人匠人制作过它；清澈的水流经浸透古老暗夜精灵魔法、并残留着如今占据此地的萨特腐化之力的废墟。",al={"克萨维亚的水从哪里来","克萨维亚水样由谁制作","克萨维亚水的来源"}}},fp="19,153,26.443.0,36.181.0,31.211.0,40.178.0,54.183.0"}
P.entries["item:young-crocolisk-skin"] = {n="小鳄鱼皮",s="在湿地，幼年鳄鱼的皮是米奈希尔港的贸易货物。当地制皮匠詹姆斯·哈洛兰将这些较柔软的皮鞣制后，运往远方的港口。",h="在湿地，幼年鳄鱼的皮是米奈希尔港的贸易货物。当地制皮匠詹姆斯·哈洛兰将这些较柔软的皮鞣制后，运往远方的港口。",kw={"鳄鱼","詹姆斯·哈洛兰","皮革","米奈希尔港","兽皮","鞣皮","湿地"},ang={["class:Hunter"]="身为猎人，你可以在湿地泥泞的边缘地带追猎鳄鱼，获取兽皮，供应米奈希尔港的皮革贸易。"},sec={{t="沼泽中的鞣皮与贸易",b="米奈希尔港位于卡兹莫丹西海岸，将沼泽出产的货物运往远方的港口。镇上的制皮匠詹姆斯·哈洛兰鞣制兽皮，这些兽皮是镇上利润最高的出口货物之一。成年鳄鱼的鳞甲厚实坚韧，幼年鳄鱼则能提供更柔软、更易加工的皮革。这些细嫩的皮需求旺盛，因此哈洛兰依靠当地猎人和过往旅人搜寻镇外泥泞的沼泽，让他的鞣皮架上始终有皮可鞣。"}},faq={{q="詹姆斯·哈洛兰为什么专门收购幼年鳄鱼的皮？",a="与成年鳄鱼厚实坚韧的鳞甲相比，幼年鳄鱼的皮更柔软，也更容易加工和鞣制。这种皮革在各条海上贸易航线上需求旺盛。",al={"为什么收购小鳄鱼皮","哈洛兰兽皮","为什么要柔软的皮"}},{q="在哪里能找到幼年鳄鱼？",a="湿地鳄鱼幼崽栖息在湿地西部、米奈希尔港外的水道、泥沼和湿地中。",al={"幼年鳄鱼位置","哪里有幼年鳄鱼","湿地鳄鱼"}},{q="还有谁在为港口猎捕这些鳄鱼？",a="当地猎人埃纳尔经常将鳄鱼皮送到詹姆斯·哈洛兰的制皮作坊，但仅靠一名追踪者并不总能满足需求。",al={"谁猎捕鳄鱼","埃纳尔猎人","米奈希尔港制皮匠猎人"}},{q="这些鞣制好的皮会运往哪里？",a="詹姆斯·哈洛兰的成品搭乘商船离开米奈希尔港，运往东部王国各地及更远地方的主要港口和市场。",al={"鳄鱼皮革贸易","米奈希尔港兽皮出口","兽皮运往哪里"}}},fx={["2363e64c"]={q="小鳄鱼皮是什么？",a="这是从湿地沼泽中游荡的幼年鳄鱼身上剥取的生皮，质地柔软。由于幼兽还没有长出成年鳄鱼那种厚实坚硬的鳞片，它们的皮更柔韧，深受当地制皮匠人青睐。",al={"小鳄鱼皮是什么","小鳄鱼皮物品","鳄鱼皮的含义"}},a9554702={q="小鳄鱼皮从哪里来？",a="这些皮直接取自栖居在米奈希尔港周边湿润沼泽中的小鳄鱼。它们不是加工制品，而是从猎杀的野兽身上剥下的天然兽皮，之后再经过鞣制加工成优质皮革。",al={"小鳄鱼皮的来源","去哪里获取小鳄鱼皮","小鳄鱼皮由谁制作"}}},fp="20,151,32.458.0,70.174.0,36.120.0,47.141.0,36.153.0"}
P.entries["item:yowler-s-paw"] = {n="犹勒的爪子",s="在湖畔镇，犹勒的爪子被交给弗纳·奥斯古，作为那名令人畏惧的豺狼人首领已死的证明。犹勒率领着威胁湖畔镇上方山丘的豺狼人群。",h="在湖畔镇，犹勒的爪子被交给弗纳·奥斯古，作为那名令人畏惧的豺狼人首领已死的证明。犹勒率领着威胁湖畔镇上方山丘的豺狼人群。",kw={"豺狼人族群首领","群山中的嚎叫","湖畔镇","赤脊山豺狼人","赤脊山","弗纳·奥斯古","犹勒","犹勒的爪子"},ang={["class:Hunter"]="作为猎人，追踪赤脊山的豺狼人首领并取下他的爪子，意味着你要面对一头危险的掠食者，检验自己的追踪与应付野兽的本领。",["faction:Alliance"]="暴风城的军力捉襟见肘，无力保护自己的东部边境，此时击败犹勒并带回他的爪子，有助于稳住赤脊山的局势。"},sec={{t="族群首领的战利品",b="犹勒率领着赤脊山的豺狼人，在止水湖周围的高地上肆虐，嚎叫声传到湖畔镇。他是最令人畏惧的存在，这名残忍的首领驱使着各个族群不断扩张。弗纳·奥斯古请求勇敢的冒险者带回犹勒的爪子，这是人类领地上领取悬赏时惯用的凭证。取下这只爪子，意味着一头异常狡猾的掠食者已经死去，也打击了他那些散漫追随者之间的指挥体系。"},{t="孤立无援的小镇",b="犹勒的爪子揭示了湖畔镇面临的危险。暴风城军队忙于应付盘踞在石堡要塞周围的黑石兽人威胁，地方官员和镇民只能雇用路过的佣兵来保卫小镇。由于没有王国正规驻军，弗纳·奥斯古这样的定居者只能依靠威胁已被消除的凭证，勉强维持当地道路的安全，供商旅通行。"}},faq={{q="谁在索要犹勒的爪子？",a="索要犹勒的爪子的是弗纳·奥斯古，他是湖畔镇一位颇有名望的工匠，也是镇上的居民。他想要证据，证明那个在山丘间肆虐的危险豺狼人首领已被彻底除掉。",al={"谁要犹勒的爪子","弗纳·奥斯古爪子任务","交付犹勒的爪子"}},{q="犹勒是谁？",a="犹勒率领着赤脊山的豺狼人群。他凭借蛮力与狡诈聚集起多个族群，成为附近镇民亟须应对的威胁。",al={"犹勒是谁","犹勒背景故事","赤脊山豺狼人首领"}},{q="湖畔镇为何依靠悬赏，而不是暴风城的士兵？",a="暴风城军队疲于应付在赤脊山东部石堡要塞设防的黑石兽人。由于无力抽调援军，弗纳·奥斯古这样的镇民只能依靠自由冒险者，猎杀犹勒之类的威胁。",al={"为何没有暴风城卫兵","暴风城军队在哪里","为何弗纳雇用佣兵"}},{q="犹勒被杀后会发生什么？",a="杀死犹勒，就摧毁了将这些凶悍豺狼人聚集在一起的领导力量。他的族群四散逃入荒野，让湖畔镇的居民获得了暂时的喘息之机。",al={"犹勒死后会怎样","犹勒死后的豺狼人","豺狼人的乱吠结局"}}},fx={["5e9f7255"]={q="犹勒的爪子是什么？",a="犹勒的爪子是赤脊山豺狼人首领被斩下的爪子，用来作为他毙命的实物证据。湖畔镇的弗纳·奥斯古请求冒险者猎杀这头凶残的首领并取回爪子，以确认这个暴徒终于被杀死。",al={"犹勒的爪子是什么","犹勒的爪子物品","犹勒的爪子"}},c7fb7fcc={q="犹勒的爪子从哪里来？",a="这不是加工制成的物品，而是犹勒本人的断肢。犹勒统领着在湖畔镇上方丘陵中游荡的凶悍豺狼人，比那些威胁赤脊山的普通杂种更加凶猛狡诈。",al={"去哪里获取犹勒的爪子","犹勒的爪子由谁制作","犹勒的爪子来源"}},["034bdc4c"]={q="弗纳·奥斯古为什么想要犹勒的爪子？",a="弗纳·奥斯古要求拿到爪子，以此作为这名凶恶豺狼人首领已死的确凿证据。暴风城的军队正全力应对黑石兽人，湖畔镇只能依靠路过的冒险者清除当地的猛兽；弗纳必须先看到证据，才会给你报酬。",al={"为什么有人想要犹勒的爪子","弗纳为什么想要犹勒的爪子","犹勒的爪子悬赏"}}},fp="12,157,25.399.0,22.397.0,26.181.0,14.148.0,66.225.0,35.170.0"}
P.entries["item:zalazane-s-head"] = {n="扎拉赞恩的头颅",s="加德林大师正等待扎拉赞恩已被击败的证据。暗矛希望摆脱那个将他们逐出回音群岛的巫医。",h="加德林大师正等待扎拉赞恩已被击败的证据。暗矛希望摆脱那个将他们逐出回音群岛的巫医。",kw={"暗矛","回音群岛","加德林","受妖术控制的巨魔","森金村","巫毒巨魔","扎拉赞恩","扎拉赞恩的头颅"},ang={["faction:Horde"]="作为部落的一员，你通过铲除扎拉赞恩，阻止他的黑暗魔法侵蚀萨尔新建立的领地，帮助保卫杜隆塔尔的南部海岸。",["race:Troll"]="作为暗矛巨魔，取下扎拉赞恩的头颅，是你亲手向叛徒复仇、伸张正义之举，正是他将你的族人逼入流亡，奴役了你的兄弟。"},sec={{t="叛徒伏诛的证据",b="加德林大师要求提供扎拉赞恩已死的证据。这个巫医背叛了暗矛，用奴役心智的妖术控制了他们的海岛家园。他的魔法迫使沃金的族人逃往杜隆塔尔的海岸。扎拉赞恩仍从回音群岛派出受妖术控制的奴仆，渡海抓捕更多受害者。森金村需要证据，证明他的统治已经结束。带回扎拉赞恩的头颅，就能证实他已被击败，让流离失所的部族得到些许安宁，也让他们有望在将来夺回被侵占的群岛。"}},faq={{q="谁要求带回扎拉赞恩的头颅？",a="加德林大师是杜隆塔尔南部海岸森金村的巫医，他要求带回扎拉赞恩的头颅，作为扎拉赞恩已被杀死的证据。",al={"谁要扎拉赞恩的头颅","扎拉赞恩任务给予者","加德林 扎拉赞恩"}},{q="为什么要除掉扎拉赞恩？",a="扎拉赞恩曾是暗矛中备受尊敬的巫师。对力量的渴望使他用控制心智的魔法奴役同胞，将部族逐出回音群岛，还袭击大陆，抓捕更多暗矛成员，束缚他们充当奴仆。",al={"为什么杀扎拉赞恩","扎拉赞恩做了什么","扎拉赞恩背景故事"}},{q="在哪里能找到扎拉赞恩？",a="扎拉赞恩住在杜隆塔尔东南海岸外、回音群岛中最大的岛屿上。他周围都是受妖术控制的巨魔，以及被巫毒束缚、为他效命的巨魔。",al={"扎拉赞恩在哪里","扎拉赞恩位置","回音群岛扎拉赞恩"}},{q="带回头颅就能夺回回音群岛吗？",a="杀死扎拉赞恩能消除他发动袭击的眼前威胁，让森金村得以喘息，但回音群岛依然危机四伏，到处都是残留的巫毒奴仆。暗矛仍主要驻留在大陆上。",al={"巨魔能夺回回音群岛吗","回音群岛收复了吗","回音群岛安全吗"}}},fp="15,139,26.493.0,29.146.0,26.232.0,24.141.0,46.227.0"}
P.entries["item:zamah-s-note"] = {n="扎玛的便笺",s="扎玛的便笺将一份紧急求助从雷霆崖带往塔伦米尔。扎玛请求药剂师林度恩用炼金术想个办法，在不直接造成流血的情况下将荆棘谷地精逐出石爪山。",h="扎玛的便笺将一份紧急求助从雷霆崖带往塔伦米尔。扎玛请求药剂师林度恩用炼金术想个办法，在不直接造成流血的情况下将荆棘谷地精逐出石爪山。",kw={"希尔斯布莱德丘陵","林度恩","石爪山脉","塔伦米尔","雷霆崖","幽暗城","荆棘谷地精","扎玛"},ang={["faction:Horde"]="这封便笺的递送展现了部落在卡利姆多和东部王国相隔遥远的主城之间，如何共用交通路线与资源。",["race:Undead"]="身为亡灵，你所属的族群拥有皇家药剂师学会，为面临严峻危机的盟友提供专门的化学知识与技术。"},sec={{t="跨越无尽之海的求助",b="荆棘谷地精已深入石爪山脉，砍伐树木，破坏神圣的土地。扎玛希望找到一种无需屠杀就能迫使地精离开的办法。她向被遗忘者皇家药剂师学会寻求帮助。她在便笺中向同僚药剂师林度恩讲述了石爪山面临的危险。林度恩身在远方，位于洛丹伦的希尔斯布莱德丘陵的塔伦米尔。"},{t="药剂师之间的联系",b="这封密封的便笺必须跨越大陆，才能送到林度恩手中。来自卡利姆多的旅人乘坐飞艇前往幽暗城，再向南穿过银松森林，进入希尔斯布莱德。扎玛的具体请求引起了林度恩的兴趣。消息漂洋过海传到了他这里，他开始准备用炼金术解决地精带来的问题。"}},faq={{q="扎玛的便笺是什么？",a="扎玛的便笺是一封从雷霆崖寄给塔伦米尔的药剂师林度恩的密封信。信中请求提供一种炼金配方，将荆棘谷地精逐出石爪山。",al={"这是什么物品","扎玛的便笺","给 林度恩 的信"}},{q="扎玛为什么需要塔伦米尔的帮助？",a="扎玛希望在不流血的情况下将地精逐出石爪山。她向药剂师林度恩求助，是因为被遗忘者炼金师能够调制专门的药剂，以隐秘的方式制造干扰。",al={"为何送往希尔斯布莱德","为何联系 林度恩","为何是塔伦米尔"}},{q="便笺需要送到哪里？",a="便笺必须送到药剂师林度恩手中，他位于洛丹伦的希尔斯布莱德丘陵的塔伦米尔。",al={"便笺交给谁","扎玛的便笺交付","便笺送往何处"}},{q="便笺中提到的荆棘谷地精是什么组织？",a="荆棘谷地精是一个由地精经营的采矿和伐木集团。它在卡利姆多各地大肆砍伐森林，掠夺自然资源，污染土地，连石爪山脉的神圣群峰也未能幸免。",al={"荆棘谷地精 石爪山","荆棘谷地精是什么组织","荆棘谷地精"}}},fp="12,172,27.380.0,22.271.0,21.172.0,42.188.0,41.93.0,49.208.0"}
P.entries["item:zargh-s-meats"] = {n="扎尔夫的肉品",s="在十字路口，扎尔夫为奥格瑞玛的格雷什卡备好了鲜肉。这包肉让年轻的部落旅人有了熟悉风骑士航线的契机。",h="在十字路口，扎尔夫为奥格瑞玛的格雷什卡备好了鲜肉。这包肉让年轻的部落旅人有了熟悉风骑士航线的契机。",kw={"十字路口","迪弗拉克","格雷什卡","肉品","奥格瑞玛","力量谷","风骑士","扎尔夫"},ang={["profession:Cooking"]="格雷什卡很看重这些鲜肉。它们体现了兽人对半生肉食的偏爱，只需略加烹制，肉则直接取自贫瘠之地的野兽。",["race:Orc"]="身为兽人，将扎尔夫准备的肉送给格雷什卡，会让你认识力量谷这片首都的核心地带，也让你了解乘坐双足飞龙在空中旅行的必要性。"},sec={{t="信使的货物",b="扎尔夫是贫瘠之地十字路口的一名兽人屠夫兼猎人，他为奥格瑞玛力量谷的旅店老板格雷什卡备好了新鲜的肉。草原上的酷热会让新鲜猎物迅速腐坏，因此这包肉交给了前往十字路口飞行点的信使。风骑士管理员迪弗拉克安排了一趟前往奥格瑞玛通天塔的双足飞龙航班，让旅人免去了穿越杜隆塔尔的漫长陆路跋涉。"},{t="打动芳心",b="扎尔夫送出的这包肉除了供应食材，还承载着一份私人的情意。格雷什卡收到肉后，便看出了扎尔夫善于用上好的野味赢得女士的欢心。她迫不及待地想把这些肉烹制成菜肴，招待旅店的食客和住客。对于初来乍到的兽人和巨魔旅人，这趟送货之旅让他们初次体验了卡利姆多部落定居点之间的长途飞行。"}},faq={{q="扎尔夫的肉品是谁准备的？",a="扎尔夫是贫瘠之地十字路口的一名兽人屠夫兼猎人，这些肉由他准备并打包。",al={"扎尔夫的肉品是谁做的","扎尔夫是谁","肉从哪里来"}},{q="这些肉要交给谁？",a="这些肉由奥格瑞玛力量谷的旅店老板格雷什卡接收。",al={"肉交给谁","格雷什卡是谁","扎尔夫的肉品送到哪里"}},{q="为什么必须通过风骑士运送这些肉？",a="在贫瘠之地和杜隆塔尔的酷热中，鲜肉很快就会腐坏。扎尔夫让信使前往十字路口飞行点找到迪弗拉克，那里的双足飞龙能在肉腐坏之前将包裹送到奥格瑞玛。",al={"为什么空运肉","迪弗拉克 风骑士 肉"}},{q="为什么只有某些种族能运送这个包裹？",a="兽人和巨魔旅人将扎尔夫的包裹送往奥格瑞玛。牛头人冒险者将兽皮送往雷霆崖，而被遗忘者信使则把补给带回瑟伯切尔。",al={"为什么牛头人不能接这个任务","亡灵 扎尔夫的肉品","谁能运送扎尔夫的肉品"}}},fp="13,149,17.389.0,18.360.0,27.95.0,34.76.0,41.188.0,48.175.0"}
P.entries["item:zhevra-hooves"] = {n="斑马蹄",s="在贫瘠之地，斑马 在开阔的草原上吃草。它们的蹄子能证明猎人有能力对付迅捷而强壮的猎物。",h="在贫瘠之地，斑马 在开阔的草原上吃草。它们的蹄子能证明猎人有能力对付迅捷而强壮的猎物。",kw={"贫瘠之地","十字路口","黑棘","蹄子","狩猎","奔跑者","瑟格拉","斑马"},ang={["class:Hunter"]="身为猎人，在草原上追踪 zhevra，能让你学会应对行动迅捷的群居动物，它们随时可能转身，用强有力的踢击反击。",["faction:Horde"]="作为初到贫瘠之地的部落新兵，你可以为瑟格拉·黑棘收集蹄子，证明自己有能力保卫十字路口。"},sec={{t="狩猎的战利品",b="斑马 遍布贫瘠之地，以草为食，但它们短而健壮的腿能发出猛烈的踢击。掌管十字路口的兽人萨满祭司瑟格拉·黑棘派遣有志成为部落斥候的新手，去收集 快步斑马 的蹄子。这场狩猎磨炼着初出茅庐的猎人的直觉与韧性。受惊的 快步斑马 一脚就能踢倒强壮的牛头人。完整的蹄子证明，猎人在挑战卡利姆多最致命的掠食者之前，已有能力对付行动迅捷、善于踢击的猎物。"}},faq={{q="谁需要斑马蹄？",a="贫瘠之地十字路口的兽人萨满祭司瑟格拉·黑棘要求猎人带回四只斑马蹄，证明他们已准备好挑战更难对付的猎物。",al={"谁需要蹄子","谁收斑马蹄","瑟格拉 蹄子"}},{q="斑马蹄从哪里获得？",a="斑马蹄来自 斑马，它们在十字路口南北两侧的开阔草原上吃草。",al={"哪里获取蹄子","疾奔斑马 位置","寻找 斑马"}},{q="为什么猎杀 斑马 很危险？",a="斑马 能用后腿发出强有力的踢击。疾奔中的 斑马 一脚就能将成年牛头人踢翻在地，不过它们的攻击性不如迅猛龙或徘徊者。",al={"斑马 强壮吗","斑马 踢击力量","斑马 的危险"}},{q="为什么瑟格拉让猎人追踪 斑马，而不是更凶猛的野兽？",a="瑟格拉认为，斑马 比平原陆行鸟更难对付。在新手面对真正致命的生物之前，它们能提供严格而安全的训练。",al={"为什么猎杀 斑马","瑟格拉 训练目的"}}},fp="13,132,20.416.0,24.152.0,33.106.0,33.167.0,69.135.0"}
P.entries["npc:abercrombie"] = {n="亚伯克隆比",s="在暮色森林西部，亚伯克隆比住在乌鸦岭墓地附近的小屋里，向旅人求助。他看起来是个虚弱而古怪的隐士，饱受林中恐怖之物的侵扰。他让心怀同情的旅人前往夜色镇，替他取来一些古怪的材料和补给。",h="在暮色森林西部，亚伯克隆比住在乌鸦岭墓地附近的小屋里，向旅人求助。他看起来是个虚弱而古怪的隐士，饱受林中恐怖之物的侵扰。他让心怀同情的旅人前往夜色镇，替他取来一些古怪的材料和补给。",kw={"亚伯克隆比","憎恶","夜色镇","暮色森林","伊莉莎","食尸鬼雕像","乌鸦岭","隐士"},ang={["class:Paladin"]="身为圣骑士，你能从亚伯克隆比身上看到，通灵术的邪恶腐化如何藏在一个寻常镇民乞求施舍的伪装之下。",["class:Warlock"]="身为术士，你能从亚伯克隆比献出自己心脏的举动中看到，凡人为了掌控黑暗魔法，会走到何等极端、自毁的地步。",["faction:Alliance"]="帮助这个可怜隐士的联盟英雄，在不知情中为袭击夜色镇提供了材料。"},sec={{t="乌鸦岭的隐士",b="亚伯克隆比住在乌鸦岭墓地附近一间破败的小屋里，暮色森林的衰败让他看起来像个潦倒的老人。他说自己只是想在林中的恐怖威胁下活下去，请旅人从夜色镇带来补给、草药和线。不了解这片土地往事的人，只会觉得他又是一个在这片地区沦为废墟时被遗弃的可怜人。"},{t="藏尸者的疯狂",b="亚伯克隆比曾住在乌鸦岭，是一位受人尊敬、心地善良的炼金师。他深爱的妻子伊莉莎去世后，悲痛摧毁了他的理智。他转而钻研禁忌的通灵术，挖出自己的心脏，放进伊莉莎冰冷的胸膛，想让她重获生命。仪式却让她变成了一个怪物，对活人的血肉有着永远无法满足的渴望，而这位疯狂的炼金师一直将她埋在墓地里。"},{t="骇人的骗局",b="在阴暗的民间传说中，亚伯克隆比被称为藏尸者，他对夜色镇及其领袖怀有深切而疯狂的怨恨。他让热心的旅人替他收集食尸鬼的肋骨、特制的线和腐蚀性药剂。这些补给正是组装缝合怪所需的最后几样材料，那是一个用血肉缝合而成的巨大憎恶，专为屠杀守夜人、蹂躏小镇而造。"}},faq={{q="亚伯克隆比是谁？",a="亚伯克隆比是暮色森林乌鸦岭墓地附近的一名隐士。他曾是一位技艺精湛的炼金师，在妻子去世后失去了理智，成了被称为藏尸者的通灵者。",al={"隐士是谁","亚伯克隆比的故事","亚伯克隆比是谁"}},{q="亚伯克隆比为什么想要夜色镇的补给？",a="亚伯克隆比声称，他需要日常用品和线，才能在荒野中生存。实际上，他是在欺骗旅人，让他们收集组装恐怖憎恶缝合怪所需的材料。",al={"亚伯克隆比为什么需要线","亚伯克隆比的补给","亚伯克隆比在制造什么"}},{q="伊莉莎是谁？",a="伊莉莎是亚伯克隆比的妻子。她死后，他把自己的心脏放进她的尸体，试图用黑暗魔法将她复活。她复生后成了一个饥饿难耐的亡灵怪物，他不得不一直将她埋在乌鸦岭墓地里。",al={"伊莉莎 亚伯克隆比","亚伯克隆比的妻子","藏尸者的新娘"}},{q="交出给镇长的信后会发生什么？",a="艾尔罗领主看不懂便笺，因为它是用一种古老的语言写成的，于是他请希拉·沃宁迪翻译。译文揭示，亚伯克隆比做了一件难以启齿的事。艾尔罗读完之后，恐怖的缝合怪便沿着道路，从乌鸦岭蹒跚走向夜色镇。",al={"给镇长的信","纸条上写了什么","亚伯克隆比的信"}},{q="亚伯克隆比为什么憎恨夜色镇？",a="亚伯克隆比从未解释过自己为何憎恨夜色镇。妻子死后，悲痛与黑暗魔法使他陷入疯狂，他一边讥讽地称镇长埃伯洛克为老朋友，一边让自己造出的怪物沿路前去摧毁小镇。",al={"亚伯克隆比为什么攻击夜色镇","藏尸者的动机","亚伯克隆比的复仇"}},{q="亚伯克隆比与天灾军团结盟了吗？",a="没有。亚伯克隆比是个独居的隐士，与巫妖王的军队毫无关联。",al={"亚伯克隆比属于天灾军团吗","亚伯克隆比为谁效力"}}},fx={["5abf44f4"]={q="亚伯克隆比为什么住在乌鸦岭墓地附近？",a="亚伯克隆比住在暮色森林西部、乌鸦岭墓地东北方一间孤零零的小屋里，远离夜色镇。他自称是个无害而古怪的隐士，还会请路过的旅人从镇上替他带些补给。",al={"亚伯克隆比为什么在这里","乌鸦岭的亚伯克隆比","亚伯克隆比所在位置的原因"}},a3c5130f={q="亚伯克隆比为什么令整个暮色森林的人都害怕？",a="亚伯克隆比表面上是个无害的隐士，实际上却是那个令人胆寒的“防腐师”。当地传说和孩子们的故事讲述了他如何堕入疯狂的通灵术，为了让死去的妻子复生为嗜肉的食尸鬼，竟亲手剖出自己的心脏。光是他的名字，就足以让人想起那些被禁忌之术缝合而成、并被释放到生者之间的恐怖怪物。",al={"亚伯克隆比为什么令人畏惧","防腐师亚伯克隆比的名声","暮色森林的防腐师"}}},fp="11,160,25.380.0,22.376.2,21.366.1,19.181.2,50.193.1,14.227.1,52.283.2,36.238.1,39.72.0"}
P.entries["npc:aelthalyste"] = {n="艾萨莱斯特",s="在幽暗城的军事区，艾萨莱斯特教导被遗忘者牧师掌握暗影之力。她指导他们的精神修行，并将巨魔侍僧送往奥格瑞玛，向他们自己的长者求教。",h="在幽暗城的军事区，艾萨莱斯特教导被遗忘者牧师掌握暗影之力。她指导他们的精神修行，并将巨魔侍僧送往奥格瑞玛，向他们自己的长者求教。",kw={"艾萨莱斯特","女妖","噬灵瘟疫","牧师","暗影","幽暗城","乌尔库","军事区"},ang={["class:Priest"]="身为被遗忘者牧师，你可以向艾萨莱斯特学习自己的教义、黑暗法术与暗影之道。",["faction:Horde"]="身为部落的一员，你可以看到艾萨莱斯特对乌尔库教诲的尊重，正帮助弥合部落内部的文化分歧。",["race:Troll"]="身为巨魔，艾萨莱斯特会指引你前往奥格瑞玛，向乌尔库学习暗矛的仪式。",["race:Undead"]="身为Undead，你与被遗忘者一样，背离了生前信奉的圣光，转而追求暗影的实用力量。"},sec={{t="遗忘之影之声",b="艾萨莱斯特教导被遗忘者牧师掌握暗影之力。艾泽拉斯各地的许多牧师都尊崇圣光，她的学生却已背离了它。她以没有实体的女妖之身复生，与希尔瓦娜斯·风行者的追随者承受着同样的灵体痛楚，也怀有同样坚定不移的意志。她在幽暗城军事区的房间里，召唤远方哨站中有志成为牧师的人前来，掌握更为黑暗的法术。她教导他们将苦难化为武器。"},{t="与部落的纽带",b="艾萨莱斯特尊重部落其他施法者的精神传统。她不让巨魔学徒接受自己的暗影教诲，而是指引他们渡海前往奥格瑞玛，向乌尔库学习暗矛的通灵之道。她的尊重让部落施法者得以沿袭各自的传统，也加强了卡利姆多与洛丹伦之间的联系。"}},faq={{q="艾萨莱斯特是谁？",a="艾萨莱斯特是一位女妖，也是被遗忘者牧师中的重要导师。在幽暗城的军事区，她教导被遗忘者修习暗影魔法。",al={"艾萨莱斯特背景故事","女妖牧师是谁","艾萨莱斯特非玩家角色"}},{q="在哪里可以找到艾萨莱斯特？",a="艾萨莱斯特位于首都废墟下方的幽暗城，就在军事区。附近还有其他被遗忘者导师。",al={"艾萨莱斯特位置","艾萨莱斯特在哪里","寻找艾萨莱斯特"}},{q="被遗忘者牧师信奉什么？",a="许多被遗忘者牧师认为，圣光在他们化为亡灵后抛弃了他们。他们背离了生前尊崇的圣光，转而投向暗影，拥抱黑暗、意志力与自身的修行。",al={"遗忘之影","被遗忘者牧师信仰","遗忘之影教派"}},{q="艾萨莱斯特为什么将巨魔牧师送往奥格瑞玛？",a="艾萨莱斯特将巨魔牧师送往奥格瑞玛，是因为巨魔与灵魂及暗影的联系不同于被遗忘者的教义。她尊重这种差异，将巨魔侍僧送到精神谷，向暗矛的牧师训练师乌尔库学习。",al={"乌尔库 艾萨莱斯特","为什么送走巨魔","艾萨莱斯特巨魔任务"}},{q="艾萨莱斯特传授什么？",a="艾萨莱斯特为被遗忘者角色提供牧师的基础训练，并指导高阶侍僧研习亡灵仪式。她传授的法术包括虚弱之触和黑暗献祭。",al={"艾萨莱斯特牧师训练","艾萨莱斯特传授什么法术","艾萨莱斯特技能"}},{q="艾萨莱斯特效忠于希尔瓦娜斯吗？",a="是的。艾萨莱斯特是幽暗城的一位女妖，为希尔瓦娜斯·风行者效力。她致力于通过掌握黑暗魔法来壮大被遗忘者。",al={"艾萨莱斯特阵营","她是否效忠幽暗城","女妖的忠诚"}}},fp="11,176,29.448.0,19.344.0,19.157.0,29.136.0,33.195.0,53.247.0,28.182.0,33.146.0"}
P.entries["npc:agathelos-the-raging"] = {n="暴怒的阿迦赛罗斯",s="在剃刀沼泽深处，暴怒的阿迦赛罗斯被圈禁在荆棘密布的隧道间。野猪人尊奉阿迦玛甘为神灵与始祖，因此这头野猪的庞大体型对他们意义重大，而怒火让这头披甲野猪更为可怕。他的力量与体型使他成为贫瘠之地南部地下最危险的野兽之一。",h="在剃刀沼泽深处，暴怒的阿迦赛罗斯被圈禁在荆棘密布的隧道间。野猪人尊奉阿迦玛甘为神灵与始祖，因此这头野猪的庞大体型对他们意义重大，而怒火让这头披甲野猪更为可怕。他的力量与体型使他成为贫瘠之地南部地下最危险的野兽之一。",kw={"阿迦玛甘","阿迦赛罗斯","野猪","亡首","野猪人","暴怒","剃刀沼泽"},ang={["class:Druid"]="身为德鲁伊，你十分敬重阿迦玛甘，他是在War of the Ancients中陨落的伟大远古半神之一。看到他的一头庞大同族被圈禁在沼泽中狂怒不已，令人心情沉重。",["class:Hunter"]="身为猎人，你可以欣赏Agathelos作为掠食者的庞大身躯，但他无尽的怒火意味着，这头野兽应当被斩杀，而非驯服。",["race:Tauren"]="身为与大地相通的牛头人，你熟知阿迦玛甘的传说。野猪人对他同族野兽的腐化，表明腐败正在贫瘠之地蔓延。"},sec={{t="巨型野猪的化身",b="阿迦玛甘是一头巨大的野猪，也是野猪人的神灵与始祖。对剃刀各部族而言，像阿迦赛罗斯这样庞大的野兽具有深厚的信仰意义。他的身高约为贫瘠之地雷霆蜥蜴的两倍。"},{t="锁链囚禁",b="野猪人不让阿迦赛罗斯在沼泽中自由游荡。他被圈禁在一条短小的死胡同隧道内，几名守卫在隧道前维持着一道力场。突破屏障的入侵者将直面一头狂怒的野兽，怒火使他的体型更加庞大，也更加可怕。"}},faq={{q="阿迦赛罗斯为何如此巨大？",a="阿迦赛罗斯是一头天生体型庞大的披甲野猪，体型约为普通雷霆蜥蜴的两倍。他被激怒时还会变得更大。野猪人尊奉巨型野猪阿迦玛甘为神灵与始祖，因此像阿迦赛罗斯这样庞大的野兽具有重大的信仰意义。",al={"阿迦赛罗斯为何巨大","阿迦赛罗斯体型","贫瘠之地巨型野猪"}},{q="野猪人为何把他关在屏障后？",a="野猪人将阿迦赛罗斯圈禁在一条短隧道中，隧道前的力场由几名守卫维持。这道屏障阻止这头庞大而狂怒的野猪在沼泽中自由游荡。",al={"阿迦赛罗斯屏障","阿迦赛罗斯为何被囚禁","阿迦赛罗斯力场"}},{q="他与阿迦玛甘有什么联系？",a="阿迦玛甘是巨型野猪远古半神，也是野猪人的始祖。他传下的血脉，使阿迦赛罗斯这样的巨型野猪对野猪人具有重大的信仰意义。",al={"阿迦赛罗斯 阿迦玛甘","阿迦赛罗斯是神吗","阿迦玛甘之子"}},{q="哪个部族创造了阿迦赛罗斯？",a="阿迦赛罗斯是一头野兽，并非造物。剃刀沼泽的亡首野猪人将他关在荆棘深处一条有守卫看守的隧道中。",al={"谁创造了阿迦赛罗斯","谁喂养阿迦赛罗斯","阿迦赛罗斯部族"}},{q="猎人能驯服阿迦赛罗斯吗？",a="不能。阿迦赛罗斯是一头身披厚甲的精英怪物，危险到猎人无法将其控制。",al={"驯服阿迦赛罗斯","能否驯服阿迦赛罗斯","猎人阿迦赛罗斯"}}},fx={a8df9e57={q="暴怒的阿迦赛罗斯是谁？",a="暴怒的阿迦赛罗斯是一头被关在剃刀沼泽深处的巨型披甲野猪。对于野猪人而言，他们的神祇和始祖阿迦玛甘是一头泰坦巨兽般的野猪，因此阿迦赛罗斯具有相当重要的灵性意义；它的体型约有普通雷霆蜥蜴的两倍，战斗时还会变得更加骇人。",al={"阿迦赛罗斯是谁","阿迦赛罗斯的身份","什么是暴怒的阿迦赛罗斯"}},["28c36899"]={q="暴怒的阿迦赛罗斯站在哪一边？",a="阿迦赛罗斯只是一头野兽，并非阴谋家。它被剃刀沼泽的野猪人看守着，关在一条设有守卫的隧道里，任何闯入它领地的人都会遭到攻击。",al={"阿迦赛罗斯的阵营","阿迦赛罗斯侍奉谁","阿迦赛罗斯站在哪一边"}},["38ca6f4f"]={q="暴怒的阿迦赛罗斯想要什么？",a="阿迦赛罗斯没有什么远大抱负，也没有自己的狡诈阴谋。它被纯粹的野性怒火吞噬，只想粉碎、顶撞并践踏任何闯入它领地的东西。",al={"阿迦赛罗斯想要什么","阿迦赛罗斯的动机","阿迦赛罗斯的目标"}},be737a36={q="暴怒的阿迦赛罗斯为什么令人畏惧？",a="阿迦赛罗斯因其骇人的庞大身躯和无法遏制的狂怒而令人畏惧。它身披甲胄，天生体型就极为庞大；发怒时，体型和凶性还会进一步暴涨，足以用蹄子踏碎整支突袭队伍。",al={"阿迦赛罗斯为什么令人畏惧","阿迦赛罗斯有多危险","阿迦赛罗斯的名声"}}},fp="20,289,25.220.0,14.252.0,25.269.0,53.165.0,36.158.0,29.134.0,27.102.0"}
P.entries["npc:aggem-thorncurse"] = {n="阿格姆",s="在剃刀沼泽，阿格姆拥有亡首预言者的头衔。受到威胁时，他会召唤野猪之灵前来助战。",h="在剃刀沼泽，阿格姆拥有亡首预言者的头衔。受到威胁时，他会召唤野猪之灵前来助战。",kw={"阿格姆","沼泽","野猪人","剃刀","棘咒"},ang={["class:Priest"]="身为牧师，你听到阿格姆的先知头衔，便能感受到野猪人的精神传统。",["class:Shaman"]="身为萨满，你看到阿格姆召唤野猪之灵前来助战，这是野猪人萨满之道的独特体现。",["faction:Horde"]="身为部落的一员，在野猪人威胁贫瘠之地之际，你通过击败阿格姆这样顽强的守卫者，帮助保卫杜隆塔尔和莫高雷。"},sec={{t="死亡之首预言者",b="阿格姆守卫着剃刀沼泽的一部分，那里是亡首氏族的居所。他的萨满之力让他能够召唤野猪之灵，体现了野猪人对阿迦玛甘的崇敬。"}},faq={{q="阿格姆是谁？",a="阿格姆是剃刀沼泽的一名野猪人萨满，也是亡首先知。",al={"阿格姆","阿格姆是谁","阿格姆 剃刀沼泽"}},{q="在哪里可以找到阿格姆？",a="阿格姆位于贫瘠之地南部的剃刀沼泽内。",al={"阿格姆位置","阿格姆在哪","哪里能找到阿格姆"}},{q="阿格姆会召唤什么灵体？",a="阿格姆会召唤野猪之灵，与他并肩作战。",al={"阿格姆灵体","阿格姆野猪之灵"}},{q="阿格姆如何战斗？",a="阿格姆使用萨满法术，并召唤野猪之灵与他并肩作战。",al={"阿格姆技能","阿格姆如何战斗"}},{q="阿格姆隶属于某个特定的野猪人氏族吗？",a="阿格姆属于亡首氏族。",al={"阿格姆氏族","阿格姆属于什么氏族","剃刀野猪人"}}},fx={["0a149290"]={q="阿格姆为什么在这里？",a="阿格姆身处剃刀沼泽的亡首野猪人之中，守卫着部族的领地。",al={"阿格姆·荆棘诅咒为什么在剃刀沼泽","阿格姆·荆棘诅咒所在位置的原因"}},["32004356"]={q="阿格姆与谁有关联？",a="他属于亡首部族，修习野猪人的萨满传统。",al={"阿格姆·荆棘诅咒的人脉","阿格姆·荆棘诅咒与谁结盟"}}},fp="16,125,24.193.0,24.70.0,36.61.0,33.46.0,31.77.0,62.40.0"}
P.entries["npc:ahanu"] = {n="安哈努",s="抵达雷霆崖的信使可以在海瓦的武器店找到安哈努。他为即将踏上莫高雷及更广阔平原的旅人和年轻勇士制作并出售皮甲，也帮助初来乍到的信使在各处台地间找到方向。",h="抵达雷霆崖的信使可以在海瓦的武器店找到安哈努。他为即将踏上莫高雷及更广阔平原的旅人和年轻勇士制作并出售皮甲，也帮助初来乍到的信使在各处台地间找到方向。",kw={"安哈努","海瓦的武器店","加翰·鹰翼","皮甲","莫高雷","雷霆崖"},ang={["race:Tauren"]="作为一名从十字路口乘坐双足飞龙抵达的年轻牛头人勇士，你可以在安哈努这里感受到熟悉的热情款待，并获得旅途必需的皮革。"},sec={{t="海瓦的武器店的商人",b="安哈努加工着好友加翰·鹰翼从十字路口送来的皮革。在雷霆崖下层台地的海瓦的武器店，他为穿行于卡利姆多草原的人们制作耐用的皮甲装备。从十字路口乘坐双足飞龙抵达的旅人，可以在城中的工匠商贩之间找到他。他接收他们送来的货物，并为信使指明当地飞行栖所的方向。"}},faq={{q="安哈努是谁？",a="安哈努是雷霆崖下层台地海瓦的武器店的一名牛头人商人。他出售皮甲，也帮助从十字路口抵达的信使。",al={"安哈努 非玩家角色","安哈努背景故事","安哈努是谁"}},{q="安哈努出售什么？",a="安哈努出售基础皮甲，包括外套、腰带、靴子和护腕。这些装备适合猎人、潜行者和年轻的冒险者。",al={"安哈努货物","安哈努商品","安哈努商人"}},{q="在雷霆崖哪里能找到他？",a="安哈努在雷霆崖下层台地的海瓦的武器店内工作，附近还有其他护甲匠、制皮匠和武器锻造师。",al={"安哈努位置","安哈努在哪","安哈努地图"}},{q="哪些任务与安哈努有关？",a="年轻的牛头人冒险者在“飞往雷霆崖”任务中乘坐双足飞龙，将货物送给安哈努。随后，他让他们回到城中的双足飞龙管理员塔尔那里。",al={"安哈努任务","飞往 雷霆崖 安哈努"}}},fp="5,230,25.392.0,13.146.0,21.135.0,38.126.0,26.150.0"}
P.entries["npc:aku-mai"] = {n="阿库麦尔",s="在黑暗深渊，阿库麦尔盘踞于佐拉姆海岸沿线沉没的 艾露恩 神殿废墟中。一位上古之神的腐化玷污了神殿中神圣的月亮井，阿库麦尔作为它的仆从从水中崛起。如今，暮光之锤将无辜者献祭给阿库麦尔，以换取力量。",h="在黑暗深渊，阿库麦尔盘踞于佐拉姆海岸沿线沉没的 艾露恩 神殿废墟中。一位上古之神的腐化玷污了神殿中神圣的月亮井，阿库麦尔作为它的仆从从水中崛起。如今，暮光之锤将无辜者献祭给阿库麦尔，以换取力量。",kw={"阿库麦尔","黑暗深渊","多头蛇","克尔里斯","上古之神","佐拉姆"},ang={["class:Druid"]="阿库麦尔违背自然的腐化扭曲了灰谷的沿海水域，必须将其净化，才能恢复自然的平衡。",["class:Priest"]="阿库麦尔与暮光之锤体现了上古之神的腐化，与圣光和 Elune 的教诲相悖。",["race:NightElf"]="阿库麦尔亵渎了一座神殿废墟最深处的圣所，那里曾供奉着 Elune，如今却从圣地变成了腐化的巢穴。"},sec={{t="佐拉姆海岸的祸患",b="黑暗深渊曾是一座宏伟的 艾露恩 神殿，直到一位上古之神的腐化玷污了其中神圣的月亮井。阿库麦尔是一头庞大的多头蛇，也是这位上古之神的仆从，从水中崛起。如今，阿库麦尔盘踞在暗夜精灵那座陷落神殿沉没的废墟中，成为佐拉姆海岸的一大祸患，它的恶意使水域染上剧毒。"},{t="原初黑暗的仆从",b="阿库麦尔的存在将暮光之锤引入了地下洞穴。在梦游者克尔里斯的带领下，这些教徒与纳迦结盟，占据了沉没的神殿，并将无辜者献祭给阿库麦尔，以换取力量。"}},faq={{q="阿库麦尔是什么？",a="阿库麦尔是一头古老的三头蛇，侍奉着一位上古之神。阿库麦尔从黑暗深渊遭到污染的水中崛起，盘踞在神殿被淹没的厅堂中。",al={"阿库麦尔是谁","阿库麦尔的故事","阿库麦尔是什么怪物"}},{q="阿库麦尔栖息在哪里？",a="阿库麦尔栖息在黑暗深渊被淹没的洞窟中，那里是灰谷西北部佐拉姆海岸沿线的一座 艾露恩 神殿废墟。",al={"阿库麦尔的位置","阿库麦尔在哪里","哪里能找到阿库麦尔"}},{q="暮光之锤为什么要喂养阿库麦尔？",a="暮光之锤将阿库麦尔尊奉为上古之神的仆从。在梦游者克尔里斯的带领下，这些教徒将无辜者献祭给阿库麦尔，以换取黑暗力量。",al={"教徒为何喂养阿库麦尔","克尔里斯 阿库麦尔","暮光之锤 阿库麦尔"}},{q="阿库麦尔拥有哪些力量？",a="阿库麦尔体型庞大，多个头颅不断噬咬，还蒙受着上古之神的黑暗眷顾。战斗中，阿库麦尔会陷入狂暴，用毒云吞没附近的敌人。",al={"阿库麦尔的力量","阿库麦尔是否具有魔力","虚空多头蛇"}},{q="阿库麦尔是一位上古之神吗？",a="不是。阿库麦尔是一头侍奉着一位上古之神的原初多头蛇。它邪恶的存在吸引了暮光之锤前来，围绕着它进行崇拜。",al={"阿库麦尔是 上古之神 吗","阿库麦尔是神吗"}},{q="冒险者为什么要深入黑暗深渊将它杀死？",a="若不加以遏制，阿库麦尔的凶残与教徒的狂热将使灾难性的邪恶席卷灰谷和卡利姆多。联盟与部落的当局都希望铲除暮光之锤，并杀死盘踞在神殿深处的恐怖生物。",al={"为何杀死阿库麦尔","黑暗深渊的邪恶 阿库麦尔","阿库麦尔的威胁"}}},fx={["055a774d"]={q="阿库麦尔站在哪一边？",a="阿库麦尔侍奉一位上古之神，不效忠于任何凡人种族。暮光之锤教派崇拜这头野兽，并以无辜者为祭品，换取黑暗力量。",al={"阿库麦尔的阵营","阿库麦尔侍奉谁","阿库麦尔的忠诚对象"}},["7b9e18bb"]={q="阿库麦尔想要什么？",a="阿库麦尔是一头凶残的野兽，并非阴谋家。它是上古之神的仆从，潜伏在黑暗深渊受污染的水域中；暮光之锤教徒以无辜者为祭品，希望恢复上古之神统治世界的时代。",al={"阿库麦尔的目标","阿库麦尔渴望什么","阿库麦尔的目的"}},["6cae52d5"]={q="阿库麦尔为什么在黑暗深渊？",a="当上古之神的腐化从地底渗出，污染了沉没神庙的月亮井时，阿库麦尔便从神庙水中崛起。如今，黑暗深渊的沉没大厅为暮光之锤教派提供了一处阴暗的水下藏身之所，让他们能在此庇护并秘密崇拜这头野兽。",al={"阿库麦尔为什么在黑暗深渊","阿库麦尔是如何来到这里的","阿库麦尔藏身处"}},ba41fb22={q="阿库麦尔与谁有关？",a="阿库麦尔是上古之神的仆从。在黑暗深渊，梦游者克尔里斯率领暮光之锤崇拜这头野兽，并向它献祭无辜者以换取力量。",al={"阿库麦尔相关人物","谁控制阿库麦尔","阿库麦尔与克尔里斯"}},["989c4b42"]={q="阿库麦尔为何如此令人畏惧？",a="阿库麦尔是一头体型庞大的三头九头蛇，也是上古之神的仆从，从佐拉姆海岸受污染的水域中崛起。关于它残暴行径的传说，以及暮光之锤对它的黑暗崇拜，使它成为灰谷海岸最令人胆寒的邪恶存在之一。",al={"阿库麦尔为何令人畏惧","阿库麦尔的名声","阿库麦尔危险吗"}}},fp="7,265,27.313.0,34.231.1,16.161.0,24.136.0,45.156.0,33.157.0,22.124.0,53.241.0"}
P.entries["npc:alamar-grimm"] = {n="阿拉玛尔·格里姆",s="在寒脊山谷的安威玛尔，阿拉玛尔·格里姆教导年轻的侏儒驾驭邪能魔法。自从诺莫瑞根陷落后，他对外人日渐怨愤，并打算教学生们召唤小鬼。",h="在寒脊山谷的安威玛尔，阿拉玛尔·格里姆教导年轻的侏儒驾驭邪能魔法。自从诺莫瑞根陷落后，他对外人日渐怨愤，并打算教学生们召唤小鬼。",kw={"阿拉玛尔","安威玛尔","寒脊","诺莫瑞根","格里姆","小鬼","训练师","术士"},ang={["class:Warlock"]="作为从寒脊山谷踏上旅途的侏儒术士，你向阿拉玛尔·格里姆学习最初的法术。你必须证明自己的价值，才能获得第一个小鬼。",["race:Gnome"]="身为侏儒，面对仍被石腭怪占据的诺莫瑞根，你或许也能体会那些流亡者的怨愤，他们觉得自己遭到了盟友的抛弃。"},sec={{t="心怀怨愤的流亡者",b="在安威玛尔，阿拉玛尔·格里姆仍对诺莫瑞根的陷落耿耿于怀。寒脊山谷的其他侏儒忙于重整旗鼓、钻研发明，他却不信任普通冒险者，甚至不信任收留族人的铁炉堡矮人。他抱怨盟友更关心与人类的外交关系，而非夺回陷落的城市。阿拉玛尔寻找着与自己想法相同的人，相信族人或许需要借助冷酷无情的力量。"},{t="黑暗魔法大师",b="阿拉玛尔·格里姆指引着修习邪能魔法的年轻侏儒。一份被污染的备忘录能换来他难得的热情接待，他也会开始传授基础法术。在传授束缚恶魔小鬼所需的危险知识之前，他要求每个新手证明自己在魔法和体力上的耐力。他派他们去取回当地霜鬃巨魔新手携带的奇异羽毛护符。"}},faq={{q="阿拉玛尔·格里姆是谁？",a="阿拉玛尔·格里姆在寒脊山谷的安威玛尔训练侏儒术士。他教新学生基础邪能魔法，以及如何召唤他们的第一个小鬼。",al={"阿拉玛尔·格里姆","阿拉玛尔 是谁","安威玛尔侏儒术士训练师"}},{q="阿拉玛尔·格里姆为何对矮人心怀怒意？",a="阿拉玛尔怨恨铁炉堡矮人，因为他认为，比起夺回诺莫瑞根，他们更看重与人类的同盟关系。尽管他们收留了流离失所的侏儒，他仍觉得他们没有把自己族人的家园放在首位。",al={"阿拉玛尔 为何憎恨矮人","阿拉玛尔 对矮人的看法","为何愤怒"}},{q="阿拉玛尔·格里姆要求新术士做什么？",a="阿拉玛尔·格里姆要求术士新手从当地的霜鬃巨魔新手身上收集羽毛护符。他用这些护符考验他们的耐力和魔法能力，然后才教他们召唤小鬼。",al={"阿拉玛尔·格里姆小鬼任务","羽毛护符任务","霜鬃 护符术士"}}},fx={["04c944ae"]={q="阿拉玛尔·格里姆站在哪一边？",a="阿拉玛尔·格里姆坚定地支持流亡的侏儒同胞，但对他们如今的盟友怀有强烈的怨愤。虽然矮人在丹莫罗收留了流离失所的侏儒，阿拉玛尔却对铁炉堡的领袖心怀不满，认为他们把与远方人类的关系看得比收复诺莫瑞根更重要。他在联盟中活动，纯粹是为了按自己的方式重建侏儒的力量。",al={"阿拉玛尔·格里姆的阵营","阿拉玛尔·格里姆效忠谁","阿拉玛尔·格里姆为谁而战"}},["949ab41a"]={q="阿拉玛尔·格里姆想要什么？",a="阿拉玛尔一心要收复诺莫瑞根，并通过黑暗魔法增强族人的力量。他认为寻常冒险者无能又失败，坐视城市沦陷，因此希望培养纪律严明、能力出众的术士，让他们拥有夺回家园所需的真正魔力与体魄。",al={"阿拉玛尔·格里姆的目标","阿拉玛尔想要什么","阿拉玛尔·格里姆的动机"}},["1846448c"]={q="阿拉玛尔·格里姆为什么在寒脊山谷？",a="诺莫瑞根惨遭沦陷后，阿拉玛尔与其他幸存者一同来到安全的寒脊山谷避难。他驻留在安威玛尔附近，教导和训练那些刚刚到来、受到邪能魔法吸引的侏儒，考验他们的潜力，并传授他们在前方艰险道路上生存所需的黑暗法术。",al={"阿拉玛尔·格里姆为什么在这里","阿拉玛尔为什么在安威玛尔","阿拉玛尔·格里姆在这里的目的"}}},fp="12,196,14.402.0,23.366.0,20.142.0,41.228.0,46.194.0"}
P.entries["npc:alanndarian-nightsong"] = {n="奥兰达利亚·夜歌",s="在奥伯丁，奥兰达利亚·夜歌照料着黑海岸患病的野生动物。她与旅者携手，缓解在这片地区蔓延的病症，尤其是鹿群中的病症。",h="在奥伯丁，奥兰达利亚·夜歌照料着黑海岸患病的野生动物。她与旅者携手，缓解在这片地区蔓延的病症，尤其是鹿群中的病症。",kw={"奥兰达利亚","奥伯丁","治疗","黑海岸","卡多雷","夜歌","陆行鸟","野生动物"},ang={["class:Druid"]="身为德鲁伊，你与奥兰达利亚一样，都在寻找水中的污染，并救治黑海岸各处中毒的生灵。",["class:Hunter"]="身为猎人，你可以通过辨识野兽留下的踪迹，帮助奥兰达利亚追踪野生陆行鸟和处境艰难的猎物。",["faction:Alliance"]="对于抵达奥伯丁的联盟旅者，奥兰达利亚能帮助他们了解卡利姆多北部荒野的脆弱现状。",["race:NightElf"]="身为暗夜精灵，奥兰达利亚对森林及其中遭受腐化的野生动物的照料，体现了 kaldorei 守护自然的理念。"},sec={{t="奥伯丁的照料者",b="奥兰达利亚·夜歌在沿海聚落奥伯丁守护着黑海岸的野生动物。土壤和水源中的污染让古老林地里的生灵染上疾病，变得异常凶暴。她设法减轻它们的痛苦，让它们恢复活力。"},{t="救治患病的生灵",b="奥兰达利亚正在寻找黑海岸动物患病的原因。她采集植物，研究当地的水源，然后配制药膏和治疗药水。旅者帮助她用这些药物救治患病的动物，希望阻止腐化侵蚀野生动物。"}},faq={{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌在奥伯丁照料黑海岸患病的野生动物。她寻求草药疗法，医治沿海岸蔓延的异常疾病。",al={"奥兰达利亚","奥兰达利亚·夜歌是谁","奥兰达利亚·夜歌背景故事"}},{q="在哪里能找到奥兰达利亚·夜歌？",a="奥兰达利亚·夜歌住在奥伯丁，这里是黑海岸雾气笼罩的海岸上最主要的暗夜精灵聚落。",al={"奥兰达利亚位置","奥兰达利亚在哪里","寻找奥兰达利亚·夜歌"}},{q="她会请冒险者执行哪些任务？",a="奥兰达利亚请旅者寻找疾病的源头，收集疗伤药材，并为病鹿等患病的动物施药。",al={"奥兰达利亚任务","奥伯丁患病动物任务","奥兰达利亚需要什么"}},{q="她与其他夜歌家族成员有亲属关系吗？",a="其他暗夜精灵也以夜歌为姓，但目前没有已知的联系能证实奥兰达利亚与他们有亲属关系。她每天都致力于照料黑海岸的荒野。",al={"夜歌家族","夜歌大师 关系","法拉拉·夜歌"}},{q="黑海岸的生物为什么会患病？",a="峭壁之泉是黑海岸的主要饮用水源，那里的水受到污染，导致整个地区的鹿群患病。奥兰达利亚怀疑，还有更严重的污染在起作用。",al={"黑海岸动物为什么患病","黑海岸被腐化的陆行鸟","黑海岸疫病"}},{q="她能训练陆行鸟宠物吗？",a="尽管传闻说奥兰达利亚对陆行鸟十分了解，她并不训练猎人驯服的宠物。她仍然专注于野生种群。",al={"陆行鸟训练师","奥伯丁陆行鸟训练","训练陆行鸟"}}},fp="21,181,24.266.0,29.294.0,29.155.0,41.99.0,47.144.0,35.149.0,40.172.0,31.149.0"}
P.entries["npc:althea-ebonlocke"] = {n="阿尔泰娅·埃伯洛克",s="夜色镇依靠阿尔泰娅·埃伯洛克和守夜人抵御暮色森林中的恐怖威胁。她是镇长埃伯洛克的亲属，在这片没有暴风城正规军驻守的偏远地区统领着城镇卫兵。",h="夜色镇依靠阿尔泰娅·埃伯洛克和守夜人抵御暮色森林中的恐怖威胁。她是镇长埃伯洛克的亲属，在这片没有暴风城正规军驻守的偏远地区统领着城镇卫兵。",kw={"阿尔泰娅","指挥官","夜色镇","暮色森林","埃伯洛克","民兵","摩拉迪姆","守夜人","缝合怪"},ang={["class:Paladin"]="身为圣骑士，你可以帮助阿尔泰娅让暮色森林阴郁道路上不得安息的灵魂归于平静，稍稍减轻压在她麾下民兵心头的恐惧。",["class:Warrior"]="身为战士，你或许会敬重阿尔泰娅严厉而务实的指挥方式。她看重纪律，也看重那些面对压倒性敌人仍愿坚守阵线的战士。",["faction:Alliance"]="在被遗忘的边疆，阿尔泰娅展现了联盟严峻而坚定的决心，在王国军队撤离的地方维系着王国的完整。"},sec={{t="卫队指挥官",b="阿尔泰娅·埃伯洛克负责指挥夜色镇的防务，她的亲属、镇长埃伯洛克则在镇公所处理政务。暴风城没有派遣王国军队来保护暮色森林，抵御这里的恐怖威胁，于是镇民组建了守夜人。在阿尔泰娅的严厉指挥下，志愿者们巡逻于雾气笼罩的道路，阻止亡灵骷髅、凶狼和蜘蛛侵入城镇边缘。"},{t="危在旦夕的城镇",b="阿尔泰娅深知，仅凭自己的民兵，能做的十分有限。新兵本就稀缺，卫队又不断折损人手，因此她招募过往的佣兵和旅人，削减夜色镇附近的威胁。她指挥人们清剿森林中那些寂静而凄凉的墓地里的食尸鬼和骷髅，同时留意着林地深处更为阴暗的传闻。"},{t="林中悲剧",b="阿尔泰娅统筹搜寻暮色森林中最严重的祸患，并组织力量将其消灭。她协助揭开斯塔文·密斯特曼托的黑暗命运，也探寻着堕落骑士摩根·拉迪莫尔为何化作摩拉迪姆，永无宁日地游荡。当亚伯克隆比让恐怖的憎恶缝合怪沿着大路前进时，阿尔泰娅麾下的守夜人便出动，沿路迎击。"}},faq={{q="阿尔泰娅·埃伯洛克是谁？",a="阿尔泰娅·埃伯洛克统领着守夜人，这支民兵驻守在暮色森林的夜色镇。她组织当地的防御，抵御潜伏在阴影中的亡灵和野兽。",al={"阿尔泰娅是谁","指挥官阿尔泰娅·埃伯洛克","守夜人指挥官是谁"}},{q="守夜人是什么？",a="守夜人是夜色镇居民自愿组建的民兵。由于几乎得不到暴风城的军事支援，镇民们在阿尔泰娅的指挥下巡逻道路，与林中的恐怖之物作战。",al={"守夜人是什么","守夜人是哪些人","夜色镇民兵"}},{q="阿尔泰娅与镇长埃伯洛克是什么关系？",a="阿尔泰娅是镇长埃伯洛克的亲属，后者在镇公所治理夜色镇。她则在外指挥民兵作战。",al={"艾尔罗 埃伯洛克亲属","阿尔泰娅是艾尔罗的女儿吗","阿尔泰娅家人"}},{q="暴风城为何不帮助阿尔泰娅保卫夜色镇？",a="暴风城的资源捉襟见肘，而随着瓦里安·乌瑞恩国王失踪，贵族对王国外围领地大多疏于照管。夜色镇几乎得不到兵力或物资援助，因此阿尔泰娅只能依靠当地志愿者和自由冒险者。",al={"为何没有暴风城卫兵","暴风城支援暮色森林","士兵在哪里"}},{q="指挥官阿尔泰娅提供哪些任务？",a="阿尔泰娅派遣冒险者在暮色森林各处猎杀狼、骷髅怪物和食尸鬼。她也协助调查斯塔文的传说，并对抗四处游荡的恐怖存在摩拉迪姆。",al={"阿尔泰娅任务","守夜人任务线"}},{q="缝合怪袭击夜色镇时，阿尔泰娅会做什么？",a="当亚伯克隆比用尸块缝合的憎恶缝合怪沿着道路，蹒跚着走向夜色镇时，阿尔泰娅麾下的守夜人卫兵便会出动迎击。如果没有冒险者的帮助，这头怪物就能直接杀穿他们的防线。",al={"阿尔泰娅 缝合怪","谁对抗缝合怪","夜色镇遭到袭击"}}},fx={["4a666294"]={q="指挥官阿尔泰娅·埃伯洛克站在哪一方？",a="指挥官阿尔泰娅坚定地支持夜色镇的居民和联盟。暴风城基本上已将暮色森林留给阴影摆布，但阿尔泰娅拒绝抛弃自己的家园。她领导着夜行者——一支走投无路的地方民兵，立誓抵挡那些威胁要将镇子从地图上抹去的野兽、躁动的亡灵与步步逼近的恐怖。",al={"阿尔泰娅·埃伯洛克的阵营","阿尔泰娅为谁而战","阿尔泰娅属于联盟吗"}},["37e849b9"]={q="指挥官阿尔泰娅·埃伯洛克想要什么？",a="她最重要的目标是让夜色镇存续下去。由于常规军队迟迟没有增援，阿尔泰娅不懈努力，阻止荒野不断逼近。她指挥夜行者对抗来袭的骷髅魔物、狂暴的狼和蜘蛛，并积极招募勇敢的冒险者，铲除潜伏在林中阴影里的致命威胁，以免它们屠戮饱受困扰的镇民。",al={"阿尔泰娅想要什么","阿尔泰娅·埃伯洛克的目标","阿尔泰娅在暮色森林的任务"}},["288c0322"]={q="指挥官阿尔泰娅·埃伯洛克为何在夜色镇？",a="暮色森林是她的家园，也是她的职责所在。她与镇长艾尔罗·埃伯洛克公爵有亲缘关系，驻守在镇中心广场，从聚落核心指挥夜行者。阿尔泰娅没有逃往安全的暴风城，而是留在前线协调巡逻，并召集任何有能力的旅人共同守卫边境。",al={"阿尔泰娅为何在夜色镇","指挥官阿尔泰娅为何在此","阿尔泰娅·埃伯洛克的位置"}}},fp="16,191,22.368.0,19.358.0,21.381.1,24.164.0,24.214.0,46.126.0,53.263.0,40.179.0,52.215.1"}
P.entries["npc:altsoba-ragetotem"] = {n="奥索巴·狂怒图腾",s="奥索巴·狂怒图腾是一名驻守在费伍德森林血毒岗哨的牛头人武器匠。在这座偏远的部落哨站，他为途经此地的勇士提供可靠的锤、法杖和斧，助他们对抗林中遭受枯萎侵蚀的恐怖生物。",h="奥索巴·狂怒图腾是一名驻守在费伍德森林血毒岗哨的牛头人武器匠。在这座偏远的部落哨站，他为途经此地的勇士提供可靠的锤、法杖和斧，助他们对抗林中遭受枯萎侵蚀的恐怖生物。",kw={"奥索巴","血毒岗哨","费伍德森林","狂怒图腾","牛头人","商人","武器匠"},ang={["faction:Horde"]="奥索巴为坚守在卡利姆多腐化最严重地区之一的部落人员提供必需的军需物资。",["race:Tauren"]="作为狂怒图腾部族的一员，奥索巴将牛头人世代相传的坚毅带到了这片深受恶魔腐化之苦的土地。"},sec={{t="血毒岗哨的铸甲师",b="血毒岗哨坐落于费伍德森林腹地，四周恶魔腐化蔓延，野生生物也受到污染，是一座危机四伏的哨站。在这里维持补给线是艰难却又不可或缺的任务，奥索巴·狂怒图腾则为部落斥候和旅人配备武器，尽自己的一份力。无论来者需要坚固的月牙斧，还是沉重的战槌，奥索巴都会确保深入腐化林地的战士不至于赤手空拳地投入战斗。"}},faq={{q="奥索巴·狂怒图腾是谁？",a="奥索巴·狂怒图腾是一名牛头人商人，驻守在费伍德森林的部落营地血毒岗哨。他为勇闯这片枯萎山谷的旅人和守卫提供基础的重型武器。",al={"奥索巴是谁","奥索巴·狂怒图腾","血毒岗哨的牛头人"}},{q="奥索巴出售什么？",a="他出售各种常见的近战武器，包括战斗法杖、晨星锤、战槌和斧，为深入费伍德森林的冒险者提供可靠的兵器。",al={"奥索巴的货物","奥索巴出售的物品","奥索巴出售什么武器"}},{q="在哪里可以找到奥索巴·狂怒图腾？",a="可以在血毒岗哨内找到歇息的他，这座哨站坐落在悬崖边，俯瞰着费伍德森林污浊的水域和受污染的林间空地。",al={"奥索巴的位置","奥索巴在哪里","血毒岗哨商人位置"}}},fp="17,150,26.379.0,25.177.0,23.164.0,35.123.0"}
P.entries["npc:alyissia"] = {n="奥莉希亚",s="在奥达希尔，奥莉希亚训练年轻的暗夜精灵，让他们凭借力量与纪律作战。她教导战士如何保卫这棵年轻的世界之树。",h="在奥达希尔，奥莉希亚训练年轻的暗夜精灵，让他们凭借力量与纪律作战。她教导战士如何保卫这棵年轻的世界之树。",kw={"奥达希尔","奥莉希亚","暗夜精灵","幽影谷","泰达希尔","战士训练师"},ang={["class:Warrior"]="身为暗夜精灵战士，奥莉希亚是你的第一位导师。在你深入泰达希尔的荒野之前，她会教你基础的战斗姿态和战斗纪律。",["race:NightElf"]="身为暗夜精灵，你可以向奥莉希亚学习kaldorei的前线战斗纪律，为保护奥达希尔的根须免遭腐化做好准备。"},sec={{t="幽影谷的武艺导师",b="奥莉希亚在奥达希尔内训练年轻的暗夜精灵，让他们学习用刀剑和盾牌作战，而非研习自然魔法或走上祭司之道。卡多雷的军队以哨兵和隐秘的弓箭手闻名，但卡利姆多各地的危险也需要能够坚守前线的战士。奥莉希亚传授最初的战斗技巧：如何引导战斗中的怒气、掌握战斗姿态，以及抵御侵入幽影谷的野兽和腐化的劣魔。"}},faq={{q="奥莉希亚是谁？",a="奥莉希亚在幽影谷中心的奥达希尔训练初出茅庐的暗夜精灵战士。当他们开始在泰达希尔接受训练时，她会为他们传授入门知识，并安排简单的武艺练习。",al={"奥莉希亚是谁","奥莉希亚非玩家角色","奥莉希亚做什么"}},{q="在哪里可以找到奥莉希亚？",a="奥莉希亚位于泰达希尔幽影谷中心的奥达希尔内，就在那巨大中空树干的底层。",al={"奥莉希亚位置","奥莉希亚在哪里","寻找奥莉希亚"}},{q="奥莉希亚提供哪些任务？",a="奥莉希亚接收初出茅庐的暗夜精灵战士带来的简易符记。这枚符记引领他们认识奥达希尔的战士训练师。",al={"奥莉希亚任务","奥莉希亚提供的任务"}}},fp="8,148,28.406.0,16.182.0,26.112.0,32.127.0"}
P.entries["npc:amber-kearnen"] = {n="Amber Kearnen",s="在西部荒野，Amber Kearnen 为 SI:7 监视迪菲亚潜行者。她藏身暗处，为马迪亚斯·肖尔追踪他们的不法活动。",h="在西部荒野，Amber Kearnen 为 SI:7 监视迪菲亚潜行者。她藏身暗处，为马迪亚斯·肖尔追踪他们的不法活动。",kw={"琥珀","迪菲亚","吉尔妮","克拉文·摩特维克","克拉文之塔","马迪亚斯·肖尔","潜行者","si:7","西部荒野"},ang={["class:Rogue"]="身为联盟潜行者，在筹划潜入克拉文之塔时，你可以依靠密探吉尔妮担任你的外勤联络人。",["faction:Alliance"]="身为联盟成员，你可以将吉尔妮视为暴风城驻西部荒野的秘密密探。她在不惊动民众的情况下对抗迪菲亚潜行者。"},sec={{t="监视高塔",b="远离暴风要塞的 Amber Kearnen 在西部荒野为 SI:7 执行侦察任务。她监视着一座被迪菲亚潜行者占据的废弃哨塔。马迪亚斯·肖尔指挥她的工作。受派前来遏制迪菲亚威胁、在这片纷争不断的乡野搜集情报的秘密特工，会从吉尔妮那里听取情况简报。"},{t="致命的任务",b="Amber Kearnen 监视着克拉文·摩特维克，这名迪菲亚成员藏身于哨兵岭东南方的高塔中。经过数周的监视，她向潜入的潜行者介绍了那些随着一批暮色森林货物抵达的诡异非人守卫。她派他们偷取高塔钥匙，进入塔内，查明暮色森林来的箱子里装着什么，其中包括克拉文的日记。她的耐心和详尽记录，为王国对抗迪菲亚的秘密行动提供了帮助。"}},faq={{q="安玻·吉尔妮 是谁？",a="安玻·吉尔妮 效力于 军情七处，这是暴风城的精锐情报部门。作为一名外勤密探兼斥候，她在西部荒野追踪迪菲亚的活动。",al={"安玻·吉尔妮","吉尔妮 是谁","密探吉尔妮"}},{q="在哪里可以找到 安玻·吉尔妮？",a="安玻·吉尔妮 在西部荒野的荒野中保持监视，位置就在被迪菲亚潜行者占据的废弃联盟哨塔附近。",al={"安玻·吉尔妮 位置","吉尔妮 在哪里","安玻·吉尔妮 在哪里"}},{q="她与马迪亚斯·肖尔有什么关系？",a="安玻·吉尔妮 直接听命于 SI:7 的首领马迪亚斯·肖尔。肖尔派其他密探前往西部荒野与她接头，了解她掌握的当地迪菲亚活动情报。",al={"吉尔妮 马迪亚斯·肖尔","吉尔妮 为谁效力"}},{q="她在克拉文之塔的行动中扮演什么角色？",a="安玻·吉尔妮 监视着克拉文·摩特维克占据的高塔。她向 SI:7 派来的联盟潜行者说明如何潜入塔内、避开迪菲亚守卫并取回克拉文的日记。",al={"克拉文之塔","安玻·吉尔妮 克拉文之塔","她在高塔做什么"}}},fx={b2881d9a={q="安玻·吉尔妮效忠哪一方？",a="安玻·吉尔妮是联盟的忠诚特工，供职于暴风城首屈一指的情报机构军情七处。她直接听命于军情七处的领导层，在外秘密行动，保护王国免受内部颠覆活动与敌对势力的侵害。",al={"安玻·吉尔妮的阵营","安玻·吉尔妮为谁效力","安玻·吉尔妮属于联盟吗"}},e7eadf92={q="安玻·吉尔妮想要什么？",a="她的首要目标是监视迪菲亚潜行者，并瓦解他们在西部荒野的行动。她专注于收集有关克拉文·摩特维克的情报，并协助奉命潜入其高塔、取回迪菲亚重要文件的外勤特工。",al={"安玻·吉尔妮的目标","安玻·吉尔妮想做什么","安玻·吉尔妮的任务"}},e7dcbc70={q="安玻·吉尔妮为什么驻守在西部荒野？",a="SI:7派她前往西部荒野，持续侦察一座被迪菲亚潜行者占据的废弃联盟哨塔。她隐蔽在附近，观察敌人的动向，并为奉命潜入据点的密探提供秘密支援。",al={"安玻·吉尔妮为什么在这里","安玻·吉尔妮为什么在西部荒野","密探吉尔妮为什么在西部荒野"}}},fp="13,139,17.291.0,19.446.1,21.138.0,33.126.0,39.171.0,42.170.0"}
P.entries["npc:anastasia-hartwell"] = {n="安娜斯塔西娅·哈特威尔",s="在幽暗城的魔法区，安娜斯塔西娅·哈特威尔向被遗忘者和部落法师传授奥术。她指导施法者研习法术，并指派他们在洛丹伦及更远的地方开展魔法研究和实地工作。",h="在幽暗城的魔法区，安娜斯塔西娅·哈特威尔向被遗忘者和部落法师传授奥术。她指导施法者研习法术，并指派他们在洛丹伦及更远的地方开展魔法研究和实地工作。",kw={"安娜斯塔西娅","巴尼尔","迪诺","被遗忘者","哈特威尔","洛丹伦","法师","魔法区","塔贝萨","训练师","幽暗城"},ang={["class:Mage"]="身为法师，你可以在幽暗城向安娜斯塔西娅·哈特威尔学习更高等级的法术。她指导途经此地的部落法师，并交给他们重要的任务。",["faction:Horde"]="身为部落的一员，你可以看到安娜斯塔西娅通过奥格瑞玛的迪诺等训练师，将洛丹伦的奥术传承与部落各地的魔法研究联系起来。",["race:Undead"]="身为亡灵，你能看到，尽管遭受了化为亡灵的悲剧，达拉然和洛丹伦的奥术传统仍在被遗忘者之中延续。"},sec={{t="废墟中的奥术之道",b="在幽暗城的魔法区，安娜斯塔西娅·哈特威尔教导被遗忘者和部落法师引导奥术能量。尽管洛丹伦已沦为废墟，安娜斯塔西娅这样的昔日人类施法者仍在亡灵之身中延续着学术传统。她要求研习魔法时严守规矩。草率施放的咒语可能吞噬未经训练的人。"},{t="实地研究与遗物",b="安娜斯塔西娅除了传授法术，还会派有潜力的学生前往实地。在提瑞斯法林地东部的巴尼尔农场，法师们采集金鱼草，以了解瘟疫蔓延的范围。在炼金房，他们前往奥格诺恩的炼金商店，捕捉引发奇异骚动的隐形生物，这些生物由纯粹的魔法构成。她布置的任务让他们直面魔法的危险，即使在自己的城市里也不例外。"},{t="研习魔法的盟友",b="安娜斯塔西娅的人脉延伸到了提瑞斯法之外。随着部落施法者的技艺日益精进，她会与远方的训练师协调，其中就包括奥格瑞玛的迪诺。她也会指引学有所成的学生，去拜访隐居的大师，例如尘泥沼泽湿地中的塔贝萨。她的指导让被遗忘者法师得以参与部落各地的魔法探索。"}},faq={{q="安娜斯塔西娅·哈特威尔是谁？",a="安娜斯塔西娅·哈特威尔在幽暗城的魔法区训练被遗忘者法师。她传授法术，并指派他们前往洛丹伦各地，取回奥术神器和施法材料。",al={"安娜斯塔西娅·哈特威尔","安娜斯塔西娅是谁","哈特威尔 幽暗城"}},{q="在哪里可以找到安娜斯塔西娅·哈特威尔？",a="你可以在幽暗城的魔法区找到安娜斯塔西娅·哈特威尔，她就在这座地下城市的穹顶之下，与其他奥术研习者和训练师待在一起。",al={"安娜斯塔西娅·哈特威尔位置","安娜斯塔西娅·哈特威尔在哪里","幽暗城法师训练师位置"}},{q="安娜斯塔西娅会对非法师访客说些什么？",a="安娜斯塔西娅告诫非法师访客，在旅途中要提防魔法。未经训练的人很容易被它灼伤。",al={"安娜斯塔西娅闲谈","安娜斯塔西娅对话","哈特威尔忠告"}},{q="安娜斯塔西娅·哈特威尔提供哪些任务？",a="安娜斯塔西娅会给法师布置训练任务，包括在巴尼尔农场采集金鱼草，以及调查炼金房一家炼金商店中的魔法骚动。她也会指引他们向远方的导师求教，例如奥格瑞玛的迪诺和尘泥沼泽的塔贝萨。",al={"安娜斯塔西娅任务","哈特威尔差事","幽暗城法师任务"}},{q="安娜斯塔西娅·哈特威尔与提瑞斯法的其他哈特威尔有亲属关系吗？",a="安娜斯塔西娅与安德鲁·哈特威尔和吉奥芬·哈特威尔同姓，但他们之间的亲属关系尚未得到证实。",al={"哈特威尔家族","安德鲁·哈特威尔","吉奥芬·哈特威尔"}},{q="安娜斯塔西娅为什么派法师前往巴尼尔农场？",a="安娜斯塔西娅让法师采集巴尼尔金鱼草，以判断瘟疫在提瑞斯法林地的蔓延程度，并将这些花送给药剂师。",al={"巴尼尔农场任务","为何前往巴尼尔农场","哈特威尔 巴尼尔"}}},fx={["686de903"]={q="安娜斯塔西娅·哈特威尔站在哪一方？",a="安娜斯塔西娅·哈特威尔坚定地支持被遗忘者和部落。她驻扎在幽暗城深处的魔法区，为希尔瓦娜斯·风行者女士培养新崛起的法师，让他们掌握奥术之力，守卫这个新生的王国。",al={"安娜斯塔西娅·哈特威尔的阵营","安娜斯塔西娅·哈特威尔效忠于谁","安娜斯塔西娅·哈特威尔的忠诚对象"}},bc0bb7e5={q="安娜斯塔西娅·哈特威尔为何在这里？",a="她住在幽暗城的魔法区，训练有志成为施法者的被遗忘者和部落成员研习奥术。她指导初出茅庐的施法者，警告新手魔法的危险，同时派遣有能力的法师执行洛丹伦及更远地区的重要任务。",al={"安娜斯塔西娅·哈特威尔为何在幽暗城","安娜斯塔西娅·哈特威尔在这里做什么","安娜斯塔西娅·哈特威尔的职责"}},["18e123e6"]={q="安娜斯塔西娅·哈特威尔想要什么？",a="她致力于确保奥术施法者纪律严明、能力出众且行事谨慎，并经常提醒外来者，未经训练便驾驭狂暴的力量只会引火烧身。她通过严苛的任务和魔法调查，努力增强被遗忘者的奥术力量。",al={"安娜斯塔西娅·哈特威尔的目标","安娜斯塔西娅·哈特威尔的动机是什么"}}},fp="18,218,27.341.0,25.418.0,19.358.0,26.169.0,36.155.0,37.102.0,42.291.0,61.116.0,54.141.0"}
P.entries["npc:andron-gant"] = {n="安德隆·甘特",s="在幽暗城的炼金房，安德隆·甘特偶尔为当地学者承接委托，安排寻回遗物。他是个深居简出的被遗忘者，经常醉酒，很少离开这座城市。",h="在幽暗城的炼金房，安德隆·甘特偶尔为当地学者承接委托，安排寻回遗物。他是个深居简出的被遗忘者，经常醉酒，很少离开这座城市。",kw={"安德隆·甘特","炼金房","阿斯托·哈德恩","亡灵哨兵","杰迪加","玛科里石板","瓦里玛萨斯"},ang={["class:Rogue"]="作为一名被遗忘者潜行者，你在亡灵哨兵中逐步晋升时会明白，在幽暗城的厅堂内，也需要像守卫边境那样时刻保持警惕。",["race:Undead"]="身为Undead，你或许早已熟悉炼金房里的甘特：一个醉醺醺的被遗忘者，很少离开城市，替城里的法师牵线安排一些古怪的差事。"},sec={{t="口齿不清的隐士",b="安德隆·甘特整日待在炼金房的有毒烟雾之中，很少踏出幽暗城的石墙。他看起来不过是个醉醺醺的学者。他有时会替当地法师雇用信使，前往遥远的海岸寻找鲜为人知的遗物，其中就包括玛科里石板。"},{t="被亡灵哨兵揭穿",b="幽暗城的情报网察觉了甘特的背叛行径。辛迪加派阿斯托·哈德恩前来收取一本记有泄露情报的账簿，但这名信使遭到了有志加入亡灵哨兵的特工拦截。一名特工冒充哈德恩，骗醉酒的甘特交出了那本足以定罪的账簿，丝毫没有引起怀疑。这本账簿为瓦里玛萨斯大人提供了甘特背叛被遗忘者的确凿证据。"}},faq={{q="在哪里可以找到安德隆·甘特？",a="安德隆·甘特位于幽暗城内炼金房区的下层。",al={"安德隆·甘特位置","安德隆·甘特在哪里","甘特幽暗城位置"}},{q="安德隆·甘特为什么对艾萨拉的石板感兴趣？",a="甘特替幽暗城的某些法师安排报酬，派遣拾荒者以及杰迪加这样的联络人，从艾萨拉的废墟中寻回古代遗物。",al={"安德隆·甘特艾萨拉","玛科里石板安德隆·甘特","甘特为什么想要石板"}},{q="亡灵哨兵为什么调查安德隆·甘特？",a="亡灵哨兵调查甘特与外部联络人的往来，并搜集有关他研究委托的情报。",al={"甘特调查","安德隆·甘特联络人","安德隆·甘特为谁效力"}},{q="谁在指挥对安德隆·甘特的调查？",a="亡灵哨兵奉瓦里玛萨斯大人之命调查甘特，搜集有关他的联络人和研究的情报。",al={"谁在调查安德隆·甘特","亡灵哨兵安德隆·甘特","瓦里玛萨斯安德隆·甘特"}}},fp="11,165,18.283.0,29.401.1,29.96.0,49.152.0,49.121.1,47.119.1"}
P.entries["npc:anduin-wrynn"] = {n="安度因·乌瑞恩国王",s="安度因·莱恩·乌瑞恩 是暴风城加冕的十岁国王，在父亲瓦里安·乌瑞恩国王失踪期间在位。由于他年纪尚小，王国的实际政务由伯瓦尔·弗塔根公爵和王廷掌管。",h="安度因·莱恩·乌瑞恩 是暴风城加冕的十岁国王，在父亲瓦里安·乌瑞恩国王失踪期间在位。由于他年纪尚小，王国的实际政务由伯瓦尔·弗塔根公爵和王廷掌管。",kw={"安度因","伯瓦尔","年幼的国王","普瑞斯托","王子","暴风城","王座厅","乌瑞恩"},ang={["faction:Alliance"]="在联盟的公民和士兵眼中，Anduin 国王是王国坚韧不屈的纯真象征，但许多人也担心，他年纪尚小，让王位容易受到王廷暗中阴谋的侵扰。",["race:Human"]="对暴风城的人民而言，这位年幼的国王代表着乌瑞恩王朝的延续，代替失踪的父亲瓦里安居于王位。"},sec={{t="王座上的男孩",b="安度因 王子出生于 第二次大战 之后的和平间隙，他的名字是为了纪念祖父莱恩国王和传奇骑士安杜因·洛萨爵士。父亲在前往塞拉摩参加外交峰会的途中神秘失踪后，这个孩子便仓促加冕，以维持整个王国的稳定。尽管这位十岁的君主有着超越年龄的聪慧与同理心，他对国家事务却几乎没有实际发言权，王国的统治权由伯瓦尔·弗塔根公爵和王室顾问女伯爵卡特拉娜·普瑞斯托分掌。"},{t="王廷中的棋子",b="在暴风要塞金碧辉煌的高墙内，年幼的 安度因 身边的政治局势日益紧张。伯瓦尔大领主负责军事防御，竭力维护王国的完整，而贵族女子卡特拉娜·普瑞斯托不断向王廷进言，暗中阻挠向偏远人类定居点派遣军队。安度因 察觉到王廷的处境岌岌可危，也深深思念着父亲，但眼下，他仍只是一个有名无实的君主，身边尽是勾心斗角的贵族和时刻警戒的守护者。"}},faq={{q="为什么由一个孩子统治暴风城？",a="瓦里安·乌瑞恩国王在乘船前往塞拉摩参加外交峰会的途中神秘失踪。为了避免王位继承危机并维持全国秩序，十岁的 安度因 王子正式加冕为王，伯瓦尔·弗塔根公爵则被任命为摄政王，代他治理王国。",al={"安度因 为什么是国王","瓦里安 在哪里","小国王是谁"}},{q="如今究竟是谁在治理王国？",a="伯瓦尔·弗塔根公爵担任暴风城摄政王，统领王国的军队，并在 安度因 成年之前掌握最高行政权力。然而，贵族女伯爵卡特拉娜·普瑞斯托担任高级顾问，对王廷和贵族议会有着举足轻重的影响。",al={"谁统治暴风城","谁掌权","暴风城摄政王"}},{q="安度因 的名字是为了纪念谁？",a="他的名字是为了纪念暴风城历史上的两位英雄：他的祖父、已故的莱恩乌瑞恩国王，以及在第一次兽人战争和 第二次战争 期间领导联盟的艾泽拉斯之雄狮安杜因·洛萨爵士。",al={"安度因 名字来源","安度因 名字纪念谁","为什么取名 安度因"}},{q="安度因 在城里的什么地方？",a="安度因 国王位于暴风要塞的王座厅，坐在王座上，伯瓦尔·弗塔根公爵和女伯爵卡特拉娜·普瑞斯托紧随左右。",al={"安度因 在哪里","安度因 位置","安度因·乌瑞恩国王位置"}}},fp="12,178,19.463.0,19.407.0,32.292.1,40.249.0,26.199.0,36.147.0"}
P.entries["npc:apothecary-helbrim"] = {n="药剂师赫布瑞姆",s="药剂师赫布瑞姆在十字路口为皇家药剂师学会研究贫瘠之地。他被派往卡利姆多，为被遗忘者收集陌生的材料。",h="药剂师赫布瑞姆在十字路口为皇家药剂师学会研究贫瘠之地。他被派往卡利姆多，为被遗忘者收集陌生的材料。",kw={"药剂师","贫瘠之地","十字路口","菌类孢子","赫布瑞姆","皇家药剂师学会","扎玛"},ang={["faction:Horde"]="赫布瑞姆在兽人守卫和牛头人旅者附近工作，但他对收集孢子和毒素的执着，连盟友也感到不安。",["race:Undead"]="身为被遗忘者的一员，你能看到自己的族人如何在卡利姆多为部落出力：赫布瑞姆将荒野中的产物变成了学会的研究材料。"},sec={{t="尘土中的药剂师",b="药剂师赫布瑞姆在十字路口的烈日下工作，远离皇家药剂师学会设在幽暗城潮湿地下城区的驻地。他被派遣跨越无尽之海，来到卡利姆多，在贫瘠之地寻找有用的植物、真菌和其他天然标本。他依靠旅人为他带来样本，其中包括当地的菌类孢子，并与雷霆崖的药剂师扎玛合作。通过赫布瑞姆，被遗忘者的炼金师将活动范围扩展到了洛丹伦残破的疆界之外。"}},faq={{q="药剂师赫布瑞姆是谁？",a="赫布瑞姆是一名被遗忘者炼金师，也是皇家药剂师学会的成员。他驻扎在十字路口，收集并研究来自贫瘠之地各处的天然材料。",al={"赫布瑞姆是谁","赫布瑞姆的故事","十字路口药剂师"}},{q="为什么一名被遗忘者药剂师会驻扎在贫瘠之地？",a="皇家药剂师学会为研究寻找新的化合物、毒素和材料。赫布瑞姆被派往卡利姆多中部，研究当地的标本，其中包括与洛丹伦遭瘟疫蹂躏的土地上所见不同的菌类孢子。",al={"他为何在十字路口","赫布瑞姆在这里做什么","被遗忘者为何在贫瘠之地"}},{q="他如何处理玩家带来的菌类孢子？",a="赫布瑞姆研究菌类孢子的毒性、药用价值和其他特性。他将样本打包，交由信使送往雷霆崖的药剂师扎玛处，供其进一步实验。",al={"菌类孢子赫布瑞姆","孢子有什么用途","菌类孢子任务"}},{q="赫布瑞姆与谁合作？",a="赫布瑞姆听命于幽暗城的皇家药剂师学会。在卡利姆多，他与雷霆崖预见之池的药剂师扎玛合作，有时也通过地精中间人开展交易，例如棘齿城的码头管理员迪兹维格。",al={"赫布瑞姆的盟友","赫布瑞姆听命于谁"}}},fp="18,158,22.462.0,26.158.0,54.231.0,57.190.0,27.244.0"}
P.entries["npc:apothecary-johaan"] = {n="药剂师乔汉",s="在布瑞尔，药剂师乔汉正为被遗忘者研制瘟疫。皇家药剂师学会和希尔瓦娜斯女士命他以当地动植物开展致命实验。",h="在布瑞尔，药剂师乔汉正为被遗忘者研制瘟疫。皇家药剂师学会和希尔瓦娜斯女士命他以当地动植物开展致命实验。",kw={"药剂师","布瑞尔","乔汉","瘟疫","皇家药剂师学会","银松森林","提瑞斯法"},ang={["faction:Horde"]="作为部落的一员，你或许能看到乔汉的致命药剂如何守住部落在东部王国的立足之地。兽人和牛头人可能会对炼金瘟疫有所抗拒。",["race:Undead"]="作为亡灵，你投身于乔汉的研究所服务的被遗忘者事业。他研制武器，是为了确保族人拥有永久的家园，免受Scourge与生者的威胁。"},sec={{t="学会的仆从",b="药剂师乔汉在提瑞斯法林地的布瑞尔公开为新成立的皇家药剂师学会效力。和遍布洛丹伦的同僚一样，他奉直属命令研制生物与炼金武器。被遗忘者希望这些武器能让他们在生者与天灾军团的威胁下，守住岌岌可危的未来。"},{t="调制新的瘟疫",b="药剂师乔汉主持学会的新的瘟疫早期实地试验。他使用取自提瑞斯法受腐化的野生生物和枯萎农田的材料，包括黑暗犬的血液、鱼人鳞片、蜘蛛毒液和偷来的农场南瓜。他在活体上测试这些混合物，测定效力，并将研究结果送往南方的银松森林。"}},faq={{q="药剂师乔汉是谁？",a="药剂师乔汉在布瑞尔为皇家药剂师学会研究炼金术。他指派年轻的被遗忘者勇士前往提瑞斯法林地各处，收集邪恶的试剂。",al={"药剂师乔汉","乔汉是谁","乔汉 布瑞尔"}},{q="在哪里能找到药剂师乔汉？",a="你可以在布瑞尔的户外找到药剂师乔汉，就在绞刑架和炼金器具附近。这座小镇位于提瑞斯法林地，在幽暗城正北方不远处。",al={"乔汉位置","乔汉在哪里","寻找乔汉"}},{q="乔汉正在研究什么？",a="乔汉正在研制新的瘟疫的早期毒株。他测试从提瑞斯法枯萎的田地和野兽身上提取的生物制剂与有毒提取物。",al={"乔汉的实验","乔汉做什么","乔汉 瘟疫"}},{q="他如何处理瘟疫样本？",a="调配样本并评估其致命性后，乔汉会派信使将样本送给银松森林的盟友药剂师。",al={"送往银松森林","瘟疫样本送往何处"}},{q="乔汉属于什么组织？",a="乔汉属于皇家药剂师学会，这个炼金公会在幽暗城为希尔瓦娜斯·风行者女士和被遗忘者效力。",al={"乔汉的阵营","乔汉为谁效力"}},{q="他为什么对当地农场感兴趣？",a="索利丹农场等人类农场和附近的南瓜田种植的南瓜，被乔汉用作实验性毒素的原料。",al={"悲伤之地 乔汉","为何派我去农场"}}},fp="17,174,24.302.0,22.330.1,25.163.0,35.153.0,26.146.0,40.118.0,40.140.0,40.136.0"}
P.entries["npc:apothecary-renferrel"] = {n="药剂师伦弗利尔",s="在瑟伯切尔，药剂师伦弗利尔致力于推进银松森林的被遗忘者炼金术研究。他研究当地受腐化的野生动物和亡灵威胁，旅人则协助收集性质不稳定的试剂，并调查天灾军团残余势力。",h="在瑟伯切尔，药剂师伦弗利尔致力于推进银松森林的被遗忘者炼金术研究。他研究当地受腐化的野生动物和亡灵威胁，旅人则协助收集性质不稳定的试剂，并调查天灾军团残余势力。",kw={"药剂师","死亡配方","伦弗利尔","腐皮","皇家药剂师学会","瑟伯切尔","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="作为部落的一员，你或许会觉得伦弗利尔的生物实验令人毛骨悚然。他针对Scourge收集的情报，有助于保护部落领土免遭北方势力的入侵。",["race:Undead"]="身为亡灵，你深知被遗忘者为求生存而不择手段的决心。伦弗利尔将洛丹伦本土的动植物化为武器，为重获自由的亡灵争取未来。"},sec={{t="瑟伯切尔的炼金师",b="在瑟伯切尔，伦弗利尔负责皇家药剂师学会在银松森林的实地研究。协会的大型实验室和高层领导都位于幽暗城，而他负责野外工作。他采集本地生物样本，精炼强效药剂，并研究洛丹伦西部边境的阴森生态。"},{t="调查腐皮与天灾军团",b="伦弗利尔研究银松森林的腐皮豺狼人和失控的亡灵。血液和组织样本帮助他研究瘟疫残留的影响，以及束缚当地怪物的通灵力量。他的调查使他与图勒·鸦爪发生冲突，后者是盘踞在芬里斯岛废墟附近的一名强大天灾军团通灵师。"}},faq={{q="药剂师伦弗利尔是谁？",a="药剂师伦弗利尔在瑟伯切尔为皇家药剂师学会效力，这里是被遗忘者在银松森林的主要前哨。他研究当地野兽、瘟疫变种和敌方势力，以调制药剂，并为希尔瓦娜斯女王巩固这片地区。",al={"伦弗利尔","伦弗利尔是谁","药剂师伦弗利尔背景故事"}},{q="伦弗利尔在银松森林研究什么？",a="伦弗利尔研制新的瘟疫和剧毒混合物，统称为“死亡配方”。他请旅人收集灰熊的心脏、腐皮豺狼人的脓液和其他生物材料，以便试验并改良致命药剂。",al={"伦弗利尔的研究","伦弗利尔的实验","死亡的配方"}},{q="他与腐皮豺狼人有什么关联？",a="伦弗利尔研究腐皮豺狼人受腐化的脓液。他在初步试验中检测到了术士魔法和通灵魔法，因此将一份样本送给幽暗城的比索·埃斯沙德，以供进一步研究。",al={"腐皮豺狼人的脓液","腐皮的起源","银松森林豺狼人"}},{q="伦弗利尔为何针对图勒·鸦爪？",a="伦弗利尔调查腐皮豺狼人背后的魔法，并寻求比索·埃斯沙德的帮助，以查明魔法的源头。调查的线索指向了芬里斯岛上的威胁。",al={"图勒·鸦爪任务","图勒·鸦爪是谁","芬里斯城堡通灵师"}},{q="离开银松森林后，伦弗利尔会派冒险者去哪里？",a="初步研究完成、当地威胁得到处理后，伦弗利尔会派经验丰富的旅人向东南前往希尔斯布莱德丘陵。这将瑟伯切尔的边境行动与被遗忘者在洛丹伦更大范围的行动联系起来。",al={"瑟伯切尔之后","希尔斯布莱德送货","前往希尔斯布莱德"}},{q="皇家药剂师学会是什么？",a="皇家药剂师学会是被遗忘者的科学与炼金术部门，在希尔瓦娜斯·风行者女士麾下成立。协会以幽暗城为基地，研究人员研制新的毒药，寻求抵抗自然腐朽的方法，并制造足以根除天灾军团的瘟疫。",al={"皇家药剂师学会","被遗忘者药剂师"}}},fp="20,211,25.338.0,34.315.1,28.268.0,43.241.0,46.187.0,42.180.1,55.223.0,37.260.0"}
P.entries["npc:apothecary-zinge"] = {n="药剂师金格",s="在洛丹伦废墟之下，药剂师金格为被遗忘者效力。她研究生物标本，并安排研究物资在部落各地的运输。",h="在洛丹伦废墟之下，药剂师金格为被遗忘者效力。她研究生物标本，并安排研究物资在部落各地的运输。",kw={"炼金房","药剂师金格","十字路口","赫布瑞姆","皇家药剂师学会","样本","幽暗城","金格"},ang={["faction:Horde"]="身为部落的一员，你依靠畅通的补给路线和往返于卡利姆多与东部王国之间、值得信赖的信使，维持前线的补给。",["race:Undead"]="身为被遗忘者的一员，你能看到金格这样的研究人员正站在族人争取科研自主的最前沿。他们不知疲倦地钻研各种方案，力求确保被遗忘者的生存与霸权。"},sec={{t="为协会效力",b="药剂师金格在幽暗城地下的炼金房工作。在大药剂师法拉尼尔的领导下，她寻找有助于实现被遗忘者目标的化学与生物化合物。她的工作让她与远在提瑞斯法林地之外的实地研究员和斥候保持联系，其中也包括卡利姆多偏远哨站的人员。"},{t="跨越大陆的实验",b="药剂师金格依靠信使和冒险者将实验材料运过大海。她经常写信给驻扎在贫瘠之地十字路口的药剂师赫布瑞姆。她将银松森林中带毒的狼心样本寄给他，让他研究洛丹伦的毒素如何影响卡利姆多的野兽。"}},faq={{q="在哪里可以找到药剂师金格？",a="药剂师金格在炼金房工作，这片炼金区域位于幽暗城的东南层。",al={"金格位置","药剂师金格在哪里","药剂师金格地点"}},{q="她属于哪个组织？",a="药剂师金格属于皇家药剂师学会，这是一群为希尔瓦娜斯·风行者女士效力的被遗忘者炼金师，负责研制药剂、瘟疫和解毒剂。",al={"金格阵营","金格为谁效力"}},{q="她为什么需要贫瘠之地的样本？",a="样本从银松森林送往十字路口的药剂师赫布瑞姆手中。金格让冒险者将带毒的狼心送给她的同僚，由他研究洛丹伦的毒素如何影响卡利姆多的野兽。",al={"为何需要贫瘠之地样本","赫布瑞姆样本","金格贫瘠之地送货"}}},fp="16,143,25.322.0,29.304.0,36.104.0,37.164.0,43.207.0"}
P.entries["npc:aramis-hammerhand"] = {n="Aramis Hammerhand",s="在丧钟镇的礼拜堂里，Aramis Hammerhand训练刚刚复生的被遗忘者，教导他们以圣光作战。圣光能够回应他们的呼唤，但驾驭圣光会灼烧他们腐朽的血肉，也需要极为严格的自律。",h="在丧钟镇的礼拜堂里，Aramis Hammerhand训练刚刚复生的被遗忘者，教导他们以圣光作战。圣光能够回应他们的呼唤，但驾驭圣光会灼烧他们腐朽的血肉，也需要极为严格的自律。",kw={"阿拉米斯","礼拜堂","丧钟镇","被遗忘者","锤手","圣光","圣骑士","提瑞斯法","训练师"},ang={["class:Paladin"]="身为被遗忘者圣骑士，Aramis是你的第一位导师。他指引你承受以亡灵之躯驾驭圣光的痛苦，并修习所需的精神自律。",["race:Undead"]="身为亡灵旅者，你能从Aramis身上看到，亡灵之身未必会断绝洛丹伦以圣光作战的传承，尽管这条道路伴随着巨大的苦难。"},sec={{t="丧钟镇的明灯",b="在丧钟镇的礼拜堂里，阿拉米斯·锤手指引着那些坚守生前信仰的被遗忘者。在天灾军团席卷北方之前，许多洛丹伦人曾响应白银之手的号召。阿拉米斯在洛丹伦陷落时幸存下来，随后又以亡灵之身复生。他保留了生前学到的武艺与精神教诲，如今指引着其他不愿放弃信仰的人。"},{t="圣光的灼痛",b="对被遗忘者而言，引导圣光需要坚韧的意志。圣光的力量会灼烧坏死的血肉，唤醒早已死去的神经，带来剧烈的痛楚。Aramis教导新晋圣骑士，信仰意味着忍受这样的折磨。他要求他们正视驾驭这种与亡灵本性相悖的力量时，身体与精神所要付出的代价。"}},faq={{q="阿拉米斯·锤手是谁？",a="阿拉米斯·锤手在提瑞斯法林地丧钟镇的礼拜堂里训练被遗忘者圣骑士。他指引那些刚刚复生、寻求以圣光作战的人。",al={"阿拉米斯背景故事","锤手是谁","丧钟镇圣骑士训练师"}},{q="被遗忘者真的能驾驭圣光吗？",a="可以。被遗忘者能够凭借意志与信念召唤圣光。圣光的辉煌力量在治疗或强化他们的同时，也会灼烧、涤荡他们腐烂的血肉。",al={"亡灵能当圣骑士吗","亡灵如何使用圣光","被遗忘者圣光"}},{q="在哪里能找到阿拉米斯·锤手？",a="阿拉米斯·锤手就在丧钟镇的礼拜堂内，丧钟镇是被遗忘者在提瑞斯法林地的起始聚居地。",al={"阿拉米斯在哪里","锤手位置","圣骑士训练师丧钟镇"}},{q="阿拉米斯·锤手提供哪些任务？",a="阿拉米斯为刚刚复生的圣骑士提供职业专属训练，包括艰难的道路、重寻圣光、黑暗中的圣光、接受现实和继续训练。",al={"阿拉米斯任务","丧钟镇圣骑士任务"}},{q="为什么会有圣骑士训练师为被遗忘者效力？",a="瘟疫爆发之前，洛丹伦是白银之手骑士团的摇篮。许多刚刚重获自由的被遗忘者仍记得自己的誓言，即使已是亡灵，也依然坚守神圣的使命。",al={"为什么有被遗忘者圣骑士","被遗忘者 白银之手"}},{q="使用圣光能像平常一样治疗亡灵吗？",a="圣光可以修复亡灵的躯体，赋予他们战斗的力量，但使用圣光会带来剧痛。它会唤醒他们的感官，迫使他们感受到自身躯体的腐烂。",al={"圣光会伤害亡灵吗","圣光治疗亡灵背景故事"}}},fp="17,196,22.379.0,27.317.0,25.133.0,47.173.0,35.108.0,41.185.0,50.190.0,55.163.0"}
P.entries["npc:arcanist-doan"] = {n="奥法师杜安",s="奥法师杜安是一位人类法师大师，居住在血色修道院图书馆区的图书馆中。他是血色十字军最致命的奥术专家之一，也负责守护十字军的重要档案。",h="奥法师杜安是一位人类法师大师，居住在血色修道院图书馆区的图书馆中。他是血色十字军最致命的奥术专家之一，也负责守护十字军的重要档案。",kw={"奥法师","图书馆","起爆","杜安","血色十字军钥匙","血色修道院"},ang={["class:Mage"]="杜安精通奥术防御，他的防护气泡生动地展现了魔法结界的力量。",["class:Paladin"]="圣骑士会发现，杜安是一位罕见的、受到血色十字军信任的奥法师，而这个组织通常将圣光置于其他一切力量之上。",["faction:Alliance"]="对联盟军队而言，杜安表明血色十字军的狂热影响深远，连一位奥术大师也被其暴戾的偏执所束缚。",["faction:Horde"]="被遗忘者及其部落盟友将杜安视为一名危险的血色十字军指挥官，他的图书馆藏有重要情报，以及攻入十字军内部圣所所需的钥匙。"},sec={{t="图书馆的守护者",b="血色十字军的狂热成员极为倚重武力与神圣信仰的热忱，杜安却始终坚信，要将天灾军团从洛丹伦清除，强大的奥术力量不可或缺。他驻守在修道院图书馆深处的图书馆，既受托保管典籍，也掌管着通行要务，守护着血色十字军钥匙，这把钥匙关系着北方诸王国各处十字军圣所的安全。"}},faq={{q="血色十字军中为什么会有法师？",a="虽然十字军以狂热的圣骑士和牧师为主，杜安却坚信，要将天灾军团从洛丹伦清除，精湛的奥术魔法是不可或缺的武器。",al={"杜安为什么是法师","十字军法师","杜安的魔法"}},{q="奥法师杜安与灰烬使者有什么联系？",a="目前没有已知的联系。杜安以血色修道院图书馆的看守者和血色十字军钥匙的守护者闻名，并非灰烬使者故事中的一员。",al={"杜安与灰烬使者","灰烬使者是杜安制造的吗","灰烬使者水晶"}},{q="杜安在图书馆中守护着什么？",a="杜安在图书馆中看守着修道院收藏的书籍与历史记录。他身后放着一个锁箱，里面装着血色十字军钥匙，这把重要的钥匙可以打开修道院军械库区和大教堂区紧锁的大门。",al={"杜安掉落什么","血色十字军钥匙","为什么要杀杜安"}},{q="杜安在战斗中使用什么魔法？",a="杜安以施放奥术气泡而闻名，这个法术能让他在引导威力巨大、席卷整个房间的爆炸法术时免受伤害。他还会用范围沉默干扰施法者，并将威胁他的敌人变成绵羊。",al={"杜安的法术","杜安的技能","奥法师杜安的气泡"}},{q="杜安在第三次战争期间曾在哪里作战？",a="他在第三次战争中的事迹没有留下记录。如今，他以血色修道院图书馆的看守者闻名，在那里守护着图书馆和血色十字军钥匙。",al={"杜安的战争经历","杜安曾在哪里"}},{q="杜安有什么私人秘密吗？",a="杜安是血色十字军的一名奥法师。经典旧世的资料中没有记载他的私人感情关系。",al={"杜安的背景故事"}}},fx={["979d2c44"]={q="奥法师杜安是谁？",a="奥法师杜安是一名人类法师，也是效力于血色十字军的最强大奥术施法者之一。他住在血色修道院图书馆深处的雅典娜神殿，负责保管组织的档案和血色十字军钥匙，并以毁灭性的奥术魔法守卫组织的圣所。",al={"杜安是谁","奥法师杜安背景","杜安与血色修道院"}},["46f867c9"]={q="奥法师杜安想要什么？",a="杜安坚信，奥术魔法是彻底净化洛丹伦、驱逐天灾军团的唯一办法。血色十字军的同袍几乎完全依靠圣光的狂热信仰，而杜安认为，只有原始的奥术力量和深入研究，才能彻底遏制并根除亡灵瘟疫。",al={"杜安的目标","杜安想要什么","奥法师杜安的动机"}},["88b26aa6"]={q="奥法师杜安为何令人畏惧？",a="杜安是洛丹伦最令人畏惧的强大法师之一。战斗中，他会用几乎坚不可摧的奥术屏障护住自己，同时施放毁灭性的爆炸法术，瞬间将大群闯入者烧成灰烬。",al={"杜安为何令人畏惧","杜安有多强","杜安的名声"}}},fp="13,157,23.277.0,37.150.0,53.110.0,36.177.0,35.201.0,42.122.0,38.101.0"}
P.entries["npc:archaeologist-flagongut"] = {n="考古学家弗拉冈特",s="在米奈希尔港，考古学家弗拉冈特与远在无尽之海彼岸的实地研究人员保持着联系。这位探险者协会的矮人学者正暂住深水旅店，准备前往维尔加挖掘场。",h="在米奈希尔港，考古学家弗拉冈特与远在无尽之海彼岸的实地研究人员保持着联系。这位探险者协会的矮人学者正暂住深水旅店，准备前往维尔加挖掘场。",kw={"考古学家","深水旅店","探险者协会","弗拉冈特","米奈希尔港","雷姆塔维尔","维尔加"},ang={["faction:Alliance"]="身为联盟的一员，你能看到弗拉冈特如何将黑海岸的暗夜精灵领地与东部卡兹莫丹的联盟据点联系起来。",["race:Dwarf"]="身为矮人，你能从弗拉冈特在海边旅店的工作中，看到探险者协会的足迹延伸得有多远；他在那里一点点拼凑出Titan的秘密。"},sec={{t="港口中的学者",b="考古学家弗拉冈特手捧酒杯，在米奈希尔港的深水旅店歇脚。与铁炉堡探险者协会的许多成员一样，他向西穿过卡兹莫丹，前来协助研究湿地维尔加挖掘场附近的发现。尽管远离图书馆的高大厅堂，他仍与实地研究人员保持联系，处理远征队从无尽之海彼岸带回的失落遗物和报告。"},{t="与考古现场的联系",b="矮人的好奇心并不局限于一片大陆。达纳苏斯的首席考古学家杜瑟·灰须将一块神秘的化石寄给弗拉冈特，那是健忘的勘察员雷姆塔维尔在黑海岸挖掘出土的。弗拉冈特惊叹不已：他曾带着一块相似的化石，参加探险者协会在铁炉堡召开的年度会议，并坚信其中蕴藏着某种能够释放出来的力量。"}},faq={{q="考古学家弗拉冈特是谁？",a="弗拉冈特是探险者协会的一名矮人研究员，暂住在米奈希尔港的深水旅店。他在那里审阅挖掘报告，并与各处挖掘场保持联系。",al={"弗拉冈特是谁","弗拉冈特非玩家角色","考古学家弗拉冈特背景故事"}},{q="弗拉冈特为什么会在深水旅店？",a="弗拉冈特在前往湿地维尔加挖掘场的途中，来到了米奈希尔港。在港口逗留期间，他以旅店为落脚点，收取邮件和运来的文物，并处理海外来信。",al={"弗拉冈特为什么在米奈希尔","弗拉冈特位置","弗拉冈特在这里做什么"}},{q="弗拉冈特与黑海岸有什么联系？",a="达纳苏斯的首席考古学家杜瑟·灰须将勘察员雷姆塔维尔在黑海岸发现的神秘的化石寄给弗拉冈特。它与弗拉冈特曾带到探险者协会会议上的一块化石十分相似，他相信这类化石蕴藏着能够释放出来的力量。",al={"弗拉冈特与黑海岸的联系","湿地为什么有黑海岸任务"}},{q="他属于什么组织？",a="弗拉冈特属于探险者协会，这是国王麦格尼·铜须的皇家学会。这个学会在艾泽拉斯各地探寻矮人一族的远古起源、遗物与历史。",al={"弗拉冈特阵营","弗拉冈特探险者协会"}}},fp="23,226,17.406.0,17.354.0,31.184.0,41.198.0,40.252.0,36.169.0"}
P.entries["npc:archaeologist-hollee"] = {n="考古学家霍莉",s="在奥伯丁，考古学家霍莉关注着矮人在黑海岸各地的研究进展。古老的遗迹吸引着铁炉堡的学者来到这片海岸，她在这里与寻找文物和奇特地质构造的勘察员保持联系。",h="在奥伯丁，考古学家霍莉关注着矮人在黑海岸各地的研究进展。古老的遗迹吸引着铁炉堡的学者来到这片海岸，她在这里与寻找文物和奇特地质构造的勘察员保持联系。",kw={"考古学家霍莉","奥伯丁","黑海岸","探险者协会","铁炉堡","勘察员雷姆塔维尔","健忘的勘察员","黑海岸的麻烦"},ang={["faction:Alliance"]="作为联盟的一员，你可以将霍莉的工作看作东部王国与暗夜精灵之间的合作，他们以奥伯丁为基地，研究卡利姆多的过去。",["race:Dwarf"]="作为一名矮人，在远隔重洋、雾气弥漫的黑海岸林地中见到同胞，会让你想起铁炉堡探寻远古历史的热忱。"},sec={{t="卡多雷领地上的矮人学者",b="考古学家霍莉在奥伯丁开展工作，与守卫并定居于黑海岸的暗夜精灵为邻。这位矮人学者是穿越荒野的测量员和探险队在当地的联络人。探险者协会派遣成员远渡重洋，寻找远古历史的痕迹，而黑海岸的遗迹为他们提供了研究之地。"},{t="关注雷姆塔维尔的行踪",b="勘察员雷姆塔维尔是霍莉关注的野外研究人员之一。他受命在荒凉的海岸沿线进行重要的勘测，却常常游荡到远离工作地点的地方，错过汇报时间。霍莉请途经奥伯丁的旅行者找到他，取回遗失的勘测资料，并保护研究成果免受当地野生动物和其他威胁的侵害。"}},faq={{q="考古学家霍莉是谁？",a="考古学家霍莉是奥伯丁的一名矮人，负责在卡利姆多西海岸开展并监督矮人考古活动中的野外研究。",al={"霍莉是谁","霍莉 黑海岸","奥伯丁的矮人"}},{q="在哪里能找到霍莉？",a="霍莉位于奥伯丁，这座港口小镇坐落在黑海岸的西部海岸。",al={"霍莉的位置","考古学家霍莉在哪里"}},{q="矮人为什么在黑海岸开展研究？",a="第三次大战之后，铁炉堡与暗夜精灵之间的关系日益紧密，矮人研究者也因此来到了卡利姆多。他们研究古代文物、地质构造，以及可能揭示矮人起源的尘封历史。",al={"矮人为什么在黑海岸","卡利姆多的铁炉堡势力"}},{q="她需要别人帮忙解决什么麻烦？",a="霍莉很担心勘察员雷姆塔维尔，这位心不在焉的测量员游荡到了黑海岸南部，却一直没有汇报他的发现。",al={"霍莉的任务","健忘的勘察员任务"}},{q="霍莉和勘察员雷姆塔维尔是什么关系？",a="霍莉和勘察员雷姆塔维尔是同事，一同参与黑海岸的挖掘与勘测工作。雷姆塔维尔在野外研究遗迹，霍莉则在奥伯丁统筹报告，并与旅行者交谈。",al={"雷姆塔维尔是谁","雷姆塔维尔和霍莉"}},{q="霍莉属于探险者协会吗？",a="霍莉代表着与铁炉堡结盟的矮人考古和勘探队伍。这类探险队通常由探险者协会组织，该组织以东部王国为基地开展活动。",al={"探险者协会 霍莉","霍莉的阵营"}}},fp="20,221,35.323.0,25.349.1,28.149.0,26.85.0,49.221.0,37.145.0,65.200.0,44.203.0"}
P.entries["npc:archbishop-benedictus"] = {n="大主教本尼迪塔斯",s="在暴风城，大主教本尼迪塔斯坐镇光明大教堂，领导圣光教会。他引领信徒与联盟度过动荡的岁月。",h="在暴风城，大主教本尼迪塔斯坐镇光明大教堂，领导圣光教会。他引领信徒与联盟度过动荡的岁月。",kw={"阿隆索斯·法奥","大主教","本尼迪塔斯","光明大教堂","圣光教会","帕雷斯之眼","牧师","暴风城"},ang={["class:Priest"]="身为牧师，你仰望大主教本尼迪塔斯。他作为Church of the Holy Light的领袖，掌管所有联盟牧师的训练、教义与誓言。",["faction:Alliance"]="身为联盟的一员，你可以向大主教本尼迪塔斯寻求道德指引，并为难民寻求精神慰藉。他也指引高阶圣骑士与指挥官。"},sec={{t="圣光的牧者",b="导师阿隆索斯·法奥大主教去世后，大主教本尼迪塔斯接掌了圣光教会。他亲眼见证第一次和第二次大战摧残各个王国，并协助督建了暴风城的光明大教堂。他在那里立誓恪守信仰的美德。\n\n第三次大战期间，洛丹伦沦陷，天灾军团崛起，人类诸国转而向本尼迪塔斯寻求精神指引。他在大教堂中为王室提供谏言，并训练刚入教的牧师。他还指挥神圣的征伐，讨伐威胁艾泽拉斯的亡灵与恶魔势力。"},{t="希望的灯塔",b="在整个联盟，人们都视大主教本尼迪塔斯为一位温和、睿智而仁慈的宗教领袖。他为民众带来希望，号召英雄对抗黑暗威胁，其中就包括盘踞在卡利姆多的寒冰之王亚门纳尔。他也帮助净化虔诚的冒险者带来的受诅咒遗物。"}},faq={{q="大主教本尼迪塔斯是谁？",a="大主教本尼迪塔斯领导圣光教会，是大联盟的最高宗教权威。他坐镇暴风城的光明大教堂，引领信徒，并为王国的领袖提供谏言。",al={"本尼迪塔斯","暴风城大主教","圣光教会领袖"}},{q="他与阿隆索斯·法奥是什么关系？",a="大主教本尼迪塔斯是阿隆索斯·法奥大主教最杰出的学生，后者创立了白银之手骑士团。法奥去世后，本尼迪塔斯接掌教会，继续导师的事业。",al={"法奥的学生","阿隆索斯·法奥 本尼迪塔斯"}},{q="本尼迪塔斯为冒险者安排哪些任务？",a="大主教本尼迪塔斯指引联盟英雄对抗天灾军团，包括远征剃刀高地，消灭巫妖寒冰之王亚门纳尔。他也运用神圣之力，净化被诅咒的帕雷斯之眼等遭到腐化的神器。",al={"本尼迪塔斯任务","大主教本尼迪塔斯做什么"}},{q="他对亡灵持什么态度？",a="大主教本尼迪塔斯主张让被遗忘者迅速而彻底地死去。他的追随者卡尔·菲利普指挥官说，大主教只要求将他们的心脏带回光明大教堂焚烧。",al={"本尼迪塔斯 被遗忘者","本尼迪塔斯对天灾军团的看法"}}},fx={["40ad9930"]={q="大主教本尼迪塔斯效忠哪一方？",a="大主教本尼迪塔斯坚定地支持大联盟和圣光教会。他居于暴风城的光明大教堂，是人类与矮人信徒共同的精神之父，指引王国的牧师，并在瓦里安·乌瑞恩国王缺席期间提供忠告。",al={"大主教本尼迪塔斯阵营","本尼迪塔斯是否属于联盟","本尼迪塔斯为谁效力"}},ae63c6cb={q="大主教本尼迪塔斯想要什么？",a="本尼迪塔斯希望在这个支离破碎的世界中守护并传播圣光的美德。在洛丹伦沦陷于天灾军团之手的惨剧之后，他努力庇护信徒，培养新一代牧师，并铲除一切威胁联盟的黑暗腐化。",al={"本尼迪塔斯目标","本尼迪塔斯想做什么","本尼迪塔斯动机"}},["5f68afea"]={q="大主教本尼迪塔斯为什么出名？",a="本尼迪塔斯以圣光教会最高领袖的身份闻名。他曾直接师从备受敬重的大主教阿隆索斯·法奥，并协助监督暴风城宏伟的光明大教堂的修建，在整个东部王国，他都因虔诚的智慧和坚定的领导而备受尊崇，被视为指路明灯。",al={"本尼迪塔斯为何闻名","本尼迪塔斯是否出名","本尼迪塔斯声望"}}},fp="21,169,26.598.0,16.287.0,29.226.0,41.211.0,51.240.0,33.221.0"}
P.entries["npc:archmage-ansirem-runeweaver"] = {n="大法师安斯雷姆·鲁因维沃尔",s="大法师安斯雷姆·鲁因维沃尔是一位资深的人类法师，也是达拉然统治机构 六人议会 的成员。他在第三次大战期间 天灾军团 对达拉然的毁灭中幸存下来，如今在城市重建之际，从紫罗兰城堡督管肯瑞托的事务。尽管致力于重建自己的城市，他也在暗中关注着远方的事务——其中就包括他那任性的女儿，她离家出走，跑到藏宝海湾当了海盗。",h="大法师安斯雷姆·鲁因维沃尔是一位资深的人类法师，也是达拉然统治机构 六人议会 的成员。他在第三次大战期间 天灾军团...",kw={"安斯雷姆","藏宝海湾","凯特琳","六人议会","达拉然","紫罗兰城堡","肯瑞托","里维加兹","鲁因维沃"},ang={["class:Mage"]="安斯雷姆是 Council of Six 中备受敬重的成员，在严谨的奥术研究领域始终享有权威。",["faction:Alliance"]="作为一位驻扎在洛丹伦的肯瑞托领袖，在人类施法者奋力从 Scourge 残部手中夺回故土之际，安斯雷姆依然支持联盟的利益。"},sec={{t="肯瑞托的支柱",b="安斯雷姆·鲁因维沃尔是一位数十年来协助保卫达拉然的资深法师，也是肯瑞托的法师统治议会 六人议会 的成员。当阿尔萨斯·米奈希尔率领 天灾军团 进军这座城市、阿克蒙德被召唤而来时，他从那场浩劫中幸存下来。达拉然陷落后，安斯雷姆一直协助重建这座奥术之城，其防护屏障早早便已解除，如今他在紫罗兰城堡处理事务。"},{t="远方的牵挂",b="尽管肩负学术职责，举止也带着法师的严肃，安斯雷姆的私人关系却远远延伸到了奥特兰克山脉之外。他任性的女儿凯特琳离家出走，跑到藏宝海湾当了海盗，还带走了他在荆棘谷研究期间发现的一把古老巨魔匕首。他也曾在那里与大财主里维加兹打过交道。他还从事涉及巨魔古物的奥术研究，并与遥远的国度保持着外交联系。"}},faq={{q="大法师安斯雷姆·鲁因维沃尔是谁？",a="他是一位造诣深厚的人类法师，也是肯瑞托的 六人议会 中执掌统治权的六位大法师之一。他数十年来一直保卫着达拉然，如今督管重建后的城市及其奥术防线周边的事务。",al={"安斯雷姆 是谁","安斯雷姆·鲁因维沃尔 的故事","大法师是谁"}},{q="他的女儿怎么了？",a="他任性的女儿凯特琳离家出走，跑到藏宝海湾当了海盗，在那里被称为利刃凯特琳。安斯雷姆曾将自己在荆棘谷研究期间发现的一把古老巨魔匕首送给她，而她离开时也带走了它。",al={"安斯雷姆 的女儿","利刃凯特琳","凯特琳·鲁因维沃"}},{q="他在达拉然担任什么职责？",a="安斯雷姆是肯瑞托驻紫罗兰城堡的重要人物，在城市从第三次大战的毁灭中重建期间，负责协调研究、魔法防御以及与盟友的联络。",al={"安斯雷姆 为什么在 奥特兰克","安斯雷姆 达拉然","他在这里做什么"}},{q="安斯雷姆参加过第三次大战吗？",a="是的。安斯雷姆数十年来一直协助保卫达拉然，也亲历了 天灾军团 对这座城市的围攻，当时阿尔萨斯正在守护克尔苏加德召唤阿克蒙德的仪式。他从城市的毁灭中幸存，如今正协助重建。",al={"安斯雷姆 天灾军团","安斯雷姆 与 阿尔萨斯 交战过吗"}}},fp="27,255,25.359.0,19.339.0,35.214.0,30.206.0,28.190.0,35.204.0"}
P.entries["npc:archmage-malin"] = {n="大法师马林",s="在暴风城的巫师圣殿外，大法师马林掌管着城中的奥术事务。他曾是大法师特雷莱恩的学生，如今负责协调各地人员，在东部王国寻找魔法神器和稀有材料。",h="在暴风城的巫师圣殿外，大法师马林掌管着城中的奥术事务。他曾是大法师特雷莱恩的学生，如今负责协调各地人员，在东部王国寻找魔法神器和稀有材料。",kw={"阿拉希高地","大法师马林","克里汀","法师区","马林","斯奎尔图","暴风城","特雷莱恩","巫师圣殿"},ang={["class:Mage"]="作为一名造访巫师圣殿的联盟法师，你看到马林将暴风城中的正规研习与荒野中寻回失落遗物的险途联系起来。",["faction:Alliance"]="作为一名联盟旅者，你知道马林在阿拉希的代理人正在寻找强大的神器，以抢在辛迪加、石拳食人魔或部落之前将它们收入囊中。"},sec={{t="巫师圣殿的守望者",b="在法师区，大法师马林于巫师圣殿下方监管暴风城的施法者。他曾跟随大法师特雷莱恩学习魔法，如今守护着昔日导师散落各地的遗产。学徒们在塔内研习。马林则关注着王国各地需要魔法监管的事务。"},{t="高地的耳目",b="在北方阿拉希高地危机四伏的废墟中，大法师马林信赖的同伴正在寻找特雷莱恩遗失的物品和精细的施法材料。斯奎尔图和学徒克里汀负责这项工作。马林在首都协调他们的行动，并依靠能干的联盟旅者，将指令、补给和情报送入敌境。"}},faq={{q="大法师马林是谁？",a="大法师马林是暴风城的一位高阶人类法师。他在法师区的巫师圣殿外监督研究、派遣学徒前往各地，并协助维持首都施法者之间的秩序。",al={"大法师马林背景故事","马林是谁","马林 暴风城"}},{q="马林与大法师特雷莱恩有什么关系？",a="大法师特雷莱恩曾教导并指引大法师马林。马林始终忠于昔日的导师，并协调阿拉希高地的搜寻行动，以找回特雷莱恩的物品和魔法遗物。",al={"马林 特雷莱恩","马林的导师是谁","大法师特雷莱恩 关系"}},{q="马林为何派冒险者前往阿拉希高地？",a="大法师马林派旅者前往阿拉希高地，与他在当地的代理人斯奎尔图和学徒克里汀取得联系。旅途危险，通信困难，因此旅者们要带去请求、魔法补给，以及找回特雷莱恩神器的指令。",al={"马林的请求任务","为何前往阿拉希","斯奎尔图任务"}},{q="在哪里可以找到大法师马林？",a="大法师马林位于暴风城法师区的塔楼底部，就在巫师圣殿入口外。从那里，他可以俯瞰通往上方圣所传送门大厅的坡道。",al={"马林在哪里","大法师马林位置","马林地图"}}},fx={deac5a59={q="大法师马林效忠哪一方？",a="大法师马林效忠联盟，在暴风城任职。他驻守在法师区的巫师圣殿外一处显眼的位置，与其他人类法师密切合作，并依靠可信赖的代理人和联盟冒险者，在东部王国各地执行他交付的任务。",al={"马林是否属于联盟","马林阵营","马林为谁效力"}},["77b45b55"]={q="大法师马林为什么会在暴风城？",a="大法师马林驻守在巫师圣殿外，协调魔法事务，并监督首都以外的行动。他留在暴风城，同时派遣斯奎尔图和学徒克里汀这样的代理人，前往阿拉希高地等遥远而危险的地区，并请途经城中的能干旅者前去协助他们。",al={"马林为何在暴风城","马林在巫师圣殿的目的","马林为何在密室外"}}},fp="14,230,31.318.0,21.374.0,22.228.0,47.193.0,56.265.0,34.198.0"}
P.entries["npc:archmage-xylem"] = {n="大法师克希雷姆",s="大法师克希雷姆是一位性情古怪、深居简出的人类法师，住在艾萨拉北部悬崖顶上一座偏僻的高塔中。他以喜怒无常的脾气和危险的实验闻名，远离尘世纷争，潜心研究深奥的奥术。想见到他，必须借助魔法传送，而他只接待那些能协助他进行古怪研究或帮他报私仇的冒险者。",h="大法师克希雷姆是一位性情古怪、深居简出的人类法师，住在艾萨拉北部悬崖顶上一座偏僻的高塔中。他以喜怒无常的脾气和危险的实验闻名，远离尘世纷争，潜心研究深奥的奥术。想见到他，必须借助魔法传送，而他只接待那些能协助他进行古怪研...",kw={"奥术","大法师","艾萨拉","摩弗拉斯","萨纳斯","高塔","克希雷姆"},ang={["class:Mage"]="对奥术研习者而言，克希雷姆既代表着至高的造诣，也展现了为了追求魔法力量而彻底与世隔绝所带来的不安后果。",["faction:Horde"]="虽然身为人类，这位深居简出的法师却出人意料地愿意与能协助他研究的部落勇士交涉。",["race:Human"]="与达拉然或暴风城那些循规蹈矩的法师不同，克希雷姆彻底抛下了人类社会，在艾萨拉荒野的高处过着不受打扰的生活。"},sec={{t="海岸上方的隐士",b="大法师克希雷姆住在艾萨拉北部嶙峋峭壁上的一座僻静尖塔中，俯瞰着满目疮痍的精灵海岸。这位法师没有修建道路或小径，而是让自己的居所与外界彻底隔绝，依靠仆人萨纳斯将获准来访的人用魔法传送到悬崖之上。卡利姆多各地留意他的人都认为，他极其古怪，与他打交道十分危险；就连其他学者也对他格外谨慎，指出他的行事作风几乎不同于任何其他人类法师。"},{t="对摩弗拉斯的仇恨",b="克希雷姆的隐居生活并非全然平静；他对绿龙军团怀有强烈的仇恨，尤其是一条名叫摩弗拉斯的幼龙。过去，这头巨兽将克希雷姆的一名不幸学徒整个吞下，连同那名学生携带的一块蕴含强大奥术力量的碎片一起吞进了肚子。这位一心复仇的大法师没有哀悼学徒，而是始终执着于追杀摩弗拉斯，从龙腹中取回那件珍贵的神器。"}},faq={{q="如何前往大法师克希雷姆的高塔？",a="大法师克希雷姆的高塔坐落在艾萨拉北部一处无法攀登的悬崖顶上，没有可供步行上去的道路。要见到他，你必须找到他的仆人萨纳斯，他站在悬崖脚下附近，能用魔法将旅人传送到高塔所在的地方。",al={"前往克希雷姆","前往克希雷姆的高塔","传送到克希雷姆","克希雷姆的位置"}},{q="大法师克希雷姆是谁？",a="他是一位性情古怪的人类大法师，住在艾萨拉北部悬崖顶上一座与世隔绝的高塔中，远离文明社会，进行危险的奥术实验。",al={"克希雷姆是谁","大法师克希雷姆的故事","克希雷姆的背景"}},{q="克希雷姆为什么想杀死巨龙摩弗拉斯？",a="绿龙幼龙摩弗拉斯袭击了克希雷姆的追随者，并将他的一名学徒整个吞下。那名学徒随身带着一块蕴含庞大奥术力量的碎片，克希雷姆想要杀死这条幼龙，好从它腹中取回那件遗物。",al={"克希雷姆与摩弗拉斯","为什么杀死摩弗拉斯","摩弗拉斯的碎片"}},{q="人们为什么说克希雷姆很危险？",a="杰迪加等当地知情人告诫旅人，克希雷姆难以捉摸、冷漠疏离，与其他人类相比显得格外古怪。",al={"克希雷姆是否危险","克希雷姆发疯","克希雷姆的性格"}},{q="克希雷姆属于联盟还是肯瑞托？",a="克希雷姆是一位完全独立行事的隐士。他并未积极为联盟军队效力，只要冒险者愿意听从他的吩咐，无论属于哪个阵营，他都乐意与之打交道。",al={"克希雷姆的阵营","克希雷姆是否属于联盟","克希雷姆与肯瑞托"}}},fp="14,184,25.381.0,24.334.1,40.186.0,22.185.0,44.183.0,37.131.0,51.171.0"}
P.entries["npc:argent-guard-manados"] = {n="银月守卫玛纳杜斯",s="在达纳苏斯的工匠区，银月守卫玛纳杜斯警戒着卡利姆多各地的腐化势力。他效力于银色黎明，并派遣冒险者前往黑暗深渊。",h="在达纳苏斯的工匠区，银月守卫玛纳杜斯警戒着卡利姆多各地的腐化势力。他效力于银色黎明，并派遣冒险者前往黑暗深渊。",kw={"银色黎明","银月守卫玛纳杜斯","黑暗深渊","工匠区","达纳苏斯","玛纳杜斯","暮光之锤的末日"},ang={["faction:Alliance"]="作为到访达纳苏斯的联盟勇士，你可以通过玛纳杜斯，了解远在洛丹伦的征战与卡利姆多北部日益增长的教徒威胁之间的联系。",["race:NightElf"]="身为暗夜精灵，玛纳杜斯表明，职责并不限于塞纳里奥议会和Sentinels之内。一些暗夜精灵效力于银色黎明这样的中立组织，以守护艾泽拉斯。"},sec={{t="黎明的哨兵",b="银月守卫玛纳杜斯在达纳苏斯为银色黎明守望。组织中的大多数成员都在守卫洛丹伦，抵御天灾军团，而他则驻守在工匠区的工匠与商贩之间。这处哨位让他得以留意威胁卡利姆多北部平衡的势力。当他得知暮光之锤已在灰谷的波涛之下站稳脚跟时，便召集有能力的英雄进攻黑暗深渊，夺取教徒用以供奉黑暗的神器。"}},faq={{q="银月守卫玛纳杜斯是谁？",a="玛纳杜斯是银色黎明的一名暗夜精灵，驻守在达纳苏斯。他警戒着卡利姆多的黑暗教派与异界腐化，而组织的重心则放在东部王国的天灾军团身上。",al={"玛纳杜斯是谁","银月守卫玛纳杜斯的职责","玛纳杜斯 达纳苏斯"}},{q="在哪里可以找到银月守卫玛纳杜斯？",a="你可以在达纳苏斯的工匠区找到玛纳杜斯。他守望着这座城市，并与当地的冒险者协调行动。",al={"玛纳杜斯的位置","银月守卫玛纳杜斯在哪里","玛纳杜斯 工匠区"}},{q="银月守卫玛纳杜斯提供什么任务？",a="玛纳杜斯提供暮光之锤的末日任务。他派遣冒险者进入灰谷的黑暗深渊，从里面的教徒手中取回暮光坠饰。",al={"玛纳杜斯的任务","暮光之锤的末日任务给予者","黑暗深渊 银色黎明任务"}},{q="银色黎明为何关注黑暗深渊？",a="银色黎明时刻警惕着威胁艾泽拉斯的邪恶势力。暮光之锤教派出现在灰谷被水淹没的废墟中，崇拜着古老而腐化的存在，银色黎明无法坐视这一威胁。",al={"银色黎明为何关注黑暗深渊","银色黎明 暮光教派"}}},fx={df5dd966={q="银月守卫玛纳杜斯属于哪一方？",a="银月守卫玛纳杜斯效力于银色黎明，这是一个致力于铲除邪恶、保护艾泽拉斯免受黑暗腐化侵害的独立组织。虽然他是一名驻扎在达纳苏斯的暗夜精灵，但他主要效忠于银色黎明在世界各地开展的圣战，而非联盟的常规指挥体系。",al={"玛纳杜斯的阵营","玛纳杜斯效忠谁","玛纳杜斯是否属于联盟"}},f4cc0234={q="银月守卫玛纳杜斯想做什么？",a="玛纳杜斯想要阻止在灰谷海岸滋生的黑暗仪式。他召集能干的冒险者深入黑暗深渊，打击亵渎暗夜精灵古老圣所的暮光之锤教徒。",al={"玛纳杜斯在寻找什么","玛纳杜斯的目标","为何派人前往黑暗深渊"}}},fp="20,180,22.469.0,28.193.0,38.136.0,43.143.0,55.218.0"}
P.entries["npc:argos-nightwhisper"] = {n="阿古斯·夜语",s="在暴风城的花园区，阿古斯·夜语指引联盟旅人前往黑海岸。他的兄弟戈沙拉正在研究那里不断蔓延的腐化。",h="在暴风城的花园区，阿古斯·夜语指引联盟旅人前往黑海岸。他的兄弟戈沙拉正在研究那里不断蔓延的腐化。",kw={"阿古斯","奥伯丁","远方的堕落","达纳苏斯","卡多雷","夜语","公园区","暴风城"},ang={["faction:Alliance"]="作为联盟英雄，你可以将阿古斯视为连接东部王国与卡利姆多的纽带。他鼓励年轻的英雄跨越大海，援助暗夜精灵。",["race:NightElf"]="作为远离卡利姆多的kaldorei，你或许会觉得阿古斯十分亲切。他指引旅人前往黑海岸，寻找他的兄弟，并应对危及他们家园的威胁。"},sec={{t="人类首都中的一位卡多雷",b="阿古斯·夜语与聚集在暴风城花园区的暗夜精灵一同生活。那里宁静的林地让他们想起了卡多雷世代居住的森林。与其他身在人类王国的同族一样，阿古斯帮助跨越无尽之海的新盟友建立联系。来自大洋彼岸的消息令他忧心。他敦促有能力的联盟勇士前往黑海岸的奥伯丁，他的兄弟戈沙拉在那里需要帮助，以应对不断蔓延的腐化。"}},faq={{q="阿古斯·夜语是谁？",a="阿古斯·夜语是一位居住在暴风城的暗夜精灵。他在这座位于东方的联盟首都代表达纳苏斯，并指引旅人寻找前往卡利姆多的航路。",al={"阿古斯·夜语","阿古斯是谁","阿古斯 暴风城"}},{q="在哪里可以找到阿古斯·夜语？",a="你可以在花园区找到阿古斯，那是暴风城中草木葱茏的城区，来访的暗夜精灵聚集于此。",al={"阿古斯位置","阿古斯在哪里","寻找阿古斯·夜语"}},{q="阿古斯请求冒险者做什么？",a="阿古斯请求经验丰富的冒险者前往黑海岸的奥伯丁。他的兄弟戈沙拉需要帮助，研究正在这片土地上蔓延的腐化。",al={"遥远的旅途任务","阿古斯任务","为什么去达纳苏斯"}},{q="阿古斯与其他夜语家族成员有亲属关系吗？",a="有。阿古斯是戈沙拉·夜语的兄弟，后者是一位身在黑海岸奥伯丁的暗夜精灵学者。正因如此，阿古斯才会派旅人前往那里。",al={"夜语家族","阿古斯的亲属"}}},fx={["50b5b885"]={q="阿古斯·夜语效忠哪一方？",a="阿古斯·夜语坚定地支持联盟和自己的卡多雷同胞。作为一名居住在暴风城花园区的使节与旅者之间的暗夜精灵，他始终效忠达纳苏斯，同时帮助那些致力于保卫联盟、为联盟谋求福祉的旅者和英雄。",al={"阿古斯·夜语阵营","阿古斯是否属于联盟","阿古斯为谁效力"}},e48f5556={q="阿古斯·夜语为什么会在暴风城？",a="阿古斯留在花园区，这片葱郁的庇护之地是暴风城专为暗夜精灵划出的。与许多身在人类首都的同胞一样，他担任达纳苏斯与东部王国之间的使者和联络人，寻找能干的勇士，协助处理卡多雷在外的事务。",al={"阿古斯为何在暴风城","阿古斯·夜语为何在这里","阿古斯在暴风城做什么"}}},fp="18,144,31.434.0,26.165.0,38.98.0,38.152.0,40.139.0"}
P.entries["npc:arugal"] = {n="阿鲁高",s="在影牙城堡，阿鲁高统领着他为对抗天灾军团而召来的狼人。疯狂与悲痛让这位昔日的达拉然法师自封为它们的父亲，而他的力量正威胁着银松森林。",h="在影牙城堡，阿鲁高统领着他为对抗天灾军团而召来的狼人。疯狂与悲痛让这位昔日的达拉然法师自封为它们的父亲，而他的力量正威胁着银松森林。",kw={"阿鲁高","肯瑞托","焚木村","暗影之牙","席瓦莱恩","银松森林","ur","狼人"},ang={["class:Mage"]="阿鲁高的遭遇揭示了鲁莽召唤的危险：肯瑞托的研究化作了一场无法控制的噩梦。",["faction:Horde"]="阿鲁高的狼人盘踞在瑟伯切尔以南的道路上，Sylvanas女士已下令处决他，确保银松森林掌握在被遗忘者手中。",["race:Undead"]="阿鲁高的野兽已经杀死了数名亡灵哨兵和药剂师。皇家药剂师学会需要有人终结他的疯狂。"},sec={{t="绝望的召唤",b="在洛丹伦陷落之前，阿鲁高曾是肯瑞托的一员。一些同僚，包括达拉尔·道恩维沃尔，都称他是个骗子，靠附魔饰物弥补施法能力的不足。第三次战争期间，天灾军团席卷北方，阿鲁高开始寻找能够阻挡亡灵的武器。他利用已故达拉然法师乌尔的研究，穿透界域之间的帷幕，召来了狼人。这些饥肠辘辘的野兽撕碎了天灾军团的军队，却无人能遏制它们的凶性。很快，它们便将饥饿的目光转向了无辜的凡人。"},{t="陷入疯狂",b="狼人屠戮了天灾军团，随后又转而攻击召唤它们的法师。它们围攻了席瓦莱恩男爵的祖传领地，城堡最终沦陷在利爪与獠牙之下。席瓦莱恩和他的家臣都死于这场屠杀。愧疚摧毁了阿鲁高的心智，但他并未逃离自己造就的灾祸。他将这些野兽收作自己的子嗣，并将这座要塞改名为影牙城堡。他盘踞在城墙之上，身边尽是受害者的幽魂与忠诚的猎犬群。"},{t="银松之祸",b="阿鲁高的力量从影牙城堡延伸至周围的乡野。他的黑暗巫术笼罩着焚木村，村民承受着入夜便会发作的诅咒，埃利姆矿洞中也遍布饥饿的月怒野兽。被遗忘者视他为无法容忍的威胁。希尔瓦娜斯·风行者麾下的亡灵哨兵和药剂师正密谋处决这位疯狂的大法师，以保卫他们新生王国的边境。"}},faq={{q="阿鲁高是谁？",a="阿鲁高曾是肯瑞托的一名人类大法师。第三次战争期间，他召来狼人对抗天灾军团。自己的所作所为令他不堪重负，于是他退居影牙城堡，如今自封为狼人的父亲，统领着成群的狼人。",al={"阿鲁高是谁","阿鲁高的过往","暗影之牙首领背景"}},{q="阿鲁高为什么召唤狼人？",a="第三次战争期间，天灾军团几乎要席卷洛丹伦北部。阿鲁高试图寻找阻止亡灵的武器，为此借助了达拉然法师乌尔对异位面的研究。他相信这些凶残的野兽能够消灭天灾军团，却在召唤它们之后失去了控制。",al={"为什么是狼人","为什么召唤野兽","阿鲁高召唤狼人的动机"}},{q="阿鲁高如今住在哪里？",a="阿鲁高的巢穴位于影牙城堡的最高处，这座古老的要塞坐落在银松森林南部，俯瞰着焚木村。他那凶兽般的宠物狼芬鲁斯与忠诚的狼人、不安的幽魂一同守护着他。",al={"阿鲁高在哪里","阿鲁高的位置","寻找阿鲁高"}},{q="席瓦莱恩男爵遭遇了什么？",a="席瓦莱恩男爵曾是统治这座要塞和焚木村村庄的贵族领主。阿鲁高的狼人围攻城堡时，席瓦莱恩与他的廷臣惨遭屠戮。他们饱受折磨的幽魂至今仍在城堡的厅堂中游荡。",al={"席瓦莱恩男爵的命运","暗影之牙原本属于谁","城堡的历史"}},{q="被遗忘者为什么想要阿鲁高死？",a="阿鲁高麾下的兽群在银松森林肆虐，袭击被遗忘者的斥候，伏击巡逻队，还感染了皇家药剂师学会的仆从。希尔瓦娜斯·风行者认为，这位疯狂的大法师直接威胁着幽暗城边境的安全与扩张。",al={"被遗忘者与阿鲁高的对抗","除掉阿鲁高任务","为什么杀死阿鲁高"}},{q="焚木村中了什么诅咒？",a="阿鲁高的魔法让焚木村的人类居民染上了狼人诅咒。白天，村民看起来仍是人类，但到了夜幕降临时，他们就会变成凶残的野兽，被迫守卫阿鲁高的领地。",al={"焚木村的诅咒","焚木村村民为什么是狼","焚木村与阿鲁高"}}},fx={c709d248={q="大法师阿鲁高属于哪一方？",a="阿鲁高既不效力于联盟，也不效力于部落。他曾是达拉然肯瑞托的一员，但陷入疯狂后断绝了所有旧日关系。如今，他在影牙城堡中率领自己的野蛮狼群，将狼人视为真正的子嗣，并强烈排斥肯瑞托使者和被遗忘者。",al={"阿鲁高的阵营","阿鲁高效忠谁","阿鲁高属于部落还是联盟"}},["5a0ecd53"]={q="大法师阿鲁高想做什么？",a="阿鲁高释放狼人给世间带来灾祸后，深陷罪疚与疯狂，如今一心想庇护、统领并壮大自己的族群。他用附魔魔法将野兽束缚于自己的意志之下，在银松森林传播狼人诅咒，以建立他黑暗的家族，并屠杀任何胆敢侵入其领地的人。",al={"阿鲁高的目标","阿鲁高想做什么","阿鲁高的动机"}},["127eccbf"]={q="大法师阿鲁高为何在影牙城堡？",a="被召唤出的狼人挣脱控制后，袭击了焚木村上方席瓦莱恩男爵的堡垒。阿鲁高因自己一手酿成的灾祸而发疯，将凶暴的野兽收为子嗣，占据了化为废墟的城堡，并将其更名为影牙城堡，以隐居之姿统治自己的族群。",al={"阿鲁高为何在这里","阿鲁高为何前往影牙城堡","阿鲁高如何占据影牙城堡"}},["760497b6"]={q="大法师阿鲁高为何令人畏惧？",a="阿鲁高因借助乌尔的禁忌研究、将野蛮的狼人释放到世间而在洛丹伦臭名昭著。他带来的诅咒不只杀死了天灾军团，还感染附近的土地，将和平的村民变成嗜血野兽，并在他反复无常的魔法操控下，把整个地区变成了噩梦。",al={"阿鲁高为何出名","阿鲁高的声望","阿鲁高为何危险"}}},fp="6,206,19.527.0,17.463.0,25.398.1,14.242.0,33.280.0,35.225.0,35.197.0,37.264.0,38.207.0"}
P.entries["npc:ashlan-stonesmirk"] = {n="阿什兰·暗石",s="在丹莫德，阿什兰·暗石随守卫萨多尔大桥的部队一同警戒边境。这位矮人爆破专家时刻提防着威胁铁炉堡的危险。",h="在丹莫德，阿什兰·暗石随守卫萨多尔大桥的部队一同警戒边境。这位矮人爆破专家时刻提防着威胁铁炉堡的危险。",kw={"水坝危机","阿什兰","丹莫德","铁炉堡","洛克莫丹","暗石"},ang={["faction:Alliance"]="阿什兰的工作有助于保障连接洛克莫丹、湿地和北方联盟领土的战略通道安全。",["race:Dwarf"]="身为矮人，阿什兰代表着那些技艺精湛的专家，他们沿卡兹莫丹边境为铁炉堡的士兵提供支援。"},sec={{t="边境上的专家",b="在湿地北部的丹莫德，阿什兰·暗石效力于守卫萨多尔大桥的部队。当可疑材料威胁到矮人的防御时，他的爆破知识使他成为值得求助的人。"},{t="迫近的黑暗威胁",b="首席工程师辛德维尔七世在巨石水坝附近发现了可疑的粉末，将其送交阿什兰检验。阿什兰认出这种粉末是爆盐，并说明了如何消除它的威胁。"}},faq={{q="在哪里可以找到阿什兰·暗石？",a="阿什兰·暗石驻扎在湿地北部的丹莫德，靠近萨多尔大桥。",al={"阿什兰位置","阿什兰·暗石在哪里","阿什兰·暗石位置"}},{q="阿什兰·暗石担任什么职责？",a="阿什兰·暗石是一位矮人爆破专家，隶属于守卫丹莫德和萨多尔大桥的部队。辛德维尔七世请他鉴定在巨石水坝附近发现的可疑粉末。",al={"阿什兰·暗石是谁","阿什兰职责","阿什兰做什么"}},{q="阿什兰提供哪些任务？",a="在“水坝危机”任务中，阿什兰帮助冒险者检验首席工程师辛德维尔七世送来的可疑粉末。",al={"阿什兰任务","阿什兰·暗石提供的任务"}}},fx={["0cdc60de"]={q="阿什兰·暗石是谁？",a="阿什兰·暗石是一名矮人爆炸物专家，驻扎在湿地北部丹莫德的军团中。",al={"阿什兰是谁","阿什兰·暗石的背景","阿什兰·暗石是谁"}},c5f8e74c={q="阿什兰·暗石属于哪一方？",a="他效力于铁炉堡和联盟，协助守卫湿地北部，并查明对矮人工程构成威胁的事物。",al={"阿什兰·暗石的阵营","阿什兰是否属于联盟","阿什兰·暗石效忠谁"}},["82d01692"]={q="阿什兰·暗石为何在这里？",a="阿什兰驻扎在丹莫德，他的爆炸物知识能帮助矮人军团和调查巨石水坝险情的旅者。",al={"阿什兰为何在洛克莫丹","阿什兰·暗石营地的用途","阿什兰为何在莫格罗什附近"}}},fp="17,163,23.215.0,19.203.1,35.91.0,33.193.0,30.114.0"}
P.entries["npc:asterion"] = {n="阿斯特利安",s="在巴莎兰，阿斯特利安仍被月亮石封印束缚着。这位古老的上层精灵曾侍奉总督埃瑟里克斯·纳拉辛，如今他的灵魂在废墟间等待解脱。",h="在巴莎兰，阿斯特利安仍被月亮石封印束缚着。这位古老的上层精灵曾侍奉总督埃瑟里克斯·纳拉辛，如今他的灵魂在废墟间等待解脱。",kw={"亚米萨兰","阿斯特利安","埃瑟里克斯","巴莎兰","黑海岸","上层精灵","月亮石","纳拉辛","萨特"},ang={["class:Mage"]="阿斯特利安生前以精通奥术和擅长近身格斗而闻名。他的故事让人得以窥见早期Kaldorei的施法技艺。",["faction:Alliance"]="愿意信任并帮助联盟冒险者的上层精灵灵魂并不多，阿斯特利安便是其中之一。他寻求他们的帮助，以打破囚禁了自己一万年的牢笼。",["race:NightElf"]="阿斯特利安是Sundering之前遗留下来的悲剧人物。他的故事展现了艾萨拉邀请燃烧军团进入他们的领地之前，上层精灵内部残酷的权力斗争。"},sec={{t="昔日荣光的侍从",b="在大灾变之前，巴莎兰与亚米萨兰是一对受到艾萨拉女王赐福的姊妹城市。她任命埃瑟里克斯·纳拉辛统治这两座城市，而阿斯特利安则是他的得力助手。阿斯特利安以近身格斗和奥术魔法闻名，与巴莎兰的居民生活在一起。他经常往返于两座姊妹城市之间，照料居民的需求。"},{t="月亮石牢笼",b="阿斯特利安失去了埃瑟里克斯·纳拉辛的宠信，原因早已湮没在岁月之中。他的主人制作了一道强大的月亮石封印，那是一座无法逃脱的魔法牢笼，要将他囚禁在巴莎兰。数个世纪的囚禁让阿斯特利安痛苦不堪。即使死亡也未能带来解脱：世界崩裂、恶魔侵占这片聚居地之后，他的灵魂依然被束缚在破败的神殿中。"},{t="来自坟墓的复仇",b="邪恶的萨特和劣魔在巴莎兰游荡，吞噬着残存的奥术能量，却避开了阿斯特利安的幽灵徘徊的神殿。一名联盟冒险者可以从萨特手中夺取月亮石封印，并在亚米萨兰将其击碎，终于斩断束缚阿斯特利安灵魂的锁链。自由并未带来安宁。埃瑟里克斯·纳拉辛依然存活于世，阿斯特利安摆脱了一万年的绝望，转而寻求复仇。"}},faq={{q="阿斯特利安是谁？",a="阿斯特利安是黑海岸巴莎兰废墟中一位古老的上层精灵幽灵。在天崩地裂之前，他是一位技艺精湛的法师，也是总督埃瑟里克斯·纳拉辛的副手。",al={"阿斯特利安的故事","巴莎兰的幽灵是谁","黑海岸精灵幽灵"}},{q="阿斯特利安为什么被囚禁？",a="埃瑟里克斯·纳拉辛用一道魔法月亮石封印束缚了阿斯特利安。他们反目的原因无人知晓，但这道强大的魔法将阿斯特利安的灵魂禁锢了数千年，即使死后也未能解脱。",al={"阿斯特利安为何被困","阿斯特利安的牢笼","埃瑟里克斯为何囚禁阿斯特利安"}},{q="巴莎兰的萨特为什么不攻击他？",a="萨特和劣魔以巴莎兰残存的奥术能量为食，却远远避开了束缚阿斯特利安的神殿。萨特持有维系这座牢笼的月亮石封印，并不干扰他的灵魂。",al={"萨特会攻击阿斯特利安吗","恶魔为何不打扰阿斯特利安"}},{q="阿斯特利安生前住在哪里？",a="阿斯特利安曾与巴莎兰的居民生活在一起。他经常南下前往巴莎兰的姊妹城市亚米萨兰，在艾萨拉女王任命的总督麾下处理城务。",al={"阿斯特利安的家","阿斯特利安来自哪里"}},{q="释放他之后会发生什么？",a="阿斯特利安希望打破月亮石封印，结束这场延续到死后的囚禁。之后发生的事，将在隐藏的篇章中讲述。",al={"阿斯特利安后来如何","阿斯特利安会安息吗","阿斯特利安的复仇"}},{q="阿斯特利安敌视如今的暗夜精灵吗？",a="不。虽然阿斯特利安是来自艾萨拉女王宫廷的古老上层精灵，但他对联盟旅人态度友善，并寻求他们的帮助，以打破古老的魔法束缚。",al={"阿斯特利安友善吗","阿斯特利安与联盟"}}},fx={["0f52734c"]={q="阿斯特利安想做什么？",a="阿斯特利安想要摆脱困住自己灵魂长达一万年的古老魔法囚牢。阿斯瑞库斯·纳拉辛用月石封印将他束缚在巴莎兰，即使肉身消亡，阿斯特利安仍饱受折磨。他迫切需要你从萨特手中夺回封印，并在亚米萨兰将其击碎，以结束漫长的苦难，让他得以将心思转向报复昔日的主人。",al={"阿斯特利安的目标","阿斯特利安需要什么","阿斯特利安的动机"}},["98a0ebe3"]={q="阿斯特利安与谁有关联？",a="远古时期，阿斯特利安直接效力于阿斯瑞库斯·纳拉辛。阿斯瑞库斯是艾萨拉女王任命的上层精灵领主，负责统治亚米萨兰和巴莎兰。作为副手，阿斯特利安照料着两处聚居地的事务。尽管阿斯特利安忠心耿耿，阿斯瑞库斯还是用黑暗法术将他囚禁在奥术月石牢笼中，缘由早已湮没于历史，昔日的主从情谊也就此沦为背叛的遗产。",al={"阿斯特利安的主人","是谁囚禁了阿斯特利安","阿斯瑞库斯·纳拉辛与阿斯特利安"}}},fp="8,175,29.355.0,20.384.0,24.410.1,16.187.0,27.195.0,47.230.0,32.158.0,32.150.1,42.171.0"}
P.entries["npc:athridas-bearmantle"] = {n="阿斯瑞达斯·熊皮",s="在多兰纳尔，阿斯瑞达斯·熊皮致力于保护聚落及周边荒野。这位暗夜精灵德鲁伊派遣年轻的冒险者，调查当地野生动物和附近瘤背熊怪遭受腐化的情况。",h="在多兰纳尔，阿斯瑞达斯·熊皮致力于保护聚落及周边荒野。这位暗夜精灵德鲁伊派遣年轻的冒险者，调查当地野生动物和附近瘤背熊怪遭受腐化的情况。",kw={"阿斯瑞达斯","熊皮","多兰纳尔","熊怪","瘤背","卡多雷","暗夜精灵","泰达希尔"},ang={["class:Druid"]="阿斯瑞达斯对抗遭受腐化的瘤背，并关切古老圣物，这些都关乎德鲁伊誓言恢复的自然平衡。",["race:NightElf"]="对于离开幽影谷的年轻Kaldorei而言，阿斯瑞达斯让他们看到了新家园面临的困境，这里已受到来自内部的威胁。"},sec={{t="多兰纳尔的守护者",b="在多兰纳尔，阿斯瑞达斯·熊皮协助保护从幽影谷前来的暗夜精灵。新近长成的世界之树泰达希尔，显露出反常的衰败与动荡迹象。阿斯瑞达斯组织当地的侦察行动，守护城镇，抵御周边荒野中的威胁。"},{t="熊怪的苦难",b="阿斯瑞达斯为附近的瘤背熊怪忧心忡忡。这个部族曾是和平的邻居，如今却陷入了不断蔓延的疯狂与腐化，其萨满祭司和酋长也深受毒害，开始对卡多雷施暴。阿斯瑞达斯召集有意相助的勇士，遏制危险，并调查正在荒野中扎根的深层腐化。"}},faq={{q="阿斯瑞达斯·熊皮是谁？",a="阿斯瑞达斯·熊皮是一名暗夜精灵，居住在泰达希尔的多兰纳尔。他组织聚落的防御，并召集冒险者，应对世界之树枝桠间涌现的威胁。",al={"阿斯瑞达斯是谁","阿斯瑞达斯·熊皮的背景故事","阿斯瑞达斯 多兰纳尔"}},{q="在哪里可以找到阿斯瑞达斯·熊皮？",a="阿斯瑞达斯就在多兰纳尔，这是暗夜精灵冒险者离开泰达希尔的幽影谷后抵达的第一座主要城镇。",al={"阿斯瑞达斯的位置","阿斯瑞达斯在哪里","寻找阿斯瑞达斯·熊皮"}},{q="阿斯瑞达斯主要关注哪些威胁？",a="阿斯瑞达斯主要关注充满敌意的瘤背熊怪，腐化驱使它们四处袭击。他指引旅人遏制它们的攻势，调查它们陷入疯狂的原因，并寻回至关重要的圣物。",al={"阿斯瑞达斯的任务","阿斯瑞达斯想要什么","阿斯瑞达斯·熊皮的任务"}},{q="瘤背熊怪为什么攻击多兰纳尔？",a="瘤背部族遭到了某种反常的腐化，这股腐化正在泰达希尔蔓延。它使部族的萨满祭司和战士陷入疯狂，对暗夜精灵充满敌意。",al={"瘤背为何疯狂","瘤背的腐化","熊怪的敌意 泰达希尔"}},{q="阿斯瑞达斯在保卫泰达希尔方面发挥了什么作用？",a="阿斯瑞达斯组织早期防御，应对泰达希尔野兽和熊怪中的腐化，努力阻止这股威胁吞没多兰纳尔。",al={"阿斯瑞达斯的作用","阿斯瑞达斯的重要性"}}},fp="19,209,20.270.0,22.368.0,27.179.0,37.126.0,36.208.0,50.171.0,52.160.0"}
P.entries["npc:auntie-bernice-stonefield"] = {n="波尼斯·斯通菲尔德姑妈",s="在艾尔文森林中南部的斯通菲尔德家宅，“大婶”波尼斯·斯通菲尔德留意着邻里的动静。王国的征战夺走了她的丈夫，如今她住在斯通菲尔德妈妈身旁，她做的猪肉馅饼在整个山谷都很有名。她始终对与自家敌对的马科伦家族深怀戒心。",h="在艾尔文森林中南部的斯通菲尔德家宅，“大婶”波尼斯·斯通菲尔德留意着邻里的动静。王国的征战夺走了她的丈夫，如今她住在斯通菲尔德妈妈身旁，她做的猪肉馅饼在整个山谷都很有名。她始终对与自家敌对的马科伦家族深怀戒心。",kw={"大婶","波尼斯","艾尔文","金牙","马科伦","项链","猪肉馅饼","斯通菲尔德"},ang={["profession:Cooking"]="波尼斯的猪肉馅饼是人类边疆丰盛家常菜中的一道常见美食，在整个艾尔文森林都很有名。",["race:Human"]="身为人类，波尼斯展现了暴风城乡民的坚韧，在丈夫为王国战死后，仍继续操持日常生活，守护家族的骄傲。"},sec={{t="艰辛的一生",b="波尼斯的丈夫在暴风城王国的征战中丧生。如今，她与亲人一同住在家族宅邸。她在那里帮助斯通菲尔德妈妈打理农场的日常事务，操持家务，照料一家人的饮食。她做的猪肉馅饼让她名扬整个山谷。"},{t="世仇与失踪的项链",b="对波尼斯而言，斯通菲尔德与马科伦家族两家之间的积怨根深蒂固。她珍爱的传家项链失踪后，她怀疑是年幼的比利·马科伦拿走了它。然而，找回项链远比处理邻居的一场恶作剧更复杂。比利发誓自己没有偷项链，却几乎承认是自己把它掉在了法戈第矿洞附近。在那里，他看见长着金牙的狗头人金牙抢走项链，把它带回了巢穴。"}},faq={{q="“大婶”波尼斯·斯通菲尔德是谁？",a="“大婶”波尼斯·斯通菲尔德是斯通菲尔德家族的一位长辈，住在艾尔文森林南部的斯通菲尔德农场。王国的战争让她成了寡妇，如今她与斯通菲尔德妈妈一同照料农场，并以制作猪肉馅饼闻名。",al={"波尼斯 大婶是谁","波尼斯·斯通菲尔德 的故事","斯通菲尔德 大婶"}},{q="波尼斯大婶的丈夫遭遇了什么？",a="波尼斯的丈夫在为暴风城王国作战的一次军事行动中阵亡，留下她独自守寡。",al={"波尼斯 大婶的丈夫","波尼斯 的丈夫是谁","斯通菲尔德 寡妇"}},{q="波尼斯大婶以什么闻名？",a="波尼斯做的猪肉馅饼在当地乡间远近闻名，就连调皮捣蛋的邻居也愿意拿东西来换上一块。",al={"波尼斯·斯通菲尔德 的馅饼","艾尔文 猪肉馅饼"}},{q="波尼斯大婶为什么生比利·马科伦的气？",a="波尼斯怀疑比利·马科伦拿走了她珍爱的传家项链，使斯通菲尔德与马科伦家族两家由来已久的仇怨进一步加深。",al={"比利·马科伦的世仇","偷 波尼斯 项链的人","波尼斯 为什么讨厌 比利"}},{q="比利·马科伦真的偷了项链吗？",a="比利发誓自己没有偷波尼斯的项链，却几乎承认是自己把它掉在了法戈第矿洞附近。他说，长着金牙的狗头人金牙捡起项链，把它带回了巢穴。",al={"比利 偷了项链吗","斯通菲尔德 的项链在谁手里","金牙 项链"}},{q="波尼斯大婶在哪里？",a="波尼斯就在斯通菲尔德农场的主屋外，位于闪金镇与西部荒野之间道路的南侧，在斯通菲尔德妈妈身旁。",al={"波尼斯 大婶的位置","波尼斯·斯通菲尔德 在哪里"}}},fx={["0a2ddc6d"]={q="波尼斯·斯通菲尔德效忠哪一方？",a="波尼斯老太太是暴风城王国的忠诚臣民，也以身为斯通菲尔德家族的一员为荣。在家族与邻居马科伦一家由来已久的激烈争斗中，她坚定地站在亲族一边，对任何冠着那个姓氏的人都没什么耐心。",al={"波尼斯老太太阵营","波尼斯支持谁","波尼斯·斯通菲尔德联盟"}},["0e5ea09d"]={q="波尼斯·斯通菲尔德想要什么？",a="波尼斯老太太最想找回她珍视的家传项链，项链失踪后，她怀疑是小比利·马科伦拿走了它。为了解开谜团、找回传家宝，她愿意烤一个自己拿手的猪肚馅饼，哄他说出实情。",al={"波尼斯老太太需要什么","波尼斯老太太目标","波尼斯·斯通菲尔德任务动机"}},f6bb7867={q="波尼斯·斯通菲尔德为什么会在这里？",a="斯通菲尔德农场是波尼斯老太太的家。她的丈夫在暴风城的一次军事行动中丧生，此后，她便与斯通菲尔德妈妈及其他族人一起，留在艾尔文森林的家族农庄里，操持家务，料理农活。",al={"波尼斯为何在农场","波尼斯·斯通菲尔德在此的原因","波尼斯老太太为何来到这里"}},["21972eac"]={q="波尼斯·斯通菲尔德与谁有关联？",a="她是斯通菲尔德家族的一位女性长辈，与斯通菲尔德妈妈一起住在艾尔文森林的家族农场。她的家族与附近的马科伦一家长期激烈对立，这几乎影响着她与对方家族成员的每一次来往。",al={"波尼斯老太太家族","波尼斯·斯通菲尔德亲属","波尼斯老太太与谁有亲属关系"}}},fp="27,319,18.302.0,33.438.1,33.237.0,42.109.0,34.129.0,47.141.0,46.196.1,32.139.0"}
P.entries["npc:austil-de-mon"] = {n="奥斯蒂尔·德·蒙",s="在布瑞尔，奥斯蒂尔·德·蒙在恐惧之末旅店训练被遗忘者战士。他教导新近苏醒的亡灵为黑暗女王而战。",h="在布瑞尔，奥斯蒂尔·德·蒙在恐惧之末旅店训练被遗忘者战士。他教导新近苏醒的亡灵为黑暗女王而战。",kw={"奥斯蒂尔·德·蒙","布瑞尔","被遗忘者战士","恐惧之末旅店","提瑞斯法林地","战士训练师"},ang={["class:Warrior"]="作为一名离开丧钟镇的被遗忘者战士，你可以在提瑞斯法林地拜奥斯蒂尔·德·蒙为师，接受指导和正规的技能训练。",["race:Undead"]="作为新近苏醒的亡灵，你可以跟随奥斯蒂尔训练，成为一名前线战士，准备保卫洛丹伦，对抗Scourge和血色十字军。"},sec={{t="恐惧之末的老兵",b="奥斯蒂尔·德·蒙在布瑞尔的恐惧之末旅店内训练被遗忘者战士。离开丧钟镇的战士会前来向他求教，他是他们最早接触的导师之一。活人曾在这间旅店饮酒歇息。如今，奥斯蒂尔教导刚刚获得解放的亡灵掌握武艺与战斗技巧，对抗王国四周的敌人。"}},faq={{q="奥斯蒂尔·德·蒙是谁？",a="奥斯蒂尔·德·蒙在提瑞斯法林地的布瑞尔训练亡灵战士，教导被遗忘者战斗人员。",al={"奥斯蒂尔·德·蒙","奥斯蒂尔","奥斯蒂尔是谁"}},{q="在哪里可以找到奥斯蒂尔·德·蒙？",a="你可以在提瑞斯法林地布瑞尔的恐惧之末旅店找到奥斯蒂尔·德·蒙，就在幽暗城北面。",al={"奥斯蒂尔·德·蒙位置","奥斯蒂尔在哪","奥斯蒂尔·德·蒙地图"}},{q="他在布瑞尔担任什么职责？",a="奥斯蒂尔教导新手战士掌握战斗技巧、姿态和战斗技能，增强被遗忘者军队应对当地威胁的实力。",al={"奥斯蒂尔做什么","奥斯蒂尔训练师","奥斯蒂尔职责"}}},fp="13,123,25.300.0,21.65.0,31.105.0,32.153.0"}
P.entries["npc:ayanna-everstride"] = {n="阿亚娜·远途",s="在幽影谷，阿亚娜·远途向年轻的卡多雷传授猎人之道。她驻守在奥达希尔，在世界之树之下教授射术、追踪和生存技巧。",h="在幽影谷，阿亚娜·远途向年轻的卡多雷传授猎人之道。她驻守在奥达希尔，在世界之树之下教授射术、追踪和生存技巧。",kw={"奥达希尔","阿亚娜","远途","猎人训练师","暗夜精灵","幽影谷","泰达希尔"},ang={["class:Hunter"]="作为一名从幽影谷起步的猎人，你可以向阿亚娜·远途寻求武器使用、追踪和荒野生存方面的最初指引。",["race:NightElf"]="身为暗夜精灵，你会在奥达希尔神圣的树洞内找到阿亚娜。她训练初出茅庐的新兵，让他们抵御不断侵袭周围森林的腐化，并协助守护年轻的世界之树。"},sec={{t="幽影谷的导师",b="阿亚娜·远途在幽影谷中心的奥达希尔内，训练刚刚苏醒的卡多雷猎人。对暗夜精灵而言，猎人是神圣森林不可或缺的守护者，而不仅仅是捕猎者或神射手。阿亚娜向新手传授基础武艺、远程作战技巧，以及如何在泰达希尔危机四伏的林地中生存。"}},faq={{q="阿亚娜·远途是谁？",a="阿亚娜·远途在泰达希尔幽影谷的奥达希尔内训练暗夜精灵新手猎人。她教授基础战斗和野外生存技巧。",al={"阿亚娜·远途","阿亚娜是谁","奥达希尔猎人训练师"}},{q="在哪里可以找到阿亚娜·远途？",a="你可以在泰达希尔中心的幽影谷找到阿亚娜·远途，她就在奥达希尔内，那是一处建在巨大空心树中的聚居地。",al={"阿亚娜位置","阿亚娜在哪","寻找阿亚娜·远途"}},{q="哪些任务与阿亚娜·远途有关？",a="在早期训练中，暗夜精灵新手猎人会被派去寻找阿亚娜。他们最初的导师可能会交给他们一枚风化符记，随后阿亚娜会为这些立志成为林地游侠的新手提供入门训练。",al={"阿亚娜任务","风化符记任务","阿亚娜任务给予者"}}},fp="17,149,22.318.0,25.147.0,35.128.0,38.174.0"}
P.entries["npc:ayessa-dawnsinger"] = {n="Ayessa Dawnsinger",s="艾耶莎·黎明之歌 是一位 天裔 领袖，位于泽风岛的瓦拉纳尔。她领导着塑风者，引导这些与部落结盟的 天裔 应对考验与政治纷争。",h="艾耶莎·黎明之歌 是一位 天裔 领袖，位于泽风岛的瓦拉纳尔。她领导着塑风者，引导这些与部落结盟的 天裔 应对考验与政治纷争。",kw={"阿耶莎","晨歌","部落","天行者","瓦拉纳尔","塑风者","泽弗拉斯"},ang={["faction:Horde"]="对部落而言，Ayessa Dawnsinger 是他们与 Skyborne 之间最主要的合作纽带，巩固着他们在泽风岛的立足点与外交联系。",["race:Skyborne"]="作为塑风者的领袖，Ayessa 体现了那些选择与部落团结一致、以保障自身未来的 Skyborne 的愿景。"},sec={{t="塑风者的领袖",b="艾耶莎·黎明之歌 坐镇泽风岛的瓦拉纳尔聚落，是塑风者的最高领袖——这是与部落结盟的 天裔 派系。她从这里指挥遍及全岛的关键行动，应对外部威胁、内部裂痕，以及族人的整体生存问题，而她的族人也在摸索如何与卡利姆多及更远地区的势力建立同盟。"},{t="泽风 的纷争",b="艾耶莎 在化解岛上冲突的过程中发挥着关键作用，她派遣信赖的勇士处理失控的构造体、洛尔苏娜 这样的敌对人物，以及等待着 天裔 的更大命运。她以权威引领塑风者应对紧张的政治角力与武力冲突，确保他们的声音与力量在部落内部始终受到尊重。"}},faq={{q="艾耶莎·晨歌 是谁？",a="艾耶莎·晨歌 是一位显赫的 天裔 人物，领导着塑风者这一泽风岛上与部落结盟的 天裔 派系。",al={"艾耶莎  背景故事","艾耶莎 是谁","艾耶莎·晨歌 背景"}},{q="在哪里可以找到 艾耶莎·晨歌？",a="她位于泽风岛的瓦拉纳尔聚落。",al={"艾耶莎 在哪里","艾耶莎 位置","艾耶莎·晨歌 地图"}},{q="塑风者是什么组织？",a="塑风者是与部落结盟的 天裔 派系，由 艾耶莎·晨歌 在他们位于瓦拉纳尔的据点中领导。",al={"塑风者派系","塑风者是谁"}},{q="艾耶莎 在当地任务中扮演什么角色？",a="艾耶莎 发布多项关乎岛屿防御的重要任务，包括调查失控的构造体、对抗 洛苏娜，以及决定 泽风 未来的命运。",al={"艾耶莎 任务","艾耶莎 任务线"}}},fx={["53a49c44"]={q="艾耶莎·晨歌支持哪一方？",a="艾耶莎·晨歌坚定地支持部落。作为塑风者的领袖，她统率这支与部落结盟的天裔势力。塑风者以泽风岛上的瓦拉纳尔为据点，由她指挥行动并召集部落勇士追随她。",al={"艾耶莎·晨歌所属阵营","艾耶莎是部落还是联盟","艾耶莎效忠于谁"}},e31c8ea2={q="艾耶莎·晨歌与谁有关联？",a="艾耶莎·晨歌与塑风者关系密切，她领导着这支由部落天裔组成的阵营。她以瓦拉纳尔为据点，协调他们的行动，并在泽风岛各地组织抵抗当地的敌人。",al={"艾耶莎·晨歌的阵营关系","艾耶莎的关系网","艾耶莎与谁共事"}}},fp="17,142,25.301.0,24.318.1,25.84.0,37.59.0,25.109.0,38.155.0"}
P.entries["npc:azar-stronghammer"] = {n="阿扎尔·战锤",s="在卡拉诺斯的雷酒酿制厂，阿扎尔·战锤指引新入门的矮人圣骑士研习圣光之道。训练结束后，他会将有潜力的新兵送往铁炉堡，接受进一步的指导。",h="在卡拉诺斯的雷酒酿制厂，阿扎尔·战锤指引新入门的矮人圣骑士研习圣光之道。训练结束后，他会将有潜力的新兵送往铁炉堡，接受进一步的指导。",kw={"阿扎尔","酿酒厂","丹莫罗","卡拉诺斯","圣骑士","战锤","雷酒","圣洁之书","训练师"},ang={["class:Paladin"]="作为一名从丹莫罗起步的矮人圣骑士，你可以先向阿扎尔学习，再由他指引你前往铁炉堡，取得神圣的圣洁之书。",["race:Dwarf"]="阿扎尔展现了卡兹莫丹的矮人如何信奉圣光。对你而言，对神圣正义的虔诚，与温暖的炉火和一杯雷酒同样属于生活的一部分。"},sec={{t="严寒中的引路人",b="阿扎尔·战锤在丹莫罗冰冷的山坡上，指引刚刚入门的矮人圣骑士。人们常将人类与宏伟的大教堂联系在一起，但卡兹莫丹的矮人也已信奉圣光。阿扎尔已将自己的武艺与信仰誓言融会贯通，如今帮助初学者找到方向。当一名新兵表现出坚定的信念与成熟的心性时，他便会让其沿山路前往铁炉堡，在那里接受蒂萨·热炉等资深勇士的进一步教导。"}},faq={{q="阿扎尔·战锤是谁？",a="阿扎尔·战锤在卡拉诺斯的雷酒酿制厂训练矮人圣骑士。他指导他们完成最初的训练，随后将有潜力的新兵送往铁炉堡深造。",al={"阿扎尔是谁","阿扎尔·战锤的职责","卡拉诺斯圣骑士训练师"}},{q="在哪里能找到阿扎尔·战锤？",a="你可以在丹莫罗白雪覆盖的群山之间，在卡拉诺斯的雷酒酿制厂内找到阿扎尔·战锤。",al={"阿扎尔·战锤的位置","阿扎尔在哪里","寻找阿扎尔·战锤"}},{q="他为年轻的圣骑士提供什么训练？",a="阿扎尔教授初学者圣骑士的基础武艺与法术。当学徒准备好接受圣洁之书的试炼及其神圣的复活仪式时，他便会指引他们前往铁炉堡，寻找蒂萨·热炉。",al={"阿扎尔做什么","阿扎尔任务","阿扎尔圣骑士任务"}},{q="为什么圣骑士训练师会驻留在酿酒厂？",a="雷酒酿制厂将卡拉诺斯的守卫者与导师聚集在一起。在矮人的生活中，履行公民职责、维系情谊都与醇厚的美酒相伴，而这座酿酒厂正是村庄社交生活与防御的中心。",al={"圣骑士为何在酿酒厂","酒馆里的圣骑士","酿酒厂训练师"}}},fx={["38fe723c"]={q="阿扎尔·战锤效忠哪一方？",a="阿扎尔·战锤坚定地支持铁炉堡王国和联盟。作为一名经验丰富的矮人圣骑士，他效忠自己的人民、国王麦格尼·铜须，以及圣光的神圣教义。",al={"阿扎尔·战锤的阵营","阿扎尔·战锤的效忠对象","阿扎尔为谁而战"}},["56baf4f4"]={q="阿扎尔·战锤想要什么？",a="阿扎尔已经完成了自身漫长的圣光修行，如今致力于引导下一代矮人圣骑士。他照看丹莫罗那些前途可期的学徒，确保他们做好准备，再将他们送往铁炉堡，接受蒂萨·热炉等资深训练师的教导。",al={"阿扎尔·战锤的目标","阿扎尔打算做什么","阿扎尔·战锤的目的"}},["132f6bb2"]={q="阿扎尔·战锤与谁有联系？",a="阿扎尔与其他矮人圣骑士保持着密切联系，尤其会与铁炉堡秘法大厅的蒂萨·热炉协作，让有潜力的新学员得到进一步的教导。",al={"阿扎尔·战锤的关系","阿扎尔·战锤的盟友","阿扎尔认识谁"}}},fp="17,194,19.463.0,25.197.0,37.114.0,48.214.0,51.220.0"}
P.entries["npc:azuregos"] = {n="艾索雷葛斯",s="艾索雷葛斯是一头性情古怪的蓝龙，驻守在艾萨拉海岸，保护古代上层精灵的遗物。织法者 玛里苟斯 委托他守护强大的魔法力量。他更喜欢安静地钻研，而非诉诸暴力，但若有冒险者愚蠢到打扰他的守望，他也会毫不犹豫地将其拍开。",h="艾索雷葛斯是一头性情古怪的蓝龙，驻守在艾萨拉海岸，保护古代上层精灵的遗物。织法者 玛里苟斯 委托他守护强大的魔法力量。他更喜欢安静地钻研，而非诉诸暴力，但若有冒险者愚蠢到打扰他的守望，他也会毫不犹豫地将其拍开。",kw={"艾萨拉","艾索雷葛斯","风暴海湾","蓝龙","埃达拉斯","玛里苟斯","节杖碎片","流沙"},ang={["class:Mage"]="作为蓝龙军团的一员，艾索雷葛斯体现着对奥术的掌控与约束。在他眼中，凡人施法者就像鲁莽的孩子，胡乱摆弄着超出自身理解的力量。",["race:NightElf"]="艾索雷葛斯徘徊在埃达拉斯破碎的遗迹之间，警惕地看守着上层精灵的魔法，正是这些魔法在 Sundering 期间险些撕裂了卡利姆多。"},sec={{t="埃达拉斯的守护者",b="艾萨拉充盈魔力的海岸吸引了艾索雷葛斯，他选择了埃达拉斯的古老废墟作为自己的居所。无数遗物在大灾变中幸存，散落在这些支离破碎的海岸上。作为玛里苟斯的仆从，艾索雷葛斯认为，让这些强大的神器远离粗心大意的凡人，是自己的神圣职责。他并不潜伏在幽暗的洞穴里，而是自在地漫步于峭壁与海滩之间，骄傲地自称这片地区一切魔法的主宰。他虽然言语诙谐、喜好讥讽，却会坚决捍卫艾萨拉的宝藏，抵御那些为名声或财宝而源源不断涌来的冒险者。"},{t="不情愿的保管者",b="流沙之战结束后，艾索雷葛斯被迫担起了保管蓝色节杖碎片的重任——那是打破甲虫之墙屏障所需钥匙的一部分。这件神器招来的无尽烦扰、寻宝者和自命不凡的英雄令他深恶痛绝，于是这头聪明的蓝龙最终以一种极其随意的方式丢掉了它：将它喂给了一条名叫巨齿鲨、被赋予了强大力量的小鱼，确保任何想要取得碎片的人都得去深海搜寻，而不是来纠缠他。"}},faq={{q="艾索雷葛斯是谁？",a="艾索雷葛斯是一头强大的蓝龙，受守护巨龙玛里苟斯派遣，巡视艾萨拉的废墟。许多巨龙阴沉寡言或暴躁易怒，艾索雷葛斯却格外古怪而风趣，不过，凡是打断他钻研魔法或觊觎埃达拉斯宝藏的凡人，都会遭到他毫不留情的碾压。",al={"艾索雷葛斯背景故事","艾萨拉的蓝龙是谁","艾索雷葛斯背景"}},{q="艾索雷葛斯为什么在艾萨拉？",a="他来到这里，是为了研究并守护古代上层精灵文明在大灾变后留下的强大奥术神器。他守卫着埃达拉斯的废墟，抵御那些为追寻危险魔法而来的鲁莽掠夺者。",al={"艾索雷葛斯为什么在这里","艾索雷葛斯在艾萨拉做什么","艾索雷葛斯的职责"}},{q="他与甲虫之墙有什么联系？",a="艾索雷葛斯受托保管蓝色节杖碎片，它是能够重新开启甲虫之墙的钥匙的一部分。想知道碎片后来去了哪里，就得与这头巨龙交谈。",al={"艾索雷葛斯节杖碎片","艾索雷葛斯 流沙","流沙 碎片"}},{q="他的灵魂为什么会出现在艾萨拉？",a="艾索雷葛斯之魂出现在艾萨拉，就在活着的艾索雷葛斯附近，并会与旅人交谈。灵魂与巨龙为何能同时存在，始终没有得到解释。",al={"艾索雷葛斯之魂","艾索雷葛斯幽灵","艾索雷葛斯为什么是幽灵"}}},fp="8,193,24.484.0,21.428.1,16.178.0,27.199.0,42.148.1,38.153.0"}
P.entries["npc:bailiff-conacher"] = {n="拜里弗·科纳彻尔",s="在湖畔镇大厅，拜里弗·科纳彻尔在所罗门镇长麾下维护暴风城的法律。他依靠旅人，在战火纷飞的赤脊山各地执行地方法令。",h="在湖畔镇大厅，拜里弗·科纳彻尔在所罗门镇长麾下维护暴风城的法律。他依靠旅人，在战火纷飞的赤脊山各地执行地方法令。",kw={"司法官","科纳彻尔","湖畔镇","莫甘斯","赤脊山","暗皮","所罗门","镇政厅"},ang={["faction:Alliance"]="作为联盟的旅人，你可以在这座几乎只能自力更生的边境小镇，见识暴风城法律所能触及的范围。"},sec={{t="湖畔镇的司法",b="拜里弗·科纳彻尔在湖畔镇大厅与所罗门镇长共事，维护赤脊山各地的法律。黑石兽人和当地的豺狼人围困着镇子，使科纳彻尔无法依靠常规的行政程序或王国驻军。他颁布法令，授权过往旅人以王国之名执行死刑。"},{t="执行所罗门的律法",b="黑暗法师莫甘斯占据伊尔加拉之塔，并迫使当地的暗皮豺狼人听命于他，湖畔镇法庭因此判定这些野兽犯下叛国重罪。根据暴风城的法律，协助逃犯和罪犯者将被处以死刑。科纳彻尔援引所罗门的律法，派遣旅人翻越山岭，寻找暗皮豺狼人，并带回它们的坠饰，以证明王国的法律已得到执行。"}},faq={{q="拜里弗·科纳彻尔是谁？",a="拜里弗·科纳彻尔效力于湖畔镇法庭，协助所罗门镇长在赤脊山维护地方政权与暴风城的法律。",al={"拜里弗·科纳彻尔职责","科纳彻尔是谁","科纳彻尔背景故事"}},{q="在哪里可以找到拜里弗·科纳彻尔？",a="你可以在赤脊山桥北侧的湖畔镇大厅内找到拜里弗·科纳彻尔。",al={"拜里弗·科纳彻尔位置","科纳彻尔在哪里","科纳彻尔 赤脊山"}},{q="什么是所罗门的律法？",a="所罗门的律法依据所罗门镇长的法令执行暴风城的法律。协助莫甘斯这样的在逃巫师及其他已知罪犯者将被判处死刑，因此与他结盟的暗皮豺狼人也将面临处决。",al={"什么是所罗门的律法","所罗门的律法 豺狼人","暗皮法律"}},{q="科纳彻尔为什么要收集暗皮坠饰？",a="这些坠饰证明，暗皮豺狼人已依照湖畔镇对莫甘斯帮凶作出的判决被处死。",al={"为什么收集坠饰","暗皮坠饰用途"}}},fx={["6ce891cc"]={q="拜里弗·科纳彻尔支持哪一方？",a="拜里弗·科纳彻尔为联盟效力，直接听命于湖畔镇的所罗门镇长。作为赤脊山法庭的官员，他的职责是维护暴风城的法律，并保护当地居民免受日益逼近的威胁。",al={"科纳彻尔效忠于谁","科纳彻尔为谁效力","科纳彻尔是否属于联盟"}},["5d999432"]={q="拜里弗·科纳彻尔想要什么？",a="科纳彻尔致力于维护湖畔镇的法律并保护赤脊山。叛逃法师摩根特招募了当地的暗皮豺狼人，治安官于是招募有本领的冒险者惩治这些豺狼人，并遏制黑暗法师的势力。",al={"科纳彻尔的目标","拜里弗·科纳彻尔需要什么"}},["8124ae86"]={q="拜里弗·科纳彻尔为什么在湖畔镇？",a="科纳彻尔驻扎在湖畔镇市政厅，担任镇上的治安官。他与所罗门镇长并肩工作，协助处理地方事务、维护公正，并在暴风城无力派遣援军支援此地时管理城镇防务。",al={"科纳彻尔为什么在赤脊山","科纳彻尔与湖畔镇市政厅"}},df8ac9aa={q="拜里弗·科纳彻尔与谁有关联？",a="科纳彻尔是湖畔镇法庭的一员，直接听命于所罗门镇长。他与镇上的官员和当地卫兵密切合作，抵御外来侵略者，维护聚居地的秩序。",al={"科纳彻尔的盟友","科纳彻尔与谁共事"}}},fp="16,166,20.336.0,22.404.0,24.143.0,36.116.0,22.210.0,46.121.0"}
P.entries["npc:bailor-stonehand"] = {n="白洛尔·石手",s="在塞尔萨玛，白洛尔·石手正等着那批被莫格罗什食人魔抢走的矿石。这位技艺精湛的矮人铁匠能打造用于制作精良武器装备的特殊合金，还曾教导过人类武器匠乔丹·斯迪威尔。",h="在塞尔萨玛，白洛尔·石手正等着那批被莫格罗什食人魔抢走的矿石。这位技艺精湛的矮人铁匠能打造用于制作精良武器装备的特殊合金，还曾教导过人类武器匠乔丹·斯迪威尔。",kw={"白洛尔·石手","乔丹·斯迪威尔","洛克莫丹","莫格罗什","铁匠","塞尔萨玛","维里甘之拳"},ang={["class:Paladin"]="身为圣骑士，你所沿用的工艺源自白洛尔对乔丹·斯迪威尔的传授。他的特殊合金配方被用于打造圣锤维里甘之拳。",["profession:Blacksmithing"]="身为铁匠，你能看出白洛尔对稀有而坚韧的金属的追求。他的特殊合金闻名于整个卡兹莫丹。"},sec={{t="熔炉大师",b="白洛尔·石手在塞尔萨玛照看熔炉。他对矿物和特殊合金的学识远播卡兹莫丹之外。他曾传授乔丹·斯迪威尔冶金的基础知识，并分享了用于打造维里甘之拳等受祝福的圣骑士武器装备的配方。"},{t="食人魔伏击",b="塞尔萨玛东北方山丘中的莫格罗什食人魔抢走了运往白洛尔熔炉的矿石。没有原料，他就无法冶炼稀有合金。他需要旅人和盟友从食人魔的营地中夺回物资。"}},faq={{q="白洛尔·石手是谁？",a="白洛尔·石手是洛克莫丹塞尔萨玛的一位资深矮人铁匠。他冶炼稀有的金属合金，还曾传授乔丹·斯迪威尔武器锻造技艺。",al={"白洛尔·石手","白洛尔是谁","塞尔萨玛铁匠"}},{q="白洛尔与乔丹·斯迪威尔有什么关系？",a="白洛尔曾教导铁炉堡附近的人类铁匠乔丹·斯迪威尔如何加工精炼矿石。他还教会了他冶炼一种特殊合金，用于打造神圣战锤维里甘之拳。",al={"白洛尔与乔丹","乔丹·斯迪威尔的老师","维里甘之拳铁匠"}},{q="白洛尔的矿石出了什么事？",a="洛克莫丹东北部丘陵中的莫格罗什食人魔拦截并抢走了运给白洛尔的一批原矿。他因此没有材料进行特殊的金属锻造。",al={"白洛尔的矿石货物","谁抢走了白洛尔的矿石","食人魔货物"}},{q="在哪里可以找到白洛尔·石手？",a="白洛尔就在塞尔萨玛的中心附近，这座城镇是洛克莫丹主干道沿线最主要的矮人城镇。",al={"白洛尔的位置","白洛尔·石手在哪里","白洛尔塞尔萨玛"}}},fx={["0eb0f83a"]={q="白洛尔·石手效忠哪一方？",a="白洛尔·石手坚定地支持铁炉堡和联盟。他与同胞一起住在塞尔萨玛，凭借手艺支持当地的矮人城镇，并帮助途经此地的联盟冒险者，尤其是寻求他冶金技艺帮助的圣骑士，共同抵御敌对势力对王国的威胁。",al={"白洛尔·石手的阵营","白洛尔是否属于联盟","白洛尔支持哪一方"}},a41b979c={q="白洛尔·石手想要什么？",a="白洛尔希望不受打扰地从事锻造，但他最关心的是找回贵重的原材料。莫格罗什食人魔袭击并抢走了他最近运来的一批矿石，因此，他正在寻找有本领的旅人，前往食人魔的领地取回遗失的货物。",al={"白洛尔想要什么","白洛尔·石手的目标","白洛尔的动机"}},["346dae44"]={q="白洛尔·石手为什么在塞尔萨玛？",a="白洛尔住在塞尔萨玛，经营自己的熔炉，为这处定居点提供精良的矮人金属制品。这座城镇靠近洛克莫丹的矿井与崎岖山地，是经验丰富的铁匠理想的落脚之地，尽管当地食人魔的袭击偶尔会妨碍他的物资供应。",al={"白洛尔为什么在这里","白洛尔为什么在洛克莫丹","白洛尔为什么在塞尔萨玛"}}},fp="16,212,19.252.0,11.237.0,24.153.0,47.164.0,30.150.0,36.101.0"}
P.entries["npc:baine-bloodhoof"] = {n="贝恩·血蹄",s="在血蹄村，贝恩·血蹄守护着他的族人和莫高雷。凯恩在雷霆崖领导族人，贝恩则指挥当地的防御，抵御豺狼人和外来威胁。",h="在血蹄村，贝恩·血蹄守护着他的族人和莫高雷。凯恩在雷霆崖领导族人，贝恩则指挥当地的防御，抵御豺狼人和外来威胁。",kw={"贝恩","血蹄","血蹄村","凯恩","半人马","基拉格","莫高雷","白鬃","雷克萨","雷霆崖"},ang={["class:Shaman"]="贝恩将大地之灵放在首位。他派旅人让矮人的机器和肆意妄为的矿工停下来，以免他们的挖掘进一步伤害大地之灵。",["faction:Horde"]="贝恩为萨尔的部落带来沉稳的智慧和内敛的武勇，指引着途经莫高雷中部的人们。",["race:Tauren"]="贝恩承袭着High Chieftain凯恩的荣耀血脉，也承载着聚居于莫高雷平原各处的年轻部族的希望。"},sec={{t="大酋长之子",b="贝恩·血蹄是凯恩的儿子，从小随游牧的族人四处迁徙。他们在莫高雷的草原定居，但半人马氏族依然构成威胁。第三次大战之后，基拉格的战团俘虏了贝恩，悲痛让凯恩几乎无力领导这些新建的聚落。雷克萨救出了被囚禁的贝恩。这次营救让凯恩重振精神，牛头人与萨尔的部落并肩对抗入侵的库尔提拉斯人，在这片大陆上站稳了脚跟。"},{t="血蹄村的守护者",b="贝恩与族人一同住在血蹄村，而非都城的台地之上。随着凯恩日渐年迈，贝恩肩负起更多照顾族人的责任，也代表着牛头人的新一代领袖。他指挥勇士和来访的盟友对抗侵扰边境的白鬃豺狼人，也时刻留意威胁莫高雷自然平衡的外来势力。"},{t="守护大地母亲",b="贝恩面对的侵占者，几乎不顾灵性的平衡。在莫高雷东部，地精经营的荆棘谷地精正在破坏这片神圣的土地。来自巴尔莫丹的矮人勘探者在巴尔丹挖掘场挖掘先祖的土地。贝恩主张采取坚定而有分寸的应对：警告矿工并摧毁他们的设备，而非贸然引发无谓的流血。他说，他们粗暴的挖掘伤害了大地之灵，矿工们却不肯听从。"}},faq={{q="贝恩·血蹄是谁？",a="贝恩·血蹄是凯恩·血蹄的独子。他在血蹄村负责防御和部族事务，指挥当地勇士并保护莫高雷，而他的父亲则在雷霆崖统领族人。",al={"贝恩的故事","贝恩是谁","凯恩的儿子"}},{q="现在可以在哪里找到贝恩？",a="贝恩位于莫高雷中部的血蹄村，就在雷霆崖以南。他在村子中心附近，为初来乍到的冒险者安排任务。",al={"贝恩位置","贝恩在哪里","贝恩·血蹄所在地"}},{q="贝恩是如何从半人马手中获救的？",a="第三次大战之后，奇拉格俘虏了贝恩，让凯恩陷入绝望，难以振作。雷克萨向伯文·风之图腾率领的流亡者寻求帮助，追踪半人马来到他们的营地，杀死了囚禁贝恩的敌人，将他平安送回父亲身边。",al={"贝恩遭绑架","雷克萨营救贝恩","贝恩被俘"}},{q="贝恩在血蹄村处理哪些问题？",a="贝恩统筹应对骚扰当地兽群的白鬃豺狼人。他也监视外来入侵者，包括地精经营的荆棘谷地精，以及破坏大地的联盟矮人挖掘者。",al={"贝恩任务","贝恩做什么","血蹄村的麻烦"}},{q="贝恩对巴尔丹的矮人挖掘场持什么态度？",a="贝恩认为，巴尔丹矿工粗暴的挖掘伤害了大地之灵，亵渎了这片土地。他派旅人夺取并砸毁他们的工具，希望吓退矿工，让他们明白，挖空大地并不是求知之道。",al={"贝恩与矮人","巴尔丹采矿","莫高雷矮人挖掘场"}},{q="贝恩会接替凯恩成为大酋长吗？",a="身为凯恩的儿子，贝恩随着父亲日渐年迈，在领导牛头人的事务中承担着更重要的职责。许多人视他为联合各部族的当然继承人。",al={"贝恩会成为领袖吗","未来的大酋长","凯恩的继承人"}}},fp="15,181,25.445.0,29.369.0,26.453.0,23.195.0,35.149.0,39.247.0,53.198.0,55.252.0,44.149.0"}
P.entries["npc:balir-frosthammer"] = {n="巴尔林·霜锤",s="在寒脊山谷，巴尔林·霜锤召集新兵，应对正向矮人领地进逼的石腭穴居人。",h="在寒脊山谷，巴尔林·霜锤召集新兵，应对正向矮人领地进逼的石腭穴居人。",kw={"新的威胁","巴尔林·霜锤","寒脊山谷","丹莫罗","石腭穴居人","塔诺克·霜锤"},ang={["faction:Alliance"]="身为联盟新兵，你在卡兹莫丹接受训练，而巴尔林则努力确保寒脊山谷的安全，让这里能够作为集结地。",["race:Dwarf"]="身为矮人，你可以帮助巴尔林·霜锤抵御来自地下的威胁，保卫家园。他的号召让你在初入征途时，就有机会守护丹莫罗。"},sec={{t="守住寒脊山谷",b="巴尔林·霜锤号召新兵保卫寒脊山谷。长久以来，矮人和侏儒的新兵都在这里寻求庇护，接受训练。但地下的变故将凶暴的石腭穴居人逼到了地表。巴尔林是最早发出警报的人之一，他敦促新兵削减它们的数量，阻止它们进一步深入丹莫罗。"},{t="霜锤家族的亲缘",b="巴尔林·霜锤与卡拉诺斯的塔诺克·霜锤拥有相同的姓氏。两人可能出自同一个家族，家族成员都支持铁炉堡。随着威胁在整个地区蔓延，他们协力守护寒冷的山间隘口，保障旅人、矿工和巡山人的安全。"}},faq={{q="巴尔林·霜锤是谁？",a="巴尔林·霜锤守卫着丹莫罗的寒脊山谷。他号召前来报到的新兵削减敌对的石腭穴居人的数量，这些敌人正威胁着山谷的防线。",al={"巴尔林·霜锤是谁","巴尔林是谁"}},{q="巴尔林为何担忧穴居人？",a="石腭 穴居人最近大批涌上地表，扰乱寒脊山谷，袭击矮人定居点。巴尔林看出危险正在加剧，必须及早遏制。",al={"为何担忧穴居人","寒脊山谷穴居人问题"}},{q="巴尔林与塔诺克·霜锤有亲缘关系吗？",a="有可能。巴尔林与卡拉诺斯的塔诺克·霜锤都姓霜锤，这表明他们可能有亲缘关系，但尚未得到证实。",al={"塔诺克的亲属","霜锤家族"}}},fx={c02dfef8={q="巴尔林·霜锤效忠哪一方？",a="巴尔林坚定地支持铁炉堡和联盟。他驻守在寒脊山谷，关切着矮人家园的安全，与其他巡山人和新兵并肩作战，保护丹莫罗免受新出现的危险威胁。",al={"巴尔林·霜锤的阵营","巴尔林为谁效力","巴尔林是否属于联盟"}},["14c400d2"]={q="巴尔林·霜锤想要什么？",a="巴尔林想要击退那些开始在山谷中肆虐的石腭穴居人。它们突然出现并发动攻击，让他深感不安，于是他招募身强力壮的冒险者，赶在这些入侵者占领寒脊之前削减它们的数量。",al={"巴尔林·霜锤的动机","巴尔林需要什么","巴尔林为什么需要帮助"}}},fp="17,99,24.334.0,23.263.0,25.156.0,40.168.0,39.142.0"}
P.entries["npc:balthule-shadowstrike"] = {n="巴苏尔·影击",s="巴苏尔·影击在奥萨拉克斯之塔附近监视着黑海岸北部的海岸。他是净化者德尔格伦麾下的前哨斥候，密切留意着古老精灵废墟中的黑暗施法者。",h="巴苏尔·影击在奥萨拉克斯之塔附近监视着黑海岸北部的海岸。他是净化者德尔格伦麾下的前哨斥候，密切留意着古老精灵废墟中的黑暗施法者。",kw={"奥萨拉克斯","巴苏尔","邪教徒","黑海岸","德尔格伦","玛塞斯特拉","净化者","斥候","影击"},ang={["class:Rogue"]="身为潜行者，你深知在危险施法者的眼皮底下深入敌境，需要怎样的耐心与警觉。作为一名精灵斥候，巴苏尔展现了这些品质。",["faction:Alliance"]="作为从奥伯丁被派往北方的联盟成员，你可以找到巴苏尔，由他担任前线联络人，对抗奥萨拉克斯之塔周围的黑暗邪教徒。",["race:NightElf"]="身为暗夜精灵，邪教徒亵渎卡利姆多古老废墟的行径或许会让你愤怒。巴苏尔力图在腐化进一步蔓延到你的领地之前，为此复仇。"},sec={{t="暗影中的斥候",b="在奥萨拉克斯之塔以西，巴苏尔·影击独自执行着危险的监视任务。黑海岸北部遍布不安的灵魂和阴影笼罩的废墟，但这座高塔带来的威胁尤为严重。在净化者德尔格伦的指示下，巴苏尔监视着进入古老上层精灵废墟的黑暗施法者。"},{t="揭开邪教的秘密",b="奥萨拉克斯之塔中的巫师和邪教徒研习禁忌魔法，从附近的废墟中搜集神器与灵魂。巴苏尔向途经此地的联盟勇士求助，请他们打击邪教首领，夺回羊皮纸和护符，以查明这些人的召唤活动波及多远。"}},faq={{q="巴苏尔·影击是谁？",a="巴苏尔·影击在黑海岸北部执行侦察任务。他与净化者德尔格伦合作，监视那里的邪教徒。",al={"巴苏尔是谁","巴苏尔的职责","巴苏尔·影击 非玩家角色"}},{q="巴苏尔·影击在哪里？",a="巴苏尔·影击就在黑海岸北部的奥萨拉克斯之塔以西，靠近海岸的地方。",al={"巴苏尔在哪","巴苏尔的位置","寻找巴苏尔·影击"}},{q="他在奥萨拉克斯之塔的任务是什么？",a="巴苏尔受命监视奥萨拉克斯之塔中的黑暗施法者和邪教徒。他搜集情报，并协调针对他们仪式的打击行动。",al={"巴苏尔为何在此","巴苏尔想要什么","奥萨拉克斯任务人物"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是驻守在灰谷迈斯特拉岗哨的一名人类圣骑士。他协调着对抗黑海岸北部黑暗势力的行动，巴苏尔则是他在前方的耳目。",al={"德尔格伦是谁","巴苏尔的上级","与德尔格伦的关系"}},{q="哪些敌人占据着奥萨拉克斯之塔？",a="黑暗邪教徒和巫师占据着奥萨拉克斯之塔及其周边，还有他们召唤出的恶魔或暗影仆从。他们企图利用上层精灵的古老力量达成邪恶目的。",al={"塔里有谁","奥萨拉克斯的敌人","奥萨拉克斯之塔邪教徒"}},{q="联盟为何关注这些废墟？",a="奥萨拉克斯之塔是一座古老的精灵建筑。邪恶巫术和恶魔活动离精灵领地如此之近，威胁着黑海岸和达纳苏斯的暗夜精灵。",al={"为何关注这座塔","联盟在黑海岸的势力"}}},fp="21,179,22.310.0,19.294.1,29.104.0,39.103.0,46.160.0,28.190.0,51.182.0,46.160.0"}
P.entries["npc:barithras-moonshade"] = {n="巴瑞萨斯·月影",s="在奥伯丁，巴瑞萨斯·月影正关注着黑海岸荒野中稀有的地下植物。这位暗夜精灵正在寻找愿意探索这片幽暗土地并采集这些植物的旅行者。",h="在奥伯丁，巴瑞萨斯·月影正关注着黑海岸荒野中稀有的地下植物。这位暗夜精灵正在寻找愿意探索这片幽暗土地并采集这些植物的旅行者。",kw={"奥伯丁","巴瑞萨斯","洞穴蘑菇","黑海岸","毒帽蘑菇","月影","安努"},ang={["profession:Herbalism"]="你与植物生命心意相通，或许能理解巴瑞萨斯为何对黑海岸洞穴中那些奇特的真菌感兴趣。",["race:NightElf"]="身为暗夜精灵，你可以通过观察当地植物，并与安努这样的古老森林守护者保持联系，帮助奥伯丁的同胞守护黑海岸。"},sec={{t="奥伯丁的居民",b="巴瑞萨斯·月影守望着奥伯丁，协助暗夜精灵研究和管理黑海岸。他派遣旅行者前往附近的洞穴，采集包括毒帽蘑菇在内的真菌，以供研究和使用。"},{t="与古树的联系",b="巴瑞萨斯还会指引有能力的旅行者南下拜访安努。这位古树致力于净化黑海岸遭到污染的土壤，安抚那里躁动不安的自然之灵。"}},faq={{q="巴瑞萨斯·月影是谁？",a="巴瑞萨斯·月影是居住在奥伯丁的一名暗夜精灵，他请旅行者调查当地的植物，并与这一地区的守护者取得联系。",al={"巴瑞萨斯 是谁","巴瑞萨斯·月影","这个暗夜精灵是谁"}},{q="在哪里可以找到巴瑞萨斯·月影？",a="在黑海岸沿岸的港口聚落奥伯丁，可以找到巴瑞萨斯·月影。",al={"巴瑞萨斯 位置","巴瑞萨斯 在哪里","巴瑞萨斯·月影位置"}},{q="巴瑞萨斯会交付什么任务？",a="巴瑞萨斯会派遣旅行者前往附近的洞穴，采集毒帽蘑菇等真菌，然后指引他们南下拜访安努。",al={"巴瑞萨斯 任务","巴瑞萨斯 交付什么任务","洞穴蘑菇任务"}},{q="巴瑞萨斯与其他姓月影的人有亲属关系吗？",a="没有关于巴瑞萨斯亲属的记载，因此他与其他姓月影的暗夜精灵是否有亲属关系，尚不得而知。",al={"月影 家族","其他姓 月影 的人","巴瑞萨斯 与哨兵 月影 有亲属关系吗"}}},fp="19,106,21.203.0,20.152.0,27.113.0,37.90.0,31.129.0,45.99.0"}
P.entries["npc:barkeep-daniels"] = {n="酒吧老板丹尼尔",s="道路虽受袭扰，酒吧老板丹尼尔仍在湖畔镇旅店为客人供应酒水。聚在这里的镇卫兵、渔夫和旅人都靠这间旅店获得片刻喘息，但存货已所剩无几。",h="道路虽受袭扰，酒吧老板丹尼尔仍在湖畔镇旅店为客人供应酒水。聚在这里的镇卫兵、渔夫和旅人都靠这间旅店获得片刻喘息，但存货已所剩无几。",kw={"酒吧老板丹尼尔","酒保","丹尼尔","旱季","湖畔镇旅店","赤脊山旅店老板"},ang={["faction:Alliance"]="对联盟而言，维持湖畔镇的士气至关重要。这座饱受摧残的城镇是王国抵御北方黑石要塞威胁的缓冲地带。"},sec={{t="为湖畔镇振奋精神",b="酒吧老板丹尼尔在桥边的湖畔镇旅店斟酒迎客。数月来，豺狼人和黑石兽人不断威胁着湖畔镇，守卫们结束艰苦的巡逻后，便到酒馆里歇息。袭击与道路阻断扰乱了整个地区的贸易。镇上正需要美酒振奋人心，酒却快喝光了，因此丹尼尔欢迎愿意从较安全的定居点运来酒水的旅人。"}},faq={{q="酒吧老板丹尼尔是谁？",a="酒吧老板丹尼尔在湖畔镇旅店照看柜台，为镇民、旅人和镇卫兵供应酒水。",al={"丹尼尔 赤脊山","湖畔镇 酒吧老板","丹尼尔是谁"}},{q="他的酒为什么快用完了？",a="黑石兽人和豺狼人的袭击阻断了进入赤脊山的商队与贸易路线。货物无法送达，压力重重的守卫们又不断消耗着存酒，丹尼尔很难补足货架上的酒水。",al={"为什么没酒了","旱季任务背景","为什么没有酒"}},{q="他需要什么帮助？",a="丹尼尔需要旅人从赤脊山以外带来新的酒水，好让旅店继续招待客人。",al={"酒吧老板丹尼尔任务","他想要什么","丹尼尔的差事"}}},fx={["2f43c9bf"]={q="酒吧老板丹尼尔站在哪一方？",a="酒吧老板丹尼尔是忠诚的联盟公民，也是湖畔镇的一员。他在湖畔镇旅店柜台后为当地居民、访客和驻防守军服务；面对日益严重的黑石威胁，他坚定地支持暴风王国。",al={"酒吧老板丹尼尔的阵营","酒吧老板丹尼尔是联盟成员吗","丹尼尔在赤脊山效忠于谁"}}},fp="15,182,33.405.0,23.107.0,32.215.0,28.108.0"}
P.entries["npc:baron-aquanis"] = {n="阿奎尼斯男爵",s="暮光之锤盘踞在黑暗深渊，阿奎尼斯男爵则从其中被水淹没的月光神殿废墟中现身。有人扰动深渊之石时，他便会出现，而大地之环怀疑他遭到了这个教派的腐化。",h="暮光之锤盘踞在黑暗深渊，阿奎尼斯男爵则从其中被水淹没的月光神殿废墟中现身。有人扰动深渊之石时，他便会出现，而大地之环怀疑他遭到了这个教派的腐化。",kw={"阿奎尼斯","阿奎尼斯男爵","黑暗深渊","大地之环","深渊之核","深渊之石","耶努萨克雷","暮光之锤","水元素"},ang={["class:Shaman"]="对大地之环的萨满祭司而言，阿奎尼斯男爵是元素遭到扭曲的悲剧例证。他被污染的残骸能为净化扭曲的灵体提供线索。",["faction:Horde"]="耶努萨克雷在灰谷海岸与部落合作。他的部落助手取回的深渊之核，将用于揭示暮光之锤在那里对元素的所作所为。"},sec={{t="深渊之石的守护者",b="深渊之石位于月光神殿废墟被水淹没的殿堂之下，就在占据此地的暮光之锤教徒眼皮底下。石中藏着一枚深渊之核，只要正确解读这件装置，就能了解附近元素活动的历史。大地之环的耶努萨克雷派部落冒险者前去取回它。扰动这块石头，就会引出深处的阿奎尼斯男爵。"},{t="深处的腐化",b="大地之环一直认为，阿奎尼斯男爵是一股遭到腐化的元素力量。他被消灭后，会留下一颗奇怪的水球，那是一颗坚不可摧的球体，里面盛着不断晃荡的腐臭之水，似乎曾为他提供能量。耶努萨克雷认为，这颗水球或许能证明是什么腐化了男爵，以及腐化是如何发生的。如果幕后黑手是暮光之锤，他也不会感到意外。"}},faq={{q="在哪里能找到阿奎尼斯男爵？",a="阿奎尼斯男爵栖身于黑暗深渊深处被水淹没的月光神殿废墟。有人扰动水下的深渊之石时，他便会从水中现身，部落冒险者为耶努萨克雷取回其中的深渊之核时就会如此。",al={"阿奎尼斯位置","阿奎尼斯男爵在哪里","如何召唤阿奎尼斯男爵"}},{q="奇怪的水球是什么？",a="奇怪的水球是阿奎尼斯男爵被消灭后留下的东西。这颗坚不可摧的球体中盛着不断晃荡的腐臭之水，似乎曾滋养他的元素能量。大地之环的耶努萨克雷想研究它，寻找证据，查明是什么腐化了男爵，以及腐化是如何发生的。",al={"奇怪的水球","阿奎尼斯水球","水球有什么用"}},{q="大地之环为何关注阿奎尼斯男爵？",a="大地之环守护着元素的平衡。耶努萨克雷和他的同伴一直认为，阿奎尼斯男爵是一股遭到腐化的元素力量。暮光之锤盘踞在月光神殿废墟，他们担心这个教派可能正在胁迫元素对抗部落。男爵的残骸和深渊之核或许能揭示这个教派的所作所为。",al={"大地之环为何关注","耶努萨克雷 阿奎尼斯"}},{q="深渊之核是什么？",a="深渊之核是一件元素神器，藏在沉入水中的深渊之石内。受过训练的萨满祭司若能正确解读它，就能全面了解当地元素活动的历史，还能揭露暮光之锤在废墟中进行的任何黑暗仪式。",al={"深渊之核背景","深渊之核有什么用"}},{q="阿奎尼斯男爵与暮光之锤是盟友吗？",a="据目前所知，阿奎尼斯男爵是一个遭到腐化的元素，而非自愿效命的仆从。占据月光神殿废墟的暮光之锤教徒显然最有嫌疑。耶努萨克雷说，即使他们牵涉其中，他也不会意外，但他想先找到证据，再下定论。",al={"阿奎尼斯属于暮光之锤吗","阿奎尼斯教派"}},{q="联盟与阿奎尼斯男爵有什么瓜葛吗？",a="没有直接的瓜葛。深渊之石和阿奎尼斯男爵是耶努萨克雷关注的事。他是大地之环的萨满祭司，在灰谷海岸与部落合作，并派部落冒险者去取回深渊之核。黑暗深渊中的联盟探索者另有任务。",al={"联盟能打阿奎尼斯吗","联盟阿奎尼斯任务"}}},fp="13,234,28.355.0,24.370.1,31.220.0,32.264.0,52.357.0,24.231.0,51.276.0,51.276.0"}
P.entries["npc:baron-revilgaz"] = {n="大财主里维加兹",s="大财主里维加兹是藏宝海湾与黑水海盗的狡猾地精首领，代表热砂港统治着这处海盗天堂。他坐镇水手之家旅店高处的阳台，在脆弱的贸易中立与冷酷务实的投机手段之间维持平衡。他雇用过往的雇佣兵保护自己的投资，打击血帆海盗等对手，并寻回丛林中的古代遗物。",h="大财主里维加兹是藏宝海湾与黑水海盗的狡猾地精首领，代表热砂港统治着这处海盗天堂。他坐镇水手之家旅店高处的阳台，在脆弱的贸易中立与冷酷务实的投机手段之间维持平衡。他雇用过往的雇佣兵保护自己的投资，打击血帆海盗等对手，并寻回...",kw={"黑水海盗","血帆海盗","藏宝海湾","纳菲瑞提湖","里维加兹","水手之家旅店","卡拉·海角","热砂港","海潮之石"},ang={["class:Rogue"]="里维加兹看重盗贼、间谍和投机者。他经常雇用潜行者执行风险极高的盗窃任务，破坏竞争财团的业务，并秘密取回丛林中的稀有文物。",["faction:Alliance"]="藏宝海湾建在黑水湾的废墟之上，那里曾是第一次战争前暴风城的一处聚居地，而每当古老知识能带来利润时，里维加兹都会照例与暴风城的人类学者和图书管理员合作。",["profession:Engineering"]="里维加兹始终参与着地精工程学的竞争，利用卑劣手段从荆棘谷地精手中获取先进的蓝图和燃料调节器。"},sec={{t="藏宝海湾之主",b="大财主里维加兹在水手之家旅店顶端的高处，用一架特制的附魔望远镜观察黑水湾繁忙的码头。在他身旁的是备受信任的顾问，牛头人舰队指挥官卡拉·海角，里维加兹牢牢掌控着镇上的扒手、商人和私掠者。这座港口最初是一处人类定居点，在第一次战争前被巨魔攻陷，后来被地精占据并加固，最终发展为黑水海盗偏向海盗势力的商业枢纽。里维加兹确保港口在名义上始终向联盟和部落的旅人开放，并在港区内严格执行中立政策，让贸易得以持续进行。"},{t="野心之网",b="里维加兹的影响力远不止于港口码头。当艾泽拉斯其他地方近来的战事导致生意停滞时，他抓住发现可口鱼的机会，创办了荆棘谷钓鱼大赛，将人群重新吸引到自己的海岸。在荆棘谷各处，他密切关注着竞争者与潜在威胁：他委托他人破坏纳菲瑞提湖一带荆棘谷地精的业务，严密监视奈辛瓦里的狩猎远征队和北方脱离管束的人类军营，并与沙漠赛道的蒙特·加兹鲁维和普兹克保持赛车贸易往来。"},{t="海潮之石",b="里维加兹商人身份的背后，是对古代力量与财富的痴迷。为了调查近海一座闹鬼岛屿的传闻，里维加兹派遣冒险者寻找传说中的海潮之石。这场搜寻需要查阅暴风城图书馆中的古籍，与大法师安斯雷姆·鲁因维沃尔一同研究元素残留物，并从血帆海盗手中夺回一把古老的巨魔匕首，以摧毁海岸上庇护宝石的祭坛。里维加兹借此破除了致命的元素诅咒，将这件无价遗物收入自己的宝库。"}},faq={{q="大财主里维加兹是谁？",a="大财主里维加兹是藏宝海湾的统治者，也是黑水海盗的首领。他代表中立的热砂港行事，以冷酷的贪婪和务实的外交手腕治理着这处海盗天堂。",al={"里维加兹是谁","里维加兹背景故事","藏宝海湾首领","藏宝海湾领袖"}},{q="在哪里可以找到大财主里维加兹？",a="他站在藏宝海湾水手之家旅店的顶层阳台上，与备受信任的顾问舰队指挥官卡拉·海角一同俯瞰海湾。",al={"里维加兹在哪里","里维加兹位置","如何找到里维加兹"}},{q="里维加兹与血帆海盗是什么关系？",a="他们是死敌。血帆海盗不受热砂港的规矩约束，还频繁劫掠藏宝海湾的航运船只。事实上，血帆海盗的头目们经常密谋暗杀里维加兹和卡拉·海角。",al={"里维加兹 血帆海盗","血帆海盗对抗里维加兹","为何仇恨血帆海盗"}},{q="里维加兹在沙漠赛道有什么利益？",a="里维加兹资助普兹克率领的地精赛车队，在闪光平原与侏儒较量。他利用冒险者从纳菲瑞提湖的荆棘谷地精手中窃取专有的燃料调节器的蓝图，并将其送往赛道。",al={"里维加兹赛车","里维加兹 闪光平原","里维加兹 波兹克"}},{q="荆棘谷钓鱼大赛是什么？",a="当艾泽拉斯其他地区的战事导致贸易衰退时，里维加兹在品尝了当地的“可口鱼”后，开始资助一位名叫林格·巴斯贝特的钓鱼人。里维加兹以这种渔获为契机，在荆棘谷沿岸举办每周一次的钓鱼竞赛，以重振藏宝海湾的经济。",al={"钓鱼大赛背景故事","谁创办了钓鱼比赛","可口鱼 里维加兹"}},{q="海潮之石是什么？",a="它是一块古老而受诅咒的魔法石，藏在暗礁海。里维加兹从暴风城的文献中发掘出它的传说，并雇用达拉然学者大法师安斯雷姆·鲁因维沃尔，帮助冒险者解除它的元素结界，取得这件遗物。",al={"海潮之石任务","暗礁海宝石","海潮祭坛"}}},fp="14,298,19.536.0,17.507.0,22.504.1,22.151.0,34.166.0,62.180.0,47.229.0,47.262.0,31.238.1"}
P.entries["npc:baron-silverlaine"] = {n="席瓦莱恩男爵",s="席瓦莱恩男爵的灵魂徘徊在焚木村上方的大厅。他曾统治席瓦莱恩城堡，直到大法师阿鲁高将狼人放入这片地区，他也惨遭狼人杀害。",h="席瓦莱恩男爵的灵魂徘徊在焚木村上方的大厅。他曾统治席瓦莱恩城堡，直到大法师阿鲁高将狼人放入这片地区，他也惨遭狼人杀害。",kw={"阿鲁高","男爵","幽灵","大厅","城堡","焚木村","暗影之牙","席瓦莱恩","狼人"},ang={["class:Mage"]="对法师而言，席瓦莱恩的命运警示着滥用魔法的后果。大法师阿鲁高不当运用召唤之术，毁掉了无辜者的生命，留下了难以磨灭的创伤。",["race:Human"]="对人类而言，席瓦莱恩的命运标志着吉尔尼斯边境人类贵族统治的衰落。一名在达拉然受训的巫师肆意施法，导致他的城堡陷落。",["race:Undead"]="对穿越银松森林的被遗忘者而言，席瓦莱恩的幽灵又是一处旧贵族势力的残余。只有将其清除，他们才能打破阿鲁高对城堡的控制。"},sec={{t="席瓦莱恩 城堡的陷落",b="席瓦莱恩男爵统治着银松森林南部丘陵中的一处贵族领地。他的城堡守卫着周边土地，保一方平安。大法师阿鲁高召唤狼人对抗肆虐的天灾军团，并将它们放入这片地区，这份安宁就此终结。这些凶残的野兽无法控制。它们冲入城堡，击溃守卫，残杀了男爵。"},{t="受折磨的幽灵",b="席瓦莱恩男爵依然被束缚在城堡古老的大厅中。他不安的幽魂徘徊在破损的餐桌之间，那里曾是他设宴欢宴的地方。这位受诅咒的领主会攻击闯入他昔日家园的人。"}},faq={{q="席瓦莱恩男爵生前是什么人？",a="席瓦莱恩男爵曾统治席瓦莱恩城堡，这座城堡坐落在焚木村上方。狼人攻陷了城堡，并杀死了他。",al={"席瓦莱恩男爵背景故事","席瓦莱恩是谁","谁曾统治暗影之牙"}},{q="他为何在影牙城堡徘徊？",a="大法师阿鲁高放出的狼人在席瓦莱恩自己的家中残杀了他。他死后遭受诅咒，幽魂始终被束缚在城堡的餐厅里，无法安息。",al={"席瓦莱恩为何成为幽灵","席瓦莱恩死了吗","席瓦莱恩灵魂"}},{q="席瓦莱恩为何攻击擅闯者？",a="席瓦莱恩受诅咒的灵魂仍留在昔日的家中，攻击闯入大厅的人。",al={"席瓦莱恩为何攻击","席瓦莱恩幽灵","席瓦莱恩擅闯者"}},{q="在城堡的什么地方能找到他？",a="席瓦莱恩男爵的幽魂徘徊在大厅。这里曾是城堡奢华的餐厅，在他的领地陷落时遭到破坏。",al={"席瓦莱恩在哪里","席瓦莱恩男爵位置","席瓦莱恩餐厅"}},{q="狼人进攻之前，影牙城堡叫什么？",a="狼人进攻之前，这座城堡名为席瓦莱恩城堡，得名于男爵所属的贵族家族。在阿鲁高掌控这里之前，统治城堡的正是这个家族。",al={"暗影之牙原名","席瓦莱恩城堡背景故事","暗影之牙旧名"}},{q="席瓦莱恩的家人有人幸存吗？",a="没有记载说明席瓦莱恩的家人是否有人幸存。记载讲述了狼人的袭击和男爵的幽魂，却未提及他家中的其他人。",al={"席瓦莱恩家族","席瓦莱恩的家人幸存了吗","席瓦莱恩继承人"}}},fx={["1b1b3783"]={q="席瓦莱恩男爵站在哪一方？",a="席瓦莱恩男爵只为自己和对毁灭领地的悲惨回忆而战。阿鲁高大法师将凶暴的狼人放入城堡时，席瓦莱恩惨遭杀害；死亡扭曲了他的幽灵心智。在痛苦的诅咒束缚下，他会不分青红皂白地袭击任何闯入他宴会厅的活人。",al={"席瓦莱恩男爵的阵营","席瓦莱恩为谁而战","席瓦莱恩男爵和阿鲁高站在一边吗"}},["5d3ddd3d"]={q="席瓦莱恩男爵想要什么？",a="席瓦莱恩男爵化作复仇幽魂，困于世间，只想赶走或杀死任何胆敢侵入家园的人。他饱受惨烈死亡的折磨，灵魂因任何扰乱城堡古老大厅的人而持续暴怒，猛烈反击。",al={"席瓦莱恩想要什么","席瓦莱恩男爵的目标","席瓦莱恩为什么发动攻击"}},["02c6a3ca"]={q="席瓦莱恩男爵与谁有关？",a="席瓦莱恩男爵的悲惨命运与阿鲁高大法师紧密相连。阿鲁高召唤异次元的狼人对抗天灾军团时，这些野兽变得嗜血成性，围攻了席瓦莱恩的城堡。阿鲁高将这座堡垒据为己有，命名为影牙城堡，而男爵复仇的幽灵至今仍在其中徘徊。",al={"席瓦莱恩的关系","席瓦莱恩与谁有关","席瓦莱恩男爵与阿鲁高"}}},fp="17,191,28.360.0,19.208.0,26.120.0,35.170.0,40.104.0,34.113.0,57.141.0,43.176.0"}
P.entries["npc:baros-alexston"] = {n="巴隆斯·阿历克斯顿",s="在暴风城的市政厅里，巴隆斯·阿历克斯顿照管着这座他曾参与重建的都城。他曾在石匠行会中与艾德温·范克里夫关系密切，但公会分裂时，他依然效忠王室。",h="在暴风城的市政厅里，巴隆斯·阿历克斯顿照管着这座他曾参与重建的都城。他曾在石匠行会中与艾德温·范克里夫关系密切，但公会分裂时，他依然效忠王室。",kw={"阿历克斯顿","建筑师","巴隆斯","教堂广场","市政厅","迪菲亚","农场","石匠","未寄出的信","范克里夫"},ang={["class:Rogue"]="身为暴风城的潜行者，你可以通过Baros与马迪亚斯·肖尔及SI:7建立联系。尽管这位建筑师过去与范克里夫有过来往，他们仍私下欠他一个人情。",["faction:Alliance"]="身为联盟的一员，你能看到那场令石匠行会分裂的痛苦妥协。公会的工匠们曾将毕生心血倾注于都城的重建。",["race:Human"]="身为来自西部荒野的人类，你或许因破败的阿历克斯顿农场而听说过Baros这个姓氏。如今，盗贼和豺狼人盘踞在那里。"},sec={{t="从农场到脚手架",b="巴隆斯在西部荒野起伏的草原上，在阿历克斯顿农场长大。他年幼时，盗贼侵占并烧毁了他的家园。逃离之前，他的父亲把家中珍爱的传家宝藏在了农场各处。\n\n巴隆斯后来前往都城，加入了石匠行会。多年来，他与公会会长艾德温·范克里夫并肩劳作，让暴风城从第一次兽人战争的灰烬中重新崛起。"},{t="痛苦的决裂",b="暴风城重建完工后，贵族拒绝支付承诺的报酬。愤怒的抗议随之爆发，石匠行会解散，街头的暴乱夺去了人命。艾德温·范克里夫率领未获报酬的工匠流亡在外，他们在那里组建了迪菲亚潜行者。\n\n贵族们提出，只要巴隆斯表态与起义划清界限，就让他担任城市建筑师。他反对公会沦为施暴的匪徒，便接受了这个职位。这一选择让他与昔日同伴之间留下了痛苦的裂痕。"},{t="死亡矿井中的幽灵",b="巴隆斯坐在市政厅的办公桌前，监管都城的维护工作。军情七处的马迪亚斯·肖尔私下欠他一个人情。\n\n范克里夫在死亡矿井深处倒下后，这位迪菲亚潜行者首领的尸体上留下了一封写给巴隆斯、却未曾寄出的信。信中追忆了一段情谊，它因围绕暴风城根基的政治纷争、叛国与流血而破裂。"}},faq={{q="在哪里可以找到巴隆斯·阿历克斯顿？",a="你可以在暴风城内、教堂广场北侧的市政厅里找到巴隆斯·阿历克斯顿。",al={"巴隆斯·阿历克斯顿位置","巴隆斯·阿历克斯顿在哪","巴隆斯 暴风城"}},{q="巴隆斯·阿历克斯顿在暴风城担任什么职务？",a="巴隆斯是暴风城的首席建筑师，负责城内的建设、维护和建筑规划。",al={"巴隆斯 工作","巴隆斯 头衔","巴隆斯 做什么"}},{q="巴隆斯是如何认识艾德温·范克里夫的？",a="巴隆斯和艾德温·范克里夫曾是石匠行会中关系密切的同僚。第一次兽人战争结束后，他们并肩重建暴风城。贵族拒绝支付工钱时，范克里夫率众反抗，而巴隆斯留了下来，成为城市建筑师。",al={"巴隆斯 与 范克里夫","巴隆斯 认识 艾德温 吗","巴隆斯 石匠"}},{q="巴隆斯为什么没有加入迪菲亚潜行者？",a="巴隆斯反对公会转向暴力叛乱。贵族们提出，只要他拒绝追随范克里夫，就让他担任城市建筑师，巴隆斯接受了。",al={"巴隆斯 为什么留下","巴隆斯 迪菲亚 决裂","巴隆斯 为什么背叛 石匠"}},{q="艾德温·范克里夫身上那封未寄出的信是什么？",a="艾德温·范克里夫死于死亡矿井后，人们在他的尸体上发现了一封写给巴隆斯·阿历克斯顿、却未曾寄出的信。信中诉说着这些昔日工匠之间挥之不去的怨恨，以及未曾了结的往事。",al={"未寄出的信任务","范克里夫 未寄出的信","给 巴隆斯 的信"}},{q="巴隆斯·阿历克斯顿与西部荒野有什么联系？",a="巴隆斯在西部荒野的阿历克斯顿农场长大。盗贼烧毁农场后，他的家人逃离了那里。他招募冒险者找回童年时的物品，其中包括他的第一个罗盘。",al={"阿历克斯顿农场","巴隆斯 西部荒野","巴隆斯 童年"}}},fx={["47ce41c7"]={q="巴隆斯·阿历克斯顿为什么在暴风城的市政厅？",a="巴隆斯·阿历克斯顿是暴风城的首席建筑师，在教堂广场的市政厅办公。石匠行会因拖欠薪酬而反抗时，巴隆斯拒绝加入艾德温·范克里夫的暴力叛乱。由于他效忠王室，并在理念上与公会决裂，王室授予了他城市建筑师的正式职位，由他监督王国的公共工程和建筑项目。",al={"巴隆斯·阿历克斯顿为何在这里","巴隆斯·阿历克斯顿为何在市政厅","巴隆斯在暴风城做什么"}},["8a4dbaf4"]={q="巴隆斯·阿历克斯顿想要什么？",a="巴隆斯希望光荣地为暴风城效力，同时直面过去的阴影。在私事上，他希望找回遗失的传家宝，比如他的第一只罗盘，那是在盗贼烧毁他位于西部荒野的童年农场之前藏起来的。在政事上，他十分关切如何揭露城中的叛逆行径，并终结迪菲亚潜行者的暴力行动。",al={"巴隆斯·阿历克斯顿的动机","巴隆斯想要什么","巴隆斯的目标"}}},fp="14,189,34.402.0,24.486.1,27.341.1,32.112.0,43.104.0,35.263.1,45.150.1,50.198.1,48.185.0"}
P.entries["npc:bartleby"] = {n="巴特莱比",s="巴特莱比在暴风城旧城区的猪和哨声旅店里喝酒滋事。他死攥着麦酒不放，成了有志成为战士的人必须面对的考验：在酒馆里和他打上一架。",h="巴特莱比在暴风城旧城区的猪和哨声旅店里喝酒滋事。他死攥着麦酒不放，成了有志成为战士的人必须面对的考验：在酒馆里和他打上一架。",kw={"巴特莱比","斗殴","伯加德","醉酒","酒杯","旧城区","猪和哨声旅店","酒馆","战士"},ang={["class:Warrior"]="身为暴风城的一名年轻战士，你记得自己与巴特莱比的那场决斗。夺走这个顽固酒鬼的酒杯，是一次令人难忘的徒手搏斗考验。",["race:Human"]="身为人类，你看到了暴风城旧城区粗粝的平民生活，在这里，邻里纠纷靠掀翻酒馆高凳的斗殴来解决，而非王室的敕令。"},sec={{t="猪和哨声旅店的老面孔",b="巴特莱比整天泡在暴风城旧城区的猪和哨声旅店里。这里的酒客比教堂广场那些酒馆里的更粗野。他紧攥着心爱的酒杯，喝着廉价麦酒，心怀怨气，谁打扰他，他就找谁打架。"},{t="战士的入门试炼",b="暴风城的战士训练师把巴特莱比当作一场实战考验。哈里·伯加德派初出茅庐的战士去找他，夺走他的酒杯。他们与这个醉醺醺的斗殴者赤手空拳地交锋，证明自己有勇气近身迎战一个蛮横的对手。"}},faq={{q="巴特莱比是谁？",a="巴特莱比是暴风城旧城区的猪和哨声旅店里一名蛮横的酒客。他喝得酩酊大醉，不打一场拳架就不肯交出酒杯。",al={"巴特莱比背景故事","巴特莱比是谁","巴特莱比暴风城"}},{q="在哪里能找到巴特莱比？",a="你可以在暴风城旧城区的猪和哨声旅店一楼找到正在喝酒的巴特莱比。",al={"巴特莱比位置","巴特莱比在哪","巴特莱比猪和哨声旅店"}},{q="战士为什么需要和他打架？",a="旧城区的战士训练师哈里·伯加德派年轻的新兵去找巴特莱比，检验他们的战斗能力。强行夺走他的酒杯，表明他们能够应付突如其来的斗殴和难缠的对手。",al={"为什么要打败巴特莱比","战士任务巴特莱比","巴特莱比的作用"}},{q="与他对峙时会发生什么？",a="当有人要夺走他的酒杯时，巴特莱比会喝下一瓶药水来增强耐力，并转为敌对。他在酒馆里赤手空拳地搏斗，直到被打服。",al={"与巴特莱比战斗","打败巴特莱比任务","巴特莱比斗殴"}},{q="巴特莱比属于什么阵营或组织吗？",a="巴特莱比是暴风城的平民，也是个嗜酒成性的酒鬼。目前没有迹象表明他与迪菲亚潜行者或城市卫兵有任何联系。",al={"巴特莱比是迪菲亚潜行者吗","巴特莱比阵营","巴特莱比联盟"}},{q="他为什么不肯直接交出酒杯？",a="巴特莱比好勇斗狠，醉得厉害，而且固执己见。他把索要酒水或酒杯视为侮辱，宁可用拳头解决问题，也不愿放下自己的酒。",al={"巴特莱比的酒杯","巴特莱比的麦酒杯","为什么要为酒杯打架"}}},fx={["59ff692a"]={q="巴特莱比为什么在旧城区这里？",a="巴特莱比整天在猪和哨声旅店借酒浇愁。他在旧城区没有什么远大的抱负或职责，只是徘徊在吧台附近，慢慢喝着麦酒，守着心爱的酒杯，提防胆敢来打扰他的人。",al={"巴特莱比为何在猪和哨声旅店","巴特莱比在此的原因","巴特莱比为何在暴风城"}}},fp="8,194,32.256.0,27.267.0,16.166.0,26.105.0,34.193.0,35.159.0,52.126.0,36.184.0"}
P.entries["npc:bashana-runetotem"] = {n="巴珊娜·符文图腾",s="在雷霆崖的长者高地，巴珊娜·符文图腾研究植物与腐化。她是大德鲁伊哈缪尔·符文图腾的女儿，并协助塞纳里奥议会。",h="在雷霆崖的长者高地，巴珊娜·符文图腾研究植物与腐化。她是大德鲁伊哈缪尔·符文图腾的女儿，并协助塞纳里奥议会。",kw={"巴珊娜","黑暗深渊","塞纳里奥议会","长者高地","哈缪尔","晨光麦","符文图腾","雷霆崖"},ang={["class:Druid"]="作为在哈缪尔指导下学习的牛头人德鲁伊，巴珊娜展现了理解卡利姆多不断变化的生态所需的实地研究工作。",["faction:Horde"]="身为部落的一员，你可以通过巴珊娜，将雷霆崖的塞纳里奥议会与对抗邪教徒威胁的勇士联系起来。"},sec={{t="议会之女",b="巴珊娜·符文图腾在雷霆崖的长者高地传承着父亲、大德鲁伊哈缪尔·符文图腾的德鲁伊之道。父亲指导牛头人德鲁伊，并为凯恩·血蹄提供建议，而巴珊娜则研究奇异植物和各地的威胁。她向旅人提供常青袋等工具，用来培育包括晨光麦在内的神秘植物。她还协调部落的行动，对抗从黑暗深渊等地蔓延而来的腐化。"}},faq={{q="巴珊娜·符文图腾是谁？",a="巴珊娜·符文图腾是雷霆崖长者高地的一位牛头人德鲁伊，也是一名研究者。她是大德鲁伊哈缪尔·符文图腾的女儿，为塞纳里奥议会研究奇异植物，并组织行动，应对卡利姆多各地威胁自然的力量。",al={"巴珊娜是谁","巴珊娜的故事","巴珊娜·符文图腾是谁"}},{q="她对晨光麦进行哪些研究？",a="巴珊娜请部落冒险者用种子包和泥土培育并收集晨光麦。塞纳里奥议会研究这种草药的独特性质，以及它与卡利姆多各地其他植物谜团的联系。",al={"晨光麦研究","巴珊娜用晨光麦做什么","为什么研究晨光麦"}},{q="她与黑暗深渊有何联系？",a="银月守卫塞尔瑞德派遣冒险者前往黑暗深渊对抗邪教徒，巴珊娜则接收他们带回的报告和证据。她给予他们奖励，酬谢他们协助对抗威胁灰谷的腐化。",al={"巴珊娜 黑暗深渊","黑暗深渊中的邪恶任务","为什么去黑暗深渊"}},{q="在哪里可以找到她？",a="巴珊娜位于雷霆崖的长者高地，就在德鲁伊的帐篷附近。这座台地是城中萨满祭司、德鲁伊和精神领袖们的居所。",al={"巴珊娜·符文图腾在哪里","巴珊娜的位置","如何找到巴珊娜"}}},fp="17,151,24.442.0,25.250.0,48.219.0,44.194.0,23.151.0"}
P.entries["npc:bath-rah-the-windwatcher"] = {n="捕风者巴斯拉",s="捕风者巴斯拉是一位离群索居的丛林巨魔萨满祭司兼武器匠，住在冰风岗附近的废墟中。远离热带故土的他研究着北方群山中狂暴的元素，寻找足够强大的勇士，协助他打造威力惊人的风之武器。",h="捕风者巴斯拉是一位离群索居的丛林巨魔萨满祭司兼武器匠，住在冰风岗附近的废墟中。远离热带故土的他研究着北方群山中狂暴的元素，寻找足够强大的勇士，协助他打造威力惊人的风之武器。",kw={"奥特兰克","巴斯拉","冰风","塞克隆尼亚","元素","萨满祭司","旋风","捕风者"},ang={["class:Shaman"]="同为驾驭元素的大师，巴斯拉与那些寻求和大地、水与风之灵深入沟通的萨满祭司有着深厚的灵魂联系。",["class:Warrior"]="巴斯拉在久经沙场的战士中颇负盛名，因为他会指引他们完成必要的试炼，利用元素生物塞克隆尼亚的精华锻造标志性的Whirlwind兵器。"},sec={{t="群峰中的隐士",b="大多数丛林巨魔都生活在南方温暖的森林和海岸，巴斯拉却选择在奥特兰克山脉冰冷的废墟中，过着山中隐士的独居生活。身为经验丰富的萨满祭司和工匠，他终日聆听呼啸的风声，与自然之灵交流。他的执着并不止于思索；他试图将猛烈元素风暴的怒火封入实体兵器，交给那些有力量驾驭它们的人。"},{t="塞克隆尼亚之主",b="巴斯拉最大的抱负与塞克隆尼亚有关，那是一个栖身于周围群峰中的恐怖风元素。他无法独自战胜这样的存在，于是这位捕风者招募老练的战士和萨满祭司，收集奇异的元素精华，召唤这头怪物。通过杀死塞克隆尼亚并夺取它的元素之心，巴斯拉将原始的风暴之力铸成名扬艾泽拉斯的传奇武器。"}},faq={{q="捕风者巴斯拉是谁？",a="巴斯拉是一位性情古怪的丛林巨魔萨满祭司兼武器匠，隐居在奥特兰克山脉冰风岗附近的废墟中。他帮助经验丰富的冒险者将元素之力铸入强大的武器。",al={"巴斯拉身份","巴斯拉是谁","捕风者背景故事"}},{q="为什么一个丛林巨魔会住在奥特兰克？",a="巴斯拉隐居在冰风岗附近，研究元素之力，并帮助有实力的冒险者锻造武器。他离开故土的原因尚不明确。",al={"巴斯拉为什么在奥特兰克","奥特兰克山脉的巨魔"}},{q="塞克隆尼亚是什么？",a="塞克隆尼亚是一个庞大而狂暴的风元素，盘踞在巴斯拉居所周围的废墟中。巴斯拉需要这个生物的核心，才能锻造灌注风元素之力的武器。",al={"塞克隆尼亚是谁","巴斯拉召唤什么"}},{q="战士们为什么要寻找他？",a="世界各地的战士远道而来寻找巴斯拉，因为他掌握着标志性的旋风武器的锻造方法。在他的指引下击败塞克隆尼亚，就能获得灌注呼啸狂风之力的兵器。",al={"巴斯拉战士任务","旋风斧的锻造者"}},{q="巴斯拉只帮助部落成员吗？",a="巴斯拉是一位独居的隐士，远离各大阵营的政治纷争。他主要专注于元素锻造，会帮助那些有实力、尊重诸灵并协助他开展元素研究的战士和萨满祭司。",al={"巴斯拉是否敌对","巴斯拉联盟"}}},fx={["4f68ea16"]={q="捕风者巴斯拉想要什么？",a="巴斯拉正在寻找一位有资格挑战并击败塞克隆尼亚的勇士。这个狂暴的元素生物居住在他的营地附近。他渴望得到它的心脏，希望借助其中原始而狂野的能量，铸造一件威力惊人的非凡武器。",al={"捕风者巴斯拉想要什么","捕风者巴斯拉的目标"}}},fp="24,220,19.329.0,19.342.1,32.196.0,40.172.0,18.164.0,29.182.0,45.191.0"}
P.entries["npc:bazil-thredd"] = {n="巴基尔·斯瑞德",s="在暴风城监狱，巴基尔·斯瑞德从东侧牢区指挥迪菲亚潜行者囚犯发动叛乱。这位艾德温·范克里夫的副手自石匠暴动以来就一直被关押在那里。",h="在暴风城监狱，巴基尔·斯瑞德从东侧牢区指挥迪菲亚潜行者囚犯发动叛乱。这位艾德温·范克里夫的副手自石匠暴动以来就一直被关押在那里。",kw={"巴基尔·斯瑞德","迪菲亚潜行者","艾德温·范克里夫","哈姆霍克","监狱","石匠","暴风城监狱","典狱官塞尔沃特"},ang={["faction:Alliance"]="暴风城街道下方的一场迪菲亚潜行者叛乱正威胁着首都，典狱官塞尔沃特希望在叛乱蔓延之前除掉其首领。",["race:Human"]="身为人类，你眼前这个活生生的人物，让你想起了那场使迪菲亚潜行者与王国为敌的Stonemasons暴动。"},sec={{t="范克里夫的副手",b="当石匠行会起身反抗暴风城贵族时，巴基尔·斯瑞德站在艾德温·范克里夫身边。公会重建了这座城市，却被拒绝支付报酬，而范克里夫拒绝了政府的安抚，引发了公开叛乱。斯瑞德是他的首席副官，也是他最信任的助手。在随后的激烈冲突中，城市卫兵抓住了斯瑞德。范克里夫和幸存的石匠逃往西部荒野，组建了迪菲亚潜行者，而斯瑞德则被送进了暴风城监狱。"},{t="监狱暴动",b="一场监狱暴动击溃了守卫，打开了牢门，将法师区地下的监狱变成了一座武装堡垒。斯瑞德在东翼的一处据点指挥被关押的迪菲亚潜行者匪徒、叛乱者及其凶徒盟友，由一个名叫哈姆霍克的食人魔守护。多年来，他在铁窗后始终沉默，似乎已被抛弃。如今，典狱官塞尔沃特想要斯瑞德的首级，希望在混乱蔓延到城市街头之前，摧毁叛乱的指挥核心。"},{t="可疑的访客",b="暴动前几个月，一个自称麦里克的男人开始每周探望巴基尔·斯瑞德一两次。典狱官塞尔沃特一直以为迪菲亚潜行者已经抛弃斯瑞德，任他在牢里腐烂，这些探访引起了他的怀疑。然而，麦里克的证件经查完全合法。如今斯瑞德已死，塞尔沃特怀疑那名访客不会再来了。能拿到如此完备证件的人必定人脉深厚，而这些探访表明，城中有外部势力已经与这位迪菲亚潜行者副官取得了联系。"}},faq={{q="巴基尔·斯瑞德是谁？",a="在暴风城的石匠叛乱期间，巴基尔·斯瑞德是艾德温·范克里夫的得力助手。他在暴动中被捕，关进监狱，如今正领导着叛乱的囚犯。",al={"巴基尔·斯瑞德背景故事","斯瑞德是谁","监狱首领斯瑞德"}},{q="在哪里能找到巴基尔·斯瑞德？",a="巴基尔·斯瑞德位于暴风城监狱深处，就在法师区附近的运河区地下。从主走廊的交叉口进入东侧牢区，经过食人魔哈姆霍克所在之处；斯瑞德就在尽头房间中央的牢房里发号施令。",al={"巴基尔·斯瑞德在哪里","斯瑞德位置","寻找巴基尔·斯瑞德"}},{q="监狱为什么发生暴动？",a="囚犯们制服了守卫，打开牢门，占据了监狱的走廊。巴基尔·斯瑞德是监狱中最重要的迪菲亚潜行者囚犯，他指挥着暴动的匪徒和罪犯，而典狱官塞尔沃特正设法阻止叛乱蔓延到暴风城的街头。",al={"他们为何暴动","监狱暴动起因","囚犯为何叛乱"}},{q="典狱官塞尔沃特为什么要杀死斯瑞德？",a="典狱官塞尔沃特认为，只要斯瑞德仍在指挥，暴动就无法平息。守卫已被击溃，整座监狱都被囚犯控制，他因此下令处决斯瑞德，以摧毁叛乱的指挥核心。",al={"为何杀死斯瑞德","塞尔沃特悬赏斯瑞德","索取巴基尔·斯瑞德的头颅的原因"}},{q="暴动前是谁在探望斯瑞德？",a="暴动前的几个月，一个自称麦里克的寡言男子每周都会探望斯瑞德一两次。塞尔沃特不信任他，但他的证件确实合法，这表明城中人脉深厚的势力已与这位迪菲亚潜行者副官取得了联系。",al={"斯瑞德的访客","麦里克是谁","可疑访客的身份"}},{q="斯瑞德在石匠行会中担任什么职务？",a="在暴风城重建及随后的劳资纠纷期间，斯瑞德是艾德温·范克里夫的首席副官。贵族拒绝支付他们的工钱后，他协助领导了公会的反抗。",al={"斯瑞德曾是石匠吗","斯瑞德石匠","石匠斯瑞德"}}},fp="12,173,21.505.0,21.461.0,19.474.1,20.181.0,32.249.0,28.223.0,43.202.0,40.244.1,48.211.0"}
P.entries["npc:bazzalan"] = {n="巴扎兰",s="巴扎兰在奥格瑞玛地下的熔岩洞穴中统率着灼热之刃教派。他与祈求者耶戈什共同指挥教派在怒焰裂谷的行动。",h="巴扎兰在奥格瑞玛地下的熔岩洞穴中统率着灼热之刃教派。他与祈求者耶戈什共同指挥教派在怒焰裂谷的行动。",kw={"巴扎兰","教徒","耶戈什","奥格瑞玛","怒焰裂谷","萨特","灼热之刃"},ang={["class:Rogue"]="巴扎兰善用潜行、凶狠的攻击和淬毒的刀刃，因此格外受到盗贼们的关注。",["faction:Horde"]="巴扎兰及其教派在萨尔的堡垒地下构成威胁，部落想要将他们铲除。",["race:Orc"]="兽人历经艰苦斗争才摆脱了恶魔的操控。如今，一个萨特竟在他们自己的城池根基之下指挥教徒，这令他们愤怒不已。"},sec={{t="城下的毒蛇",b="在奥格瑞玛地下，巴扎兰加入了怒焰裂谷中的灼热之刃教派。当萨尔致力于在杜隆塔尔各地建设兽人的新家园时，这名萨特盗贼在蜿蜒的熔岩洞穴中指挥着教派的作战部队。他挥舞双刃，动作迅捷而致命。"},{t="教派首领与诡计",b="巴扎兰在中央洞室上方的一处火山岩台上监督教派守卫。祈求者耶戈什则在下方举行恶魔仪式。和所有萨特一样，巴扎兰最终效忠的是恶魔主人。他用毒药、迅捷的攻击和潜行，对付那些冒险靠近教派集结地的部落斥候。"}},faq={{q="巴扎兰是谁？",a="巴扎兰是一名萨特盗贼，也是奥格瑞玛地下怒焰裂谷中灼热之刃教派的首领之一。",al={"巴扎兰背景故事","巴扎兰是谁","怒焰裂谷萨特首领"}},{q="在怒焰裂谷的哪里能找到巴扎兰？",a="巴扎兰潜伏在怒焰裂谷的上层岩台上，位于祈求者耶戈什上方。沿着洞壁开凿的昏暗坡道可以抵达他的藏身处。",al={"巴扎兰位置","巴扎兰在哪","寻找巴扎兰"}},{q="一个萨特在奥格瑞玛地下做什么？",a="巴扎兰与灼热之刃合作，这是一个企图从内部颠覆部落的恶魔教派。萨特受恶魔力量束缚，常为暗影议会充当煽动者和刺客。",al={"奥格瑞玛为什么有萨特","巴扎兰为什么在怒焰裂谷"}},{q="巴扎兰在战斗中使用什么技能？",a="巴扎兰使用近战武器迅速攻击，并施展邪恶攻击。他有时会给对手施加一种轻度削弱能力的毒药。",al={"巴扎兰技能","巴扎兰攻击","巴扎兰如何战斗"}},{q="他与祈求者耶戈什是什么关系？",a="巴扎兰与耶戈什共同领导怒焰裂谷中的灼热之刃。耶戈什负责祈求和召唤黑暗力量，巴扎兰则指挥教派的武力行动与潜行任务。",al={"耶戈什与巴扎兰","巴扎兰与耶戈什有关吗"}},{q="部落为什么要杀死巴扎兰？",a="巴扎兰藏身于都城深处，构成了直接的恶魔威胁。部落领袖派遣冒险者进入怒焰裂谷，要在灼热之刃的阴谋危及城市之前将他铲除。",al={"巴扎兰悬赏","阻止入侵巴扎兰"}}},fp="8,135,26.242.0,26.327.0,16.110.0,46.128.0,40.194.0,43.134.0,48.195.0,38.205.0"}
P.entries["npc:beldin-steelgrill"] = {n="贝尔丁·钢架",s="在丹莫罗的钢架补给站，贝尔丁·钢架负责让矮人的战争机器保持运转。他是享誉卡兹莫丹的技师大师，靠着源源不断的专用工具，修理攻城机械和装甲战车。",h="在丹莫罗的钢架补给站，贝尔丁·钢架负责让矮人的战争机器保持运转。他是享誉卡兹莫丹的技师大师，靠着源源不断的专用工具，修理攻城机械和装甲战车。",kw={"贝尔丁·钢架","丹莫罗","铁炉堡","卡拉诺斯","机械师","攻城机械","蒸汽坦克","钢架"},ang={["profession:Engineering"]="身为工程师，你可以在贝尔丁的场地里见识矮人的载具制造工艺，联盟那些威力强大的战争机器就在这里接受维护。",["race:Dwarf"]="身为矮人，你可以在贝尔丁的场地里见识铁炉堡的工业技艺，矮人的本领从手工工具延伸到了攻城火炮。"},sec={{t="履带巨兽之主",b="从卡拉诺斯沿路走不远，便是测试和检修蒸汽坦克与攻城机械的钢架补给站。在金属与隆隆作响的锅炉之间作业，让重型扳手、切割工具和精密仪器承受着严峻的考验。贝尔丁不断需要替换工具，让当地的铁匠为他的工作台忙个不停。"}},faq={{q="贝尔丁·钢架是谁？",a="贝尔丁·钢架是丹莫罗钢架补给站的老板，也是在此主事的技师大师。他以维护矮人攻城机械和战车的本领闻名于卡兹莫丹。",al={"贝尔丁·钢架","贝尔丁是谁","丹莫罗坦克技师"}},{q="钢架补给站里都在忙些什么？",a="钢架补给站就在卡拉诺斯东北方，是联盟测试和维护蒸汽坦克与重型机械设备的场地。",al={"钢架补给站","钢架补给站是什么","补给站用途"}},{q="贝尔丁为什么会消耗这么多工具？",a="贝尔丁需要处理厚重的装甲、复杂的齿轮和蒸汽锅炉，专用工具因此磨损得很快。附近的铁匠满足他要求严苛的订单，为他的工作台持续供应工具。",al={"他为什么需要工具","钢架的工具","给钢架的工具"}}},fx={c08b01c8={q="贝尔丁·钢架站在哪一边？",a="贝尔丁效忠铁炉堡的铜须氏族，坚定地站在联盟一方。他在离卡拉诺斯不远的路旁工作，为矮人军队和当地防御部队配备重型机械装甲与攻城坦克。",al={"贝尔丁·钢架的阵营","贝尔丁为谁效力","贝尔丁·钢架属于联盟吗"}},["940fd3ae"]={q="贝尔丁·钢架为何出名？",a="贝尔丁以当世最出色的攻城坦克技师之名享誉丹莫罗。他对战争机器和重型机械的精通，让他在矮人工程师中享有无可比拟的声誉，不过，他对当地工具制造者的苛刻要求也同样出了名。",al={"贝尔丁·钢架的声誉","贝尔丁为何出名","最出色的攻城坦克技师"}}},fp="17,234,27.289.0,25.181.0,35.138.0,41.172.0"}
P.entries["npc:bethor-iceshard"] = {n="比索·埃斯沙德",s="在幽暗城，比索·埃斯沙德统领着魔法区的奥术与暗影施法者。他在希尔瓦娜斯的领地中握有权柄，而昔日的友谊仍牵系着他的过往。",h="在幽暗城，比索·埃斯沙德统领着魔法区的奥术与暗影施法者。他在希尔瓦娜斯的领地中握有权柄，而昔日的友谊仍牵系着他的过往。",kw={"比索·埃斯沙德","被遗忘者","冈瑟尔·阿坎努斯","魔法区","流浪的巫妖","诅咒神殿","图勒·鸦爪","幽暗城"},ang={["class:Mage"]="身为被遗忘者法师，你能从比索·埃斯沙德身上看到，奥术技艺如何在亡灵之躯中延续。",["faction:Horde"]="身为部落的一员，你受益于比索·埃斯沙德的进攻魔法与对抗死灵法术的行动，它们守护着部落在洛丹伦各地的立足之地。",["race:Undead"]="身为亡灵，你或许明白那种痛苦：因Scourge而失去朋友与家园，随后又不得不与昔日盟友为敌。"},sec={{t="魔法区之主",b="比索·埃斯沙德在幽暗城的诅咒神殿指挥奥术与暗影施法者。他的才智与冰冷意志令人既敬重又畏惧。他在政治和魔法上的影响力足以号令洛丹伦各地的地方执政官。比索派遣被遗忘者特工夺取珍贵的魔典，调查奥术异象，并压制威胁幽暗城统治的敌对势力。"},{t="旧友与悲喜交织的重逢",b="比索·埃斯沙德仍记得昔日的同伴。他追踪提瑞斯法和银松森林各地强大的亡灵施法者，派遣特工查明这些不受管束的施法者究竟效忠于巫妖王，还是可能投身被遗忘者的事业。当他发现冈瑟尔·阿坎努斯在澈水湖复活死者时，比索耐心地设法将这位老友招入希尔瓦娜斯麾下。图勒·鸦爪却没有得到这样的宽恕；他自愿背叛，断送了他们的兄弟情谊。"},{t="学徒间的情谊",b="在第三次大战摧毁洛丹伦之前，比索·埃斯沙德还是一名凡人学徒，与挚友冈瑟尔·阿坎努斯和图勒·鸦爪一同研习魔法。三人将各自的练习魔杖编结在一起，作为友谊的见证。天灾军团粉碎了这份情谊。当死亡与黑暗魔法席卷王国时，图勒自愿将灵魂献给了巫妖王。冈瑟尔死后，在澈水湖的一座孤岛上重新站了起来。比索也未能幸免，后来挣脱了控制，成为被遗忘者的一员。"}},faq={{q="比索·埃斯沙德是谁？",a="比索·埃斯沙德在幽暗城魔法区的诅咒神殿统领奥术与暗影施法者。他为黑暗女王主持魔法研究，指挥针对不受管束的施法者的情报工作，以及秘密奥术行动。",al={"比索·埃斯沙德","比索是谁","比索的故事"}},{q="在哪里可以找到比索·埃斯沙德？",a="比索·埃斯沙德住在幽暗城魔法区的诅咒神殿内。",al={"比索在哪里","比索的位置","寻找比索·埃斯沙德"}},{q="比索与冈瑟尔·阿坎努斯有怎样的过往？",a="比索·埃斯沙德与冈瑟尔·阿坎努斯曾是洛丹伦的挚友，也是一同学习魔法的学徒。两人都在天灾军团入侵期间死去，后来挣脱了巫妖王的控制。比索安排冈瑟尔加入了被遗忘者。",al={"冈瑟尔与比索","冈瑟尔·阿坎努斯的友谊","比索如何认识冈瑟尔"}},{q="图勒·鸦爪与比索是什么关系？",a="图勒·鸦爪是比索·埃斯沙德和冈瑟尔·阿坎努斯学徒小团体中的第三位成员。在天灾军团入侵期间，他自愿将灵魂献给巫妖王，成为一名盘踞在芬里斯岛、遭人痛恨的死灵法师。",al={"与图勒·鸦爪的关系","图勒与比索","比索与鸦爪"}},{q="比索的魔杖背后有什么故事？",a="年轻时，比索·埃斯沙德、冈瑟尔·阿坎努斯和图勒·鸦爪曾将各自的练习魔杖编结在一起，象征永恒的友谊。这件编结而成的信物，将如今分崩离析的三位施法者与他们身为凡人的过往联系在一起。",al={"狼人魔杖","给比索的魔杖","比索的学徒魔杖"}},{q="比索在被遗忘者社会中担任何种角色？",a="比索·埃斯沙德是幽暗城最具影响力的奥术权威之一。他指导新近复生的法师与术士，指挥针对不受管束的死灵法师的情报工作，并有权管辖执政官塞弗伦这样的被遗忘者地方文官。",al={"比索的职责","比索做什么","比索的权柄"}}},fp="15,178,27.367.0,36.401.1,23.480.1,23.247.0,35.89.0,46.231.1,34.226.1,39.225.0,47.234.0"}
P.entries["npc:billy-maclure"] = {n="比利·马科伦",s="在马科伦农场，比利·马科伦的恶作剧在相邻的两座农场之间惹出了麻烦。这个人类小男孩逃避杂活，还卷入自家与斯通菲尔德一家的争斗，不过新鲜出炉的糕点就能换来他的帮助。",h="在马科伦农场，比利·马科伦的恶作剧在相邻的两座农场之间惹出了麻烦。这个人类小男孩逃避杂活，还卷入自家与斯通菲尔德一家的争斗，不过新鲜出炉的糕点就能换来他的帮助。",kw={"波尼斯·斯通菲尔德","比利·马科伦","法戈第矿洞","金牙","丢失的项链","马科伦农场","猪肉馅饼","斯通菲尔德"},ang={["faction:Alliance"]="作为刚从北郡来到这里的联盟冒险者，帮比利处理恶作剧惹出的麻烦，会让你见识到法戈第矿洞里的危险。",["profession:Cooking"]="作为厨师，你可以看到波尼斯大婶的猪肉馅饼如何帮助平息当地的争端，让守口如瓶的农家男孩坦白实情。",["race:Human"]="作为人类，你能从比利的烦恼中看到艾尔文乡间的日常争吵。暴风城政局动荡，农场间的争斗和孩子们的顽皮胡闹仍在继续。"},sec={{t="农场里的男孩",b="比利·马科伦整天待在马科伦农场的谷仓外，离农夫葛拉德·提勒不远。他在艾尔文森林南部的葡萄藤间长大，经常溜出去逃避杂活，在草地上闲逛。马科伦一家与斯通菲尔德一家长期互相敌视。比利趁着两家的争斗，搞恶作剧，做些小偷小摸的勾当。"},{t="被偷走的项链",b="比利·马科伦偷走了波尼斯·斯通菲尔德大婶珍爱的传家项链。他在法戈第矿洞附近奔跑时，把项链弄丢了。金牙是个体型庞大、凶狠的狗头人，他一把抓走项链，消失在矿洞的坑道里。比利既怕狗头人，又怕邻家长辈发怒，因此迟迟不敢坦白。波尼斯大婶热腾腾的猪肉馅饼能让他说出实情。"}},faq={{q="比利·马科伦是谁？",a="比利·马科伦是艾尔文森林马科伦农场里的一个人类小男孩。他逃避农活，爱搞恶作剧，还总惹恼邻居斯通菲尔德一家。",al={"比利是谁","比利·马科伦的故事","马科伦家的孩子"}},{q="在哪里能找到比利·马科伦？",a="比利待在马科伦农场的主谷仓外，这里位于艾尔文森林南部、斯通菲尔德农场以东。",al={"比利·马科伦的位置","比利在哪里","寻找比利·马科伦"}},{q="比利对波尼斯大婶做了什么？",a="两家争斗期间，比利偷走了波尼斯·斯通菲尔德大婶的传家项链。",al={"波尼斯的项链","比利偷了什么","艾尔文被偷的项链"}},{q="比利偷走的项链后来怎么样了？",a="比利在法戈第矿洞附近弄丢了项链。金牙捡起项链，把它带进了矿洞。",al={"项链在哪里","艾尔文丢失的项链","波尼斯的项链在谁手里"}},{q="怎样才能让比利坦白项链的下落？",a="给比利一份波尼斯大婶刚烤好的猪肉馅饼。为了满足口腹之欲，他就会坦白。",al={"给比利的馅饼","如何贿赂比利","贿赂比利·马科伦"}},{q="金牙是谁？",a="金牙是法戈第矿洞里一个体型异常庞大、凶狠的狗头人首领。他在矿洞入口附近拿走了波尼斯大婶的项链，并将它留在坑道里。",al={"金牙是谁","金牙的故事","法戈第矿洞的狗头人"}}},fx={["324ac528"]={q="比利·马科伦站在哪一边？",a="比利是艾尔文森林马科伦家族的忠实成员，坚定地拥护暴风城王国和联盟。虽然他的家族与邻居斯通菲尔德家族长期积怨甚深，但比利仍然只是一个小男孩，夹在家族恩怨和自己的口腹之欲之间。",al={"比利·马科伦的阵营","比利站在哪一边","比利支持谁"}},c9c2f9db={q="比利·马科伦想要什么？",a="比利只想少惹麻烦，满足自己的口腹之欲。尽管两家势同水火，他最馋的还是波尼斯·斯通菲尔德婶婶那有名的猪肚馅饼。只要有人给他带来一个她新做的美味馅饼，他甚至愿意承认自己那些调皮捣蛋的行径。",al={"比利想要什么","比利·马科伦渴望什么","比利·马科伦的最爱食物"}},f69aaa51={q="比利·马科伦为什么在这里？",a="比利住在马科伦农场，那是他家在艾尔文森林的住所，也是全家的生计所在。平日里，只要没有偷偷溜向邻近的斯通菲尔德农场，他就在葛拉德·提勒附近的谷仓外闲逛、跑腿，或在周围的乡间玩耍。",al={"比利·马科伦为何在这里","比利为何在马科伦农场","比利在这里做什么"}},["275e906f"]={q="比利·马科伦与谁有关联？",a="比利出身于务农的马科伦家族，与亲属以及葛拉德·提勒这样的雇工一起住在农场里。他那些调皮捣蛋的行径，也让他与敌对的斯通菲尔德家族纠缠颇深，尤其是波尼斯·斯通菲尔德婶婶，他偷走了她珍爱的项链，却又暗地里喜爱她烘焙的食物。",al={"比利·马科伦的家人","比利·马科伦与谁有亲属关系","比利·马科伦的人际关系"}}},fp="13,221,22.344.0,19.383.1,21.152.0,33.106.0,36.97.0,42.97.1,62.101.1,17.166.1"}
P.entries["npc:bingles-blastenheimer"] = {n="宾格斯·雷管",s="在洛克莫丹的东南岸，宾格斯·雷管守候在他的飞行器残骸旁。这位侏儒飞行员被穴居人和野兽困在此地，需要找回自己的工具和零件。",h="在洛克莫丹的东南岸，宾格斯·雷管守候在他的飞行器残骸旁。这位侏儒飞行员被穴居人和野兽困在此地，需要找回自己的工具和零件。",kw={"宾格斯","雷管","侏儒","旋翼机","洛克莫丹","飞行员"},ang={["profession:Engineering"]="身为工程师，你明白飞行出了岔子后，专用扳手和小装置又被穴居人夺走的苦恼。",["race:Gnome"]="身为侏儒，你和宾格斯一样，渴望让侏儒的发明翱翔天际，即使机械故障会让降落变得狼狈不堪。"},sec={{t="迫降遇险",b="宾格斯·雷管驾驶着他改装的飞行器升上天空，降落时却出了岔子。他的旋翼机发生故障，坠毁在洛克莫丹的东南岸。宾格斯幸存了下来，飞行器却摔得四分五裂。这里远离铁炉堡，他留在残骸附近，提防着饥饿的鳄鱼和充满敌意的穴居人。附近一座岛上的穴居人偷走了他的工具和气压炸弹炸药，于是他请求过路的旅者帮忙找回这些东西。"}},faq={{q="宾格斯·雷管是谁？",a="宾格斯·雷管是一名侏儒飞行员兼工匠，他的飞行器坠毁在洛克莫丹的东南岸，他也因此受困于此。",al={"宾格斯是谁","宾格斯·雷管的故事","湖边的侏儒是谁"}},{q="他的飞行器出了什么事？",a="宾格斯驾驶的旋翼机坠入了洛克湖。附近一座岛上的穴居人袭击了他，偷走了他的工具和气压炸弹炸药。",al={"宾格斯为何坠机","宾格斯的旋翼机","宾格斯的飞机出了什么事"}},{q="宾格斯为什么还没回镇上？",a="失去了旋翼机，宾格斯受困于此，附近一座岛上的穴居人还偷走了他的工具和气压炸弹炸药。他想找回这些东西，用于夺回诺莫瑞根的行动，因此一直守在残骸旁，等待有人帮他找回失物。",al={"宾格斯为何受困","为何留在湖边"}},{q="飞行器修好后，宾格斯会去哪里？",a="宾格斯仍留在洛克湖东南岸的坠机地点，等待旅者找回他遗失的物资。",al={"宾格斯去哪里","宾格斯的小屋"}}},fx={["1e141199"]={q="宾格斯·雷管站在哪一边？",a="宾格斯是个忠诚的侏儒，坚定地拥护诺莫瑞根和联盟。他依靠友善的联盟旅人帮忙找回遗失的装备，确保自己能在洛克莫丹的荒野中生存。",al={"宾格斯·雷管的阵营","宾格斯属于联盟吗","宾格斯为谁工作"}},["89c66e03"]={q="宾格斯·雷管为什么在这里？",a="宾格斯驾驶着心爱的旋翼机飞越洛克莫丹时，灾难突然降临。他的飞行器坠毁在湖岸边，让他孤身受困于荒野，周围游荡着危险的野兽和充满敌意的穴居人。",al={"宾格斯为何在洛克莫丹","宾格斯怎么来到这里的","宾格斯·雷管坠机"}}},fp="21,191,15.438.0,29.134.0,36.136.0,36.233.0,51.124.1"}
P.entries["npc:bink"] = {n="彬克",s="在铁炉堡的秘法大厅，彬克向有志成为法师的人传授奥术。她凭借敏捷的才思，帮助有潜力的学生寻找联盟各地的巫师。",h="在铁炉堡的秘法大厅，彬克向有志成为法师的人传授奥术。她凭借敏捷的才思，帮助有潜力的学生寻找联盟各地的巫师。",kw={"安多玛斯","彬克","侏儒","秘法大厅","铁炉堡","法师训练师","秘法区","塔贝萨"},ang={["class:Mage"]="作为身在铁炉堡的联盟法师，你可以向彬克学习，并遵循她的指引，去寻找艾泽拉斯各地强大的导师。",["race:Gnome"]="身为侏儒，你与彬克一样，在矮人盟友厅堂中庇护的流亡者之间，追求对奥术的精通。"},sec={{t="秘法大厅中的明灯",b="在铁炉堡的秘法大厅，彬克传授法师之道。她与聚集在秘法区的学者、牧师和奥术师共事。和许多被迫离开诺莫瑞根的侏儒一样，她在这座矮人的山中要塞安了家。她以敏锐的头脑和精湛的奥术技艺，指引学习魔法的人。\n\n彬克结识的巫师遍布东部王国和卡利姆多。她会指引有潜力的学徒去寻找导师，例如暴风城的高阶巫师安多玛斯，以及尘泥沼泽的塔贝萨。"}},faq={{q="彬克是谁？",a="彬克在铁炉堡的秘法大厅训练联盟的侏儒法师。她传授奥术施法技艺，并在法师成长的道路上给予指引。",al={"彬克故事","彬克是谁","彬克铁炉堡"}},{q="在哪里可以找到彬克？",a="你可以在铁炉堡秘法区西翼的秘法大厅找到彬克。",al={"彬克位置","彬克在哪里","寻找彬克"}},{q="哪些任务与彬克有关？",a="正在成长的法师会通过和彬克交谈任务前去拜访彬克。她会派他们向权威法师求学，例如暴风城巫师圣殿的高阶巫师安多玛斯，或是隐居在尘泥沼泽的法师塔贝萨。",al={"彬克任务","和彬克交谈任务"}},{q="彬克会对非​​法师说些什么？",a="如果你不研习奥术，彬克会愉快地建议：“和法师交个朋友吧！我们总有那么一两手绝活，是的……”",al={"彬克闲谈","彬克对话"}}},fx={cf09b30e={q="彬克效忠哪一方？",a="彬克坚定地支持联盟和避居铁炉堡的诺莫瑞根流亡者。她与其他学者和法师一起在神秘大厅活动，运用自己的魔法才能帮助盟友，并指导在联盟旗帜下作战、有潜力的新法师。",al={"彬克的阵营","彬克为谁效力","彬克属于联盟还是部落"}},d0de8b26={q="彬克为什么在神秘大厅？",a="彬克住在铁炉堡的神秘大厅，担任侏儒法师训练师。诺莫瑞根陷落后，流离失所的侏儒在铜须矮人中找到了庇护；彬克运用自己的奥术专长训练有志成为法师的人，并派学生执行对奥术界至关重要的任务。",al={"彬克为什么在这里","彬克在铁炉堡做什么","彬克为什么在铁炉堡"}}},fp="4,152,33.505.0,12.130.0,22.91.0,25.210.0,32.126.0"}
P.entries["npc:bishop-delavey"] = {n="德拉维主教",s="在暴风要塞，德拉维主教倾听着宫廷中不便声张的忧虑。他在请愿者大厅代表圣光教会，信仰与国政在这里交汇。",h="在暴风要塞，德拉维主教倾听着宫廷中不便声张的忧虑。他在请愿者大厅代表圣光教会，信仰与国政在这里交汇。",kw={"德拉维主教","德拉维","埃林·提亚斯","圣光","乔贞","失踪的使节","暴风要塞"},ang={["class:Priest"]="身为牧师，你能看到Church of the Holy Light与暴风城的政治联系有多么紧密，信仰在这里与治国之术及秘密事务交织。",["faction:Alliance"]="身为联盟的一员，你能看到德拉维如何谨慎地展开调查，维护暴风城与吉安娜·普罗德摩尔的塞拉摩据点之间脆弱的和平。"},sec={{t="宫廷中的主教",b="德拉维主教在要塞内为暴风城宫廷提供谏言。大主教本尼迪塔斯照管光明大教堂，而德拉维则置身于贵族与请愿者之间。他既要提供精神指引，也要应对王国的政治事务。身在宫廷，他往往先于伯瓦尔·弗塔根公爵或年幼的安度因国王，听到私下流传的传闻与难以启齿的申诉。"},{t="一场谨慎的调查",b="一名使节的失踪，让德拉维主教卷入了一场秘密调查。这名使节奉命前往塞拉摩会见吉安娜·普罗德摩尔，却始终没有抵达。为了避免引发恐慌，宫廷对失踪一事秘而不宣。德拉维怀疑迪菲亚潜行者与此有关，于是绕过了常规的卫兵渠道。他依靠私人关系和行事谨慎的冒险者，通过渔夫乔贞等人，联络埃林·提亚斯这样的隐秘线人。"}},faq={{q="在哪里可以找到德拉维主教？",a="德拉维主教位于暴风要塞内的请愿者大厅，就在主入口通道旁，臣民们聚集于此，向王室宫廷请愿。",al={"德拉维位置","德拉维主教在哪里","德拉维要塞"}},{q="他在暴风要塞担任何种职务？",a="德拉维主教在暴风城王室宫廷中代表圣光教会。他处理教会事务，为贵族提供谏言，并为王国暗中处理敏感事务。",al={"德拉维职责","德拉维主教是谁","德拉维做什么"}},{q="他为何调查失踪的使节？",a="这名使节在前往塞拉摩会见吉安娜·普罗德摩尔的途中失踪。德拉维主教怀疑迪菲亚潜行者从中作梗，便通过可信的渠道展开调查，以免这场危机引起民众恐慌。",al={"失踪的使节德拉维","德拉维为何关心使节"}},{q="德拉维与埃林·提亚斯有何联系？",a="德拉维主教通过渔夫乔贞等中间人，向埃林·提亚斯传递消息。提亚斯是一位奶酪大师，暗中为SI:7搜集情报。",al={"德拉维与提亚斯","德拉维si7联络人"}}},fx={["9f3cf19d"]={q="德拉维主教是谁？",a="德拉维主教是圣光教会的一位人类高级教士，驻于暴风要塞。他作为教会派往王室宫廷的正式使者，负责处理贵族与摄政当局之间的教务和行政事务。",al={"德拉维是谁","德拉维主教的身份","德拉维主教是谁"}},["8f5e30a8"]={q="德拉维主教站在哪一边？",a="德拉维全心效忠圣光教会和暴风城的大联盟。他直接为王国的福祉效力，力求保护王室，并在恐慌蔓延到街头之前，悄然化解王国面临的威胁。",al={"德拉维的阵营","德拉维主教属于联盟吗","德拉维主教为谁效力"}},["663bbb38"]={q="德拉维主教想要什么？",a="德拉维想查明一位奉命前往塞拉摩的重要暴风城外交官失踪的真相。由于失踪的消息可能动摇宫廷的稳定，他打算借助可靠的第三方和秘密情报渠道，悄悄展开调查。",al={"德拉维想做什么","德拉维主教的目标","德拉维想要什么"}},["44aea1e7"]={q="德拉维主教为什么在暴风要塞？",a="德拉维住在觐见室，代表圣光教会面见伯瓦尔·弗塔根公爵和王廷。在这个职位上，他就教会事务向王室进言，并密切关注王国的政治动向。",al={"德拉维为什么在要塞","德拉维主教为什么在这里","德拉维 请愿者大厅"}}},fp="14,183,17.380.0,18.424.1,34.156.0,35.187.0,45.212.0,41.174.1"}
P.entries["npc:blanchy"] = {n="布兰契",s="老布兰契是西奥多和弗娜·法布隆忠诚勤劳的母马，如今正在西部荒野贾森农场附近的货车旁歇息。她性情温顺，食量惊人，远近闻名，在席卷乡间的动荡中，始终踏实地陪伴着主人。",h="老布兰契是西奥多和弗娜·法布隆忠诚勤劳的母马，如今正在西部荒野贾森农场附近的货车旁歇息。她性情温顺，食量惊人，远近闻名，在席卷乡间的动荡中，始终踏实地陪伴着主人。",kw={"布兰契","法布隆","贾森农场","燕麦","老布兰契","弗娜·法布隆","西部荒野"},ang={["faction:Alliance"]="对于从艾尔文森林南下进入西部荒野的联盟旅人来说，帮忙喂养老布兰契，往往是他们为当地艰难度日的难民所做的最初几件平凡善举之一。"},sec={{t="忠实的农场帮手",b="早在拉着法布隆一家的货车穿行于西部荒野的尘土之间以前，布兰契就在他们位于暴风城粮仓的农场里干活，以性情格外温顺、乖巧听话而闻名。多年的繁重劳作让她日渐衰老，成了“老布兰契”，而逃离动荡家园的艰辛旅途更让她疲惫不堪。尽管看上去十分疲倦，她的胃口依然很好，旅人若从周围的田野里收集几捧散落的营养燕麦带给她，弗娜就会以布兰契珍爱的毯子和饲料袋作为酬谢。"}},faq={{q="布兰契的主人是谁？",a="布兰契属于西奥多和弗娜·法布隆，这对农户夫妇正在西部荒野跋涉。她既是他们可靠的挽马，也是深受一家人喜爱的伙伴。",al={"布兰契的主人","布兰契属于谁","法布隆的马"}},{q="布兰契最初来自哪里？",a="没有记录说明布兰契出生在何处。据西部荒野的人们所知，她很早就是法布隆一家的马，一直在他们的农场干活，直到这家人不得不踏上旅途。",al={"布兰契的来历","布兰契来自哪里","年轻的布兰契"}},{q="弗娜·法布隆为什么需要燕麦来喂布兰契？",a="多年的劳作，加上沿西部荒野危险道路的长途跋涉，让老布兰契耗尽了力气。弗娜请路过的冒险者从附近农田里搜集剩下的燕麦袋，帮助这匹忠实的马恢复体力。",al={"布兰契的燕麦","为什么要喂布兰契","法布隆家的马疲惫"}},{q="在哪里能找到布兰契？",a="老布兰契拴在法布隆一家的货车旁，就在西部荒野北部贾森农场附近的大路边。",al={"布兰契的位置","老马布兰契在哪里","布兰契地图"}}},fp="7,170,19.436.0,17.122.0,39.180.0,46.211.0,27.116.0"}
P.entries["npc:blind-hunter"] = {n="盲眼猎手",s="盲眼猎手栖息在剃刀沼泽深处，那里终年不见阳光。这只行踪隐秘的白化蝙蝠在野猪人的据点中游猎，远离洞穴入口附近的普通蝙蝠。",h="盲眼猎手栖息在剃刀沼泽深处，那里终年不见阳光。这只行踪隐秘的白化蝙蝠在野猪人的据点中游猎，远离洞穴入口附近的普通蝙蝠。",kw={"白化蝙蝠","盲眼猎手","沼泽蝙蝠","沼泽野兽","稀有蝙蝠","剃刀沼泽"},ang={["class:Hunter"]="作为一名穿越贫瘠之地的驯兽师，你或许会看重盲眼猎手，想要驯服这只稀有的白化野兽，或从它身上获取地下出产的精良弓。"},sec={{t="沼泽深处",b="剃刀沼泽蜿蜒穿过地下的荆棘与幽暗洞穴。普通蝙蝠栖息在更靠近地表的地方，外界的微光还能照进那里。盲眼猎手则藏身于荆棘迷宫最深、最暗的洞窟。它苍白的皮肤和乳白色的眼睛，或许源于世代远离自然阳光的生活。"},{t="罕见的猎物",b="人们认为，盲眼猎手已经失去了大部分乃至全部正常视力。学者和斥候相信，它凭借敏锐的听觉和回声定位，在幽暗中追踪猎物。它极少现身，只偶尔在茂密的荆棘丛中狩猎。对洞穴探险者而言，能见到这只幽灵般的野兽，实属难得。"}},faq={{q="盲眼猎手是什么？",a="盲眼猎手是一只稀有的白化蝙蝠，栖息在剃刀沼泽最深、最暗的隧道中。它苍白的体色和隐秘的习性，使它有别于入口附近的普通蝙蝠。",al={"盲眼猎手是谁","盲眼猎手是什么","盲眼猎手蝙蝠"}},{q="盲眼猎手在哪里出没？",a="盲眼猎手栖息在剃刀沼泽内部幽暗的通道沿线，那里已在外界日光所能照及的范围之外。",al={"盲眼猎手位置","哪里能找到盲眼猎手","盲眼猎手刷新"}},{q="盲眼猎手真的失明了吗？",a="从盲眼猎手乳白色的眼睛和洞穴深处的栖息地来看，博物学家和冒险者怀疑它已经失明。凭借敏锐的听觉和回声定位，它依然能精准地捕猎。",al={"它是否失明","盲眼猎手能否看见"}},{q="猎人能驯服盲眼猎手吗？",a="能。能够驾驭飞行掠食者的驯兽师可以驯服盲眼猎手。只要有足够的耐心找到它，就能拥有这位独特的苍白伙伴。",al={"能否驯服盲眼猎手","盲眼猎手能否驯服","盲眼猎手宠物"}},{q="盲眼猎手为什么是白色的？",a="盲眼猎手是一只白化蝙蝠。与那些会靠近洞口的蝙蝠不同，它的体色可能是在远离阳光、永恒黑暗的环境中逐渐形成的。",al={"它为什么会白化","盲眼猎手为什么是白色的","白化蝙蝠"}},{q="它与普通的沼泽蝙蝠有什么不同？",a="普通的沼泽蝙蝠有着常见的深色体色，生活在更靠近入口、仍有光线照到的地方。盲眼猎手则通体苍白，深居简出，适应了隧道深处的生活。",al={"沼泽蝙蝠区别","沼泽蝙蝠与盲眼猎手对比"}}},fx={["7be10a10"]={q="盲眼猎手属于哪一方？",a="盲眼猎手是一头野兽，既不隶属于剃刀沼泽的野猪人，也不听命于任何外部势力。它是剃刀沼泽漆黑洞穴中的顶级捕食者，完全凭借动物本能生存，将任何闯入者都视为潜在猎物。",al={"盲眼猎手阵营","盲眼猎手是否与野猪人一伙","盲眼猎手属于哪一方"}},["5a3f492c"]={q="盲眼猎手想要什么？",a="作为一头未受驯服的地下生物，盲眼猎手没有政治野心，也没有恶意。它只是为了觅食而狩猎，并在剃刀沼泽最深处不见天日的洞穴中守卫自己与世隔绝的猎场，不让任何不幸闯入巢穴的人靠近。",al={"盲眼猎手的动机","盲眼猎手的目标","盲眼猎手想要什么"}},["66c6306f"]={q="盲眼猎手为什么在这里？",a="与在入口附近、阳光还能照进来的地方飞舞的普通沼泽蝙蝠不同，盲眼猎手栖息在剃刀沼泽最深处的漆黑地带。它早已习惯了永恒的黑暗，在远离地表的幽深洞穴中繁衍生息，从未见过光明。",al={"盲眼猎手为何在剃刀沼泽","盲眼猎手的位置缘由","盲眼猎手为何在这里"}}},fp="12,170,19.305.0,13.302.0,25.175.0,35.123.0,35.171.0,34.142.0,30.153.0,43.171.0"}
P.entries["npc:blind-mary"] = {n="盲眼玛丽",s="在夜色镇东南方的一座破败农舍里，盲眼玛丽化作饱受折磨的女妖，徘徊不去。她生前是个爱慕虚荣的美丽女子，但惨死与异变让她无法接受自己的模样，悲痛之下竟自残身体。",h="在夜色镇东南方的一座破败农舍里，盲眼玛丽化作饱受折磨的女妖，徘徊不去。她生前是个爱慕虚荣的美丽女子，但惨死与异变让她无法接受自己的模样，悲痛之下竟自残身体。",kw={"女妖","盲眼玛丽","夜色镇","暮色森林","幽灵的头发","出没之地","镜子","怨灵"},ang={["class:Priest"]="身为牧师，你能从玛丽身上看到一个因可怕创伤而失去归依的灵魂，因悲痛与虚荣困在生与永劫之间。",["faction:Alliance"]="身为联盟的守卫者，你能从玛丽的命运中看到，暮色森林的诅咒给普通居民带来了多么深重的灾难。",["profession:Tailoring"]="身为裁缝，你或许会寻找玛丽这样的幽灵，获取幽灵的发丝，这种精细的材料由虚无缥缈的残留物织成。"},sec={{t="虚荣的悲剧",b="在阴影笼罩暮色森林之前，玛丽曾以美貌闻名。她对此深感自豪，几乎总是带着心爱的镜子。亡灵席卷这片地区时，玛丽和许多邻居都惨遭杀害。她的灵魂未能在地下安息。她反而化作了虚无缥缈的女妖，被迫以骇人的半透明形态游荡于凡人的世界。"},{t="绝望中的失明",b="当玛丽醒来，发现自己已成为亡灵时，悲伤、恐惧与愤怒将她彻底吞没。她无法忍受镜中自己那可怕的模样，便徒手挖出了双眼。她丢弃了心爱的镜子，在荒废的家中飘荡，双目失明，哭泣不止，紧抓着生前那些模糊的记忆。"}},faq={{q="盲眼玛丽是谁？",a="盲眼玛丽是一个女妖，出没于夜色镇东南方的一处破败农庄。她生前是当地一位美丽的女子，在暮色森林陷入黑暗时遇害，随后以亡灵之身复起。",al={"盲眼玛丽是谁","盲眼玛丽的身世","盲眼玛丽的故事","暮色森林盲眼玛丽"}},{q="她为什么叫盲眼玛丽？",a="玛丽因自己的女妖形态而陷入悲痛与绝望，无法忍受镜中的倒影，于是挖出了自己的双眼。",al={"她为何失明","盲眼玛丽如何失去双眼","盲眼玛丽的眼睛"}},{q="盲眼玛丽住在哪里？",a="盲眼玛丽徘徊在一座名为玛丽的鬼屋的破旧农舍里，那里位于暮色森林东部、夜色镇的东南方。",al={"盲眼玛丽的位置","盲眼玛丽在哪里","盲眼玛丽出没之地"}},{q="盲眼玛丽会敌视活着的旅人吗？",a="盲眼玛丽不会一见到旅人就发动攻击。周围林地里的食尸鬼和骷髅充满敌意，她却始终困于哀痛之中，来到她破败家园的人可以与她交谈。",al={"盲眼玛丽是否有敌意","盲眼玛丽是否会攻击","能否与盲眼玛丽交谈"}},{q="玛丽的眼镜怎么了？",a="玛丽惊恐于自己的幽灵形态，挖出双眼后便丢弃了珍爱的镜子。它至今仍遗失在暮色森林幽魂出没的某个角落。",al={"玛丽的镜子","盲眼玛丽的镜子","她的镜子怎么了"}},{q="冒险者为什么要寻找盲眼玛丽？",a="旅人与当地工匠在夜色镇一带办事时，会前去探访玛丽。有些人为维克托·安特拉斯的观星装置寻找她旧日的镜子；另一些人则带来伊瓦夫人的鬼梳，采集幽灵的头发来制作特殊丝线。",al={"盲眼玛丽的任务","为何探访盲眼玛丽","盲眼玛丽的任务线"}}},fx={d3776a58={q="盲眼玛丽属于哪一方？",a="盲眼玛丽不属于任何军队或阵营。尽管她是暮色森林悲剧中诞生的女妖，却没有加入天灾军团，也没有向生者开战。她被困在孤独的苦痛之中，对四处游荡的冒险者保持中立；只要有人愿意聆听她的悲伤，或归还她前世的遗物，她便会与之交谈。",al={"盲眼玛丽属于联盟还是部落","盲眼玛丽的阵营","玛丽属于哪一方"}},["45d21972"]={q="盲眼玛丽想要什么？",a="玛丽渴望找回失去的美貌，无法忍受别人看见自己。她曾随身携带一面镜子，如今仍会向询问的人提起它。但有人给她带来一把梳子时，那只会让她想起自己如今的模样，于是她便将梳子送走。",al={"玛丽想要什么","盲眼玛丽追求什么","盲眼玛丽的愿望"}},["5b1d02ea"]={q="盲眼玛丽为什么在这里？",a="盲眼玛丽徘徊在夜色镇东南方的一座废弃农舍中，因为她正是在那里悲惨地死去的。她被肆虐暮色森林的游荡亡灵杀死，随后化作哭泣的女妖，因悲伤与疯狂而被束缚在昔日家园的废墟之中。",al={"盲眼玛丽为何在暮色森林","盲眼玛丽为何徘徊在农舍","盲眼玛丽的位置与故事"}}},fp="10,213,15.376.0,18.335.0,18.177.0,29.110.0,28.116.0,42.201.0,38.156.0,39.241.0"}
P.entries["npc:bloodmage-drazial"] = {n="血法师德拉吉亚",s="血法师德拉吉亚是一名研习奥术与鲜血魔法的血精灵，在诅咒之地北部扎营。他与妹妹莱诺雷一同研究这片赤红荒原上的本土野兽，为途经此地的冒险者调制强效炼金药剂。",h="血法师德拉吉亚是一名研习奥术与鲜血魔法的血精灵，在诅咒之地北部扎营。他与妹妹莱诺雷一同研究这片赤红荒原上的本土野兽，为途经此地的冒险者调制强效炼金药剂。",kw={"暴怒的野猪","诅咒之地","血法师","调制药剂","德拉吉亚","莱诺雷","厚甲蝎","弯牙"},ang={["class:Mage"]="德拉吉亚体现了血精灵中备受争议的一条异路：公开运用鲜血魔法和生物试剂，合成强化奥术能力的药剂，而非完全依赖传统的肯瑞托法术。"},sec={{t="赤红荒原的炼金研究",b="在悲伤沼泽通往诅咒之地的北部山口附近，血法师德拉吉亚研习着一种奇特的魔法。许多高等精灵对禁忌法术避之不及，或为奎尔萨拉斯的遭遇而绝望，德拉吉亚和妹妹莱诺雷却运用鲜血魔法，从恶劣的环境中汲取力量。荒原上遭到污染的动物——厚甲蝎、弯牙土狼和诅咒野猪——展现出异乎寻常的活力，德拉吉亚和莱诺雷认为，这源自黑暗之门开启时释放的能量。德拉吉亚采集这些生物的特定器官和组织，调制出性质不稳定的药剂，能使力量、敏捷和耐力在短时间内大幅提升。"},{t="独立的药剂供应者",b="与许多驻扎在诅咒之地的阵营人员不同，德拉吉亚行事务实，置身纷争之外。他并未正式效忠联盟或部落，而是选择以自己的炼金技艺，与任何足够坚韧、敢于深入荒原并收集他所需原料的人交易。只要旅人带来当地掠食者的器官，德拉吉亚就乐于让坩埚里的药剂继续翻滚。"}},faq={{q="血法师德拉吉亚是谁？",a="血法师德拉吉亚是一名驻扎在诅咒之地北部入口附近的血精灵法师。他与妹妹莱诺雷一同研究当地的野生动物，利用从这一带受腐化野兽身上收集的材料，调制强效炼金试剂。",al={"德拉吉亚是谁","德拉吉亚背景故事","血法师德拉吉亚非玩家角色"}},{q="德拉吉亚为什么收集动物的身体部位？",a="诅咒之地的生物已经适应了这片遭到污染、充斥着魔法能量的土地。德拉吉亚利用野猪、土狼、蝎子和石化蜥蜴蕴含强大力量的内脏，调制专门增强战士体能的药剂。",al={"德拉吉亚为什么要野猪肺","德拉吉亚任务物品","德拉吉亚动物器官"}},{q="德拉吉亚为联盟还是部落效力？",a="德拉吉亚对双方阵营都保持中立。他和莱诺雷并不关心暴风城与部落之间的战争，任何愿意为他们的魔法与炼金研究提供材料的冒险者，都能与他们交易。",al={"德拉吉亚阵营","德拉吉亚是部落还是联盟","联盟能否与德拉吉亚交谈"}},{q="与他一同扎营的另一名血精灵是谁？",a="他身旁的精灵是他的妹妹，血法师莱诺雷。兄妹二人一同研习鲜血魔法，用游荡在诅咒之地的各种野兽调制各具功效的药剂。",al={"德拉吉亚的同伴","谁和德拉吉亚在一起","莱诺雷"}}},fp="17,160,36.553.0,23.307.0,25.207.0,39.203.0,48.197.0,43.182.0"}
P.entries["npc:bloodmage-lynnore"] = {n="血法师莱诺雷",s="血法师莱诺雷是一名研习禁忌血魔法的血精灵，与她的兄弟德拉吉亚一同驻扎在诅咒之地北部入口附近。她用当地野兽的器官调制强效炼金药剂，为冒险者提供帮助。",h="血法师莱诺雷是一名研习禁忌血魔法的血精灵，与她的兄弟德拉吉亚一同驻扎在诅咒之地北部入口附近。她用当地野兽的器官调制强效炼金药剂，为冒险者提供帮助。",kw={"诅咒之地","血魔法","血法师莱诺雷","脑皮层混合饮料","砂囊口香糖","莱诺雷"},ang={["class:Mage"]="对于痴迷于非常规施法技艺的法师而言，莱诺雷代表着奥术哲学中一个鲜为人知且备受争议的分支，操纵的是生命精华，而非常规的魔网能量。",["faction:Horde"]="对部落旅人而言，莱诺雷是诅咒之地一位很有价值的联系人，无论来者属于哪个阵营，只要带来原料，就能换取她独特的炼金混合药剂。"},sec={{t="血魔法大师",b="血法师莱诺雷与她的兄弟德拉吉亚一同驻扎在诅咒之地北部入口附近，是东部王国极为罕见的精灵血魔法施法者之一。诅咒之地严酷而充满腐化的环境并未令她却步，她在此研究当地野兽体内潜藏的奥术能量与生命能量。旅人只要为她带来当地动物的脑和砂囊，就会发现她能将这些骇人的材料提炼成特殊药剂，大幅提升智力和精神。"}},faq={{q="血法师莱诺雷是谁？",a="血法师莱诺雷是一名血精灵血法师，驻扎在诅咒之地北部入口附近。她提供任务，也精通炼金术，用能够大幅提升属性的混合药剂换取野兽器官。",al={"莱诺雷是谁","血法师莱诺雷背景故事","莱诺雷诅咒之地"}},{q="在哪里可以找到血法师莱诺雷？",a="她与兄弟血法师德拉吉亚一同扎营在诅咒之地北部入口附近，从悲伤沼泽通往荒原的山口就在此处。",al={"莱诺雷位置","莱诺雷在哪里","如何找到血法师莱诺雷"}},{q="她会调制哪些药剂？",a="莱诺雷用从当地野生动物身上收集的器官——例如石化蜥蜴的脑、秃鹫的砂囊和弯牙土狼的颚肉——调制脑皮层混合饮料和砂囊口香糖等稀有补剂，能在较长时间内提升智力和精神。",al={"莱诺雷增益效果","诅咒之地消耗品","脑皮层混合饮料"}}},fp="17,172,21.401.0,25.180.0,37.173.0,31.205.0"}
P.entries["npc:bloodmage-thalnos"] = {n="血法师萨尔诺斯",s="血法师萨尔诺斯是一名骷髅施法者，盘踞在血色修道院的墓地区。他生前的身份无从查考，但亡灵瘟疫夺走了他的生命，如今他仍徘徊在十字军圣地的深处，渴望复仇。",h="血法师萨尔诺斯是一名骷髅施法者，盘踞在血色修道院的墓地区。他生前的身份无从查考，但亡灵瘟疫夺走了他的生命，如今他仍徘徊在十字军圣地的深处，渴望复仇。",kw={"血法师","墓地","血色修道院","骷髅","萨尔诺斯"},ang={["class:Mage"]="萨尔诺斯展现了瘟疫如何将一位天赋出众的施法者扭曲成满怀复仇欲望、依然操纵着火焰与暗影的怪物。",["class:Priest"]="萨尔诺斯伫立在墓穴之间，令人不安地昭示着：十字军纵有满腔狂热，也未能将黑暗挡在自己的圣地之外。",["faction:Horde"]="被遗忘者从萨尔诺斯身上看到了自己曾逃脱的命运：一个除复仇外再无其他意志的亡灵法师，潜伏在血色十字军自己修道院的腹地。"},sec={{t="死而复起的法师",b="没有记载说明萨尔诺斯生前是谁。无论他有过怎样的过去，亡灵瘟疫都夺走了他的生命。他既未得到净化，也未被彻底消灭，而是化作一具枯槁的骷髅重新站起，依然掌握着火焰魔法和精湛的奥术，并嘶喊着要复仇，要更多灵魂。"},{t="墓地之主",b="萨尔诺斯被困在修道院庭院墓穴的最深处，指挥幽灵和步履蹒跚的亡灵仆从，攻击任何惊扰他领地的人。他的存在对十字军而言是一个痛苦的矛盾：一头亡灵怪物就徘徊在他们神圣殿堂的下方，正是他们发誓要永远根除的恐怖化身。"}},faq={{q="血法师萨尔诺斯是谁？",a="萨尔诺斯是一名盘踞在修道院墓地的骷髅施法者。他生前的身份无从查考；亡灵瘟疫夺走了他的生命，他随后化作亡灵法师复起，依然渴望复仇。",al={"萨尔诺斯是谁","萨尔诺斯背景故事","血法师萨尔诺斯资料"}},{q="为什么血色修道院会容留一具亡灵骷髅？",a="十字军狂热地处决所有出现在眼前的亡灵，因此萨尔诺斯的存续显得格外反常。他藏身于墓地尽头，在亡灵复起的墓穴与幽魂之间，游荡在自己那片遭到亵渎的领地，而非自由行走于活着的十字军成员之中。",al={"萨尔诺斯为何在修道院","血色十字军为何容留萨尔诺斯","血色十字军亡灵法师"}},{q="萨尔诺斯掌握着什么力量？",a="尽管萨尔诺斯仍保留着血法师的头衔，并以骷髅之身复起，他掌握着火焰法术和暗影魔法，还会召唤复仇的幽魂与行尸，淹没闯入墓地的人。",al={"萨尔诺斯法术","血法师萨尔诺斯魔法","萨尔诺斯做什么"}},{q="萨尔诺斯曾是血精灵吗？",a="他生前所属的种族尚不确定。仅凭血法师这个头衔，无法断定他曾是血精灵。",al={"萨尔诺斯是高等精灵吗","萨尔诺斯种族","萨尔诺斯生前是什么种族"}},{q="谁想要萨尔诺斯死？",a="萨尔诺斯敌视闯入修道院墓地的人。这里并未确立这一时期有任何要求杀死他的具体委托。",al={"萨尔诺斯任务","谁想杀死萨尔诺斯","圣光的黑暗面 萨尔诺斯"}}},fx={ee50c387={q="血法师萨尔诺斯属于哪一方？",a="萨尔诺斯不为任何人效力。在屈服于亡灵瘟疫后，他变成了一个完全受复仇欲望与邪恶力量驱使的生物。如今，这具亡灵骷髅在修道院的墓地中牢牢守卫着自己的领地，驱使幽灵和僵尸般的生物，屠杀所有挡路的生者。",al={"萨尔诺斯的阵营","萨尔诺斯为谁效力","萨尔诺斯是否属于血色十字军"}},fb23ba27={q="血法师萨尔诺斯想要什么？",a="萨尔诺斯因亡灵之躯而发疯，除了邪恶的复仇，几乎别无所求。这位被束缚在修道院墓地中的复仇法师操纵着不安的幽灵和复活的尸体，想要消灭所有胆敢踏入他诅咒领地的人。",al={"萨尔诺斯想要什么","萨尔诺斯的目标","萨尔诺斯的动机"}},["39b55bcf"]={q="为什么人们惧怕血法师萨尔诺斯？",a="萨尔诺斯是一名强大的亡灵施法者，统治着修道院的墓地。他向入侵者投掷火焰与暗影，高喊着复仇与更多灵魂。这样一个生物潜伏在血色十字军自己的亡者之中，更让人不寒而栗。",al={"萨尔诺斯为何令人畏惧","萨尔诺斯因何闻名","血法师萨尔诺斯的名声"}}},fp="17,185,21.206.0,23.285.0,25.208.0,59.210.0,31.140.0,24.108.0,23.125.0"}
P.entries["npc:bluff-runner-windstrider"] = {n="雷霆崖信使斯塔德尔",s="在雷霆崖的台地上，雷霆崖信使斯塔德尔奔走于城中，传递紧急消息。他指引部落旅者前往遥远的边疆，包括灰谷、菲拉斯和瘟疫之地。",h="在雷霆崖的台地上，雷霆崖信使斯塔德尔奔走于城中，传递紧急消息。他指引部落旅者前往遥远的边疆，包括灰谷、菲拉斯和瘟疫之地。",kw={"灰谷","雷霆崖信使","莫沙彻营地","信使","莫高雷","雷霆崖","斯塔德尔"},ang={["faction:Horde"]="身为部落的一员，你可以将莫高雷的消息带往部落为资源与生存而战的前线。",["race:Tauren"]="身为牛头人，你可以延续信使的传统，不依靠机械或外族的邮政网络，维系各部族与中央长老之间的联系。"},sec={{t="台地上的信使",b="雷霆崖信使斯塔德尔在雷霆崖的高耸台地之间传递消息。他脚步迅捷，让城中的领袖和访客及时获知消息。他沿着绳桥和小径奔跑，沿途高声传达消息，递送公文。当卡利姆多或东部王国的哨站需要援军时，斯塔德尔便号召途经的勇士传递消息，响应战斗的召唤。"},{t="边疆的召唤",b="雷霆崖信使斯塔德尔传递的消息远达莫高雷之外。他派冒险者北上，前往灰谷的碎木岗哨，参加塞娜尼·雷心的大狩猎。他指引经验丰富的斥候南下，前往菲拉斯的莫沙彻营地，也传达有关西瘟疫之地亡灵威胁仍未消退的严峻警告。他递送的公文将莫高雷这片部族腹地与部落在各地的战事联系起来。"}},faq={{q="雷霆崖信使斯塔德尔是谁？",a="雷霆崖信使斯塔德尔在雷霆崖城中传递消息。他传达新闻，号召有能力的部落旅者为艾泽拉斯各地的紧急战事提供援助。",al={"斯塔德尔非玩家角色","雷霆崖信使","斯塔德尔是谁"}},{q="在哪里可以找到雷霆崖信使斯塔德尔？",a="雷霆崖信使斯塔德尔沿着雷霆崖的桥梁和台地奔跑。他常在中央台地与相邻的高地之间往返。",al={"斯塔德尔位置","雷霆崖信使在哪里","寻找斯塔德尔"}},{q="斯塔德尔提供哪些任务？",a="雷霆崖信使斯塔德尔指引旅者前往遥远的地区。他传达的召唤包括参加灰谷的狩猎、在菲拉斯建立莫沙彻营地，以及响应瘟疫之地的战斗号召。",al={"斯塔德尔任务","他提供什么","雷霆崖信使任务"}},{q="他为什么被称为“雷霆崖信使”？",a="雷霆崖崎岖的台地、峭壁和悬桥，可能让骑乘变得不便或缓慢。像斯塔德尔这样的信使靠双脚在城中传递消息。",al={"什么是雷霆崖信使","雷霆崖信使头衔"}}},fp="24,194,24.348.0,21.382.0,32.155.0,42.138.0,35.183.0,34.168.0"}
P.entries["npc:bolvar-fordragon"] = {n="伯瓦尔·弗塔根",s="瓦里安国王失踪期间，伯瓦尔·弗塔根在暴风要塞执掌王权与军队。身为摄政王和暴风城武装部队的最高统帅，他守在年幼的安度因国王身旁，竭力维系王国的团结。国内的动荡日益加剧，女伯爵卡特拉娜·普瑞斯托的建议却常常使他的军事决策迟迟无法落实。",h="瓦里安国王失踪期间，伯瓦尔·弗塔根在暴风要塞执掌王权与军队。身为摄政王和暴风城武装部队的最高统帅，他守在年幼的安度因国王身旁，竭力维系王国的团结。国内的动荡日益加剧，女伯爵卡特拉娜·普瑞斯托的建议却常常使他的军事决策迟迟...",kw={"安度因·乌瑞恩国王","伯瓦尔","弗塔根","大领主","卡特拉娜·普瑞斯托","摄政王","暴风要塞"},ang={["class:Paladin"]="身为圣骑士，即使政治阴谋日益增多，伯瓦尔依然体现着联盟的尚武理想：虔信圣光，坚定不移地履行对人民的职责。",["faction:Alliance"]="身为暴风城的最高统帅，伯瓦尔统领人类军队，在应对地方叛乱与履行联盟更广泛的责任之间权衡。"},sec={{t="王国摄政",b="瓦里安国王在前往塞拉摩岛参加和平峰会的途中失踪，暴风城随之陷入混乱。为了维持王位传承，年仅十岁的安度因王子加冕为王，伯瓦尔·弗塔根公爵则以摄政王的身份承担起治理王国的重任。\n\n伯瓦尔是一位备受尊崇、忠于王室的圣骑士，如今却要面对一个内外交困的王国。暴风城的士兵分散在西部荒野、赤脊山和暮色森林各地，兵力捉襟见肘。女伯爵卡特拉娜·普瑞斯托不以为意，一再阻挠他派遣王国军队驰援边境城镇。"},{t="欺诈之网",b="城镇的行政官和边境的治安官恳求增援，以抵御迪菲亚潜行者和黑石兽人。普瑞斯托女士暗中左右王室法令，对每一份险情报告都嗤之以鼻。伯瓦尔尊重贵族的意见，因此在得到无可辩驳的证据之前，迟迟不愿采取行动。不知不觉间，他让王室陷入了无力作为的境地。\n\n当有力的证据送达时，摄政王便会将宫廷惯例放在一旁。来自塞拉摩调查人员的警告，或是前线军官失踪的消息，都可能促使他向独立行事的冒险者求助。"}},faq={{q="为什么由伯瓦尔执政，而不是瓦里安国王？",a="瓦里安·乌瑞恩国王乘船前往塞拉摩岛参加外交峰会时离奇失踪。为了维持政局稳定，他十岁的儿子安度因加冕为王。伯瓦尔·弗塔根公爵出任摄政王，在找到瓦里安之前治理王国、统率军队。",al={"国王在哪里","为什么由伯瓦尔掌权","摄政王是谁"}},{q="为什么伯瓦尔不派兵援助赤脊山或西部荒野？",a="暴风城的常备军既要守卫腹地，又要保卫边境，兵力捉襟见肘。伯瓦尔的首席顾问女伯爵卡特拉娜·普瑞斯托一再质疑来自湖畔镇等地的报告，称其夸大其词，并劝他不要派遣王国军队。由于缺乏军事证据，伯瓦尔转而授权独立行事的冒险者介入。",al={"为什么没有暴风城军队","伯瓦尔为什么不派援军","湖畔镇军队"}},{q="伯瓦尔与女伯爵卡特拉娜·普瑞斯托是什么关系？",a="女伯爵卡特拉娜·普瑞斯托是暴风城王室的首席顾问。伯瓦尔尊重她的政治判断，也认可她对贵族事务的了解，但她不断劝他保持克制，建议他不要理会有关巨龙、兽人和迪菲亚阴谋的报告。",al={"伯瓦尔与普瑞斯托","普瑞斯托女士与伯瓦尔的关系"}},{q="伯瓦尔与年幼的安度因王子有什么关系？",a="伯瓦尔与安度因并无亲缘关系，却是这位年幼国王坚定的保护者、监护人和导师。他守在暴风要塞内安度因的王座旁，保护他免受宫廷阴谋的侵害，并在瓦里安归来之前确保乌瑞恩王朝稳固。",al={"安度因与伯瓦尔","伯瓦尔是安度因的父亲吗"}}},fx={["634d3c0f"]={q="伯瓦尔·弗塔根公爵是谁？",a="伯瓦尔·弗塔根公爵是一位备受敬重的圣骑士，也是暴风城的摄政王。瓦里安·乌瑞恩国王离奇失踪后，他身为王国军队的最高统帅，代年幼的安度因·乌瑞恩国王执掌政务。他以高尚的品格和荣誉感闻名，在暴风城最为脆弱的时期之一，肩负着维持秩序和保卫王国的重任。",al={"伯瓦尔是谁","伯瓦尔的身份","大领主伯瓦尔是谁"}},["946cb7aa"]={q="伯瓦尔·弗塔根效忠哪一方？",a="伯瓦尔全心效忠于暴风城王国和联盟。他首先忠于乌瑞恩家族，竭力保护年幼的安度因王子，并在政局严重动荡、驻军兵力不足的情况下，努力保卫王国的领土。",al={"伯瓦尔效忠对象","伯瓦尔属于什么阵营","伯瓦尔阵营"}},["309206e7"]={q="伯瓦尔·弗塔根想要什么？",a="伯瓦尔最希望维持暴风城的稳定，查明失踪的瓦里安国王的下落，并保护年幼的安度因·乌瑞恩国王，免遭那些企图利用他年幼无知之人的算计。他努力应对迪菲亚潜行者和黑石兽人日益增长的威胁，试图在保卫赤脊山和西部荒野等边远领地与听取王廷建议之间取得平衡。",al={"伯瓦尔的目标","伯瓦尔想做什么","伯瓦尔的动机"}},e6552818={q="伯瓦尔·弗塔根为什么出名？",a="伯瓦尔是一位以非凡的决心、英勇和坚定不移的道德信念著称的圣骑士。身为大领主、摄政王和暴风城军队的最高统帅，他的领导才能与坚贞的荣誉感，使他成为整个联盟最受尊敬的军事人才和圣骑士之一。",al={"伯瓦尔为什么出名","伯瓦尔的声望","伯瓦尔是否有名"}}},fp="16,333,19.514.0,15.531.1,44.297.0,60.355.0,56.256.0,51.248.0"}
P.entries["npc:braelyn-firehand"] = {n="布莱林·火拳",s="布莱林·火拳住在烈日石居的部落成员之中，招揽旅人参与对抗石爪峰暗夜精灵的行动。",h="布莱林·火拳住在烈日石居的部落成员之中，招揽旅人参与对抗石爪峰暗夜精灵的行动。",kw={"布莱林","塞纳留斯","火手","上层精灵","奥达努斯","石爪山","烈日石居"},ang={["class:Druid"]="身为德鲁伊，你知道，屠杀塞纳留斯的子嗣、劫掠猛禽洞穴，都是破坏自然平衡的罪行。",["class:Mage"]="身为法师，你或许能理解布莱林所说的魔网能量和魔法阻塞。她试图争取那些了解大地上奥术魔法流动的人。",["faction:Horde"]="身为部落的一员，你会发现布莱林正在雇用流浪者袭击暗夜精灵。双方在卡利姆多的领土冲突掩盖了她更深层的图谋。"},sec={{t="意外的来客",b="在烈日石居，血精灵布莱林·火拳公然住在牛头人的屋舍与兽人的帐篷之间。营地的萨满和酋长们容许她留在这里，似乎并不知道她真正效忠于谁。她自称在观察这一带的魔法，并雇用路过的部落佣兵，在险峻的山间执行危险的任务。"},{t="对林地的仇怨",b="布莱林·火拳派盟友攻击石爪峰的暗夜精灵德鲁伊和塞纳留斯的神圣子嗣。她声称，德鲁伊阻塞了魔网能量的流动，妨碍了群峰间的奥术力量。她的怨恨源于私仇：在她的记忆中，守护者奥达努斯傲慢自大，认为自己甚至凌驾于上层精灵之上。她付钱雇用部落旅人追杀他，并带回他的首级。"},{t="与加德纳尔的联系",b="布莱林·火拳的仇恨为费伍德森林加德纳尔的暗影议会教派效力。她怂恿部落勇士杀死守卫神圣群峰的暗夜精灵和守护者，为更黑暗的力量扫清道路，同时以边境冲突为掩护，隐瞒自己的关系。"}},faq={{q="布莱林·火拳是谁？",a="布莱林·火拳是一名精灵法师，住在石爪山脉的烈日石居。尽管身处部落之中，她仍在以奥术力量对付守卫石爪峰的暗夜精灵。",al={"布莱林是谁","布莱林·火拳的故事","烈日石居的精灵"}},{q="为什么一个精灵会住在烈日石居？",a="烈日石居是一处偏僻的边境营地，容许布莱林留在那里。她利用络绎不绝的部落战士，雇人攻击暗夜精灵，而不会立刻引起营地首领的怀疑。",al={"她为何与部落为伍","布莱林为何在烈日石居","石爪山的血精灵"}},{q="她想让人在石爪峰做什么？",a="布莱林要求旅人攻击石爪峰的德鲁伊和塞纳留斯的子嗣，声称他们阻碍了魔法的流动。她对守护者奥达努斯的追杀延伸到了灰谷的林中树居。",al={"布莱林的任务目标","为何杀死奥达努斯","布莱林·火拳的任务"}},{q="她与守护者奥达努斯有何过往？",a="布莱林声称，在遥远的过去，她曾与守护者奥达努斯有过私交。她对他极度傲慢的态度怀恨在心，并说他认为自己甚至比古老的上层精灵更高贵。",al={"布莱林与奥达努斯","她如何认识奥达努斯","奥达努斯的过往"}},{q="布莱林·火拳声称自己在研究什么？",a="布莱林声称，石爪峰的德鲁伊和塞纳留斯的子嗣限制了魔法的流动。她想除掉他们，好让自己汲取那股力量。",al={"布莱林的真正阵营","布莱林与暗影议会","她为谁效力"}},{q="布莱林是法师还是术士？",a="布莱林修习奥术魔法，并使用火球术战斗。",al={"布莱林的职业","布莱林是术士吗","布莱林·火拳的法术"}}},fx={deec6fbf={q="布莱林·火拳与谁有关联？",a="布莱林为加德纳尔的一位主子效力，并与暗影议会有所牵连。她招募部落旅人，派他们袭击暗夜精灵和塞纳留斯的子嗣。",al={"布莱林·火拳的关系","布莱林与谁有联系","布莱林·火拳的盟友"}}},fp="16,139,17.314.0,26.380.1,16.270.1,24.202.0,42.208.0,43.203.0,40.184.0,51.148.2,31.57.2"}
P.entries["npc:braenna-flintcrag"] = {n="布莱纳·火崖",s="在铁炉堡的秘法区，布莱纳·火崖传授圣光之道。她训练牧师掌握治疗与精神修行，并在来访的暗夜精灵牧师被召回达纳苏斯的月神殿时，将消息告知他们。",h="在铁炉堡的秘法区，布莱纳·火崖传授圣光之道。她训练牧师掌握治疗与精神修行，并在来访的暗夜精灵牧师被召回达纳苏斯的月神殿时，将消息告知他们。",kw={"布莱纳·火崖","秘法大厅","圣光","铁炉堡","秘法区","牧师训练师","返回家园"},ang={["class:Priest"]="身为联盟牧师，你可以在铁炉堡向布莱纳·火崖学习必备法术，研习圣光之道。",["race:Dwarf"]="身为矮人，你可以从布莱纳·火崖的工作中，看到铁炉堡在尚武传统之外对圣光的虔诚。"},sec={{t="秘法大厅的引路人",b="布莱纳·火崖在秘法大厅训练牧师。在铁炉堡的秘法区，她教导矮人学徒运用圣光治疗伤者、施放防护结界。她的教诲让他们做好准备，应对危险的世界。在这座以熔炉和勇士闻名的城市里，她以这份职责照料着卡兹莫丹的精神需求。"}},faq={{q="布莱纳·火崖是谁？",a="布莱纳·火崖在铁炉堡的秘法大厅训练牧师。她传授神圣的祷言、法术与精神修行之道。",al={"布莱纳·火崖","布莱纳是谁","牧师训练师布莱纳"}},{q="在哪里可以找到布莱纳·火崖？",a="布莱纳·火崖位于铁炉堡秘法区内的秘法大厅。",al={"布莱纳在哪里","布莱纳·火崖的位置","寻找布莱纳·火崖"}},{q="她为旅人提供哪些服务？",a="布莱纳·火崖训练联盟牧师，帮助他们提升阶位。她还会在来访的暗夜精灵牧师被召回达纳苏斯的月神殿时，将消息告知他们。",al={"布莱纳的服务","布莱纳做什么","布莱纳能训练我吗"}},{q="她在卡兹莫丹还有其他亲属吗？",a="布莱纳·火崖与苏尔曼·火崖同姓。这个姓氏暗示她与卡兹莫丹的一个显赫矮人家族有所关联。",al={"火崖家族","苏尔曼·火崖的亲属","布莱纳·火崖的亲属"}}},fx={d5abdbfc={q="布莱纳·火崖效忠哪一方？",a="布莱娜忠于联盟和矮人的铁炉堡王国。她在秘法大厅与其他学者、秘法研究者和神圣之道的修习者共事，通过圣光的教诲和精神修行，为自己的人民和整个联盟效力。",al={"布莱纳·火崖阵营","布莱纳为谁效力","布莱纳·火崖联盟"}},["787cf3cf"]={q="布莱纳·火崖想要什么？",a="布莱娜致力于引导虔诚的信徒，为他们探索圣光的奥秘做好准备。她在铁炉堡悉心训练立志成为牧师的矮人，确保他们具备帮助族人、保卫联盟所需的坚定意志和神圣技艺。",al={"布莱纳想要什么","布莱纳·火崖的目标","布莱纳·火崖的目的"}},["19ad6f1b"]={q="布莱纳·火崖为什么在这里？",a="布莱娜住在铁炉堡秘法区内的秘法大厅，这里是首都研究神圣之道和修习魔法的圣所。她与其他导师一同驻守于此，随时为途经这座山中城市或在此效力的牧师提供帮助和指导。",al={"布莱纳为什么在这里","布莱纳为什么在铁炉堡","布莱纳·火崖在此的原因"}}},fp="17,240,32.337.0,25.126.0,35.78.0,44.175.0,44.135.0"}
P.entries["npc:brainwashed-noble"] = {n="被洗脑的贵族",s="在死亡矿井外围的洞穴深处，被洗脑的贵族仍被迪菲亚潜行者控制着。附魔剥夺了他的意志，如今他与亡灵仆从一同守卫他们的藏身之处，不再漫步于暴风城的宏伟厅堂。",h="在死亡矿井外围的洞穴深处，被洗脑的贵族仍被迪菲亚潜行者控制着。附魔剥夺了他的意志，如今他与亡灵仆从一同守卫他们的藏身之处，不再漫步于暴风城的宏伟厅堂。",kw={"被洗脑的贵族","死亡矿井","迪菲亚潜行者","贵族","月溪镇","暴风城","西部荒野"},ang={["class:Mage"]="身为法师，你能认出被洗脑的贵族所用的魔法法杖，以及Polymorph之类的奥术法术。这些迹象表明，在心智遭到摧残之前，他曾在首都接受过正规的魔法训练。",["race:Human"]="身为人类，看到王国的一位贵族在西部荒野地下沦为毫无心智的哨兵，你便能明白迪菲亚潜行者对暴风城统治阶层的仇恨有多深。"},sec={{t="兄弟会的傀儡",b="被洗脑的贵族游荡在通往死亡矿井的通道中，与匪徒和腐尸为伍。他华贵的衣着表明他可能出身于暴风城的贵族，或许是现任成员，也可能是某位成员的后裔。艾德温·范克里夫俘虏了他。迪菲亚潜行者没有索要赎金，而是选择用附魔扭曲他的心智，让他成为守卫藏身之处的施法者。暴风城重建后，那些贵族拒绝支付报酬，迪菲亚潜行者对他们的仇恨甚至延伸到了西部荒野地下的洞穴中。"}},faq={{q="被洗脑的贵族是谁？",a="被洗脑的贵族是一名人类贵族，据信属于暴风城的贵族。迪菲亚潜行者俘虏了他，并在死亡矿井的洞穴深处用魔法控制了他。",al={"被洗脑的贵族是谁","被洗脑的贵族是什么","死亡矿井中的贵族"}},{q="为什么一名暴风城贵族会在死亡矿井的洞穴里？",a="暴风城重建后留下的欠款，让迪菲亚潜行者对城中的贵族怀有深切的仇恨。俘获一名贵族，既能让他用魔法为他们效劳，也能让他们借此泄愤。",al={"他为什么在死亡矿井","贵族为什么在洞穴里"}},{q="在哪里能找到被洗脑的贵族？",a="被洗脑的贵族游荡在月溪镇通往死亡矿井入口的洞穴隧道中，那些通道里盘踞着骷髅亡灵。",al={"被洗脑的贵族位置","他在哪里出现"}},{q="他是如何被洗脑的？",a="没人知道是哪位施法者给他洗了脑。西部荒野的迪菲亚潜行者中，那些叛变的施法者和附魔师能够用巫术扭曲俘虏的心智。",al={"谁给他洗了脑","他是如何被控制的"}}},fx={["7d2ae820"]={q="被洗脑的贵族效忠哪一方？",a="他为迪菲亚潜行者效力，却并非出于自愿。这名贵族俘虏被剥夺了自主意志，如今守卫着通往艾德温·范克里夫据点的隧道网络，用自己的奥术攻击任何闯入匪徒领地的人。",al={"被洗脑的贵族所属一方","被洗脑的贵族为谁而战","被洗脑的贵族是否属于迪菲亚"}},["0b33d704"]={q="被洗脑的贵族与谁有关联？",a="他过去与暴风城的贵族有联系，这些掌权贵族目前在伯瓦尔·弗塔根公爵麾下治理王国。然而，如今他的心智已被摧毁，完全受制于艾德温·范克里夫和那些在月溪镇矿井深处操控他的迪菲亚密谋者。",al={"被洗脑的贵族的关联","谁控制被洗脑的贵族","被洗脑的贵族阵营"}}},fp="17,224,25.460.1,29.181.0,52.204.1,41.143.1,23.151.0"}
P.entries["npc:brandur-ironhammer"] = {n="布兰度尔·铁锤",s="在铁炉堡，布兰度尔·铁锤教导年轻的圣骑士领悟圣光，并派遣他们前往联盟各地。",h="在铁炉堡，布兰度尔·铁锤教导年轻的圣骑士领悟圣光，并派遣他们前往联盟各地。",kw={"布兰度尔","秘法大厅","铁炉堡","铁锤","秘法区","圣骑士","蒂萨·热炉","圣洁之书","训练师"},ang={["class:Paladin"]="作为矮人或联盟圣骑士，你可以在铁炉堡向布兰度尔学习战斗技巧与神圣的圣印，再遵循他的指引，接受更高阶的神圣试炼。",["race:Dwarf"]="作为矮人，你也承袭了卡兹莫丹的圣骑士传统，在铁炉堡将战斗的钢铁之力与对圣光的崇敬融为一体。"},sec={{t="秘法区的引路人",b="在秘法大厅，布兰度尔·铁锤向初入门的圣骑士传授圣光之道。他与蒂萨·热炉引导年轻的矮人勇士完成圣洁之书的试炼。蒂萨曾直言布兰度尔的缺点。他努力克制自己的嫉妒，保持圣光战士应有的内心纯洁。"},{t="联结白银之手",b="布兰度尔将铁炉堡与联盟各地的圣骑士同袍联系在一起。来到这座山城的人类新兵会被派往南方，去光明大教堂寻找达索瑞恩·拉尔。经验丰富的圣骑士则会前往西瘟疫之地的寒风营地等战场。久经沙场的十字军战士会被指引去寻找格雷森·沙东布瑞克公爵，接受艰巨的战马试炼。"}},faq={{q="布兰度尔·铁锤在哪里？",a="布兰度尔·铁锤位于铁炉堡北部秘法区的秘法大厅内。",al={"布兰度尔·铁锤位置","寻找布兰度尔·铁锤","布兰度尔在哪"}},{q="布兰度尔·铁锤对圣骑士起着什么作用？",a="布兰度尔·铁锤训练新晋圣骑士，引导新兵完成圣洁之书，并指引经验丰富的圣骑士前往联盟各地，接受更高阶的试炼。",al={"布兰度尔圣骑士训练师","布兰度尔做什么","布兰度尔作用"}},{q="布兰度尔在秘法大厅的同僚是谁？",a="布兰度尔与蒂萨·热炉共事，后者也是秘法大厅内的一位矮人圣骑士训练师。蒂萨曾指出他的嫉妒心，而布兰度尔正努力克服它。",al={"布兰度尔同伴","谁与布兰度尔共事","蒂萨·热炉关系"}},{q="布兰度尔为什么派圣骑士前往暴风城？",a="布兰度尔将那些在铁炉堡受训的人类圣骑士派往暴风城的光明大教堂，寻找达索瑞恩·拉尔或格雷森·沙东布瑞克公爵，完成他们所属王国的正式仪式。",al={"布兰度尔暴风城任务","为什么去找达索瑞恩·拉尔","布兰度尔人类圣骑士"}},{q="布兰度尔与对抗天灾军团的战斗有联系吗？",a="有。布兰度尔传达阿什拉姆·瓦罗菲斯特指挥官的紧急召集，派遣已证明自身纯洁与英勇的圣骑士前往西瘟疫之地边境的寒风营地，支援联盟的征战。",al={"布兰度尔瘟疫之地","寒风营地布兰度尔","阿什拉姆·瓦罗菲斯特布兰度尔"}}},fx={ce9b1d9f={q="布兰度尔·铁锤是谁？",a="布兰度尔·铁锤是一名矮人圣骑士训练师，驻守在铁炉堡秘法区内的秘法大厅。他献身圣光，在战斗、信仰和美德方面指导成长中的圣骑士，引领矮人新兵和人类盟友接受考验、拜访导师，以磨砺他们履行神圣使命的本领。",al={"布兰度尔·铁锤","布兰度尔是谁","布兰度尔的故事"}},d07784b0={q="布兰度尔·铁锤效忠哪一方？",a="布兰度尔坚定地效忠于铁炉堡王国和大联盟。他为信奉圣光的圣骑士效力，与暴风城的其他守卫者密切合作，并传达征召，支援在前线对抗天灾军团的联盟指挥官。",al={"布兰度尔·铁锤阵营","布兰度尔为谁效力","布兰度尔联盟"}},cf78f4b8={q="布兰度尔·铁锤想要什么？",a="布兰度尔希望培养出有能力、秉持正义的新一代圣骑士，保卫联盟，对抗威胁艾泽拉斯的黑暗。在个人修行上，他努力克服自身的缺点，曾向同僚蒂萨·热炉发誓，要努力战胜心中挥之不去的嫉妒。",al={"布兰度尔的目标","布兰度尔想要什么","布兰度尔的目的"}},["65b7f94c"]={q="布兰度尔·铁锤为什么在铁炉堡？",a="他驻守在秘法大厅，为矮人首都的神圣战士充当明灯和导师。在这里，他传授武艺和精神修行之道，考验新手，并与联盟各地的导师协调，确保圣光骑士做好战斗准备。",al={"布兰度尔为什么在这里","布兰度尔在秘法大厅","布兰度尔为什么在铁炉堡"}}},fp="18,108,26.330.0,26.354.0,36.98.0,52.156.0,47.168.0,49.177.0,63.204.0"}
P.entries["npc:brann-bronzebeard"] = {n="布莱恩·铜须",s="布莱恩·铜须是麦格尼国王和被认为已经身亡的穆拉丁的幼弟，作为无与伦比的探险家、考古学家和探险者协会的创始领袖之一，闻名于艾泽拉斯。他对泰坦遗迹和远古历史有着永不满足的好奇心，漫游四方的渴望驱使他深入希利苏斯危机四伏的荒野。他在希利苏斯南部的野外同伴正等待着他最近一次探险的消息。",h="布莱恩·铜须是麦格尼国王和被认为已经身亡的穆拉丁的幼弟，作为无与伦比的探险家、考古学家和探险者协会的创始领袖之一，闻名于艾泽拉斯。他对泰坦遗迹和远古历史有着永不满足的好奇心，漫游四方的渴望驱使他深入希利苏斯危机四伏的荒野...",kw={"安其拉","布莱恩","铜须","探险者协会","弗兰卡","格里布","纳塔莉亚·玛尔利斯","鲁特加尔","甲虫之墙","希利苏斯"},ang={["faction:Alliance"]="布莱恩的探险工作直接充实了联盟的知识和档案，不过他动辄消失得无影无踪的习惯，常常让铁炉堡的领导者们焦头烂额。",["race:Dwarf"]="作为麦格尼国王的幼弟，布莱恩体现了矮人对探寻自身泰坦传承根源的热忱。"},sec={{t="王室漫游者",b="长兄麦格尼坐镇王座统治铁炉堡，穆拉丁则曾在战场前线效力，而布莱恩选择了辽阔的荒野。他是一名参加过 第二次大战 的老兵。然而，和平岁月让他将强健的体魄用于发掘被遗忘的往昔。作为探险者协会的领袖之一，布莱恩绘制了东部王国大片地域的地图，从艾尔文森林到祖尔格拉布的蛮荒丛林，随后又将目光投向无尽之海彼岸，探寻古老卡利姆多的奥秘。"},{t="希利苏斯的危机",b="塞纳里奥议会传来关于上古之神克苏恩和沉睡的 其拉 虫群的报告，吸引布莱恩南下，与探险同伴鲁特加尔·雕石和弗兰卡·石桥一同在希利苏斯南部建立了铜须营地。流沙中低语的恐怖存在令女祭司纳塔莉亚玛尔利斯神志失常，她突袭了他们的营地，灾难随之降临。她要求布莱恩带他们返回雷戈虫巢，遭到拒绝后便发狂发动攻击，布莱恩、他的队员和他的宠物猿格里布勉强才将她击退。"},{t="甲虫之墙的彼端",b="在那场可怕的袭击之后，这位无畏的考古学家没有退却，反而一心想要进入甲虫之墙后方被封闭的王国。布莱恩发现了一条隐秘的地下隧道，能完全绕过这道古老的屏障，于是独自进入其中，将格里布留给探险队照料，并留下严格的书面命令，要求为这只猿提供充足的食物、水和充满关爱的拥抱。他的同伴仍被困在希利苏斯南部，焦急地等待着异种虫巢穴内部传来的消息。"}},faq={{q="布莱恩·铜须是谁？",a="他是铁炉堡的国王麦格尼·铜须的幼弟，也是矮人探险者协会的共同创始人和中坚力量。布莱恩没有安坐议事厅，而是作为一位传奇考古学家和制图师，游历艾泽拉斯最危险的边疆，寻找泰坦神器和失落的文明。",al={"布莱恩 是谁","布莱恩 的故事","布莱恩·铜须 的背景故事"}},{q="布莱恩·铜须现在在哪里？",a="他的踪迹通向希利苏斯，鲁特加尔·雕石和弗兰卡·石桥正在那里维持铜须营地的运作。他们或许知道他最近一次探险的消息。",al={"布莱恩 的位置","哪里能找到 布莱恩","布莱恩 在希利苏斯哪里"}},{q="他在希利苏斯的营地发生了什么？",a="鲁特加尔·雕石和弗兰卡·石桥带来了有关探险队的坏消息。与他们交谈，就能得知营地里发生了什么。",al={"铜须营地发生了什么","谁袭击了 布莱恩 的营地","纳塔莉亚 袭击 布莱恩"}},{q="格里布是谁？",a="格里布是布莱恩·铜须的猿类伙伴，目前与探险者们一起待在希利苏斯的铜须营地。",al={"猿 格里布","布莱恩 的猴子","布莱恩 的宠物"}},{q="布莱恩参加过 第二次兽人战争 吗？",a="是的。布莱恩是一名参加过 第二次兽人战争 的老兵，不过在和平时期，他将自己的力量用于发掘被遗忘的往昔。",al={"布莱恩 与 第二次战争","布莱恩 是否在联盟军队服役","布莱恩 和 穆拉丁 的战争经历"}},{q="布莱恩为什么对希利苏斯感兴趣？",a="塞纳里奥议会中有关上古之神克苏恩、泰坦历史和被困的 其拉 帝国的传闻吸引布莱恩来到这片沙漠，促使他寻找穿过封闭的甲虫之墙的道路，亲自考察其中的遗迹。",al={"布莱恩 为什么去希利苏斯","布莱恩 去希利苏斯的目的","布莱恩 与 克苏恩"}}},fp="17,330,16.414.0,19.475.1,22.402.1,25.291.0,37.165.0,38.152.0,13.115.0,34.129.0,36.240.0"}
P.entries["npc:branstock-khalder"] = {n="布兰斯托克·卡德尔",s="在寒脊山谷的安威玛尔，布兰斯托克·卡德尔引导矮人牧师研习圣光，并留意哨站外穴居人的威胁。",h="在寒脊山谷的安威玛尔，布兰斯托克·卡德尔引导矮人牧师研习圣光，并留意哨站外穴居人的威胁。",kw={"安威玛尔","布兰斯托克","寒脊","丹莫罗","卡德尔","圣光","牧师","训练师"},ang={["class:Priest"]="作为牧师，你遇到的第一位精神导师便是布兰斯托克·卡德尔。他教你最初的神圣符文，并带你入门，学习圣光的治疗与防御之术。",["race:Dwarf"]="作为矮人，你能从布兰斯托克身上看到对圣光的务实信仰，以及面对严寒和穴居人威胁时的坚韧。"},sec={{t="寒脊的指引者",b="在安威玛尔，布兰斯托克·卡德尔教导牧师新手最初的祷文与神圣符文。他引导他们研习圣光，而穴居人正威胁着当地的巡山人。当新手学有所成，布兰斯托克便派他们穿过寒脊山小径，前往卡拉诺斯。在那里，他们可以向他的上级马克萨恩·安沃尔神父寻求进一步的指引。"}},faq={{q="布兰斯托克·卡德尔是谁？",a="在寒脊山谷的安威玛尔，布兰斯托克·卡德尔训练年轻的矮人牧师研习圣光，并指引他们度过山谷中的种种艰难。",al={"布兰斯托克背景故事","布兰斯托克是谁","安威玛尔牧师训练师"}},{q="布兰斯托克接下来会派学生去哪里？",a="布兰斯托克派年轻的牧师穿过寒脊山小径，前往卡拉诺斯，向他的上级马克萨恩·安沃尔神父寻求进一步的指引。",al={"布兰斯托克之后去哪里","布兰斯托克后续任务","从安威玛尔出发的牧师之路"}},{q="布兰斯托克担忧寒脊山谷中的什么事情？",a="布兰斯托克担忧寒脊山谷日益严重的穴居人威胁，以及它给当地巡山人带来的危险。",al={"安威玛尔的难题","布兰斯托克的担忧","寒脊穴居人威胁"}},{q="他会对非牧师说些什么？",a="布兰斯托克劝你永远不要背弃圣光。信仰也许有一天会救你一命。",al={"布兰斯托克语录","布兰斯托克闲聊文本"}}},fx={ac45145a={q="布兰斯托克·卡德尔效忠哪一方？",a="布兰斯托克坚定地站在铁炉堡和联盟一边。身为圣光的牧师，他致力于培养初出茅庐的矮人牧师，同时保护寒脊山谷免受外来威胁。",al={"布兰斯托克·卡德尔阵营","布兰斯托克·卡德尔为谁效力","布兰斯托克·卡德尔效忠对象"}},["48c1936a"]={q="布兰斯托克·卡德尔想要什么？",a="布兰斯托克希望教导初入门的侍僧遵循圣光之道，确保他们具备在安威玛尔之外生存的坚韧意志。他也希望当地的穴居人威胁能在彻底淹没寒脊山谷之前得到遏制。",al={"布兰斯托克·卡德尔的目标","布兰斯托克想要什么","布兰斯托克·卡德尔的目的"}},["0b38c258"]={q="布兰斯托克·卡德尔为什么在寒脊山谷？",a="布兰斯托克驻守在安威玛尔，迎接刚刚觉醒的牧师，教导他们基础祷言和神圣修行之道。在这处宁静的驻地，他帮助年轻的新手做好准备，再指引他们前往卡拉诺斯。",al={"布兰斯托克·卡德尔为什么在这里","布兰斯托克在安威玛尔的目的","布兰斯托克为什么在安威玛尔"}},["15965ad4"]={q="布兰斯托克·卡德尔与谁有关联？",a="布兰斯托克听命于牧师马克萨恩·安沃尔，这位上级驻守在山下的卡拉诺斯。他也与斯登·粗臂等当地守卫紧密合作，从新兵中发掘有潜力的人选。",al={"布兰斯托克·卡德尔的关系","布兰斯托克听命于谁","布兰斯托克·卡德尔的上级"}}},fp="17,140,27.331.0,25.149.0,44.124.0,54.120.0,32.93.0"}
P.entries["npc:brave-moonhorn"] = {n="卫兵穆赫·月角",s="卫兵穆赫·月角是一名牛头人斥候，驻守在贫瘠之地南部边界的升降梯顶端。他从这处悬崖上监视着通往千针石林的入口，并提醒旅人留意前方的当地危险。",h="卫兵穆赫·月角是一名牛头人斥候，驻守在贫瘠之地南部边界的升降梯顶端。他从这处悬崖上监视着通往千针石林的入口，并提醒旅人留意前方的当地危险。",kw={"卫兵穆赫·月角","半人马","峭壁卫兵图林·长角","乱风岗","升降梯","恐怖图腾","千针石林"},ang={["faction:Horde"]="月角担任部落的前哨守卫，指引初入峡谷的旅人前往安全地带，以及乱风岗设有防御工事的高地。",["race:Tauren"]="月角对恐怖图腾的深切戒心，反映出忠于凯恩·血蹄的传统部族与行事隐秘的恐怖图腾氏族之间暗流涌动的摩擦与猜忌。"},sec={{t="升降梯的哨兵",b="卫兵穆赫·月角驻守在千针石林的陡峭悬崖之上，守卫着北方平原与峡谷地带的交界处。他的主要职责是密切监视下方谷底出没的各路威胁，尤其是那些敌对的半人马氏族。打算下到石柱之间的人，往往会先遇见他，在踏上升降梯的巨大平台前得到重要的警告。"},{t="不安的阴影",b="除了四处游荡的半人马带来的持续威胁，月角还对来自恐怖图腾部族的牛头人同胞深怀疑虑。他告诫途经此地的部落盟友与他们保持距离，指出他们在千针石林一带的行为愈发反常，也愈发可疑。为了确保这一地区的防务，他派信使前往乱风岗，向峭壁卫兵图林·长角传递警告。"}},faq={{q="卫兵穆赫·月角是谁？",a="卫兵穆赫·月角是一名牛头人战士兼斥候，负责监视通往升降梯的道路，这座升降梯连接着贫瘠之地与千针石林。他监视敌人的动向，并提醒过往旅人留意附近的危险。",al={"卫兵穆赫·月角的职责","月角是谁","升降梯牛头人卫兵"}},{q="月角为何警告人们提防恐怖图腾？",a="月角注意到，恐怖图腾氏族在周围峡谷中的举止古怪，令人难以捉摸。虽然名义上仍属于牛头人群体，但他们咄咄逼人、排斥外人的作风，让沿途维持秩序的卫兵难以信任他们。",al={"恐怖图腾警告","为何避开恐怖图腾","月角与恐怖图腾"}},{q="他想让人向乱风岗传递什么消息？",a="他有关于千针石林半人马活动日益频繁的紧急警告，希望可靠的部落信使将这份情报转交给乱风岗的峭壁卫兵图林·长角。",al={"乱风岗的消息","月角的消息是什么","送往乱风岗的消息背景"}},{q="卫兵穆赫·月角在哪里？",a="他站在升降梯顶端的平台边缘附近，正处于贫瘠之地与千针石林的交界处。",al={"月角在哪里","卫兵穆赫·月角的位置","升降梯卫兵"}}},fx={["9347caaf"]={q="卫兵穆赫·月角支持哪一方？",a="卫兵穆赫·月角效力于雷霆崖和部落。他驻守在贫瘠之地与千针石林之间的升降梯顶端，监视边境，并指引途经的部落冒险者安全进入下方峡谷。",al={"卫兵穆赫·月角是部落成员吗","卫兵穆赫·月角的阵营","月角为谁效力"}},ff589928={q="卫兵穆赫·月角为什么驻守在升降梯？",a="月角驻守在千针石林的悬崖边，守卫下行通道并监视附近的危险。从这个制高点，他留意半人马的侵袭和蛮锤氏族不安分的动向，确保下到峡谷的旅人得到适当警告。",al={"月角为什么在这里","月角在升降梯做什么","卫兵穆赫·月角为什么在升降梯"}},["4ac94a87"]={q="卫兵穆赫·月角与谁有关？",a="月角听命于雷霆崖的牛头人领袖，并与乱风岗的峭壁卫兵图林·长角密切合作。峡谷道路附近出现危险时，长角是他依靠的指挥官，负责接收他的侦察报告。",al={"月角的盟友","月角向谁汇报","卫兵穆赫·月角的关系"}}},fp="14,148,20.330.0,14.281.0,22.203.0,45.239.0,53.177.0,32.133.0"}
P.entries["npc:brewmaster-drohn"] = {n="酿酒师德罗恩",s="在棘齿城码头上方，酿酒师德罗恩专心钻研着酿酒技艺。这个兽人就住在港口上坡不远处，用与熊猫人游历者老陈一脉相承的方法酿造烈酒。在卡利姆多各地找到遗弃酒桶的旅人，都会被指引到德罗恩家门前。",h="在棘齿城码头上方，酿酒师德罗恩专心钻研着酿酒技艺。这个兽人就住在港口上坡不远处，用与熊猫人游历者老陈一脉相承的方法酿造烈酒。在卡利姆多各地找到遗弃酒桶的旅人，都会被指引到德罗恩家门前。",kw={"贫瘠之地","酿酒师","老陈","德罗恩","棘齿城","洞穴麦酒"},ang={["faction:Alliance"]="身为联盟冒险者，你要知道，热砂在棘齿城保护着德罗恩。攻击他，当地的地精当局就会与你为敌。",["profession:Cooking"]="如果你研习烹饪，德罗恩的本领在于将稀有的动植物原料调配成沙漠中的美酒。",["race:Orc"]="身为兽人，你或许会将德罗恩的酿酒视为一种手艺，将杜隆塔尔和贫瘠之地的安宁融入其中，这与许多追随萨尔来到卡利姆多后修筑堡垒的战士有所不同。"},sec={{t="棘齿城的酿酒大师",b="酿酒师德罗恩在家中酿酒，他的家坐落在棘齿城地精码头上方的山坡上。这个兽人没有投身战斗，而是将一身技艺倾注于酿酒。他平静地生活在加兹鲁维的热砂港建立的中立避风港中。许多兽人偏爱粗酿的烈酒或普通烧酒，德罗恩却使用稀有原料，细心调和风味，采用同族鲜少掌握的酿造方法。"},{t="与熊猫人的渊源",b="酿酒师德罗恩的酿酒技艺来自一位师从老陈的导师，这位熊猫人游历者曾在杜隆塔尔建立期间与雷克萨和部落并肩作战。老陈也教过德罗恩酿造洞穴麦酒。当旅人在荒野中发现老陈遗弃的酒桶时，德罗恩是当地唯一能够辨认酒中原料，并重现这位游历者所酿烈酒的行家。"}},faq={{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩在贫瘠之地的棘齿城酿酒。这个兽人以风味独特的麦酒闻名，他的酿酒技艺也与熊猫人游历者老陈的酿造传统颇有渊源。",al={"德罗恩的故事","德罗恩是谁","棘齿城酿酒师"}},{q="德罗恩是怎么认识老陈的？",a="德罗恩的导师曾跟随老陈学习酿造风暴烈酒，德罗恩又向这位导师学习酿酒。后来，老陈教会了德罗恩如何酿造洞穴麦酒。",al={"与老陈的关系","他怎么认识老陈的","德罗恩与老陈"}},{q="找到老陈的空酒桶后该怎么办？",a="把老陈的空酒桶带给棘齿城的酿酒师德罗恩。他认得老陈的手艺，会让你寻找重现这种酒所需的当地稀有原料。",al={"老陈的空酒桶","找到空酒桶","酒桶任务"}},{q="酿酒师德罗恩属于部落吗？",a="是的。德罗恩是部落的兽人，不过他生活和酿酒的地方是棘齿城，一座中立的地精港口。攻击他会降低联盟冒险者在棘齿城和热砂港的声望。",al={"德罗恩属于部落吗","德罗恩是中立的吗","德罗恩的阵营"}},{q="德罗恩酿造什么样的酒？",a="德罗恩酿造烈性酒，其中包括洞穴麦酒，以及以老陈之名命名的风暴烈酒。酿造这些酒需要獠牙、腺体，以及贫瘠之地各处野兽身上的其他部位。",al={"德罗恩的配方","德罗恩酿酒厂的酒"}},{q="德罗恩的确切位置在哪里？",a="德罗恩就在贫瘠之地棘齿城主码头西北方不远处，俯瞰城镇的山坡上，他的屋子外面。",al={"德罗恩的位置","德罗恩在哪里","寻找酿酒师德罗恩"}}},fp="16,250,32.335.0,23.374.0,24.161.0,36.127.0,44.162.0,43.191.0,36.170.0,31.110.0"}
P.entries["npc:brewmeister-bilger"] = {n="布鲁米·比格尔",s="布鲁米·比格尔在南海镇旅店的地窖里，等待远方运来的货物。这个醉醺醺的矮人靠品尝烈酒打发时光。",h="布鲁米·比格尔在南海镇旅店的地窖里，等待远方运来的货物。这个醉醺醺的矮人靠品尝烈酒打发时光。",kw={"比格尔","布鲁米·比格尔","希尔斯布莱德丘陵","旅店地窖","马克里尔","南海镇"},ang={["faction:Alliance"]="身为联盟的一员，你可以在南海镇旅店的地窖里找到比格尔。他是在这座饱受困扰的城镇里与人类共同生活的矮人之一。",["race:Dwarf"]="身为矮人，你可以看到，即便身处远离铁炉堡的人类港口城镇，比格尔对烈酒的热爱依然不减。"},sec={{t="地窖里的生活",b="布鲁米·比格尔在南海镇旅店下方的地窖里踱步，打着酒嗝，寻觅着艾泽拉斯最烈的佳酿。"},{t="偏爱远方的烈酒",b="布鲁米·比格尔虽然总是醉醺醺的，却仍能品评烈酒。他偏爱浓烈的矮人私酿酒和劲道十足的南方烈酒，也热切地接收特别酿制的酒，比如醉鬼马克里尔从萨多尔大桥送来的私酿酒。"}},faq={{q="在哪里能找到布鲁米·比格尔？",a="布鲁米·比格尔就在南海镇旅店下方的地窖里，南海镇是希尔斯布莱德丘陵的一座联盟港口城镇。",al={"比格尔位置","比格尔在哪","南海镇地窖矮人"}},{q="哪些任务与布鲁米·比格尔有关？",a="布鲁米·比格尔接收从湿地向北运往南海镇的珍稀酒品，其中包括马克里尔的月光酒这样的烈酒。",al={"比格尔任务","马克里尔的月光酒任务"}}},fx={["0436bf77"]={q="布鲁米·比格尔是谁？",a="布鲁米·比格尔是一名矮人酿酒师，整天待在南海镇旅店的地窖里喝酒，醉醺醺地打着嗝，等着朋友醉鬼马克里尔还他欠下的私酿酒。",al={"比格尔是谁","布鲁米·比格尔的身份","布鲁米·比格尔是谁"}},["29798063"]={q="布鲁米·比格尔支持哪一方？",a="比格尔站在联盟和南海镇一边。他是铁炉堡的矮人，在当地居民中安稳度日，尽管比起履行城镇事务，他更喜欢在地窖里安静地陪伴酒桶。",al={"比格尔的阵营","比格尔是联盟成员吗","比格尔支持哪一方"}},["5541902b"]={q="布鲁米·比格尔为什么在这里？",a="比格尔把南海镇旅店的地窖当成了自己的家，整天待在酒桶间，喝着烈酒，等着朋友醉鬼马克里尔还他欠下的私酿酒。",al={"比格尔为什么在南海镇","比格尔在这里做什么","布鲁米·比格尔为什么在这里"}}},fp="18,150,18.123.0,26.214.0,36.115.0,39.142.0"}
P.entries["npc:brine"] = {n="布瑞恩",s="在黑棘山，布瑞恩引导萨满祭司学徒走近水之灵。这位兽人萨满祭司教导他们与潮汐沟通，赢得自己的水之图腾。",h="在黑棘山，布瑞恩引导萨满祭司学徒走近水之灵。这位兽人萨满祭司教导他们与潮汐沟通，赢得自己的水之图腾。",kw={"贫瘠之地","黑棘山","布瑞恩","水之召唤","萨满祭司","塔伦米尔","水之图腾"},ang={["class:Shaman"]="布瑞恩引导你经历耐力与心灵的试炼，之后你才能与水沟通，获得自己的水之图腾。",["faction:Horde"]="布瑞恩曾历经希尔斯布莱德的战火，如今她将元素的精神传承传授给新一代，以此为部落效力。"},sec={{t="山中的隐士",b="布瑞恩住在黑棘山北部的一座山丘上，远离贫瘠之地的贸易站。尽管周围尽是干燥的草原，她却毕生致力于领悟水的奥秘。部落各地的萨满祭司在掌握大地与火焰的力量后，都会前来向她求教。她教导他们，水需要耐心与眼界，而很少有人能像她一样深刻地理解这两种品质。"},{t="东部王国的回忆",b="年轻时，布瑞恩曾与兽人同伴一道行军穿越希尔斯布莱德丘陵，攻打人类的定居点。在那场战事中，她来到塔伦米尔，发现了一口由清澈泉水补给的简陋水井。那口井作为满目疮痍中的生命象征，一直留在她的记忆里。它让她更加确信儿时学到的道理：即使身陷最深沉的悲伤，仍能找到一丝希望。"},{t="水之图腾",b="布瑞恩让有志成为萨满祭司的人踏上朝圣之旅，从不同的水源采集纯净的水滴，以此考验他们。她的试炼教导他们，水既能温柔，也能坚韧不屈。在她的仪式中，萨满祭司与元素之灵沟通，将水的治愈精华注入凝聚力量的图腾。"}},faq={{q="布瑞恩是谁？",a="布瑞恩是一位经验丰富的兽人萨满祭司，独自住在贫瘠之地南部、黑棘山北部的一座山丘上。她指引着寻求与水之灵沟通的学徒。",al={"布瑞恩的故事","布瑞恩是谁","黑棘山的兽人"}},{q="一位水之萨满祭司为何住在沙漠中？",a="贫瘠之地虽然干旱，但独居让布瑞恩得以远离聚落的喧嚣，与元素深入沟通。",al={"为何在贫瘠之地","布瑞恩为何住在沙漠"}},{q="布瑞恩与塔伦米尔有什么渊源？",a="多年前，布瑞恩曾与部落战士并肩在希尔斯布莱德丘陵作战，并进入了塔伦米尔。她在那里发现了一口涌出纯净泉水的小井，在战火留下的废墟中，它成为长存于她心中的生命与希望的象征。",al={"塔伦米尔的水井","布瑞恩与希尔斯布莱德","布瑞恩的过往"}},{q="布瑞恩在萨满祭司的训练中承担什么职责？",a="布瑞恩引导学徒完成水之召唤的各阶段试炼。她派他们从不同的水源采集纯净的水，并教导他们谦逊与坚韧，让他们最终获得掌握水之图腾所需的领悟。",al={"布瑞恩萨满祭司任务","如何获得水之图腾","水之召唤 布瑞恩"}},{q="布瑞恩的确切位置在哪里？",a="布瑞恩住在贫瘠之地南部、黑棘山北部的一处高崖顶上，就在剃刀沼泽以北。",al={"布瑞恩的位置","布瑞恩在哪里","贫瘠之地寻找布瑞恩"}},{q="她的教诲遵循怎样的理念？",a="布瑞恩教导人们，即使身处痛苦与悲伤之中，也能找到希望与新生。水象征着生命，以及历经严酷试炼仍不屈不挠的毅力。",al={"布瑞恩的理念","水的教诲"}}},fp="5,150,19.350.0,32.405.0,17.266.1,13.174.0,41.120.0,42.205.0,45.222.0,31.114.0,37.135.0"}
P.entries["npc:brock-stoneseeker"] = {n="布洛克·寻石者",s="在塞尔萨玛，布洛克·寻石者向初出茅庐的勘探者传授采矿技艺。在他开办的矿工学校，他训练学员寻找并开采矿石与矿物。",h="在塞尔萨玛，布洛克·寻石者向初出茅庐的勘探者传授采矿技艺。在他开办的矿工学校，他训练学员寻找并开采矿石与矿物。",kw={"布洛克·寻石者","洛克莫丹","采矿训练师","采矿学校","塞尔萨玛"},ang={["profession:Mining"]="身为洛克莫丹的矿工，你可以到塞尔萨玛找到布洛克·寻石者，开始学习或进一步研习当地矿石的开采与熔炼技艺。",["race:Dwarf"]="身为卡兹莫丹的矮人，你继承了以岩石和金属为根基的传统。布洛克这样的导师帮助铁炉堡延续工艺传统。"},sec={{t="采矿与勘测大师",b="在塞尔萨玛，布洛克·寻石者在他开办的矿工学校教授矿工。洛克莫丹的丘陵蕴藏着丰富的矿脉，矿工既要稳稳地挥动矿镐，也要有辨识岩石的敏锐眼力。布洛克教他们寻找矿石、开采原生金属，并勘测地下矿藏。他传授的技艺帮助联盟的工匠为铁炉堡的铁匠铺供应原料。"}},faq={{q="布洛克·寻石者是谁？",a="布洛克·寻石者在洛克莫丹的塞尔萨玛训练矿工。在他开办的矿工学校，他教工匠开采矿石、勘测矿藏。",al={"布洛克·寻石者","布洛克是谁","布洛克 塞尔萨玛"}},{q="在哪里可以找到布洛克·寻石者？",a="布洛克·寻石者位于塞尔萨玛，这里是洛克莫丹的主要矮人城镇。他在当地工匠聚集的地方附近开办采矿学校。",al={"布洛克在哪里","布洛克·寻石者位置","布洛克地图"}},{q="布洛克教授什么专业？",a="布洛克·寻石者教授采矿。他向旅行者传授如何采集卡兹莫丹乡野间的粗糙石块、铜矿和其他入门矿石。",al={"布洛克教什么","布洛克训练师类型","塞尔萨玛采矿训练师"}},{q="布洛克的矿工学校是什么？",a="布洛克的矿工学校是塞尔萨玛的一所培训学校。布洛克教勘探者安全地开采矿物，并辨识群山中的地下矿脉。",al={"布洛克的学校","塞尔萨玛采矿学校"}}},fx={["38215f8d"]={q="布洛克·寻石者效忠哪一方？",a="布洛克·寻石者坚定地支持铁炉堡矮人与大联盟。他以洛克莫丹宁静的聚落塞尔萨玛为据点，培养技艺娴熟的矿工，让他们勘探矮人家园崎岖的山丘，以此为卡兹莫丹的巡山人和旅人效力。",al={"布洛克·寻石者的阵营","布洛克·寻石者属于联盟吗","布洛克·寻石者为谁效力"}},["53fa3834"]={q="布洛克·寻石者为什么在这里？",a="布洛克定居塞尔萨玛，经营布洛克的矿工学校。洛克莫丹周围的峭壁与山岭蕴藏着丰富的原石和矿脉，是教导采矿学徒，并派他们前往周围险峻山地实践的理想地点。",al={"布洛克·寻石者为什么在塞尔萨玛","布洛克为什么在这里","布洛克为何来到洛克莫丹"}},["7d1f98e6"]={q="布洛克·寻石者想要什么？",a="布洛克希望将采矿这门矮人的重要技艺传授给新人，并表彰学校里最勤勉的学生。他力求让勘探者做好充分准备，再深入卡兹莫丹崎岖的荒野，开采富矿并勘测土地。",al={"布洛克·寻石者想要什么","布洛克·寻石者的目标","布洛克想要什么"}}},fp="17,162,30.348.0,25.165.0,37.133.0,33.149.0,47.179.0"}
P.entries["npc:bromos-grummner"] = {n="布罗莫斯·格鲁诺尔",s="在安威玛尔，布罗莫斯·格鲁诺尔引导年轻的矮人圣骑士信奉圣光，接纳他们研习圣光之道。他教导他们坚定信仰，并讲述白银之手骑士团中矮人与人类之间的纽带。",h="在安威玛尔，布罗莫斯·格鲁诺尔引导年轻的矮人圣骑士信奉圣光，接纳他们研习圣光之道。他教导他们坚定信仰，并讲述白银之手骑士团中矮人与人类之间的纽带。",kw={"安威玛尔","布罗莫斯","寒脊","丹莫罗","格鲁诺尔","圣骑士","白银之手","训练师"},ang={["class:Paladin"]="身为矮人圣骑士，你可以将布罗莫斯视为最初的精神导师。他会引领你了解白银之手的神圣职责。",["race:Dwarf"]="身为矮人，你传承着信奉圣光的悠久传统，与人类盟友并肩作战。"},sec={{t="寒脊的明灯",b="在安威玛尔，布罗莫斯向年轻的圣骑士传授战斗仪式与神圣祷言。然而，他讲述的不只有战斗。白银之手骑士团将铁炉堡与联盟的人类王国团结在共同的正义目标之下。"}},faq={{q="布罗莫斯·格鲁诺尔是谁？",a="布罗莫斯·格鲁诺尔在丹莫罗寒脊山谷的安威玛尔训练新入门的矮人圣骑士。他为他们提供基础训练，传授法术，并给予精神上的指引。",al={"布罗莫斯是谁","布罗莫斯·格鲁诺尔的故事","安威玛尔圣骑士训练师"}},{q="布罗莫斯代表哪个骑士团？",a="布罗莫斯代表白银之手骑士团。他向学徒讲述人类与矮人在这个神圣骑士团的旗帜下结成的纽带。",al={"布罗莫斯 白银之手","布罗莫斯是否属于白银之手"}},{q="他教新兵些什么？",a="布罗莫斯向新入门的圣骑士传授基本战技与神圣法术。他为初学者安排最初的试炼，让他们证明自己对圣光的虔诚，以及守护丹莫罗的决心与准备。",al={"布罗莫斯的任务","布罗莫斯·格鲁诺尔做什么"}}},fx={["73c3e4de"]={q="布罗莫斯·格鲁诺尔效忠哪一方？",a="布罗莫斯坚定地支持铁炉堡与大联盟。身为白银之手骑士团的虔诚成员，他极为重视矮人与人类之间牢固持久的纽带，相信双方对圣光的共同信仰，是维系各自国度团结的关键。",al={"布罗莫斯·格鲁诺尔的阵营","布罗莫斯与联盟","布罗莫斯为谁而战"}},["830a5136"]={q="布罗莫斯·格鲁诺尔为什么在寒脊山谷？",a="布罗莫斯驻守安威玛尔，教导响应圣光召唤的矮人圣骑士新兵。面对步步逼近的严寒和当地穴居人的威胁，他确保每一位有志守护同胞的人都能学会运用武艺与正义的祝福，为自己的人民效力。",al={"布罗莫斯为什么在安威玛尔","布罗莫斯·格鲁诺尔的目的","布罗莫斯在这里做什么"}},["33b2371f"]={q="布罗莫斯·格鲁诺尔想要什么？",a="布罗莫斯希望培养出纪律严明、意志坚定的新一代矮人圣骑士。他不仅要让学生掌握圣光的神圣力量，还要让他们深深忠于白银之手中矮人与人类缔结的神圣盟约。",al={"布罗莫斯想要什么","布罗莫斯的目标","布罗莫斯的动机"}}},fp="15,215,21.238.0,23.157.0,33.137.0,32.179.0"}
P.entries["npc:brother-joshua"] = {n="乔舒修士",s="在暴风城的光明大教堂，乔舒修士指引前来学习圣光之道的人们。他训练初入门的牧师治疗伤口，增强盟友的力量。",h="在暴风城的光明大教堂，乔舒修士指引前来学习圣光之道的人们。他训练初入门的牧师治疗伤口，增强盟友的力量。",kw={"乔舒修士","光明大教堂","圣光","人类牧师","牧师训练师","暴风城"},ang={["class:Priest"]="身为牧师，你可以在暴风城跟随乔舒修士研习圣光。随着你不断精进，他会传授你新的祷言和戒律。",["faction:Alliance"]="身为联盟的一员，你可以在王国腹地、暴风城的光明大教堂找到乔舒。"},sec={{t="大教堂中的导师",b="乔舒修士在暴风城的光明大教堂主祭坛附近等候。作为圣光教会的牧师，他教导新入教的侍奉者治疗伤口、施放防护结界，并凝神与圣光沟通。刚开始为联盟效力的年轻人类牧师，会在他这里找到最初的导师之一。"}},faq={{q="乔舒修士是谁？",a="乔舒修士是一名人类牧师，也是圣光教会的训练师。在暴风城的光明大教堂，他向有志成为牧师的人传授法术、仪式和神圣职责。",al={"乔舒修士是谁","乔舒修士的职责","牧师乔舒"}},{q="在哪里可以找到乔舒修士？",a="乔舒修士在光明大教堂后部的高祭坛附近等候，这座教堂位于暴风城的教堂广场。",al={"乔舒修士的位置","乔舒修士在哪里","乔舒在哪里"}},{q="他提供哪些服务？",a="乔舒修士教导牧师更高等级的神圣法术和治疗法术。他也可以重置他们的精神天赋。",al={"乔舒做什么","乔舒修士的训练","乔舒能提供训练吗"}}},fx={cce3d5dc={q="乔舒修士效忠哪一方？",a="乔舒修士侍奉圣光教会，并坚定地支持大联盟。他潜心遵循圣光的教诲，在暴风城的光明大教堂拱顶下履行教职，为同胞与联盟旅人提供心灵上的指引和支持。",al={"乔舒修士的效忠对象","乔舒修士的阵营","乔舒修士为谁效力"}},["2e9120b0"]={q="乔舒修士想要什么？",a="乔舒修士希望传播圣光的教义，引导有潜力的侍僧践行神圣的使命。他每日悉心训练牧师新兵，加深他们与圣光的沟通，并确保暴风城的信徒在动荡岁月中依然坚定不移。",al={"乔舒修士的目标","乔舒修士想做什么","乔舒修士的目的"}},["2e708272"]={q="乔舒修士为什么在这里？",a="乔舒修士驻于暴风城的光明大教堂，作为正式受任的牧师导师，在祭坛附近履行职责。在这处信仰权威的中心，他指导响应圣职召唤的人，也帮助前来寻求圣光智慧的访客。",al={"乔舒修士为什么在暴风城","乔舒修士为什么在大教堂","乔舒修士在此的原因"}},["5cfd3f6a"]={q="乔舒修士与谁有关联？",a="乔舒修士隶属于圣光教会的神职人员，与驻于光明大教堂的牧师和圣骑士共事。履行教职期间，若职责需要彼此援助，他也会与塞纳里奥议会等其他组织保持联系。",al={"乔舒修士的关系","乔舒修士所属的教会","乔舒修士听命于谁"}}},fp="14,177,25.338.0,22.182.0,32.122.0,28.117.0"}
P.entries["npc:brother-kristoff"] = {n="克里斯托弗修士",s="在教堂广场，克里斯托弗修士在乌瑟尔的雕像下布道。这位人类牧师正在寻找实用的书籍，用于讲述精神力量的布道。",h="在教堂广场，克里斯托弗修士在乌瑟尔的雕像下布道。这位人类牧师正在寻找实用的书籍，用于讲述精神力量的布道。",kw={"克里斯托弗修士","光明大教堂","教堂广场","坚韧","克里斯托弗","钢铁的考验","乌瑟尔雕像"},ang={["class:Priest"]="身为牧师，你或许会欣赏克里斯托弗修士讲解礼仪时脚踏实地的方式。他借助实用技艺，传授内心坚韧的深层奥秘。",["profession:Blacksmithing"]="身为铁匠，你或许会觉得有趣：一位圣光的神职人员，竟借助有关铁的应力和冶金的书籍，向其他神职人员讲授坚韧。"},sec={{t="雕像旁的布道者",b="克里斯托弗修士在教堂广场的光明使者乌瑟尔雕像下，为圣光教会效力。他在广场上来往的市民和朝圣者之间传道，而非在光明大教堂内。\n\n在准备坚韧的灵魂等布道时，他会借用世俗事物作比。在《金属的延展性》中，他找到了说明灵魂如何承受压力的方法。他教导人们，圣光赋予的内在意志，就像金属经过锤炼后获得的强度。"}},faq={{q="克里斯托弗修士是谁？",a="克里斯托弗修士是一位人类牧师，也是圣光教会的学者。他在暴风城的教堂广场露天传道，就在光明使者乌瑟尔的宏伟雕像附近。",al={"克里斯托弗修士背景故事","克里斯托弗是谁","克里斯托弗 暴风城"}},{q="克里斯托弗修士在教堂广场做什么？",a="克里斯托弗修士准备有关圣光与信仰的布道。他正在筹备一场关于坚韧的灵魂的布道，并寻找冶金方面的书籍，用来阐释精神的坚韧。",al={"克里斯托弗的目的","克里斯托弗的职责","克里斯托弗修士为什么站在外面"}},{q="克里斯托弗修士为什么需要一本关于铁的书？",a="克里斯托弗修士正在寻找《金属的延展性》，用于讲述坚韧的布道。他以承受压力的铁为例，说明对圣光的虔诚如何增强凡人的精神，使其抵御逆境。",al={"金属的延展性","关于坚韧的演讲书籍","克里斯托弗为什么需要冶金知识"}}},fx={["610da828"]={q="克里斯托弗修士效忠哪一方？",a="克里斯托弗修士侍奉圣光教会，并为联盟效力。作为牧师中的一名修士，他虔诚地信奉圣光，致力于引导暴风城人民的心灵，忠实地守在光明大教堂的阴影之下。",al={"克里斯托弗修士的阵营","克里斯托弗修士为谁效力","克里斯托弗修士与联盟"}},["8237c000"]={q="克里斯托弗修士与谁有关联？",a="克里斯托弗修士是圣光教会的神职人员，常驻暴风城的光明大教堂。他与教堂广场的牧师和圣骑士同僚共事，照料王国民众与守卫者的精神需求。",al={"克里斯托弗修士的关系","克里斯托弗修士所属的教会","克里斯托弗修士隶属于谁"}}},fp="16,144,24.495.0,24.179.0,50.180.0,49.186.0"}
P.entries["npc:brother-neals"] = {n="尼尔斯修士",s="在北郡修道院，尼尔斯修士负责保障食物和饮品的储备。他监督货物运送，并品尝当地葡萄园酿制的葡萄酒。",h="在北郡修道院，尼尔斯修士负责保障食物和饮品的储备。他监督货物运送，并品尝当地葡萄园酿制的葡萄酒。",kw={"尼尔斯修士","艾尔文森林","葡萄出货单","北郡修道院","北郡山谷","葡萄园","葡萄酒"},ang={["profession:Cooking"]="尼尔斯修士管理修道院的给养和烈酒，因此他的职责与烹饪技艺有所关联。"},sec={{t="酒窖管理人",b="尼尔斯修士在钟楼上层的房间里，核查来自北郡农场的葡萄出货单。频繁的品酒让他得以检验各年份的葡萄酒。他也跟进山谷农田送来的物资，保障修道院的储备。"}},faq={{q="尼尔斯修士是谁？",a="尼尔斯修士管理北郡修道院的食物、饮品和葡萄酒储备，供山谷中的神职人员和新兵使用。",al={"尼尔斯修士","尼尔斯","尼尔斯是谁"}},{q="在哪里可以找到尼尔斯修士？",a="尼尔斯修士待在北郡修道院最上层的房间里。沿着大厅内的石阶向上走，就能到达他位于塔楼近顶处的清静居所。",al={"尼尔斯修士在哪里","尼尔斯修士位置","寻找尼尔斯"}},{q="他在葡萄园事务中负责什么？",a="尼尔斯修士跟进附近北郡农场的葡萄收成和葡萄酒运输。他品尝葡萄酒，并记录账目。",al={"葡萄出货单任务","尼尔斯葡萄酒","尼尔斯做什么"}}},fx={["340be3c1"]={q="尼尔斯修士效忠哪一方？",a="尼尔斯修士是北郡兄弟会的忠诚成员，为北郡修道院和暴风城的大联盟效力。他在修道院的高墙内平静地履行教职。",al={"尼尔斯修士的阵营","尼尔斯修士为谁效力","尼尔斯修士与联盟"}},["0d7c1646"]={q="尼尔斯修士想要什么？",a="尼尔斯修士需要妥善记录北郡的储备物资，尤其是当地葡萄园出产的葡萄酒库存。他要求将货物以及葡萄出货单之类的记录直接送到楼上他的住处，以便管理物资，也好尽情品尝修道院的佳酿。",al={"尼尔斯修士的葡萄出货单","尼尔斯修士需要什么"}},bb6478cd={q="尼尔斯修士为什么在这里？",a="作为修道院的一名修士，尼尔斯住在北郡修道院安静的高塔上层，监管院内的食物与酒水储备。这个岗位让他能就近照看地窖中的储备和账目文书，保障神职人员与新兵的日常所需。",al={"尼尔斯修士为什么在塔里","尼尔斯修士为什么在北郡"}}},fp="13,140,20.243.0,21.117.0,33.161.0,40.137.0"}
P.entries["npc:brother-sarno"] = {n="萨尔努修士",s="在暴风城的光明大教堂，萨尔努修士迎接访客与信众。他也指引联盟旅人前往铁炉堡，那里有一位工匠大师欧沃斯巴克，需要援手收复诺莫瑞根。",h="在暴风城的光明大教堂，萨尔努修士迎接访客与信众。他也指引联盟旅人前往铁炉堡，那里有一位工匠大师欧沃斯巴克，需要援手收复诺莫瑞根。",kw={"萨尔努修士","光明大教堂","圣光教会","暴风城","尖端机器人","工匠大师欧沃斯巴克"},ang={["class:Priest"]="身为牧师，你可以在暴风城看到萨尔努修士迎接访客。他展现着圣光的热忱与温和恩典。",["race:Gnome"]="萨尔努修士虽然在人类的礼拜场所侍奉，却也指引愿意伸出援手的旅人前往铁炉堡，帮助诺莫瑞根复兴。"},sec={{t="教堂里的迎客之声",b="在暴风城的光明大教堂，萨尔努修士在入口处迎接朝圣者与旅人。作为圣光教会的一名修士，他欢迎前来祈祷、寻求慰藉或指引的人。在教堂的日常往来中，他和善的态度让访客感到安心。"},{t="与铁炉堡的联系",b="萨尔努修士也在教堂之外为联盟提供帮助。他听说铁炉堡的工匠大师欧沃斯巴克需要人手，处理他在诺莫瑞根失控的发明尖端机器人，便指引有能力的旅人前往丹莫罗。他的援助支持着那些流离失所的侏儒。"}},faq={{q="在哪里可以找到萨尔努修士？",a="萨尔努修士就在暴风城教堂广场的光明大教堂内，刚进正门左手边的位置。",al={"萨尔努修士位置","萨尔努修士在哪里","教堂迎宾者"}},{q="萨尔努修士做些什么？",a="萨尔努修士在光明大教堂迎接访客与信众。他也指引旅人前往铁炉堡，寻找工匠大师欧沃斯巴克，协助解决诺莫瑞根的问题。",al={"萨尔努修士职责","萨尔努修士做什么"}},{q="为什么暴风城的牧师会派人前往诺莫瑞根？",a="神职人员收到消息，得知工匠大师欧沃斯巴克需要援手，收回尖端机器人等失控的技术造物。萨尔努修士便指引有能力的勇士前往铁炉堡提供帮助。",al={"萨尔努修士诺莫瑞根任务","萨尔努修士为什么关心侏儒"}},{q="他属于某个特定的教团吗？",a="萨尔努修士是圣光教会正式授职的成员。他在暴风城侍奉，听命于教堂的高级教士和大主教本尼迪塔斯。",al={"萨尔努修士阵营","萨尔努修士教团"}}},fx={["61335d44"]={q="萨尔努修士是谁？",a="萨尔努修士是圣光教会的一名人类牧师，驻守在暴风城宏伟的光明大教堂内。他站在正门内侧的左手边，亲切地迎接进入圣所的访客和朝圣者。",al={"萨尔努修士是谁","萨尔努修士身份","萨尔努是谁"}},["52c947c9"]={q="萨尔努修士属于哪一方？",a="萨尔努修士是圣光教会的虔诚侍从，也是大联盟的忠诚成员。他支持暴风城的居民，并与联盟的盟友保持着密切的合作关系，其中包括卡兹莫丹的侏儒和矮人。",al={"萨尔努修士阵营","萨尔努修士效忠对象","萨尔努修士为谁效力"}},["3cc89cc1"]={q="萨尔努修士想要什么？",a="除了迎接前来光明大教堂礼拜的信徒，萨尔努修士也在留意有本领的联盟冒险者。他指引热心的旅人前往铁炉堡，协助工匠大师欧沃斯巴克处理一个名叫尖端机器人的麻烦机械造物，它位于沦陷的诺莫瑞根城深处。",al={"萨尔努修士想要什么","萨尔努修士目标","萨尔努修士动机"}},["222a0285"]={q="萨尔努修士为什么在大教堂里？",a="萨尔努修士站在光明大教堂的正门附近，迎接信徒、朝圣者，以及寻求慰藉的疲惫旅人。在这个岗位上，他也留心远方的危难，为到访的勇士引荐需要帮助的盟友。",al={"萨尔努修士为何在这里","萨尔努为何在大教堂","萨尔努修士驻留原因"}}},fp="13,200,34.263.0,17.285.0,31.139.0,27.173.0,54.175.0,37.153.0"}
P.entries["npc:brother-wilhelm"] = {n="威尔海姆修士",s="在闪金镇铁匠铺后方，威尔海姆修士指引年轻的圣骑士走向更广阔的森林。他们从北郡修道院来到这里，迈出在艾尔文森林历练的第一步。",h="在闪金镇铁匠铺后方，威尔海姆修士指引年轻的圣骑士走向更广阔的森林。他们从北郡修道院来到这里，迈出在艾尔文森林历练的第一步。",kw={"威尔海姆修士","北郡兄弟会","艾尔文森林","闪金镇","圣光","圣骑士训练师","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你离开北郡山谷后，遇到的第一位导师就是威尔海姆修士。他指引你成长，为你开启掌握圣洁之书的道路。",["race:Human"]="身为人类，你从威尔海姆修士身上看到了 Church of the Holy Light 的信仰，这个教会守护着艾尔文森林的腹地。"},sec={{t="闪金镇的引路人",b="威尔海姆修士在闪金镇铁匠铺后方训练初出茅庐的圣骑士。北郡山谷庇护着那些刚踏上圣光之路的人，但许多人进入更广阔的森林后，便会寻求他的指引。他教导离开修道院的圣骑士履行神圣的职责。随后，他们便肩负起保卫王国的重任。"},{t="圣典之路",b="威尔海姆修士指引有志成为圣骑士的人研习圣洁之书。其中的仪式教导初学者理解牺牲的分量与神圣救赎的力量。他们通过试炼考验自己的虔诚，并学会驾驭圣光。他们能够复活倒下的战友，在暴风城王国各地伸张正义。"}},faq={{q="在哪里可以找到威尔海姆修士？",a="威尔海姆修士位于艾尔文森林闪金镇的村庄铁匠铺后方。他在那里训练并指引有志成为圣骑士的人。",al={"威尔海姆修士位置","威尔海姆修士在哪里","寻找威尔海姆修士"}},{q="威尔海姆修士提供哪些服务？",a="威尔海姆修士向在艾尔文森林历练的年轻圣骑士传授新的法术、战斗祝福和神圣技艺。",al={"威尔海姆修士做什么","闪金镇圣骑士训练师","威尔海姆修士训练师"}},{q="威尔海姆修士是北郡兄弟会的成员吗？",a="威尔海姆修士的头衔，以及他与北郡修道院的密切联系，暗示他与北郡兄弟会有所关联。他在闪金镇为 圣光教会 和暴风城王国效力。",al={"威尔海姆修士是否属于 北郡兄弟会","威尔海姆修士阵营","威尔海姆修士为谁效力"}},{q="他在圣洁之书任务中扮演什么角色？",a="威尔海姆修士指引实力有所增长的人类圣骑士研习圣洁之书，并接受其中的试炼。这些试炼将引领他们获得复活的神圣赐福。",al={"圣洁之书 威尔海姆修士","复活任务威尔海姆修士","闪金镇圣骑士任务"}}},fx={["0af03050"]={q="威尔海姆修士是谁？",a="威尔海姆修士是驻守闪金镇的一名人类圣骑士导师。他献身于圣光，致力于保卫王国，为那些走出北郡山谷、踏入艾尔文森林更广阔地域的年轻圣骑士提供指导和训练。",al={"威尔海姆修士是谁","威尔海姆修士身份","威尔海姆是谁"}},cccf7116={q="威尔海姆修士属于哪一方？",a="威尔海姆修士坚定地效忠联盟和暴风城王国。他为圣光的神圣教团效力，致力于增强王国圣骑士的实力，以应对内乱和各地的威胁。",al={"威尔海姆修士为谁效力","威尔海姆阵营","威尔海姆修士联盟"}},["3fb91c50"]={q="威尔海姆修士为什么在闪金镇？",a="威尔海姆修士驻守在闪金镇铁匠铺后方，教导刚刚离开北郡修道院的年轻圣骑士。他留在艾尔文森林，随时指导他们继续成长，并在他们正式履职时确保他们在精神上做好准备。",al={"威尔海姆修士为何在这里","威尔海姆修士闪金镇","威尔海姆为何在艾尔文"}}},fp="15,156,20.304.0,20.318.0,33.134.0,43.127.0,57.189.0,47.163.0"}
P.entries["npc:bruegal-ironknuckle"] = {n="布鲁高·铁拳",s="布鲁高·铁拳在暴动肆虐的暴风城监狱走廊中游荡。这个危险的矮人擅长搏斗，任何试图恢复秩序的人都可能尝到他的拳头。",h="布鲁高·铁拳在暴动肆虐的暴风城监狱走廊中游荡。这个危险的矮人擅长搏斗，任何试图恢复秩序的人都可能尝到他的拳头。",kw={"格斗者","布鲁高·铁拳","矮人","囚犯","铁拳","犯人","稀有","监狱","暴风城"},ang={["class:Warrior"]="身为战士，你能从铁拳的顽强意志和沉重双拳中，看到失去纪律与荣誉之后所剩的蛮力。",["faction:Alliance"]="身为联盟的勇士，你可以协助暴风城的卫兵镇压铁拳这样的恶棍，他们正威胁着要将首都腹地变成混乱的堡垒。",["race:Dwarf"]="身为矮人，看到一位敦实的同胞混迹于暴风城的扒手与恶棍之间，你或许会感到沉重。即便是铁炉堡的子民，也难逃流放与沦为亡命徒的命运。"},sec={{t="危险的囚犯",b="暴风城监狱爆发叛乱时，布鲁高·铁拳在其中四处游荡。这个危险的矮人以凶狠的拳脚和蛮力闻名。城中许多最暴戾的亡命之徒占据了地下监区，布鲁高也在其中。他并不待在某一间牢房里，而是在暴动肆虐的走廊中游荡，随时准备痛殴任何试图平息叛乱的人。"},{t="桀骜的亡命徒",b="布鲁高·铁拳是被关押在暴风城地下深处的众多恶棍与亡命徒之一。迪菲亚潜行者及其头目主导了大部分叛乱，而布鲁高这样的囚犯则表明，这座监狱关押着来自东部诸国各地的罪犯。无论他因何罪入狱，他顽强的韧性都让他难以对付，也让他成为走廊中最致命的独行囚犯之一。"}},faq={{q="布鲁高·铁拳是谁？",a="布鲁高·铁拳是暴风城监狱中的一名精英矮人囚犯。暴动仍在持续，他在监狱的走廊中游荡，行踪难觅。",al={"布鲁高是谁","铁拳的故事","监狱矮人囚犯"}},{q="布鲁高·铁拳是迪菲亚潜行者的一员吗？",a="布鲁高是监狱中的一名矮人囚犯。他的确切归属没有记载。",al={"布鲁高是迪菲亚潜行者吗","迪菲亚潜行者矮人监狱"}},{q="他为什么被关进监狱？",a="公开的通缉令并未记载布鲁高因何罪被关进监狱。他性情暴戾，又以好勇斗狠闻名，想必曾严重触犯暴风城的律法。",al={"布鲁高为何被关押","布鲁高的罪行"}},{q="在监狱的什么地方能找到他？",a="布鲁高在监狱内部的通道和岔路口游荡，并不待在某一间牢房里。他可能会突然袭击那些清剿暴徒的人。",al={"布鲁高刷新","布鲁高在哪里","监狱稀有刷新"}},{q="他一直都在监狱里吗？",a="不是。动乱期间，布鲁高只是偶尔现身。他常常被严加禁闭，或藏在视线之外。",al={"布鲁高会不刷新吗","为什么找不到布鲁高"}},{q="他在囚犯中有何特别之处？",a="布鲁高以令人畏惧的格斗本领闻名。据说他还瞒着守卫藏匿了贵重的违禁品和装备，因此，那些有胆量面对他的人都渴望将他拿下。",al={"为什么有人寻找布鲁高","布鲁高的重要性"}}},fp="19,184,19.330.0,13.394.0,27.153.0,54.94.0,37.181.0,42.152.0,35.119.0,43.186.0"}
P.entries["npc:cain-firesong"] = {n="凯恩·火歌",s="在布瑞尔的恐惧之末旅店，凯恩·火歌指导被遗忘者法师研习奥术。他在提瑞斯法林地训练他们，再将学有所成的学生送往幽暗城深造。",h="在布瑞尔的恐惧之末旅店，凯恩·火歌指导被遗忘者法师研习奥术。他在提瑞斯法林地训练他们，再将学有所成的学生送往幽暗城深造。",kw={"安娜斯塔西娅·哈特威尔","奥术","布瑞尔","凯恩·火歌","恐惧之末旅店","法师训练师","提瑞斯法林地"},ang={["class:Mage"]="作为一名从丧钟镇出发的被遗忘者法师，你可以先在提瑞斯法林地向凯恩·火歌学习奥术，再前往幽暗城继续深造。",["race:Undead"]="作为一名Undead，你可以将昔日人类法师的奥术传统化作被遗忘者的武器。"},sec={{t="布瑞尔的奥术研习者",b="凯恩·火歌在布瑞尔教授传统奥术，被遗忘者法师在这里开始求学。许多被遗忘者施法者转而研习暗影或通灵术，凯恩却始终专注于奥术。他指导从丧钟镇出发的法师。亡灵卫兵会指引访客前往恐惧之末旅店楼上的楼梯平台，凯恩就在那里。他们打趣说，他来得太晚，没能订到房间。"},{t="指引新秀",b="当有才干的学生完成在提瑞斯法林地的初步学业后，凯恩便会让他们前往别处深造。他指引他们去找安娜斯塔西娅·哈特威尔，一位住在幽暗城魔法区的女巫大师。"}},faq={{q="凯恩·火歌是谁？",a="凯恩·火歌在提瑞斯法林地的布瑞尔训练被遗忘者法师。他教授奥术法术，并指引学有所成的学生前往幽暗城继续学习。",al={"凯恩·火歌是谁","凯恩·火歌背景故事","凯恩·火歌 布瑞尔"}},{q="凯恩·火歌住在布瑞尔的哪里？",a="凯恩·火歌就在布瑞尔的恐惧之末旅店楼上的楼梯平台。当地的亡灵卫兵打趣说，他来得太晚，没能订到房间。",al={"凯恩·火歌在哪里","凯恩·火歌位置","凯恩 旅店房间"}},{q="凯恩会在法师完成初步训练后派他们去哪里？",a="凯恩会将受他指导、学有所成的法师送往幽暗城的魔法区，由安娜斯塔西娅·哈特威尔继续教导他们。",al={"凯恩·火歌任务","凯恩派法师去找谁","与安娜斯塔西娅交谈"}}},fp="13,186,23.375.0,18.199.0,21.162.0,39.154.0,56.141.0"}
P.entries["npc:cairne-bloodhoof"] = {n="凯恩·血蹄",s="在雷霆崖，凯恩·血蹄以历经磨难得来的智慧治理着族人。这位德高望重的大酋长领导着团结一致的牛头人各氏族。在兽人帮助他们摆脱半人马带来的灭族危机后，他便将族人的命运与萨尔的部落紧紧相连。",h="在雷霆崖，凯恩·血蹄以历经磨难得来的智慧治理着族人。这位德高望重的大酋长领导着团结一致的牛头人各氏族。在兽人帮助他们摆脱半人马带来的灭族危机后，他便将族人的命运与萨尔的部落紧紧相连。",kw={"贝恩","血蹄","凯恩","半人马","大酋长","莫高雷","萨尔","雷霆崖"},ang={["faction:Horde"]="身为部落的一员，你与凯恩为共同的事业而战。他是部落在卡利姆多的奠基者之一，也是荣誉、智慧与军事实力的支柱。",["race:Tauren"]="身为牛头人，凯恩是你族人的救星。他团结了分散的氏族，击退了半人马，并领导修建了雷霆崖。"},sec={{t="莫高雷的家园",b="凯恩·血蹄带领牛头人结束了四处逃亡的生活，在莫高雷建立了家园。世世代代，半人马掠夺者在贫瘠之地追猎游牧的牛头人氏族，将他们逼向灭绝的边缘。当萨尔和他率领的兽人抵达卡利姆多时，凯恩在他们身上看到了难得的高尚品格。萨尔答应提供军事保护，护送凯恩陷入绝境的车队穿过平原，作为交换，凯恩要为他们指引前往石爪峰寻找神谕的道路。牛头人在雷霆崖高耸的台地上定居，凯恩在那里团结了各个氏族，给了他们一个永久的家园。"},{t="向部落宣誓效忠",b="在第三次大战期间，凯恩·血蹄与萨尔的部落和吉安娜·普罗德摩尔率领的人类并肩作战，共同对抗燃烧军团。出于对萨尔的感激，他曾跟随兽人前往石爪峰。当海军上将戴林·普罗德摩尔入侵杜隆塔尔时，凯恩被俘的儿子贝恩获救并平安归来，随后他再次拿起武器，与雷克萨并肩作战。如今，凯恩是部落最受尊敬的长者之一，仍是萨尔最亲密的知己，以沉着的劝告抵制鲁莽的好战之举。"}},faq={{q="凯恩·血蹄是谁？",a="凯恩·血蹄是联合起来的牛头人各氏族的大酋长、血蹄氏族的酋长，也是雷霆崖的领袖。这位年迈的战士带领牛头人结束了游牧流亡的生活，为他们建立了安稳的家园。",al={"凯恩是谁","牛头人领袖","大酋长"}},{q="牛头人为何与兽人结盟？",a="在第三次大战期间，四处劫掠的半人马氏族追猎牛头人，将他们逼向灭绝。萨尔和初来乍到的兽人击退了掠夺者，护送凯恩的庞大车队抵达莫高雷。为了报答这份恩情，凯恩宣誓让族人向萨尔的部落献上忠诚与力量。",al={"牛头人为何加入部落","凯恩与萨尔的友谊","牛头人与兽人结盟"}},{q="凯恩住在哪里？",a="凯恩居住在雷霆崖，这座城市建在莫高雷高耸的台地上。他与重新团结起来的牛头人各氏族的领袖共同治理族人。",al={"凯恩在哪里","凯恩位置","寻找凯恩·血蹄"}},{q="贝恩·血蹄与凯恩是什么关系？",a="贝恩是凯恩深爱的儿子，也是他的继承人。半人马掠夺者绑架贝恩后，凯恩陷入深深的悲痛，拒绝参战，直到雷克萨和同伴找到贝恩，将他平安带回家。",al={"凯恩的儿子","贝恩是凯恩的儿子吗","贝恩·血蹄的关系"}}},fp="16,186,19.536.0,19.485.0,24.210.0,40.277.0,25.136.0,33.200.0"}
P.entries["npc:calor"] = {n="卡洛尔",s="在夜色镇，卡洛尔指挥着抵御狼人、保卫暮色森林的行动。在乔纳森·卡尔文的指示下，他协助卡尔文家族猎杀潜伏在森林中的野兽。",h="在夜色镇，卡洛尔指挥着抵御狼人、保卫暮色森林的行动。在乔纳森·卡尔文的指示下，他协助卡尔文家族猎杀潜伏在森林中的野兽。",kw={"卡洛尔","卡尔文","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","烂果园","狼人"},ang={["class:Hunter"]="作为猎人，你可以与卡洛尔合作，追踪并猎杀那些违背森林自然秩序的凶猛野兽。",["faction:Alliance"]="作为联盟的勇士，你可以帮助卡洛尔保护夜色镇那些身处阴暗林地、孤立无援的镇民。"},sec={{t="暗影中的忠诚者",b="在夜色镇，卡洛尔支持卡尔文家族对抗步步逼近城镇的恐怖威胁。他与夜色镇的守卫者之一乔纳森·卡尔文合作，力图在剩下的镇民惨遭屠戮之前，铲除那些超自然的恐怖生物。"},{t="狼人的威胁",b="卡洛尔派遣战士追猎在暮色森林游荡的狼人，尤其是烂果园附近的狼人。这些凶猛的狼人比普通野兽更加危险，无论是旅人还是巡逻队，都会遭到它们的屠杀。卡洛尔召集有实力的战士，削减狼人的数量并调查它们的起源，希望能遏制它们的袭击。"}},faq={{q="卡洛尔是谁？",a="卡洛尔住在夜色镇，支持卡尔文家族。他派遣战士应对暮色森林中的危险威胁，协助保卫城镇。",al={"卡洛尔 夜色镇","卡洛尔是谁","卡洛尔 暮色森林"}},{q="在哪里可以找到卡洛尔？",a="卡洛尔位于夜色镇，那是暮色森林林地中的一座联盟城镇。",al={"卡洛尔在哪里","卡洛尔 位置","卡洛尔 坐标"}},{q="卡洛尔与乔纳森·卡尔文是什么关系？",a="卡洛尔支持卡尔文家族，听从乔纳森·卡尔文的指示，对抗森林中的怪物。",al={"卡洛尔和卡尔文","卡洛尔为谁效力","卡尔文家族 卡洛尔"}},{q="卡洛尔会让你对付哪些敌人？",a="卡洛尔派遣战士猎杀林中的狼人，尤其是烂果园附近的狼人。",al={"卡洛尔 任务","卡洛尔想要什么","狼人任务 卡洛尔"}},{q="为什么暮色森林的狼人威胁如此紧迫？",a="狼人是凶残的掠食者，会攻击视野内的一切。如果不定期猎杀以控制数量，它们很快就会突破夜色镇薄弱的防线；卡洛尔与守夜人一道协调抵御行动。",al={"为什么猎杀暮色森林的狼人","暮色森林 狼人威胁"}},{q="卡洛尔是守夜人的成员吗？",a="不是。卡洛尔认为守夜人安于现状，逐渐对其失望，于是加入了乔纳森·卡尔文的行列，支持卡尔文家族对抗狼人。",al={"卡洛尔 守夜人","卡洛尔是守夜人的成员吗"}}},fx={e997a1f9={q="卡洛尔想要什么？",a="卡洛尔决心铲除盘踞在暮色森林的狼人。他直接奉乔纳森·卡尔文之命，召集有能力的冒险者，追猎潜伏在烂果园等地的野兽，并阻止它们阴暗的腐化蔓延，以免夜色镇遭其吞噬。",al={"卡洛尔的目标","卡洛尔在做什么","卡洛尔想要什么"}},f0ff266f={q="卡洛尔为什么在夜色镇？",a="卡洛尔留驻夜色镇，协助卡尔文家族讨伐林地中的野兽。他在这座饱受困扰的城镇里，协调侦察和狩猎行动，对付徘徊于周围树林和废弃果园中的凶残狼人群。",al={"卡洛尔为什么在这里","卡洛尔为何在夜色镇","卡洛尔为什么在暮色森林"}}},fp="5,164,25.248.0,17.314.0,13.139.0,25.78.0,51.119.0,39.86.0,47.188.0,37.162.0"}
P.entries["npc:calvin-montague"] = {n="卡尔文·蒙泰古",s="在丧钟镇门口，卡尔文·蒙泰古专挑刚刚苏醒、离开墓地的被遗忘者下手，哄骗路人为他跑腿。",h="在丧钟镇门口，卡尔文·蒙泰古专挑刚刚苏醒、离开墓地的被遗忘者下手，哄骗路人为他跑腿。",kw={"潜行者的交易","卡尔文·蒙泰古","骗子","丧钟镇","被遗忘者潜行者","蒙泰古","提瑞斯法林地"},ang={["class:Rogue"]="身为被遗忘者潜行者，你能看出卡尔文·蒙泰古企图操纵不谙世事者的伎俩，不过是一个同行扒手的拙劣骗局。",["race:Undead"]="作为刚刚复生、离开丧钟镇的亡灵，你或许很早就会明白，并非所有Sylvanas的臣民都寻求团结。"},sec={{t="门边的骗子",b="卡尔文·蒙泰古等候在丧钟镇大门外不远处，这里的道路通往提瑞斯法林地。他用虚假的说辞，试图劝说四处游历的冒险者替他送信，既不愿亲自处理信件，也不愿支付合理的送信报酬。幽暗城还有其他姓蒙泰古的知名亡灵，经营着银行业务。卡尔文走的路却不怎么光彩，靠小把戏和欺骗度日。"},{t="潜行者的诡计",b="卡尔文·蒙泰古拿出一封密封的信，请旅人替他送达。头脑敏锐或熟悉地下勾当的人，很快就能看穿他的说辞。新近复生的亡灵或许还在提瑞斯法荒凉的废墟间寻找目标，但卡尔文的提议让人看清，在黑暗女王麾下效力，信任是多么稀缺。"}},faq={{q="卡尔文·蒙泰古是谁？",a="卡尔文·蒙泰古是一名被遗忘者潜行者，在提瑞斯法林地的丧钟镇出口大门附近等候。他试图欺骗新近复生的亡灵，让他们无偿替自己跑腿。",al={"卡尔文·蒙泰古","卡尔文·蒙泰古是谁","卡尔文 丧钟镇"}},{q="卡尔文想让冒险者做什么？",a="卡尔文·蒙泰古用虚假的说辞劝说过路旅人替他送信，希望靠花言巧语获得免费的送信服务。",al={"卡尔文·蒙泰古任务","卡尔文 信件","卡尔文想要什么"}},{q="卡尔文·蒙泰古与幽暗城的银行职员有亲属关系吗？",a="卡尔文与幽暗城知名的银行职员奥菲莉亚、莫提默、威廉和伦道夫·蒙泰古同姓。他们之间尚未确认有任何亲属关系。",al={"蒙泰古家族","幽暗城银行职员 蒙泰古","卡尔文与银行职员的关系"}},{q="在哪里能找到卡尔文·蒙泰古？",a="卡尔文·蒙泰古等候在丧钟镇木制北门外不远处的路边，可以在那里拦住前往提瑞斯法林地的冒险者。",al={"卡尔文位置","卡尔文·蒙泰古在哪里","寻找卡尔文·蒙泰古"}}},fp="15,137,21.411.0,16.292.1,23.167.0,40.149.0,52.152.0,35.149.0"}
P.entries["npc:canaga-earthcaller"] = {n="坎纳甘·地鸣",s="在试炼谷，坎纳甘·地鸣引导部落的新晋萨满祭司接触大地之灵，获得他们的第一件图腾。",h="在试炼谷，坎纳甘·地鸣引导部落的新晋萨满祭司接触大地之灵，获得他们的第一件图腾。",kw={"大地的召唤","坎纳甘","暗矛","杜隆塔尔","大地灵契","唤地者","萨满祭司","试炼谷"},ang={["class:Shaman"]="身为萨满祭司，你会在杜隆塔尔遇见坎纳甘，他是你的第一位精神导师。他制备大地灵契，让你能够与元素交流，并获得自己的大地图腾。",["race:Orc"]="身为兽人，你会发现坎纳甘与谷中的兽人教官并肩工作。他帮助年轻兽人将自己的灵魂与新家园贫瘠的土地相连。",["race:Troll"]="身为巨魔，你会发现坎纳甘是试炼谷中杰出的暗矛人物之一。他指引年轻的巨魔萨满祭司，让他们踏上与灵体同行的道路。"},sec={{t="大地之声",b="坎纳甘·地鸣在试炼谷的赤红峭壁间，指引踏上萨满之道的暗矛巨魔和兽人。他教导初学者静下心来，聆听卡利姆多的低鸣。他们制备大地灵契，以便与灵体交流。"},{t="第一件图腾",b="坎纳甘要求每位学徒收集神圣的材料，前往杜隆塔尔当地的灵魂石地。在那里，他们饮下 大地灵契，亲眼见到元素之灵。在他的指引下，他们获得了自己的大地图腾。"}},faq={{q="坎纳甘·地鸣是谁？",a="坎纳甘·地鸣是试炼谷的一位暗矛巨魔萨满祭司。他指导着刚刚在部落中迈出第一步的年轻萨满祭司。",al={"坎纳甘 传说","坎纳甘 是谁","坎纳甘·地鸣 非玩家角色"}},{q="坎纳甘教导年轻萨满祭司什么？",a="坎纳甘引导部落的萨满祭司在杜隆塔尔完成大地的召唤系列仪式。他调制大地灵契，让寻求第一件图腾的学徒能够感知当地的大地元素之灵，并与之交谈。",al={"杜隆塔尔萨满祭司任务","杜隆塔尔 大地的召唤","坎纳甘 任务"}},{q="坎纳甘制备的大地灵契是什么？",a="大地灵契是坎纳甘用当地材料调制的灵性饮剂。萨满祭司饮下它，便能感知大地中隐藏的灵体，并与显形的元素交谈。",al={"大地灵契 是什么","灵契 传说"}},{q="为什么一位巨魔会在兽人的试炼场训练萨满祭司？",a="第三次大战之后，暗矛部族与萨尔的部落紧密联合，并与兽人一同定居杜隆塔尔。如今，巨魔的萨满祭司和战士在试炼谷与年轻兽人一起训练。",al={"试炼谷为什么有巨魔","试炼谷的暗矛"}},{q="在哪里能找到坎纳甘·地鸣？",a="坎纳甘坐在俯瞰试炼谷东部小径的岩台上，就在主要训练区的南面。",al={"坎纳甘 位置","坎纳甘 在哪里"}}},fp="18,118,17.265.0,15.217.0,26.141.0,37.205.0,40.181.0,60.200.0,38.116.0"}
P.entries["npc:captain-danuvin"] = {n="丹努文队长",s="在哨兵岭，丹努文队长召集西部荒野的守卫者。他指挥人民军的志愿者和新兵巡逻道路，击退豺狼人和匪徒。他下达命令，保护补给线和农田不落入敌人之手。",h="在哨兵岭，丹努文队长召集西部荒野的守卫者。他指挥人民军的志愿者和新兵巡逻道路，击退豺狼人和匪徒。他下达命令，保护补给线和农田不落入敌人之手。",kw={"丹努文队长","格里安·斯托曼","人民军","河爪","哨兵岭","西部荒野"},ang={["class:Warrior"]="身为战士，你可以凭借自己的纪律和力量对抗成群的豺狼人，协助清理大道。",["faction:Alliance"]="尽管王室疏于过问，丹努文队长仍是西部荒野少数维持秩序的军人之一。身为联盟新兵，你可以协助保卫王国。",["race:Human"]="身为人类，你可以帮助丹努文队长保卫家园，让暴风城的粮仓免受劫掠者和野兽侵扰。"},sec={{t="坚守哨兵岭",b="丹努文队长在哨兵岭的防御塔中指挥巡逻。暴风城的正规驻军已经撤离，西部荒野的防御因此变得薄弱。于是，他依靠旅人、农场雇工和志愿参战者，勉力维持平原上的秩序。"},{t="巡逻边境",b="丹努文队长密切关注哨兵岭周围的道路和旷野。河爪豺狼人在中部哨站附近发动袭击，因此他派出巡逻队削减它们的数量，确保周边安全。他的命令让劫掠者和趁火打劫之徒无法包围营地。"}},faq={{q="在哪里可以找到丹努文队长？",a="丹努文队长就在哨兵岭，那是联盟在西部荒野中部的哨站。他通常在俯瞰道路的防御塔附近。",al={"丹努文队长位置","丹努文队长在哪里","丹努文队长西部荒野"}},{q="丹努文队长代表哪个阵营？",a="丹努文队长效力于联盟，支援西部荒野当地的守卫者。他与格里安·斯托曼及人民军密切合作。",al={"丹努文队长阵营","丹努文队长效力于谁"}},{q="他会给冒险者指派什么职责？",a="丹努文队长派新兵巡逻平原，击退向哨兵岭逼近的河爪豺狼人。",al={"丹努文队长任务","丹努文队长想要什么","巡逻西部荒野 任务"}},{q="丹努文队长为什么依靠志愿者，而不是 暴风城军队？",a="暴风城已不再向西部荒野派驻部队。丹努文队长和哨兵岭的领袖们只能依靠雇佣兵和民兵新兵。",al={"为什么没有 暴风城军队","为什么依靠民兵","暴风城驻军西部荒野"}},{q="丹努文队长在西部荒野以外还有什么联系吗？",a="丹努文队长牵挂的是自己的故乡西部荒野。他发誓要与留下的居民并肩坚守，因此将精力集中在哨兵岭周围的平原和道路上。",al={"丹努文队长 赤脊山","丹努文队长的联系"}},{q="与格里安·斯托曼相比，他担任什么职责？",a="格里安·斯托曼领导人民军，统筹西部荒野的防御。丹努文队长负责战地战术、道路巡逻，以及应对据点附近的豺狼人威胁。",al={"格里安·斯托曼与丹努文队长","丹努文队长负责指挥吗"}}},fp="15,238,16.246.0,23.254.0,33.149.0,44.142.0,42.112.0,67.143.0,50.163.0,47.171.0"}
P.entries["npc:captain-grayson"] = {n="葛瑞森船长",s="在西部荒野灯塔，葛瑞森船长守护着那盏曾让他丧命的航灯。他的船撞上了漆黑的海岸，如今他照看着灯火，不让其他水手重蹈他的覆辙。",h="在西部荒野灯塔，葛瑞森船长守护着那盏曾让他丧命的航灯。他的船撞上了漆黑的海岸，如今他照看着灯火，不让其他水手重蹈他的覆辙。",kw={"葛瑞森船长","幽灵海盗","葛瑞森","灯塔","老瞎眼","西部荒野","西部荒野灯塔"},ang={["class:Paladin"]="作为圣骑士，你可以帮助葛瑞森，履行保护无助者、击退凶残鱼人的神圣职责，尽管他是个亡灵。",["class:Priest"]="作为牧师，你可以抚慰葛瑞森不得安息的灵魂。亲眼目睹无辜的一家人惨死后，内疚与悲痛让他的灵魂滞留人间。",["faction:Alliance"]="迪菲亚潜行者扼住了西部荒野的咽喉，暴风城又疏于照管边疆，联盟的旅人必须回应葛瑞森的恳求，让灯塔的火焰持续燃烧。"},sec={{t="礁石夺去的生命",b="葛瑞森船长生前是一船之长，曾航行于东部王国的南部海域。一天夜里，他的船驶近西部荒野险峻的浅滩时，灯塔的火光熄灭了。船撞上礁石，葛瑞森随船殒命。他醒来时已成为无法离开尘世的幽魂，被束缚在这片海岸。"},{t="灯塔下的惨剧",b="死后，葛瑞森船长来到西部荒野灯塔，希望弄清生命尽头等待着他的是什么。在那里，他看见臭名昭著的鱼人老瞎眼赶走了守塔人及其家人。勇敢的守塔人一家回来重新点燃了灯火。但老瞎眼召集了周围的鱼人，带头发动了第二次残暴的屠杀。葛瑞森只能眼睁睁地看着这一家人惨遭杀害。"},{t="幽魂的守望",b="守塔人一家已死，西部荒野也因无人照管而日渐衰败，葛瑞森船长用幽灵之躯承担起守护灯火的庄严重任。他请求过往的旅人为灯塔的烈焰收集燃料。他还想为惨遭杀害的一家人复仇：猎杀老瞎眼，击退沿岸的鱼人。"}},faq={{q="葛瑞森船长是谁？",a="葛瑞森船长是西部荒野灯塔的一名人类海盗幽灵。航灯熄灭时，他的船撞上了海岸，如今他照看着灯火，保护过往的水手。",al={"葛瑞森身份","幽灵海盗是谁","灯塔幽灵"}},{q="葛瑞森船长是怎么死的？",a="葛瑞森船长的海盗船撞上了西部荒野沿岸险恶的礁石，他也因此丧命。那一夜灯塔没有亮光，他和船员们毫无预警，船便撞得粉碎。",al={"葛瑞森之死","葛瑞森如何成为幽灵","葛瑞森船长的死因"}},{q="真正的守塔人遭遇了什么？",a="沿岸的鱼人袭击了守塔人及其家人。这勇敢的一家人逃过了第一次袭击，又回来重新点燃航灯，但老瞎眼召集鱼人再次进攻，在葛瑞森眼前杀害了他们。",al={"守塔人在哪里","守塔人遭遇了什么","灯塔一家"}},{q="老瞎眼是谁？",a="老瞎眼是西部荒野海岸上一名狡诈凶残的鱼人酋长。他率众袭击并杀害了守塔人一家，还威胁着所有试图让航灯保持明亮的人。",al={"老瞎眼背景故事","老瞎眼","西部荒野鱼人首领"}},{q="葛瑞森为什么想让灯塔一直亮着？",a="葛瑞森在海岸一片漆黑时溺亡，因此将保持灯塔明亮视为死后的庄严职责。他想让其他水手免于在浅滩上遭受同样的命运。",al={"葛瑞森的动机","为何点燃航灯"}},{q="葛瑞森船长对冒险者有敌意吗？",a="没有。虽然葛瑞森生前是个海盗，但他对生者并无恶意。他目睹了太多屠杀，只求安宁，也希望有人帮忙照看灯火。",al={"葛瑞森是否友善","葛瑞森敌意"}}},fx={["8f770f95"]={q="葛瑞森船长属于哪一方？",a="葛瑞森船长不为任何凡人王国效力。他生前曾是一名海盗船长，如今对活着的旅人保持中立，但也寻求愿意保障海岸安全的旅人相助。死后，他真正效忠的并非暴风城或任何海军，而是西部荒野灯塔，以及航海者的平安通行。",al={"葛瑞森船长阵营","葛瑞森属于联盟还是部落","葛瑞森为谁效力"}},["2ee261a8"]={q="葛瑞森船长为什么在灯塔？",a="葛瑞森的船因灯塔未亮而在西部荒野海岸撞毁，此后他便被引到了灯塔。作为受缚于凡人世界的幽灵，他来到这里，却只能无助地看着老瞎眼和它的鱼人屠杀守塔人的家人。守塔人死后，葛瑞森决心留下，亲自守护灯塔。",al={"葛瑞森船长为何在这里","葛瑞森为何来到西部荒野灯塔","葛瑞森因何来到灯塔"}}},fp="15,183,29.290.0,21.372.0,15.310.0,23.171.0,28.203.0,44.217.0,20.193.0,46.176.0,42.160.0"}
P.entries["npc:captain-greenskin"] = {n="绿皮队长",s="在死亡矿井的海湾中，绿皮队长正为艾德温·范克里夫筹备一艘战舰。这位地精海盗为迪菲亚潜行者监督船员和建造工程，准备让这艘巨型铁甲舰驶向暴风城，发动进攻。",h="在死亡矿井的海湾中，绿皮队长正为艾德温·范克里夫筹备一艘战舰。这位地精海盗为迪菲亚潜行者监督船员和建造工程，准备让这艘巨型铁甲舰驶向暴风城，发动进攻。",kw={"绿皮队长","死亡矿井","地精海盗","绿皮","巨型战舰","重拳","范克里夫"},ang={["class:Rogue"]="身为潜行者，你会发现绿皮是迪菲亚潜行者海盗的头目，战舰甲板上的海盗和打手严密护卫着他。",["faction:Alliance"]="对联盟而言，绿皮队长统领的海上力量是迪菲亚潜行者叛乱带来的威胁。如果他的巨型战舰抵达海岸，西部荒野和暴风城缺乏防御的海岸将面临直接威胁。"},sec={{t="巨舰之主",b="绿皮队长在死亡矿井海湾中尚未完工的巨型战舰主甲板上踱步。他是一名经验丰富的地精水手，被招入艾德温·范克里夫的核心圈子，负责将一处地下洞穴改造成建造战舰的干船坞。"},{t="海盗的船员",b="绿皮队长统领的是亡命之徒，而非石匠或匪徒。他的船员包括凶悍的牛头人大副重拳先生，以及担任船上厨师的鱼人曲奇。他们共同把守跳板和上层甲板，守卫着通往舰桥顶端范克里夫私人船舱的道路。"}},faq={{q="绿皮队长是谁？",a="绿皮队长是一名受雇于艾德温·范克里夫的地精海盗船长，负责监督迪菲亚潜行者在死亡矿井中秘密建造的战舰竣工并投入使用。",al={"绿皮的故事","绿皮是谁","绿皮队长"}},{q="绿皮在加入迪菲亚潜行者之前来自哪里？",a="没有记录说明绿皮在受雇于范克里夫之前曾在哪里航行。他在死亡矿井中指挥迪菲亚潜行者的巨型战舰及其船员。",al={"绿皮的来历","绿皮来自哪里","绿皮 藏宝海湾"}},{q="绿皮队长麾下有哪些人？",a="绿皮统领着牛头人大副重拳先生、鱼人厨师曲奇，以及在铁甲舰甲板上巡逻的迪菲亚潜行者海盗。",al={"绿皮的船员","大副","绿皮的手下"}},{q="绿皮在死亡矿井中有何任务？",a="绿皮负责让这艘庞大的铁甲战舰具备出海能力，准备从地下海湾驶入无尽之海，进攻暴风城。",al={"绿皮做什么","绿皮为何在这里"}},{q="在哪里可以找到绿皮队长？",a="绿皮队长在停泊于死亡矿井最深处洞穴的巨型战舰主甲板上踱步，守卫着通往艾德温·范克里夫所在之处的道路。",al={"绿皮的位置","绿皮队长在哪里"}},{q="绿皮队长是迪菲亚潜行者的成员，还是一名雇佣兵？",a="绿皮队长是一名直接受雇于艾德温·范克里夫的海盗船长，指挥着配合迪菲亚潜行者阴谋的海上部队。",al={"绿皮属于迪菲亚潜行者吗","绿皮的阵营"}}},fx={["9c1c4117"]={q="绿皮队长为什么在这里？",a="绿皮队长受艾德温·范克里夫雇用，负责监督迪菲亚潜行者巨型主宰战舰的建造并指挥战舰。他留在死亡矿井深处的海湾中，指挥自己的海盗船员，确保战舰完工并装备齐全。",al={"绿皮为什么在死亡矿井","绿皮队长为什么在这里","绿皮在死亡矿井的目的"}},["6bcae29e"]={q="绿皮队长想要什么？",a="作为受雇的地精船长，绿皮追求财富和统率舰队的刺激。他打算在死亡矿井的海湾中建造完这艘庞大的铁甲战舰，然后驾船驶入无尽之海，为艾德温·范克里夫对付暴风城的阴谋效力。",al={"绿皮的目标","绿皮队长想要什么","绿皮的动机"}},["433e5911"]={q="绿皮队长为何令人畏惧？",a="绿皮队长统率着艾德温·范克里夫主宰战舰上的海盗船员，手下还有他的牛头人副手重拳先生这样的凶残掠夺者。他手持砍刀和涂毒鱼叉，在甲板上巡行，挡在入侵者和范克里夫之间。",al={"绿皮为何令人畏惧","绿皮队长的名声","绿皮有名吗"}}},fp="17,219,24.224.0,15.276.0,25.175.0,56.135.0,35.128.0,45.140.0,37.144.0,67.155.0"}
P.entries["npc:captain-rugelfuss"] = {n="拉格弗斯上尉",s="在洛克莫丹的南部门户，拉格弗斯上尉面对突如其来的穴居人暴动。这位严厉的矮人组织起边境防御。",h="在洛克莫丹的南部门户，拉格弗斯上尉面对突如其来的穴居人暴动。这位严厉的矮人组织起边境防御。",kw={"拉格弗斯上尉","铁炉堡守卫","洛克莫丹","巡山人","拉格弗斯","穴居人威胁","国王谷"},ang={["class:Warrior"]="身为战士，你或许熟悉拉格弗斯这种直接的做法：用刀剑与盾牌扫清前线的敌人。",["faction:Alliance"]="身为联盟的旅人，你知道，当大军在他处作战时，守护家园、抵御野蛮入侵同样至关重要。",["race:Dwarf"]="身为矮人，你能从拉格弗斯上尉抵御地下之敌、守护祖传山口的行动中，看到铁炉堡的决心。"},sec={{t="坚守南部门户",b="拉格弗斯上尉驻守国王谷，守卫洛克莫丹的南部门户。铁炉堡的兵力分散在世界各地，捉襟见肘，因此像他这样的老练军官便肩负起保卫本土的职责。他将军中的礼节搁在一旁，专心应对边境的危险。"},{t="穴居人入侵",b="穴居人从古老的洞穴中涌入高地。他们击溃了外围的矮人巡逻队，并在附近建立了坚固的据点。拉格弗斯号召有能力的旅人削减他们的兵力，将他们赶离道路，保卫国王的领土。"},{t="前线侦察",b="拉格弗斯麾下的巡山人在关口外保持警戒。他们不断侦察穴居人的营地。"}},faq={{q="拉格弗斯上尉是谁？",a="在国王谷内、洛克莫丹的南部门户，拉格弗斯上尉指挥着铁炉堡的防御。他守卫边境，抵御穴居人的暴动。",al={"拉格弗斯上尉背景故事","拉格弗斯是谁","拉格弗斯 洛克莫丹"}},{q="在哪里可以找到拉格弗斯上尉？",a="你可以在国王谷的南门附近找到拉格弗斯上尉。他守卫着从洛克莫丹通往丹莫罗的南部隘口。",al={"拉格弗斯在哪里","拉格弗斯上尉位置"}},{q="拉格弗斯上尉为何担忧穴居人？",a="最近的穴居人暴动威胁着矮人的定居点和补给线。穴居人已经抵达南部门户，并袭击了铁炉堡的巡逻队，使国王的领土陷入险境。",al={"为何对抗穴居人","穴居人威胁 洛克莫丹"}},{q="拉格弗斯为何不在意军中的礼节？",a="拉格弗斯将礼节搁在一旁，因为在国王的领土遭受攻击时，他认为这些礼节只会分散注意力。他要的是在边境采取切实的行动。",al={"拉格弗斯性格","稍息 种族"}}},fx={["506fbcb9"]={q="拉格弗斯上尉效忠哪一方？",a="拉格弗斯上尉坚定地支持铁炉堡和 大联盟。作为守卫洛克莫丹南部通路的军官，他誓言保卫矮人的领土，维护国王麦格尼·铜须的权威，抵御外来威胁。",al={"拉格弗斯上尉阵营","拉格弗斯上尉为谁效力","拉格弗斯上尉是否属于联盟"}},["8c27dafb"]={q="拉格弗斯上尉想要什么？",a="拉格弗斯上尉想要镇压威胁国王谷及国王领土的穴居人暴动。他依靠过往旅人削减入侵穴居人的数量，将这些生物从洛克莫丹的道路上赶走。",al={"拉格弗斯上尉需要什么","拉格弗斯上尉的目标","拉格弗斯上尉想做什么"}},["0fa68497"]={q="拉格弗斯上尉为何驻守国王谷？",a="拉格弗斯上尉受命驻守洛克莫丹南部边境，守卫通往丹莫罗的山口。穴居人成群涌入周围的山谷，必须有组织严密的矮人军队驻守，才能守住道路，协调国王领土的防御。",al={"拉格弗斯上尉为何在这里","拉格弗斯上尉为何在南门","拉格弗斯上尉的驻地"}}},fp="17,134,25.270.0,19.263.0,24.96.1,25.159.0,37.137.0,48.184.0,50.144.0"}
P.entries["npc:captain-shatterskull"] = {n="沙塔尔·碎颅",s="在莫尔杉营地，沙塔尔·碎颅统领着部落北部边境的防御。身为一名经验丰富的兽人指挥官，他协调各方力量，击退在战歌峡谷附近争夺边境的暗夜精灵部队。",h="在莫尔杉营地，沙塔尔·碎颅统领着部落北部边境的防御。身为一名经验丰富的兽人指挥官，他协调各方力量，击退在战歌峡谷附近争夺边境的暗夜精灵部队。",kw={"贫瘠之地","沙塔尔·碎颅","卡德拉克","莫尔杉营地","兽人队长","银翼","战歌"},ang={["faction:Horde"]="对于从南贫瘠之地赶来的部落勇士而言，沙塔尔·碎颅守卫着北部边境，抵御来自灰谷的暗夜精灵入侵。",["race:Orc"]="作为一名兽人，沙塔尔·碎颅守护着部落来之不易的土地，体现了这个被外人视为入侵者的民族的尚武精神。"},sec={{t="北部边境的守护者",b="在莫尔杉营地，沙塔尔·碎颅守卫着部落在灰谷边缘的据点。他与卡德拉克等军官并肩作战，对抗试图夺回边境地区的暗夜精灵哨兵和银翼部队。围绕灰谷木材与古老土地的争夺，让贫瘠之地的边境始终面临威胁。"}},faq={{q="沙塔尔·碎颅是谁？",a="沙塔尔·碎颅是莫尔杉营地一名经验丰富的兽人指挥官，负责指挥部落抵御暗夜精灵部队。",al={"沙塔尔·碎颅身份","沙塔尔·碎颅是谁","沙塔尔·碎颅非玩家角色"}},{q="在哪里可以找到沙塔尔·碎颅？",a="你可以在贫瘠之地北端、进入灰谷之前的莫尔杉营地找到沙塔尔·碎颅。",al={"沙塔尔·碎颅位置","沙塔尔·碎颅在哪里","莫尔杉营地沙塔尔·碎颅"}},{q="他在莫尔杉营地担任何种职责？",a="在莫尔杉营地，沙塔尔·碎颅指挥部落北部边境的防御，并集结勇士对抗联盟的银翼要塞。",al={"沙塔尔·碎颅做什么","沙塔尔·碎颅职责","莫尔杉指挥官"}},{q="沙塔尔·碎颅与谁共事？",a="沙塔尔·碎颅与卡德拉克等前线军官共事，为边境冲突协调防御与征募事宜。",al={"沙塔尔·碎颅盟友","卡德拉克与沙塔尔·碎颅"}}},fp="20,189,31.333.0,28.130.0,40.110.0,39.163.0,40.144.0"}
P.entries["npc:captain-stoutfist"] = {n="斯托菲队长",s="在米奈希尔港，斯托菲队长指挥防御，抵御龙喉氏族的进攻。这位矮人军官统筹驻军的防御与反击，确保这座联盟港口不致陷落。",h="在米奈希尔港，斯托菲队长指挥防御，抵御龙喉氏族的进攻。这位矮人军官统筹驻军的防御与反击，确保这座联盟港口不致陷落。",kw={"斯托菲队长","龙喉氏族","丹奥加兹","矮人","铁炉堡","米奈希尔港","纳克罗什","湿地"},ang={["class:Warrior"]="身为战士，你会发现斯托菲是一位直言不讳的战术家，比起谨慎加固防御，他更倾向于大胆出击，派战士摧毁敌方火炮并消灭其首领。",["faction:Alliance"]="斯托菲队长守卫着联盟最重要的海运枢纽之一，确保卡兹莫丹、暴风城与远方前哨之间的航线畅通。",["race:Dwarf"]="身为矮人，你能从斯托菲身上看到铁炉堡坚定的军事意志，他受命守护远在群峰之下的低地重要设施。"},sec={{t="米奈希尔的守卫者",b="米奈希尔港是连接铁炉堡、暴风城与湿地及外海的主要深水港。斯托菲队长负责指挥城镇防御，保护码头、居民和驻军免受周边威胁。沼泽地危机四伏，但最大的威胁来自叛乱兽人有组织的推进。"},{t="龙喉氏族的威胁",b="龙喉氏族氏族自第二次战争以来便在湿地占据据点，如今正向道路和山口推进。兽人渗入丹奥加兹，威胁着连接洛克莫丹、铁炉堡与米奈希尔港的陆路。斯托菲兵力不足，只能依靠巡山人瓦斯塔格·铁腭派来的联盟志愿者阻挡他们。"},{t="打击纳克罗什",b="斯托菲队长率军进攻兽人营地，而非坐等围城。他指示盟军夺取维尔加挖掘场附近的战旗，破坏准备发动进攻的龙喉氏族投石车，并杀死该氏族在当地的残暴酋长纳克罗什·碎颅。斯托菲力求在米奈希尔港失守之前，瓦解兽人的攻势。"}},faq={{q="斯托菲队长是谁？",a="斯托菲队长指挥守卫米奈希尔港的矮人部队。他组织驻军防御，评估整个地区的威胁，并招募志愿者击退威胁港口的敌人。",al={"斯托菲队长","斯托菲 米奈希尔","米奈希尔 队长"}},{q="斯托菲队长在哪里？",a="斯托菲队长驻守在米奈希尔港内，这里是联盟在湿地西海岸的主要据点。",al={"斯托菲位置","斯托菲队长在哪里","寻找斯托菲"}},{q="斯托菲队长为什么需要外援？",a="当地驻军分散在湿地各处，兵力捉襟见肘。龙喉氏族兽人已经占据丹奥加兹的山口，正向城镇推进，斯托菲无力同时发动反击并守卫港口。",al={"斯托菲为何需要帮助","米奈希尔 防御问题"}},{q="纳克罗什 碎颅者是谁？",a="纳克罗什 碎颅者领导着在湿地活动的龙喉氏族兽人。斯托菲队长下令杀死他，以打乱兽人的协同行动，保护米奈希尔港免遭全面进攻。",al={"纳克罗什是谁","纳克罗什 碎颅者","龙喉氏族 湿地首领"}},{q="丹奥加兹与斯托菲队长的任务有什么联系？",a="丹奥加兹是连接洛克莫丹、铁炉堡与湿地的重要山口。当龙喉氏族兽人攻入山口时，巡山人瓦斯塔格·铁腭警告说米奈希尔正面临危险，并派冒险者协助斯托菲队长加强港口防御。",al={"丹奥加兹 斯托菲","丹奥加兹告急 关联"}},{q="龙喉氏族投石车构成什么威胁？",a="龙喉氏族投石车能在正面围攻中轰击米奈希尔港的防御工事。斯托菲指示勇士们在它们进入射程之前将其破坏。",al={"纳克罗什的优势 投石车","龙喉氏族投石车"}}},fx={["40162abd"]={q="斯托菲队长效忠哪一方？",a="斯托菲队长效忠联盟和矮人王国铁炉堡。他驻扎在米奈希尔港，指挥镇上的驻军，守护这座至关重要的港口城镇，并保护往来于湿地与卡兹莫丹群山之间的旅人。",al={"斯托菲队长所属阵营","斯托菲是联盟的吗","斯托菲为谁效力"}},["31290b24"]={q="斯托菲队长想要什么？",a="斯托菲队长想彻底铲除步步逼近的龙喉兽人威胁。他要从龙喉兽人的营地夺取战旗，烧毁奈克罗什为围攻米奈希尔港而建造的投石车，并杀死他们的酋长奈克罗什·碎骨者，以确保米奈希尔港的安全。",al={"斯托菲队长的目标","斯托菲需要什么","斯托菲的目标"}},["6891235c"]={q="斯托菲队长为何在米奈希尔港？",a="斯托菲队长驻扎在米奈希尔港，负责指挥港口防务。丹奥加兹的战略山道已被敌对的龙喉兽人封锁，他留在这里召集士兵和佣兵，保护港口免遭摧毁。",al={"斯托菲为何在湿地","斯托菲队长在米奈希尔的职责","斯托菲为何在这里"}},["2b51270f"]={q="斯托菲队长与谁有联系？",a="斯托菲队长与卡兹莫丹各地的联盟守军协调行动，并接收瓦斯塔格·铁腭调派的援军。他指挥米奈希尔城堡的驻军，依靠途经此地的联盟勇士直接向龙喉氏族发起进攻。",al={"斯托菲队长的盟友","斯托菲队长与谁共事","斯托菲队长的关系"}}},fp="17,190,20.332.0,20.365.0,20.371.1,25.212.0,35.110.0,45.226.0,29.193.0,58.260.0,44.163.0"}
P.entries["npc:captain-thalo-thas-brightsun"] = {n="沙罗萨斯船长",s="在棘齿城的码头，沙罗萨斯船长对联盟旅客始终态度友善。这位私掠船长为热砂港效力，对驻守北方城堡的塞拉摩部队炮击他的船只一事心怀不满。",h="在棘齿城的码头，沙罗萨斯船长对联盟旅客始终态度友善。这位私掠船长为热砂港效力，对驻守北方城堡的塞拉摩部队炮击他的船只一事心怀不满。",kw={"贫瘠之地","沙罗萨斯","北方城堡","棘齿城","热砂港","萨罗丹船队","沙罗萨斯·亮阳"},ang={["faction:Alliance"]="沙罗萨斯在港口与你交谈时态度友善，但北方城堡的塞拉摩部队已逼得他与你的敌人暗中密谋。",["faction:Horde"]="沙罗萨斯给了部落一个理由，去攻打北方城堡，重创联盟在卡利姆多中部沿岸的海军火炮力量。"},sec={{t="棘齿城的私掠船长",b="沙罗萨斯船长在棘齿城的码头统率着萨罗丹船队，效力于热砂港旗下。只要带来钱币，棘齿城就欢迎任何旗帜下的商人，但贫瘠之地沿岸的贸易始终笼罩在危险之中。北方城堡就在港口南面不远处，那里的重炮威胁着中立航道。沙罗萨斯对来访的旅客依然态度友善，但守军对他船队的袭击已让他渐渐失去耐心。"},{t="与北方城堡的私战",b="公开进攻北方城堡可能危及棘齿城的中立地位，因此沙罗萨斯无法派遣船队攻打堡垒。他转而雇用能干的部落佣兵，替他讨还这笔血债。他们的袭击旨在摧毁火炮，并解救他被俘的船员。借助部落的援手，沙罗萨斯既能保护自己的航运利益，又能避免招致联盟对热砂港的直接报复，也不必公开卷入冲突。"}},faq={{q="沙罗萨斯船长是谁？",a="沙罗萨斯船长在棘齿城指挥萨罗丹船队，为热砂港效力。",al={"沙罗萨斯·亮阳","沙罗萨斯是谁","棘齿城船长"}},{q="他为什么对北方城堡心怀不满？",a="北方城堡的联盟部队多次用重炮轰击沙罗萨斯的商船，并关押他的水手，扰乱了沿岸的贸易。",al={"为什么攻打北方城堡","沙罗萨斯与北方城堡的纠纷","为什么痛恨联盟"}},{q="他为什么只雇用部落攻打北方城堡？",a="沙罗萨斯在棘齿城对联盟旅客保持着友善的外交姿态，却无法要求效忠联盟的人攻打自己的堡垒。部落则有理由削弱塞拉摩的军事前哨。",al={"联盟能否做他的任务","为什么仅限部落","沙罗萨斯联盟任务"}},{q="他属于联盟还是部落？",a="沙罗萨斯不属于这两个阵营中的任何一方。他效忠的是热砂港和自己的私掠船队，但眼下的恩怨让他与部落有了共同的利益。",al={"沙罗萨斯阵营","沙罗萨斯是部落吗","沙罗萨斯是中立的吗"}}},fp="28,209,20.444.0,29.402.0,36.115.0,35.163.0,53.193.0,44.180.0"}
P.entries["npc:captured-mountaineer"] = {n="被俘虏的巡山人",s="在布瑞尔，一名被俘的铁炉堡巡山人被关押在恐惧之末旅店地下。被遗忘者将他捆绑起来，供皇家药剂师学会进行实验。",h="在布瑞尔，一名被俘的铁炉堡巡山人被关押在恐惧之末旅店地下。被遗忘者将他捆绑起来，供皇家药剂师学会进行实验。",kw={"新的瘟疫","药剂师乔汉","布瑞尔地下室","被俘虏的巡山人","矮人囚徒","恐惧之末旅店","铁炉堡斥候"},ang={["race:Dwarf"]="对矮人而言，看到一位铁炉堡同胞被囚禁在被遗忘者的旅店地下，遭受炼金实验，便能看出被遗忘者对生者的敌意。",["race:Undead"]="对被遗忘者而言，活着的联盟俘虏可供皇家药剂师学会研究，完善一种针对 Scourge 和生者的瘟疫。"},sec={{t="地窖中的囚徒",b="在布瑞尔的恐惧之末旅店地下，一名铁炉堡巡山人被关押在远离卡兹莫丹的地方。楼上的客人饮酒之时，皇家药剂师学会正用他试验调制的药剂。药剂师乔汉和他的同僚用活着的联盟成员试验尚在研制的瘟疫，测试他们的毒素杀人有多快，又有多痛苦。"}},faq={{q="被俘虏的巡山人是谁？",a="他是一名来自铁炉堡的联盟斥候，如今被被遗忘者关押在布瑞尔恐惧之末旅店的地下室。",al={"这个矮人是谁","布瑞尔旅店里的矮人","被俘的矮人"}},{q="被遗忘者为什么把他留在地下室里，还让他活着？",a="皇家药剂师学会留着他的性命，是为了用他做实验。乔汉等药剂师给他服用实验药剂，研究这些药剂对活着的矮人有什么影响。",al={"为什么留他活命","他为什么在旅店里","他们在对矮人做什么"}},{q="他在实验中遭遇了什么？",a="药剂师们在研制一种新瘟疫时，强迫他吞下调制的药剂。致命的混合药剂夺走了他的性命，显现出毒素研制的进展。",al={"矮人会死吗","新的瘟疫中发生了什么"}},{q="还有谁会在这里与他接触？",a="亡灵卫兵将被俘的巡山人关押在旅店地窖里，等待处置。药剂师也会到这里进行实验。",al={"谁与矮人交谈","瑞尼·劳尔"}}},fp="20,162,24.332.0,32.113.0,55.164.0,37.139.1,38.145.0"}
P.entries["npc:captured-scarlet-zealot"] = {n="血色十字军俘虏",s="在布瑞尔的恐惧之末旅店下方，一名血色十字军狂热者被关押于此。被遗忘者的药剂师用他来测试为皇家药剂师学会调制的药剂。",h="在布瑞尔的恐惧之末旅店下方，一名血色十字军狂热者被关押于此。被遗忘者的药剂师用他来测试为皇家药剂师学会调制的药剂。",kw={"药剂师乔汉","布瑞尔","血色十字军俘虏","恐惧之末旅店","囚犯","血色十字军","提瑞斯法林地"},ang={["class:Priest"]="血色十字军的狂热者宣称圣光属于他们，但这名囚犯坚定不移的信仰无法让他摆脱被遗忘者的囚禁。",["race:Undead"]="在布瑞尔的被遗忘者眼中，这个身缚锁链的狂热者代表着那些企图将他们赶尽杀绝的十字军。他们将他交给一名药剂师，充作试验材料。"},sec={{t="布瑞尔满怀怨恨的俘虏",b="在恐惧之末旅店下方，一名血色十字军的狂热者身缚锁链，仍不肯屈服。他坚定不移的信仰体现了他所属组织的信念，而他将周围的亡灵视为怪物。他呼求圣光庇护自己，免受囚禁他的邪恶生物侵害。被遗忘者俘虏他并非出于仁慈。作为一个活人，他是药剂师乔汉宝贵的试验材料，后者用他来检验正在研制的实验性瘟疫和毒素的致命程度。"}},faq={{q="为什么布瑞尔的血色十字军狂热者被留着性命？",a="被遗忘者将他囚禁在恐惧之末旅店下方，作为活人试验品，用来测试皇家药剂师学会正在研制的毒药和化学药剂。",al={"血色 狂热者为何被俘","为何留狂热者活口","布瑞尔地下室的狂热者是谁"}},{q="在哪里能找到这名俘虏？",a="他被关押在提瑞斯法林地布瑞尔镇中心的恐惧之末旅店地下室里。",al={"血色十字军俘虏在哪里","血色 狂热者位置","布瑞尔的狂热者"}},{q="他如何对待周围的被遗忘者？",a="即使身陷囚禁，他仍狂热地抗拒，呼求圣光保护自己免受亡灵看守侵害，并发誓血色十字军会将他们从艾泽拉斯清除。",al={"狂热者说什么","狂热者对话","瑞尼 劳尔和狂热者"}}},fp="23,155,25.375.0,44.179.0,30.96.0,45.162.0"}
P.entries["npc:carendin-halgar"] = {n="凯伦丁·哈加尔",s="在幽暗城的魔法区，凯伦丁·哈加尔向被遗忘者术士传授黑暗法术。他言辞尖刻，缺乏耐心，教导学生束缚来自扭曲虚空的恶魔，包括虚空行者和魅魔。",h="在幽暗城的魔法区，凯伦丁·哈加尔向被遗忘者术士传授黑暗法术。他言辞尖刻，缺乏耐心，教导学生束缚来自扭曲虚空的恶魔，包括虚空行者和魅魔。",kw={"凯伦丁·哈加尔","虚空中的生物","被遗忘者","哈加尔","魔法区","魅魔","誓缚","训练师","幽暗城","虚空行者","术士"},ang={["class:Warlock"]="身为术士，你可以在洛丹伦向凯伦丁·哈加尔学习，在他的引导下通过试炼，束缚虚空行者和魅魔。",["faction:Horde"]="身为部落的一员，你可以向凯伦丁·哈加尔寻求东部地区的术士训练，他也与远在海对岸卡利姆多的黑暗法术修习者保持协作。",["race:Undead"]="身为亡灵，你或许能从凯伦丁·哈加尔身上认出被遗忘者的精神：他将恶魔视为可以驯服和利用的工具，毫无怜悯，也毫不犹豫。"},sec={{t="黑暗法术大师",b="凯伦丁·哈加尔在幽暗城的魔法区训练术士。他要求学生专注、服从，对失败、犹豫或软弱几乎毫无耐心。他的学生不再局限于简单的咒语，而是开始召唤恶魔、操纵灵魂。在他的指导下，他们学习被遗忘者驱使恶魔的手段。"},{t="征服虚空",b="凯伦丁·哈加尔教导术士将危险的恶魔束缚于自己的意志之下。他派学生奔赴洛丹伦各地乃至更远的地方，收集用于召唤法阵的古老符文、符文石和纯净的凡人精华。他的课程涵盖虚空生物和魅魔。术士要想驾驭恶魔，就必须先将其束缚，以免被它吞噬。"}},faq={{q="在哪里可以找到凯伦丁·哈加尔？",a="凯伦丁·哈加尔位于幽暗城的魔法区，周围聚集着研习邪能与暗影魔法的人。",al={"凯伦丁·哈加尔位置","幽暗城术士训练师位置","哈加尔在哪"}},{q="凯伦丁·哈加尔对术士有何作用？",a="凯伦丁·哈加尔指导部落术士学习召唤和束缚恶魔的仪式，包括虚空行者和魅魔。",al={"凯伦丁做什么","哈加尔的作用","凯伦丁任务"}},{q="凯伦丁·哈加尔的性格如何？",a="凯伦丁·哈加尔说话直率，要求苛刻，缺乏耐心。他要求迅速见到成果，厌恶浪费时间和找借口。",al={"哈加尔的性情","凯伦丁友善吗","凯伦丁·哈加尔背景故事"}},{q="凯伦丁为什么需要用纯洁的心进行召唤仪式？",a="在召唤魅魔的课程中，凯伦丁·哈加尔的助手高德瑞克·法杉派学徒去获取纯洁之人未受玷污的心脏。他们的纯真与精华会将恶魔引入束缚法阵。",al={"纯洁者的心的用途","凯伦丁召唤魅魔","为什么需要纯洁者的心"}},{q="凯伦丁·哈加尔会与幽暗城以外的术士往来吗？",a="会。凯伦丁·哈加尔会派有潜力的学生前往贫瘠之地，向斯坦哈德·法尔杉继续求学。",al={"凯伦丁的关系","哈加尔奥格瑞玛","甘鲁尔·血眼凯伦丁"}},{q="凯伦丁会派进阶术士去拜访谁？",a="凯伦丁·哈加尔会派已经掌握基础恶魔的学徒寻求进一步指导，其中一位导师就是贫瘠之地性情古怪的召唤师斯坦哈德·法尔杉。",al={"寻找斯坦哈德","凯伦丁派人去见谁","哈加尔的下一位导师"}}},fp="15,176,23.311.0,22.344.1,35.107.0,49.122.0,43.124.0,60.203.0,66.105.0,48.159.0"}
P.entries["npc:caretaker-folsom"] = {n="管理员弗索姆",s="在暴风城的运河沿岸、花园区附近，管理员弗索姆看守着一个贵族家庭留下的财产。他曾在弗林特雷庄园效力，如今则变卖那场血案后留下的物品。",h="在暴风城的运河沿岸、花园区附近，管理员弗索姆看守着一个贵族家庭留下的财产。他曾在弗林特雷庄园效力，如今则变卖那场血案后留下的物品。",kw={"运河","管理员弗索姆","弗林特雷","弗索姆","密斯特曼托","公园","斯塔文","暴风城"},ang={["faction:Alliance"]="作为追查暮色森林最臭名昭著的凶手的联盟调查者，你可以向Folsom求助，通过这位亲历者了解弗林特雷一家最后的日子。"},sec={{t="破败的家宅",b="弗索姆追随父亲的脚步，来到弗林特雷庄园效力。这家人惨遭屠戮，宅邸也被遗弃。剩下的钱财最终耗尽。弗索姆留下来看守残余的家业，如今将这个家族留下的传家宝和财物送去拍卖。"},{t="黑暗往事的牵连",b="追查斯塔文·密斯特曼托血腥往事的调查者，常被指引到暴风城的运河步道寻找弗索姆。他满怀悲痛，不愿多言。他保管着弗林特雷家族留下的财物和文件，揭示了斯塔文令人不安的堕落历程，以及他最终消失在暮色森林阴影中的经过。"}},faq={{q="管理员弗索姆是谁？",a="管理员弗索姆在暴风城照看弗林特雷庄园留下的财产。一场屠杀夺去了全家人的性命，此后便由他负责管理剩余的家产。",al={"弗索姆","弗索姆是谁","管理员弗索姆的故事"}},{q="在哪里可以找到管理员弗索姆？",a="你可以在暴风城运河沿岸的石砌步道上找到管理员弗索姆，就在花园区入口附近。",al={"管理员弗索姆在哪里","弗索姆位置","管理员弗索姆暴风城"}},{q="弗林特雷家族遭遇了什么？",a="多年前，弗林特雷家族在自家庄园惨遭屠戮。由于没有继承人前来接管，宅邸被封闭，钱财最终也耗尽了。",al={"弗林特雷谋杀案","弗林特雷遭遇了什么","谁杀了弗林特雷一家"}},{q="弗索姆为什么要变卖传家宝？",a="弗林特雷家族剩下的钱财最终耗尽了。弗索姆如今将庄园留下的财物送去拍卖。",al={"为什么拍卖","弗林特雷拍卖","弗索姆拍卖"}},{q="他在斯塔文的传说中扮演什么角色？",a="弗索姆向试图拼凑斯塔文·密斯特曼托悲剧始末的人提供帮助，拿出弗林特雷宅邸留下的私人物品和线索。",al={"斯塔文任务弗索姆","斯塔文的传说 弗索姆"}}},fx={["2b9b56eb"]={q="管理员弗索姆效忠哪一方？",a="管理员弗索姆是暴风城的忠诚子民，也是遭逢悲剧的弗林特雷家族尽心尽力的仆人。他没有恶意，也没有暗藏的政治效忠对象，每日在城中运河旁度日，只求缅怀他与父亲忠心侍奉过的家族，并料理好他们的身后事。",al={"管理员弗索姆阵营","管理员弗索姆为谁效力","管理员弗索姆的效忠对象"}},bbc99921={q="管理员弗索姆为什么会在这里？",a="你会在暴风城的运河旁见到管理员弗索姆，因为弗林特雷家族的资金已彻底耗尽。一家人惨遭杀害后，他不得不清算家产，留在首都监督清点和拍卖家族遗物的沉重事务。",al={"弗索姆为什么在暴风城","管理员弗索姆为什么在这里","弗索姆为何来到这里"}},["8f9af06f"]={q="管理员弗索姆与谁有关联？",a="血缘与职责将弗索姆同贵族弗林特雷家族的庄园紧紧相连。他的父亲曾担任管理员，后来由他接任，而弗索姆也将一生奉献给了这个家族的日常维护，直到斯塔文·密斯特曼托为全家带来毁灭与杀戮。",al={"弗索姆的人际关系","弗索姆与谁有关联","管理员弗索姆 弗林特雷"}}},fp="16,184,16.277.0,19.321.1,24.182.0,34.112.0,39.152.1,43.129.0,42.139.0"}
P.entries["npc:carolai-anise"] = {n="卡罗莱·安尼斯",s="在布瑞尔，卡罗莱·安尼斯传授炼金术，而她的实验却让卫兵们心神不宁。",h="在布瑞尔，卡罗莱·安尼斯传授炼金术，而她的实验却让卫兵们心神不宁。",kw={"炼金术","药剂师","布瑞尔","卡罗莱·安尼斯","被遗忘者训练师","提瑞斯法林地"},ang={["profession:Herbalism"]="作为提瑞斯法的采集者，你可以把peacebloom、silverleaf和earthroot带给卡罗莱，提炼成强效混合药剂。",["race:Undead"]="作为一名刚刚重获自由、正在学习使用试剂的被遗忘者，你可以在提瑞斯法林地向卡罗莱学习炼金术的基础知识。"},sec={{t="不稳定的技艺",b="卡罗莱·安尼斯在布瑞尔钻研炼金术，并教导初学的炼金师。许多被遗忘者研究人员都在执行皇家药剂师学会的严酷使命，但卡罗莱却在镇内调制着自己那些古怪的药剂。她那些难以预料的实验和冒烟的曲颈瓶早已远近闻名。守卫布瑞尔的亡灵卫兵毫不掩饰地抱怨，说她似乎铁了心要炸掉自己的房子。"}},faq={{q="卡罗莱·安尼斯是谁？",a="卡罗莱·安尼斯是提瑞斯法林地布瑞尔的一名亡灵炼金术训练师。她教导有志学习炼金术的被遗忘者调制药水、药剂和油。",al={"卡罗莱·安尼斯","布瑞尔炼金师","卡罗莱是谁"}},{q="在哪里能找到她？",a="卡罗莱在布瑞尔的一栋建筑内使用她的炼金用品进行工作，布瑞尔是提瑞斯法林地中部的主要被遗忘者城镇。",al={"卡罗莱·安尼斯在哪里","卡罗莱·安尼斯位置","布瑞尔炼金术训练师在哪里"}},{q="亡灵卫兵为什么抱怨她？",a="亡灵卫兵抱怨卡罗莱那些不稳定的实验可能引发事故。他们或是打趣，或是担忧，说她迟早会把整栋房子炸掉。",al={"亡灵卫兵对卡罗莱的看法","炸掉房子","卡罗莱·安尼斯的危险"}}},fp="13,79,16.336.0,21.138.0,21.121.0,42.153.0"}
P.entries["npc:cazul"] = {n="卡祖尔",s="在暗影裂口，卡祖尔指引年轻的术士更好地驾驭恶魔。他年迈失明，仍守护着兽人术士的古老传统。",h="在暗影裂口，卡祖尔指引年轻的术士更好地驾驭恶魔。他年迈失明，仍守护着兽人术士的古老传统。",kw={"失明的卡祖尔","卡祖尔","暗影裂口","恶魔学","奥格瑞玛","虚空行者","术士"},ang={["class:Warlock"]="身为部落术士，当你想要束缚来自虚空更深处的力量时，可以前往暗影裂口，寻求卡祖尔的指引。",["race:Orc"]="身为兽人，你可以从卡祖尔身上看到，黑暗魔法始终存在于你的族人之中。他避开萨尔荣誉卫兵的监视，研习自己的法术。"},sec={{t="黑暗中的双眼",b="卡祖尔在奥格瑞玛地下的暗影裂口等候，前来求教的术士都渴望精进技艺。尽管双目失明，他仍能感知扭曲虚空的涌动，听见恶魔的低语。那些想要精进技艺、束缚更危险仆从的术士，常被指引到他面前。他虽已失去视力，奥术力量却依然强大。"}},faq={{q="卡祖尔是谁？",a="卡祖尔是一位年迈失明的兽人术士，住在奥格瑞玛地下的暗影裂口。他为有志于研习术士之道的人传授黑暗巫术与恶魔学知识。",al={"卡祖尔是谁","卡祖尔背景故事","失明的卡祖尔非玩家角色"}},{q="卡祖尔为什么会失明？",a="没有记载说明卡祖尔为何失明。",al={"卡祖尔为何失明","卡祖尔如何失去视力"}},{q="卡祖尔对术士有何作用？",a="卡祖尔指引那些寻求精进技艺的术士，尤其是正在学习召唤和束缚魅魔的术士。",al={"卡祖尔任务","卡祖尔传授什么","术士任务卡祖尔"}}},fp="5,146,16.282.0,13.148.0,19.35.0,39.101.0"}
P.entries["npc:cerellean-whiteclaw"] = {n="塞瑞利恩·白爪",s="在黑海岸奥伯丁的码头与旅店附近，塞瑞利恩·白爪歇息于此，为逝去的爱人悲伤。大分裂的记忆萦绕着他，他竭力想让那个不得安宁的灵魂安息。",h="在黑海岸奥伯丁的码头与旅店附近，塞瑞利恩·白爪歇息于此，为逝去的爱人悲伤。大分裂的记忆萦绕着他，他竭力想让那个不得安宁的灵魂安息。",kw={"亚米萨兰","安娜雅·晨路","奥伯丁","塞瑞利恩·白爪","黑海岸","永志不渝","幽灵","大分裂"},ang={["class:Druid"]="身为德鲁伊，你也经历过塞瑞利恩追随玛法里奥·怒风进入的漫长沉睡。翡翠梦境未能洗去他尘世中的伤痛。",["race:NightElf"]="身为暗夜精灵，你知道塞瑞利恩的悲伤映照着War of the Ancients与大灾变在kaldorei心中留下的深刻而持久的创伤。"},sec={{t="被撕裂的爱",b="在上古之战之前，塞瑞利恩·白爪与安娜雅·晨路相伴生活。一万年前，恶魔入侵令古老的卡利姆多支离破碎，安娜雅也在她的城市亚米萨兰毁灭时丧生。悲痛欲绝的塞瑞利恩追随玛法里奥·怒风，进入了德鲁伊的漫长沉睡。翡翠梦境几乎未能缓解那些回忆带来的痛苦。数千年后醒来时，他满怀悲伤地游荡在黑海岸，发现安娜雅的幽灵仍被束缚在她殒命之处的石块之间。"},{t="祈求解脱",b="塞瑞利恩渴望让安娜雅安息，却不忍亲手击散她饱受折磨的幽魂。他请求过往的旅人南下，前往鬼魂出没的亚米萨兰废墟，让她的灵魂安息，并取回她的坠饰。获得解脱后，安娜雅的幽魂短暂地来到奥伯丁的码头探望塞瑞利恩。她向他诉说自己永恒不变的爱，并承诺他们终有一天会在来世重逢。"}},faq={{q="塞瑞利恩·白爪是谁？",a="塞瑞利恩·白爪在黑海岸奥伯丁的码头与旅店附近歇息。这位年迈的暗夜精灵哀悼着安娜雅·晨路，她在一万年前的上古之战中丧生。",al={"塞瑞利恩是谁","塞瑞利恩·白爪","奥伯丁码头精灵"}},{q="安娜雅·晨路是谁？",a="安娜雅·晨路曾在古城亚米萨兰与塞瑞利恩·白爪相伴生活。她在上古之战期间城市毁灭时丧生，饱受折磨的灵魂在废墟间徘徊了数千年。",al={"安娜雅·晨路","塞瑞利恩的爱情","塞瑞利恩的爱人"}},{q="塞瑞利恩为什么不亲自让安娜雅的灵魂安息？",a="塞瑞利恩悲痛欲绝，无法亲自面对并消灭安娜雅的幽灵。他请求心怀同情的旅人，让她的灵魂得到最终的解脱。",al={"塞瑞利恩为什么不与安娜雅战斗","为什么需要冒险者"}},{q="亚米萨兰废墟在哪里？",a="亚米萨兰废墟位于黑海岸南部，在大路以东。在大灾变中丧生的古代卡多雷的鬼魂游荡于此。",al={"亚米萨兰在哪里","安娜雅的位置","安娜雅在哪里"}}},fp="19,176,19.508.0,18.387.1,27.155.0,25.235.0,57.143.0,34.152.0"}
P.entries["npc:charlga-razorflank"] = {n="卡尔加·刺肋",s="在剃刀沼泽，卡尔加·刺肋领导着剃刀野猪人。他们将牛头人逐出了南贫瘠之地，声称自己是以陨落之神阿迦玛甘的名义而战。",h="在剃刀沼泽，卡尔加·刺肋领导着剃刀野猪人。他们将牛头人逐出了南贫瘠之地，声称自己是以陨落之神阿迦玛甘的名义而战。",kw={"阿迦玛甘","贫瘠之地","卡尔加","老妪","地卜师","沼泽","野猪人","剃刀之翼"},ang={["class:Shaman"]="卡尔加掌握着强大的地卜术，但她对元素的扭曲正在腐蚀神圣的原始传统。",["faction:Horde"]="击败卡尔加有助于保护南贫瘠之地各处的商队路线和营地，使其免受野猪人战团无休止的袭击。",["race:Tauren"]="卡尔加的扩张将你的族人逐出了南贫瘠之地各处的祖居之地。击败她意味着生存下去，夺回那些土地。"},sec={{t="沼泽的老妪",b="卡尔加·刺肋在剃刀沼泽盘根错节的荆棘丛中统治着她的族人。族人尊她为地卜大师，没有哪个野猪人能在试验性魔法上与她匹敌。她将纷争不断的同族团结起来，组成了一支致命的力量。卡尔加利用原始大地之力，以及从半神阿迦玛甘遗骸中生出的巨大荆棘，将沼泽改造成了一座难以攻入的堡垒。"},{t="扩张与背叛",b="卡尔加·刺肋派出战士，进攻南贫瘠之地各处的敌对部族和部落村落。他们的袭击将牛头人逐出了世代居住的家园。卡尔加还与亡灵天灾军团的使者秘密交易，用毫不知情的族人对她的忠诚，换取违背自然的力量和黑暗盟约。"}},faq={{q="卡尔加·刺肋是谁？",a="卡尔加·刺肋领导着剃刀野猪人，在南贫瘠之地剃刀沼泽深处的巢穴中统治着他们。",al={"卡尔加背景故事","沼泽的老妪是谁","剃刀首领"}},{q="卡尔加使用什么魔法？",a="卡尔加·刺肋是一位天赋出众的地卜师，能够驾驭大地元素，以及源自半神阿迦玛甘的巨大血色荆棘。",al={"卡尔加技能","地卜师能力"}},{q="野猪人为何攻击贫瘠之地的牛头人？",a="卡尔加·刺肋率领剃刀野猪人进攻敌对部族和部落村落，将牛头人逐出了南贫瘠之地。",al={"野猪人为何仇恨牛头人","贫瘠之地战争野猪人"}},{q="卡尔加与剃刀高地有什么联系？",a="剃刀高地与卡尔加的沼泽都由同一片巨大的藤蔓生长而成。那里是野猪人传统的都城，也是亡首部族及其高阶祭司的家园。卡尔加统治的是剃刀沼泽，而非剃刀高地。",al={"卡尔加 剃刀高地","卡尔加剃刀高地"}},{q="部落为何想要她的命？",a="卡尔加不断发动袭击，侵占牛头人的土地，还与黑暗势力进行危险的交易，因此牛头人及其部落盟友将她视为迫在眉睫的威胁。",al={"沼泽的老妪任务","为何杀死卡尔加"}}},fx={["29fd1a6b"]={q="卡尔加·刺肋效忠于哪一方？",a="卡尔加领导着剃刀沼泽的野猪人，但她与天灾军团交易，出卖了自己的族人。她声称要拥护野猪人，并让他们的野猪之神阿迦玛甘复生，却暗中与寒冰使者阿门纳尔派来的亡灵使节结盟，为其追随者所不知的险恶势力效力。",al={"卡尔加·刺肋的阵营","卡尔加效忠于谁","卡尔加·刺肋的立场"}},["98b63c0f"]={q="卡尔加·刺肋想要什么？",a="卡尔加企图绝对统治南贫瘠之地，并为自己的部族夺取至高权力。她驱使族人血洗敌对部族、部落村庄和牛头人；她还一直暗中与天灾军团的代理人谈判，在族人毫不知情的情况下让他们与亡灵结盟，意图不明。",al={"卡尔加的目标","卡尔加想要什么","卡尔加·刺肋的动机"}},["581cf8d6"]={q="卡尔加·刺肋为何在此？",a="剃刀沼泽是剃刀野猪人的祖地核心，那里由远古之战中阿迦玛甘陨落之处生长出的巨大荆棘构成。身为部族中至高无上的老巫婆和酋长，卡尔加在沼泽最深处筑巢，在那里调度她的战队并研究地脉水晶。",al={"卡尔加为何在剃刀沼泽","卡尔加·刺肋所在此处的原因","卡尔加在哪里"}},["98250d5e"]={q="卡尔加·刺肋与谁有关联？",a="卡尔加与盘踞在剃刀高地的天灾军团势力直接勾结。她与寒冰使者阿门纳尔的使者谈判；这位巫妖暗中控制着亡首野猪人。卡尔加让自己的部族在不知情的情况下加入了亡灵的阵营。",al={"卡尔加的盟友","卡尔加的关系","卡尔加与谁共事"}},f526ba0c={q="卡尔加·刺肋为何声名狼藉或令人畏惧？",a="卡尔加被称为沼泽老巫婆，拥有同族无人能及的地脉秘术，令人闻风丧胆。在她铁腕领导下，剃刀野猪人发动了残酷的征战，将游牧的牛头人彻底赶出了南贫瘠之地，使她在整个卡利姆多凶名远扬。",al={"卡尔加为何令人畏惧","卡尔加有多强","卡尔加·刺肋的力量"}}},fp="18,166,22.372.0,22.328.1,26.112.0,28.127.0,54.131.0,47.209.0,33.182.0"}
P.entries["npc:chef-breanna"] = {n="厨师布雷纳",s="在湖畔镇，厨师布雷纳为守卫赤脊山的暴风城士兵供应饭食。她掌管镇上的厨房，用当地食材做出丰盛的饭菜，让守军保持体力。",h="在湖畔镇，厨师布雷纳为守卫赤脊山的暴风城士兵供应饭食。她掌管镇上的厨房，用当地食材做出丰盛的饭菜，让守军保持体力。",kw={"布雷纳","厨师布雷纳","厨师","驻军","炖肉","湖畔镇","赤脊山炖肉"},ang={["faction:Alliance"]="厨师布雷纳为坚守湖畔镇桥梁和城镇外围的士兵供应饭食。没有她做的饭菜，面对兽人和豺狼人接连不断的侵袭，本就疲于应付的驻军可能很快就会筋疲力尽。",["profession:Cooking"]="布雷纳的赤脊山炖肉以周围荒野中的蜘蛛、秃鹫和goretusks为食材，为军事哨站提供丰盛的饭食。"},sec={{t="为湖畔镇守军供餐",b="厨师布雷纳与助手克里斯托·鲍曼和格雷彻·沃格尔一起，在湖畔镇西北部的一间餐馆里工作。她负责整个当地营队的伙食。黑石兽人、豺狼人和鱼人围攻着小镇，暴风城兵力不足的驻军必须保持战斗力。她的招牌菜赤脊山炖肉以周围山岭中的野味和野兽为食材，为疲惫的卫兵填饱肚子。"}},faq={{q="厨师布雷纳是谁？",a="厨师布雷纳掌管着湖畔镇西北角的厨房。她为保卫赤脊山的暴风城士兵供应饭食。",al={"厨师布雷纳","布雷纳 湖畔镇","布雷纳是谁"}},{q="厨师布雷纳需要什么帮助？",a="厨师布雷纳需要当地的野味肉，为驻军烹制赤脊山炖肉。你可以在湖畔镇周围的荒野中收集硬秃鹫肉、猪头肉和香脆蜘蛛肉。",al={"布雷纳任务","赤脊山 炖肉食材","她需要什么"}},{q="谁与厨师布雷纳一起工作？",a="克里斯托·鲍曼和格雷彻·沃格尔在厨师布雷纳的餐馆里与她一起工作。她们协助经营餐馆，为饥饿的镇民和士兵提供餐食。",al={"布雷纳的助手","克里斯托·鲍曼","格雷彻·沃格尔"}}},fx={["33f751f4"]={q="厨师布雷纳效忠于哪一方？",a="厨师布雷纳效忠于联盟和暴风城王国。她在湖畔镇经营厨房，负责为驻扎在当地、守卫城镇及周边边境的暴风城军团提供补给。",al={"厨师布雷纳的阵营","布雷纳效忠于谁","厨师布雷纳属于联盟吗"}},f2dfd1fc={q="厨师布雷纳为什么在湖畔镇？",a="布雷纳在湖畔镇西北部经营镇上的餐馆。她的主要职责是在威胁不断逼近赤脊山之际，为当地的暴风城士兵提供食物，确保他们随时能够投入战斗；她依靠新鲜的本地食材，为驻军补充给养。",al={"布雷纳为什么在赤脊山","厨师布雷纳为什么在湖畔镇","布雷纳在湖畔镇的职责"}}},fp="12,189,29.413.0,20.129.0,38.171.0,28.146.0"}
P.entries["npc:chef-grual"] = {n="厨师格鲁奥",s="在夜色镇，厨师格鲁奥维持着血鸦旅店厨房的运转。他为守夜人和疲惫的旅人准备饭菜，不过有些食材令人起疑。",h="在夜色镇，厨师格鲁奥维持着血鸦旅店厨房的运转。他为守夜人和疲惫的旅人准备饭菜，不过有些食材令人起疑。",kw={"厨师格鲁奥","蟹肉蛋糕","夜色镇","暮色森林","格鲁奥","基特斯","血鸦旅店","狼肉串"},ang={["faction:Alliance"]="在夜色镇的血鸦旅店，尽管从暴风城定期前来的补给商队寥寥无几，格鲁奥仍让联盟守卫有饭可吃。",["profession:Cooking"]="格鲁奥让人看到，身处偏远地区的厨师如何利用当地的野生动物，无论它们在林间行走，还是窸窸窣窣地爬行。",["race:Human"]="和许多仍留在夜色镇的居民一样，格鲁奥凭着坚忍顽强的韧性和实用的手艺，熬过幽暗森林中的恐怖。"},sec={{t="围困中的炊烟",b="夜色镇的厨师只能靠有限的物资做饭。强盗、狼和亡灵不断侵扰从西部荒野和暴风城通来的道路，让新鲜食材难以运抵。格鲁奥只好利用荒野里能找到的食材。他烹制狼肋肉和当地冒险者搜集来的肉，送进厨房的食材都能派上用场。"},{t="秘藏的食材",b="厨师格鲁奥以黑蟹蛋糕和调味狼肉串闻名。暮色森林远离海岸，所以他的蟹肉蛋糕里用的是当地结网毒蜘蛛黏糊糊的蛛腿。不管食客知道自己吃的是什么，还是宁愿不问，格鲁奥都照常掌勺，毫无歉意。"}},faq={{q="厨师格鲁奥是谁？",a="厨师格鲁奥在夜色镇的血鸦旅店掌勺。他为镇上的守卫、旅人，以及躲避暮色森林危险的难民准备饭菜。",al={"厨师格鲁奥","格鲁奥 夜色镇","夜色镇厨师"}},{q="在哪里能找到厨师格鲁奥？",a="厨师格鲁奥在夜色镇中心的血鸦旅店后屋和厨房里工作，酒馆就在主干道南侧。",al={"格鲁奥 位置","厨师格鲁奥在哪里","寻找厨师格鲁奥"}},{q="黑蟹蛋糕究竟是用什么做的？",a="黑蟹蛋糕里用的是盘踞在周围森林中的结网毒蜘蛛黏糊糊的蛛腿。格鲁奥把蛛腿剁碎，做成仿海鲜的肉饼。",al={"蟹肉蛋糕食材","蜘蛛蟹肉蛋糕","黑蟹蛋糕里有什么"}},{q="厨师格鲁奥提供哪些任务？",a="厨师格鲁奥请旅人收集狼肋肉来做调味狼肉串，再收集蛛腿来做黑蟹蛋糕。他还为基特斯制作黑蟹蛋糕，那是个躲在暮色森林里、饥肠辘辘的男人。",al={"格鲁奥 任务","厨师格鲁奥食谱"}},{q="他为什么给基特斯做饭？",a="基特斯在暮色森林的一座荒废小镇里躲了好几个星期，靠蛆虫和野草度日。他饿得只想吃顿像样的饭，便让旅人去找格鲁奥要些黑蟹蛋糕。",al={"基特斯食物","基特斯 饥肠辘辘 格鲁奥"}},{q="格鲁奥隶属于守夜人吗？",a="厨师格鲁奥是个平民厨师，并非卫兵。守夜人和当地民兵不断抵御围攻，他的厨房为他们供应饭菜。",al={"格鲁奥 守夜人","格鲁奥 参战吗"}}},fx={ccc14f35={q="厨师格鲁奥属于哪一方？",a="厨师格鲁奥坚定地站在夜色镇居民和联盟一边。尽管小镇依然与外界隔绝，饱受阴影侵袭，格鲁奥仍在血鸦旅店守着炉火，为当地居民、疲惫的旅人和小镇守卫准备饭菜。",al={"厨师格鲁奥的阵营","厨师格鲁奥为谁效力","厨师格鲁奥属于联盟吗"}},["3ac222da"]={q="厨师格鲁奥想要什么？",a="格鲁奥想在暮色森林危机四伏的局势下，确保血鸦旅店的物资充足。贸易路线已被切断，新鲜牲畜也十分稀缺，他只能依靠勇于冒险的旅人收集不寻常的本地食材——比如狼肉和黏糊糊的蜘蛛腿——来供给饥肠辘辘的顾客。",al={"厨师格鲁奥需要什么","厨师格鲁奥的食材","厨师格鲁奥的目标"}},["91c4d31a"]={q="厨师格鲁奥为什么在这里？",a="格鲁奥是夜色镇的常驻厨师，在血鸦旅店工作。暮色森林中许多人都已逃离逐渐逼近的黑暗，格鲁奥却留下来经营厨房，尽自己的一份力，帮助这座与世隔绝的聚居地生存下去。",al={"厨师格鲁奥为什么在暮色森林","格鲁奥为什么留在夜色镇","厨师格鲁奥的职责"}}},fp="10,160,19.305.0,18.290.1,18.158.0,28.137.0,43.148.1,34.197.1,25.157.0,41.128.0"}
P.entries["npc:chef-jessen"] = {n="厨师杰森",s="在南海镇，厨师杰森在边境持续紧张的局势下，为镇民供应食物。他最出名的拿手菜是海龟浓汤。",h="在南海镇，厨师杰森在边境持续紧张的局势下，为镇民供应食物。他最出名的拿手菜是海龟浓汤。",kw={"厨师杰森","烹饪","希尔斯布莱德丘陵","杰森","洛丹米尔湖","钳嘴龟","南海镇","海龟浓汤"},ang={["faction:Alliance"]="在南海镇，杰森为坚守防线、抵御北方威胁的联盟士兵和冒险者供应食物。",["profession:Cooking"]="作为途经希尔斯布莱德的厨师，你可以向杰森请教海龟浓汤的食谱，为坚韧的旅人烹制这道丰盛的菜肴。"},sec={{t="南海镇的厨师",b="厨师杰森在希尔斯布莱德丘陵南部的南海镇，为当地居民和到访的联盟士兵供应肉类与补给。他厨艺精湛。在瘟疫和战争扰乱洛丹伦北部之前，他常常向北穿过达拉然，前往洛丹米尔湖畔。他在那里采集当地的钳嘴海龟肉，用来烹制他引以为傲、浓郁丰盛的海龟汤。他愿意与帮助他收集食材的旅人分享这道菜的食谱。"}},faq={{q="厨师杰森是谁？",a="厨师杰森是希尔斯布莱德丘陵南海镇的一名人类屠夫兼厨师。他出售肉类，也与支持联盟的旅人分享当地食谱。",al={"杰森","南海镇厨师杰森","杰森是谁"}},{q="厨师杰森的拿手菜是什么？",a="厨师杰森的招牌菜是海龟汤。过去，他会向北穿过达拉然，在洛丹米尔湖周围采集新鲜的钳嘴海龟肉，用来熬制这道浓郁的汤。",al={"海龟浓汤食谱","杰森拿手菜","海龟汤"}},{q="厨师杰森为什么向旅人求助？",a="由于当地局势动荡，附近又有被遗忘者出没，在洛丹米尔湖周围采集钳嘴海龟肉变得危险起来。厨师杰森依靠身手不凡的旅人为他的浓汤收集肉料。",al={"杰森任务","海龟肉任务"}},{q="厨师杰森出售什么特别的东西吗？",a="厨师杰森向南海镇的居民出售肉类。他的拿手菜是海龟汤，他会将食谱传授给帮助收集钳嘴龟肉的厨师。",al={"杰森拿手菜","杰森食物商人"}}},fx={["4b3f98b6"]={q="厨师杰森属于哪一方？",a="厨师杰森效忠于联盟。他在南海镇生活和工作。南海镇是希尔斯布莱德丘陵南岸主要的人类避难所和联盟据点，为当地居民以及奋力守住洛丹伦防线的旅人提供膳食。",al={"厨师杰森属于联盟还是部落","厨师杰森属于联盟吗","厨师杰森的阵营"}},["73d1d0ab"]={q="厨师杰森为什么在南海镇？",a="厨师杰森在南海镇经营肉类摊位，也担任厨师。他以前会一路北上，经过达拉然前往洛丹米尔湖，亲自猎捕钳嘴龟；如今他待在镇上，依靠路过的冒险者带来新鲜食材。",al={"厨师杰森为什么在南海镇","厨师杰森为什么在这里","是什么让厨师杰森来到希尔斯布莱德"}}},fp="11,106,20.464.0,19.162.0,34.167.0,44.203.0,39.135.0"}
P.entries["npc:chief-archaeologist-greywhisker"] = {n="首席考古学家杜瑟·灰须",s="在达纳苏斯，首席考古学家杜瑟·灰须收集着来自海岸的报告。这位铁炉堡矮人在月神殿外协调探险者协会的研究，并关注黑海岸同僚们的动向。",h="在达纳苏斯，首席考古学家杜瑟·灰须收集着来自海岸的报告。这位铁炉堡矮人在月神殿外协调探险者协会的研究，并关注黑海岸同僚们的动向。",kw={"阿迦玛甘","首席考古学家","黑海岸","达纳苏斯","探险者协会","灰须","铁炉堡","塔雷尔维尔","月神殿"},ang={["faction:Alliance"]="作为联盟的一员，灰须将铁炉堡的探险者协会与遍布卡利姆多北部的探险队联系起来。",["race:Dwarf"]="身为矮人，在月神殿外见到铁炉堡最杰出的学者之一，让你想起族人在卡利姆多各地探寻古代历史的热忱。",["race:NightElf"]="身为暗夜精灵，灰须将东部王国的新同盟带到了你的城市。他在Elune的神殿外与学者们交谈，探讨这片大陆的过去。"},sec={{t="达纳苏斯的矮人学者",b="首席考古学家杜瑟·灰须在达纳苏斯的月神殿外工作，远离铁炉堡的家乡。他代表探险者协会，该组织派他远渡重洋，来到卡利姆多开展实地研究。在那里，他与塔雷尔维尔等暗夜精灵学者交谈，探求这片古老土地的知识。在铁炉堡时，他讲授过古代传说和原始生灵，其中就包括荒野之神阿迦玛甘。如今，他希望了解暗夜精灵的祖地蕴藏着什么。"},{t="关注黑海岸",b="在卡利姆多，灰须监督矮人的挖掘工作，并关注探索沿海古代遗迹的探险队。他依靠旅行者向远在海对岸黑海岸的勘察员传递消息。在未经探索的土地上开展实地研究危机四伏，他焦急地等待着挖掘场的报告，希望同僚们在废墟中平安无事。"}},faq={{q="首席考古学家杜瑟·灰须是谁？",a="首席考古学家杜瑟·灰须是一位来自铁炉堡的矮人学者，也是探险者协会的代表。他在达纳苏斯的月神殿外协调该组织在卡利姆多北部的研究，并与暗夜精灵学者交流。",al={"灰须是谁","灰须的故事","首席考古学家"}},{q="一位铁炉堡矮人在达纳苏斯做什么？",a="探险者协会派遣灰须远渡重洋，探寻被遗忘的历史和古代文物。他在暗夜精灵的首都结交学者，并监督沿卡利姆多古老海岸开展探索的矮人探险队。",al={"矮人为何在达纳苏斯","矮人 月神殿"}},{q="他与阿迦玛甘有什么联系？",a="在铁炉堡，灰须曾讲授古代历史，其中就包括巨大的野猪荒野之神阿迦玛甘。他的教导激励了独眉等年轻勘察员，促使他们研究有关远古野兽的民间传说。",al={"灰须 阿迦玛甘","阿迦玛甘讲座"}},{q="灰须在神殿外与谁交谈？",a="在达纳苏斯的月神殿外，灰须与暗夜精灵学者塔雷尔维尔交谈。他们交换见解，协调两个种族之间的历史研究。",al={"灰须 塔雷尔维尔","谁和灰须在一起"}},{q="他在黑海岸遇到了什么麻烦？",a="灰须的矮人研究同僚正在黑海岸挖掘古代遗迹，但那些偏远的探险队很难联系上。他寻找信使，前去查看那些心不在焉的勘察员的情况，并取回他们的研究日志。",al={"灰须 黑海岸","黑海岸勘察员"}},{q="灰须属于哪个阵营？",a="灰须属于探险者协会，这是铁炉堡的一个考古组织，致力于探寻矮人的起源和古代历史。该组织隶属于联盟。",al={"灰须的阵营","探险者协会 达纳苏斯"}}},fp="31,217,30.450.0,17.348.0,39.253.0,46.224.0,36.195.0,49.177.0,45.220.0,41.187.0"}
P.entries["npc:chief-engineer-hinderweir-vii"] = {n="主工程师辛德维尔七世",s="主工程师辛德维尔七世在巨石水坝顶上，监督水坝的运转与防御。在严重的危险威胁着水坝之际，这位经验丰富的矮人确保这座宏伟建筑及其机械完好无损。",h="主工程师辛德维尔七世在巨石水坝顶上，监督水坝的运转与防御。在严重的危险威胁着水坝之际，这位经验丰富的矮人确保这座宏伟建筑及其机械完好无损。",kw={"水坝危机","矮人","工程师","辛德维尔七世","洛克莫丹","蓄意破坏","巨石水坝"},ang={["faction:Alliance"]="身为联盟的一员，你绝不能让水坝垮塌。水坝被毁将切断补给路线，并重创洛克莫丹以北的盟友领地。",["profession:Engineering"]="身为工程师，你能领略水坝庞大机械设备的精妙之处，这里将土木建筑与机械控制融为一体。",["race:Dwarf"]="身为矮人，你能看出辛德维尔肩负的庄严职责：保护卡兹莫丹最伟大的石造工程，使其免遭外来恶意的侵害。"},sec={{t="水坝的主事者",b="主工程师辛德维尔七世负责维护巨石水坝，这座石坝拦住了洛克莫丹的湖水。他沿着坝顶巡视水道和闸门。他还检查风雨侵蚀和当地的隐患是否给水坝带来了负担。水坝的运转需要持续照料。"},{t="破坏与阴谋",b="主工程师辛德维尔七世在水坝发现了蓄意破坏的迹象。一旦决堤，洪水就可能淹没低地，摧毁卡兹莫丹脆弱的基础设施。因此，他召集可靠的联盟冒险者追查阴谋，拆除暗藏的炸药，在坝体崩塌前消除威胁。"}},faq={{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世负责维护和守卫洛克莫丹北部的巨石水坝。",al={"辛德维尔七世","主工程师","水坝工程师"}},{q="在哪里可以找到主工程师辛德维尔七世？",a="你可以在巨石水坝顶部的步道上找到主工程师辛德维尔七世。水坝横跨洛克莫丹北缘，靠近湿地边界。",al={"辛德维尔位置","辛德维尔在哪里","寻找辛德维尔"}},{q="巨石水坝是什么？",a="巨石水坝是一座宏伟的矮人建筑，拦住了洛克莫丹的湖水。它阻止湖水猛烈倾泻到北面地势较低的湿地。",al={"水坝是什么","巨石水坝用途","水坝为何重要"}},{q="辛德维尔担忧哪些威胁？",a="主工程师辛德维尔七世正在调查针对水坝的破坏活动。他发现了邪恶阴谋的迹象，以及为炸裂水坝地基而埋设的爆炸装置。",al={"水坝面临的威胁","水坝危机","谁想摧毁水坝"}},{q="为什么他的名字里有“七世”？",a="七世中的七是用罗马数字表示的。没有任何记录解释它为何出现在辛德维尔的名字中。",al={"辛德维尔的名字","为何是七世","辛德维尔七世的含义"}},{q="主工程师辛德维尔提供哪些任务？",a="主工程师辛德维尔七世提供名为“水坝危机”的系列任务。冒险者将奉命调查破坏行为，保护巨石水坝免遭摧毁。",al={"辛德维尔的任务","水坝的任务","水坝危机任务"}}},fx={["35f113ec"]={q="主工程师辛德维尔七世效忠哪一方？",a="主工程师辛德维尔七世是一位自豪的矮人，效忠于铁炉堡和联盟。他驻守在洛克莫丹的巨石水坝，首要职责便是保护这座矮人王国最伟大的工程奇迹之一，使其免受任何外来威胁。",al={"辛德维尔的阵营","辛德维尔是联盟成员吗","辛德维尔为谁效力"}},["3db73bdf"]={q="主工程师辛德维尔七世想要什么？",a="辛德维尔希望确保巨石水坝完好无损、防守严密。他怀疑有人图谋不轨，即将破坏这座庞大的建筑，因此寻找可靠的冒险者调查附近的可疑活动，在灾难降临洛克莫丹之前消除一切暗中的威胁。",al={"辛德维尔的目标","主工程师辛德维尔想要什么","辛德维尔的动机"}},["53bdb0ce"]={q="主工程师辛德维尔七世为什么会在这里？",a="作为负责巨石水坝的主工程师，辛德维尔直接驻守在这座庞大的建筑上，监督其日常运作和安全。他始终在现场保持警惕，处理结构隐患，并应对威胁湖泊的迫近危险。",al={"辛德维尔为什么在水坝","主工程师辛德维尔为什么在这里","辛德维尔在洛克莫丹的目的"}}},fp="29,202,17.275.0,23.300.1,37.92.0,47.150.0,29.162.0,41.152.0,32.91.0,49.173.0"}
P.entries["npc:chief-hawkwind"] = {n="鹰风酋长",s="在纳拉其营地，鹰风酋长为年轻的舒哈鲁走向更广阔的世界做准备。他在莫高雷的红云台地指导他们完成传统的成年仪式，教导他们保持谦逊、尊重土地，并拥有保护族人的力量。",h="在纳拉其营地，鹰风酋长为年轻的舒哈鲁走向更广阔的世界做准备。他在莫高雷的红云台地指导他们完成传统的成年仪式，教导他们保持谦逊、尊重土地，并拥有保护族人的力量。",kw={"一件琐事","刺背","纳拉其营地","鹰风酋长","莫高雷","红云台地","力量仪祭","大地之母仪祭","牛头人酋长"},ang={["faction:Horde"]="身为部落的一员，你将与新近成长起来的牛头人勇士并肩作战，他们在鹰风的教导下，成为出色的战士和施法者，以及坚定而光荣的盟友。",["race:Tauren"]="身为牛头人，你会从鹰风酋长那里学到Shu'halo最初的信条：敬畏Earthmother，忠于部族，拥有力量而仍保持谦逊。"},sec={{t="台地的酋长",b="鹰风酋长在纳拉其营地教导年轻的牛头人，为他们离开红云台地后的生活做准备。在台地上，初出茅庐的猎人、萨满祭司、德鲁伊和战士接受古老的大地之母仪祭。鹰风主持这些传统仪式，让每个年轻人在离开安全的台地之前，学会担当与坚忍。"},{t="指引试炼",b="鹰风酋长的教导始于谦逊，而非武功荣耀。他派新入门的年轻人去取清澈的泉水，做些简单的杂务，教导他们敬重自然与长辈。展现出谦逊之后，勇士们便要接受武艺的考验。面对侵入祖传平原、充满敌意的刺背野猪人，他们将在试炼中证明自己的决心。"},{t="保卫纳拉其营地",b="鹰风酋长也必须应对逼近纳拉其营地的危险。刺背氏族愈发大胆，不断进逼红云台地的边界。鹰风统筹营地的防御，派出刚刚通过考验的勇士，挫败野猪人的进攻，守护这片神圣的试炼之地。"}},faq={{q="鹰风酋长是谁？",a="鹰风酋长领导着红云台地上的纳拉其营地。他在那里主持部族事务，教导年轻的牛头人，为他们走向莫高雷和卡利姆多更广阔的天地做准备。",al={"鹰风","鹰风酋长的故事","纳拉其营地的酋长是谁"}},{q="大地之母仪祭是什么？",a="大地之母仪祭是年轻牛头人成年时接受的神圣试炼。鹰风酋长这样的长者会指导这些仪式，考验他们的谦逊、力量、勇气，以及与土地和先祖之间的精神联系。",al={"牛头人仪式","大地之母仪祭","这些仪式是什么"}},{q="鹰风酋长为什么先让你取水？",a="鹰风酋长交给你取水的任务，是要教导你，为族人服务、尊重族人与武力同样重要。在新入门的年轻人面对战斗之前，为部族长者取来清水能让他们学会耐心与谦逊。",al={"一件琐事","为什么要取水","鹰风取水任务"}},{q="纳拉其营地正面临什么威胁？",a="来自红云台地周围山丘的敌对刺背野猪人，持续威胁着纳拉其营地。鹰风酋长组织台地的防御，并派新入门的年轻人削减敌人的兵力。",al={"纳拉其的威胁","谁在进攻纳拉其营地","野猪人 纳拉其营地"}},{q="鹰风酋长接下来会派冒险者去哪里？",a="年轻的勇士完成台地上的初步仪式后，鹰风酋长便会派他们下山，前往莫高雷的山谷。他们会去血蹄村寻找凯恩的儿子贝恩·血蹄酋长，继续接受大地之母仪祭。",al={"完成鹰风的任务后去哪里","纳拉其营地之后","离开红云台地"}},{q="鹰风酋长与鹰风酋长的母亲有亲属关系吗？",a="有。鹰风酋长的母亲就是鹰风酋长的生母。他们的家族在红云台地的牛头人中根基深厚，世代担任领袖。",al={"鹰风酋长的母亲的亲属关系","鹰风家族","鹰风酋长的母亲是谁"}}},fp="14,217,21.298.0,17.351.0,22.254.0,22.164.0,38.223.0,51.222.0,35.181.0,48.236.0,50.150.0"}
P.entries["npc:christoph-jeffcoat"] = {n="克里斯托弗·杰弗寇特",s="在塔伦米尔，克里斯托弗·杰弗寇特为被遗忘者供应贸易和旅行所需的货物。他的商品为希尔斯布莱德丘陵的工匠和旅人提供便利，联盟与辛迪加正在这片土地上争夺控制权。",h="在塔伦米尔，克里斯托弗·杰弗寇特为被遗忘者供应贸易和旅行所需的货物。他的商品为希尔斯布莱德丘陵的工匠和旅人提供便利，联盟与辛迪加正在这片土地上争夺控制权。",kw={"克里斯托弗·杰弗寇特","被遗忘者商人","希尔斯布莱德","舒心草","塔伦米尔","商栈货物","商栈商人"},ang={["faction:Horde"]="作为在希尔斯布莱德丘陵征战的部落勇士，你可以在塔伦米尔的克里斯托弗·杰弗寇特商店里找到制作材料和常用工具。",["profession:Cooking"]="作为希尔斯布莱德的厨师，你可以向克里斯托弗·杰弗寇特购买舒心草。给他带去snapjaw肉，他就会教你制作他的海龟汤。"},sec={{t="前线商人",b="克里斯托弗·杰弗寇特照料着塔伦米尔的日常所需，这里是被遗忘者在希尔斯布莱德丘陵的据点。他向士兵和途经此地的工匠出售施法材料、工具、线和香料。他的商品包括制作海龟浓汤所用的香料、稀有结构图和炼金术用的瓶子。途经洛丹伦南部的部落军队依靠这些补给，应对南海镇和这一带的种种危险。"}},faq={{q="在哪里可以找到克里斯托弗·杰弗寇特？",a="克里斯托弗·杰弗寇特位于塔伦米尔，这里是被遗忘者和部落在希尔斯布莱德丘陵北部的主要据点。",al={"克里斯托弗·杰弗寇特位置","杰弗寇特在哪里","塔伦米尔商栈商人"}},{q="他出售哪些货物？",a="他出售裁缝用的线、铁匠之锤、助熔剂、炼金术用的瓶子和烹饪香料，包括舒心草和辣椒。他也出售一些精选配方。",al={"杰弗寇特出售什么","克里斯托弗·杰弗寇特商品","杰弗寇特物品"}},{q="他为何对当地厨师很重要？",a="杰弗寇特出售制作海龟汤所需的舒心草，还会将配方传授给那些从钳嘴龟身上取得海龟肉并带来给他的部落厨师。",al={"希尔斯布莱德舒心草商人","海龟汤材料","杰弗寇特烹饪"}}},fx={["36cd3db3"]={q="克里斯托弗·杰弗寇特是谁？",a="克里斯托弗·杰弗寇特是一名亡灵商人，驻扎在希尔布莱德丘陵的塔伦米尔。他为被遗忘者效力，为旅人、工匠以及坚守部落前线的守卫提供贸易物资、原材料和制造用品。",al={"克里斯托弗·杰弗寇特是谁","克里斯托弗·杰弗寇特的身份","杰弗寇特是谁"}},["1470d19f"]={q="克里斯托弗·杰弗寇特属于哪一方？",a="克里斯托弗·杰弗寇特坚定地效忠于被遗忘者和部落。他驻扎在争夺激烈的前哨塔伦米尔，为部落冒险者和勇士提供服务；他们正与来自南海镇的联盟势力交战。",al={"克里斯托弗·杰弗寇特的阵营","克里斯托弗·杰弗寇特属于部落吗","克里斯托弗·杰弗寇特为谁效力"}},["7ff6f152"]={q="克里斯托弗·杰弗寇特为什么在塔伦米尔？",a="塔伦米尔是部落在希尔斯布莱德丘陵北部行动的支点，工匠和战士经常缺少日常物资。克里斯托弗·杰弗寇特驻扎在此，确保贸易货物、药瓶、线和香料能随时供给守卫据点的人。",al={"克里斯托弗为什么在塔伦米尔","克里斯托弗·杰弗寇特为什么在这里","杰弗寇特为什么在希尔斯布莱德"}}},fp="18,207,29.374.0,36.119.0,33.167.0,36.140.0"}
P.entries["npc:chronormu"] = {n="克罗诺姆",s="克罗诺姆使用凡人名字克罗米，是一条化身为活泼女侏儒的青铜龙。她肩负着守护艾泽拉斯时间流的职责，常常直接与凡人共事，而非在远处观察。在西瘟疫之地，她悄然介入第三次大战留下的悲剧余波，修复紊乱的时间线。",h="克罗诺姆使用凡人名字克罗米，是一条化身为活泼女侏儒的青铜龙。她肩负着守护艾泽拉斯时间流的职责，常常直接与凡人共事，而非在远处观察。在西瘟疫之地，她悄然介入第三次大战留下的悲剧余波，修复紊乱的时间线。",kw={"安多哈尔","青铜龙","克罗米","克罗诺姆","诺兹多姆","化身"},ang={["class:Mage"]="研究时间魔法这一奥数学科的法师，会发现克罗诺姆随手操纵时间、制造局部时间区域的本领既引人入胜，其规模又令人震撼。",["race:Gnome"]="克罗诺姆以克罗米的身份行走于凡人之间，这位开朗侏儒娇小而不起眼的外形下，隐藏着一条青铜龙。"},sec={{t="小小化身中的巨龙",b="在凡人眼中，克罗诺姆是一位名叫克罗米、古怪而开朗的侏儒，实际上她是 青铜龙军团 的一员，效命于 时光之王 诺兹多姆。青铜龙受泰坦之命，守护历史，纠正时间流中的紊乱。她以女侏儒的形态行走在凡人身旁，如同一位平易近人、乐观的伙伴。"},{t="瘟疫之地的守望者",b="克罗诺姆栖身于残破的洛丹伦废墟，尤其关注满目疮痍的西瘟疫之地。王国灾难性的覆灭和 天灾军团 的蔓延，深深撕裂了这片地区的历史，留下了时间异常和受困的残存之物。她在安多哈尔废墟等地暗中行动，招募凡人冒险者修复纠缠的时间线，调查异动，除非必要，否则不会展露龙族那令人敬畏的全部威仪。"}},faq={{q="克罗米真的是侏儒吗？",a="不是。克罗米只是青铜龙克罗诺姆的凡人化身。青铜龙采用凡人的外貌，在年轻种族之间行走，以免引起过度的恐惧或猜疑。",al={"克罗米 是侏儒吗","克罗米 真身","克罗米 是谁"}},{q="克罗米为什么有两个名字？",a="克罗诺姆就是她身为青铜龙的真名。克罗米则是她以侏儒形态与凡人相处时使用的简称。",al={"克罗诺姆 名字与性别","克罗米 为什么叫 克罗诺姆","克罗诺姆 性别"}},{q="克罗米在西瘟疫之地做什么？",a="天灾军团 在洛丹伦造成的浩劫，严重扰乱了历史与时间流。克罗米驻留在废墟中，调查时间异常，消除历史中的扰动，并招募值得信赖的冒险者修复受损的时间线。",al={"克罗米 在这里做什么","克罗米 为什么在 安多哈尔","克罗米 西瘟疫之地"}},{q="青铜龙军团 是谁？",a="青铜龙军团 由守护巨龙诺兹多姆领导，获得了泰坦的赐福，拥有穿行并守护时间流的力量。他们确保历史沿着既定的轨迹发展，并在时间遭到篡改或腐化时出手干预。",al={"青铜龙","青铜龙军团 是什么","诺兹多姆 的龙族军团"}}},fp="9,149,23.333.0,26.430.0,26.166.0,32.115.0,49.234.0,32.234.0"}
P.entries["npc:clarice-foster"] = {n="克拉莉斯·弗斯特",s="在预见之池，克拉莉斯·弗斯特与牛头人先知和秘术师一同生活。远离洛丹伦，这位被遗忘者女子在莫高雷的崖壁下终日冥想。",h="在预见之池，克拉莉斯·弗斯特与牛头人先知和秘术师一同生活。远离洛丹伦，这位被遗忘者女子在莫高雷的崖壁下终日冥想。",kw={"克拉莉斯·弗斯特","被遗忘者","预见之池","灵魂高地","雷霆崖","至死方休"},ang={["race:Tauren"]="身为牛头人，你看到克拉莉斯·弗斯特受到欢迎，住进了灵魂高地下神圣的预见之池，这表明你的族人愿意接纳部落中不同寻常的新成员。",["race:Undead"]="身为被遗忘者的一员，克拉莉斯·弗斯特让你看到了族人与卡利姆多牛头人盟友之间的联系，远离提瑞斯法和银松森林那饱受瘟疫侵蚀的土地。"},sec={{t="预见之池中的被遗忘者",b="大多数被遗忘者仍留在洛丹伦，在幽暗城下重建他们的王国。克拉莉斯·弗斯特却远赴卡利姆多，来到牛头人领地的腹地。她住在雷霆崖台地下洞穴深广的预见之池，与研究大地的灵魂和元素奥秘的被遗忘者药剂师及牛头人萨满祭司为伴。"}},faq={{q="克拉莉斯·弗斯特是谁？",a="克拉莉斯·弗斯特是一位被遗忘者女子，住在雷霆崖下的预见之池。她是派驻莫高雷牛头人中的使者，也是少数与他们一同生活的亡灵访客之一。",al={"克拉莉斯是谁","克拉莉斯·弗斯特非玩家角色","克拉莉斯·弗斯特背景故事"}},{q="在哪里可以找到克拉莉斯·弗斯特？",a="你可以在预见之池找到克拉莉斯·弗斯特，那是雷霆崖灵魂高地下的一片洞穴。",al={"克拉莉斯·弗斯特位置","克拉莉斯·弗斯特在哪里","寻找克拉莉斯·弗斯特"}},{q="她提供哪些任务？",a="克拉莉斯·弗斯特提供至死方休任务。她的亡夫当年离开她去对抗亡灵，最终丧命，她对此心怀怨恨，于是派旅人前往银松森林的瑟伯切尔，将他的坠饰放在他的墓上。",al={"克拉莉斯·弗斯特任务","至死方休任务"}}},fp="14,180,33.346.0,22.185.0,32.104.0,27.203.0"}
P.entries["npc:clerk-daltry"] = {n="书记员达尔塔",s="在夜色镇大厅，书记员达尔塔保管着村镇的政务档案，也帮助人们查寻往事。账簿和登记册都由他照管，但档案的整理已落后许多，也常常无人问津。",h="在夜色镇大厅，书记员达尔塔保管着村镇的政务档案，也帮助人们查寻往事。账簿和登记册都由他照管，但档案的整理已落后许多，也常常无人问津。",kw={"卡尔文","书记员达尔塔","夜色镇","暮色森林","簿册","密斯特曼托","档案","斯塔文","镇政厅"},ang={["faction:Alliance"]="作为联盟的调查者，你可以向书记员达尔塔求助，在暮色森林的险恶谜团中查找失落已久的档案和旧案。",["race:Human"]="作为人类，你可以指望达尔塔保存Grand Hamlet留存下来的历史，那是黑暗笼罩这片林地之前的往事。"},sec={{t="镇上的档案保管员",b="书记员达尔塔照管着夜色镇的档案，而野兽、亡灵怪物和超自然的阴霾正步步逼近小镇。他在夜色镇大厅与艾尔罗·埃伯洛克公爵及当地议会一同工作。他的簿册记载着镇上的历史、地产名册和人口资料。灾难使这片地区分崩离析后，这些档案成了为数不多的线索，将人们与Grand Hamlet陷入阴影前的岁月相连。"},{t="纸上的线索",b="自夜色镇与暴风城的日常行政往来中断后，书记员达尔塔的档案便疏于整理。文书不断遗失，簿册未能及时更新，镇上的档案也常被放错地方或遭到损毁。调查旧案或寻找居民的人会来向他求助。要找到答案，可能得翻查被忽略的笔记，或冒险进入树林，找回遗失的文书。"},{t="斯塔文的传说",b="调查者追查斯塔文·密斯特曼托的家族传说时，书记员达尔塔会搜寻夜色镇的档案。登记册上关于这位昔日教师的记载残缺不全，因此他让寻访者走遍镇上各处，前往王国各地被遗忘的农庄。他们必须拼凑出那段悲惨而血腥的真相。"}},faq={{q="书记员达尔塔在哪里？",a="书记员达尔塔在暮色森林中心村镇夜色镇的夜色镇大厅内工作。他与镇上的官员和议会成员共事，保管着镇政档案。",al={"书记员达尔塔位置","达尔塔在哪","夜色镇书记员位置"}},{q="书记员达尔塔在夜色镇负责什么工作？",a="书记员达尔塔保管着夜色镇的文书、名册和法律登记簿。他帮助人们查找有关昔日居民、土地权属或镇上历史的记录。",al={"达尔塔做什么","达尔塔职责","书记员达尔塔是谁"}},{q="他的档案为什么残缺不全？",a="书记员达尔塔的档案残缺不全，是因为暮色森林经历了多年的孤立、魔法腐化和暴力动荡。守夜人的敌人威胁着人们的生存，簿册的更新也因此常常耽搁。",al={"达尔塔的档案为何残缺","暮色森林过时档案","达尔塔遗失的簿册"}},{q="书记员达尔塔会开启或参与哪些任务线？",a="书记员达尔塔帮助调查者追寻斯塔文·密斯特曼托的故事，查明他的过去。他也协助开展“卡尔文家族”和“继续搜寻”等调查。",al={"达尔塔任务","达尔塔提供什么任务","书记员达尔塔任务链"}},{q="谁会让调查者去找书记员达尔塔？",a="伊瓦夫人会让追查斯塔文谜团的人前往大厅寻找书记员达尔塔。寻找维琳德·星歌的旅人也曾被指引去找他。当档案再也提供不了线索时，达尔塔会让寻访者去别处，比如到旅店打听一位陌生人。",al={"谁让人去找达尔塔","达尔塔联系人"}},{q="部落玩家能与书记员达尔塔交谈吗？",a="不能。书记员达尔塔为联盟效力，守夜人守卫着夜色镇及镇政厅，抵御部落冒险者。",al={"达尔塔对部落友好吗","部落能与达尔塔交谈吗"}}},fx={["063859f4"]={q="书记员达尔塔是谁？",a="书记员达尔塔是一名人类文书官，驻守在暮色森林的夜色镇大厅。他负责保存小镇居民的市政记录、人口普查资料和家族史，是这座饱受阴影与尘封往事困扰的孤立聚居地的常驻档案管理员。",al={"达尔塔是谁","书记员达尔塔是谁","夜色镇的书记员达尔塔"}},["7e4b683b"]={q="书记员达尔塔属于哪一方？",a="达尔塔坚定地站在联盟和夜色镇一边。作为镇政厅的官员，他为当地民政机构效力，并协助那些帮助查明小镇祸患或寻找失踪者的旅人和调查者。",al={"达尔塔属于联盟吗","达尔塔的阵营","书记员达尔塔效忠于谁"}},["3b37b748"]={q="书记员达尔塔想要什么？",a="书记员达尔塔希望维护井然有序的档案，并协助调查暮色森林周围的黑暗谜团。他经常帮助旅人查阅镇上的日志、家族名册和旧文件，追查斯塔文·密斯特曼托等失踪居民，不过他的档案并不完整。",al={"达尔塔想要什么","书记员达尔塔的目标","达尔塔的动机"}},["7e737b61"]={q="书记员达尔塔为什么在这里？",a="达尔塔留在夜色镇，在镇政厅履行自己的市政职责。尽管森林日渐阴森，聚居地也不断遭遇危险，小镇仍需要一名文书官保存契约、信件以及本地区居民的身份记录。",al={"达尔塔为什么在夜色镇","书记员达尔塔为什么在这里","达尔塔在镇政厅的职责"}}},fp="12,205,18.396.0,15.344.0,21.310.1,30.168.0,40.171.0,31.237.0,58.205.0,40.255.0,42.119.0"}
P.entries["npc:cliffwatcher-longhorn"] = {n="峭壁卫兵图林·长角",s="峭壁卫兵图林·长角是一位沉着坚毅的牛头人领袖，驻守在千针石林高处的乱风岗。他肩负着保卫这座孤立的部落哨站的重任，统筹防务，抵御不断进犯的加拉克半人马，并监视恐怖图腾部族的可疑阴谋。",h="峭壁卫兵图林·长角是一位沉着坚毅的牛头人领袖，驻守在千针石林高处的乱风岗。他肩负着保卫这座孤立的部落哨站的重任，统筹防务，抵御不断进犯的加拉克半人马，并监视恐怖图腾部族的可疑阴谋。",kw={"阿纳克·恐怖图腾","卫兵穆赫·月角","峭壁卫兵图林·长角","乱风岗","加拉克","恐怖图腾","纳塔卡·长角","千针石林"},ang={["faction:Horde"]="乱风岗是保障卡利姆多南部补给线畅通的重要枢纽，长角确保部落能在敌对半人马的领地中守住这处岌岌可危的立足点。",["race:Tauren"]="对牛头人旅者而言，长角代表着Shu'halo的开拓精神，既守望着争夺不休的神圣台地，也周旋于同恐怖图腾部族之间尖锐而悬而未决的矛盾。"},sec={{t="台地守护者",b="乱风岗坐落于千针石林高耸的石柱之上，依靠敏锐的目光和沉稳的领导维系生存。峭壁卫兵图林·长角负责这座险地聚落的日常安保。敌对势力在下方的峡谷底部和邻近山脊上集结，长角则担任聚落的主要协调者，统筹侦察情报和军事防御行动。"},{t="半人马的敌意与恐怖图腾的阴谋",b="长角面临着来自多方的威胁。在下方峡谷中，好战的加拉克半人马不断试探哨站外围的防线，迫使他派遣冒险者击退他们，削减他们的数量。然而，更令他不安的是恐怖图腾牛头人。长角对他们设在哨站附近的隐秘营地深怀戒心，于是安排侦察行动，夺取他们藏匿的笔记，从中发现了内部背叛的可怕证据，其中包括阿纳克·恐怖图腾犯下的暴行。"}},faq={{q="峭壁卫兵图林·长角是谁？",a="峭壁卫兵图林·长角是统领乱风岗的牛头人首领，这座部落哨站高踞于千针石林之上。他组织侦察和防御巡逻，并安排应对当地威胁的行动。",al={"峭壁卫兵图林·长角资料","长角是谁","乱风岗领袖"}},{q="在哪里可以找到峭壁卫兵图林·长角？",a="他位于千针石林乱风岗的主台地顶端，从峡谷底部乘升降梯上去，再穿过木桥即可抵达。",al={"峭壁卫兵图林·长角位置","长角在哪里"}},{q="长角为什么担忧半人马？",a="卫兵穆赫·月角等斥候带回的报告表明，加拉克半人马的敌意正在急剧加剧，令人不安。长角下令主动出击，平定这个氏族，防止他们冲垮通往哨站的各处要道。",al={"为什么杀半人马","平定半人马背景故事","千针石林半人马威胁"}},{q="他为什么关注恐怖图腾部族？",a="恐怖图腾氏族名义上生活在部落之中，行事却毫不掩饰其隐秘作风与恶意。长角怀疑他们心怀不轨，于是委托冒险者窃取他们藏匿的笔记，查明他们的阴谋。",al={"长角 恐怖图腾","侦察恐怖图腾的原因"}},{q="阿纳克·恐怖图腾是谁，长角为什么要追捕他？",a="阿纳克·恐怖图腾曾对哨站居民发动暴力袭击。长角悬赏缉拿他，确保阿纳克因自己的背叛行径受到制裁。",al={"通缉阿纳克 恐怖图腾","阿纳克悬赏背景故事"}},{q="峭壁卫兵图林·长角有家人吗？",a="有，他的兄弟纳塔卡·长角驻守在遥远西方凄凉之地的幽灵岗哨。峭壁卫兵公务缠身，很少有机会给他写信。",al={"长角的兄弟","纳塔卡·长角的兄弟"}}},fx={["8c33620b"]={q="峭壁卫兵图林·长角效忠于哪一方？",a="峭壁卫兵图林·长角坚定地支持部落，以及听命于雷霆崖的牛头人部族。他驻守在乱风岗顶端，负责协调定居点的防御，依靠部落勇士守卫下方的峡谷道路，抵御来犯的半人马氏族和暗中作乱的邪枝部族。",al={"峭壁卫兵图林·长角阵营","长角效忠部落还是联盟","长角效忠于谁"}},d26a5d43={q="峭壁卫兵图林·长角想要什么？",a="长角希望维护千针石林各处的安全与秩序。他想要报复骚扰旅人的敌对加拉克半人马，揭穿当地邪枝部族正在策划的秘密阴谋，并让阿纳克·邪枝这类叛乱分子迅速受到制裁。",al={"长角想要什么","长角的目标","峭壁卫兵图林·长角的动机"}},e12f4ee3={q="峭壁卫兵图林·长角为什么在这里？",a="长角驻守在乱风岗，是这里的主要监管者和守卫之一。他从这座高耸的台地上监视峡谷地面的情况，指挥部落斥候，并组织应对包围前哨站的危险半人马部族和狡诈的邪枝部族。",al={"长角为什么在乱风岗","峭壁卫兵图林·长角为什么在千针石林","长角在乱风岗的职责"}}},fp="21,200,21.302.0,40.414.1,29.155.0,39.148.0,44.185.0,44.190.0,54.150.0,43.171.0"}
P.entries["npc:coleman-farthing"] = {n="库勒曼·法席恩",s="在布瑞尔的恐惧之末旅店里，库勒曼·法席恩心中始终怀着源自阿加曼德磨坊的仇恨。他曾为提瑞斯法北部富有的阿加曼德家族效力，与其他劳工一起为保卫雇主的庄园抵御天灾军团而死。如今，他已成为被遗忘者，一心向昔日的主人复仇。",h="在布瑞尔的恐惧之末旅店里，库勒曼·法席恩心中始终怀着源自阿加曼德磨坊的仇恨。他曾为提瑞斯法北部富有的阿加曼德家族效力，与其他劳工一起为保卫雇主的庄园抵御天灾军团而死。如今，他已成为被遗忘者，一心向昔日的主人复仇。",kw={"阿加曼德传家宝","阿加曼德磨坊","布瑞尔","库勒曼·法席恩","阿加曼德家族","恐惧之末旅店","洛丹伦","提瑞斯法林地"},ang={["class:Warrior"]="库勒曼指引胸怀抱负的战士前往阿加曼德家族墓穴，掠取这个没落贵族家族传下的武器，为未来的战争武装自己。",["race:Undead"]="对被遗忘者而言，库勒曼体现了许多平民对洛丹伦旧贵族的怨恨，瘟疫肆虐期间，这些贵族的傲慢与自负往往加速了臣民的死亡。"},sec={{t="满怀怨恨的仆人",b="第三次大战之前，库勒曼·法席恩在阿加曼德磨坊工作，那是提瑞斯法林地规模最大的磨坊与农场产业。当灾军团席卷洛丹伦时，贵族阿加曼德家族不肯舍弃价值不菲的土地逃走。他们催促家仆和劳工拿起武器，承诺大家能够守住农庄，抵挡亡灵大军。库勒曼和工友们相信了主人，留了下来。他们无一生还。"},{t="来自坟墓的复仇",b="库勒曼·法席恩被复活为亡灵后挣脱了控制，加入被遗忘者，却依旧憎恨阿加曼德家族。他认为，除了天灾军团，昔日雇主的贪婪与傲慢同样难辞其咎，是他们欺骗仆从，迫使众人进行了一场毫无胜算的最后抵抗。他身处布瑞尔的一家旅店，派部落勇士前往遭到污染的磨坊，杀死复活的阿加曼德族人，并从他们的家族墓穴中掠走传世武器，剥夺这个家族最后的荣耀。"}},faq={{q="在哪里能找到库勒曼·法席恩？",a="库勒曼·法席恩终日待在提瑞斯法林地中部布瑞尔的恐惧之末旅店里。",al={"库勒曼·法席恩位置","库勒曼·法席恩在哪","库勒曼·法席恩 布瑞尔"}},{q="库勒曼为何如此憎恨阿加曼德家族？",a="天灾军团入侵洛丹伦时，阿加曼德家族的家长们说服了包括库勒曼在内的工人，让他们留下来保卫磨坊，而非逃走。所有工人都遭到了屠杀，在库勒曼看来，主人号召他们战斗，不过是傲慢地操纵他们，最终害他丧命。",al={"库勒曼为何憎恨阿加曼德家族","库勒曼·法席恩的动机","阿加曼德磨坊的仇怨"}},{q="阿加曼德磨坊发生了什么？",a="天灾军团攻陷了这片广阔的庄园。庄园里的风力磨坊已沦为鬼魅出没的废墟，阿加曼德家族成员和遇害的工人则化作毫无心智、充满敌意的亡灵，在巫妖王的控制下游荡于遭到污染的田野。",al={"阿加曼德磨坊发生了什么","阿加曼德磨坊背景故事","阿加曼德磨坊属于谁"}},{q="库勒曼会交给冒险者什么任务？",a="库勒曼派冒险者北上阿加曼德磨坊，清剿游荡的亡灵，杀死复活的阿加曼德家族成员，带回他们的遗骸加以亵渎，随后再从阿加曼德家族墓穴中掠走祖传武器。",al={"库勒曼·法席恩任务","阿加曼德任务 布瑞尔"}},{q="库勒曼为何想要阿加曼德家族的传世武器？",a="在库勒曼眼中，阿加曼德家族的祖传武器象征着害死工友们的虚荣。他派战士前往家族墓穴掠走这些武器，夺去这个家族的荣耀，并将武器真正用于对抗敌人。",al={"阿加曼德传家宝任务背景","为何偷取阿加曼德武器"}},{q="库勒曼·法席恩与主教法席恩有亲属关系吗？",a="库勒曼·法席恩与主教法席恩姓氏相同，都出身于已经覆灭的洛丹伦王国，但没有确凿记载能够证实两人存在亲属关系。",al={"主教法席恩亲属关系","库勒曼·法席恩的家人"}}},fp="16,301,16.449.0,24.446.0,36.97.0,49.275.0,35.218.0,44.244.0,51.265.0,47.153.0"}
P.entries["npc:collin-mauren"] = {n="科林·马伦",s="在暴风城的法师区，科林·马伦研究实用魔法，用天然施法材料编织有用的法术。他还为侏儒好友兼探险同伴加克希姆·尘链制作奥术卷轴。",h="在暴风城的法师区，科林·马伦研究实用魔法，用天然施法材料编织有用的法术。他还为侏儒好友兼探险同伴加克希姆·尘链制作奥术卷轴。",kw={"石化蜥蜴","科林·马伦","尘魔","加克希姆·尘链","法师区","石爪山脉","暴风城","西部荒野"},ang={["class:Mage"]="身为法师，你能看出科林在法术技艺上的实验精神。他用元素残骸和石化蜥蜴鳞片等施法材料，编织实用的魔法。",["faction:Alliance"]="身为联盟的一员，你能看到科林如何为冒险者提供实用魔法，帮助阵营内部从西部荒野到卡利姆多的通讯与贸易。",["race:Human"]="身为人类，你与科林生活在同一座城市。他在暴风城法师区的潜心研究，体现了人类法师对学问的追求。"},sec={{t="奥术学者",b="在暴风城的法师区，科林·马伦研究如何用魔法解决实际问题。他利用遍布艾泽拉斯的异常自然物质和原始材料，构建奥术公式。这些材料的特性有助于他为朋友和旅人制作实用的卷轴与施法材料。"},{t="协助加克希姆·尘链",b="科林·马伦正在帮助好友加克希姆·尘链从远处引爆NG-5炸药。加克希姆是一位侏儒工匠，需要一个遥控引爆装置，于是科林设计了一道用于卷轴的传讯法术。为了将这道法术铭刻在卷轴上，科林使用了西部荒野那些行踪不定的尘魔留下的残骸。如今，他正等待加克希姆的计划进展的消息。"},{t="石爪山脉的奇异研究",b="科林·马伦的研究从暴风城跨越无尽之海，延伸至卡利姆多的石爪山脉。他在寻找当地石化蜥蜴的鳞片，这些生物坚韧的皮让他产生了兴趣，希望用作新法术的材料。前往卡利姆多的旅人常会收到他的委托，帮忙收集这些稀有的皮。这些鳞片帮助他研究原始生物的身体构造如何使复杂的附魔保持稳定。"}},faq={{q="在哪里可以找到科林·马伦？",a="科林·马伦位于暴风城的法师区，在首都奥术学者们使用的高塔与店铺之间。",al={"科林·马伦位置","科林·马伦在哪里","科林·马伦暴风城"}},{q="科林专精哪类魔法？",a="科林专精应用附魔与实用法术。他用元素残骸和野兽鳞片等天然材料进行实验，制作卷轴，其中就包括用于加克希姆遥控炸药的传讯法术。他还创造其他独特的魔法。",al={"科林·马伦研究","科林·马伦做什么","科林·马伦魔法"}},{q="加克希姆·尘链是谁，他与科林有什么关系？",a="加克希姆·尘链是一位热衷冒险的侏儒工匠，也是科林的朋友。当加克希姆需要从远处引爆炸药时，科林为他制作了一张铭刻着传讯法术的卷轴。",al={"加克希姆·尘链朋友","科林与加克希姆","加克希姆·尘链是谁"}},{q="科林为什么需要西部荒野的元素残骸？",a="科林需要西部荒野一只尘魔的残骸，将传讯法术铭刻在卷轴上。加克希姆·尘链需要这道法术，从远处引爆他的NG-5炸药。",al={"西部荒野中的恶魔任务","为什么需要尘魔","西部荒野尘魔任务"}},{q="科林为什么对石爪山脉感兴趣？",a="科林研究卡利姆多石爪山脉的石化蜥蜴鳞片，探索其中的魔法特性。他用这些坚固且天生具有抗性的皮作为新咒语的基础。",al={"石爪山脉石化蜥蜴","马伦的要求","石爪山脉鳞片科林"}},{q="科林隶属于肯瑞托吗？",a="科林住在法师区，遵循联盟法师中常见的魔法传统。他主要以独立研究者和施法材料制作者的身份工作，而非作为达拉然代表活动。",al={"科林属于肯瑞托吗","科林·马伦达拉然","法师区科林"}}},fx={f243f9d9={q="科林·马伦是谁？",a="科林·马伦是一位人类法师，住在暴风城的法师区。他是一名学术研究者，也钻研咒文，试验奥术公式与羊皮纸附魔，用来自远方的稀有材料，为同行和四处游历的冒险者制作魔法卷轴。",al={"科林是谁","科林·马伦 背景故事","马伦是谁"}},b186ecef={q="科林·马伦为什么在暴风城？",a="科林在暴风城的法师区安家，周围遍布城中的图书馆、学院，以及研习奥术的同行。在这片繁华的安身之所，他既能安心进行实验，也能从途经首都的冒险者手中获取珍奇的施法材料。",al={"科林为什么在这里","科林·马伦为什么在暴风城","科林在暴风城做什么"}},["8e195ded"]={q="科林·马伦想要什么？",a="科林寻求罕见的神秘施法材料，以完善自己的法术技艺。无论是从西部荒野的尘魔身上收集元素残骸，为朋友加克希姆·尘链制作专用的传讯卷轴，还是获取石爪山脉的石化蜥蜴鳞片，驱使他的都是对奥术的好奇，以及好奇的旅人们提出的需求。",al={"科林·马伦 动机","科林想要什么","科林在寻找什么"}}},fp="13,203,21.269.0,23.321.0,28.375.0,33.126.0,45.257.0,59.178.0,52.180.0,53.181.0,37.204.0"}
P.entries["npc:colonel-kurzen"] = {n="库尔森上校",s="康拉德·库尔森上校曾是暴风城军队中一位功勋卓著、品格高尚的军官，奉命率领远征队前往荆棘谷北部。他突然陷入疯狂，变得残暴专横，将麾下部队变成了一支盘踞在武装营地中的丛林叛军。如今，他昔日的部下驻扎在附近的反抗军营地，正积极设法杀死他，结束他的恐怖统治。",h="康拉德·库尔森上校曾是暴风城军队中一位功勋卓著、品格高尚的军官，奉命率领远征队前往荆棘谷北部。他突然陷入疯狂，变得残暴专横，将麾下部队变成了一支盘踞在武装营地中的丛林叛军。如今，他昔日的部下驻扎在附近的反抗军营地，正积极...",kw={"库尔森上校","康拉德·库尔森","多伦","库尔森","库尔森的营地","反抗军营地","储备物资","荆棘谷"},ang={["class:Warrior"]="库尔森的遭遇是一则警示：纪律严明的军事力量一旦失去意志与荣誉，也会被彻底颠覆和扭曲。",["faction:Alliance"]="库尔森的叛变是一桩严重的军事丑闻，也让暴风城部队蒙受了惨痛损失，促使联盟指挥部和当地忠于王国的人士授权将他铲除。",["race:Human"]="对暴风城的人类而言，库尔森曾是同袍，也是一位受人敬重的领袖，他残暴地沦为暴君，令人痛切地意识到丛林中的凶险。"},sec={{t="荣耀的陨落",b="堕落之前，康拉德·库尔森上校在暴风城被视为一位能力出众、品格高尚的军官。他深受王国高层信任，获命统率一支远征部队，南下深入荆棘谷的茂密丛林。然而，在潮湿的荒野深处，库尔森开始举止反常，变得极度狂妄自大，宣称对周围荒野拥有绝对统治权，并背弃了对暴风城的效忠。"},{t="反抗之火",b="库尔森的突然转变使麾下部队分裂。许多士兵陷入盲目的忠诚或扭曲的狂热，另一些人却对他的疯狂与暴行深感震惊，其中就包括他仅因艾米琳·朱尼斯拒绝求爱，便将她投入营地监牢的行径。在多伦上尉的带领下，一群良心不安的士兵脱离了部队，沿北部道路建立了反抗军营地。这些仍然忠于王国的出走者，如今正与库尔森殊死作战，试图阻止他麾下部队的肆虐。"},{t="幕后的食人魔",b="库尔森的疯狂并非源于丛林热病或寻常的疲惫。这位上校遭到了黑暗巫术的侵害，施术者正是莫什奥格氏族中狡诈的食人魔法师麦佐斯。麦佐斯控制了库尔森的心智，将一支纪律严明的暴风城部队变成了凶暴的棋子，通过操纵库尔森掌控这一地区，让食人魔无需亲自发动公开战争。"}},faq={{q="库尔森上校为何背叛暴风城？",a="在远征荆棘谷期间，库尔森开始举止反常，狂妄自大，并背弃了对暴风城的效忠。究竟是什么让这位曾经高尚的上校陷入疯狂，至今仍是个谜，反抗军营地中他昔日的士兵仍在努力查明真相。",al={"库尔森为何作恶","库尔森发生了什么","库尔森背景故事"}},{q="库尔森上校在哪里？",a="他在库尔森的营地深处指挥麾下民兵，这座营地位于荆棘谷北部的群山之中。他栖身于营地后方设有防御工事的储藏室建筑内。",al={"哪里能找到库尔森","库尔森位置","库尔森上校营地"}},{q="反抗军营地中的反抗军是谁？",a="这些反抗军曾是库尔森麾下的士兵，不愿追随他一同陷入疯狂。他们由多伦上尉领导，依然效忠暴风城，以北部边境附近的反抗军营地为据点，力图终结库尔森的叛军。",al={"反抗军营地背景故事","多伦上尉是谁","为何建立反抗军营地"}},{q="艾米琳·朱尼斯是谁？",a="艾米琳·朱尼斯是一名随远征队出行的女子，她拒绝了库尔森纠缠不休的求爱。随着上校日益残暴、妄念愈深，他将她关进了营地监牢的囚笼。",al={"艾米琳·朱尼斯","库尔森囚犯"}},{q="库尔森在丛林中独自行动吗？",a="不是。反抗军脱离部队、前往反抗军营地后，他仍然统率着那些继续效忠于他的人类雇佣兵、士兵和丛林战士。",al={"库尔森为谁效力","库尔森盟友"}},{q="杀死库尔森上校后会怎样？",a="多伦上尉要求联盟冒险者割下库尔森的头颅，以确凿证明上校已死，瓦解其民兵的指挥体系，并挽回暴风城军队的荣誉。",al={"库尔森任务结局","多伦 库尔森头颅"}}},fp="14,169,17.315.0,13.369.0,27.304.2,46.193.2,32.179.0,37.227.0,21.156.0,37.134.2,40.181.1"}
P.entries["npc:commander-mar-alith"] = {n="指挥官玛尔利斯",s="指挥官玛尔利斯是一位坚毅的暗夜精灵军事指挥官，在希利苏斯的塞纳里奥要塞统领塞纳里奥议会的先锋部队。他身披重甲，手持巨大的飞刃，统筹对抗异种虫群和暮光之锤教徒的军事行动。在坚定的领导风范之下，他因爱妻纳塔莉亚下落不明而深陷悲痛。",h="指挥官玛尔利斯是一位坚毅的暗夜精灵军事指挥官，在希利苏斯的塞纳里奥要塞统领塞纳里奥议会的先锋部队。他身披重甲，手持巨大的飞刃，统筹对抗异种虫群和暮光之锤教徒的军事行动。在坚定的领导风范之下，他因爱妻纳塔莉亚下落不明而深陷...",kw={"塞纳里奥议会","塞纳里奥要塞","指挥官玛尔利斯","亚什虫巢","雷戈虫巢","佐拉虫巢","玛尔利斯","纳塔莉亚·玛尔利斯","希利苏斯"},ang={["class:Warrior"]="玛尔利斯身披厚重的板甲，挥舞着巨大的飞刃，在这座主要由秘法修行者和自然守护者组成的定居点中，指挥着真刀真枪的战场厮杀。",["race:NightElf"]="玛尔利斯体现了Kaldorei哨兵与战士的献身精神，他们与德鲁伊教团并肩守卫，即使付出沉重的个人代价，仍捍卫卡利姆多，抵御古老的威胁。"},sec={{t="要塞指挥官",b="指挥官玛尔利斯驻守在塞纳里奥要塞的中心，肩负着守护议会沙漠堡垒的重任。德鲁伊们探究希利苏斯古老的生态与宇宙异象，而玛尔利斯则负责战争中严酷而务实的事务。他指挥部队对亚什虫巢、佐拉虫巢和雷戈虫巢中活跃的异种虫发动战术打击，确保远征队的核心据点不会被虫群无休止的入侵所淹没。"},{t="沙漠中的悲痛",b="尽管玛尔利斯仍保持着严肃的军人仪态，一场惨痛的私人悲剧却让他显得心力交瘁。他的爱妻纳塔莉亚玛尔利斯为执行议会的任务踏入流沙，此后便再未归来。在对塞纳里奥远征队的职责与锥心的悲痛之间挣扎，指挥官显得愈发心神不宁，紧抓仅存的希望，迫切盼望得知她在荒漠中的真实遭遇。"},{t="悲惨的命运",b="纳塔莉亚失踪背后的可怕真相沉重地压在指挥官心头。追寻她足迹的人发现，她在沙漠的低语中陷入疯狂，被一块其拉水晶洗脑，转而为克苏恩效力。得知她的悲惨结局后，玛尔利斯深受打击，指挥官不得不忍受撕心裂肺的痛苦，同时继续指挥希利苏斯的防御，抵御地下迫近的恐怖威胁。"}},faq={{q="指挥官玛尔利斯是谁？",a="指挥官玛尔利斯是一位暗夜精灵军官，担任塞纳里奥要塞中塞纳里奥议会部队的最高军事指挥官。他组织侦察与防御部队，并对希利苏斯各处的异种虫巢发动战术打击。",al={"玛尔利斯","指挥官玛尔利斯是谁","希利苏斯暗夜精灵指挥官"}},{q="在哪里可以找到指挥官玛尔利斯？",a="他位于塞纳里奥要塞内，这是塞纳里奥议会在希利苏斯风沙肆虐的沙漠中建立的主要中立定居点。",al={"玛尔利斯位置","玛尔利斯在哪"}},{q="他的妻子纳塔莉亚遭遇了什么？",a="纳塔莉亚玛尔利斯在一次远征中消失于沙漠，此后再未归来。冒险者沿着她在希利苏斯留下的踪迹追查，便能了解她的遭遇。",al={"纳塔莉亚在哪","亲爱的纳塔莉亚","纳塔莉亚 玛尔利斯的命运"}},{q="为什么玛尔利斯显得心不在焉？",a="妻子失踪，命运未卜，指挥官因此饱受悲伤与焦虑的折磨，即使竭力指挥要塞的防御，也常常为此分心。",al={"玛尔利斯为何分心","玛尔利斯举止反常"}},{q="指挥官玛尔利斯会向冒险者指派什么任务？",a="玛尔利斯发布作战任务，指派勇士们削减亚什虫巢、佐拉虫巢和雷戈虫巢中的异种虫兵力，对抗暮光之锤，并调查他失踪妻子的命运。",al={"玛尔利斯任务","玛尔利斯提供什么任务"}},{q="指挥官玛尔利斯是德鲁伊吗？",a="不是。尽管玛尔利斯为塞纳里奥议会效力，他却是一位身披铠甲的哨兵和战士指挥官，负责远征队的军事防御与战术行动，而非施展德鲁伊法术。",al={"玛尔利斯是德鲁伊吗","玛尔利斯职业"}}},fp="19,209,21.347.0,19.289.0,13.259.1,27.171.0,39.126.0,35.148.1,38.127.0,58.188.0,31.162.0"}
P.entries["npc:commander-springvale"] = {n="指挥官斯普林瓦尔",s="在影牙城堡，指挥官斯普林瓦尔的灵魂守卫着他殒命的厅堂。他曾是一名虔诚的圣骑士和指挥官，却与麾下士兵一同被阿鲁高的狼人杀害，至今仍在城堡中徘徊。",h="在影牙城堡，指挥官斯普林瓦尔的灵魂守卫着他殒命的厅堂。他曾是一名虔诚的圣骑士和指挥官，却与麾下士兵一同被阿鲁高的狼人杀害，至今仍在城堡中徘徊。",kw={"阿鲁高","指挥官","幽灵","圣骑士","暗影之牙","席瓦莱恩","银松森林","斯普林瓦尔","狼人"},ang={["class:Paladin"]="身为圣骑士的Springvale展现了，当一位高尚的骑士被束缚在腐化的坟墓中时，职责与神圣誓言如何化作永恒的折磨。",["faction:Alliance"]="身为联盟的一员，你可以将Springvale铭记为洛丹伦与吉尔尼斯阵亡将士中的一员。他们死于为阻止Scourge而贸然进行的召唤，而非Scourge本身。",["faction:Horde"]="身为收复银松森林的部落一员，你可以将安息Springvale的幽魂视为又一步行动，清除阿鲁高那场悲剧性失败留下的残余。"},sec={{t="陨落的指挥官",b="指挥官斯普林瓦尔统领着银松森林中影牙城堡的驻军。城堡尚未沦陷时，他是一名信奉圣光的高尚圣骑士。洛丹伦落入天灾军团之手后，他在那段动荡的日子里负责要塞的防务。"},{t="阿鲁高的愚行",b="大法师阿鲁高召唤了异位面的狼人，试图壮大达拉然日渐衰弱的军队，抵御亡灵天灾军团。这些野兽很快便脱离了他的控制，扑向影牙城堡。它们屠杀了席瓦莱恩男爵及其所有卫兵。斯普林瓦尔死在了自己誓言守护的厅堂中，未能继续履行职责。"},{t="无尽的守望",b="死亡并未让斯普林瓦尔得到解脱。他的幽灵与幽灵士兵一同徘徊在城堡的议事厅中。他依然以圣骑士的力量对抗入侵者，其中包括圣光和制裁之锤。"}},faq={{q="指挥官斯普林瓦尔生前是什么人？",a="指挥官斯普林瓦尔是一名信奉圣光的圣骑士，也是影牙城堡的指挥官。阿鲁高的狼人攻陷要塞时，他死在了那里。",al={"斯普林瓦尔的背景故事","指挥官斯普林瓦尔是谁","斯普林瓦尔是圣骑士吗"}},{q="指挥官斯普林瓦尔是怎么死的？",a="大法师阿鲁高召唤了凶猛的狼人来对抗天灾军团，但这些野兽却转而袭击了影牙城堡的居民。它们杀死了席瓦莱恩男爵、斯普林瓦尔和驻军。",al={"斯普林瓦尔是怎么死的","谁杀死了斯普林瓦尔","斯普林瓦尔之死"}},{q="指挥官斯普林瓦尔为何在影牙城堡徘徊？",a="斯普林瓦尔的灵魂仍被他最后的誓言束缚着。他的幽灵徘徊在厅堂中，守卫着这片废墟，抵御所有踏入此地的人。",al={"斯普林瓦尔为何成为幽灵","斯普林瓦尔的动机","斯普林瓦尔为何战斗"}},{q="斯普林瓦尔使用什么力量？",a="斯普林瓦尔在死后仍保留着圣骑士的能力。他用圣光治疗伤势，用制裁之锤击晕敌人。",al={"为何使用邪恶魔法","斯普林瓦尔的邪恶能力","堕落的圣骑士"}},{q="他的主人是谁？",a="没有记载提及斯普林瓦尔效忠的领主是谁。人们只知道，阿鲁高的狼人攻陷席瓦莱恩男爵的领地影牙城堡时，这位指挥官战死于此。",al={"斯普林瓦尔的主人","斯普林瓦尔效忠于谁","斯普林瓦尔与席瓦莱恩"}},{q="在城堡的什么地方能找到他？",a="指挥官斯普林瓦尔的幽灵徘徊在城堡深处戒备森严的房间里，靠近城堡的礼拜堂和议事厅。",al={"斯普林瓦尔的位置","斯普林瓦尔在哪里","暗影之牙中斯普林瓦尔的房间"}}},fx={ccdbb916={q="指挥官斯普林瓦尔效忠于哪一方？",a="指挥官斯普林瓦尔不再效忠任何活人，也没有与大法师阿鲁高或占据影牙城堡的狼人结盟。他死后化作幽灵，与自己的幽灵士兵一同徘徊在影牙城堡的议事厅，击倒闯入城堡大厅的任何活人。",al={"斯普林瓦尔的阵营","斯普林瓦尔效忠于谁","斯普林瓦尔的效忠对象"}},["5e96515a"]={q="指挥官斯普林瓦尔想要什么？",a="即使死后，指挥官斯普林瓦尔仍被束缚在自己陨落的影牙城堡。遭到腐化并转化为亡灵后，他将怒火倾泻在任何胆敢踏入城堡大厅的入侵者身上。",al={"斯普林瓦尔的目标","斯普林瓦尔想做什么","斯普林瓦尔的动机"}}},fp="20,197,20.263.0,14.329.0,16.197.0,37.155.0,33.176.0,53.124.0,32.113.0,19.156.0,34.122.0"}
P.entries["npc:cookie"] = {n="曲奇",s="曲奇在死亡矿井深处的巨舰上照看着船员们的烹饪大锅。他是迪菲亚潜行者中的一名鱼人，在绿皮队长和艾德温·范克里夫的监督下掌勺。在这座地下干船坞中，他是唯一一个完全可以跳过的首领。",h="曲奇在死亡矿井深处的巨舰上照看着船员们的烹饪大锅。他是迪菲亚潜行者中的一名鱼人，在绿皮队长和艾德温·范克里夫的监督下掌勺。在这座地下干船坞中，他是唯一一个完全可以跳过的首领。",kw={"绿皮队长","厨师","曲奇","死亡矿井","迪菲亚","艾德温·范克里夫","铁甲湾","巨舰","鱼人"},ang={["class:Rogue"]="范克里夫的盗贼网络依靠着一些古怪而不合常规的力量。曲奇就是兄弟会补给线上出人意料的古怪成员之一。",["faction:Alliance"]="暴风城的斥候或许会惊讶地发现，鱼人不仅出没于西部荒野的外围海岸，还在迪菲亚的领导层中任职。",["profession:Cooking"]="一艘亡命之徒的巨舰竟由鱼人担任主厨，可见海盗对饭食的要求既粗糙，又饥不择食。"},sec={{t="兄弟会的厨师",b="曲奇在铁甲湾那艘巍峨巨舰的甲板下做饭。担任这份差事的既不是人类斥候，也不是地精工程师，而是这个孤身一人的鱼人。曲奇是如何得到这个职位的，无人知晓。其他船员或许会怀疑鱼人的厨艺，但海盗很少挑剔自己的饭食。在月溪镇的地下世界，有饭吃就行。"},{t="苦涩的混合物",b="曲奇在海盗旗舰周围的水道和岸边巡逻。他挥舞着炊具，投掷酸性混合物。虽然远离寻常的鱼人部族，他仍会凶猛地守卫自己的大锅，向闯入船坞的入侵者投掷腐蚀性混合物。他的岗位远离主要跳板，因此许多攻入海湾的人都会绕过他的厨房。曲奇是迪菲亚巨舰上唯一可以绕过的监工。"}},faq={{q="为什么会有鱼人给迪菲亚当厨师？",a="没有任何记载说明曲奇是如何来到这艘巨舰上效力的。迪菲亚的亡命之徒和地精造船工接受了这样的安排，因为海盗船员只要能弄到食物就行，并不在乎厨师是什么种族。",al={"鱼人为何当厨师","曲奇为何在船上","曲奇迪菲亚背景故事"}},{q="在死亡矿井的哪里能找到曲奇？",a="曲奇位于死亡矿井最深处的铁甲湾。他在巨型木制战舰船尾附近的浅水和码头间巡逻，就在重拳先生看守的坡道后方。",al={"曲奇在哪里","曲奇死亡矿井位置","寻找曲奇"}},{q="必须击败曲奇才能通关死亡矿井吗？",a="不必，曲奇是死亡矿井中唯一可以跳过的首领。潜入者可以登船迎战绿皮队长和艾德温·范克里夫，无须惊动沿岸巡逻的厨师。",al={"曲奇可以跳过吗","必须击杀曲奇吗","跳过曲奇"}},{q="曲奇属于某个特定的鱼人部族吗？",a="曲奇与任何已知的当地鱼人部族都没有关联，包括西部荒野沿岸的那些部族。他在迪菲亚潜行者的亡命之徒和恶棍之间生活、工作。",al={"曲奇属于什么部族","曲奇鱼人部族"}},{q="曲奇使用什么武器或攻击手段？",a="曲奇用炊具进行近身战斗，并向攻击者泼洒腐蚀性酸液，用危险的烹饪混合物灼伤他们。",al={"曲奇技能","曲奇如何战斗","曲奇攻击方式"}},{q="曲奇在巨舰上听命于谁？",a="曲奇在绿皮队长的指挥下，为迪菲亚潜行者的海上部队效力，最终听命于艾德温·范克里夫。",al={"曲奇首领","曲奇听命于谁","曲奇绿皮队长范克里夫"}}},fx={f44f954f={q="曲奇是谁？",a="曲奇是一名精英鱼人，在死亡矿井深处艾德温·范克里夫的铁甲战舰上担任船厨。与大多数在西部荒野海岸四处游荡的野性鱼人不同，曲奇在一群人类暴徒中找到了一个不同寻常的归宿：他在锅里烹煮着令人难以放心的食物，供迪菲亚潜行者的海盗船员享用。",al={"曲奇是谁","曲奇的身份","鱼人厨师是谁"}},c6e0c482={q="曲奇效忠于哪一方？",a="曲奇坚定地效忠于迪菲亚潜行者。他与绿皮队长和艾德温·范克里夫一同驻守在战舰上，直接为海盗暴徒效力；他会竭力保卫船只，抵御任何试图破坏范克里夫叛乱的联盟入侵者。",al={"曲奇效忠于谁","曲奇是迪菲亚潜行者成员吗","曲奇属于什么阵营"}}},fp="6,241,22.321.0,13.434.0,49.210.0,43.188.0,43.188.0,46.180.0,40.148.0,44.130.0"}
P.entries["npc:corithras-moonrage"] = {n="科瑞萨斯·月怒",s="在多兰纳尔，科瑞萨斯·月怒向初来乍到的人讲述泰达希尔及其月亮井。他的教导揭示了这棵树在卡多雷生活中的地位，以及族人肩负的重担。",h="在多兰纳尔，科瑞萨斯·月怒向初来乍到的人讲述泰达希尔及其月亮井。他的教导揭示了这棵树在卡多雷生活中的地位，以及族人肩负的重担。",kw={"科瑞萨斯·月怒","大地之冠","多兰纳尔","范达尔·鹿盔","卡多雷","月亮井","暗夜精灵","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你会发现科瑞萨斯照料月亮井的工作与你的使命息息相关。这些仪式有助于监测世界之树的健康状况，以及悄然蔓延的病害。",["class:Priest"]="身为Elune的牧师，你可以帮助科瑞萨斯运送月亮井水，维护多兰纳尔周围荒野在灵性与形体上的和谐。",["race:NightElf"]="对于暗夜精灵，科瑞萨斯讲述了第三次战争后的生活，包括古老永生的丧失，以及泰达希尔备受争议的诞生。"},sec={{t="多兰纳尔的学者",b="在多兰纳尔，科瑞萨斯·月怒向旅人讲述泰达希尔。年轻的卡多雷开始走出幽影谷，探索这棵巨树，而他则向他们讲解新家园的历史。他也讲述了照料这片荒野所需付出的努力。在这个变迁的时代，唯有保持警惕、尊重自然秩序，才能生存下去。"},{t="大地之冠",b="科瑞萨斯为达纳苏斯的德鲁伊收集月亮井水。他派旅人用特制的小瓶，从泰达希尔各处的月亮井中汲取纯净的井水，再将井水送给范达尔·鹿盔。这项工作帮助他监护世界之树，保护荒野免受悄然蔓延的腐化侵蚀。"},{t="卡多雷的重担",b="泰达希尔背负的重担，与它的诞生息息相关。与古老的诺达希尔不同，这棵新的世界之树在生长之初并未得到守护巨龙的祝福。他们拒绝了范达尔·鹿盔这项雄心勃勃的计划。科瑞萨斯思索着暗夜精灵失去永生的代价，以及族人在这棵未获祝福的巨树下所面临的未卜前途。"}},faq={{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是多兰纳尔的一位暗夜精灵学者。他向旅人讲述泰达希尔，并派他们照料树上神圣的月亮井，检验井水。",al={"科瑞萨斯·月怒的职责","科瑞萨斯是谁","多兰纳尔任务给予者"}},{q="在哪里可以找到科瑞萨斯·月怒？",a="科瑞萨斯·月怒就在多兰纳尔的户外，这座村庄位于泰达希尔南部的道路交会处。",al={"科瑞萨斯的位置","科瑞萨斯在哪里","寻找科瑞萨斯"}},{q="大地之冠任务线讲述了什么？",a="大地之冠要求旅人从泰达希尔各处的月亮井中汲取井水。科瑞萨斯将收集的井水送往达纳苏斯，交给范达尔·鹿盔，那里的德鲁伊需要用这些水补充他们的月亮井。",al={"大地之冠的含义","科瑞萨斯的任务","月亮井任务"}},{q="科瑞萨斯为何担忧泰达希尔的由来？",a="科瑞萨斯心怀忧虑，因为泰达希尔是在第三次战争后为恢复暗夜精灵的永生而种下的，但守护巨龙拒绝赐予它祝福。这棵树缺少他们的庇护，他的族人也依然无法摆脱死亡。",al={"卡多雷为何背负重担","守护巨龙的拒绝","为何失去永生"}},{q="科瑞萨斯会教导新冒险者什么？",a="科瑞萨斯讲述第三次战争中的牺牲、泰达希尔的建立，以及每一位卡多雷保卫新林地家园的责任。",al={"科瑞萨斯的故事","多兰纳尔的历史","科瑞萨斯讲述什么"}},{q="科瑞萨斯效忠于塞纳里奥议会还是达纳苏斯？",a="科瑞萨斯是达纳苏斯忠诚的公民和学者，与多兰纳尔的德鲁伊和牧师一同守护森林及其水源。",al={"科瑞萨斯的阵营","科瑞萨斯是德鲁伊吗"}}},fx={a5e544f2={q="科瑞萨斯·月怒想要什么？",a="科瑞萨斯想要照料并了解这棵年轻世界之树的状况。通过名为“大地之冠”的仪式，他让旅人从泰达希尔各处神圣的月亮井收集重要的泉水，为参天的枝干赐福。他努力滋养这片土地，并探寻困扰卡多雷的重重负担。",al={"科瑞萨斯想要什么","科瑞萨斯·月怒的目标","科瑞萨斯的目的"}},["35aa58f2"]={q="科瑞萨斯·月怒为什么在多兰纳尔？",a="科瑞萨斯驻扎在繁忙的多兰纳尔，担任向幽影谷之外探险的新晋暗夜精灵冒险者的向导。他位于泰达希尔的中心，招募能干的人手执行重要仪式，并调查围绕世界之树日益加剧的生态与灵性问题。",al={"科瑞萨斯为什么在这里","科瑞萨斯为什么在多兰纳尔","科瑞萨斯·月怒在多兰纳尔的目的"}}},fp="18,173,19.310.0,18.301.0,26.324.1,26.159.0,38.100.0,47.209.0,54.216.0,42.146.0,59.139.0"}
P.entries["npc:councilman-millstipe"] = {n="议员米尔斯迪普",s="暴风城推翻夜色镇议会的裁决，让议会日益愤懑。议员米尔斯迪普住在镇政厅，希望为暮色森林的人民讨回公道。",h="暴风城推翻夜色镇议会的裁决，让议会日益愤懑。议员米尔斯迪普住在镇政厅，希望为暮色森林的人民讨回公道。",kw={"议员米尔斯迪普","夜色镇","迪克斯特·瓦德","暮色森林","贵族","米尔斯迪普","摩本特·费尔","监狱"},ang={["class:Rogue"]="对于愿意进入戒备森严的监狱、执行未经批准的政治处决的潜行者，米尔斯迪普提供了一份违抗贵族的差事。",["faction:Alliance"]="米尔斯迪普展现了暴风城养尊处优的贵族与暮色森林陷入绝境的边境聚落之间的政治分歧，这些聚落得到的援助寥寥无几，却面临来自首都的蛮横干涉。"},sec={{t="暴风城拒绝伸张正义",b="夜色镇面临亡灵和凶猛野兽的袭击，镇议会却还要与暴风城的官僚体制作斗争。议员米尔斯迪普的态度反映出镇民对王室日益加深的不满。臭名昭著的盗墓贼迪克斯特·瓦德因向死灵法师摩本特·费尔出售刚挖出的尸体而被捕。夜色镇的领袖们判处瓦德死刑，但暴风城的贵族减免了他的死刑，将他关进了暴风城监狱。"},{t="给贵族的警告",b="议员米尔斯迪普认为，暴风城的政客们已经将暮色森林的安全与正义抛诸脑后。他暗中指示冒险者前往监狱，在牢房里杀死迪克斯特·瓦德。这道命令违抗了贵族，也发出了警告：如果暴风城不肯保护暮色森林的人民，他们就会亲手讨回公道。"}},faq={{q="在哪里可以找到议员米尔斯迪普？",a="议员米尔斯迪普位于暮色森林东部的夜色镇镇政厅内。",al={"米尔斯迪普位置","米尔斯迪普在哪","寻找议员米尔斯迪普"}},{q="米尔斯迪普为什么想要迪克斯特·瓦德死？",a="迪克斯特·瓦德是个盗墓贼，他挖出暮色森林死者的遗体，卖给死灵法师摩本特·费尔。埃伯洛克勋爵判处他斩首，但暴风城的贵族饶了他一命，将他送进了监狱。",al={"为什么杀迪克斯特·瓦德","米尔斯迪普 迪克斯特·瓦德","瓦德罪行"}},{q="米尔斯迪普对暴风城有何不满？",a="米尔斯迪普认为，暴风城已经抛弃了暮色森林，却仍在干涉当地的司法。贵族推翻了夜色镇对迪克斯特·瓦德的死刑判决，让镇民觉得自己受到了王室的冷落，也得不到王室的保护。",al={"为什么对暴风城不满","贵族 夜色镇","米尔斯迪普政治"}},{q="米尔斯迪普有已知的家人吗？",a="议员米尔斯迪普没有已知的家人。",al={"米尔斯迪普亲属","多萝西娅·米尔斯提普","米尔斯迪普家人"}}},fx={["2e4c6610"]={q="议员米尔斯迪普是谁？",a="议员米尔斯迪普是暮色森林夜色镇议会的重要成员。他对暴风城的忽视和官僚干预感到不满，于是留在镇政厅保护饱受困扰的居民，并坚决反抗那些破坏暮色森林边境正义的远方贵族。",al={"米尔斯迪普是谁","议员米尔斯迪普","议员米尔斯迪普是谁"}},["926d4bb5"]={q="议员米尔斯迪普效忠于哪一方？",a="米尔斯迪普效忠于夜色镇居民和暮色森林议会。尽管他在名义上属于大联盟的一员，但他对暴风城腐败的贵族议会怀有强烈怨恨，坚定地维护自己的地方城镇，反对那些拒绝派遣援助的远方官僚。",al={"米尔斯迪普的阵营","米尔斯迪普属于联盟吗","米尔斯迪普效忠于谁"}},["78c3778b"]={q="议员米尔斯迪普想要什么？",a="米尔斯迪普想为暮色森林伸张边境正义，并向贵族议会发出明确警告。他对贵族赦免盗墓贼迪克斯特·瓦德、免其死刑一事深感厌恶，因此要求在监狱处死瓦德，以证明暮色森林不会容忍暴风城的腐败干预。",al={"米尔斯迪普的目标","米尔斯迪普想要什么","议员米尔斯迪普的目标"}},["7f6b4a90"]={q="议员米尔斯迪普为什么在这里？",a="米尔斯迪普留在夜色镇的镇政厅履行议员的公职。他在那里应对暮色森林日益严峻的危机，协调地方事务，并招募独立的勇士执行暴风城治安官拒绝执行的判决。",al={"米尔斯迪普为什么在暮色森林","米尔斯迪普为什么在这里","米尔斯迪普在夜色镇做什么"}}},fp="20,148,27.433.0,23.327.1,40.84.0,42.199.0,45.239.0,37.43.0"}
P.entries["npc:count-remington-ridgewell"] = {n="雷明顿·瑞治维尔伯爵",s="在暴风要塞，雷明顿·瑞治维尔伯爵将财富投入贵族的收藏事业。他是贵族的一名人类贵族，收集稀有文物、传家宝和艺术珍品。",h="在暴风要塞，雷明顿·瑞治维尔伯爵将财富投入贵族的收藏事业。他是贵族的一名人类贵族，收集稀有文物、传家宝和艺术珍品。",kw={"贵族","玛亚拉·布莱特文","博物馆","匹瑞诺德王冠","议事厅","雷明顿·瑞治维尔","瑞治维尔","暴风要塞"},ang={["faction:Alliance"]="身为联盟雇佣兵，你或许会发现瑞治维尔伯爵是一位出手阔绰的主顾。对于从北方覆灭的王国和失落的矮人城市中找回的遗物，他愿意支付丰厚的报酬。",["race:Human"]="身为人类，你能看到暴风城的贵族如何看重文化地位与艺术收藏，即使王国政局动荡也不例外。"},sec={{t="古物鉴赏家",b="雷明顿·瑞治维尔伯爵将目光从军事征战和地方叛乱转向了往昔。他家族的博物馆收藏着珠宝和文物，他不惜花费财富，收购艾泽拉斯各地覆灭文明与家族留下的遗物。为了充实展馆，他资助冒险者，并派遣玛亚拉·布莱特文这样的外勤人员深入危险的废墟。他们的搜寻范围从奥特兰克的山间堡垒，一直延伸到燃烧平原的火山荒地。"}},faq={{q="雷明顿·瑞治维尔伯爵是谁？",a="雷明顿·瑞治维尔伯爵是一位人类贵族和古物收藏家，身处暴风要塞的请愿者大厅。他用家族财富购藏来自世界各地的遗物、珠宝和艺术品。",al={"雷明顿·瑞治维尔是谁","雷明顿·瑞治维尔","瑞治维尔伯爵"}},{q="瑞治维尔伯爵在寻找哪些文物？",a="瑞治维尔为自己的博物馆寻找失落的传家宝，包括奥特兰克废墟中的匹瑞诺德王冠，以及索瑞森废墟中具有历史价值的黑铁矮人宝物。",al={"瑞治维尔任务","匹瑞诺德王冠任务","他想要什么"}},{q="玛亚拉·布莱特文是谁？",a="玛亚拉·布莱特文是受雇于瑞治维尔伯爵的一名密探。他派她前往燃烧平原，在古老的索瑞森废墟中搜寻古物。",al={"玛亚拉·布莱特文的关联","玛亚拉是谁"}},{q="在哪里可以找到雷明顿·瑞治维尔伯爵？",a="可以在暴风要塞内的请愿者大厅找到雷明顿·瑞治维尔伯爵。寻求觐见王室的贵族和显要都聚集在那里。",al={"瑞治维尔伯爵在哪里","瑞治维尔位置","请愿者大厅贵族"}}},fx={["7bd2f97e"]={q="雷明顿·瑞治维尔伯爵效忠哪一方？",a="瑞治维尔伯爵是暴风城王国忠诚的贵族，也是贵族的一员。他坚定地站在联盟一方，在皇家要塞中开展上流社会的赞助活动，处理私人事务。",al={"瑞治维尔伯爵 阵营","瑞治维尔 效忠对象","瑞治维尔为谁效力"}},ecd2a567={q="雷明顿·瑞治维尔伯爵为什么在暴风要塞？",a="作为一位颇具影响力的贵族和贵族成员，瑞治维尔伯爵在暴风要塞的请愿者大厅出席宫廷活动。他在这里维系家族的声望，处理宫廷事务，并雇用勇敢的冒险者，前往艾泽拉斯各地寻回珍贵的遗物。",al={"瑞治维尔为什么在这里","瑞治维尔伯爵为什么在暴风要塞","瑞治维尔 请愿者大厅"}}},fp="25,174,28.437.0,33.194.0,41.170.0,25.155.0,45.167.0"}
P.entries["npc:crane-operator-bigglefuzz"] = {n="起重机操作员比戈弗兹",s="起重机操作员比戈弗兹是一名地精码头工人，在棘齿城港口操作重型机械。一次起重机超载事故让货物散落在码头各处，如今他急于在上司察觉之前，找回一瓶被盗的名贵酒。",h="起重机操作员比戈弗兹是一名地精码头工人，在棘齿城港口操作重型机械。一次起重机超载事故让货物散落在码头各处，如今他急于在上司察觉之前，找回一瓶被盗的名贵酒。",kw={"比戈弗兹","货物","起重机操作员","码头","疯狂的马格利什","波特酒","棘齿城","热砂港"},ang={["class:Rogue"]="潜行者想必深有体会，像疯狂的马格利什这样伺机下手的窃贼，能多快地利用码头片刻的混乱，从地精眼皮底下偷走价值连城的违禁品。",["profession:Engineering"]="工程师或许能理解，热砂港的吊索和起重机超载，至今仍是卡利姆多沿岸工业事故的主要原因。"},sec={{t="码头事故",b="和许多地精码头工人一样，起重机操作员比戈弗兹只顾效率和速度，连最基本的安全余量也抛在脑后。他试图从一艘商船上吊起过重的货物，结果起重机不堪重负，货箱纷纷坠落，砸在棘齿城的码头各处。混乱之中，趁机捞上一笔的无赖蜂拥而至，比戈弗兹只得手忙脚乱地收拾残局，抢救最贵重的货物，免得加兹鲁维或当地的港口主管扣他的工钱。"},{t="失窃的波特酒",b="事故中最惨重的损失并非那些碎木板，而是一箱罕见的九十九年陈酿波特酒。比戈弗兹还没来得及收好散落的货物，一个名叫疯狂的马格利什、行踪不定的流浪汉就抢走了一瓶酒，躲了起来，比戈弗兹恐怕得为这无法弥补的损失承担责任。"}},faq={{q="起重机操作员比戈弗兹是谁？",a="他是驻守棘齿城码头的地精起重机操作员，负责为热砂港装卸海运货物。",al={"比戈弗兹是谁","起重机操作员","比戈弗兹 棘齿城"}},{q="码头事故是怎么发生的？",a="比戈弗兹想用起重机一次吊起远超负荷的货物，导致机械失灵，货物散落了整个码头。",al={"起重机为什么掉落货物","棘齿城码头事故","起重机事故"}},{q="谁偷了比戈弗兹的东西？",a="一个名叫疯狂的马格利什的狡猾无赖趁货物散落之机，抢走了一瓶名贵的九十九年陈酿波特酒，随后溜之大吉。",al={"谁拿走了波特酒","疯狂的马格利什 货物","谁抢了比戈弗兹"}},{q="比戈弗兹为什么如此担心那瓶被盗的酒？",a="九十九年陈酿波特酒极其稀有，价格昂贵。因疏忽而丢失这瓶酒，意味着热砂港的头目们会让他付出惨重的金钱代价，甚至受到更严厉的惩罚。",al={"比戈弗兹为什么在意那瓶酒","码头麻烦的起因"}}},fx={acbd2274={q="起重机操作员比戈弗兹效忠于哪一方？",a="比戈弗兹受雇于热砂港，驻扎在中立港口棘齿城。和镇上的大多数地精一样，他主要效忠于自己的生意和雇主，而非部落或联盟；只要愿意做生意，或帮他弥补代价高昂的过失，他都会欢迎。",al={"比戈弗兹所属阵营","比戈弗兹为谁工作","起重机操作员比戈弗兹的效忠对象"}},e72c0e10={q="起重机操作员比戈弗兹想要什么？",a="比戈弗兹想找人取回那瓶在货物洒满码头时遗失的99年波尔多陈酿。一个名叫疯狂的马格利什的地精偷走了这瓶珍稀佳酿。比戈弗兹急着把它找回来，以免上司发现这场意外。",al={"比戈弗兹需要什么","比戈弗兹的目标","比戈弗兹要你做什么"}},d46df1e8={q="起重机操作员比戈弗兹为何在这里？",a="比戈弗兹驻守在棘齿城码头，负责操作大型装货起重机，在商船和岸边之间搬运货物。不幸的是，他试图一次吊起远超负荷的货物，结果起重机严重损坏，港口的货物也散落在整个码头上。",al={"比戈弗兹为何在棘齿城","比戈弗兹在棘齿城的职责","比戈弗兹为何在码头"}},eaf0ddf2={q="起重机操作员比戈弗兹与谁有关联？",a="比戈弗兹隶属于热砂港，是棘齿城码头工人的一员。他眼下的烦恼与窃贼疯狂的马格利什直接相关，对方从他洒落的货物中偷走了贵重酒品。",al={"比戈弗兹的人际关系","比戈弗兹隶属于谁","比戈弗兹与热砂港"}}},fp="25,166,19.401.0,15.241.0,33.101.0,38.112.0,26.134.0,53.182.0"}
P.entries["npc:craven-drok"] = {n="克拉文·德洛克",s="在奥格瑞玛，克拉文·德洛克藏身于暗影裂口，为一件微妙的事寻找旅人。他想让他们思考联盟如何看待部落。",h="在奥格瑞玛，克拉文·德洛克藏身于暗影裂口，为一件微妙的事寻找旅人。他想让他们思考联盟如何看待部落。",kw={"联盟关系","暗影裂口","克拉文·德洛克","奥格瑞玛"},ang={["class:Rogue"]="身为潜行者，你或许对暗影裂口十分熟悉，那些隐秘行事的人聚集于此，结识像Drok这样的联系人。",["race:Orc"]="身为兽人，你或许会觉得，克拉文·德洛克潜藏在暗影裂口的习惯，有损你们族人所珍视的荣誉与勇气。"},sec={{t="暗影中的潜行者",b="克拉文·德洛克避开奥格瑞玛阳光明媚的大道，在城下蜿蜒的小径间游荡。暗影裂口吸引着术士、潜行者，以及从事不太光彩营生的人。德洛克隐匿行踪，雇用过路人秘密办事，其中一件便与部落在联盟眼中的地位有关。"}},faq={{q="在哪里能找到克拉文·德洛克？",a="克拉文·德洛克在暗影裂口的地下小径间游荡，就在奥格瑞玛的主要干道下方。",al={"克拉文·德洛克位置","克拉文·德洛克在哪里","德洛克奥格瑞玛位置"}},{q="他为什么被称为“懦夫”？",a="克拉文·德洛克在阴暗的洞穴中躲躲藏藏，行事低调，因此得了这个名号。他雇用别人处理自己不愿面对的差事，这有悖于兽人崇尚勇气与战斗荣耀的理念。",al={"他为何怯懦","克拉文·德洛克名字","克拉文·德洛克是懦夫吗"}},{q="他与联盟有什么牵连？",a="克拉文·德洛克在联盟关系任务的开头，称赞萨尔的智慧以及对人类行事方式的了解。他派旅人去找科尔丹，后者致力于避免联盟误以为部落与燃烧军团订立了契约。",al={"克拉文·德洛克联盟","联盟关系 德鲁克"}},{q="克拉文·德洛克派旅人去找谁？",a="克拉文·德洛克派旅人去找科尔丹，一位研习魔法的人，他的陋屋位于奥格瑞玛西侧出口附近。在大酋长的支持下，科尔丹致力于避免部落被误认为是燃烧军团的盟友。",al={"科尔丹是谁","德洛克联系人"}}},fp="11,133,24.285.0,29.105.0,26.188.0,42.229.0,39.223.0"}
P.entries["npc:cyrus-therepentous"] = {n="塞勒斯·萨雷芬图斯",s="塞勒斯·萨雷芬图斯是一名强大的黑龙人，栖身于燃烧平原滑石的洞穴深处。他不会立即杀死闯入者，而是考验那些胆大的凡人，看看他们是否有足够的力量为黑龙效力。",h="塞勒斯·萨雷芬图斯是一名强大的黑龙人，栖身于燃烧平原滑石的洞穴深处。他不会立即杀死闯入者，而是考验那些胆大的凡人，看看他们是否有足够的力量为黑龙效力。",kw={"黑龙","燃烧平原","塞勒斯·萨雷芬图斯","龙人","滑石","烈焰精华"},sec={{t="滑石之主",b="塞勒斯·萨雷芬图斯隐居在滑石的一处洞穴中，俯瞰燃烧平原的火山峭壁。和许多同类一样，他极其轻蔑地看待凡人旅者，声称只有蠢货才会打扰他的巢穴。然而，他凶猛的外表下藏着冷酷的算计：他不会一见到擅闯者就将其吞食，而是让他们挑战自己那些致命的爪牙，打算利用那些足够顽强、能在烈焰试炼中存活下来的人。"}},faq={{q="塞勒斯·萨雷芬图斯是谁？",a="塞勒斯·萨雷芬图斯是一名聪慧的黑龙人，驻守在燃烧平原滑石的一处洞穴中。他为黑龙效力，考验那些胆敢进入他巢穴的凡人冒险者。",al={"塞勒斯·萨雷芬图斯","塞勒斯是谁","滑石龙人"}},{q="在哪里可以找到塞勒斯·萨雷芬图斯？",a="他栖身于燃烧平原东北部滑石的一处洞穴深处。",al={"塞勒斯位置","塞勒斯·萨雷芬图斯在哪里","塞勒斯洞穴"}},{q="塞勒斯为什么不一见到冒险者就发动攻击？",a="虽然塞勒斯公开表示考虑吃掉擅闯者，但他更愿意看看凡人能否为他所用。他会让他们面对致命的试炼和爪牙，放过那些证明自己有用的人。",al={"塞勒斯为什么友善","塞勒斯为什么不杀我","塞勒斯对话"}}},fp="18,146,26.357.0,26.165.0,38.94.0,46.186.0"}
P.entries["npc:dalar-dawnweaver"] = {n="达拉尔·道恩维沃尔",s="在瑟伯切尔，达拉尔·道恩维沃尔将自己的奥术学识用于对抗被遗忘者的敌人。他曾是达拉然的大法师，在天灾军团摧毁这座城市时死去，后来摆脱了巫妖王的控制。如今，他研究着达拉然残存的势力，并力图终结大法师阿鲁高的疯狂行径。",h="在瑟伯切尔，达拉尔·道恩维沃尔将自己的奥术学识用于对抗被遗忘者的敌人。他曾是达拉然的大法师，在天灾军团摧毁这座城市时死去，后来摆脱了巫妖王的控制。如今，他研究着达拉然残存的势力，并力图终结大法师阿鲁高的疯狂行径。",kw={"大法师","阿鲁高","达拉尔","达拉然","道恩维沃尔","被遗忘者","肯瑞托","瑟伯切尔","银松森林"},ang={["class:Mage"]="身为一名被遗忘者法师，你能从达拉尔身上看到达拉然昔日辉煌的阴暗倒影。他在肯瑞托所受的训练，如今为黑暗女王所用。",["faction:Horde"]="在瑟伯切尔，达拉尔协助守卫部落的西部边疆。他协调针对影牙城堡狼人和肯瑞托敌对据点的打击行动。",["race:Undead"]="身为亡灵，你能看到达拉尔以被遗忘者的身份重新掌握自己的意志。他运用生前积累的知识，对抗达拉然的残余势力，以及威胁被遗忘者主权的叛逆巫师。"},sec={{t="陨落的大法师",b="达拉尔·道恩维沃尔曾在肯瑞托身居高位，在达拉然的奥术造诣鼎盛之时，行走于紫罗兰城堡的厅堂之间。天灾军团为召唤阿克蒙德而洗劫这座城市时，他的凡人生命走到了尽头。达拉尔被复活为巫妖王麾下毫无心智的奴仆，在天灾军团的控制减弱时，与希尔瓦娜斯·风行者女士一同挣脱了束缚。如今，他身在瑟伯切尔，依然保有大法师敏锐的头脑，并将这份才智用于守护被遗忘者的领地。"},{t="关注安伯米尔与影牙城堡",b="银松森林危机四伏，达拉尔负责指挥瑟伯切尔的奥术战略。在南方，达拉然的巫师占据了安伯米尔，暗中从事着他意图查明并加以破坏的活动。影牙城堡距离更近，城中的凶暴狼人游荡在林间。达拉尔十分了解自己昔日的同僚——大法师阿鲁高。他谨慎地指挥行动，阻止阿鲁高创造的野兽肆虐整个地区。"}},faq={{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是一名驻守在银松森林瑟伯切尔的被遗忘者法师。他曾是达拉然肯瑞托的大法师。在第三次大战期间死去并被天灾军团复活后，他摆脱了巫妖王的控制，加入了黑暗女王的阵营。",al={"达拉尔是谁","达拉尔·道恩维沃尔的故事","达拉尔的背景"}},{q="他在第三次大战期间经历了什么？",a="阿尔萨斯·米奈希尔率领天灾军团入侵达拉然、夺取麦迪文之书时，达拉尔就在城中。克尔苏加德将阿克蒙德召唤到艾泽拉斯之际，他在进攻中丧生，随后被复活为天灾军团的仆从，直到希尔瓦娜斯解放了他。",al={"达拉尔如何死去","达拉尔之死","达拉尔与第三次大战"}},{q="达拉尔为何驻守瑟伯切尔？",a="达拉尔是被遗忘者在银松森林当地的奥术权威。他了解占据安伯米尔的肯瑞托部队，也熟悉昔日的同僚大法师阿鲁高，因此很适合应对这两方威胁。",al={"达拉尔为何在瑟伯切尔","达拉尔在银松森林的职责"}},{q="达拉尔与大法师阿鲁高有什么关系？",a="在达拉然陷落之前，达拉尔和大法师阿鲁高都是城中的肯瑞托法师。达拉尔了解阿鲁高在影牙城堡进行召唤实验的悲惨历程，以及这些实验带来的致命危险。他派冒险者搜集阿鲁高愚行留下的遗物，并最终要求除掉这名疯狂的法师。",al={"达拉尔与阿鲁高","达拉尔认识阿鲁高吗"}},{q="达拉尔对达拉然的残余势力有何打算？",a="达拉尔监视着昔日的故土，以及安伯米尔幸存的肯瑞托部队。他指派密探截获他们的信件，查明他们的意图，使他们无法威胁银松森林的被遗忘者。",al={"达拉尔与达拉然","达拉尔与安伯米尔"}},{q="达拉尔与肯瑞托属于同一阵营吗？",a="不是。达拉尔曾是肯瑞托的大法师，如今却效忠于被遗忘者和部落。他积极对抗银松森林中残存的肯瑞托部队。",al={"达拉尔是肯瑞托成员吗","达拉尔效忠达拉然吗"}}},fp="16,303,17.484.0,32.416.0,24.249.0,42.253.0,40.204.0,46.294.0,45.208.0,36.183.0"}
P.entries["npc:daphne-stilwell"] = {n="达芙妮·斯迪威尔",s="在西部荒野的悬崖上，达芙妮·斯迪威尔守望着自己的果园与家园。她和丈夫乔丹从北方逃难而来，如今一边协助圣光教会，一边守护土地，抵御附近的匪徒。",h="在西部荒野的悬崖上，达芙妮·斯迪威尔守望着自己的果园与家园。她和丈夫乔丹从北方逃难而来，如今一边协助圣光教会，一边守护土地，抵御附近的匪徒。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","乔丹·斯迪威尔","长滩","果园","焚木村","影牙城堡","勇气之书","西部荒野"},ang={["class:Paladin"]="作为圣骑士，你在勇气之书的试炼中抵御迪菲亚潜行者劫掠者，保护达芙妮·斯迪威尔，以此证明你守护无辜者的决心。",["faction:Alliance"]="作为联盟的一员，你与斯迪威尔夫妇分担重担。这对来自北方的难民身处危机四伏的西部荒野，依然为联盟和Church of the Holy Light效力。"},sec={{t="悬崖上的生活",b="在月溪镇和死亡矿井出口的西面，达芙妮·斯迪威尔照料着峭壁上的农庄与苹果园。下方是长滩，上方高空则是通往荆棘谷的狮鹫航线。无论从哪条路望去，农场或许都显得宁静，但附近有强盗和拾荒者游荡。达芙妮在果树间劳作，守望着这片偏僻的土地。"},{t="北方的难民",b="来到西部荒野之前，达芙妮和丈夫乔丹住在洛丹伦的焚木村附近。他们曾在如今的影牙城堡工作。黑暗与灾难迫使他们和成千上万的人类难民一起逃往南方。在暴风城附近，乔丹闻名遐迩的工匠技艺和达芙妮沉稳可靠的为人，让他们与圣光教会建立了密切的联系。他们支持教会，并为白银之手的圣骑士提供神圣武器。"},{t="保卫农场",b="达芙妮·斯迪威尔面临着死亡矿井附近迪菲亚潜行者的威胁。乔丹时常外出，或在首都之外打造神圣武器，留下她独自照料海边的家园。当匪徒为了报复或劫掠而袭击农场时，达芙妮拿起武器，与大教堂派来的圣骑士候选者并肩作战。她在战斗中展现出了勇猛与干练。"}},faq={{q="达芙妮·斯迪威尔是谁？",a="达芙妮·斯迪威尔照料着西部荒野长滩上方一座偏僻的农舍。她是著名铁匠乔丹·斯迪威尔的妻子，两人一同逃离了饱受摧残的北方诸国。",al={"达芙妮是谁","达芙妮·斯迪威尔资料","斯迪威尔的妻子"}},{q="达芙妮来自哪里？",a="达芙妮曾住在北方的焚木村附近，在如今的影牙城堡工作。灾难迫使她和乔丹南下，来到暴风城势力范围内的土地。",al={"达芙妮的来历","达芙妮来自哪里","达芙妮是吉尔尼斯人吗"}},{q="迪菲亚潜行者为什么袭击她的农场？",a="达芙妮的农场坐落在死亡矿井出口隧道上方的悬崖上，俯瞰西部荒野南部的海域。由于靠近迪菲亚潜行者的据点，这里成了匪徒夺取补给或铲除碍事者的目标。",al={"迪菲亚潜行者为何袭击达芙妮","迪菲亚潜行者袭击农场","斯迪威尔农场强盗"}},{q="达芙妮与圣骑士有什么联系？",a="乔丹通过锻造受祝福的武器来协助圣光教会。在勇气之书的试炼期间，白银之手的圣骑士会被派往西部荒野，保护达芙妮免受强盗侵害。",al={"圣骑士任务达芙妮","勇气之书达芙妮","圣骑士为何拜访达芙妮"}},{q="达芙妮能保护自己吗？",a="能。当迪菲亚潜行者袭击她的果园时，达芙妮会拿起武器，与保卫农庄的圣骑士并肩作战。",al={"达芙妮会战斗吗","达芙妮是战士吗"}},{q="如何前往她的农舍？",a="达芙妮的农场位于西部荒野西南部的崖顶，在月溪镇西南方，靠近死亡矿井通往隐秘海湾的出口，俯瞰着长滩。",al={"达芙妮的农场在哪里","如何前往斯迪威尔农场","达芙妮·斯迪威尔位置"}}},fx={fe5dc862={q="达芙妮·斯迪威尔效忠哪一方？",a="达芙妮·斯迪威尔站在联盟一方，并始终深深效忠于圣光教会。她与丈夫乔丹长久以来一直帮助暴风城的圣骑士，为寻访他们偏僻家园的年轻圣光卫士提供庇护和援助。",al={"达芙妮·斯迪威尔 阵营","达芙妮·斯迪威尔 联盟","达芙妮·斯迪威尔为谁效力"}},["5fa85e8c"]={q="达芙妮·斯迪威尔想要什么？",a="达芙妮只想照料自己的苹果园，与丈夫乔丹一起过平静安宁的生活。然而，迪菲亚潜行者在西部荒野的峭壁间游荡，威胁着她的家园，她只能依靠来访的圣骑士帮助抵御这些匪徒。",al={"达芙妮·斯迪威尔需要什么","达芙妮·斯迪威尔 目标","达芙妮·斯迪威尔 动机"}},["57f727ad"]={q="达芙妮·斯迪威尔为什么在这里？",a="达芙妮与丈夫逃离银松森林的影牙城堡后，在这片俯瞰长滩的偏僻高地定居。当黑暗与疯狂吞噬他们北方的家园时，他们向南来到暴风城王国，在远离天灾军团的地方务农，建立平静的生活。",al={"达芙妮为什么在西部荒野","达芙妮·斯迪威尔为什么在这座农场","达芙妮为什么离开影牙城堡"}}},fp="15,208,20.344.0,21.442.0,18.356.1,23.186.0,27.166.0,51.220.1,40.185.0,26.121.0,31.150.0"}
P.entries["npc:darcy-parker"] = {n="达希",s="在湖畔镇旅店，达希让镇上的守卫吃饱肚子，保持士气。她供应酒水和热饭，尤其关照卫兵帕克。",h="在湖畔镇旅店，达希让镇上的守卫吃饱肚子，保持士气。她供应酒水和热饭，尤其关照卫兵帕克。",kw={"达希","卫兵帕克","湖畔镇","湖畔镇旅店","玛蒂·詹罗斯","赤脊山","女服务员"},ang={["faction:Alliance"]="作为联盟的旅行者，你可以在湖畔镇的平民百姓中找到达希。在镇子等待暴风城援助的日子里，她让大家吃饱肚子，保持士气。"},sec={{t="旅店里亲切的面孔",b="达希日夜操持着湖畔镇旅店的柜台生意。豺狼人和黑石兽人不断威胁着湖畔镇，镇上的民兵便来这里吃饭喝酒。达希也关照着驻守在镇子周围的卫兵。她请旅行者为驻守边境的守卫送去热饭，捎去问候。"},{t="哨位上的恋情",b="达希格外关心卫兵帕克，他在三角路口附近的道路上巡逻。她觉得他空着肚子工作太辛苦，常请旅行者为他送去午饭。达希密切留意着玛蒂·詹罗斯，认为她心怀嫉妒，是争取帕克青睐的情敌。他们的情愫与保卫湖畔镇的职责交织在一起。"}},faq={{q="达希是谁？",a="达希是赤脊山湖畔镇旅店的一名人类女服务员。她为镇上的守卫准备食物，并请过路的旅行者为执勤的卫兵送饭。",al={"达希是谁","达希 帕克 非玩家角色","湖畔镇女服务员"}},{q="达希与卫兵帕克是什么关系？",a="达希十分爱慕卫兵帕克。他在三角路口附近的道路上巡逻时，她会为他打包新鲜的午饭，托旅行者送去。",al={"达希与卫兵帕克","卫兵帕克 达希","达希喜欢谁"}},{q="达希为什么怀疑玛蒂·詹罗斯？",a="达希认为玛蒂·詹罗斯心怀嫉妒，并将她视为争取卫兵帕克关注的情敌。",al={"达希与玛蒂","玛蒂·詹罗斯","达希的情敌"}},{q="在哪里能找到达希？",a="你可以在赤脊山止水湖北岸的湖畔镇找到达希，她正在湖畔镇旅店招待客人。",al={"达希位置","达希在哪里","寻找达希"}}},fp="5,146,26.320.0,25.334.0,13.185.0,47.142.0,43.102.0,25.117.0"}
P.entries["npc:dark-cleric-beryl"] = {n="黑暗牧师贝里尔",s="在布瑞尔，黑暗牧师贝里尔在阴影中指引刚刚苏醒的亡灵牧师。他驻守在恐惧之末旅店，传授暗影魔法，帮助他们适应效命于黑暗女王的不洁生活。",h="在布瑞尔，黑暗牧师贝里尔在阴影中指引刚刚苏醒的亡灵牧师。他驻守在恐惧之末旅店，传授暗影魔法，帮助他们适应效命于黑暗女王的不洁生活。",kw={"贝里尔","布瑞尔","黑暗牧师贝里尔","被遗忘者牧师","恐惧之末旅店","牧师训练师","提瑞斯法林地"},ang={["class:Priest"]="作为提瑞斯法林地的一名被遗忘者牧师，你可以向布瑞尔的贝里尔寻求指引，学习暗影魔法，走过通往不洁力量的艰难历程。",["race:Undead"]="作为一名亡灵，你可以从贝里尔身上看到被遗忘者如何适应受诅咒的处境，抛弃洛丹伦昔日信仰中的盲目虔诚，以务实的态度和暗影中的坚韧应对一切。"},sec={{t="暗影中的引路人",b="黑暗牧师贝里尔在布瑞尔的恐惧之末旅店楼上指导新晋的被遗忘者牧师。他教导他们，牧师的力量源于黑暗与暗影，但要掌控黑暗，也必须了解光明。在他的指引下，刚刚复生的牧师将精力转向暗影与黑暗法术。他们最初的试炼包括制作自己的黑暗之衣，并证明自己献身于这条新道路的决心。"}},faq={{q="黑暗牧师贝里尔是谁？",a="黑暗牧师贝里尔在布瑞尔的恐惧之末旅店楼上训练被遗忘者牧师。他帮助刚刚复生的亡灵牧师精进法术，拥抱暗影。",al={"贝里尔的职责","贝里尔是谁","牧师贝里尔的故事"}},{q="在哪里可以找到黑暗牧师贝里尔？",a="黑暗牧师贝里尔就在提瑞斯法林地布瑞尔的恐惧之末旅店楼上。",al={"贝里尔的位置","贝里尔在哪里","寻找黑暗牧师贝里尔"}},{q="为什么被遗忘者牧师使用黑暗牧师这一称号？",a="抛弃圣光传统教义，或将其与更黑暗的修行相平衡的被遗忘者牧师，会采用黑暗牧师这一称号。他们的教团认为，被遗忘者在腐化中铸就，黑暗就是他们的归宿。牧师必须学会审慎地运用光明与黑暗。",al={"什么是黑暗牧师","被遗忘者黑暗牧师","为何称为黑暗牧师"}},{q="贝里尔提供哪些任务？",a="贝里尔指导被遗忘者牧师的早期训练，包括黑暗的恩赐和黑暗之衣。这些任务教导年轻的侍僧援助盟友，并穿上适合暗影之道的法衣。",al={"贝里尔的任务","黑暗牧师贝里尔的任务"}}},fp="17,179,22.394.0,25.158.0,35.90.0,50.305.0,29.185.0"}
P.entries["npc:dark-iron-ambassador"] = {n="黑铁大师",s="在诺莫瑞根深处，黑铁大师作为氏族的使者，穿行于残破的大厅之间。氏族为何来到这座沦陷的侏儒都城，至今仍不清楚。",h="在诺莫瑞根深处，黑铁大师作为氏族的使者，穿行于残破的大厅之间。氏族为何来到这座沦陷的侏儒都城，至今仍不清楚。",kw={"阴谋","黑铁大师","黑铁氏族","诺莫瑞根","超级装置","索瑞森","瑟玛普拉格"},ang={["faction:Alliance"]="作为联盟的一员，你有理由调查黑铁在诺莫瑞根的活动。",["race:Dwarf"]="作为矮人，你或许会看到，这名身处侏儒城市废墟中的黑铁矮人引起了铁炉堡盟友的注意。",["race:Gnome"]="作为侏儒，你或许会对诺莫瑞根中的黑铁使者感到不安。他的出现给侏儒调查者带来了疑问。"},sec={{t="暗中的使者",b="在诺莫瑞根遭受辐射的大厅中，黑铁大师代表着自己的氏族。他此行的目的无人知晓。"},{t="深处的阴谋",b="调查者和地精怀疑，黑铁矮人与诺莫瑞根的困境及其神秘的超级钻探机有关。目前，这些怀疑仍只是推测。大师的出现并不能证明是谁导致了这座城市的沦陷，也不能证明双方是否达成过任何协议，以及协议的具体条款。"}},faq={{q="黑铁大师是谁？",a="黑铁大师是驻留在诺莫瑞根的氏族使者。他具体肩负着什么外交使命，无人知晓。",al={"这个矮人是谁","黑铁大师身份","黑铁大师是什么"}},{q="为什么诺莫瑞根里会有一名黑铁矮人？",a="他的目的尚不明确。他的出现表明，黑铁氏族对诺莫瑞根有所关注。",al={"黑铁矮人为何在诺莫瑞根","他在这里做什么","黑铁矮人的目的"}},{q="黑铁矮人是否参与导致了诺莫瑞根的沦陷？",a="无人知晓。调查者怀疑黑铁矮人，但他们的推测并不能证明是谁造成了这场灾难。",al={"黑铁矮人是否导致穴居人入侵","黑铁阴谋","索瑞森是否帮助了瑟玛普拉格"}},{q="这位大师来自哪里？",a="他隶属于由达格兰皇帝统治的黑铁氏族。",al={"大师来自哪里","谁派他来的","他为谁效力"}},{q="他与麦克尼尔·瑟玛普拉格是盟友吗？",a="有人怀疑双方结成了同盟，但仅凭他的出现，无法证实双方达成过任何协议。",al={"瑟玛普拉格的黑铁盟友","他与瑟玛普拉格是一伙的吗","与瑟玛普拉格合作"}},{q="在哪里可以找到黑铁大师？",a="黑铁大师行踪难觅，只有在诺莫瑞根受污染的工程区域和车间走廊中，才有机会偶然遇见他。",al={"大师刷新位置","他在哪里刷新","大师在诺莫瑞根的位置"}}},fx={["694fcc25"]={q="黑铁大师效忠哪一方？",a="他隶属于黑铁氏族。",al={"黑铁大师 阵营","大使为谁效力","黑铁大师 效忠对象"}},e7a948f2={q="黑铁大师想要什么？",a="他在诺莫瑞根的具体任务和目标尚不为人所知。",al={"黑铁大师 目标","黑铁为什么来到诺莫瑞根","黑铁大师 动机"}},["388c8a07"]={q="黑铁大师与谁有关联？",a="他代表黑铁氏族。有人怀疑他与麦克尼尔·瑟玛普拉格存在联系，但这种联系的性质尚未得到证实。",al={"黑铁大师 关联","大使听命于谁","黑铁大师 皇帝"}}},fp="20,165,15.120.0,24.273.1,32.113.0,43.92.0,53.108.0,36.69.0,40.71.0,44.129.0"}
P.entries["npc:darkmaster-gandling"] = {n="黑暗院长加丁",s="黑暗院长加丁是通灵学院的凡人院长，负责为诅咒神教教导和训练死灵法师。他在凯尔达隆城堡废墟的深处，为天灾军团效力，策划对生者与死者进行骇人的魔法实验。",h="黑暗院长加丁是通灵学院的凡人院长，负责为诅咒神教教导和训练死灵法师。他在凯尔达隆城堡废墟的深处，为天灾军团效力，策划对生者与死者进行骇人的魔法实验。",kw={"凯尔达隆","诅咒教派","黑暗院长加丁","加丁","院长","死灵法师","通灵学院"},ang={["class:Mage"]="加丁体现了达拉然学术传统的极度腐化，将严谨的治学精神扭曲成了一座制造亡灵的恐怖工厂。",["race:Undead"]="对被遗忘者而言，加丁是令人憎恨的Scourge教化监督者，他在凯尔达隆地下束缚自由的灵魂，使其遭受永恒的奴役。"},sec={{t="院长的领地",b="在凯尔达隆地下的幽暗厅堂中，黑暗院长加丁掌管着通灵学院，这里是天灾军团培养死灵法师的顶尖学府。加丁是一名为诅咒神教效力的活人，他曾与巫妖莱斯·霜语一同策划暴行，残害无数从周边地区掳来的无辜俘虏。进入他课堂的学生会学习调制瘟疫、复活死者和血肉塑形。"},{t="圣物匣之主",b="加丁居于院长的书房深处，掌控着这座古老学院中的黑暗圣物和被囚禁的灵魂。他将毁灭性的奥术与暗影魔法同禁忌的死灵法术相结合，诅咒入侵者，并将他们抛入暗影传送门，送进书房周围的密闭房间。他们必须在那里独自对抗复生的亡者，而加丁则保护着自己，免受伤害。"}},faq={{q="黑暗院长加丁是谁？",a="黑暗院长加丁是一名隶属于诅咒神教的人类死灵法师。他担任通灵学院的院长，管理这所黑暗学府，并训练新的死灵法师为巫妖王效力。",al={"加丁是谁","黑暗院长加丁背景故事","通灵学院首领"}},{q="加丁是亡灵，还是活着的人类？",a="尽管精通死亡魔法并效忠于天灾军团，加丁仍是一个活着的人类凡人。他在通灵学院中领导着凡人侍僧和教徒，心甘情愿地为天灾军团效力。",al={"加丁是亡灵吗","加丁还活着吗","加丁种族"}},{q="他与莱斯·霜语有什么关系？",a="莱斯·霜语曾是加丁的老师。这位人类院长与那位强大的巫妖共同主持通灵学院的黑暗教学，并监督着凯尔达隆内针对萨克霍夫夫妇等无辜者的恐怖暴行。",al={"霜语 加丁","莱斯·霜语 老师"}},{q="黑暗院长加丁在哪里？",a="加丁居于通灵学院最底层的院长的书房，穿过达隆米尔湖中凯尔达隆地下的墓穴便可抵达。",al={"加丁位置","加丁在哪里","如何找到加丁"}}},fp="19,176,23.375.0,23.345.0,27.131.0,40.147.0,43.206.0,35.137.0"}
P.entries["npc:darn-talongrip"] = {n="达恩·鹰爪",s="达恩·鹰爪在玛拉卡金附近守望着石爪山脉的边境。这名兽人斥候追踪险峻山岩间的威胁，并在前沿哨站与部落指挥官之间传递消息。",h="达恩·鹰爪在玛拉卡金附近守望着石爪山脉的边境。这名兽人斥候追踪险峻山岩间的威胁，并在前沿哨站与部落指挥官之间传递消息。",kw={"达恩·鹰爪","卡德拉克","玛拉卡金","兽人斥候","石爪山脉"},ang={["faction:Horde"]="达恩·鹰爪守望着通往石爪山脉的上山道路，为刚从贫瘠之地抵达的部落冒险者提供联络。",["race:Orc"]="身为兽人，你熟悉这片严酷的边境，达恩就在嶙峋怪石与凶猛野兽之间守望。"},sec={{t="石爪山脉的边境斥候",b="达恩·鹰爪监视着从贫瘠之地南部通往石爪山脉的崎岖山路。在玛拉卡金，他指引新兵前往部落在灰谷开辟的新战线。攀登这些争夺中的山峰时，旅人可以通过他的哨所与部落取得联系。"},{t="指挥官的耳目",b="达恩从玛拉卡金向指挥官们传递前线的消息和报告，其中就有驻守在贫瘠之地北部瞭望塔的卡德拉克。散布在山间的营地始终面临压力，而达恩身兼哨兵与信使，让部落先锋部队随时掌握情况。"}},faq={{q="达恩·鹰爪是谁？",a="达恩·鹰爪以石爪山脉南部的玛拉卡金为据点，为部落执行侦察任务。",al={"达恩·鹰爪是谁","达恩·鹰爪身份","这个兽人是谁"}},{q="在哪里可以找到达恩·鹰爪？",a="在石爪山脉的巨魔聚落玛拉卡金可以找到达恩·鹰爪。",al={"达恩·鹰爪位置","达恩·鹰爪在哪里","达恩·鹰爪坐标"}},{q="他在石爪山脉承担什么职责？",a="达恩指引新兵前往贫瘠之地北部，向卡德拉克报到，协助保卫部落在灰谷的哨站。",al={"达恩·鹰爪做什么","达恩·鹰爪职责"}},{q="卡德拉克是谁，达恩为什么派旅人去找他？",a="卡德拉克在贫瘠之地北部的瞭望塔指挥部落军队，领导部落在灰谷的战事。达恩派新兵前去向他报到，协助保卫部落在灰谷开辟的新战线。",al={"卡德拉克是谁","向卡德拉克报到"}}},fp="14,168,28.244.0,20.268.0,22.89.0,34.95.0,31.105.0,55.183.0"}
P.entries["npc:darsok-swiftdagger"] = {n="达索克·快刀",s="达索克·快刀在十字路口监视着北方道路上的威胁。这名兽人斥候指引部落战士对抗无水岭的巫翼鹰身人，她们的袭击危及旅人和定居点。他也是玛拉卡金的巫医金吉尔的老朋友。",h="达索克·快刀在十字路口监视着北方道路上的威胁。这名兽人斥候指引部落战士对抗无水岭的巫翼鹰身人，她们的袭击危及旅人和定居点。他也是玛拉卡金的巫医金吉尔的老朋友。",kw={"贫瘠之地","血羽","十字路口","达索克","鹰身人","金吉尔","塞瑞娜","快刀","索克","巫翼"},ang={["class:Rogue"]="身为潜行者，你能看出达索克偏好对敌方首领发动精准而致命的打击，取下他们的首级。",["faction:Horde"]="身为部落旅人，你可以通过达索克早期布置的战术任务，帮助保护十字路口的商路，抵御来自空中的袭击。",["race:Orc"]="身为兽人，你能看到达索克如何专注于运用武力，守卫卡利姆多危机四伏的边疆。"},sec={{t="十字路口的守望者",b="达索克·快刀从十字路口监视着北方的灌木荒地。连接杜隆塔尔、莫高雷和贫瘠之地北部的道路面临着劫掠者、半人马，以及从空中成群来袭的猎手。达索克的怒火指向巫翼鹰身人。她们栖息在遗忘之池西北方的无水岭，威胁着向北行进的商队。"},{t="对巫翼的战事",b="达索克指挥战士攻入巫翼的领地，首先对付鹰身强盗。随后，他派出老练的战士对付鹰身人的副官，最后则是她们的族母塞瑞娜·血羽。他试图逐步瓦解她们的指挥体系，让这群鹰身人溃散在峭壁之间。"},{t="荒野中的故交",b="达索克有一位老朋友，远在贫瘠之地的西北方：巫医金吉尔，一名住在石爪山脉玛拉卡金的巨魔，鹰身人正是来自那片土地。达索克给金吉尔捎去一封信，讲述对抗鹰身人的战况。这两位朋友已经多年没有联系了。"}},faq={{q="达索克·快刀在哪里？",a="达索克·快刀驻守在十字路口，这里是贫瘠之地中部的部落定居点。他指引旅人前去应对北方的威胁。",al={"达索克位置","达索克·快刀在哪里","寻找达索克","达索克·快刀所在地点"}},{q="达索克为什么要猎杀鹰身人？",a="巫翼鹰身人栖息在遗忘之池西北方的峡谷中，威胁着贫瘠之地北方道路上的部落商队、旅人和斥候。",al={"为什么杀鹰身人","达索克与鹰身人的仇怨","贫瘠之地巫翼鹰身人"}},{q="塞瑞娜·血羽是谁？",a="塞瑞娜·血羽统领着无水岭的巫翼鹰身人。达索克派出战士杀死她，瓦解这群鹰身人的指挥体系。",al={"塞瑞娜·血羽","贫瘠之地鹰身人首领","巫翼首领"}},{q="达索克与巫医金吉尔有什么关系？",a="巫医金吉尔是一名住在石爪山脉玛拉卡金的巨魔，也是达索克的老朋友。达索克派一名旅人给金吉尔送去一封讲述对抗鹰身人战况的信，这是他多年来首次向这位朋友传递消息。",al={"金吉尔的信","达索克与金吉尔","与巫医金吉尔的关系"}},{q="达索克听命于瑟格拉·黑棘还是索克？",a="达索克在十字路口组织对抗鹰身人的行动。没有任何经典旧世资料表明瑟格拉·黑棘或索克是他的直属上级。",al={"达索克与索克","达索克听命于谁","十字路口的领导者"}},{q="巫翼鹰身人在哪里筑巢？",a="巫翼鹰身人栖息在无水岭，那里位于贫瘠之地北部、遗忘之池的西北方，遍布险峻的峡谷和悬崖。",al={"巫翼位置","无水岭鹰身人","贫瘠之地哪里有鹰身人"}}},fp="18,266,27.381.0,24.303.1,24.295.0,36.144.0,30.155.0,27.132.0,52.215.0,48.149.0,36.103.0"}
P.entries["npc:daryl-the-youngling"] = {n="年轻的达瑞尔",s="在旅行者营地，年轻的达瑞尔以洛克莫丹的野兽为目标，考验旅人的枪法。这位年轻的人类猎人希望在经验老到的矮人追踪者中赢得一席之地。",h="在旅行者营地，年轻的达瑞尔以洛克莫丹的野兽为目标，考验旅人的枪法。这位年轻的人类猎人希望在经验老到的矮人追踪者中赢得一席之地。",kw={"猎杀野猪","达瑞尔","旅行者营地","猎人","猎人的自豪","洛克莫丹","年轻的"},ang={["class:Hunter"]="达瑞尔的竞赛考验着那些来到旅行者营地的游历猎人的追踪本领、对野兽习性的了解，以及狩猎技巧。",["race:Human"]="作为人类，你能在矮人领地深处找到一位正在学习野外生存技艺的年轻人。共同历练结下的情谊将铁炉堡与人类诸王国联系在一起。"},sec={{t="巡山人中的人类",b="矮人巡山人、追踪者和老练的野外行家从旅行者营地守望着洛克莫丹的荒野。达瑞尔在这里与旅人较量，检验自己的狩猎直觉。他向他们发起挑战，要他们猎杀游荡在峭壁和湖岸边的凶悍野猪及其他野兽。"}},faq={{q="年轻的达瑞尔是谁？",a="达瑞尔是洛克莫丹旅行者营地的一位年轻人类猎人。在营地那些老练的矮人神枪手之间，他向初来乍到的人发起挑战，考验他们的狩猎和追踪技巧。",al={"达瑞尔是谁","达瑞尔的故事","年轻的达瑞尔是谁"}},{q="在哪里能找到达瑞尔？",a="达瑞尔待在旅行者营地，那里位于洛克莫丹东南岸上方林木茂密的峭壁上。",al={"达瑞尔的位置","年轻的达瑞尔在哪里","哪里能找到达瑞尔"}},{q="他为什么被称为“年轻的”？",a="营地里的矮人神枪手和常客已经在卡兹莫丹崎岖的偏远荒野巡逻了数十年。与他们相比，达瑞尔年轻且未经考验，仍在努力为自己赢得长久的猎人声誉。",al={"为什么叫年轻的","达瑞尔的绰号"}}},fx={e75652fe={q="年轻的达瑞尔效忠哪一方？",a="达瑞尔站在联盟一方，在洛克莫丹的矮人射手之间扎营。他驻扎在旅行者营地，与其他巡山人和野外生存者一道，守护这一地区的荒野。",al={"达瑞尔阵营","达瑞尔是否属于联盟","达瑞尔为谁效力"}},a39b90d4={q="年轻的达瑞尔想要什么？",a="达瑞尔渴望证明自己的箭术和野外生存本领。他寻找能干的冒险者，让他们以洛克莫丹当地的野生动物为目标，检验追踪和狩猎的本领，尽享追逐的刺激与狩猎的挑战。",al={"达瑞尔想要什么","达瑞尔的目标","达瑞尔的任务"}},f7496387={q="年轻的达瑞尔为什么在旅行者营地？",a="旅行者营地是这片山谷中最优秀的追踪者和猎兽人的栖身之所。达瑞尔在此与经验丰富的矮人神射手一同磨炼技艺，利用洛克莫丹山间丰富的猎物练习狩猎。",al={"达瑞尔为何在这里","达瑞尔为何在洛克莫丹","年轻的达瑞尔旅行者营地"}},d22cfcb5={q="年轻的达瑞尔与谁有联系？",a="达瑞尔与旅行者营地的猎人和营地管理者为伴，其中包括维林·疾风。他与他们一样热衷于狩猎，并协助他们管控在矮人哨站附近游荡的野兽。",al={"达瑞尔的盟友","达瑞尔旅行者营地","达瑞尔与谁为伴"}}},fp="19,178,26.266.0,27.176.0,25.91.0,33.193.0"}
P.entries["npc:dashel-stonefist"] = {n="达舍尔·石拳",s="在旧城区，达舍尔·石拳因脾气暴躁、拳头凶狠，以及危险的人脉而引人注目。这个绰号拳头的矮人常在暴风城治安较差的小巷出没，秘密调查员正在那里监视他。",h="在旧城区，达舍尔·石拳因脾气暴躁、拳头凶狠，以及危险的人脉而引人注目。这个绰号拳头的矮人常在暴风城治安较差的小巷出没，秘密调查员正在那里监视他。",kw={"斗殴者","达舍尔","迪菲亚潜行者","拳头","失踪的外交官","旧城区","石拳","暴风城"},ang={["class:Rogue"]="对穿行于旧城区犯罪网络中的潜行者来说，达舍尔·石拳表明，密探挨上几拳后也会口无遮拦。把机密托付给只会逞凶斗狠的人，实在不是明智的赌注。",["faction:Alliance"]="达舍尔·石拳揭露了暴风城这座首都内部悄然滋生的腐败。迪菲亚潜行者的势力已越过西部荒野的农场，伸入王国都城。",["race:Dwarf"]="许多在暴风城生活的铁炉堡矮人都是受人敬重的铁匠、巡山人或使节。石拳表明，矮人也可能沦为街头恶棍，犯下叛国罪行。"},sec={{t="旧城区的斗殴者",b="旧城区的人都叫达舍尔·石拳拳头，这个绰号是他在街头斗殴中挣来的。在当地居民和城市卫兵眼中，他是个酗酒好斗的矮人，动不动就在酒馆外挥拳打人。他在这片街区混迹，与暴风城的地下势力来往密切。走私者、扒手和政治煽动者在这里交易钱财与传闻，避开教堂广场的耳目。"},{t="外交官失踪",b="一名外交官失踪，令王室的秘密调查员找上了达舍尔·石拳。有关叛国阴谋的传闻指向这个矮人，他是迪菲亚潜行者在暴风城内的街头联络人。他知道绑架的内情，却拒绝开口，直到调查员将他打服。他透露的事情深入王国政局，远非一桩简单的绑架案。"}},faq={{q="达舍尔·石拳是谁？",a="在暴风城的旧城区，达舍尔·石拳在首都的阴暗街区充当打手和线人。这个绰号拳头的矮人以凶暴闻名，时常与人斗殴。",al={"达舍尔是谁","拳头是谁","达舍尔·石拳背景故事"}},{q="在哪里能找到达舍尔·石拳？",a="你可以在旧城区的户外找到达舍尔·石拳，他就在城中潜行者和战士常去之处附近的后巷里。",al={"达舍尔位置","达舍尔·石拳在哪里","寻找达舍尔"}},{q="调查员为什么需要与他交手？",a="追查失踪的王室外交官时，线索将调查员引向了身为同谋的达舍尔·石拳。他对那些见不得光的雇主极为忠诚，只有在赤手空拳的斗殴中被打服，才会吐露所知的内情。",al={"为什么攻击达舍尔","制服达舍尔·石拳","与达舍尔战斗"}},{q="他与迪菲亚潜行者有什么关系？",a="达舍尔·石拳在暴风城内充当迪菲亚潜行者的密探和信使。他协调当地的联络人和街头打手，向城市卫兵隐瞒迪菲亚潜行者的计划。",al={"达舍尔是迪菲亚潜行者吗","达舍尔·石拳与迪菲亚潜行者","暴风城内的迪菲亚潜行者"}},{q="与达舍尔有关的失踪外交官是谁？",a="王室密探正在追查一名未具名外交官的下落，此人在前往塞拉摩的途中失踪。",al={"失踪的外交官是谁","失踪外交官任务线","瓦里安国王失踪"}},{q="达舍尔与其他知名矮人有亲属关系吗？",a="没有关于达舍尔·石拳亲属的记载。他在暴风城的犯罪关系，使他与正派的矮人社会格格不入。",al={"特尔达·石拳亲属","达舍尔·石拳家族","石拳家族"}}},fx={["06e53778"]={q="达舍尔·石拳效忠哪一方？",a="达舍尔·石拳游走在旧城区的地下犯罪与公然叛国之间，处境危险。他在城中巷道里伪装成普通的粗野打手，暗中却效忠迪菲亚潜行者，在暴风城卫兵眼皮底下传递情报，协助协调他们的颠覆活动。",al={"达舍尔·石拳阵营","达舍尔为谁效力","达舍尔是否属于迪菲亚潜行者"}},["388c2391"]={q="达舍尔·石拳为什么在旧城区？",a="达舍尔留在旧城区，是因为这里拥挤而阴暗的街道为非法勾当提供了理想的掩护。旧城区远离教堂广场和王室宫廷严整的监管，使他得以与暗中的密谋者保持联系，安排后巷交易，并掌握城内动向，而不至于过早引起当局的注意。",al={"达舍尔为何在暴风城","达舍尔·石拳在此的原因","达舍尔在旧城区做什么"}},["329088a4"]={q="达舍尔·石拳为什么被称为拳头？",a="旧城区的居民和恶棍都只称达舍尔为“拳头”，这个绰号源于他臭名昭著的暴脾气，以及动辄以暴力解决争端的作风。他因在后巷斗殴时手段凶狠而令人畏惧，大多数市民和扒手在招惹他或打探他的事情之前，都得再三掂量。",al={"达舍尔为何被称为拳头","达舍尔·石拳的绰号","达舍尔的名声"}}},fp="16,209,21.350.0,28.373.1,24.188.0,34.114.0,39.225.1,49.201.1,48.88.2,45.123.0"}
P.entries["npc:david-trias"] = {n="大卫·提亚斯",s="在丧钟镇，大卫·提亚斯训练刚刚苏醒的被遗忘者。他传授潜行与用刃之术，让他们为希尔瓦娜斯女王和被遗忘者效力。",h="在丧钟镇，大卫·提亚斯训练刚刚苏醒的被遗忘者。他传授潜行与用刃之术，让他们为希尔瓦娜斯女王和被遗忘者效力。",kw={"大卫·提亚斯","丧钟镇","埃林·提亚斯","密文卷轴","被遗忘者","潜行者训练师","提瑞斯法林地"},ang={["class:Rogue"]="作为一名被遗忘者潜行者，大卫·提亚斯是你的第一位导师。他帮助你解读秘密卷轴，教你以亡灵特有的冰冷与精准挥动利刃。",["race:Undead"]="身为亡灵，你深知被遗忘者残酷的现实：你曾是洛丹伦的人类，但瘟疫斩断了你与前世及血脉的联系。如今，你为Sylvanas女王效力。"},sec={{t="暗影中的引路人",b="大卫·提亚斯在丧钟镇的墓碑与废墟之间训练新近复生的亡灵。他寻找那些擅长无声杀戮的人。对初生的被遗忘者而言，生存不仅需要武力，还需要从黑暗中发动精准的打击。提亚斯解读命令，教导新学徒使用匕首、隐匿行踪，并运用复生后的反应能力，对活人和天灾军团施以精准致命的攻击。"},{t="熟悉的姓氏",b="大卫·提亚斯与暴风城著名的奶酪商人埃林·提亚斯有着相同的姓氏。埃林暗中与潜行者大师和间谍首领保持着密切联系。大卫与埃林之间是否存在亲属关系，尚未得到证实。"}},faq={{q="大卫·提亚斯是谁？",a="大卫·提亚斯在提瑞斯法林地的丧钟镇训练刚刚苏醒的被遗忘者潜行者。他传授他们最初的战斗技巧，并交付他们最初的秘密任务。",al={"大卫·提亚斯","大卫·提亚斯是谁","潜行者训练师 丧钟镇"}},{q="在哪里可以找到大卫·提亚斯？",a="在提瑞斯法林地的被遗忘者新手村丧钟镇，可以找到大卫·提亚斯。他站在村中的建筑附近，帮助新近复生的亡灵。",al={"大卫·提亚斯位置","大卫·提亚斯在哪里","丧钟镇潜行者训练师"}},{q="大卫·提亚斯与暴风城的埃林·提亚斯有亲属关系吗？",a="大卫·提亚斯与暴风城的埃林·提亚斯有着相同的姓氏，但两人之间是否存在亲属关系，尚未得到证实。",al={"埃林·提亚斯亲属关系","提亚斯家族","他与埃林·提亚斯有亲属关系吗"}},{q="他在被遗忘者的训练中承担什么职责？",a="从丧钟镇墓穴中新近复生的潜行者，会将一份密文卷轴带给大卫·提亚斯。他解读给他们的指令，传授最初的技能，并引导他们为被遗忘者执行秘密任务。",al={"大卫·提亚斯任务","密文卷轴","他传授什么"}}},fp="11,160,24.422.0,15.219.1,19.172.0,29.155.0,52.101.0,44.197.0"}
P.entries["npc:dawnwatcher-selgorm"] = {n="哨兵塞尔高姆",s="在达纳苏斯的工匠区，哨兵塞尔高姆密切留意着卡利姆多北部的威胁。这名人类在暗夜精灵的都城担任银色黎明的观察员与联络人，追查有关隐秘教派活动和附近黑暗力量蠢动的报告。",h="在达纳苏斯的工匠区，哨兵塞尔高姆密切留意着卡利姆多北部的威胁。这名人类在暗夜精灵的都城担任银色黎明的观察员与联络人，追查有关隐秘教派活动和附近黑暗力量蠢动的报告。",kw={"银色黎明","黑暗深渊","黑暗深渊中的邪恶","工匠区","达纳苏斯","哨兵塞尔高姆","暮光之锤"},ang={["faction:Alliance"]="作为探索卡利姆多北部的联盟冒险者，你可以通过塞尔高姆，将达纳苏斯与沿海对抗邪恶教派的战斗联系起来。",["race:Human"]="作为一名穿行于泰达希尔偏远枝干间的人类，你或许会遇见一位为银色黎明效力的同胞。"},sec={{t="世界之树中的耳目",b="哨兵塞尔高姆为银色黎明驻守达纳苏斯。这个组织在东瘟疫之地对抗亡灵天灾军团的同时，也未曾放松对其他地方的警惕。塞尔高姆在工匠区收集有关卡利姆多荒野中新兴威胁的报告。他将暗夜精灵与各地对抗古老邪恶的行动联系起来，并寻找能够打击教徒和黑暗力量的联盟旅人，力求在这些势力蔓延之前将其遏制。"},{t="出击黑暗",b="位于灰谷佐拉姆海岸地下的黑暗深渊引起了塞尔高姆的注意。暮光之锤教派和蛇形的纳迦聚集在这片被水淹没的废墟中。塞尔高姆会奖赏深入其中的老练勇士，让他们铲除教派首领，夺回受污染的遗物，希望借此平息威胁卡利姆多神圣海岸的阴影。"}},faq={{q="哨兵塞尔高姆是谁？",a="哨兵塞尔高姆是银色黎明的一名人类成员，驻扎在达纳苏斯，监视卡利姆多各地逐渐逼近的邪恶。",al={"塞尔高姆","塞尔高姆是谁","哨兵塞尔高姆背景故事"}},{q="在哪里可以找到哨兵塞尔高姆？",a="哨兵塞尔高姆就在达纳苏斯工匠区的露天处，俯瞰着这座暗夜精灵都城的工坊。",al={"塞尔高姆位置","塞尔高姆在哪里","塞尔高姆达纳苏斯"}},{q="为什么银色黎明的成员会驻扎在达纳苏斯？",a="银色黎明在洛丹伦对抗天灾军团，也力求根除各地的邪恶。在达纳苏斯，塞尔高姆监视着日益频繁的教派活动，其中就包括卡利姆多北部的暮光之锤。",al={"达纳苏斯的银色黎明","银色黎明为什么在这里"}},{q="塞尔高姆请冒险者做些什么？",a="塞尔高姆等待着联盟英雄从灰谷的黑暗深渊归来，带回那里暮光之锤首领梦游者克尔里斯的头颅。受伤的银月守卫塞尔瑞德敦促他们杀死克尔里斯，阻止教派的腐化蔓延。",al={"塞尔高姆任务","黑暗深渊中的邪恶任务发布者"}}},fp="19,262,22.426.0,25.334.1,27.124.0,39.131.0,52.196.0,40.257.0"}
P.entries["npc:dawnwatcher-shaedlass"] = {n="哨兵山德拉斯",s="在达纳苏斯，哨兵山德拉斯为银色黎明监视着卡利姆多各地的动向。他驻守在工匠区，打听被派往敌境侦察的同僚们的消息。",h="在达纳苏斯，哨兵山德拉斯为银色黎明监视着卡利姆多各地的动向。他驻守在工匠区，打听被派往敌境侦察的同僚们的消息。",kw={"银色黎明","黑暗深渊","工匠区","达纳苏斯","哨兵","山德拉斯","塞尔瑞德"},ang={["faction:Alliance"]="对于达纳苏斯的联盟英雄而言，山德拉斯为他们指明了探寻黑暗深渊奥秘的道路，并派遣斥候去救回一名深入敌后的特工。",["race:NightElf"]="作为一名公开为银色黎明效力的暗夜精灵，山德拉斯将泰达希尔封闭的政治事务与银色黎明在世界各地对黑暗势力的警戒联系起来。"},sec={{t="银色黎明的耳目",b="银色黎明在东瘟疫之地对抗天灾军团，但其监视范围远不止洛丹伦。哨兵山德拉斯驻守在暗夜精灵的首都达纳苏斯，照看银色黎明在卡利姆多的事务。在工匠区的哨位上，他密切关注针对黑暗教派与腐化势力的秘密行动，这些势力威胁着更广阔的世界。"},{t="失踪的同袍",b="银月守卫塞尔瑞德南下前往灰谷沿岸的黑暗深渊调查教派活动，此后便失去了踪迹。山德拉斯担心，他的战友可能遭到了暮光之锤或那座古老精灵神庙中水生恐怖生物的毒手。他召集勇敢的联盟冒险者进入废墟，查明这名斥候的下落。"}},faq={{q="哨兵山德拉斯是谁？",a="哨兵山德拉斯是银色黎明的一名暗夜精灵特工，驻守在达纳苏斯的工匠区。他负责联络银色黎明与其在卡利姆多北部的行动力量。",al={"山德拉斯是谁","哨兵山德拉斯背景故事","银色黎明 达纳苏斯 非玩家角色"}},{q="为什么达纳苏斯会有银色黎明的成员？",a="银色黎明在洛丹伦对抗天灾军团，同时在艾泽拉斯各地警戒带来腐化的邪恶势力。在卡利姆多，山德拉斯追查着隐秘教派等威胁。",al={"银色黎明为何在达纳苏斯","银色黎明 暗夜精灵"}},{q="山德拉斯请冒险者做什么？",a="山德拉斯派联盟冒险者进入黑暗深渊中沉没的神庙，寻找银月守卫塞尔瑞德。塞尔瑞德秘密潜入调查暮光之锤，却一直没有传回消息。",al={"山德拉斯任务","寻找塞尔瑞德任务"}},{q="在哪里可以找到哨兵山德拉斯？",a="哨兵山德拉斯位于达纳苏斯的工匠区，就在这座首都的商贩和工匠附近。",al={"山德拉斯位置","哨兵山德拉斯在哪里"}}},fp="21,174,23.322.0,17.339.1,29.148.0,42.161.0,42.200.0,39.113.0"}
P.entries["npc:dazalar"] = {n="达扎拉",s="达扎拉在多兰纳尔训练年轻的暗夜精灵猎人，让他们为踏入泰达希尔的荒野做好准备。他教他们精准射击，并与巨树枝桠间的野兽建立羁绊。",h="达扎拉在多兰纳尔训练年轻的暗夜精灵猎人，让他们为踏入泰达希尔的荒野做好准备。他教他们精准射击，并与巨树枝桠间的野兽建立羁绊。",kw={"达扎拉","多兰纳尔","猎人","暗夜精灵","驯服野兽","泰达希尔","猎人之道","训练师"},ang={["class:Hunter"]="作为猎人，你会在达扎拉的引导下，完成掌握野兽控制和照料动物伙伴的最初试炼。",["race:NightElf"]="作为暗夜精灵，你会学习 Kaldorei 哨兵和斥候的传统，以及如何与自然界凶猛的掠食者和谐共处。"},sec={{t="多兰纳尔营地",b="年轻猎人离开幽影谷后，便会在多兰纳尔接受达扎拉的训练。暗夜精灵游侠和哨兵在荒野中巡逻，而他则教导初来乍到的猎人掌握耐心与自律，以保护泰达希尔脆弱的生态。"},{t="与荒野缔结羁绊",b="达扎拉教猎人驯服和照料野兽。卡多雷 寻求与夜刃豹、猫头鹰和 巨翼猎枭 等森林掠食者缔结契约，以尊重而非强迫的方式训练它们，让它们与伙伴并肩作战。"}},faq={{q="达扎拉是谁？",a="达扎拉在多兰纳尔训练暗夜精灵猎人，传授战斗技巧和驯服野兽的方法。",al={"达扎拉是谁","达扎拉背景故事","达扎拉身份"}},{q="在哪里可以找到达扎拉？",a="离开幽影谷后不久，你就能在泰达希尔的中心聚居地多兰纳尔的户外找到达扎拉。",al={"达扎拉位置","达扎拉在哪里","多兰纳尔猎人训练师"}},{q="达扎拉提供哪些训练？",a="达扎拉传授远程攻击、陷阱和生存技巧。他还引导新手猎人完成试炼，掌握驯服野生动物的方法。",al={"达扎拉教什么","达扎拉技能","达扎拉猎人训练"}},{q="达扎拉提供特殊任务吗？",a="是的。达扎拉提供的猎人训练包括 猎人之道、多阶段试炼驯服野兽，以及训练野兽。这些训练教年轻猎人与动物伙伴建立羁绊，并照料它们。",al={"达扎拉任务","多兰纳尔猎人任务","驯服野兽 任务"}},{q="暗夜精灵为何如此倚重猎人？",a="数千年来，暗夜精灵一直与卡利姆多的古老森林和谐共处。弓箭手和斥候构成了哨兵部队的骨干，他们凭借潜行、射击技巧和动物盟友保护家园，同时避免扰乱自然。",al={"暗夜精灵猎人背景故事","哨兵为何倚重猎人","卡多雷 猎人"}},{q="达扎拉会让猎人驯服哪些野兽？",a="达扎拉指引猎人寻找泰达希尔的本土野兽，包括当地的蜘蛛、夜刃豹和猛禽。这些试炼考验他们接近并安抚野生掠食者的能力。",al={"驯服哪些野兽","多兰纳尔驯服试炼","泰达希尔驯服野兽"}}},fp="7,146,23.218.0,21.219.0,15.99.0,25.102.0,35.136.0,38.202.0,46.239.0,54.179.0"}
P.entries["npc:deathguard-bartholomew"] = {n="亡灵卫兵巴塞洛缪",s="在布瑞尔，亡灵卫兵巴塞洛缪守望着城镇，为旅人指路。他协助维持提瑞斯法林地的被遗忘者守军的秩序。",h="在布瑞尔，亡灵卫兵巴塞洛缪守望着城镇，为旅人指路。他协助维持提瑞斯法林地的被遗忘者守军的秩序。",kw={"巴塞洛缪","布瑞尔","亡灵卫兵","被遗忘者","卫兵","提瑞斯法"},ang={["faction:Horde"]="作为从卡利姆多远道而来的盟友，你可以向Bartholomew问路，穿行于布瑞尔雾气笼罩的街道。",["race:Undead"]="作为来自丧钟镇、刚刚重获自由的被遗忘者，你通过布瑞尔的Bartholomew等卫兵，初次接触到希尔瓦娜斯的常备军。"},sec={{t="布瑞尔的哨兵",b="亡灵卫兵巴塞洛缪驻守布瑞尔，是保卫提瑞斯法林地的被遗忘者卫兵之一。和其他亡灵卫兵一样，他保护着收复的土地，抵御残存的天灾军团、狂热的血色十字军成员，以及其他威胁希尔瓦娜斯领地的敌人。他也为旅人在镇中指路，并协助维持新近复生者之间的秩序。"}},faq={{q="亡灵卫兵巴塞洛缪是谁？",a="亡灵卫兵巴塞洛缪守卫着提瑞斯法林地的布瑞尔。他守望着城镇，引导旅人找到他们要去的地方。",al={"巴塞洛缪","巴塞洛缪是谁","亡灵卫兵巴塞洛缪背景故事"}},{q="亡灵卫兵的职责是什么？",a="亡灵卫兵是被遗忘者的主要步兵和防御部队。他们巡逻于洛丹伦，保卫布瑞尔等定居点，抵御天灾军团和血色十字军，并为黑暗女王维持秩序。",al={"亡灵卫兵是什么","亡灵卫兵阵营","被遗忘者卫兵"}},{q="亡灵卫兵巴塞洛缪能指路吗？",a="能。亡灵卫兵巴塞洛缪可以为旅人指明布瑞尔各处设施的位置，包括训练师、旅店和专业商人所在之处。",al={"旅店在哪","布瑞尔问路","布瑞尔卫兵指路"}}},fp="22,159,17.317.0,30.134.0,35.190.0,43.118.0"}
P.entries["npc:deathguard-burgess"] = {n="亡灵卫兵伯吉斯",s="在布瑞尔，亡灵卫兵伯吉斯为被遗忘者守卫着这座城镇。他守护着定居点，并为旅人指引所需服务的去处。",h="在布瑞尔，亡灵卫兵伯吉斯为被遗忘者守卫着这座城镇。他守护着定居点，并为旅人指引所需服务的去处。",kw={"布瑞尔","伯吉斯","亡灵卫兵伯吉斯","被遗忘者","卫兵","提瑞斯法林地"},ang={["faction:Horde"]="作为从卡利姆多来访的部落盟友，当你需要补给或想在旅店歇脚时，可以向伯吉斯询问布瑞尔各处的方向。",["race:Undead"]="作为刚刚苏醒、离开丧钟镇的被遗忘者，你可以向布瑞尔的伯吉斯等卫兵问路，初步熟悉洛丹伦。"},sec={{t="布瑞尔的守望者",b="在幽暗城以北，亡灵卫兵伯吉斯守卫着布瑞尔，抵御天灾军团和血色十字军。与提瑞斯法林地的其他亡灵卫兵一样，他为抵达此地的被遗忘者指引当地的工匠、职业训练师和公共服务设施的所在，帮助这座脆弱的前哨维持运转。"}},faq={{q="亡灵卫兵伯吉斯是谁？",a="亡灵卫兵伯吉斯为被遗忘者守卫着布瑞尔。他协助维持秩序，并为访客指引当地训练师和重要地点的所在。",al={"伯吉斯 布瑞尔","伯吉斯是谁","亡灵卫兵伯吉斯的故事"}},{q="亡灵卫兵在布瑞尔承担什么职责？",a="在布瑞尔，亡灵卫兵保护被遗忘者免受天灾军团和血色十字军的侵害，并维持治安。",al={"亡灵卫兵是什么","亡灵卫兵的职责"}},{q="亡灵卫兵伯吉斯能指路吗？",a="能。向伯吉斯询问，就能知道布瑞尔的职业训练师、当地旅店、专业技能大师和其他重要设施在哪里。",al={"伯吉斯指路","布瑞尔去哪里"}}},fp="18,141,19.272.0,26.132.0,44.112.0,42.125.0"}
P.entries["npc:deathguard-dillinger"] = {n="亡灵卫兵迪林格尔",s="在布瑞尔镇边，亡灵卫兵迪林格尔守望着小镇，为初来乍到的被遗忘者指路。他还派遣新兵对付威胁附近农场和磨坊的天灾军团残余。",h="在布瑞尔镇边，亡灵卫兵迪林格尔守望着小镇，为初来乍到的被遗忘者指路。他还派遣新兵对付威胁附近农场和磨坊的天灾军团残余。",kw={"腐烂的爪子","布瑞尔","亡灵卫兵","亡灵卫兵迪林格尔","迪林格尔","磨坊告急","提瑞斯法林地","“锋利的切肉刀”奥拉格"},ang={["class:Warrior"]="作为一名胸怀抱负的被遗忘者战士，你可能会与迪林格尔并肩作战，对付在布瑞尔外围游荡的食尸鬼和骷髅恐魔。",["faction:Horde"]="作为部落的盟友，你会看到被遗忘者为在洛丹伦北部站稳脚跟而奋战，以及威胁布瑞尔的无智Scourge。",["race:Undead"]="作为刚刚获得自由、从丧钟镇前来的被遗忘者，你遇到的第一位军方长官可能就是迪林格尔。他会指引你接受训练，并开始履行为Sylvanas效力的最初职责。"},sec={{t="布瑞尔的哨兵",b="亡灵卫兵迪林格尔守卫布瑞尔，并指引从丧钟镇前来的人。在小镇入口，他为刚刚苏醒的亡灵指明旅店、城镇大厅和当地训练师的位置。他们必须学会如何在黑暗女王的统治下适应改变后的生活。"},{t="保卫边境",b="亡灵卫兵迪林格尔派遣有能力的新兵，清除附近农场和磨坊中没有心智的天灾军团。他们消灭腐烂的食尸鬼，夺回被侵占的设施，为布瑞尔周边筑起更安全的边界，让新建的被遗忘者定居点能够抵御亡灵的威胁。"},{t="遏制无智恐魔",b="“锋利的切肉刀”奥拉格仍被封印在布瑞尔北面的一座陵墓中。当天灾军团席卷提瑞斯法时，被遗忘者俘获了奥拉格。这名天灾军团爪牙拥有独立的心智，却仍受巫妖王奴役。所有摆脱这种控制的尝试都失败了，于是迪林格尔派遣一位久经考验的勇士解除封印，消灭奥拉格。"}},faq={{q="在哪里可以找到亡灵卫兵迪林格尔？",a="亡灵卫兵迪林格尔守望着通往布瑞尔的道路，就在提瑞斯法林地中部的小镇外围。",al={"迪林格尔位置","迪林格尔在哪里","亡灵卫兵迪林格尔坐标"}},{q="亡灵卫兵的职责是什么？",a="亡灵卫兵是被遗忘者的常备军，也负责维持治安。他们守卫布瑞尔和幽暗城等定居点，抵御天灾军团、血色十字军以及当地的其他威胁。",al={"亡灵卫兵是什么","亡灵卫兵是谁","亡灵卫兵职责"}},{q="亡灵卫兵迪林格尔提供哪些任务？",a="迪林格尔派遣新兵消灭周围田野和磨坊中没有心智的天灾军团，夺回当地的基础设施，并迎战“锋利的切肉刀”奥拉格等危险敌人。",al={"迪林格尔任务","迪林格尔有哪些任务"}},{q="亡灵卫兵迪林格尔能指路吗？",a="能。迪林格尔可以为你指明布瑞尔各处主要服务设施、专业训练师和职业导师的位置。",al={"迪林格尔指路","向迪林格尔求助"}},{q="被遗忘者为什么要与布瑞尔附近的其他亡灵作战？",a="提瑞斯法那些没有心智的亡灵仍受天灾军团和巫妖王控制。被遗忘者已经摆脱了这种控制，必须消灭这些狂暴的残余，以保护自己的领地。",al={"为什么对抗天灾军团","亡灵与亡灵交战","布瑞尔食尸鬼"}},{q="“锋利的切肉刀”奥拉格是谁？",a="“锋利的切肉刀”奥拉格是一个危险的天灾军团恐魔，与布瑞尔附近的墓穴有关。迪林格尔派遣被遗忘者新兵召唤并消灭奥拉格，确保周边地区的安全。",al={"奥拉格任务","奥拉格是谁","“锋利的切肉刀”奥拉格"}}},fp="20,161,17.255.0,24.270.0,27.315.1,38.106.0,35.185.0,43.169.0,44.109.0,54.191.0,24.169.0"}
P.entries["npc:deathguard-humbert"] = {n="亡灵卫兵亨伯特",s="在塔伦米尔，亡灵卫兵亨伯特监视着联盟在希尔斯布莱德的动向。这名被遗忘者哨兵的武器装备被丹加洛克的矮人偷走了。",h="在塔伦米尔，亡灵卫兵亨伯特监视着联盟在希尔斯布莱德的动向。这名被遗忘者哨兵的武器装备被丹加洛克的矮人偷走了。",kw={"亡灵卫兵亨伯特","丹加洛克","希尔斯布莱德丘陵","亨伯特","亨伯特的长剑","雷矛","塔伦米尔"},ang={["faction:Horde"]="找回亨伯特的长剑，既能打击矮人在希尔斯布莱德的据点，也能帮助维护塔伦米尔守军的尊严。",["race:Undead"]="被遗忘者士兵理应时刻保持警惕，为黑暗女王效力。Humbert面对生者时的一时疏忽，给亡灵卫兵留下了难堪的污点。"},sec={{t="失去兵刃的卫兵",b="亡灵卫兵亨伯特奉高级执行官达萨利亚之命，在一处隐蔽的营地监视丹加洛克。一天早晨，他外出拾柴。趁他不在，丹加洛克的矮人斥候偷走了他珍爱的长剑和其他装备。如今，他必须在上级得知此事之前找回武器，挽回颜面。"}},faq={{q="亡灵卫兵亨伯特是谁？",a="亡灵卫兵亨伯特以塔伦米尔为据点，执行守卫和侦察任务。他监视着联盟在希尔斯布莱德丘陵各处的行动。",al={"亨伯特的故事","亨伯特是谁","亨伯特 塔伦米尔"}},{q="亨伯特的长剑和护甲出了什么事？",a="高级执行官达萨利亚派亨伯特在一处隐蔽的营地监视丹加洛克。一天早晨，他外出拾柴。等他回来时，丹加洛克的矮人斥候已经偷走了他的装备，其中包括他珍爱的长剑。",al={"亨伯特的长剑被盗","谁偷走了亨伯特的装备","亨伯特为什么需要帮助"}},{q="亨伯特为什么不自己找回装备？",a="丹加洛克防御森严，驻守着纪律严明的矮人火枪手和巡山人。孤身一人的斥候在战壕外几乎毫无胜算，而亨伯特也不能轻易擅离职守，否则就得交代自己是如何丢失装备的。",al={"亨伯特为什么无法战斗","亨伯特 丹加洛克"}}},fp="18,126,29.308.0,26.116.0,43.212.0,50.216.0"}
P.entries["npc:deathguard-linnea"] = {n="亡灵卫兵林奈",s="在提瑞斯法东南部的一处路边哨所，亡灵卫兵林奈监视着布瑞尔与东部边境之间的道路。她的小队抵御血色十字军和残存的天灾军团，过往旅人有时也会协助巡逻。",h="在提瑞斯法东南部的一处路边哨所，亡灵卫兵林奈监视着布瑞尔与东部边境之间的道路。她的小队抵御血色十字军和残存的天灾军团，过往旅人有时也会协助巡逻。",kw={"布瑞尔","亡灵卫兵林奈","被遗忘者","执政官塞弗伦","巡查后方","提瑞斯法林地"},ang={["faction:Horde"]="作为途经提瑞斯法林地的被遗忘者盟友，你可以帮助林奈抵御敌对势力，保障偏远道路的安全。",["race:Undead"]="作为刚在丧钟镇苏醒的被遗忘者，你可以帮助林奈守卫驿站，巩固王国的边境。"},sec={{t="路旁的守望",b="亡灵卫兵林奈守卫着布瑞尔东南方的一处设防哨所。被遗忘者抵御血色十字军的渗透者和仍在荒野游荡的天灾军团，保卫他们新生的国度。林奈和其他卫兵沿路巡逻，并与布瑞尔的执政官塞弗伦协调情报。他们的守望保障了通往亡灵壁垒的东部道路的安全。"}},faq={{q="亡灵卫兵林奈是谁？",a="林奈效力于亡灵卫兵，这支部队负责保卫被遗忘者的领土。她守卫着提瑞斯法林地的一处驿站，就在布瑞尔东南方的道路上。",al={"林奈","亡灵卫兵林奈的故事","林奈是谁"}},{q="她为什么需要有人协助巡逻？",a="被遗忘者的兵力分散在提瑞斯法林地各处，捉襟见肘。林奈依靠旅人和崭露头角的勇士清除附近的威胁，让信使和补给运送人员能够安全往返布瑞尔。",al={"巡查后方的故事","为什么帮助林奈"}}},fp="17,240,23.335.0,25.144.0,34.212.0"}
P.entries["npc:deathguard-samsa"] = {n="亡灵卫兵沙穆萨",s="亡灵卫兵沙穆萨在塔伦米尔监视着局势紧张的边境，并派旅人前去应对定居点附近的威胁。",h="亡灵卫兵沙穆萨在塔伦米尔监视着局势紧张的边境，并派旅人前去应对定居点附近的威胁。",kw={"亡灵卫兵沙穆萨","被遗忘者","希尔斯布莱德","沙穆萨","死亡的纪念品","塔伦米尔"},ang={["faction:Horde"]="作为行走在希尔斯布莱德丘陵的部落旅人，你依靠沙穆萨这样的哨兵协调防御，抵御附近南海镇联盟势力的进攻。",["race:Undead"]="身为被遗忘者，你深知，要守住洛丹伦南部边境、抵御周边敌对势力，就必须采取冷酷而务实的防御措施。"},sec={{t="塔伦米尔的边境哨兵",b="亡灵卫兵沙穆萨在塔伦米尔站岗，被遗忘者在这片争夺不休的希尔斯布莱德丘陵坚守阵地。部落哨兵既要面对南海镇等联盟据点的压力，也要应付当地凶猛的野兽。沙穆萨守卫着外围，并指引有能力的冒险者在威胁危及营地之前将其消除。"}},faq={{q="亡灵卫兵沙穆萨是谁？",a="亡灵卫兵沙穆萨在塔伦米尔为被遗忘者军队效力。他守卫城镇，并指引来访的冒险者协助应对附近的危险，确保这一地区的安全。",al={"沙穆萨","沙穆萨是谁","亡灵卫兵沙穆萨的职责"}},{q="在哪里可以找到亡灵卫兵沙穆萨？",a="亡灵卫兵沙穆萨位于塔伦米尔，这里是希尔斯布莱德丘陵北部的部落重镇。",al={"沙穆萨的位置","亡灵卫兵沙穆萨在哪里","塔伦米尔卫兵位置"}},{q="亡灵卫兵沙穆萨会交付哪些任务？",a="沙穆萨派冒险者深入希尔斯布莱德的荒野，任务包括收集部落征战期间被杀死的希尔斯布莱德人类的颅骨。",al={"沙穆萨的任务","死亡纪念品任务给予者"}}},fp="16,97,30.324.0,24.161.0,34.101.0,42.156.0"}
P.entries["npc:deathguard-simmer"] = {n="亡灵卫兵希米尔",s="在丧钟镇边缘，亡灵卫兵希米尔审视着新近复生的被遗忘者。他派他们向西袭击一座由血色十字军巡逻的人类南瓜农场，收集布瑞尔的药剂师所需的材料。",h="在丧钟镇边缘，亡灵卫兵希米尔审视着新近复生的被遗忘者。他派他们向西袭击一座由血色十字军巡逻的人类南瓜农场，收集布瑞尔的药剂师所需的材料。",kw={"亡灵卫兵","亡灵卫兵希米尔","丧钟镇","提瑞斯法林地"},ang={["race:Undead"]="身为亡灵，你会通过希米尔的任务首次迎战血色十字军。他派你走出丧钟镇的墓穴，保卫洛丹伦。"},sec={{t="丧钟镇外的守卫",b="亡灵卫兵希米尔守卫着丧钟镇外的土地，被遗忘者在这里守住庇护所与提瑞斯法林地之间的防线。活着的人类在这一带游荡，其中包括狂热的血色十字军，他们视所有亡灵为必须用烈火与刀剑清除的怪物。希米尔派新近复生的被遗忘者向西前往索利丹农场，以此考验他们。血色十字军的士兵从附近的一座哨塔出发巡逻。新兵必须偷取十个南瓜，送给布瑞尔的药剂师乔汉。"}},faq={{q="亡灵卫兵希米尔是谁？",a="亡灵卫兵希米尔是驻守在提瑞斯法林地丧钟镇外的一名被遗忘者哨兵。他派新近复生的被遗忘者前往一座由血色十字军巡逻的人类农场偷取南瓜，以此考验他们。",al={"亡灵卫兵希米尔","希米尔是谁","希米尔非玩家角色"}},{q="亡灵卫兵希米尔在哪里？",a="亡灵卫兵希米尔站在提瑞斯法林地西南部的丧钟镇外，就在新近复生的被遗忘者离开墓穴时所走的道路旁。",al={"亡灵卫兵希米尔位置","希米尔在哪","寻找亡灵卫兵希米尔"}},{q="亡灵卫兵希米尔对抗哪些威胁？",a="亡灵卫兵希米尔憎恶那些仍在提瑞斯法耕作的活人，以及在他们附近巡逻的血色十字军。他派新近复生的被遗忘者袭击索利丹农场，夺取南瓜，既给那些人类一个教训，也为布瑞尔的药剂师提供材料。",al={"希米尔的敌人","希米尔对抗什么","血色 栅栏任务"}}},fp="17,197,27.492.0,25.195.0,35.155.0,42.256.0"}
P.entries["npc:deathstalker-faerleia"] = {n="亡灵哨兵费雷亚",s="在焚木村深处，亡灵哨兵费雷亚正暗中对抗村中的统治者。她在村镇大厅指挥秘密袭击，目标是焚木村议会，也就是阿鲁高用来统治村庄的傀儡。",h="在焚木村深处，亡灵哨兵费雷亚正暗中对抗村中的统治者。她在村镇大厅指挥秘密袭击，目标是焚木村议会，也就是阿鲁高用来统治村庄的傀儡。",kw={"伏击","议会","亡灵哨兵","费雷亚","被遗忘者","焚木村","银松森林"},ang={["class:Rogue"]="作为一名为被遗忘者效力的盗贼，你可以借鉴费雷亚的实战技巧：她悄无声息地潜入敌人的权力中心，策划伏击。",["race:Undead"]="身为亡灵，你可以看到费雷亚如何凭借渗透与冷静的算计，瓦解黑暗女王的敌人，而无需动用整支大军。"},sec={{t="深入敌后",b="亡灵哨兵费雷亚在焚木村的村镇大厅上层开展行动。她是亡灵哨兵的特工，这个组织是幽暗城负责秘密情报与暗杀的分支，她已潜入银松森林南部这片与世隔绝的人类聚居地。村中隐藏着黑暗的秘密，其中一道诅咒会让村民在夜空下变身。费雷亚在聚居地内部协调破坏行动，并召集部落特工，铲除焚木村议会中有影响力的成员。"}},faq={{q="亡灵哨兵费雷亚是谁？",a="费雷亚效力于亡灵哨兵，这是希尔瓦娜斯·风行者女王麾下负责潜行与情报的部门。她已潜入焚木村，向村中的统治者发动秘密战争。",al={"费雷亚","费雷亚 是谁","亡灵哨兵费雷亚"}},{q="在哪里可以找到亡灵哨兵费雷亚？",a="费雷亚就在焚木村的村镇大厅内，那里位于银松森林南部，格雷迈恩之墙以北不远处。",al={"费雷亚 在哪里","费雷亚 位置","寻找 费雷亚"}},{q="她会交付什么任务？",a="费雷亚指挥冒险者执行焚木村中的伏击，暗杀统治焚木村的议员，削弱这片聚居地对被遗忘者的抵抗。",al={"费雷亚 任务","焚木村中的伏击 任务"}},{q="亡灵哨兵为什么要对焚木村下手？",a="阿鲁高将焚木村议会当作傀儡，把受到诅咒的村民牢牢控制在手中。费雷亚相信，只要议会成员死去，阿鲁高之子就会反抗他们的主人，帮助被遗忘者夺取村镇，并将阿鲁高逐出影牙城堡。",al={"为何进攻 焚木村","焚木村 的 亡灵哨兵"}}},fp="21,205,18.514.1,29.185.0,41.123.0,27.178.0,53.260.0"}
P.entries["npc:deathstalker-lesh"] = {n="亡灵哨兵莱什",s="亡灵哨兵莱什在南点哨塔监视着希尔斯布莱德丘陵的人类农场。她为高级执行官达萨利亚效力，判断被遗忘者何时应当发动进攻。",h="亡灵哨兵莱什在南点哨塔监视着希尔斯布莱德丘陵的人类农场。她为高级执行官达萨利亚效力，判断被遗忘者何时应当发动进攻。",kw={"亡灵哨兵莱什","高级执行官达萨利亚","希尔斯布莱德农场","希尔斯布莱德丘陵","南点哨塔","塔伦米尔","进攻时机"},ang={["class:Rogue"]="身为潜行者，你与亡灵哨兵莱什一样，都在通过秘密行动为部落的战事效力。",["race:Undead"]="对身为被遗忘者的你而言，莱什这样的斥候有助于保卫洛丹伦，抵御卷土重来的联盟势力。"},sec={{t="监视农场",b="亡灵哨兵莱什从南点哨塔监视着附近希尔斯布莱德农场的人类农夫和城镇民兵。哨塔坐落在穿过希尔斯布莱德丘陵的南部道路上。莱什隶属于亡灵哨兵，这是被遗忘者由斥候、间谍和刺客组成的秘密网络。她为塔伦米尔的高级执行官达萨利亚追踪敌军的动向和数量。时机成熟时，莱什便向达萨利亚发出密信：“西方传来的渡鸦啼鸣正在召唤。”这句话意味着，被遗忘者进攻希尔斯布莱德的时机已经成熟。"}},faq={{q="亡灵哨兵莱什是谁？",a="莱什是驻守南点哨塔的被遗忘者斥候。她听命于塔伦米尔的高级执行官达萨利亚，监视着希尔斯布莱德农场各处的人类活动。",al={"亡灵哨兵莱什","莱什是谁","莱什 希尔斯布莱德"}},{q="亡灵哨兵是什么？",a="亡灵哨兵为女王希尔瓦娜斯·风行者担任斥候、间谍和刺客。他们为被遗忘者军队搜集情报，并在洛丹伦各地铲除重要目标。",al={"亡灵哨兵是什么","亡灵哨兵组织","被遗忘者潜行者"}},{q="莱什在南点哨塔担负什么职责？",a="莱什在南点哨塔守望，监视着希尔斯布莱德农场和希尔斯布莱德镇。时机成熟时，她便派一名旅者前往塔伦米尔，向高级执行官达萨利亚递交密信，示意进攻希尔斯布莱德的时机已经成熟。",al={"南点哨塔斥候","莱什任务","莱什为何在这里"}},{q="莱什向谁汇报？",a="莱什向高级执行官达萨利亚汇报，这位驻守塔伦米尔的被遗忘者指挥官负责指挥针对希尔斯布莱德人类部队的攻势。",al={"莱什的上司","谁指挥莱什","高级执行官达萨利亚"}}},fp="17,165,18.546.0,25.155.0,27.184.0,40.235.0,24.151.0"}
P.entries["npc:deathstalker-rane-yorick"] = {n="兰妮·尤瑞克",s="在银松森林的一处农舍里，亡灵哨兵兰妮·尤瑞克和她的兄弟奎恩与瑟伯切尔失去了联系。他们奉命侦察北部的农场，必须将消息传给高级执行官哈德瑞克。",h="在银松森林的一处农舍里，亡灵哨兵兰妮·尤瑞克和她的兄弟奎恩与瑟伯切尔失去了联系。他们奉命侦察北部的农场，必须将消息传给高级执行官哈德瑞克。",kw={"亡灵哨兵","埃兰德","被遗忘者","伊瓦农场","兰妮","潜行者","侦察兵","银松森林","尤瑞克"},ang={["class:Rogue"]="身为被遗忘者潜行者，你从兰妮·尤瑞克顶着敌人压力收集情报的行动中，看到了亡灵哨兵在外执行任务时面临的危险。",["faction:Horde"]="身为部落的一员，你受益于兰妮的情报工作，她帮助部落保障穿过银松森林的补给路线，防范狼人和当地的伏击。",["race:Undead"]="身为被遗忘者的勇士，你遇见的兰妮是一名侦察兵，守卫着银松森林的边境，抵御敌人的侵袭。"},sec={{t="林间耳目",b="在洛丹伦各地，亡灵哨兵是希尔瓦娜斯·风行者女士的耳目与利刃。兰妮·尤瑞克这样的密探从隐蔽的据点监视荒野，提防威胁被遗忘者统治的势力。兰妮和她的兄弟奎恩奉命侦察银松森林北部。荒野中的危险将他们团团围住，让秘密行动变成了求生之战。"},{t="困守伊瓦农场",b="在伊瓦农场，兰妮·尤瑞克藏身于一处破败的农舍。食尸鬼邪恶的伊瓦将她的兄弟奎恩打成重伤，座狼则在他们与瑟伯切尔之间的田野上游荡。兰妮仍然坚守任务。她请路过的部落旅人收集座狼的心脏来配制治疗药水，杀死伊瓦，并将她的报告送交指挥官。"}},faq={{q="亡灵哨兵兰妮·尤瑞克是谁？",a="兰妮·尤瑞克效力于亡灵哨兵，这是被遗忘者的潜行者组织，负责收集情报和秘密刺杀。她驻扎在银松森林伊瓦农场的一处破败农舍里。",al={"兰妮·尤瑞克是谁","兰妮·尤瑞克背景故事","亡灵哨兵 尤瑞克是谁"}},{q="亡灵哨兵是什么组织？",a="亡灵哨兵是被遗忘者的秘密潜行者公会，听命于希尔瓦娜斯·风行者女士。他们在洛丹伦各地侦察、刺探情报，并执行定点刺杀。",al={"亡灵哨兵是什么","亡灵哨兵阵营","亡灵哨兵是谁"}},{q="她为什么被困在农舍里？",a="兰妮和她的兄弟奎恩奉命侦察银松森林北部的农场。在伊瓦农场，食尸鬼邪恶的伊瓦袭击了他们，将奎恩打成重伤，于是他们躲进一处农舍，等待他康复。",al={"兰妮为何被困","伊瓦农场农舍","她为何躲藏"}},{q="她的兄弟是谁？",a="奎恩·尤瑞克是兰妮的兄弟，也是一名亡灵哨兵，与她一同执行侦察任务。邪恶的伊瓦在伊瓦农场将他打成重伤。",al={"兰妮·尤瑞克的兄弟","埃兰德是谁","亡灵哨兵埃兰德"}},{q="他们在银松森林追踪哪些威胁？",a="兰妮和奎恩奉命侦察银松森林北部的农场，查探威胁被遗忘者统治的势力。他们发现天灾军团的数量超出预期，还有四处游荡的座狼和食尸鬼邪恶的伊瓦。",al={"他们在侦察什么","兰妮在调查什么"}},{q="她向哪里汇报侦察结果？",a="兰妮向瑟伯切尔的高级执行官哈德瑞克汇报侦察结果。哈德瑞克负责督管被遗忘者对银松森林的占领。",al={"报告送往哪里","兰妮的上级是谁"}}},fp="11,177,17.321.0,21.325.1,32.194.0,27.162.0,34.216.0,19.136.0,45.185.0,35.129.0"}
P.entries["npc:deathstalker-vincent"] = {n="亡灵哨兵文森特",s="在影牙城堡内，亡灵哨兵文森特倒毙在地，死于阿鲁高之手。这名被遗忘者斥候与亡灵哨兵阿达曼特一同潜入要塞，探查防御部署，但被遗忘者尚未发起进攻，任务就已告终。",h="在影牙城堡内，亡灵哨兵文森特倒毙在地，死于阿鲁高之手。这名被遗忘者斥候与亡灵哨兵阿达曼特一同潜入要塞，探查防御部署，但被遗忘者尚未发起进攻，任务就已告终。",kw={"阿鲁高","亡灵哨兵阿达曼特","亡灵哨兵文森特","影牙城堡","银松森林","文森特","狼人"},ang={["class:Rogue"]="对于潜行者而言，文森特遭到处决一事揭示了潜行人员独自潜入敌方要塞时面临的危险。",["faction:Horde"]="身为部落的一员，发现文森特的尸体证实了被遗忘者指挥官对银松森林局势的担忧：侦察小队失败了，必须以武力肃清城堡。"},sec={{t="斥候的末路",b="亡灵哨兵需要摸清影牙城堡的布局，被遗忘者才能发动进攻。文森特和阿达曼特悄悄越过路障，潜入堡垒。他们的任务失败了：阿达曼特被俘，关进了地牢，而文森特则被带到了城堡主人面前。文森特拒绝为阿鲁高效力，也不肯向他屈服。法师处决了他，将他的尸体留在石地板上。"},{t="阿鲁高的挑衅",b="阿鲁高用文森特的死向闯入城堡的人示威。面对被俘的斥候，这个疯狂的法师嘲弄被遗忘者，将他们的入侵与昔日肯瑞托同僚的失败尝试相提并论。阿鲁高要求文森特献出利刃和秘密，为自己所用。文森特拒绝后，阿鲁高将他击杀，并宣称他的遗骸将警告所有擅闯其领地的人。"}},faq={{q="亡灵哨兵文森特是谁？",a="文森特是被遗忘者情报机构亡灵哨兵的一名被遗忘者斥候。他与亡灵哨兵阿达曼特潜入影牙城堡，为计划中的进攻收集情报。",al={"文森特是谁","文森特 影牙城堡","暗影之牙死去的潜行者"}},{q="文森特在影牙城堡遭遇了什么？",a="文森特在侦察时被俘，因拒绝为阿鲁高效力或交出秘密而遭到处决。阿鲁高将他的尸体留在了倒下的地方。",al={"文森特怎么死的","文森特为何死了","谁杀了文森特"}},{q="他的搭档亡灵哨兵阿达曼特在哪里？",a="亡灵哨兵阿达曼特被生擒，关在附近的地牢牢房里，由一名狼人守卫看守。",al={"阿达曼特在哪里","另一名亡灵哨兵","阿达曼特位置"}},{q="亡灵哨兵为何被派往影牙城堡？",a="银松森林是希尔瓦娜斯和被遗忘者的重要领地，而阿鲁高的狼人占据着影牙城堡。文森特和阿达曼特奉命摸清堡垒的布局和防御部署，以便被遗忘者发动有效的进攻。",al={"亡灵哨兵为何在暗影之牙","被遗忘者在暗影之牙的任务"}}},fp="20,180,19.408.0,17.391.1,29.188.0,44.165.0,43.103.0,51.238.0"}
P.entries["npc:deathwing"] = {n="死亡之翼",s="毁灭者死亡之翼曾名为大地守护者奈萨里安，是黑龙堕落的守护巨龙。上古之神的黑暗低语令他陷入疯狂，他背叛了其他守护巨龙，将世界拖入烈火与动荡之中。尽管他在第二次战争之后于格瑞姆巴托附近战败，被认为已经死去或藏匿起来，但他留下的恐怖阴影仍笼罩着艾泽拉斯的幽深之地。",h="毁灭者死亡之翼曾名为大地守护者奈萨里安，是黑龙堕落的守护巨龙。上古之神的黑暗低语令他陷入疯狂，他背叛了其他守护巨龙，将世界拖入烈火与动荡之中。尽管他在第二次战争之后于格瑞姆巴托附近战败，被认为已经死去或藏匿起来，但他留下...",kw={"守护巨龙","黑龙","死亡之翼","恶魔之魂","毁灭者","巨龙之魂","大地守护者","格瑞姆巴托","奈萨里安","普瑞斯托"},ang={["faction:Alliance"]="想到Daval Prestor领主曾险些夺取奥特兰克的王冠，并操纵Council of Seven Nations从内部摧毁联盟，联盟的贵族们至今仍不寒而栗。",["faction:Horde"]="旧部落曾在Second War期间与死亡之翼达成邪恶交易，通过龙喉氏族氏族获取红龙，新部落力求将这一污点留在过去。",["race:NightElf"]="卡多雷的长者们仍记得，一万年前的War of the Ancients期间，奈萨里安突然发动了毁灭性的背叛，那场暴行重创了龙族，也注定了他们古老帝国的覆灭。"},sec={{t="奈萨里安的堕落",b="在被称为毁灭者之前，奈萨里安获泰坦万神殿授予了掌管艾泽拉斯大地与地下洞窟的权柄。然而，他栖居之处离世界最深处太近，使他受到被囚禁的上古之神阴险低语的侵蚀。在远古的上古之战期间，疯狂彻底控制了他。他以阻止燃烧军团为幌子，诱骗其他守护巨龙将各自的一部分精华注入一枚名为巨龙之魂的金色圆盘，随后却将这件可怕的武器对准盟友，造成了灾难性的破坏。"},{t="人类领主的阴谋",b="第二次战争之后，死亡之翼企图从内部瓦解凡人的王国。他化身为魅力非凡的人类贵族达瓦尔·普瑞斯托领主，蛊惑了国王泰瑞纳斯·米奈希尔二世与洛丹伦联盟的最高议会，密谋登上奥特兰克空悬的王位。与此同时，他帮助格瑞姆巴托的龙喉氏族氏族继续奴役女王阿莱克丝塔萨，并夺取她产下的一窝窝龙蛋。当罗宁摧毁恶魔之魂后，他的阴谋随之瓦解，其他守护巨龙被窃取的力量得以恢复，并将死亡之翼逐走。"},{t="留下的子嗣",b="如今，凡人的王国大多认为死亡之翼已被消灭，或已被永远逐出这个世界。然而，黑龙仍在艾泽拉斯各地肆虐。在他那些狡诈子嗣的带领下，包括他的女儿奥妮克希亚和儿子奈法利安，黑色幼龙操纵着凡人的政局，并从山间巢穴出动，恐吓四方。这位黑龙守护者远古背叛所留下的创伤深重，穿行于崎岖荒地和幽深地下隧道的旅人，仍然惧怕那头巨龙再次苏醒。"}},faq={{q="死亡之翼原本是谁？",a="死亡之翼原本是大地守护者奈萨里安，黑龙的领袖，泰坦赋予他力量，让他照管艾泽拉斯的大地与群山。数千年前，由于身处大地深处，他容易受到上古之神阴险低语的侵蚀，逐渐丧失了理智。",al={"奈萨里安历史","奈萨里安是谁","大地守护者起源"}},{q="巨龙之魂是什么？",a="巨龙之魂是一件金色神器，由奈萨里安在上古之战期间铸造，后来被称为恶魔之魂。他诱骗其他四位守护巨龙将力量注入其中，随后将这件武器毁天灭地的威力倾泻在同族巨龙与凡人守军身上。",al={"恶魔之魂","巨龙之魂是什么","奈萨里安的神器"}},{q="达瓦尔·普瑞斯托领主是谁？",a="达瓦尔·普瑞斯托领主是死亡之翼在第二次战争之后采用的人类伪装。他通过强大的魅惑魔法与宫廷骗术，企图夺取奥特兰克的王位，并从内部操纵洛丹伦联盟，直到他的阴谋败露。",al={"普瑞斯托领主","达瓦尔·普瑞斯托身份","普瑞斯托背景故事"}},{q="死亡之翼与格瑞姆巴托有何关联？",a="死亡之翼暗中向格瑞姆巴托的龙喉氏族兽人提供了恶魔之魂，确保红龙女王阿莱克丝塔萨继续受到囚禁，并被迫为战争繁衍后代。后来，罗宁用死亡之翼的一片鳞片摧毁了这件神器。其他守护巨龙恢复力量后，与死亡之翼交战并将他逐走。",al={"死亡之翼 格瑞姆巴托","格瑞姆巴托发生了什么"}},{q="如今由谁领导黑龙？",a="死亡之翼不知所踪，并被认为已经死去，他最主要的子嗣各自行动。他的女儿奥妮克希亚盘踞在尘泥沼泽的巢穴中，而他的儿子奈法利安则在黑石山高处统率黑龙，并用龙血进行实验。",al={"现任黑龙领袖","谁领导黑龙","奈法利安与奥妮克希亚"}}},fp="9,335,22.435.0,24.501.1,21.469.0,29.242.0,25.265.0,27.246.1,45.288.0,39.250.2"}
P.entries["npc:deino"] = {n="迪诺",s="在奥格瑞玛的精神谷，迪诺传授部落法师奥术技艺。她教导施法者掌控奥术与元素之力，并派经验丰富的法师前往卡利姆多各地，研究古老魔法，寻访偏远之地的导师。",h="在奥格瑞玛的精神谷，迪诺传授部落法师奥术技艺。她教导施法者掌控奥术与元素之力，并派经验丰富的法师前往卡利姆多各地，研究古老魔法，寻访偏远之地的导师。",kw={"迪诺","欢笑姐妹","法师训练师","奥格瑞玛","塔贝萨","巨魔法师","精神谷","之水 萨维亚","萨维亚"},ang={["class:Mage"]="身为法师，你可以在奥格瑞玛向迪诺学习法术和传送门魔法，然后前往灰谷和尘泥沼泽深造。",["faction:Horde"]="身为部落的一员，你可以在奥格瑞玛的灵魂信仰区域找到迪诺，她在那里训练部落的施法者，与萨满祭司和术士为邻。",["race:Troll"]="身为巨魔，你可以看到暗矛如何将深奥的奥术学识与精神谷的传统结合起来。"},sec={{t="山谷中的奥术师",b="迪诺在奥格瑞玛的精神谷训练部落法师。她授课的高台周围，分布着图腾、棚屋与宁静的水面。巨魔施法者在敬奉灵魂与精研奥术之间寻求平衡，迪诺与同为导师的恩尤和皮菲瑞多也遵循着这条道路。"},{t="探寻奥术之谜",b="迪诺派有潜力的法师走出杜隆塔尔，研究奥术之谜。在灰谷遭到腐化的荒野中，他们收集受到污染的之水萨维亚，以及欢笑姐妹蕴含魔力的头发。当学生的力量超出奥格瑞玛导师所能传授的范围时，迪诺便指引他们寻访偏远之地的大师，其中就包括隐居在尘泥沼泽的女巫塔贝萨。"}},faq={{q="在哪里可以找到迪诺？",a="迪诺站在奥格瑞玛西南部精神谷的高台上。同为巨魔法师训练师的恩尤和皮菲瑞多也与她站在一起。",al={"迪诺位置","迪诺在哪里","迪诺奥格瑞玛"}},{q="迪诺教授什么？",a="迪诺教授奥术、火焰和冰霜法术、传送门的开启方法，并随着法师经验的增长，传授必要的各级法术。",al={"迪诺训练师","迪诺教授哪些法术"}},{q="迪诺为什么派法师前往萨维亚？",a="萨维亚是灰谷东部的一座古城，如今被萨特占据。据说那里的水蕴含强大的魔力，迪诺希望从城中最高的瀑布底部取一份水样，用于研究。",al={"之水 萨维亚任务","为什么去萨维亚"}},{q="站在迪诺身边的训练师是谁？",a="恩尤和皮菲瑞多站在迪诺身边。三人的名字与古老神话中的格赖埃姐妹相同，她们是奥格瑞玛巨魔法师导师的核心成员。",al={"恩尤是谁","皮菲瑞多","精神谷的巨魔法师"}},{q="迪诺为什么派法师前往尘泥沼泽？",a="当法师的技艺更加娴熟时，迪诺便派他们去寻找塔贝萨，一位隐居在尘泥沼泽深处的强大人类隐士。塔贝萨掌握着独到的奥术秘法。",al={"迪诺塔贝萨","沼泽之旅"}},{q="其他种族也能向迪诺学习吗？",a="可以。包括巨魔、兽人和被遗忘者在内，任何种族的部落法师都能在精神谷向迪诺学习职业法术，接受她的指导。",al={"兽人能向迪诺学习吗","部落法师训练"}}},fp="5,229,21.286.0,27.337.0,23.140.0,22.114.0,36.189.0,41.158.0,46.163.0,32.148.0"}
P.entries["npc:delgren-the-purifier"] = {n="净化者德尔格伦",s="在迈斯特拉岗哨，净化者德尔格伦帮助暗夜精灵抵御灰谷北缘的恶魔与暗影魔法。他与巴苏尔·影击和费罗·艾隆汉并肩守卫边境。",h="在迈斯特拉岗哨，净化者德尔格伦帮助暗夜精灵抵御灰谷北缘的恶魔与暗影魔法。他与巴苏尔·影击和费罗·艾隆汉并肩守卫边境。",kw={"奥萨拉克斯","银色黎明","灰谷","巴苏尔·影击","暗滩教派","德尔格伦","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨","奥萨拉克斯之塔"},ang={["class:Paladin"]="身为圣骑士，德尔格伦展现了圣光如何远播卡利姆多。他对恶魔与黑暗魔法的征伐，早已远远超出了东部王国。",["faction:Alliance"]="对于从黑海岸南下的联盟旅人而言，德尔格伦和同伴在危机四伏的灰谷道路沿线提供了一处军事据点。",["race:NightElf"]="身为暗夜精灵，你或许不信任外来的信仰，但德尔格伦的队伍正在对抗那些侵扰古老废墟的恶魔教派。"},sec={{t="卡多雷边境的圣战士",b="净化者德尔格伦守望着从奥伯丁南下的旅人。人类圣骑士在卡利姆多的古老森林中并不多见，但他随一支银色黎明的神圣勇士队伍来到了西方。他们此行是为了帮助联盟新近结交的暗夜精灵盟友，对抗第三次大战遗留下来的恶魔与亡灵残部。德尔格伦驻守在黑海岸与灰谷的交界附近，那里的危险已经蔓延到了道路上。"},{t="净化暗滩教派",b="德尔格伦与巴苏尔·影击在黑海岸北部的奥萨拉克斯之塔周围对抗暗滩教派。这个教派的黑暗仪式威胁着边境。德尔格伦派冒险者深入其领地，击杀教徒，摧毁他们的召唤法器，并猎杀那些与恶魔暗影之力打交道的术士。"},{t="不拘成规的心智",b="德尔格伦对圣光的虔诚并未妨碍他研究卡利姆多错综复杂的政治局势。他学会了兽人语，令思想保守的上级既恼火又不屑。这门语言让他得以超越所属组织的教导，去理解那些同处这片蛮荒大陆的敌人与邻居。"}},faq={{q="净化者德尔格伦是谁？",a="德尔格伦是一名人类圣骑士，驻守在灰谷北部道路沿线的迈斯特拉岗哨。他为银色黎明效力，帮助暗夜精灵对抗恶魔腐化、邪教徒，以及燃烧军团入侵后留下的暗影。",al={"德尔格伦是谁","德尔格伦背景故事","迈斯特拉岗哨的圣骑士是谁"}},{q="在哪里能找到德尔格伦？",a="德尔格伦位于迈斯特拉岗哨，这是灰谷西北部的一处暗夜精灵小型哨站，就在通往黑海岸的小径南边。",al={"德尔格伦在哪里","德尔格伦位置","德尔格伦坐标"}},{q="一名人类圣骑士为何远赴灰谷？",a="德尔格伦随一队银色黎明圣骑士西行，前来援助联盟的暗夜精灵盟友。他们致力于清除威胁卡利姆多北部的恶魔、亡灵残部和黑暗教派。",al={"德尔格伦为何在灰谷","灰谷为何有人类","德尔格伦使命"}},{q="德尔格伦与奥萨拉克斯之塔有什么联系？",a="德尔格伦和同伴监视着黑海岸北部奥萨拉克斯之塔周围的腐化活动。他派冒险者调查这片废墟，追猎暗滩教派，并破坏其黑暗召唤仪式。",al={"德尔格伦 奥萨拉克斯","奥萨拉克斯之塔任务","暗滩教派"}},{q="德尔格伦为何学习兽人语？",a="德尔格伦学习兽人语，是为了更好地了解卡利姆多及其居民。他在组织中的上级对此并不赞同。",al={"德尔格伦会说兽人语","德尔格伦会说兽人语吗","德尔格伦兽人语言"}},{q="德尔格伦在迈斯特拉岗哨与谁共事？",a="德尔格伦在迈斯特拉岗哨与巴苏尔·影击和费罗·艾隆汉并肩作战。他们一起警戒边境的威胁，处理后勤事务，并在灰谷边境对抗暗影教徒。",al={"德尔格伦同伴","迈斯特拉岗哨有谁"}}},fp="20,186,35.371.0,23.335.1,18.299.0,28.201.0,25.128.0,52.190.0,55.226.0,29.108.0,45.198.0"}
P.entries["npc:demisette-cloyce"] = {n="德米赛特·克劳斯",s="在暴风城的已宰的羔羊下方，德米赛特·克劳斯秘密传授术士之道。她指导学生研习邪能魔法，并派学有所成者向其他召唤师求教。",h="在暴风城的已宰的羔羊下方，德米赛特·克劳斯秘密传授术士之道。她指导学生研习邪能魔法，并派学有所成者向其他召唤师求教。",kw={"克劳斯","德米赛特","法师区","梅纳拉·沃伦德","已宰的羔羊","暴风城","术士训练师"},ang={["class:Warlock"]="身为暴风城的术士，你可以向德米赛特学习基础法术。她会指引你获取地狱战马，并束缚恶魔宝珠。",["race:Human"]="身为人类，你可以在暴风城地下找到德米赛特。她已经背离圣光，转而追求恶魔的力量。"},sec={{t="已宰的羔羊的地下墓穴",b="术士们聚集在暴风城法师区的已宰的羔羊地下室里。城中的当局维护秩序与圣光，而德米赛特·克劳斯则住在下方的地下墓穴中。在那里，她教导那些愿意研习禁忌法术的人。她告诫他们，黑暗能量只会腐蚀那些缺乏自律、无法驾驭它的人。"},{t="联结各地集会",b="当术士掌握了足够的本领，德米赛特便会指引他们走出暴风城。她为他们引荐其他召唤师，例如贫瘠之地的梅纳拉·沃伦德。在那里，他们可以寻找强大的神器，学习束缚强悍的地狱战马。"}},faq={{q="德米赛特·克劳斯是谁？",a="德米赛特·克劳斯在暴风城法师区的已宰的羔羊下方训练术士。她传授恶魔召唤术与黑暗法术。",al={"德米赛特是谁","德米赛特·克劳斯的故事","德米赛特·克劳斯是谁"}},{q="她为什么藏在酒馆的地下室里？",a="术士们聚集在已宰的羔羊下方的地下室里，避开公众的视线。这里为他们修习黑暗法术提供了隐秘的场所。",al={"她为什么在地下室","为什么在已宰的羔羊","已宰的羔羊地下室"}},{q="她与贫瘠之地有什么联系？",a="德米赛特派遣经验丰富的术士远渡重洋，前往贫瘠之地沿海的棘齿城，拜访梅纳拉·沃伦德。他们寻求高深的仪式、强大的宝珠和束缚仪式。",al={"德米赛特与贫瘠之地","寻找梅纳拉·沃伦德","与梅纳拉·沃伦德的联系"}},{q="她如何对待术士以外的人？",a="德米赛特鄙视外人。如果你没有踏上术士之路，她就会警告你，黑暗不会接纳你。随后，她会命令你闭嘴离开。",al={"德米赛特的对白","与德米赛特交谈"}}},fx={["9bf7bbcc"]={q="德米赛特·克劳斯站在哪一边？",a="德米赛特·克劳斯效忠联盟，安然居住在暴风城中。虽然她与其他术士一同隐居在已宰的羔羊下方的地下墓穴中，但她致力于教导并增强效忠暴风城的施法者，而非为敌对教派或火刃氏族效力。",al={"德米赛特·克劳斯的阵营","德米赛特·克劳斯是联盟吗","德米赛特为谁效力"}},["5142027a"]={q="德米赛特·克劳斯想要什么？",a="德米赛特希望引导有潜力的术士掌握危险的邪能魔法，同时避免被腐化吞噬。她指引施法者前往世界各地寻找古老的神器与强大的导师，甚至远赴卡利姆多，因为她相信，只有意志坚定的学徒才能有效驾驭黑暗法术，而不至于过早迎来毁灭性的结局。",al={"德米赛特·克劳斯的动机","德米赛特·克劳斯的目标","德米赛特想要什么"}}},fp="16,166,34.342.0,21.235.0,24.137.0,37.139.0,38.175.0,35.171.0"}
